// Sqwik -- two printed clauses:
//   "Sing the Scarletsong: Your Paradwyn Creatures remove one extra energy in attacks." Real
//   energy add to the attacker (same "increase what's dealt" shape as Culla/N'ssah), scoped to own
//   Paradwyn Creatures attacking -> onBeforeEnergyRemoved.
//   "Perfect Pitch: Your Scarletsong cards cost one less energy to play, to a minimum of one." --
//   costModifier, "Scarletsong" family name match.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { effectiveRegions } from '../targeting.js';

const SCARLETSONG_FAMILY = /\bScarletsong\b/;

registerCardEffect('Sqwik', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Sing the Scarletsong is the
  // "own Paradwyn Creatures deal +1" pre-damage adder; Perfect Pitch is the Scarletsong
  // cost discount.
  effectHooks: {
    'Sing the Scarletsong': ['onBeforeEnergyRemoved'],
    'Perfect Pitch': ['costModifier'],
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.attacker).includes('Paradwyn')) return;
    addEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect');
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return SCARLETSONG_FAMILY.test(playedDef.name) ? -1 : 0;
  },
});
