// Ookami's Drums -- two Powers sharing the same target filter ("any Creature in play with less
// than its starting energy"), opposite effects:
//   "Badum: ...Add one energy to the chosen Creature."
//   "Badumbum: ...Discard one energy from the chosen Creature."
// Implementing both together since they're the same card and the same target logic -- not
// splitting the add/remove halves across separate work.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveStartingEnergy } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

function isBelowStarting(state: GameState, cardDb: CardDatabase, c: CardInstance): boolean {
  return (c.currentEnergy ?? 0) < effectiveStartingEnergy(state, cardDb, c);
}

registerCardEffect("Ookami's Drums", {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- Badumbum only (it discards
  // energy); Badum adds energy, Dreamburn doesn't cover it, stays untouched.
  powerTargets: (state, cardDb, playerId, powerName) => {
    const naturalPool = allCreaturesInPlay(state, cardDb).filter((c) => isBelowStarting(state, cardDb, c));
    if (powerName !== 'Badumbum') return naturalPool;
    const alternatePool = allMagiInPlay(state).filter((c) => isBelowStarting(state, cardDb, c));
    return flexibleTargetPool(state, cardDb, playerId, naturalPool, alternatePool);
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Badum' && ctx.powerName !== 'Badumbum') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isBelowStarting(ctx.state, ctx.cardDb, target)) return;
    if (ctx.powerName === 'Badum') {
      // Dreamburn only covers energy-DISCARD Powers, not this ADD Power -- stays Creature-only.
      if (ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
      addEnergy(ctx.state, ctx.cardDb, target, 1, 'power');
    } else {
      // task #34, 2026-07-16: Abraxin's Crown's Dreamburn covers this DISCARD Power.
      if (!isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
      discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
    }
  },
});
