// Core Grag -- "Firestorm (5): Choose any one Magi in play. Discard Core Grag from play. Discard
// two energy from each of the chosen Magi's Creature in play. Discard three energy from the
// chosen Magi." Magi-only target, self-discard, then a sweep scoped to the target's own
// controller's Creatures.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Core Grag', {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- the already-chosen target IS the Magi
  // that will be hit (Firestorm always targets a Magi directly), so this is just an opposing-side
  // check, no execution.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options, powerName) => {
    if (powerName !== 'Firestorm') return false;
    const targetId = options.chosenTargetId as string | undefined;
    if (!targetId) return false;
    const target = findCreatureOrMagiById(state, targetId);
    return !!target && target.controllerId !== actingPlayerId && cardDb.get(target.definitionKey)?.card_type === 'Magi';
  },
  powerTargets: (state) => allMagiInPlay(state),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Firestorm') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const owner = ctx.state.players.get(target.controllerId);
    if (owner) {
      for (const creature of owner.inPlay) {
        if (ctx.cardDb.get(creature.definitionKey)?.card_type === 'Creature') {
          discardEnergy(ctx.state, ctx.cardDb, creature, 2, undefined, undefined, ctx.rng);
        }
      }
    }
    discardEnergy(ctx.state, ctx.cardDb, target, 3, undefined, undefined, ctx.rng);
  },
});
