// Static card data shape, matching data-pipeline/output/cards_final.json
// (see docs/card-database-schema.md). This is read-only reference data -- never mutated
// during a game. In-play state lives on CardInstance (see instance.ts) instead.

export type CardType = 'Magi' | 'Creature' | 'Relic' | 'Spell';
export type Rarity = 'C' | 'U' | 'R' | 'P' | 'F';

export interface NamedAbility {
  name: string | null;
  text: string;
}

export interface Power {
  /** The internal lookup key -- power.ts's findPower resolves a Power by `.find((p) => p.name ===
   *  powerName)`, which only ever reaches the FIRST array entry when two Powers on the same card
   *  share a name. Guaranteed unique per card as of the Naroom Spell-pass audit (2026-07-23, Tryn
   *  Flame-Saver) -- see `displayName` below for the one card whose printed text needed this
   *  disambiguated from what's actually shown to the player. */
  name: string;
  /** What's actually shown to the player (Play.tsx render sites), falling back to `name` when
   *  absent (the overwhelming majority of Powers). Only set when `name` had to be disambiguated
   *  away from the card's own printed text to make it a unique lookup key (Tryn Flame-Saver's two
   *  same-printed-name "Energy Substitution" Powers: internal names "Energy Substitution (Cald)"/
   *  "(Naroom)", both displaying as "Energy Substitution"). Rayje's Belt's Lockdown resolves this
   *  before comparing against its own locked category, so naming either of Tryn's two clauses locks
   *  both as one nameable ability (owner-confirmed ruling, 2026-07-23) -- see rayjesBelt.ts. */
  displayName?: string;
  /** 212 real Powers have no cost at all in the source data -- a genuinely free activated
   *  ability, not a data error (often with a non-energy cost baked into the text instead, e.g.
   *  "Discard [this card] from play"). power.ts treats a missing cost as 0. */
  cost: number | 'X' | undefined;
  text: string;
}

export interface CardLegality {
  constructed: 'legal' | 'banned';
  constructed_banned_as_of: string | null;
}

export type ImplementationStatus = 'not started' | 'structured' | 'custom code needed';

export interface CardDefinition {
  key: number;
  name: string;
  normalized_name: string;
  card_type: CardType;
  set: string;
  rarity: Rarity;
  regions: string[];
  cost: number | 'X';
  energize: number | null;
  starting: string[] | null;
  /** Usually a single Magi/region name, but a real data quirk: 2 cards ("Power of the Creators",
   *  "Cleansing") print "Starting: <Magi A>, <Magi B>[, ...]" for more than one Magi at once, so
   *  this is scraped as a string array for those. See impliedStartingCardNames in setup.ts. */
  starting_magi: string | string[] | null;
  effects: NamedAbility[];
  powers: Power[];
  text: string | null;
  flavor: string | null;
  artist: string | null;
  alternate: string | null;
  subtype: string | null;
  /** Which Magi are granted a one-tier region-legality bump toward playing this card (see
   *  regions.ts's checkRegionLegality doc comment for the full Restricted -> Penalty -> Free
   *  tier model): a comma-separated region-name string (e.g. "Arderial, Orothe"), or a single
   *  region name, or null. For a card whose own `regions` includes 'Core', this ALSO grants a
   *  plain (non-Shadow) Magi of the named region(s) the bump, not just that region's Shadow Magi
   *  -- confirmed against real card text (e.g. Dagok: "Naroom Magi can play Dagok"). Symmetrically,
   *  for a card whose own `regions` does NOT include Core, `shadow_play="Core"` grants a plain
   *  Core Magi the bump instead (e.g. Sneaky Weebo: "Core Magi may play Sneaky Weebo," Swamp
   *  Hyren) -- region-audit follow-up, 2026-07-24, see regions.ts's qualifiesForShadowPlayGrant.
   *  When `region_restrictive` is true, this same field instead names the SOLE exempted region(s)
   *  from that card's hard restriction (see below), rather than an additive grant. */
  shadow_play: string | null;
  /** Non-null only on actual Shadow Magi (Magi cards) -- the region this Magi was "originally,"
   *  before becoming a Core Shadow Magi (e.g. Lanyx: regions=['Core'], original_region='Cald').
   *  This IS the Shadow Magi identity marker regions.ts's checkRegionLegality already keys off. */
  original_region: string | null;
  /** True for the "Only [Region] Magi and [Region] Shadow Magi can play [card]" cycle (the 11
   *  "Crushing [Element]" Spells) plus Shadow Ritual ("Only Shadow Magi can play," any region) --
   *  overrides the normal off-region-penalty allowance, hard-blocking everyone outside
   *  `shadow_play`'s named region (+ that region's Shadow Magi), or outside "any Shadow Magi" if
   *  `shadow_play` is null. Derived by data-pipeline/add-shadow-magi-fields.js. */
  region_restrictive: boolean;
  /** True only for Crushing Darkness -- carves Shadow Magi OUT of the free Core-card access every
   *  other Core Magi gets for this specific card. Derived by
   *  data-pipeline/add-shadow-magi-fields.js. */
  shadow_magi_excluded: boolean;
  image_front: string | null;
  legality: CardLegality;
  implementation_status: ImplementationStatus;
}

/** Lookup table keyed by CardDefinition.key, the form the engine consumes internally. */
export type CardDatabase = ReadonlyMap<number, CardDefinition>;

export function buildCardDatabase(cards: readonly CardDefinition[]): CardDatabase {
  const map = new Map<number, CardDefinition>();
  for (const card of cards) {
    if (map.has(card.key)) {
      throw new Error(`Duplicate card key in database: ${card.key} (${card.name})`);
    }
    map.set(card.key, card);
  }
  return map;
}
