// Gherish -- two clauses:
//   "Drift: At the beginning of your turn, move up to two energy from one of your Creatures to
//   Gherish."
//   "Abrade: Whenever an opponent uses a Power, choose one of that player's Creatures. Discard
//   one energy from the chosen Creature."
//
// Drift real choice (Phase 4c, 2026-07-11): "one of your Creatures" replaces the earlier "first
// eligible own Creature with energy to spare" simplification with a real pending choice
// (registry.ts's pendingTargetChoice/resolveTargetChoice); "up to two" still moves as much as
// available capped at two, resolved against whichever Creature is actually chosen.
//
// Abrade (task #39-3b, 2026-07-17, d'Resh Category C): the new "react to opponent's Power use"
// mechanism -- registry.ts's `onOpponentPowerUsed` broadcast (power.ts, fired unconditionally
// right after every Power finishes resolving) sets its own pending marker, then the SAME
// `pendingTargetChoice`/`resolveTargetChoice` pair Drift already uses (mandatory -- "choose one,"
// no "may") offers the opponent's own Creatures as the pool instead. Both clauses share the one
// hook pair, so `pendingTargetChoice`/`resolveTargetChoice` branch on which tag is actually set --
// Drift and Abrade can never both be pending at once in practice (Drift only fires at the very
// start of Gherish's OWN controller's turn; Abrade only fires off the OPPONENT's Power use), but
// the branch is written defensively either way. No resolution is a no-op for both clauses (matches
// Drift's own pre-existing behavior from Phase 4c -- neither clause prints "may," but declining is
// treated as inaction rather than synthesizing a default, kept consistent between the two).

import { registerCardEffect } from './registry.js';
import { discardEnergy, rearrangeEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { getOpponents } from '../types/state.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';
import type { CardInstance } from '../types/instance.js';

const DRIFT_PENDING = 'gherishDriftPending';
// Stage 2 of Drift. "Move UP TO two energy" needs an AMOUNT as well as a source, and the two cannot
// share one prompt, so the chosen source is parked on a dynamically-keyed tag (same encoding trick
// as bazha.ts's per-(source, Power) grant cap) while the numeric family collects 0..2.
const DRIFT_AMOUNT_PENDING = 'gherishDriftAmountPending';
const DRIFT_SOURCE_PREFIX = 'gherishDriftSource:';

function driftSource(self: CardInstance): string | undefined {
  for (const tag of self.tags) if (tag.startsWith(DRIFT_SOURCE_PREFIX)) return tag.slice(DRIFT_SOURCE_PREFIX.length);
  return undefined;
}

function clearDriftSource(self: CardInstance): void {
  for (const tag of [...self.tags]) if (tag.startsWith(DRIFT_SOURCE_PREFIX)) removePermanentTag(self, tag);
}
const ABRADE_PENDING = 'gherishAbradePending';

function driftPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  return creaturesControlledBy(state, cardDb, self.controllerId).filter((c) => c.instanceId !== self.instanceId && (c.currentEnergy ?? 0) > 0);
}

function abradePool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const opponent = getOpponents(state, self.controllerId)[0];
  if (!opponent) return [];
  return opponent.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature');
}

registerCardEffect('Gherish', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Drift arms on turn-start and runs a source-then-
  // amount two-stage chain (target + numeric); Abrade arms on opponent-Power-use and runs a
  // single target choice. The pendingTargetChoice/resolveTargetChoice pair is shared; each
  // hook body already branches on its own pending tag, so narrowing to one Effect still
  // fires only that Effect's branch on Taglat.
  effectHooks: {
    Drift: ['onOwnTurnStart', 'pendingTargetChoice', 'resolveTargetChoice', 'pendingNumericChoice', 'resolveNumericChoice'],
    Abrade: ['onOpponentPowerUsed', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  onOwnTurnStart: (state, cardDb, self) => {
    if (driftPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, DRIFT_PENDING);
  },
  onOpponentPowerUsed: (state, cardDb, self, user) => {
    if (user.controllerId === self.controllerId) return;
    if (abradePool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, ABRADE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (self.tags.has(DRIFT_PENDING)) {
      const pool = driftPool(state, cardDb, self);
      if (pool.length === 0) return undefined;
      // `optional`/`intent` returned by the HOOK, not read from promptIntent.ts's table: that table
      // is keyed by card NAME, and Gherish's two clauses share this one family with opposite
      // answers -- Drift is a beneficial "up to" (declinable), Abrade is a mandatory harmful
      // "choose one". Only the per-branch return can tell them apart. Live playtest 2026-07-27:
      // Drift was offered with no Skip, so a Creature at 1-2 energy was drained to zero and
      // DEFEATED by its controller's own beneficial effect, with no way out.
      return {
        prompt: "Gherish's Drift: choose one of your Creatures to move up to 2 energy from to Gherish",
        pool,
        optional: true,
        intent: 'beneficial' as const,
      };
    }
    if (self.tags.has(ABRADE_PENDING)) {
      const pool = abradePool(state, cardDb, self);
      if (pool.length === 0) return undefined;
      return { prompt: "Gherish's Abrade: choose one of your opponent's Creatures to discard one energy from", pool };
    }
    return undefined;
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    if (self.tags.has(DRIFT_PENDING)) {
      removePermanentTag(self, DRIFT_PENDING);
      if (!chosenInstanceId) return; // declined -- "up to two" includes none
      const source = driftPool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
      if (!source) return;
      // Hand off to the numeric stage rather than auto-moving the max. Moving 2 off a 2-energy
      // Creature kills it, so "up to two" has to mean the player picks the number -- quorPup.ts,
      // the sibling "move up to two" card, already works this way, and habob.ts's own Serve clause
      // in this same region was converted for the same reason (task #359).
      addPermanentTag(state, cardDb, self, `${DRIFT_SOURCE_PREFIX}${source.instanceId}`);
      addPendingChoiceTag(self, DRIFT_AMOUNT_PENDING);
      return;
    }
    if (self.tags.has(ABRADE_PENDING)) {
      removePermanentTag(self, ABRADE_PENDING);
      if (!chosenInstanceId) return;
      const target = abradePool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
      if (target) discardEnergy(state, cardDb, target, 1, 'effect', undefined, rng);
    }
  },
  pendingNumericChoice: (state, cardDb, self) => {
    if (!self.tags.has(DRIFT_AMOUNT_PENDING)) return undefined;
    const sourceId = driftSource(self);
    const source = sourceId ? driftPool(state, cardDb, self).find((c) => c.instanceId === sourceId) : undefined;
    // Source gone or drained between the two stages -- drop the whole thing rather than stranding a
    // prompt the player cannot answer.
    if (!source) {
      removePermanentTag(self, DRIFT_AMOUNT_PENDING);
      clearDriftSource(self);
      return undefined;
    }
    const max = Math.min(2, source.currentEnergy ?? 0);
    const name = cardDb.get(source.definitionKey)?.name ?? 'that Creature';
    return { prompt: `Gherish's Drift: how much energy to move from ${name} to Gherish (0-${max})`, min: 0, max };
  },
  resolveNumericChoice: (state, cardDb, self, chosen, rng) => {
    if (!self.tags.has(DRIFT_AMOUNT_PENDING)) return;
    removePermanentTag(self, DRIFT_AMOUNT_PENDING);
    const sourceId = driftSource(self);
    clearDriftSource(self);
    const source = sourceId ? driftPool(state, cardDb, self).find((c) => c.instanceId === sourceId) : undefined;
    if (!source) return;
    const amount = Math.max(0, Math.min(chosen, 2, source.currentEnergy ?? 0));
    if (amount > 0) rearrangeEnergy(state, cardDb, source, self, amount, rng);
  },
});
