// Xyx Minor -- "Gathering Clouds (2): Choose any one Xyx in play. Add four energy to the chosen
// Xyx." Name-family match ("Xyx"), same established pattern as Chogus/Vemment/Trulb/Hyren/Vashp.
//
// Swirling Orshaa's Morph (Spell-pass audit follow-up, 2026-07-24) -- "Xyx" isn't always the LAST
// word of a card's name (creatureType()'s own convention), so this matches on a name substring via
// matchesCreatureFamily() instead -- that helper also checks a live Morph identityOverride FIRST,
// so Orshaa can react here even though this card never calls creatureType()/effectiveCreatureType()
// directly.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, matchesCreatureFamily } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Xyx Minor', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => matchesCreatureFamily(cardDb, c, 'Xyx')),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Gathering Clouds') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!matchesCreatureFamily(ctx.cardDb, target, 'Xyx')) return;

    addEnergy(ctx.state, ctx.cardDb, target, 4, 'power');
  },
  specifiedCreatureTypes: () => ['Xyx'],
});
