// Bombard (Spell, Cald, cost 4) -- "Roll a die. Discard that much energy, divided any way you
// choose, from up to three opposing Creatures." Cald Spell pass, Category C (2026-07-20).
//
// "Divided any way you choose" across up to 3 targets has no existing multi-value-split picker in
// this engine (registry.ts's pendingMultiTargetChoice assigns a FIXED amount per chosen target,
// not a free allocation of one shared pool). Per the plan's own suggestion, built as a small local
// state machine ALTERNATING between two already-proven post-hoc families on the SAME (already
// discarded) instance, rather than inventing a new picker type:
//   - pendingTargetChoice ("who's next") offers the not-yet-used opposing Creatures.
//   - pendingNumericChoice ("how much for them, out of what's left") offers 0..remaining pool.
// The two alternate, tracked via a phase tag pair (AWAITING_TARGET/AWAITING_AMOUNT, mutually
// exclusive) plus a remaining-pool counter and one USED_TARGET_PREFIX tag per creature already
// assigned energy -- up to 3 rounds, stopping early if the player declines a target pick, the pool
// hits zero, or 3 targets have been used. Same "tag survives the Spell's own move to the discard
// pile" trick Muck Rain/Trulbble! already use -- pendingTargetChoice/pendingNumericChoice's own
// 5-zone scans find the card there.
//
// FIXED (playtest bug, 2026-07-21): the real damage here happens via resolveNumericChoice, called
// much later by the UI (once the player answers the picker) than play.ts's own ONE-SHOT
// broadcastSpellDiscardedOpposingEnergy call (fired immediately after resolveSpell returns, long
// before any of these post-hoc rounds happen) -- so Scroll of Fire's/Valkan's/Ithapher's own
// same-resolution bonuses, and Blast Gloves' reaction, never saw this Spell's damage at all. Now
// uses effects.ts's discardEnergyFromSpellPostHoc, which wraps each individual hit with its own
// snapshot + broadcast, giving each round the same bonus-eligibility a normal synchronous
// resolveSpell-time hit gets.

import { registerCardEffect } from './registry.js';
import { discardEnergyFromSpellPostHoc, getCounter, setCounter, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { opposingCreatures } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const AWAITING_TARGET = 'bombardAwaitingTarget';
const AWAITING_AMOUNT = 'bombardAwaitingAmount';
const CURRENT_PICK_PREFIX = 'bombardCurrentPick:';
const USED_TARGET_PREFIX = 'bombardUsedTarget:';
const REMAINING_POOL_COUNTER = 'bombardRemainingPool';
const MAX_TARGETS = 3;

function usedTargetIds(self: CardInstance): Set<string> {
  const ids = new Set<string>();
  for (const tag of self.tags) {
    if (tag.startsWith(USED_TARGET_PREFIX)) ids.add(tag.slice(USED_TARGET_PREFIX.length));
  }
  return ids;
}

function currentPickId(self: CardInstance): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(CURRENT_PICK_PREFIX));
  return tag ? tag.slice(CURRENT_PICK_PREFIX.length) : undefined;
}

function eligiblePool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const used = usedTargetIds(self);
  return opposingCreatures(state, cardDb, self.controllerId).filter((c) => !used.has(c.instanceId));
}

registerCardEffect('Bombard', {
  resolveSpell: (ctx) => {
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.controllingPlayer.playerId,
      6,
      'bombard:resolve',
      { controllingPlayerId: ctx.controllingPlayer.playerId },
      ctx.rng
    );
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_TARGET)) return undefined;
    if (getCounter(self, REMAINING_POOL_COUNTER) <= 0) return undefined;
    if (usedTargetIds(self).size >= MAX_TARGETS) return undefined;
    const pool = eligiblePool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    const remaining = getCounter(self, REMAINING_POOL_COUNTER);
    return { prompt: `Bombard: choose an opposing Creature to discard some of the remaining ${remaining} energy from`, pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, AWAITING_TARGET);
    if (!chosenInstanceId) return; // decline -- stop the whole sequence
    const target = eligiblePool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    addPermanentTag(state, cardDb, self, `${CURRENT_PICK_PREFIX}${chosenInstanceId}`);
    addPendingChoiceTag(self, AWAITING_AMOUNT);
  },
  pendingNumericChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_AMOUNT)) return undefined;
    const remaining = getCounter(self, REMAINING_POOL_COUNTER);
    return { prompt: `Bombard: how much of the remaining ${remaining} energy to discard from this Creature?`, min: 0, max: remaining };
  },
  resolveNumericChoice: (state, cardDb, self, chosen, rng) => {
    removePermanentTag(self, AWAITING_AMOUNT);
    const targetId = currentPickId(self);
    if (targetId) removePermanentTag(self, `${CURRENT_PICK_PREFIX}${targetId}`);
    if (!targetId) return;

    const remaining = getCounter(self, REMAINING_POOL_COUNTER);
    const amount = Math.max(0, Math.min(chosen, remaining));
    const target = eligiblePool(state, cardDb, self).find((c) => c.instanceId === targetId);
    if (target && amount > 0) discardEnergyFromSpellPostHoc(state, cardDb, self.controllerId, self, target, amount, rng);

    addPermanentTag(state, cardDb, self, `${USED_TARGET_PREFIX}${targetId}`);
    setCounter(self, REMAINING_POOL_COUNTER, remaining - amount);

    if (remaining - amount > 0 && usedTargetIds(self).size < MAX_TARGETS && eligiblePool(state, cardDb, self).length > 0) {
      addPendingChoiceTag(self, AWAITING_TARGET);
    }
  },
});

registerRollConsumer('bombard:resolve', (state, cardDb, source, payload, finalRoll) => {
  if (!source) return; // Spell removed from every zone during Whimsy window -- unreachable in practice
  const { controllingPlayerId } = payload as { controllingPlayerId: string };
  setCounter(source, REMAINING_POOL_COUNTER, finalRoll);
  if (opposingCreatures(state, cardDb, controllingPlayerId).length > 0) {
    addPendingChoiceTag(source, AWAITING_TARGET);
  }
});
