// Frost Raxis -- "Thermal Stress (1): Choose a Relic in play. That Relic's player must discard
// one of their Relics from play. If the discarded Relic is not the one you chose, add two energy
// to Frost Raxis." Slot 2 (the opponent's mandatory pick of WHICH Relic) always has at least one
// legal option -- the Relic named in slot 1 itself, since its controller necessarily controls it.

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, inPlayControlledBy, findInPlayById } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Frost Raxis', {
  powerTargetSlots: (state, cardDb) => [
    {
      label: 'Choose a Relic in play',
      pool: (s, db) => allRelicsInPlay(s, db),
      min: 1,
      max: 1,
    },
    {
      label: 'Opponent: choose one of your Relics to discard',
      pool: (s, db, pid, priorChoices) => {
        const chosenRelicId = priorChoices[0]?.[0];
        if (!chosenRelicId) return [];
        const chosenRelic = findInPlayById(s, chosenRelicId);
        return chosenRelic ? inPlayControlledBy(s, chosenRelic.controllerId).filter((c) => db.get(c.definitionKey)?.card_type === 'Relic') : [];
      },
      min: 1,
      max: 1,
      respondingPlayer: 'opponent',
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Thermal Stress') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const chosenRelicId = slots[0]?.[0];
    if (!chosenRelicId) return;
    const chosenRelic = findInPlayById(ctx.state, chosenRelicId);
    if (!chosenRelic || ctx.cardDb.get(chosenRelic.definitionKey)?.card_type !== 'Relic') return;

    const discardedId = slots[1]?.[0];
    if (!discardedId) return;
    const discarded = findInPlayById(ctx.state, discardedId);
    if (!discarded || ctx.cardDb.get(discarded.definitionKey)?.card_type !== 'Relic') return;
    if (discarded.controllerId !== chosenRelic.controllerId) return;
    const owner = ctx.state.players.get(discarded.controllerId);
    if (!owner) return;

    discardFromPlay(ctx.state, ctx.cardDb, owner, discarded.instanceId, undefined, undefined, ctx.rng);
    if (discarded.instanceId !== chosenRelic.instanceId) {
      addEnergy(ctx.state, ctx.cardDb, ctx.source, 2, 'power');
    }
  },
});
