// Possession's Glee (Spell) -- "Add three energy to a Creature you control but do not own.
// Orothe Shadow Magi may play Possession's Glee." The Shadow Magi access clause needs no code --
// same `shadow_play` database field + regions.ts precedent as Cataclysm's own "Arderial Shadow
// Magi may play Cataclysm" (cardEffects/cataclysm.ts). "Control but do not own" reads
// CardInstance.ownerId (distinct from controllerId, e.g. a gained-control Creature).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';
import type { PlayerId } from '../types/state.js';

function controlledNotOwned(state: GameState, cardDb: CardDatabase, playerId: PlayerId) {
  return creaturesControlledBy(state, cardDb, playerId).filter((c) => c.ownerId !== playerId);
}

registerCardEffect("Possession's Glee", {
  spellTargets: (state, cardDb, playerId) => controlledNotOwned(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    const target = controlledNotOwned(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    if (!target) return;
    addEnergy(ctx.state, ctx.cardDb, target, 3, 'spell');
  },
});
