// The Prankster -- "Surprise!: At the beginning of your turn, if you have no Creatures in play,
// reveal the top card of your deck. If the revealed card is a Kybar's Teeth Creature, you may play
// it, reducing its cost by four, to a minimum of zero. The Creature cannot attack this turn.
// Otherwise, discard the revealed card." Built task #42, 2026-07-17, the Kybar's Teeth region pass.
//
// "You may play it" is a real player choice -> `pendingYesNoChoice`/`resolveYesNoChoice`, armed at
// `onOwnTurnStart` only when the top card qualifies; the "otherwise, discard" branch has no choice
// and fires immediately. The revealed card's instance id is remembered via an embedded-id permanent
// tag (Venger/Oranragan's technique) so `resolveYesNoChoice` can re-verify it's still on top of the
// deck before playing it (same defensive check Trulb's own `resolvePower` uses). Playing "reducing
// its cost by four" is modeled the same way every other play-from-a-non-hand-zone card in this
// engine is (Trulb, Shaper's Apprentice): the Creature enters with a computed starting energy
// (printed cost - 4, floored at 0) via `playFromZone`, no separate Magi-payment step -- there's no
// real cost-payment path for a card played straight out of the deck in this engine's existing
// conventions.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveStartingEnergy } from '../targeting.js';
import { discardTopOfDeck, playFromZone } from '../effects.js';
import { addPermanentTag, removePermanentTag, addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

const AWAITING_PLAY_PREFIX = 'pranksterAwaitingPlay:';

function awaitingCardId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(AWAITING_PLAY_PREFIX)) return tag.slice(AWAITING_PLAY_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('The Prankster', {
  onOwnTurnStart: (state, cardDb, self) => {
    if (creaturesControlledBy(state, cardDb, self.controllerId).length > 0) return;
    if (awaitingCardId(self) !== undefined) return; // already armed
    const player = state.players.get(self.controllerId);
    const top = player?.deck[0];
    if (!player || !top) return;
    const def = cardDb.get(top.definitionKey);
    if (def?.card_type === 'Creature' && def.regions.includes("Kybar's Teeth")) {
      addPermanentTag(state, cardDb, self, `${AWAITING_PLAY_PREFIX}${top.instanceId}`);
    } else {
      discardTopOfDeck(state, player);
    }
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    const cardId = awaitingCardId(self);
    if (cardId === undefined) return undefined;
    return {
      prompt: "The Prankster's Surprise!: play the revealed Creature (cost reduced by 4, minimum 0)?",
      yesLabel: 'Play it',
      noLabel: 'Discard it',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const cardId = awaitingCardId(self);
    if (cardId === undefined) return;
    removePermanentTag(self, `${AWAITING_PLAY_PREFIX}${cardId}`);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const top = player.deck[0];
    if (!top || top.instanceId !== cardId) return; // deck changed since arming -- decline safely
    if (!chosenBoolean) {
      discardTopOfDeck(state, player);
      return;
    }
    const reducedCost = Math.max(0, effectiveStartingEnergy(state, cardDb, top) - 4);
    const played = playFromZone(state, cardDb, { owner: player, zone: 'deck', instanceId: cardId }, player, reducedCost, rng);
    if (played) addRestrictionTag(state, played, CANNOT_ATTACK, state.turnNumber);
  },
});
