// Grubble -- "Dreamform: Choose any one other Grubble in play. Discard both this Grubble and the
// chosen Grubble from play. Search your deck for any one Creature and play that Creature with its
// starting energy." Excludes itself at the POOL level (via sourceInstanceId, same fix as Flame
// Rudwot's Healing Flame -- see registry.ts's powerTargets doc comment) -- without it, the filter
// by name === 'Grubble' includes THIS copy too (up to 3 copies can be in play), so the UI offered
// a dead-end self-pick that still paid the Power's cost.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById, printedStartingEnergy } from '../targeting.js';
import { discardFromPlay, searchDeckIntoPlay } from '../effects.js';
import { shuffleDeck } from '../zones.js';

registerCardEffect('Grubble', {
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) =>
    creaturesControlledBy(state, cardDb, playerId).filter(
      (c) => c.instanceId !== sourceInstanceId && cardDb.get(c.definitionKey)?.name === 'Grubble'
    ),
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dreamform') return;
    if (ctx.chosenTargetId === undefined) return;
    if (ctx.chosenTargetId === ctx.source.instanceId) return; // must be an OTHER Grubble
    const other = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!other || ctx.cardDb.get(other.definitionKey)?.name !== 'Grubble') return;
    if (other.controllerId !== ctx.controllingPlayer.playerId) return;

    const searchIds = ctx.chosenDeckSearchIds ?? [];
    if (searchIds.length > 1) return;
    for (const id of searchIds) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      if (!card || ctx.cardDb.get(card.definitionKey)?.card_type !== 'Creature') return;
    }

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, other.instanceId, undefined, undefined, ctx.rng);
    for (const id of searchIds) {
      const key = ctx.controllingPlayer.deck.find((c) => c.instanceId === id)?.definitionKey;
      if (key === undefined) continue;
      searchDeckIntoPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, id, printedStartingEnergy(ctx.cardDb, key), true, ctx.rng);
    }
    shuffleDeck(ctx.controllingPlayer, ctx.rng);
  },
});
