// Weave Mat -- "Easy Go: At the end of each turn, if no Creatures were played that turn, discard
// two of your non-Magi cards from your hand or from play." "No Creatures were played" is read
// globally (by EITHER player), using CardInstance's playedOnTurnNumber field. Registers BOTH
// onOwnTurnEnd and onOpponentTurnEnd with the same body, same "covers every turn-end exactly
// once" reasoning as chillCane.ts.
//
// Real choice (task #40-6, 2026-07-17, player-choice-default retrofit, Group 6): "discard two of
// your... cards from your hand or from play" doesn't say which -- now a
// `pendingMultiTargetChoice`/`resolveMultiTargetChoice` (registry.ts's new multi-select post-hoc
// family), the first user whose pool spans TWO zones at once (hand + in-play; a flat instance-id
// list is exactly why `pendingMultiTargetChoice.pool` is ids rather than `CardInstance[]`). No
// resolution falls back to the old "hand first, then play, in array order" default (Magi are
// never in either zone in this engine, so no separate exclusion is needed either way).

import { registerCardEffect } from './registry.js';
import { discardFromHand, discardFromPlay, drawCards } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag, addDurationTag, hasDurationTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING_CHOICE = 'weaveMatEasyGoAwaitingChoice';

function anyCreaturePlayedThisTurn(state: GameState, cardDb: CardDatabase): boolean {
  for (const player of state.players.values()) {
    for (const card of [...player.inPlay, ...player.discardPile]) {
      if (card.playedOnTurnNumber === state.turnNumber && cardDb.get(card.definitionKey)?.card_type === 'Creature') {
        return true;
      }
    }
  }
  return false;
}

function pool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return [...player.hand, ...player.inPlay];
}

function easyGo(state: GameState, cardDb: CardDatabase, self: CardInstance): void {
  if (self.tags.has(AWAITING_CHOICE)) return;
  if (anyCreaturePlayedThisTurn(state, cardDb)) return;
  if (pool(state, cardDb, self).length === 0) return;
  addPendingChoiceTag(self, AWAITING_CHOICE);
}

const EASY_COME_USED_THIS_TURN = 'weaveMatEasyComeUsedThisTurn';

registerCardEffect('Weave Mat', {
  // Per-Effect hook narrowing (deep-dive audit, 2026-08-13). Easy Come is the once/turn draw
  // on any-Creature-played; Easy Go is the end-of-turn "if no Creatures played, discard two"
  // multi-target pending choice (fires on either turn-end hook, one per real event).
  effectHooks: {
    'Easy Come': ['onPlay'],
    'Easy Go': ['onOwnTurnEnd', 'onOpponentTurnEnd', 'pendingMultiTargetChoice', 'resolveMultiTargetChoice'],
  },
  // "Easy Come: Once per turn, when a Creature is played, draw a card." BUILT 2026-07-28
  // (ability-count sweep) -- the file had only Easy Go. Broadcast onPlay reactor with a
  // once-per-turn duration tag, the same shape as J'lith's Collector. No controller filter: the
  // text says "when a Creature is played", not "when you play", so either player's Creature arms
  // it -- and the DRAW is Weave Mat's controller's, which is what `self.controllerId` gives.
  onPlay: (state, cardDb, played, self) => {
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (hasDurationTag(self, EASY_COME_USED_THIS_TURN)) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;

    drawCards(state, cardDb, owner, 1);
    addDurationTag(state, cardDb, self, EASY_COME_USED_THIS_TURN, state.turnNumber);
  },
  onOwnTurnEnd: (state, cardDb, self) => easyGo(state, cardDb, self),
  onOpponentTurnEnd: (state, cardDb, self) => easyGo(state, cardDb, self),
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const candidates = pool(state, cardDb, self);
    if (candidates.length === 0) return undefined;
    const count = Math.min(2, candidates.length);
    return {
      prompt: "Weave Mat's Easy Go: discard two of your non-Magi cards from your hand or from play",
      pool: candidates.map((c) => c.instanceId),
      minCount: count,
      maxCount: count,
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds, rng) => {
    removePermanentTag(self, AWAITING_CHOICE);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const candidates = pool(state, cardDb, self);
    const candidateIds = new Set(candidates.map((c) => c.instanceId));
    const count = Math.min(2, candidates.length);

    let chosen: string[];
    if (chosenInstanceIds) {
      const valid = [...new Set(chosenInstanceIds)].filter((id) => candidateIds.has(id)).slice(0, count);
      chosen = valid.length === count ? valid : candidates.slice(0, count).map((c) => c.instanceId);
    } else {
      chosen = candidates.slice(0, count).map((c) => c.instanceId);
    }

    for (const id of chosen) {
      if (player.hand.some((c) => c.instanceId === id)) {
        discardFromHand(state, cardDb, player, [id], undefined, rng);
      } else if (player.inPlay.some((c) => c.instanceId === id)) {
        discardFromPlay(state, cardDb, player, id, undefined, undefined, rng);
      }
    }
  },
});
