// Cave Rudwot -- "Defense: If Cave Rudwot is attacked, add two energy to it before energy is
// removed."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Cave Rudwot', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    addEnergy(ctx.state, ctx.cardDb, self, 2, 'effect');
  },
});
