// Exposure (Spell) -- "Each non-Nar Magi loses energy equal to their Energize. Each Core Magi
// loses two additional energy." Nar Spell pass, Category A (2026-07-22). No target -- a board-wide
// loop over allMagiInPlay, using effectiveMagiDef (not a raw cardDb.get) so a Shadow Magi's real
// region (Core, via magiIdentityOverride) is read correctly, and effectiveEnergizeRate (not the
// printed def.energize) so any live Energize modifier is reflected.

// Ashio's Weave Twist (2026-07-24): "Core" above is Exposure's OWN printed text, so under Ashio it
// means its own region (Nar) instead -- collapsing the "+2" clause to duplicate the "non-Nar"
// exclusion already above it (Nar Magi are skipped entirely, so the +2 branch becomes unreachable
// for them). See targeting.ts's ashioAdjustedRegion doc comment.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, ashioAdjustedRegion, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { effectiveEnergizeRate } from '../turn.js';
import { effectiveMagiDef } from '../regions.js';

registerCardEffect('Exposure', {
  resolveSpell: (ctx) => {
    for (const magi of allMagiInPlay(ctx.state)) {
      const def = ctx.cardDb.get(magi.definitionKey);
      if (!def) continue;
      const regions = effectiveMagiDef(def, magi).regions;
      if (regions.includes(regionForTargetFilter(ctx.state, 'Nar'))) continue;
      let amount = effectiveEnergizeRate(ctx.state, ctx.cardDb, magi);
      if (regions.includes(regionForTargetFilter(ctx.state, ashioAdjustedRegion(ctx.state, ctx.cardDb, 'Core', ['Nar'])))) amount += 2;
      if (amount > 0) discardEnergy(ctx.state, ctx.cardDb, magi, amount, 'spell', undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. `isCoreRegion` bypassed here (inline check instead)
  // since that shared helper has no state param and is used elsewhere for unrelated,
  // non-swap-aware purposes.
  specifiedSpellTargetRegions: (state, cardDb) => ['Nar', ashioAdjustedRegion(state, cardDb, 'Core', ['Nar'])],
});
