// Nalo -- "Tsunami: Discard Nalo from play. Discard two energy from each Creature and Magi in
// play." Self-discard, no target picker, sweeps everyone on both sides.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Nalo', {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- unconditional once used, so this only
  // checks that an opposing Magi actually exists.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options, powerName) =>
    powerName === 'Tsunami' && getOpponents(state, actingPlayerId).some((opp) => !!opp.activeMagi),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Tsunami') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 2, undefined, undefined, ctx.rng);
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      discardEnergy(ctx.state, ctx.cardDb, magi, 2, undefined, undefined, ctx.rng);
    }
  },
});
