// Gogor's Spade -- "Paydirt: Whenever one of your Creatures defeats an opposing Creature in an
// attack, draw a card." afterCombat fires after the zero-energy defeat check already ran, so
// outcome.defenderSurvived reflects the real result.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect("Gogor's Spade", {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (!ctx.defender) return; // "an opposing Creature" -- not a direct Magi attack
    if (outcome.defenderSurvived) return;

    drawCards(ctx.state, ctx.cardDb, ctx.attackingPlayer, 1);
  },
});
