// Gift of the Weave -- "Gift of the Weave cannot be discarded from play by cards that specifically
// discard Relics from play. Discard Gift of the Weave from play if your Magi is not a Weave Magi
// or Weave Shadow Magi." Same shape as Kybar's Fang/Vault of Knowledge Key/Gate to Ombor, via the
// shared regionLockedRelic.ts helper -- "Weave Shadow Magi" checked via `original_region` (the
// same Shadow-Magi identity check tithragar.ts/shadowHyren.ts already established).

import { registerCardEffect } from './registry.js';
import { applyRegionLockedRelic } from './regionLockedRelic.js';

registerCardEffect('Gift of the Weave', {
  canBeDiscardedFromPlay: () => false,
  onOwnTurnStart: (state, cardDb, self, rng) =>
    applyRegionLockedRelic(
      state,
      cardDb,
      self,
      (magiDef) => magiDef.regions.includes('Weave') || magiDef.original_region === 'Weave',
      rng
    ),
});
