// Wudge -- "Strengthen: Whenever any other Creature is played, add one energy to Wudge." Broadcast
// onPlay reactor -- fires for EITHER side's Creature plays (no "opponent"/"you" qualifier in the
// text), excluding only Wudge's own play.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Wudge', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;

    addEnergy(state, cardDb, self, 1, 'effect');
  },
});
