// The Real Qwade -- two printed clauses:
//   "The Real Qwade can be in a Magi stack with 'Qwade'. When you reveal The Real Qwade, defeat
//   him if your previous defeated Magi was not 'Qwade'." A self-defeat trigger AT REVEAL time --
//   reuses the existing `onMagiRevealed` hook (fires for the revealed Magi itself, per its own doc
//   comment), checked against the CONTROLLER's most recent entry in `defeatedMagi`. `magiCountsAs`
//   (not a raw name check) for the "Qwade" match, same convention as every other card that names a
//   specific Magi. Reuses energy.ts's now-exported `defeatMagi` (the same zone move a normal
//   defeat uses) + `checkMagiDefeats` for the win-check machinery -- no immediate re-reveal happens
//   (matching normal succession rules: the next Magi only comes in at the start of the
//   controller's next turn).
//   "Leech: At the beginning of your Play Creatures step, you may discard two energy from The
//   Real Qwade. If you do, until the end of your turn, whenever you play a Creature, choose
//   another Creature. Move one energy from the chosen Creature to the Creature you just played."
//   Built task #35, 2026-07-16 -- registry.ts's new `onOwnPlayCreaturesStepStart` (fired by
//   turn.ts's new `runPlayCreaturesPhaseStart`, a phase-entry hook that mirrors runEnergizePhase/
//   runDrawPhase but for the `playNewCreatures` phase specifically -- a DIFFERENT, later moment
//   than `onOwnTurnStart`) marks a pending yes/no choice, reusing the existing
//   `pendingOwnTurnStartChoice`/`resolveOwnTurnStartChoice` UI machinery (that hook's own doc
//   comment describes it as "a pending turn-start choice" -- functionally identical shape to what
//   Leech needs, just fired from a different trigger than its usual onOwnTurnStart caller). If
//   accepted, a LEECH_ARMED duration tag (expires end of THIS turn, `state.turnNumber`) arms the
//   second clause: an `onPlay` broadcast reactor (same shape as Nymat's Sandstorm) that, for every
//   OTHER Creature played this turn, marks a real target choice (Dark Furok's Revile is the
//   reference shape for a marker-tag-driven pendingTargetChoice) excluding the just-played card
//   itself, then moves 1 energy from the chosen Creature to the just-played one.

import { registerCardEffect } from './registry.js';
import { defeatMagi, checkMagiDefeats } from '../energy.js';
import { magiCountsAs } from './magiIdentity.js';
import { discardEnergy, addEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag, addPermanentTag, removePermanentTag } from '../durationTags.js';
import { allCreaturesInPlay } from '../targeting.js';
import type { CardInstance } from '../types/instance.js';

const LEECH_PENDING = 'realQwadeLeechPending';
const LEECH_ARMED = 'realQwadeLeechArmed';
const LEECH_TARGET_PREFIX = 'realQwadeLeechTarget:';

function leechPendingJustPlayedId(self: CardInstance): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(LEECH_TARGET_PREFIX)) return tag.slice(LEECH_TARGET_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('The Real Qwade', {
  onMagiRevealed: (state, cardDb, revealedMagi, self, rng) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const previousDefeated = player.defeatedMagi[player.defeatedMagi.length - 1];
    const wasQwade = previousDefeated ? magiCountsAs(cardDb, previousDefeated, 'Qwade') : false;
    if (!wasQwade) {
      defeatMagi(state, cardDb, player, rng);
      checkMagiDefeats(state, cardDb, rng);
    }
  },
  onOwnPlayCreaturesStepStart: (state, cardDb, self) => {
    if ((self.currentEnergy ?? 0) < 2) return;
    addPermanentTag(state, cardDb, self, LEECH_PENDING);
  },
  pendingOwnTurnStartChoice: (state, cardDb, self) => {
    if (!self.tags.has(LEECH_PENDING)) return undefined;
    return { prompt: 'Leech: discard two energy from The Real Qwade to arm it for this turn?', yesLabel: 'Discard 2', noLabel: 'Skip' };
  },
  resolveOwnTurnStartChoice: (state, cardDb, self, chosenBoolean) => {
    if (!self.tags.has(LEECH_PENDING)) return;
    removePermanentTag(self, LEECH_PENDING);
    if (!chosenBoolean) return;
    discardEnergy(state, cardDb, self, 2, 'effect');
    addDurationTag(state, cardDb, self, LEECH_ARMED, state.turnNumber);
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (!hasDurationTag(self, LEECH_ARMED)) return;
    const pool = allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== played.instanceId);
    if (pool.length === 0) return;
    addPermanentTag(state, cardDb, self, `${LEECH_TARGET_PREFIX}${played.instanceId}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const justPlayedId = leechPendingJustPlayedId(self);
    if (!justPlayedId) return undefined;
    const pool = allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== justPlayedId);
    if (pool.length === 0) return undefined;
    return { prompt: 'Leech: choose a Creature to move one energy from', pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const justPlayedId = leechPendingJustPlayedId(self);
    if (!justPlayedId) return;
    removePermanentTag(self, `${LEECH_TARGET_PREFIX}${justPlayedId}`);
    if (!chosenInstanceId) return;
    const chosen = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    const justPlayed = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === justPlayedId);
    if (!chosen || !justPlayed) return;
    discardEnergy(state, cardDb, chosen, 1, 'effect', undefined, rng);
    addEnergy(state, cardDb, justPlayed, 1, 'effect');
  },
});
