// Inhibitor Band -- "When you play Inhibitor Band, discard all other Universal Relics in play."
// (onPlay reacting to its OWN entry, the drahkar `played.instanceId === self.instanceId` pattern)
// + "Players cannot play Universal Relics." (registry.ts's preventsPlayOf -- a both-sides passive
// lockdown while Inhibitor Band is in play). The first Inhibitor Band plays fine, since the block is
// only checked against Relics ALREADY in play; a second Universal Relic (including another Inhibitor
// Band) is then blocked.

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, effectiveRegions } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { getPlayer } from '../types/state.js';
import { isUniversal } from '../regions.js';

registerCardEffect('Inhibitor Band', {
  // Per-Effect hook narrowing (deep-dive audit, 2026-08-13). Reprise is the self-play
  // sweep-other-Universal-Relics reaction; Universal Lock is the passive both-sides play block.
  effectHooks: {
    Reprise: ['onPlay'],
    'Universal Lock': ['preventsPlayOf'],
  },
  onPlay: (state, cardDb, played, self, rng) => {
    if (played.instanceId !== self.instanceId) return; // only on Inhibitor Band's OWN play
    for (const relic of allRelicsInPlay(state, cardDb)) {
      if (relic.instanceId === self.instanceId) continue;
      if (isUniversal(effectiveRegions(state, cardDb, relic))) {
        discardFromPlay(state, cardDb, getPlayer(state, relic.controllerId), relic.instanceId, undefined, undefined, rng);
      }
    }
  },
  preventsPlayOf: (_state, cardDb, playedDef) =>
    playedDef.card_type === 'Relic' && isUniversal(playedDef.regions),
});
