// Lightning (Spell) -- "Choose any one Creature in play. Add two energy to or discard two energy
// from the chosen Creature." The chooser (the Spell's own controller) picks which of the two
// branches, alongside the target -- registry.ts's new spellBooleanChoice hook, first card to need
// it (chosenBoolean true = "add", the declared yesLabel branch).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Lightning', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellBooleanChoice: () => ({ prompt: 'Add or discard two energy?', yesLabel: 'Add', noLabel: 'Discard' }),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (ctx.chosenBoolean) {
      addEnergy(ctx.state, ctx.cardDb, target, 2, 'spell');
    } else {
      discardEnergy(ctx.state, ctx.cardDb, target, 2, 'spell', undefined, ctx.rng);
    }
  },
});
