// Updraft (Spell) -- "Choose any one of your Creatures in play. Return the chosen Creature to your
// hand. Place its energy on your Magi." Own Creatures only. Energy is captured BEFORE returnToHand
// runs (which nulls currentEnergy) and added to the Magi AFTER (never leave a Creature at 0 energy
// while still in a zone that gets defeat-checked -- the same ordering caveat documented on Barak's
// Prophecy-class rearrange-then-return cards).

import { registerCardEffect } from './registry.js';
import { addEnergy, returnToHand } from '../effects.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';

registerCardEffect('Updraft', {
  spellTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const energy = target.currentEnergy ?? 0;
    returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId);
    const magi = ctx.controllingPlayer.activeMagi;
    if (magi && energy > 0) addEnergy(ctx.state, ctx.cardDb, magi, energy, 'spell');
  },
});
