// Spore Vashp -- "True Form: Discard Spore Vashp from play. Choose any two different Underneath
// Creatures in your discard pile. Your opponent chooses one of the two chosen Creatures. Play that
// Creature with half of its starting energy (rounded up) without paying any costs. That Creature may
// not attack this turn." Built task #48, 2026-07-18, the Underneath region pass -- Category C.
//
// "Your opponent chooses one of the two" is auto-resolved by the documented adversarial-auto-pick
// convention (same as every other opponent-chooses-among-your-picks card in this codebase): the
// acting player would rationally offer the two highest-starting-energy Underneath Creatures in their
// discard pile, and the opponent would then keep the WORSE of those two for them -- i.e. the
// second-highest overall. So this plays the second-highest-starting-energy Underneath Creature at
// half its printed starting energy (rounded up), via effects.ts#playFromZone (which bypasses cost/
// region legality, exactly what "without paying any costs" wants), then tags it CANNOT_ATTACK.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, playFromZone } from '../effects.js';
import { effectiveRegions, regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Spore Vashp', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'True Form') return;
    const player = ctx.controllingPlayer;

    // Discard Spore Vashp from play first, exactly as the text orders it.
    discardFromPlay(ctx.state, ctx.cardDb, player, ctx.source.instanceId, undefined, undefined, ctx.rng);

    // Underneath Creatures in your discard pile (excluding Spore Vashp itself, which just landed
    // there -- "any two different" Creatures, and re-playing the card you just spent would be a
    // degenerate reading). Sorted by printed starting energy, highest first.
    const candidates = player.discardPile
      .filter((c) => c.instanceId !== ctx.source.instanceId)
      .filter((c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature')
      .filter((c) => effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, 'Underneath')))
      .sort((a, b) => effectiveStartingEnergy(ctx.state, ctx.cardDb, b) - effectiveStartingEnergy(ctx.state, ctx.cardDb, a));

    // "Two different" Creatures are required; the opponent then keeps the worse (second-highest).
    if (candidates.length < 2) return;
    const chosen = candidates[1]!; // second-highest = opponent's adversarial pick

    const half = Math.ceil(effectiveStartingEnergy(ctx.state, ctx.cardDb, chosen) / 2);
    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: player, zone: 'discardPile', instanceId: chosen.instanceId },
      player,
      half
    , ctx.rng);
    if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Underneath'],
});
