// Shared "Each of your non-Nar, non-Universal cards costs one additional energy to play" helper
// -- NOT itself a registered card, imported by every Nar Magi that prints this exact clause
// verbatim (Bronn, Emaya, Halsted, Laranel, Odavast, Ust -- 2026-07-11 cost-modification bucket).
// Self-surcharge, not opposing -- only applies to `self`'s OWN controller playing a card.

import type { GameState } from '../types/state.js';
import type { CardDatabase, CardDefinition } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { PlayerId } from '../types/state.js';

export function narSurcharge(
  state: GameState,
  cardDb: CardDatabase,
  playedDef: CardDefinition,
  playerId: PlayerId,
  self: CardInstance
): number {
  if (playerId !== self.controllerId) return 0;
  if (playedDef.regions.includes('Nar') || playedDef.regions.includes('Universal')) return 0;
  return 1;
}
