// Ora -- "Strengthen: Whenever Ora plays an Arderial Creature, add one energy to that Creature."
// Self-trigger onPlay reactor on the Magi (same shape as Kazm/Wudge -- onPlay already fires for
// both players' Magi with no extra wiring needed).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Ora', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Creature' || !playedDef.regions.includes('Arderial')) return;

    addEnergy(state, cardDb, played, 1, 'effect');
  },
});
