// Orwin -- "Recall (2): Take any one card from your discard pile and place it in your hand. Do
// not draw any cards during your Draw Step this turn. Cards are only affected by Recall once per
// game." Three clauses, three distinct mechanisms: (1) discardPileSearch/retrieveFromDiscardPile,
// same as Sperri/Delia/Bog Stone/Book of Life; (2) state.skipDrawStepThisTurn (new this batch,
// mirrors the existing skipAttackPhaseThisTurn flag); (3) "Cards are only affected by Recall once
// per game" reads as a restriction on the CARD (subject of the sentence), not on the Power's own
// usage count -- so a permanent tag on the retrieved card instance itself (addPermanentTag,
// durationTags.ts), filtered out of future offers, rather than a per-game usage counter on Orwin.

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';
import { addPermanentTag } from '../durationTags.js';

const RECALLED_BY_ORWIN = 'recalledByOrwin';

registerCardEffect('Orwin', {
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => !card.tags.has(RECALLED_BY_ORWIN),
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Recall') return;
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    if (!card || card.tags.has(RECALLED_BY_ORWIN)) return;

    addPermanentTag(ctx.state, ctx.cardDb, card, RECALLED_BY_ORWIN);
    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'hand');
    ctx.state.skipDrawStepThisTurn = true;
  },
});
