// Ahron -- "Dust Cloud: Whenever one of your Creatures is attacked and defeated, you may discard
// two energy from Ahron. If you do, reduce the attacking Creature to one energy."
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice` -- the specific attacker
// is remembered via an embedded-id permanent tag (same technique as Reef Hyren/Skullek/Wellisk in
// this same batch, Dreamcatcher/Mirago/Venger's own precedent) since the resolve call has no
// target parameter of its own. Fizzles harmlessly if the attacker is no longer in play by the
// time the player answers (e.g. discarded by something else in between).

import { registerCardEffect } from './registry.js';
import { discardEnergy, restoreEnergy } from '../effects.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { findInPlayById } from '../targeting.js';

const PENDING_PREFIX = 'ahronDustCloudPending:';

function pendingAttackerId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return tag.slice(PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Ahron', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat) -- Ahron has one named printed Effect,
  // Dust Cloud, whose hooks span three fields; a Taglat-copied 'Dust Cloud' fires all three on
  // Taglat, nothing else. Wired here as the plan's live-UI verification scenario (Gremm's Helmet
  // and Taglat both).
  effectHooks: {
    'Dust Cloud': ['afterCombat', 'pendingYesNoChoice', 'resolveYesNoChoice'],
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.defender === null || ctx.defender.controllerId !== self.controllerId) return;
    if (outcome.defenderSurvived) return;
    if ((self.currentEnergy ?? 0) < 2) return;
    addPermanentTag(ctx.state, ctx.cardDb, self, `${PENDING_PREFIX}${ctx.attacker.instanceId}`);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (pendingAttackerId(self) === undefined) return undefined;
    if ((self.currentEnergy ?? 0) < 2) return undefined;
    return {
      prompt: "Ahron's Dust Cloud: discard two energy from Ahron to reduce the attacking Creature to one energy?",
      yesLabel: 'Discard 2, reduce attacker to 1',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const attackerId = pendingAttackerId(self);
    if (attackerId !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${attackerId}`);
    if (!chosenBoolean || attackerId === undefined) return;
    if ((self.currentEnergy ?? 0) < 2) return;
    const attacker = findInPlayById(state, attackerId);
    if (!attacker) return;
    discardEnergy(state, cardDb, self, 2, 'effect', undefined, rng);
    restoreEnergy(state, cardDb, attacker, 1);
  },
});
