// Ormagon -- "Devastate: Discard all non-Underneath Creatures from play." No target, no
// self-discard -- Ormagon is itself Underneath, so it survives its own sweep.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Ormagon', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Devastate') return;
    const targets = allCreaturesInPlay(ctx.state, ctx.cardDb).filter(
      (c) => !effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, 'Underneath'))
    );
    for (const creature of targets) {
      const owner = ctx.state.players.get(creature.controllerId);
      if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, creature.instanceId, undefined, undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Underneath'],
});
