// Mushroom Hyren -- "Sanctuary (1): Choose any one of your Creatures in play. Return the chosen
// Creature to its owner's hand. Add energy to your Magi equal to the Creature's printed starting
// energy or current energy, whichever is less." Same shape as Alaban Gloves/Gruk, restricted to
// own Creatures only. The printed-starting-energy cap is an official 2i Design errata
// (data-pipeline/output/rulings.json, applied 2026-07-09) -- previously this moved the Creature's
// full CURRENT energy uncapped. Capture-then-return-then-add, NOT rearrangeEnergy -- see Alaban
// Gloves' comment for why (avoids the automatic zero-energy defeat check firing on the creature
// while it's still nominally in play).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById, printedStartingEnergy } from '../targeting.js';
import { addEnergy, returnToHand } from '../effects.js';

registerCardEffect('Mushroom Hyren', {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Sanctuary') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;

    const amount = Math.min(target.currentEnergy ?? 0, printedStartingEnergy(ctx.cardDb, target.definitionKey));
    returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId);
    if (amount > 0) addEnergy(ctx.state, ctx.cardDb, magi, amount, 'power');
  },
});
