// Focus (Universal Spell, cost 3) -- "During your next turn, this Magi's energize rate is tripled.
// You cannot play any cards until the end of your next turn."
//
// Weave + Universal Spell pass, Category B (2026-07-27). Same `spellStaysInPlay` + self-discard
// shape as Weave Winds (see that file's header for why a lingering effect cannot live in the
// discard pile), with the target turn recorded on a dynamically-keyed tag so both clauses agree
// about which turn "your next turn" is.
//
// TRIPLED, on the PRINTED rate. `energizeRateModifier` is additive by contract -- every other
// implementer returns a delta -- so tripling is expressed as `+2 x printed`. That deliberately does
// NOT compound with other modifiers: a Magi with printed 5 and a Collar of Despair (-1) energizes
// 5 + 10 - 1 = 14, not (5-1) x 3 = 12. Reading "tripled" against the printed rate is the
// interpretation consistent with how `printedStartingEnergy` and the rest of this codebase treat
// "its rate"; if a judge ruling ever says otherwise, this is the one line to change.
//
// THE DRAWBACK IS THE LONGER HALF. "Until the END of your next turn" outlasts the energize bonus,
// which applies only DURING that turn -- so the Spell must survive to the end of that turn and the
// two clauses cannot share one expiry check. The play-lock is simply "while this card is in play";
// the energize bonus additionally requires the turn number to match.
//
// The lock covers ALL card types including Spells and Relics ("any cards"), and applies only to the
// caster -- `preventsPlayOf` receives the attempting player, so scoping it to `self.controllerId`
// is what makes this a self-inflicted drawback rather than a global lockdown (Tuku's Restrain is
// the deliberately-global counterexample).

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { addPermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';

const TURN_PREFIX = 'focusBoostedTurn:';

function boostedTurn(self: CardInstance): number | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(TURN_PREFIX)) return Number(tag.slice(TURN_PREFIX.length));
  }
  return undefined;
}

registerCardEffect('Focus', {
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    // state.turnNumber + players = this player's next turn (nextOwnTurnNumber's own definition),
    // recorded now so both clauses below reference the same turn.
    const next = ctx.state.turnNumber + ctx.state.turnOrder.length;
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${TURN_PREFIX}${next}`);
    // Required -- see weaveWinds.ts for the full explanation. `spellStaysInPlay` suppresses the
    // auto-discard but places nothing; a Spell with no attach host must add itself to inPlay or it
    // vanishes into no zone.
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  energizeRateModifier: (state, cardDb, energizing, self) => {
    if (energizing.instanceId !== state.players.get(self.controllerId)?.activeMagi?.instanceId) return 0;
    if (state.turnNumber !== boostedTurn(self)) return 0;
    const printed = cardDb.get(energizing.definitionKey)?.energize ?? 0;
    return printed * 2; // printed x3 total
  },
  preventsPlayOf: (_state, _cardDb, _playedDef, playerId, self) => playerId === self.controllerId,
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    // Fires at the end of EVERY own turn while in play; only the boosted one ends it. The turn it
    // was played ends first and must NOT discard it -- that turn is strictly before `boostedTurn`.
    if (state.turnNumber !== boostedTurn(self)) return;
    const owner = state.players.get(self.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, self.instanceId, undefined, 'effect', rng);
  },
});
