// Crushing Roots (Spell, cost 4) -- "Choose any one Creature in play. Discard four energy from the
// chosen Creature. If this discards the chosen Creature from play, choose any one of your
// Creatures in play. Add three energy to that Creature. Only Naroom Magi and Naroom Shadow Magi
// can play Crushing Roots." Naroom Spell pass, Category B (2026-07-23). "Only Naroom Magi..." is
// already fully data-driven (region_restrictive: true in cards_final.json) -- no code needed.
// The "discard 4; if it dies, do X" half is crushingStench.ts's exact structure
// (discardEnergy -> checkCreatureDefeats -> re-check findInPlayById); the conditional follow-up
// pick reuses the post-hoc pendingTargetChoice/resolveTargetChoice family (spark.ts precedent)
// since it's only offered SOMETIMES (when the discard actually defeats the target), not a
// mandatory spellSecondTargets pick collected up front.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const CRUSHING_ROOTS_PENDING = 'crushingRootsPending';

registerCardEffect('Crushing Roots', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);
    checkCreatureDefeats(ctx.state, ctx.cardDb, 'spell', undefined, ctx.rng);
    const stillThere = findInPlayById(ctx.state, target.instanceId);
    if (stillThere) return; // wasn't discarded from play -- no follow-up

    if (creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).length > 0) {
      addPendingChoiceTag(ctx.source, CRUSHING_ROOTS_PENDING);
    }
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(CRUSHING_ROOTS_PENDING)) return undefined;
    const pool = creaturesControlledBy(state, cardDb, self.controllerId);
    if (pool.length === 0) return undefined;
    return { prompt: 'Crushing Roots: choose one of your Creatures to add three energy to', pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, CRUSHING_ROOTS_PENDING);
    if (!chosenInstanceId) return;
    const target = creaturesControlledBy(state, cardDb, self.controllerId).find((c) => c.instanceId === chosenInstanceId);
    if (target) addEnergy(state, cardDb, target, 3, 'spell');
  },
});
