// Aurorea -- "Mistress of Frost: If Aurorea is frozen, increase her energize by two."

import { registerCardEffect } from './registry.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Aurorea', {
  energizeRateModifier: (state, cardDb, energizing, self) => {
    if (energizing.instanceId !== self.instanceId) return 0;
    return isFrozen(state, cardDb, self) ? 2 : 0;
  },
});
