// Sand Strands -- "Mirage: Discard Sand Strands from play. Choose any one of your non-Illusionary
// Creatures in play. Add energy to your Magi equal to half of the chosen Creature's current
// energy, rounded up. The amount added cannot exceed half of the chosen Creature's printed
// starting energy, rounded up. As long as the chosen Creature remains in play, it is Illusionary;
// Illusionary Creatures do not count as being in play when checking to see if your Magi is
// defeated. Illusionary Creatures cannot choose to attack Magi." Grants ILLUSION permanently (via
// durationTags.ts's addPermanentTag), unlike Olum Fiend's turn-limited version of the same tag.
// The printed-starting-energy cap is an official 2i Design errata (data-pipeline/output/
// rulings.json, applied 2026-07-09) -- previously this was uncapped against current energy alone.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById, printedStartingEnergy } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { addPermanentTag, isIllusion, ILLUSION } from '../durationTags.js';

registerCardEffect('Sand Strands', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId).filter((c) => !isIllusion(c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mirage') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (isIllusion(target)) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    if (ctx.controllingPlayer.activeMagi) {
      const fromCurrent = Math.ceil((target.currentEnergy ?? 0) / 2);
      const cap = Math.ceil(printedStartingEnergy(ctx.cardDb, target.definitionKey) / 2);
      addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, Math.min(fromCurrent, cap), 'power');
    }
    addPermanentTag(ctx.state, ctx.cardDb, target, ILLUSION);
  },
});
