// Shimmering Orshaa -- "Illusion Twist (4): Choose one of your other illusions in play. Discard
// the chosen illusion. Play a d'Resh Creature from your hand, ignoring all costs. The played
// Creature cannot attack this turn." First user of registry.ts's handPlayChoice.
//
// "As you play Shimmering Orshaa, reduce its cost by four. Shimmering Orshaa is not considered to
// be in play when checking to see if your Magi is defeated, and it cannot attack Magi directly." --
// post-playtest correctness pass, P1 (2026-07-12), via the shared illusionCreature.ts helper.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay, playFromZone } from '../effects.js';
import { isIllusion, addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { applyIllusionEntry } from './illusionCreature.js';

registerCardEffect('Shimmering Orshaa', {
  selfCostAdjustment: () => -4,
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) applyIllusionEntry(state, cardDb, self);
  },
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => isIllusion(c) && c.instanceId !== sourceInstanceId),
  handPlayChoice: {
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes("d'Resh");
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Illusion Twist') return;
    if (ctx.chosenTargetId === undefined) return;
    const illusion = ctx.controllingPlayer.inPlay.find(
      (c) => c.instanceId === ctx.chosenTargetId && isIllusion(c) && c.instanceId !== ctx.source.instanceId
    );
    if (!illusion) return;
    if (!ctx.chosenHandPlayId) return;
    const handCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    const def = handCard ? ctx.cardDb.get(handCard.definitionKey) : undefined;
    if (!def || def.card_type !== 'Creature' || !def.regions.includes("d'Resh")) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, illusion.instanceId, undefined, undefined, ctx.rng);
    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: ctx.chosenHandPlayId },
      ctx.controllingPlayer,
      effectiveStartingEnergy(ctx.state, ctx.cardDb, handCard!)
    , ctx.rng);
    if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
  },
});
