// Ground Breaker (Spell, Underneath, cost 3) -- "Roll one die. Choose any one Magi in play.
// Discard energy equal to the die roll from the chosen Magi."
//
// The target is collected UP FRONT by the UI (spellTargets), the way every other targeted Spell
// works, and the die is rolled at resolution -- the printed order ("roll, then choose") is
// deliberately not modelled as a two-step prompt, matching every other die-roll card in the
// codebase.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { allMagiInPlay } from '../targeting.js';

registerCardEffect('Ground Breaker', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!target) return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.controllingPlayer.playerId,
      6,
      'groundBreaker:resolve',
      { chosenTargetId: ctx.chosenTargetId, controllingPlayerId: ctx.controllingPlayer.playerId },
      ctx.rng
    );
  },
});

registerRollConsumer('groundBreaker:resolve', (state, cardDb, _source, payload, finalRoll, rng) => {
  const { chosenTargetId, controllingPlayerId } = payload as { chosenTargetId: string; controllingPlayerId: string };
  const target = allMagiInPlay(state).find((m) => m.instanceId === chosenTargetId);
  if (!target) return;
  discardEnergy(state, cardDb, target, finalRoll, 'spell', controllingPlayerId, rng);
});
