// Ugger -- "Borrow: Whenever Ugger attacks, you may move any amount of energy from one of your
// other Creatures to Ugger before energy is removed." Same pendingPreCombatTargetChoice/
// onBeforeEnergyRemoved shape as Scout Bungaloo's Flee (scoutBungaloo.ts), but this is the first
// card whose choice needs an AMOUNT alongside the target -- PreCombatTargetResolution's `amount`
// field (task #35, 2026-07-16) exists for exactly this. No safe auto-pick default for an
// arbitrary amount (unlike Scout Bungaloo's fixed "move everything"), so an unresolved choice is
// a no-op skip rather than guessing a value -- same conservative default already used wherever
// this codebase has no rational auto-pick for a genuinely free numeric choice.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import type { PreCombatTargetResolution } from '../combat.js';

function donorPool(state: Parameters<typeof creaturesControlledBy>[0], cardDb: Parameters<typeof creaturesControlledBy>[1], self: { instanceId: string; controllerId: string }) {
  return creaturesControlledBy(state, cardDb, self.controllerId).filter(
    (c) => c.instanceId !== self.instanceId && (c.currentEnergy ?? 0) > 0
  );
}

registerCardEffect('Ugger', {
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker) => {
    if (!isAttacker) return undefined;
    const pool = donorPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Ugger's Borrow: choose a Creature to move energy from (and how much)", pool };
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
    const resolution = resolutions?.[self.instanceId];
    if (!resolution || 'skip' in resolution) return;
    const pool = donorPool(ctx.state, ctx.cardDb, self);
    const donor = pool.find((c) => c.instanceId === resolution.chosenInstanceId);
    if (!donor || !resolution.amount || resolution.amount <= 0) return;
    rearrangeEnergy(ctx.state, ctx.cardDb, donor, self, resolution.amount, ctx.rng);
  },
});
