// Tuk Berries -- "Nourish (1): Use this Power only before your Attack Step. Choose any one Weave
// Creature in play. Add two energy to the chosen Creature. That Creature cannot attack this
// turn." Reuses the existing CANNOT_ATTACK tag (built for Firefly Amulet), but with a THIS-turn
// expiry instead of Firefly Amulet's "next turn" -- both are just different expiresAfterTurnNumber
// values passed to the same addDurationTag call.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Tuk Berries', {
  legalPhases: ['prs1'],
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Weave'))),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Nourish') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Weave'))) return;

    addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Weave'],
});
