// Firefly Amulet -- "Swarm: Choose any one Creature in play. Discard a Cald card from your hand
// to remove two energy from the chosen Creature. If the discarded card was a Spell, that
// Creature cannot attack on its player's next turn." First card using durationTags.ts's
// CANNOT_ATTACK tag.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, regionForTargetFilter } from '../targeting.js';
import { discardEnergy, discardFromHand } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK, nextTurnNumberFor } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Firefly Amulet', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(state, 'Cald')) ?? false,
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Swarm') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandCardIds![0]);
    if (!discardedCard || !ctx.cardDb.get(discardedCard.definitionKey)?.regions.includes(regionForTargetFilter(ctx.state, 'Cald'))) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;

    const wasSpell = ctx.cardDb.get(discardedCard.definitionKey)?.card_type === 'Spell';
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    discardEnergy(ctx.state, ctx.cardDb, target, 2, undefined, undefined, ctx.rng);
    if (wasSpell) {
      addRestrictionTag(ctx.state, target, CANNOT_ATTACK, nextTurnNumberFor(ctx.state, target.controllerId));
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Cald'],
});
