// Snag Hyren -- "Stumble (3): Until the beginning of your next turn, opposing Creatures remove
// two less energy in attacks." No target -- tags the controlling player's own Magi with STUMBLE,
// which combat.ts checks generically against whichever player is DEFENDING in any given attack.

import { registerCardEffect } from './registry.js';
import { addDurationTag, STUMBLE, beginningOfNextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Snag Hyren', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Stumble') return;
    if (!ctx.controllingPlayer.activeMagi) return;
    // 4th arg (2026-07-27): attributes the tag to Snag Hyren so Cawh's/Tunnel Parmalag's
    // anti-protection can strip it -- without it the tag is unsourced and fails closed.
    addDurationTag(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, STUMBLE, beginningOfNextOwnTurnNumber(ctx.state), ctx.source.instanceId);
  },
});
