// Ice Arboll -- "Ice Pack: If Ice Arboll is frozen, discard it to add two energy to each of your
// Creatures."

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Ice Arboll', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Ice Pack') return;
    if (!isFrozen(ctx.state, ctx.cardDb, ctx.source)) return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      addEnergy(ctx.state, ctx.cardDb, creature, 2, 'power');
    }
  },
});
