// Artyva -- "Healer's Aura: At the end of your turn, choose any one Creature in play with less
// than its starting energy. Add two energy to the chosen Creature."
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first eligible in array order" (own
// side first) simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, opposingCreatures, effectiveStartingEnergy } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

const HEALERS_AURA_PENDING = 'artyvaHealersAuraPending';

function belowStartingEnergy(state: GameState, cardDb: CardDatabase, c: CardInstance): boolean {
  return (c.currentEnergy ?? 0) < effectiveStartingEnergy(state, cardDb, c);
}

function healersAuraPool(state: Parameters<typeof creaturesControlledBy>[0], cardDb: Parameters<typeof creaturesControlledBy>[1], self: { controllerId: string }) {
  return [
    ...creaturesControlledBy(state, cardDb, self.controllerId).filter((c) => belowStartingEnergy(state, cardDb, c)),
    ...opposingCreatures(state, cardDb, self.controllerId).filter((c) => belowStartingEnergy(state, cardDb, c)),
  ];
}

registerCardEffect('Artyva', {
  onOwnTurnEnd: (state, cardDb, self) => {
    if (healersAuraPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, HEALERS_AURA_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(HEALERS_AURA_PENDING)) return undefined;
    const pool = healersAuraPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Artyva's Healer's Aura: choose a Creature with less than its starting energy to add 2 energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, HEALERS_AURA_PENDING);
    if (!chosenInstanceId) return;
    const target = healersAuraPool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
    if (target) addEnergy(state, cardDb, target, 2, 'effect');
  },
});
