// Flame Hyren -- "Energy Transfer: Distribute Flame Hyren's energy among any number of Creatures.
// Discard Flame Hyren from play." No "your Creatures" qualifier -- widened to any Creature in play
// (either side).
//
// Real choice (task #40-2, 2026-07-17, player-choice-default retrofit, Group 2, de-escalated from
// a "Hard Case" after the project owner pointed out the actual flow is simpler than first scoped:
// snapshot Flame Hyren's energy (X), then a sequential "pick a Creature, assign some amount, repeat
// until the pool is exhausted" loop). No free-form per-target amount input exists anywhere in this
// engine's `powerTargetSlots`, so this reuses that same mechanism in UNARY: one slot per energy
// unit in X (each `min: 0, max: 1` so a unit can be left undistributed), pool is every Creature in
// play except Flame Hyren itself -- a Creature can appear in more than one slot's answer (different
// slots are independent, `allowRepeats` only governs picks WITHIN one slot), so this produces
// exactly the same "distribute X freely, any split" result as a true amount input would, with zero
// new engine/UI plumbing. `powerTargetSlots` already receives `sourceInstanceId`, so X is read
// directly off Flame Hyren's own live `currentEnergy` at slot-build time.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

function distributionPool(state: GameState, cardDb: CardDatabase, sourceInstanceId: string) {
  return allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== sourceInstanceId);
}

registerCardEffect('Flame Hyren', {
  powerTargetSlots: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    if (powerName !== 'Energy Transfer') return [];
    const player = state.players.get(playerId)!;
    const source = [...player.inPlay].find((c) => c.instanceId === sourceInstanceId);
    const total = source?.currentEnergy ?? 0;
    return Array.from({ length: total }, (_, i) => ({
      label: `Assign one energy (${i + 1} of ${total}) to a Creature, or leave it unassigned`,
      pool: (s: GameState, db: CardDatabase) => distributionPool(s, db, sourceInstanceId),
      min: 0,
      max: 1,
    }));
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Energy Transfer') return;

    const pool = distributionPool(ctx.state, ctx.cardDb, ctx.source.instanceId);
    const counts = new Map<string, number>();
    for (const slot of ctx.chosenSlotIds ?? []) {
      const id = slot[0];
      if (!id) continue;
      if (!pool.some((c) => c.instanceId === id)) continue;
      counts.set(id, (counts.get(id) ?? 0) + 1);
    }
    for (const [id, amount] of counts) {
      const target = pool.find((c) => c.instanceId === id);
      if (target) addEnergy(ctx.state, ctx.cardDb, target, amount, 'power');
    }
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
  },
});
