// Entangle (Spell, Orothe, cost 3) -- "Choose any one Magi in play. The chosen Magi cannot play any
// spells during his or her next turn." New PlayerState.spellPlayLockedUntilTurn field (types/state.ts),
// same "locked until turn N" shape as the existing handPlayLockedUntilTurn (Spirit of Nar), just
// narrowed to Spell plays only -- checked generically in play.ts#isLegalToPlay. The lock lives on the
// TARGETED player, not necessarily this caster, so the expiry uses nextTurnNumberFor(state, targetId)
// rather than nextOwnTurnNumber(state).

import { registerCardEffect } from './registry.js';
import { allMagiInPlay } from '../targeting.js';
import { nextTurnNumberFor } from '../durationTags.js';

registerCardEffect('Entangle', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const target = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!target) return;
    const owner = ctx.state.players.get(target.controllerId);
    if (!owner) return;
    owner.spellPlayLockedUntilTurn = nextTurnNumberFor(ctx.state, target.controllerId);
  },
});
