// Nodj -- "Restore: At the beginning of your turn, if Nodj has less than its starting energy,
// restore it to its starting energy."

import { registerCardEffect } from './registry.js';
import { restoreEnergy } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';

registerCardEffect('Nodj', {
  onOwnTurnStart: (state, cardDb, self) => {
    const starting = effectiveStartingEnergy(state, cardDb, self);
    if ((self.currentEnergy ?? 0) >= starting) return;
    restoreEnergy(state, cardDb, self, starting);
  },
});
