// Roar (Spell) -- "Choose one of your Creatures in play. The next time the chosen Creature
// attacks, remove twice as much energy from the defending Creature." Kybar's Teeth Spell pass,
// Category B (2026-07-22). Identical payload to Moga/Moga Pup's "Roar" Power (roarPower.ts) --
// reuses the same ROAR_DOUBLE_NEXT_ATTACK duration tag and combat.ts consumption side, just
// applied via a Spell's spellTargets/resolveSpell instead of a Power's powerTargets/resolvePower.
// Only your OWN Creatures (unlike the Power version, which can target either side) -- printed text
// says "one of your Creatures."

import { registerCardEffect } from './registry.js';
import { addDurationTag } from '../durationTags.js';
import { ROAR_DOUBLE_NEXT_ATTACK } from '../durationTags.js';
import { creaturesControlledBy } from '../targeting.js';

registerCardEffect('Roar', {
  spellTargets: (state, cardDb, controllingPlayerId) => creaturesControlledBy(state, cardDb, controllingPlayerId),
  resolveSpell: (ctx) => {
    const target = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    if (!target) return;
    addDurationTag(ctx.state, ctx.cardDb, target, ROAR_DOUBLE_NEXT_ATTACK, ctx.state.turnNumber);
  },
});
