// Djarmander -- both printed clauses:
//   "Dreamdrain": "When an opposing Relic is discarded from play, add two energy to Djarmander."
//   Unnamed passive: "While Djarmander is in play, all Relics in play are frozen; Powers on
//   frozen cards cost one additional energy to use." Built via task #26's `grantsFrozenTo`
//   broadcast (2026-07-14) -- the "Powers cost +1" half is already generic (power.ts's
//   isLegalPowerUse), so registering the grant alone is enough for both clauses.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allRelicsInPlay } from '../targeting.js';

registerCardEffect('Djarmander', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Only Dreamdrain is mapped; the
  // unnamed Relic-freeze passive (grantsFrozenTo) has no name to key on and falls through
  // to whole-card grant.
  effectHooks: {
    Dreamdrain: ['onCardDiscardedFromPlay'],
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discardedOwnerId === self.controllerId) return;
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Relic') return;

    addEnergy(state, cardDb, self, 2, 'effect');
  },
  grantsFrozenTo: (state, cardDb, self, target) =>
    allRelicsInPlay(state, cardDb).some((c) => c.instanceId === target.instanceId),
});
