// Ice Vinoc -- "Once per turn, as an opposing Frozen Creature attacks, move one energy from that
// Creature to Ice Vinoc." A third-party reactor (Ice Vinoc doesn't need to be part of the combat).

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { isFrozen } from '../durationTags.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const USED_THIS_TURN = 'iceVinocUsedThisTurn';

registerCardEffect('Ice Vinoc', {
  // Steals from the attacker's own real energy during the attack step, corrected 2026-07-11 to
  // run in onBeforeEnergyRemoved so the reduced amount is what the attacker actually deals this
  // same attack, not just a separate after-the-fact theft.
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.controllerId === self.controllerId) return; // "an OPPOSING Frozen Creature"
    if (!isFrozen(ctx.state, ctx.cardDb, ctx.attacker)) return;
    if (hasDurationTag(self, USED_THIS_TURN)) return;
    rearrangeEnergy(ctx.state, ctx.cardDb, ctx.attacker, self, 1, ctx.rng);
    addDurationTag(ctx.state, ctx.cardDb, self, USED_THIS_TURN, ctx.state.turnNumber);
  },
});
