// Ice Hyren -- "Shared Strength: If your Magi's Energize is greater than each opposing Magi's, Ice
// Hyren gains ENERGIZE: 1." A self-conditional flat rate GRANT (energizing must be Ice Hyren
// itself), unlike Water of Life/Ruid's genuinely-additive "grant to a DIFFERENT card" shape.
// Combines via MAX against Ice Hyren's own printed rate and any other grant on it, not SUM --
// 2026-08-05 rules-correctness fix, see registry.ts's energizeRateGrant doc comment.
//
// Compares the fully-computed effectiveEnergizeRate (turn.ts) for both Magi, not printed
// def.energize -- fixed 2026-08-11 (post-audit bug-fix follow-up). The earlier printed-rate
// simplification assumed this would recurse (effectiveEnergizeRate calls every in-play card's
// energizeRateGrant hook, including this one) -- re-examined and confirmed SAFE: Ice Hyren's own
// grant only ever targets ITSELF (`energizing.instanceId !== self.instanceId` guard below), never
// either Magi, so a nested effectiveEnergizeRate(magi) call can never re-enter this hook's real
// comparison logic -- it only reaches the guard, which returns 0 immediately for a Magi target.
// The only way this hook's comparison logic runs at all is when effectiveEnergizeRate is called on
// ICE HYREN ITSELF (its own normal per-turn Energize resolution) -- at that single entry point,
// calling effectiveEnergizeRate on a DIFFERENT instance (either Magi) is a one-level-deep,
// non-recursive read.
// "Ravage: When Ice Hyren attacks and defeats a Creature, choose an opposing Relic. Discard the
// chosen Relic." Built task #43, 2026-07-18, the Nar region pass -- Category B. `afterCombat`
// (only fires when the defender was actually defeated) + pendingTargetChoice/resolveTargetChoice,
// same shape as a dozen other after-combat-choice cards this project.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { discardFromPlay } from '../effects.js';
import { effectiveEnergizeRate } from '../turn.js';

const RAVAGE_PENDING = 'iceHyrenRavagePending';

registerCardEffect('Ice Hyren', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Shared Strength is the conditional
  // self-Energize-+1; Ravage is the attack-defeats-Creature choose-and-discard-a-Relic sequence.
  effectHooks: {
    'Shared Strength': ['energizeRateGrant'],
    Ravage: ['afterCombat', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  energizeRateGrant: (state, cardDb, energizing, self) => {
    if (energizing.instanceId !== self.instanceId) return 0;
    const owner = state.players.get(self.controllerId);
    const ownRate = owner?.activeMagi ? effectiveEnergizeRate(state, cardDb, owner.activeMagi) : 0;
    for (const p of state.players.values()) {
      if (p.playerId === self.controllerId) continue;
      const oppRate = p.activeMagi ? effectiveEnergizeRate(state, cardDb, p.activeMagi) : 0;
      if (ownRate <= oppRate) return 0;
    }
    return 1;
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null || outcome.defenderSurvived) return;
    const opponent = ctx.defendingPlayer;
    const hasRelic = opponent.inPlay.some((c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Relic');
    if (!hasRelic) return;
    addPendingChoiceTag(self, RAVAGE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(RAVAGE_PENDING)) return undefined;
    const opponents = [...state.players.values()].filter((p) => p.playerId !== self.controllerId);
    const pool = opponents.flatMap((p) => p.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic'));
    if (pool.length === 0) return undefined;
    return { prompt: "Ice Hyren's Ravage: choose an opposing Relic to discard", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, RAVAGE_PENDING);
    if (!chosenInstanceId) return;
    for (const p of state.players.values()) {
      if (p.playerId === self.controllerId) continue;
      const target = p.inPlay.find((c) => c.instanceId === chosenInstanceId && cardDb.get(c.definitionKey)?.card_type === 'Relic');
      if (target) {
        discardFromPlay(state, cardDb, p, target.instanceId, undefined, undefined, rng);
        return;
      }
    }
  },
});
