// Climbing Gear -- "Higher Ground: Whenever you play a Kybar's Teeth Creature, add one energy to
// your Magi. If there's no larger Creature in play, add an additional energy to your Magi." Built
// task #42, 2026-07-17, the Kybar's Teeth region pass -- same onPlay broadcast as Climbing Staff's
// Higher Ground, plus a size comparison against every OTHER Creature in play (current energy, same
// convention as Bone Cragnoc's "largest Creature" check).
//
// "Catch: As an opposing Spell, Power, or Effect would affect only your Magi, you may discard
// Climbing Gear from play. If you do, that Spell, Power, or Effect does nothing." and its unnamed
// twin: "As an opposing Spell, Power, or Effect would affect only your hand, you may discard
// Climbing Gear from your hand. If you do, that Spell, Power, or Effect does nothing." Built task
// #44 follow-up, 2026-07-18 -- same reclassification out of the once-planned Checkpoint B as
// Climbing Staff (see that file's comment for the full story; both clauses are Checkpoint A's
// "react to WHO an already-resolving Power affects" timing, not Checkpoint B's before-target-
// collection one). Unlike Climbing Staff, Climbing Gear's two clauses are mutually exclusive by
// ZONE: "Catch" only works while Climbing Gear is in PLAY (the Magi-half), the unnamed clause only
// works while it's in HAND (the hand-half, using handOnlyNegation.ts's shared Power-name list,
// same as Climbing Staff's own hand condition) -- each `offersPowerNegation` branch is gated on
// self's own current zone matching its clause.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromHand, discardFromPlay } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { isHandOnlyNegationPower } from './handOnlyNegation.js';

registerCardEffect('Climbing Gear', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  // Per-Effect hook narrowing (deep-dive audit, 2026-08-13). Higher Ground is the KT-Creature-
  // play energy bonus; Catch is the in-play Magi-only Power negation. The unnamed hand-half
  // twin shares offersPowerNegation/resolvePowerNegation with Catch (self-vs-zone gating
  // keeps the wrong branch dormant under a narrowed grant); Catch lists both.
  effectHooks: {
    'Higher Ground': ['onPlay'],
    Catch: ['offersPowerNegation', 'resolvePowerNegation'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Creature' || !def.regions.includes("Kybar's Teeth")) return;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi) return;
    addEnergy(state, cardDb, magi, 1, 'effect');
    const playedEnergy = played.currentEnergy ?? 0;
    const hasLarger = allCreaturesInPlay(state, cardDb).some(
      (c) => c.instanceId !== played.instanceId && (c.currentEnergy ?? 0) > playedEnergy
    );
    if (!hasLarger) addEnergy(state, cardDb, magi, 1, 'effect');
  },
  offersPowerNegation: (state, cardDb, self, user, powerName, currentTargetId) => {
    if (user.controllerId === self.controllerId) return false; // "an OPPOSING Spell, Power, or Effect"
    const owner = state.players.get(self.controllerId);
    if (!owner) return false;
    const targetsMyMagi = !!owner.activeMagi && currentTargetId === owner.activeMagi.instanceId;
    const inPlay = owner.inPlay.some((c) => c.instanceId === self.instanceId);
    if (targetsMyMagi && inPlay) return true; // "Catch" -- Magi-half, requires being in play

    const targetsMyHandOnly = isHandOnlyNegationPower(powerName) && (currentTargetId === undefined || targetsMyMagi);
    const inHand = owner.hand.some((c) => c.instanceId === self.instanceId);
    return targetsMyHandOnly && inHand; // unnamed -- hand-half, requires being in hand
  },
  resolvePowerNegation: (state, cardDb, self, negatedSource, negatedPowerName, currentTargetId, rng) => {
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    if (isHandOnlyNegationPower(negatedPowerName) && owner.hand.some((c) => c.instanceId === self.instanceId)) {
      discardFromHand(state, cardDb, owner, [self.instanceId]);
    } else if (owner.inPlay.some((c) => c.instanceId === self.instanceId)) {
      discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    }
  },
});
