// Qwade -- "Leech (X+4): Choose any two Creatures in play. Discard X energy from one of the
// chosen Creatures. Add X energy to the other chosen Creature." First real "X+N" printed cost
// (power.ts's isVariableCostPower/resolveVariableCost) -- X is the SAME value the player already
// chose to pay the +4 energy cost, reused here for the effect text. Single slot, exactly two
// picks from one pool; order determines role (first picked loses energy, second gains) since the
// card text doesn't otherwise specify which of the two is which.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Qwade', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- the pool can't know in
  // advance which of the two picks will end up "first" (loser, discard-covered) vs "second"
  // (gainer, add, not covered), so it offers a Magi for both positions; resolvePower below is the
  // final authority and only accepts a Magi in the loser position, same "pool is a hint, resolve
  // validates" pattern as Emaya.
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose two Creatures in play (first loses energy, second gains it)',
      pool: (s, db, pid) => flexibleTargetPool(s, db, pid, allCreaturesInPlay(s, db), allMagiInPlay(s)),
      min: 2,
      max: 2,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Leech') return;
    if (ctx.chosenXValue === undefined || ctx.chosenXValue < 0) return;
    const chosen = ctx.chosenSlotIds?.[0];
    if (!chosen || chosen.length !== 2 || chosen[0] === chosen[1]) return;

    const loser = findCreatureOrMagiById(ctx.state, chosen[0]!);
    const gainer = findCreatureOrMagiById(ctx.state, chosen[1]!);
    // task #34, 2026-07-16: loser (discard) may be a Magi given Dreamburn; gainer (add) stays
    // Creature-only, Dreamburn doesn't cover it.
    if (!loser || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, loser, 'Creature')) return;
    if (!gainer || ctx.cardDb.get(gainer.definitionKey)?.card_type !== 'Creature') return;

    discardEnergy(ctx.state, ctx.cardDb, loser, ctx.chosenXValue, undefined, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, gainer, ctx.chosenXValue, 'power');
  },
});
