// Gia's Tome -- "Research: Once per turn, you may play a Creature from under Gia's Tome as if it
// were in your hand. If your Magi is Gia, Creatures played from Gia's Tome cost one less energy
// to play, to a minimum of one." "Record: Each time a Creature that you own is defeated in an
// attack, you may place it under Gia's Tome instead of the discard pile. If Gia's Tome is
// discarded from play, discard all cards under it."
//
// BUG FIXED 2026-08-11 (post-audit deferred-gap closure pass): the Gia discount used to check raw
// `magiDef.name === 'Gia'`, missing Empress Gia -- her own name is "Empress Gia", with db
// `alternate: "Nagsis, Gia"` (a comma-separated dual-alternate list, split by `magiIdentityNames`
// into "Nagsis" and "Gia" separately), so only the alias lookup catches her. Now
// `magiCountsAs(cardDb, magi, 'Gia')`.
//
// Research is described only in `effects[]`, not the card database's own `powers[]` -- the first
// card needing registry.ts's new syntheticPowers (2026-07-11). Re-derives play.ts's own
// region/cost legality inline, same "playCard itself is hand-only, can't be called directly"
// situation as Warrior's Boots -- doesn't replicate play.ts's onPlay broadcast either, matching
// that same precedent (playFromZone doesn't fire onPlay).
//
// Record's "each time... defeated in an attack" maps to registry.ts's offersAttachRedirect with
// cause 'zero-energy' + source 'combat' (any combat defeat, attacking or defending -- unlike
// Nyrex's Catch, which is defending-only).

import { registerCardEffect } from './registry.js';
import { detachCard, discardAllAttached } from '../attachedCards.js';
import { checkRegionLegality, effectiveMagiDef } from '../regions.js';
import { checkCreatureDefeats } from '../energy.js';
import { spellPlayCostWithModifiers, resolveDreamwarpDelta, commitDreamwarpDelta } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { addToZone } from '../zones.js';
import { magiCountsAs } from './magiIdentity.js';

registerCardEffect("Gia's Tome", {
  // Per-Effect hook narrowing (deep-dive audit, 2026-08-13). Research is the synthetic Power
  // to play a Creature from under the Tome; Record is the on-defeat-in-combat attach redirect
  // plus the "discard all cards under it on self-discard" cleanup. holdsInertContents +
  // legalPhases fold under Record and Research respectively (same convention as Nyrex's
  // holdsInertContents under Catch: whichever Effect creates the attachment zone).
  effectHooks: {
    Research: ['syntheticPowers', 'powerTargets', 'powerPlaysCreatureAsIfFromHand', 'resolvePower', 'legalPhases'],
    Record: ['offersAttachRedirect', 'onCardDiscardedFromPlay', 'holdsInertContents'],
  },
  // Cards stored under this one are OUT of play, not markers riding on it -- see
  // registry.ts's `holdsInertContents`. Without this, every board-wide broadcast that
  // flattens `attachedCards` (to reach the marker family) also fires the abilities of
  // whatever is sitting inertly in here.
  holdsInertContents: true,
  // Research plays a Creature "as if it were in your hand," so it must obey normal Creature-play
  // timing -- only during the playNewCreatures step, not the default prs1/prs2 Powers step (task #49
  // playtest fix, 2026-07-19). Research is Gia's Tome's only Power, so this card-level gate is safe.
  legalPhases: ['playNewCreatures'],
  syntheticPowers: [
    {
      name: 'Research',
      cost: undefined,
      text:
        "Once per turn, you may play a Creature from under Gia's Tome as if it were in your hand. " +
        'If your Magi is Gia, Creatures played from Gia\'s Tome cost one less energy to play, to a minimum of one.',
    },
  ],
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    if (powerName !== 'Research') return undefined;
    const player = state.players.get(playerId);
    const self = player?.inPlay.find((c) => c.instanceId === sourceInstanceId);
    return self?.attachedCards.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature') ?? [];
  },
  // Task #577: tells the UI which Creature this use is about to play, so it can offer that
  // Creature's Dreamwarp. Depends on the CURRENT target pick, so Play.tsx re-asks as it changes.
  powerPlaysCreatureAsIfFromHand: (state, cardDb, playerId, self, powerName, chosenTargetId) => {
    if (powerName !== 'Research' || !chosenTargetId) return undefined;
    const chosen = self.attachedCards.find((c) => c.instanceId === chosenTargetId);
    return chosen && cardDb.get(chosen.definitionKey)?.card_type === 'Creature' ? chosen : undefined;
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Research') return;
    if (!ctx.chosenTargetId) return;
    const chosen = ctx.source.attachedCards.find((c) => c.instanceId === ctx.chosenTargetId);
    const def = chosen ? ctx.cardDb.get(chosen.definitionKey) : undefined;
    const magi = ctx.controllingPlayer.activeMagi;
    const magiDefRaw = magi ? ctx.cardDb.get(magi.definitionKey) : undefined;
    if (!chosen || !def || def.card_type !== 'Creature' || !magi || !magiDefRaw) return;
    if (typeof def.cost !== 'number') return; // X-cost Creatures have no chosenXValue plumbing here
    const magiDef = effectiveMagiDef(magiDefRaw, magi);

    const regionCheck = checkRegionLegality(magiDef, def);
    if (!regionCheck.legal) return;
    // BUG FIXED 2026-07-27 (owner playtest: "Playing from Gia's Tome does not appear to be seeing
    // cost reduction" -- Marella, Savant's Bliss should have made a cost-7 Junjertrug cost 5, and
    // the full 7 was charged). This re-derived the cost by hand and never consulted `costModifier`
    // at ALL, so every cost-modifying card in the game was invisible to Research: Marella both ways,
    // Void Stone, Jasker's Mask, Korremar, the Nar surcharge, all of them.
    //
    // docs/hook-reference.md §13 closes with "If a fourth route ever appears, call the shared
    // helper -- don't re-derive it." Research IS that fourth route; it was written before §13
    // existed and was never brought in line. Now priced through `spellPlayCostWithModifiers`, the
    // same helper playFromZone and castSpellFromOpponentZone use.
    //
    // ORDER matters and mirrors play.ts's isLegalToPlay exactly: card-specific base adjustment
    // first, then broadcast modifiers with their own minimum-of-one floor, THEN the regional
    // penalty on top (play.ts:1005-1026). Applying Gia's discount to the base before the helper is
    // the Maelstrom Flask precedent from §13 -- a card's own "costs one less" is a base adjustment,
    // not one of the modifiers being summed, so it does not double-apply.
    // Dreamwarp (task #577, owner ruling 2026-07-28: Research is "another way to play a creature,"
    // so it may be Dreamwarped). Applied to the PRINTED cost first, before Gia's own discount and
    // before the broadcast modifiers -- the same order play.ts uses, where the Dreamwarp delta folds
    // into baseCost and the starting-energy snapshot is taken immediately after it but BEFORE any
    // plain cost reduction. Doing it in this order is what keeps Gia's -1 out of starting energy.
    //
    // RESOLVED here but COMMITTED only after the affordability gate below -- an unaffordable pick
    // must cost nothing and must not leave a Dreamwarp stamped on a Creature that never got played.
    const dreamwarpDelta = resolveDreamwarpDelta(
      ctx.state,
      ctx.cardDb,
      ctx.controllingPlayer.playerId,
      chosen,
      def.cost,
      ctx.chosenDreamwarpAdjustment
    );
    const dreamwarpedCost = def.cost + dreamwarpDelta;
    const giaAdjustedBase = magiCountsAs(ctx.cardDb, magi, 'Gia') ? Math.max(1, dreamwarpedCost - 1) : dreamwarpedCost;
    const modifiedCost = spellPlayCostWithModifiers(ctx.state, ctx.cardDb, def, ctx.controllingPlayer.playerId, giaAdjustedBase);
    const totalCost = modifiedCost + regionCheck.regionalPenalty;
    if ((magi.currentEnergy ?? 0) < totalCost) return;

    const detached = detachCard(ctx.source, chosen.instanceId);
    if (!detached) return;
    // Stamped on the DETACHED instance (same object, but read after this point), so
    // effectiveStartingEnergy below sees the Dreamwarped stat.
    commitDreamwarpDelta(ctx.state, ctx.cardDb, detached, def.cost, dreamwarpDelta);
    magi.currentEnergy = (magi.currentEnergy ?? 0) - totalCost;
    // Starting energy is the PRINTED cost, never the discounted/modified one. Found in the same
    // pass: this used to assign the Gia-discounted figure, so under Gia a Creature entered play one
    // energy short. play.ts states the invariant directly -- starting energy is "NEVER" adjusted by
    // a cost-reduction/surcharge effect, which "only ever changes what's PAID". printedStartingEnergy
    // is the canonical reader (it also honours per-instance overrides, e.g. Slime Stone).
    detached.currentEnergy = effectiveStartingEnergy(ctx.state, ctx.cardDb, detached);
    addToZone(ctx.controllingPlayer, 'inPlay', detached);
    checkCreatureDefeats(ctx.state, ctx.cardDb, 'power', undefined, ctx.rng);
  },
  offersAttachRedirect: (state, cardDb, discarded, discardedOwnerId, self, cause, source) => {
    if (discardedOwnerId !== self.controllerId) return false;
    if (cause !== 'zero-energy' || source !== 'combat') return false;
    return cardDb.get(discarded.definitionKey)?.card_type === 'Creature';
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;
    discardAllAttached(state, cardDb, self);
  },
});
