// Prek -- two printed clauses:
//   "Kinship: Prek may play Kybar's Teeth cards, ignoring regional penalties and restrictions." --
//   regionOverride, same shape as Grej.
//   "Tech Savvy: All of your Relics cost one less to play. Your Relics' powers cost one less to
//   use." -- costModifier + powerCostModifier, both scoped to Relics.

import { registerCardEffect } from './registry.js';
import { magiCountsAs } from './magiIdentity.js';

registerCardEffect('Prek', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Kinship = the ignore-penalties
  // override on Prek's own Kybar's Teeth plays (`regionOverride`); Tech Savvy = the -1
  // discount on both playing Relics AND using Relic Powers.
  effectHooks: {
    Kinship: ['regionOverride'],
    'Tech Savvy': ['costModifier', 'powerCostModifier'],
  },
  regionOverride: (state, cardDb, playedDef, magi) =>
    magiCountsAs(cardDb, magi, 'Prek') && playedDef.regions.includes("Kybar's Teeth"),
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return playedDef.card_type === 'Relic' ? -1 : 0;
  },
  powerCostModifier: (state, cardDb, powerUserId, sourceDef, self) => {
    if (powerUserId !== self.controllerId) return 0;
    return sourceDef.card_type === 'Relic' ? -1 : 0;
  },
});
