// Leaf Chogo -- "Leaf Storm": "After Leaf Chogo attacks, you may discard it from play. If you do,
// add one energy to each of your Creatures. Discard one energy from each opposing Core Creature."
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice` -- no external reference
// needed (the effect is a board-wide broadcast re-derivable fresh at resolve time).
//
// "Resistance: Leaf Chogo is not affected by opposing Core Spells and Powers." Built (Spell-pass
// audit follow-up, 2026-07-23) via blocksPowerEffectBySourceRegion -- the same hook Chaos Flugg's
// own (structurally identical, but "opposing"-qualified) Resistance clause uses, and Chaos Flugg's
// own file comment confirms this hook was already correctly wired into effects.ts's
// discardEnergy/addEnergy, just never actually registered on Leaf Chogo. Unlike Chaos Flugg/Magor
// (no "opposing" qualifier), Leaf Chogo's own text IS scoped to opposing sources, so this checks
// `state.currentAction?.actorPlayerId` against `self.controllerId` too.
//
// Ashio's Weave Twist (2026-07-24): both "Core" references above are Leaf Chogo's OWN printed
// text, so under Ashio they mean Leaf Chogo's own region (Naroom) instead -- see targeting.ts's
// ashioAdjustedRegion doc comment for the general mechanism.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy, discardFromPlay } from '../effects.js';
import { ashioAdjustedRegion, creaturesControlledBy, effectiveRegions, opposingCreatures } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const AWAITING_CHOICE = 'leafChogoAwaitingChoice';

registerCardEffect('Leaf Chogo', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Leaf Storm spans the
  // afterCombat-triggered yes/no choice; Resistance blocks opposing Core Spells/Powers.
  effectHooks: {
    'Leaf Storm': ['afterCombat', 'pendingYesNoChoice', 'resolveYesNoChoice'],
    Resistance: ['blocksPowerEffectBySourceRegion'],
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    addPendingChoiceTag(self, AWAITING_CHOICE);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    return {
      prompt: "Leaf Chogo's Leaf Storm: discard Leaf Chogo to add 1 energy to each of your Creatures and discard 1 from each opposing Core Creature?",
      yesLabel: 'Discard Leaf Chogo',
      noLabel: 'Keep Leaf Chogo in play',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, AWAITING_CHOICE);
    if (!chosenBoolean) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    for (const creature of creaturesControlledBy(state, cardDb, self.controllerId)) {
      addEnergy(state, cardDb, creature, 1, 'effect');
    }
    for (const creature of opposingCreatures(state, cardDb, self.controllerId)) {
      if (effectiveRegions(state, cardDb, creature).includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Naroom']))) {
        discardEnergy(state, cardDb, creature, 1, 'effect', undefined, rng);
      }
    }
  },
  blocksPowerEffectBySourceRegion: (state, cardDb, self) => {
    if (state.currentAction?.actorPlayerId === self.controllerId) return false; // "opposing" only
    const sourceKey = state.currentAction?.sourceDefinitionKey;
    if (sourceKey === undefined) return false;
    const sourceDef = cardDb.get(sourceKey);
    return sourceDef?.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Naroom'])) ?? false;
  },
});
