// Evu's Jellybeans -- three printed pieces:
//   Top-level text: "When you play Evu's Jellybeans, add X Jellybean Counters to it. If Evu's
//   Jellybeans has no Jellybean Counters on it, discard it from play." (Plus "Naroom Shadow Magi
//   may play Evu's Jellybeans" -- already fully covered by the database's own shadow_play field,
//   same as Urhail, no code needed for that half.)
//   "Black Ones" Power: "Discard one Jellybean Counter from Evu's Jellybeans. Choose any one
//   player. That player chooses and discards one card from his or her hand. If your Magi is
//   Core, the discard is random. If your Magi is Evu, you do not need to discard a Jellybean
//   Counter to use this Power."
//   "Red Ones" Effect: "At the end of your turn, discard one Jellybean Counter from Evu's
//   Jellybeans and draw a card."
//
// Uses the new generic counters field (task #50f, 2026-07-12) under the 'jellybean' key, seeded
// from play.ts's auto-recorded 'startingX' (Relics have no currentEnergy to remember a chosen X
// the way a Creature does). "Choose any one player" has no real prompt at this trigger point --
// auto-picks the opponent (a hostile hand-discard effect targeting yourself would never be
// chosen), matching this codebase's established auto-pick convention; "that player chooses"
// their own card is likewise auto-picked (first in hand) unless the controller's Magi is Core
// (a REGION check, not a Magi-identity one), which forces a random discard instead.
//
// Ashio's Weave Twist (2026-07-24): "Core" above is Evu's Jellybeans' OWN printed text, so under
// Ashio it means its own region (Naroom) instead -- see targeting.ts's ashioAdjustedRegion doc
// comment.

import { registerCardEffect } from './registry.js';
import { discardFromHand, discardRandomFromHand, drawCards, getCounter, setCounter, spendCounter } from '../effects.js';
import { getOpponents } from '../types/state.js';
import { magiCountsAs } from './magiIdentity.js';
import { ashioAdjustedRegion } from '../targeting.js';

const JELLYBEAN = 'jellybean';

registerCardEffect("Evu's Jellybeans", {
  causesOpponentHandDiscard: true, // task #718 (Riptide clause 2, 2026-08-11)
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    setCounter(self, JELLYBEAN, getCounter(self, 'startingX'));
  },
  standingConditionMet: (state, cardDb, self) => getCounter(self, JELLYBEAN) <= 0,
  onOwnTurnEnd: (state, cardDb, self) => {
    if (!spendCounter(self, JELLYBEAN, 1)) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    drawCards(state, cardDb, owner, 1);
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Black Ones') return;
    const magi = ctx.controllingPlayer.activeMagi;
    const isEvu = magi ? magiCountsAs(ctx.cardDb, magi, 'Evu') : false;
    if (!isEvu && !spendCounter(ctx.source, JELLYBEAN, 1)) return;

    const [target] = getOpponents(ctx.state, ctx.controllingPlayer.playerId);
    if (!target || target.hand.length === 0) return;
    const magiDef = magi && ctx.cardDb.get(magi.definitionKey);
    const isCore = magiDef?.regions.includes(ashioAdjustedRegion(ctx.state, ctx.cardDb, 'Core', ['Naroom'])) ?? false;
    if (isCore) {
      discardRandomFromHand(ctx.state, ctx.cardDb, target, 1, ctx.rng);
    } else {
      discardFromHand(ctx.state, ctx.cardDb, target, [target.hand[0]!.instanceId], undefined, ctx.rng);
    }
  },
});
