// Korul -- "Icy Touch: Whenever Korul attacks, before energy is removed, discard energy from the
// defending Creature equal to the number of the defending player's Relics in play." A direct
// discardEnergy on the defender, not a ctx.locked adjustment -- distinct from the normal combat
// damage, applied on top of it.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allRelicsInPlay } from '../targeting.js';

registerCardEffect('Korul', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    const relicCount = allRelicsInPlay(ctx.state, ctx.cardDb).filter(
      (r) => r.controllerId === ctx.defendingPlayer.playerId
    ).length;
    if (relicCount > 0) discardEnergy(ctx.state, ctx.cardDb, ctx.defender, relicCount, 'effect', undefined, ctx.rng);
  },
});
