// Corf -- "Final Blow (3): Choose any one Creature in play that was attacked this turn. Discard
// the chosen Creature from play." "Was attacked" means it was the DEFENDER, not the attacker --
// tracked by the separate wasAttackedThisTurn field (added for this card; see combat.ts's
// declareAttack), distinct from attackedThisTurn (which means the opposite: this card attacked).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { getPlayer } from '../types/state.js';

registerCardEffect('Corf', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => c.wasAttackedThisTurn),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Final Blow') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!target.wasAttackedThisTurn) return; // re-validate at resolution time
    discardFromPlay(ctx.state, ctx.cardDb, getPlayer(ctx.state, target.controllerId), target.instanceId, undefined, undefined, ctx.rng);
  },
});
