// Chelon -- two Powers.
// "Shifting Tides (0): Choose an opponent. Look at the top two cards of that opponent's deck. You
// may discard one of these cards, or put them back on top of the deck in any order." Same
// deckTopReveal('target') shape as d'Rasha, but scoped to an OPPONENT specifically (opposingMagi,
// not allMagiInPlay), and at most ONE of the two may be discarded (not both, unlike Orothean
// Goggles). The unchosen card naturally stays on top in original order.
// "Wash Ashore (0): Search an opponent's discard pile for any one card that was discarded this
// turn. Play the chosen card, ignoring regional restrictions. Creatures played this way cannot
// attack this turn." "Discarded this turn" IS modeled (CardInstance.discardedOnTurn, stamped by
// zones.ts's moveToDiscardPile -- the single choke point every discard-entry path funnels
// through, including the automatic zero-energy defeat check) -- Wash Ashore's own
// discardPileSearch filter checks it.
//
// deckTopReveal (Shifting Tides) and discardPileSearch (Wash Ashore) are scoped to their OWN
// Power via the function-of-powerName form (registry.ts) -- Chelon is the first card whose two
// Powers need genuinely different shapes of these fields. Before this existed, BOTH fields applied
// to BOTH Powers unconditionally, so using Shifting Tides also (wrongly) prompted for a
// discard-pile search, and vice versa -- a real bug caught in playtesting (PROGRESS_LOG.md).

import { registerCardEffect } from './registry.js';
import { opposingMagi, findCreatureOrMagiById, effectiveStartingEnergy } from '../targeting.js';
import { discardFromDeck, playFromZone } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Chelon', {
  powerTargets: (state, cardDb, playerId) => opposingMagi(state, cardDb, playerId),
  deckTopReveal: (powerName) => (powerName === 'Shifting Tides' ? { count: 2, whoseDeck: 'target' } : undefined),
  discardPileSearch: (powerName) =>
    powerName === 'Wash Ashore'
      ? {
          count: 1,
          whoseDiscardPile: 'target' as const,
          filter: (state, cardDb, playerId, card) => card.discardedOnTurn === state.turnNumber,
        }
      : undefined,
  resolvePower: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const owner = ctx.state.players.get(chosenMagi.controllerId);
    if (!owner) return;

    if (ctx.powerName === 'Shifting Tides') {
      const ids = ctx.chosenDeckTopIds ?? [];
      if (ids.length > 1) return;
      if (ids.length === 0) return;
      const top = owner.deck.slice(0, 2).map((c) => c.instanceId);
      if (!top.includes(ids[0]!)) return;
      discardFromDeck(ctx.state, owner, ids);
    } else if (ctx.powerName === 'Wash Ashore') {
      const ids = ctx.chosenDiscardPileIds ?? [];
      if (ids.length !== 1) return;
      const [id] = ids;
      const card = owner.discardPile.find((c) => c.instanceId === id);
      if (!card || card.discardedOnTurn !== ctx.state.turnNumber) return;
      const startingEnergy = effectiveStartingEnergy(ctx.state, ctx.cardDb, card);
      const played = playFromZone(
        ctx.state,
        ctx.cardDb,
        { owner, zone: 'discardPile', instanceId: id! },
        ctx.controllingPlayer,
        startingEnergy
      , ctx.rng);
      if (played && ctx.cardDb.get(played.definitionKey)?.card_type === 'Creature') {
        addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
      }
    }
  },
});
