// Strag's Claws -- "Offense: Whenever one of your Creatures attacks an opposing Creature, add one
// energy to it before energy is removed and add one energy to it after energy is removed." Two
// real energy adds, split across the two hook timings.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect("Strag's Claws", {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (!ctx.defender) return; // "an opposing Creature" -- not a direct Magi attack
    addEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect');
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (!ctx.defender) return;
    if (!outcome.attackerSurvived) return;
    addEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect');
  },
});
