// Ogar -- "Feral Instinct: Whenever a Creature is played, roll a die: 1, 2, 3 = choose any one
// Creature in play, add one energy to it; 4, 5, 6 = choose any one Creature in play, discard one
// energy from it." Broadcast onPlay reactor for EITHER side's Creature plays. `rng` (2026-07-22,
// save/replay-determinism audit) is threaded from onPlay's own dispatch site
// (effects.ts's broadcastCardEnteredPlay, itself given a real rng by play.ts's playCard) -- the
// out-of-scope "onPlay hooks have no rng param at all" gap this file used to document is now
// closed for THIS dispatch path specifically; other onPlay-adjacent gaps (e.g. a hook reached via
// a different, still-unwidened entry point) may still exist elsewhere. Still passes a luckContext
// (task #31, 2026-07-16: Pyte's Luck) alongside the real rng -- state/cardDb were always available
// as onPlay hook params for that part.
//
// Real choice (Phase 4c, 2026-07-11): "choose any one Creature in play" replaces the earlier
// "smallest for add / largest for discard" simplification with a real pending choice
// (registry.ts's pendingTargetChoice/resolveTargetChoice) over every Creature in play, either
// side. The die roll still decides WHICH branch (add or discard) applies, encoded in the pending
// tag so resolveTargetChoice knows which one to run.
//
// The discard branch passes `self.controllerId` as discardEnergy's `causedByPlayerId` -- this
// fires for EITHER side's play, so `state.activePlayerId` alone would misattribute a discard Ogar
// causes during an opponent's turn as "not opposing" (effects.ts's discardEnergy doc comment).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { allCreaturesInPlay } from '../targeting.js';
import { addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const FERAL_INSTINCT_ADD_PENDING = 'ogarFeralInstinctAddPending';
const FERAL_INSTINCT_DISCARD_PENDING = 'ogarFeralInstinctDiscardPending';

registerCardEffect('Ogar', {
  onPlay: (state, cardDb, played, self, rng) => {
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    requestDieRoll(state, cardDb, self, self.controllerId, 6, 'ogar:feralInstinct', {}, rng);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    if (self.tags.has(FERAL_INSTINCT_ADD_PENDING)) {
      return { prompt: "Ogar's Feral Instinct: choose a Creature to add 1 energy to", pool };
    }
    if (self.tags.has(FERAL_INSTINCT_DISCARD_PENDING)) {
      return { prompt: "Ogar's Feral Instinct: choose a Creature to discard 1 energy from", pool };
    }
    return undefined;
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const adding = self.tags.has(FERAL_INSTINCT_ADD_PENDING);
    const discarding = self.tags.has(FERAL_INSTINCT_DISCARD_PENDING);
    removePermanentTag(self, FERAL_INSTINCT_ADD_PENDING);
    removePermanentTag(self, FERAL_INSTINCT_DISCARD_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    if (adding) addEnergy(state, cardDb, target, 1, 'effect');
    else if (discarding) discardEnergy(state, cardDb, target, 1, 'effect', self.controllerId, rng);
  },
});

registerRollConsumer('ogar:feralInstinct', (state, cardDb, source, _payload, finalRoll) => {
  if (!source) return;
  if (allCreaturesInPlay(state, cardDb).length === 0) return;
  addPendingChoiceTag(source, finalRoll <= 3 ? FERAL_INSTINCT_ADD_PENDING : FERAL_INSTINCT_DISCARD_PENDING);
});
