// Ulmi -- two printed clauses:
//   "Crystal Affinity: Crystal cards cost you one less energy to play, to a minimum of one." --
//   costModifier, "Crystal" family name match.
//   "Resist: Your Crystal Creatures lose one less energy when attacked." -- real energy discard
//   reduction on the defender, same shape as Stradus' Backlash but applied to self, not the
//   attacker: instead of discarding from the attacker, this ADDS to the defender before damage.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

const CRYSTAL_FAMILY = /\bCrystal\b/;

registerCardEffect('Ulmi', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Crystal Affinity = the -1
  // discount on own Crystal-family plays (`costModifier`); Resist = the +1 to own Crystal
  // defenders before energy is removed (`onBeforeEnergyRemoved`).
  effectHooks: {
    'Crystal Affinity': ['costModifier'],
    Resist: ['onBeforeEnergyRemoved'],
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return CRYSTAL_FAMILY.test(playedDef.name) ? -1 : 0;
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    if (!CRYSTAL_FAMILY.test(ctx.cardDb.get(ctx.defender.definitionKey)?.name ?? '')) return;
    addEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect');
  },
});
