// Voda -- "Deluge: At the end of your turn, add four energy to the Creature in play with the most
// energy. If two or more Creatures are tied for the most energy, an opponent of your choice
// chooses which Creature gets the energy."
//
// Real choice (Phase 4c, 2026-07-11): when there's a genuine tie, this is now a real pending
// choice (registry.ts's pendingTargetChoice/resolveTargetChoice) over just the tied Creatures,
// replacing the earlier "first tied Creature in array order" simplification. When there's no tie
// (the overwhelmingly common case), the single highest-energy Creature gets the energy
// immediately -- there's no real choice to offer, since the printed text only hands the pick to
// an opponent WHEN there's a tie.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const DELUGE_PENDING = 'vodaDelugePending';

function tiedForMostEnergy(state: Parameters<typeof allCreaturesInPlay>[0], cardDb: Parameters<typeof allCreaturesInPlay>[1]) {
  const creatures = allCreaturesInPlay(state, cardDb);
  if (creatures.length === 0) return [];
  const max = Math.max(...creatures.map((c) => c.currentEnergy ?? 0));
  return creatures.filter((c) => (c.currentEnergy ?? 0) === max);
}

registerCardEffect('Voda', {
  onOwnTurnEnd: (state, cardDb, self) => {
    const tied = tiedForMostEnergy(state, cardDb);
    if (tied.length === 0) return;
    if (tied.length === 1) {
      addEnergy(state, cardDb, tied[0]!, 4, 'effect');
      return;
    }
    addPendingChoiceTag(self, DELUGE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(DELUGE_PENDING)) return undefined;
    const pool = tiedForMostEnergy(state, cardDb);
    if (pool.length < 2) return undefined;
    return { prompt: "Voda's Deluge: an opponent chooses which tied Creature gets 4 energy", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, DELUGE_PENDING);
    if (!chosenInstanceId) return;
    const target = tiedForMostEnergy(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) addEnergy(state, cardDb, target, 4, 'effect');
  },
});
