// Vinoc -- "Generate: Discard any number of cards from your hand. For each card discarded, add
// one energy to Vinoc." First card exercising handDiscardCost's 'any' count (0 or more, player's
// choice) -- every earlier hand-discard card used a fixed count or 'X'.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromHand } from '../effects.js';

registerCardEffect('Vinoc', {
  handDiscardCost: { count: 'any' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Generate') return;
    const ids = ctx.chosenHandCardIds ?? [];
    const validIds = ids.filter((id) => ctx.controllingPlayer.hand.some((c) => c.instanceId === id));
    if (validIds.length === 0) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, validIds, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, ctx.source, validIds.length, 'power');
  },
});
