// Snow Hyren -- both printed effects:
//   "Energy Transfer (X): Choose a Creature in play. Add X energy to the chosen Creature." Same
//   X-cost pattern as Wyle's Energy Transfer.
//   "Cold and Colder: Whenever a frozen Creature is attacked, add one energy to Snow Hyren before
//   energy is removed." (a third-party reactor, either side's frozen Creature)

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Snow Hyren', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Energy Transfer') return;
    if (ctx.chosenTargetId === undefined || ctx.chosenXValue === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    addEnergy(ctx.state, ctx.cardDb, target, ctx.chosenXValue, 'power');
  },
  onAttack: (ctx, self) => {
    if (!ctx.defender || !isFrozen(ctx.state, ctx.cardDb, ctx.defender)) return;
    addEnergy(ctx.state, ctx.cardDb, self, 1, 'effect');
  },
});
