// Shimmer -- "Creature Bond: If there is no energy on Shimmer at the end of your turn, discard
// one energy from each opposing Creature in play."

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { opposingCreatures } from '../targeting.js';

registerCardEffect('Shimmer', {
  onOwnTurnEnd: (state, cardDb, self) => {
    if ((self.currentEnergy ?? 0) !== 0) return;
    for (const creature of opposingCreatures(state, cardDb, self.controllerId)) {
      discardEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
});
