// Morag -- "Theft (X): Choose any one opposing Relic in play. Gain control of the chosen Relic
// for X turns, beginning with the current turn. At the end of X turns, or if Morag is defeated,
// return the chosen Relic to its owner's hand."
//
// Target pool filtered to opposing Relics via targeting.ts's allRelicsInPlay. Control grab via
// effects.ts's gainControl, same as Zet/Darkbreed Hyren, but additionally stamps
// CardInstance.temporaryControlTheft ("X turns, beginning with the current turn" =
// expiresAfterTurnNumber: state.turnNumber + X - 1, same DurationTag-style "valid through this
// turn number" semantics) for the natural-expiry path (swept every turn start) and pushes onto
// CardInstance.gainedControlOf (Gorath's own precedent field) for the early-revert path, read
// back here by Morag's own onOwnMagiDefeated.

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, findInPlayById } from '../targeting.js';
import { getOpponents } from '../types/state.js';
import { gainControl, returnToOwnersHand } from '../effects.js';

registerCardEffect('Morag', {
  powerTargets: (state, cardDb, playerId, powerName) =>
    powerName === 'Theft' ? getOpponents(state, playerId).flatMap((p) => p.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic')) : undefined,
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Theft') return;
    if (ctx.chosenTargetId === undefined || !ctx.chosenXValue) return;
    const target = allRelicsInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target || target.controllerId === ctx.source.controllerId) return;

    gainControl(ctx.state, ctx.cardDb, target, ctx.source.controllerId);
    target.temporaryControlTheft = {
      grantedByInstanceId: ctx.source.instanceId,
      expiresAfterTurnNumber: ctx.state.turnNumber + ctx.chosenXValue - 1,
    };
    ctx.source.gainedControlOf.push(target.instanceId);
  },
  onOwnMagiDefeated: (state, cardDb, self) => {
    for (const instanceId of self.gainedControlOf) {
      const target = findInPlayById(state, instanceId);
      if (target && target.temporaryControlTheft?.grantedByInstanceId === self.instanceId) {
        target.temporaryControlTheft = null;
        returnToOwnersHand(state, cardDb, target);
      }
    }
    self.gainedControlOf = [];
  },
});
