// Hailstorm Pendant -- "All Hail You (2): If you have no Creatures in play, choose a Creature in
// play. Remove energy from the chosen Creature equal to your Magi's energize." The condition
// gates the target pool itself -- controlling any Creature at all means no legal targets.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, creaturesControlledBy, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Hailstorm Pendant', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).length > 0
      ? []
      : flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'All Hail You') return;
    if (creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).length > 0) return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;

    const magi = ctx.controllingPlayer.activeMagi;
    const amount = magi ? (ctx.cardDb.get(magi.definitionKey)?.energize ?? 0) : 0;
    discardEnergy(ctx.state, ctx.cardDb, target, amount, undefined, undefined, ctx.rng);
  },
});
