// Ullig's Slingshot -- "Fire Away!: Once per turn, when one of your Creatures is attacked and
// before energy is removed, you may roll one die: 1-2: Discard three energy from the defending
// Creature. 3-4: Discard one energy from the attacking Creature. 5-6: Discard three energy from
// the attacking Creature. Always use this result if your Magi is Ullig." Third-party reactor
// (Ullig's Slingshot doesn't need to be part of the combat itself).
//
// FATE'S WHIMSY REBUILD (accepted-limitation tail closure, 2026-08-15). Fire Away's roll now
// fires pre-combat via `requestDieRoll` and threads through
// `AttackDeclaration.preCombatDieRolls`; Whimsy is eligible. Missing entry (bot mode / test
// caller not pre-collecting, OR the Ullig-controller deterministic-6 branch below) falls back
// to the pre-2026-08-15 inline `rollDie(ctx.rng)` -- identical outcome, no Whimsy in that
// path. See `grassHyren.ts` header for the shared shape.
//
// Ullig-controller deterministic-6 branch: printed text "Always use this result if your Magi
// is Ullig" collapses the die to a fixed 6, so `offersPreCombatDieRoll` returns false in that
// case (nothing random for Whimsy to react to). The `onBeforeEnergyRemoved` body still applies
// the guaranteed 6 outcome via its existing `guaranteedBest` branch.
//
// Real choice (task #40-3, 2026-07-17, player-choice-default retrofit, Group 3): "you may roll"
// is a real yes/no via `pendingPreCombatTargetChoice`, single-candidate pool (self -- there's
// no real target to choose, just whether to trigger the roll at all). Discoverable by
// `combat.ts`'s widened `previewPreCombatTargetChoices` even though Ullig's Slingshot is neither
// the attacker nor the declared defender. No resolution supplied falls back to the old always-
// take default (the roll is strongly positive-EV for the defending side -- 2 of 3 outcomes hurt
// the attacker, only 1 of 3 hurts the defender). The pre-combat die-roll offer honors THIS same
// yes/no answer (reads it from `preCombatTargetChoices` passed by the widened
// `previewPreCombatDieRolls`) -- if the player declined the roll, we don't offer a Whimsy on it
// either.

import { registerCardEffect } from './registry.js';
import { discardEnergy, rollDie } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import { magiCountsAs } from './magiIdentity.js';
import { getPlayer } from '../types/state.js';
import type { PreCombatTargetResolution } from '../combat.js';

const FIRE_AWAY_USED_THIS_TURN = 'ulligsSlingshotFireAwayUsedThisTurn';

registerCardEffect("Ullig's Slingshot", {
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker, isDefender, attacker, defender) => {
    if (!defender || defender.controllerId !== self.controllerId) return undefined;
    if (hasDurationTag(self, FIRE_AWAY_USED_THIS_TURN)) return undefined;
    return { prompt: "Ullig's Slingshot's Fire Away!: roll a die to discard energy from the attacker or defender?", pool: [self] };
  },
  offersPreCombatDieRoll: (state, cardDb, self, _isAttacker, _isDefender, _attacker, defender, preCombatTargetChoices) => {
    if (!defender || defender.controllerId !== self.controllerId) return false;
    if (hasDurationTag(self, FIRE_AWAY_USED_THIS_TURN)) return false;
    // Deterministic-6 branch (see header): Ullig-controlled Magi collapses the roll to 6, so
    // there's nothing random for Whimsy to react to -- skip the offer, let the inline path
    // in onBeforeEnergyRemoved apply the guaranteed 6.
    const magi = getPlayer(state, self.controllerId).activeMagi;
    if (magi && magiCountsAs(cardDb, magi, 'Ullig')) return false;
    // Player's yes/no gate -- mirrors onBeforeEnergyRemoved's own `takeIt` computation below.
    // Absent resolution = auto-take default (positive-EV for defending side); a resolution
    // whose shape is `'skip'` = player declined = no offer.
    const resolution = preCombatTargetChoices?.[self.instanceId];
    const takeIt = resolution !== undefined ? !('skip' in resolution) : true;
    return takeIt;
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender || ctx.defender.controllerId !== self.controllerId) return;
    if (hasDurationTag(self, FIRE_AWAY_USED_THIS_TURN)) return;

    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
    const resolution = resolutions?.[self.instanceId];
    const takeIt = resolution !== undefined ? !('skip' in resolution) : true; // unchanged auto-take default
    if (!takeIt) return;

    addDurationTag(ctx.state, ctx.cardDb, self, FIRE_AWAY_USED_THIS_TURN, ctx.state.turnNumber);

    const magi = ctx.defendingPlayer.activeMagi;
    const guaranteedBest = magi ? magiCountsAs(ctx.cardDb, magi, 'Ullig') : false;
    const preCollected = (ctx.scratch.preCombatDieRolls as Record<string, number> | undefined)?.[self.instanceId];
    const roll = guaranteedBest
      ? 6
      : preCollected ?? rollDie(ctx.rng, 6, { state: ctx.state, cardDb: ctx.cardDb, rollingPlayerId: self.controllerId, source: self });

    if (roll <= 2) {
      discardEnergy(ctx.state, ctx.cardDb, ctx.defender, 3, 'effect', undefined, ctx.rng);
    } else if (roll <= 4) {
      discardEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect', undefined, ctx.rng);
    } else {
      discardEnergy(ctx.state, ctx.cardDb, ctx.attacker, 3, 'effect', undefined, ctx.rng);
    }
  },
});
