// Sandswirl (X-cost Spell, Arderial/d'Resh) -- "Choose any one Creature or Magi in play. For the
// next X turns, the chosen Creature or Magi cannot use any Power or Effects and loses one
// additional energy in attacks." task #50, 2026-07-20, Arderial Category D.
//
// Power-lock: reuses durationTags.ts's existing CANNOT_USE_POWER verbatim (already consulted
// generically by power.ts's isLegalPowerUse) -- no new mechanism needed.
// Attack-loss: durationTags.ts's new LOSES_BONUS_ENERGY_IN_ATTACKS, consulted by combat.ts right
// next to AGRAMS_ARMOR_SHIELD.
// Effects-lock: durationTags.ts's EFFECTS_LOCKED_DOWN (built 2026-07-22, Kybar's Teeth Spell
// pass's Feet of Stone) -- a true PER-INSTANCE effect lock, unlike lockdown.ts's Rayje's Belt
// Lockdown (which is keyed by printed effect NAME across every card sharing it). Consulted by
// lockdown.ts's isCardEffectLockedDown, the single choke point every effect-hook dispatch site in
// the engine now goes through (mechanically swept across ~104 call sites the same session this
// tag was added) -- so tagging the target here is the entire fix, no further plumbing needed.
// Previously deferred as a documented simplification (same "partial" treatment as Kintor
// Furs/Sarf/Glacier Hyren) because that per-instance mechanism didn't exist yet; now built.
//
// X is read back via effects.ts's getCounter(source, 'startingX') -- play.ts's playCard already
// stores whatever chosenXValue the UI collected there for any card type, no Spell-specific plumbing
// needed.

import { registerCardEffect } from './registry.js';
import { getCounter } from '../effects.js';
import { addDurationTag, CANNOT_USE_POWER, LOSES_BONUS_ENERGY_IN_ATTACKS, EFFECTS_LOCKED_DOWN } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { findCreatureOrMagiById } from '../targeting.js';
import type { CardInstance } from '../types/instance.js';

registerCardEffect('Sandswirl', {
  spellTargets: (state, cardDb) => {
    const pool: CardInstance[] = [];
    for (const player of state.players.values()) {
      for (const c of player.inPlay) {
        if (cardDb.get(c.definitionKey)?.card_type === 'Creature') pool.push(c);
      }
      if (player.activeMagi) pool.push(player.activeMagi);
    }
    return pool;
  },
  resolveSpell: (ctx) => {
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId ?? '');
    if (!target) return;
    const x = getCounter(ctx.source, 'startingX');
    if (x <= 0) return;
    const expiry = ctx.state.turnNumber + x;
    addRestrictionTag(ctx.state, target, CANNOT_USE_POWER, expiry);
    addDurationTag(ctx.state, ctx.cardDb, target, LOSES_BONUS_ENERGY_IN_ATTACKS, expiry);
    addRestrictionTag(ctx.state, target, EFFECTS_LOCKED_DOWN, expiry);
  },
});
