// Szalak -- "Supercharge: Roll a die: 1, 2 = Add five energy to Szalak. 3, 4 = Discard Szalak
// from play. 5, 6 = Add three energy to Szalak and three energy to your Magi." No target picker
// -- a pure branching-table effect, all outcomes affect only Szalak itself and/or its own Magi.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { getPlayer } from '../types/state.js';

registerCardEffect('Szalak', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Supercharge') return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'szalak:supercharge',
      { controllingPlayerId: ctx.controllingPlayer.playerId },
      ctx.rng
    );
  },
});

registerRollConsumer('szalak:supercharge', (state, cardDb, source, payload, finalRoll, rng) => {
  if (!source) return;
  const { controllingPlayerId } = payload as { controllingPlayerId: string };
  const controllingPlayer = getPlayer(state, controllingPlayerId);
  if (finalRoll <= 2) {
    addEnergy(state, cardDb, source, 5, 'power');
  } else if (finalRoll <= 4) {
    discardFromPlay(state, cardDb, controllingPlayer, source.instanceId, undefined, undefined, rng);
  } else {
    addEnergy(state, cardDb, source, 3, 'power');
    if (controllingPlayer.activeMagi) {
      addEnergy(state, cardDb, controllingPlayer.activeMagi, 3, 'power');
    }
  }
});
