// Hyren's Call (Spell, cost 6) -- "Search your deck for any one hyren. Play the hyren with full
// energy. The hyren cannot attack this turn. Shuffle your deck." Naroom Spell pass, Category B
// (2026-07-23). Reuses the plain spellTargets/chosenTargetId pipeline with the pool computed
// directly from `player.deck` (naranLights.ts's own precedent for a deck-zone spellTargets pool,
// just the WHOLE deck instead of a top-3 reveal) -- no new deck-search picker mechanism needed.
// `.name.includes('Hyren')` is the established name-family idiom (babyHyren.ts/monarchHyren.ts/
// thunderHyren.ts/etc.), cross-region (no Naroom restriction, matching the printed "any one
// hyren"). effects.ts's searchDeckIntoPlay + zones.ts's shuffleDeck (Warlum's own combo).

import { registerCardEffect } from './registry.js';
import { searchDeckIntoPlay } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';
import { shuffleDeck } from '../zones.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect("Hyren's Call", {
  spellTargets: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player) return [];
    return player.deck.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature' && cardDb.get(c.definitionKey)?.name.includes('Hyren'));
  },
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    if (ctx.chosenTargetId === undefined) return;
    const card = player.deck.find((c) => c.instanceId === ctx.chosenTargetId);
    const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
    if (!card || !def || def.card_type !== 'Creature' || !def.name.includes('Hyren')) return;

    const played = searchDeckIntoPlay(ctx.state, ctx.cardDb, player, card.instanceId, effectiveStartingEnergy(ctx.state, ctx.cardDb, card), true, ctx.rng);
    if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
    shuffleDeck(player, ctx.rng);
    checkCreatureDefeats(ctx.state, ctx.cardDb);
  },
});
