// Shadow Vinoc -- "Dark Strength: When you play Shadow Vinoc, add one energy to it for each
// opposing Relic in play." Errata-corrected text (2i Design: "opposing" Relics only, not every
// Relic in play) -- data-pipeline/output/cards.json already carries the corrected wording.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allRelicsInPlay } from '../targeting.js';

registerCardEffect('Shadow Vinoc', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    const opposingRelics = allRelicsInPlay(state, cardDb).filter((r) => r.controllerId !== self.controllerId);
    if (opposingRelics.length > 0) {
      addEnergy(state, cardDb, self, opposingRelics.length, 'effect');
    }
  },
});
