// Emec's Forge -- "Recycle: Once per turn, as one of your Kybar's Teeth Creatures is being
// defeated, or being discarded from play by an opposing card while it has energy, you may
// discard one of your Relics from play. If you do, leave your Creature in play with its current
// energy or restore it to the energy it had before the attack instead of discarding it."
//
// registry.ts's preventsDiscardOf, checked at BOTH choke points its text covers ("being
// defeated" -> energy.ts's zero-energy sweep; "being discarded... by an opposing card" ->
// effects.ts's explicit discardFromPlay). "Leave with current energy (0) or restore to energy
// before the attack" is a player choice with no prompt infrastructure at this trigger point --
// simplified to always restoring the full printed starting energy, which is strictly the more
// useful of the two options and the auto-take convention this codebase uses throughout for
// unprompted "may" choices. The sacrificed Relic is auto-picked as the first eligible OTHER
// Relic -- excluding Emec's Forge itself, since sacrificing the very card granting this
// protection as part of using it is a strange choice no player would actually want when a
// different Relic is available (its printed text doesn't forbid it, but "one of your Relics"
// doesn't require it either).

import { registerCardEffect } from './registry.js';
import { discardFromPlay, restoreEnergy } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const USED_THIS_TURN = 'emecsForgeUsedThisTurn';

registerCardEffect("Emec's Forge", {
  preventsDiscardOf: (state, cardDb, target, self, cause, rng) => {
    if (target.controllerId !== self.controllerId) return false;
    const targetDef = cardDb.get(target.definitionKey);
    if (targetDef?.card_type !== 'Creature' || !targetDef.regions.includes("Kybar's Teeth")) return false;
    if (hasDurationTag(self, USED_THIS_TURN)) return false;
    const owner = state.players.get(self.controllerId);
    if (!owner) return false;
    const relic = owner.inPlay.find(
      (c) => c.instanceId !== self.instanceId && cardDb.get(c.definitionKey)?.card_type === 'Relic'
    );
    if (!relic) return false;

    discardFromPlay(state, cardDb, owner, relic.instanceId, undefined, undefined, rng);
    restoreEnergy(state, cardDb, target, effectiveStartingEnergy(state, cardDb, target));
    addDurationTag(state, cardDb, self, USED_THIS_TURN, state.turnNumber);
    return true;
  },
});
