// Klynn -- "Seer (2): Roll a die. Reveal a number of cards from the top of your deck equal to the
// die roll. If you reveal any Spells, choose one and add it to your hand. Discard the remaining
// cards."
//
// FATE'S WHIMSY REBUILD (Bucket D Tier 2 completion, 2026-08-14). Split into two phases:
//   PHASE A (`resolvePower`): arms `requestDieRoll('klynn:seer', {klynnInstanceId})` and returns.
//     Whimsy is eligible; if no reactor exists, the consumer fires inline (fast path). Klynn
//     no longer declares `deckTopReveal` -- Play.tsx cannot open the reveal prompt at usePower
//     time because the die roll hasn't happened yet.
//   PHASE B (`resolveKlynnSeer` engine export): called by Play.tsx after the player answers the
//     reveal-and-discard prompt (armed via `state.pendingKlynnSeer`, set by the consumer). Does
//     the ORIGINAL resolvePower body's work: move each revealed card to discard, tag each
//     revealed Spell for the follow-up pendingTargetChoice, clear pendingKlynnSeer.
//
// The consumer stores the final roll on `state.pendingKlynnSeer = {klynnInstanceId, count}`.
// Play.tsx polls this state (parallel to how it polls `pendingFirstPlayerChoice` /
// `pendingDieRoll` etc.); when non-null, it renders the reveal prompt with the pre-computed N,
// collects the player's picks, and calls `resolveKlynnSeer(state, cardDb, chosenIds, rng)`.
//
// `deckTopReveal.count` (the pre-2026-08-14 mechanism) stays in place for Trulb and any other
// board-state-driven count card -- those aren't die rolls and don't need Whimsy. Only Klynn's
// registration removes it.
//
// The second-tier "choose ONE Spell to add to hand" pendingTargetChoice is unchanged --
// resolveKlynnSeer's body tags every revealed Spell with the SEER_SPELL_PREFIX tag, and
// Klynn's pendingTargetChoice/resolveTargetChoice hooks handle the pick same as before.

import { registerCardEffect } from './registry.js';
import { requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { removeFromZone, moveToDiscardPile } from '../zones.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { Rng } from '../rng.js';

const SEER_SPELL_PREFIX = 'klynnSeerSpell:';

function pendingSpellIds(self: { tags: ReadonlySet<string> }): string[] {
  const ids: string[] = [];
  for (const tag of self.tags) {
    if (tag.startsWith(SEER_SPELL_PREFIX)) ids.push(tag.slice(SEER_SPELL_PREFIX.length));
  }
  return ids;
}

registerCardEffect('Klynn', {
  effectHooks: {
    Seer: ['resolvePower', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Seer') return;
    // Phase A: arm the roll. Consumer fires later (either inline via fast path or after Whimsy
    // resolves), sets state.pendingKlynnSeer, Play.tsx picks it up.
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'klynn:seer',
      { klynnInstanceId: ctx.source.instanceId },
      ctx.rng
    );
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const ids = pendingSpellIds(self);
    if (ids.length === 0) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player) return undefined;
    const pool: CardInstance[] = ids
      .map((id) => player.discardPile.find((c) => c.instanceId === id))
      .filter((c): c is CardInstance => !!c);
    if (pool.length === 0) return undefined;
    return { prompt: "Klynn's Seer: choose a revealed Spell to add to your hand", pool };
  },
  resolveTargetChoice: (state, _cardDb, self, chosenInstanceId) => {
    const ids = pendingSpellIds(self);
    for (const id of ids) removePermanentTag(self, `${SEER_SPELL_PREFIX}${id}`);
    if (!chosenInstanceId || !ids.includes(chosenInstanceId)) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const index = player.discardPile.findIndex((c) => c.instanceId === chosenInstanceId);
    if (index === -1) return;
    const [card] = player.discardPile.splice(index, 1);
    player.hand.push(card!);
  },
});

registerRollConsumer('klynn:seer', (state, _cardDb, _source, payload, finalRoll) => {
  const { klynnInstanceId } = payload as { klynnInstanceId: string };
  // Store the pre-computed count for Play.tsx to render the reveal prompt.
  state.pendingKlynnSeer = { klynnInstanceId, count: finalRoll };
});

/** Bucket D Tier 2 completion 2026-08-14: Phase B of Klynn's Seer. Called by Play.tsx (or a
 *  test that wants to skip the UI round-trip) after the reveal-and-discard picks are collected
 *  from the player. Does the original resolvePower body's work: for each id in
 *  `chosenDeckTopIds`, move that card from the player's deck to the discard pile and tag it on
 *  Klynn for the follow-up Spell-choice pendingTargetChoice. Silently no-ops if
 *  `pendingKlynnSeer` isn't armed (torn state / duplicate call). Clears pendingKlynnSeer on
 *  exit. */
export function resolveKlynnSeer(
  state: GameState,
  cardDb: CardDatabase,
  chosenDeckTopIds: readonly string[],
  _rng: Rng
): void {
  const pending = state.pendingKlynnSeer;
  if (!pending) return;
  const klynn = [...state.players.values()]
    .flatMap((p) => (p.activeMagi ? [p.activeMagi, ...p.inPlay] : p.inPlay))
    .find((c) => c.instanceId === pending.klynnInstanceId);
  if (!klynn) {
    state.pendingKlynnSeer = null;
    return;
  }
  const player = state.players.get(klynn.controllerId);
  if (!player) {
    state.pendingKlynnSeer = null;
    return;
  }
  const revealed = chosenDeckTopIds
    .map((id) => player.deck.find((c) => c.instanceId === id))
    .filter((c): c is CardInstance => !!c);
  for (const card of revealed) {
    const instance = removeFromZone(player, 'deck', card.instanceId);
    moveToDiscardPile(state, player, instance);
    if (cardDb.get(instance.definitionKey)?.card_type === 'Spell') {
      addPermanentTag(state, cardDb, klynn, `${SEER_SPELL_PREFIX}${instance.instanceId}`);
    }
  }
  state.pendingKlynnSeer = null;
}
