// Blu -- "Artifice: The first time each turn Blu plays a relic, draw one card." Regex-classified
// as onOwnTurnStart (probably matched on an unrelated phrase), but this is actually an onPlay
// card (reacts to playing a Relic, not to the turn starting) -- reclassified and built under the
// existing onPlay hook instead, once-per-turn guarded the same way every other "once per turn"
// onPlay reaction in this codebase is.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const ARTIFICE_USED_THIS_TURN = 'bluArtificeUsedThisTurn';

registerCardEffect('Blu', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;
    if (hasDurationTag(self, ARTIFICE_USED_THIS_TURN)) return;

    const player = state.players.get(self.controllerId);
    if (!player) return;
    drawCards(state, cardDb, player, 1);
    addDurationTag(state, cardDb, self, ARTIFICE_USED_THIS_TURN, state.turnNumber);
  },
});
