// Pillar of Brine (Spell, Orothe, cost 2) -- "Choose any one player. During the chosen player's
// next turn, each of his or her Creatures removes two less energy from opposing Creatures when they
// attack." New durationTags.ts WEAKENED_ATTACKS tag (STUMBLE's mirror image, keyed to the
// ATTACKING player's Magi instead of the defending one), applied to the chosen player's own Magi
// with an expiry of nextTurnNumberFor(state, chosenPlayerId) -- "during [their] next turn" is
// valid only through that one turn, same convention Entangle/Will of Orothe use.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay } from '../targeting.js';
import { addDurationTag, nextTurnNumberFor, WEAKENED_ATTACKS } from '../durationTags.js';

registerCardEffect('Pillar of Brine', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const target = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!target) return;
    // 4th arg (2026-07-27): attributes the reduction to Pillar of Brine itself, which by then is in
    // the discard pile -- findCard looks in every zone, and "other cards" does not require the
    // card to still be in play. This is the case that shipped broken.
    addDurationTag(ctx.state, ctx.cardDb, target, WEAKENED_ATTACKS, nextTurnNumberFor(ctx.state, target.controllerId), ctx.source.instanceId);
  },
});
