// Stradus -- "Backlash: Whenever one of your Creatures is attacked, you may discard one energy
// from the attacking Creature before energy is removed." Real energy discard -> onBeforeEnergyRemoved.
// Third-party reactor -- Stradus doesn't need to be part of the combat itself, just in play on the
// defending side.
//
// Real choice (task #40-3, 2026-07-17, player-choice-default retrofit, Group 3): "may" is now a
// real yes/no via `pendingPreCombatTargetChoice`, single-candidate pool (the attacking Creature --
// the only possible target). Discoverable by `combat.ts`'s widened `previewPreCombatTargetChoices`
// even though Stradus is neither the attacker nor the declared defender. No resolution supplied
// falls back to the old always-take default.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import type { PreCombatTargetResolution } from '../combat.js';

registerCardEffect('Stradus', {
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker, isDefender, attacker, defender) => {
    if (!defender || defender.controllerId !== self.controllerId) return undefined;
    return { prompt: "Stradus's Backlash: discard one energy from the attacking Creature?", pool: [attacker] };
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
    const resolution = resolutions?.[self.instanceId];
    const takeIt = resolution !== undefined ? !('skip' in resolution) : true; // unchanged auto-take default
    if (takeIt) {
      // Caused by Stradus's own controller (the defending side), not the attacker.
      discardEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect', self.controllerId, ctx.rng);
    }
  },
});
