// Magma Jile -- "Hunger: Whenever an opponent plays a Creature with a starting energy of two or
// less, you may add two energy to Magma Jile." Broadcast onPlay reactor (self reacts to an
// OPPOSING play), same shape as the "onPlay subset, broadcast group" batch, just missed by that
// survey.
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice` -- no external reference
// needed (the effect only ever touches self).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const AWAITING_CHOICE = 'magmaJileAwaitingChoice';

registerCardEffect('Magma Jile', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (effectiveStartingEnergy(state, cardDb, played) > 2) return;
    addPendingChoiceTag(self, AWAITING_CHOICE);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    return {
      prompt: 'Magma Jile\'s Hunger: add two energy to Magma Jile?',
      yesLabel: 'Add 2 energy',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean) => {
    removePermanentTag(self, AWAITING_CHOICE);
    if (!chosenBoolean) return;
    addEnergy(state, cardDb, self, 2, 'effect');
  },
});
