// Quallon -- "Weave": "Whenever Quallon attacks or is attacked, before energy is removed, you may
// move one energy between it and one of your other Weave Creatures in play." (see weave.ts)
//
// "Rapid Change: Whenever you use an Effect that moves energy between two Creatures in play, you
// may move one additional energy." -- BUILT 2026-08-11 (post-audit deferred-gap closure pass,
// Category B), via the `from`/`to` parameters newly added to registry.ts's
// `onOwnCreatureMovedEnergyViaEffect` broadcast. Read literally, "one additional energy" is MORE of
// the move that just happened, not a fresh player-chosen pair -- so the bonus replicates the exact
// same `from`/`to` direction as the triggering move, offered as a real yes/no choice (Zaya's
// Payback precedent for a post-hoc "may," including its frozen-at-trigger-time reasoning: the pair
// is captured in the pending tag rather than re-derived at resolve time, since either card could
// have left play by then). The bonus move itself does NOT re-broadcast
// `onOwnCreatureMovedEnergyViaEffect` -- "one additional energy," singular, not a repeatable chain.

import { registerCardEffect } from './registry.js';
import { applyWeave } from './weave.js';
import { rearrangeEnergy } from '../effects.js';
import { addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const PENDING_PREFIX = 'quallonRapidChangePending:';

function pendingPair(self: CardInstance): { fromId: string; toId: string } | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) {
      const [fromId, toId] = tag.slice(PENDING_PREFIX.length).split('>');
      return fromId && toId ? { fromId, toId } : undefined;
    }
  }
  return undefined;
}

function clearPending(self: CardInstance): void {
  const pair = pendingPair(self);
  if (pair) removePermanentTag(self, `${PENDING_PREFIX}${pair.fromId}>${pair.toId}`);
}

function findCard(state: GameState, controllerId: string, instanceId: string): CardInstance | undefined {
  const player = state.players.get(controllerId);
  return player?.inPlay.find((c) => c.instanceId === instanceId);
}

registerCardEffect('Quallon', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Weave is the standard move hook +
  // `weaveConfig`; Rapid Change is the post-move reactor + its yes/no follow-up.
  effectHooks: {
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
    'Rapid Change': ['onOwnCreatureMovedEnergyViaEffect', 'pendingYesNoChoice', 'resolveYesNoChoice'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
  onOwnCreatureMovedEnergyViaEffect: (state, cardDb, self, mover, from, to) => {
    if (mover.controllerId !== self.controllerId) return; // "whenever YOU use an Effect"
    if (!from || !to) return; // no single unambiguous pair to replicate (e.g. Blade Hyren's Great Weave)
    clearPending(self); // drop a stale unanswered offer before opening a new one (Zaya precedent)
    addPendingChoiceTag(self, `${PENDING_PREFIX}${from.instanceId}>${to.instanceId}`);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    const pair = pendingPair(self);
    if (!pair) return undefined;
    const from = findCard(state, self.controllerId, pair.fromId);
    const to = findCard(state, self.controllerId, pair.toId);
    if (!from || !to || (from.currentEnergy ?? 0) <= 0) return undefined;
    return {
      prompt: "Quallon's Rapid Change: move one additional energy the same way?",
      yesLabel: 'Move 1 more energy',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const pair = pendingPair(self);
    clearPending(self); // cleared on BOTH branches -- a decline must not re-offer forever
    if (!chosenBoolean || !pair) return;
    const from = findCard(state, self.controllerId, pair.fromId);
    const to = findCard(state, self.controllerId, pair.toId);
    if (!from || !to || (from.currentEnergy ?? 0) <= 0) return;
    rearrangeEnergy(state, cardDb, from, to, 1, rng);
  },
});
