// Spined Hyren -- "Mental Assault (2): Choose a player, and one of that player's Creatures. Look
// at the chosen player's hand. Discard one energy from the chosen Creature for each Spell in that
// player's hand." The "choose a player" isn't a separate UI step -- the target picker offers every
// Creature in play (either player's), and "the chosen player" is just whoever controls the picked
// Creature. "Look at the chosen player's hand" needs no new reveal mechanic either: the engine
// already has full access to both players' hands (hidden hands are a UI-only rendering choice),
// so counting Spells there is a direct, correct read.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Spined Hyren', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mental Assault') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    const owner = ctx.state.players.get(target.controllerId);
    if (!owner) return;
    const spellCount = owner.hand.filter((c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Spell').length;
    discardEnergy(ctx.state, ctx.cardDb, target, spellCount, undefined, undefined, ctx.rng);
  },
});
