// Zaya's Bow -- "Long Shot (1): Choose any one Creature in play. Discard one energy from the
// chosen Creature. That Creature must attack on its controller's next turn, if able. If your
// Magi is Zaya, all other Creatures controlled by that player must also attack on his or her
// next turn, if able." Built task #44 Part B, 2026-07-18 -- the flagship card of the must-attack
// enforcement architecture. "Any one Creature in play" -- no ownership qualifier, so the target
// pool is `allCreaturesInPlay` (both sides), same discipline as Energy Band/Blizzard Core's own
// unrestricted "choose a..." pools. Expiry is `nextTurnNumberFor` the TARGET's controller (not
// the caster) -- "on ITS controller's next turn," a delayed obligation, unlike Icefang
// Battlesled/Wasperine Stalker/Energy Band's "this turn" scope. The Zaya-identity cascade reuses
// `magiCountsAs` (Ullig's Slingshot precedent, task #28) + `creaturesControlledBy` (Icefang
// Battlesled precedent) to tag every OTHER Creature the target's controller has in play, same
// expiry as the primary target.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, MUST_ATTACK_THIS_TURN, nextTurnNumberFor } from '../durationTags.js';
import { magiCountsAs } from './magiIdentity.js';

registerCardEffect("Zaya's Bow", {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Long Shot') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    discardEnergy(ctx.state, ctx.cardDb, target, 1, 'power', undefined, ctx.rng);
    const targetOwner = ctx.state.players.get(target.controllerId);
    if (!targetOwner) return;
    const expiry = nextTurnNumberFor(ctx.state, targetOwner.playerId);
    addDurationTag(ctx.state, ctx.cardDb, target, MUST_ATTACK_THIS_TURN, expiry);

    const casterMagi = ctx.controllingPlayer.activeMagi;
    if (casterMagi && magiCountsAs(ctx.cardDb, casterMagi, 'Zaya')) {
      for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, targetOwner.playerId)) {
        if (creature.instanceId === target.instanceId) continue;
        addDurationTag(ctx.state, ctx.cardDb, creature, MUST_ATTACK_THIS_TURN, expiry);
      }
    }
  },
});
