// Giant Baldar -- both printed pieces:
//   "Momentum: If Giant Baldar attacks and defeats a Magi's last Creature in play, discard all
//   but one energy from the defeated Creature's Magi." Checked in afterCombat, after the defeat
//   sweep has already removed the Creature from play -- "last Creature" means the defending
//   player controls zero Creatures at that point.
//   "Invulnerability: Giant Baldar loses one less energy in attacks." (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Giant Baldar', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Invulnerability owns onAttack,
  // Momentum owns afterCombat.
  effectHooks: {
    Invulnerability: ['onAttack'],
    Momentum: ['afterCombat'],
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null || outcome.defenderSurvived) return;
    if (creaturesControlledBy(ctx.state, ctx.cardDb, ctx.defendingPlayer.playerId).length > 0) return;
    const magi = ctx.defendingPlayer.activeMagi;
    if (!magi) return;
    const excess = (magi.currentEnergy ?? 0) - 1;
    if (excess > 0) discardEnergy(ctx.state, ctx.cardDb, magi, excess, 'effect', undefined, ctx.rng);
  },
});
