// Sandsinger -- "Ballad of the Truth: Discard Sandsinger and one of your other cards from play to
// search your deck for any one d'Resh card and place that card into your hand."

import { registerCardEffect } from './registry.js';
import { inPlayControlledBy, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay, searchDeck } from '../effects.js';

registerCardEffect('Sandsinger', {
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(state, "d'Resh")) ?? false,
  },
  // Excludes itself at the POOL level (via sourceInstanceId, same fix as Flame Rudwot's Healing
  // Flame -- see registry.ts's powerTargets doc comment) -- this comment used to say that
  // information wasn't available at this stage, which was true before that 2026-07-08 fix but is
  // stale now; updated 2026-07-09 after the same class of bug was caught again in playtesting.
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) =>
    inPlayControlledBy(state, playerId).filter((c) => c.instanceId !== sourceInstanceId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Ballad of the Truth') return;
    if (ctx.chosenTargetId === undefined) return;
    if (ctx.chosenTargetId === ctx.source.instanceId) return; // must be an OTHER card
    const other = ctx.controllingPlayer.inPlay.find((c) => c.instanceId === ctx.chosenTargetId);
    if (!other) return;

    const ids = ctx.chosenDeckSearchIds ?? [];
    if (ids.length > 1) return;
    for (const id of ids) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      if (!card || !ctx.cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(ctx.state, "d'Resh"))) return;
    }

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, other.instanceId, undefined, undefined, ctx.rng);
    searchDeck(ctx.state, ctx.controllingPlayer, ids, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ["d'Resh"],
});
