// Agrilla -- both printed pieces:
//   Power "Fear: Choose any one of your other Creatures in play that can attack. The chosen
//   Creature may attack twice this turn." A genuine ONE-SHOT: the text picks a single Creature and
//   is done, so this writes types/instance.ts's oneShotBonusAttacks counter rather than using the
//   standing grantsBonusAttacksTo hook that Yaki/Yaki's Gauntlets/Korremar, Avatar use (task #557).
//   "Invulnerability: Agrilla loses one less energy in attacks." (invulnerability.ts)

import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { hasDurationTag, CANNOT_ATTACK, hasAttacksRemaining } from '../durationTags.js';
import { applyInvulnerability } from './invulnerability.js';

// "that can attack" -- the per-turn budget half comes from the SHARED helper so this agrees with
// combat.ts about what the budget is, including any standing grants in play (task #557).
function canStillAttack(state: GameState, cardDb: CardDatabase, c: CardInstance): boolean {
  return hasAttacksRemaining(state, cardDb, c) && !hasDurationTag(c, CANNOT_ATTACK) && !c.tags.has(CANNOT_ATTACK);
}

registerCardEffect('Agrilla', {
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => c.instanceId !== sourceInstanceId && canStillAttack(state, cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Fear') return;
    if (ctx.chosenTargetId === undefined) return;
    if (ctx.chosenTargetId === ctx.source.instanceId) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!canStillAttack(ctx.state, ctx.cardDb, target)) return;

    target.oneShotBonusAttacks += 1;
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
});
