// Nightmare Hyren -- "Horrible Dreams (3): Choose an opposing Creature. The chosen Creature gains
// 'Effect -- Toss and Turn: At the beginning of your turn, discard one energy from your Magi and
// each of your Creatures in play. This Creature removes two less energy from Core Creatures in
// attacks.'" A permanent granted-ability tag (durationTags.ts's TOSS_AND_TURN, task #35,
// 2026-07-16), checked generically in turn.ts (the start-of-turn drain) and combat.ts (the -2-vs-
// Core reduction) rather than through this file's own hooks, since the tagged Creature is
// typically a DIFFERENT card entirely once granted.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, findInPlayById } from '../targeting.js';
import { addPermanentTag, TOSS_AND_TURN } from '../durationTags.js';

registerCardEffect('Nightmare Hyren', {
  powerTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Horrible Dreams') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;

    addPermanentTag(ctx.state, ctx.cardDb, target, TOSS_AND_TURN);
  },
});
