// Giant Kelthet -- "Flamebath (6): Remove three energy from each non-Cald Creature and Magi."
// No target -- a region-filtered sweep across Creatures and Magi, both sides. ("Your Powers,
// Spells and Effects may not increase the amount removed" is moot for now -- nothing in the
// engine currently modifies another effect's removal amount.)

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Giant Kelthet', {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- static region check mirroring
  // resolvePower's own gating below, no execution.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options, powerName) => {
    if (powerName !== 'Flamebath') return false;
    const specifiedRegion = regionForTargetFilter(state, 'Cald');
    return getOpponents(state, actingPlayerId).some(
      (opp) => opp.activeMagi && !effectiveRegions(state, cardDb, opp.activeMagi).includes(specifiedRegion)
    );
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Flamebath') return;
    const specifiedRegion = regionForTargetFilter(ctx.state, 'Cald');
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(specifiedRegion)) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 3, undefined, undefined, ctx.rng);
      }
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, magi).includes(specifiedRegion)) {
        discardEnergy(ctx.state, ctx.cardDb, magi, 3, undefined, undefined, ctx.rng);
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (This file was missed in the original 34-file sweep --
  // caught while writing representative test coverage for that sweep.)
  specifiedTargetRegions: () => ['Cald'],
});
