// Crushing Stench (Spell, Bograth-Magi-only) -- "Choose any one Creature in play. Discard four
// energy from the chosen Creature. If the chosen Creature is discarded from play, play a Bograth
// Creature from your hand with two energy instead of its starting energy. That Creature cannot
// attack this turn. Only Bograth Magi and Bograth Shadow Magi can play Crushing Stench." Bograth
// Spell pass, Category B1 (2026-07-20). Pure synthesis of two already-built precedents: the
// "Bograth Magi/Shadow Magi only" restriction is 100% data-driven (region_restrictive, per
// crushingSands.ts's own header comment -- zero code needed). The "discard 4; if it dies, do X"
// half is crushingSands.ts's own exact structure (discardEnergy -> checkCreatureDefeats ->
// re-check findInPlayById). The "play from hand at overridden energy, cannot attack" half is
// phlouk.ts's exact handPlayChoice + playFromZone(..., 'hand', 2) + CANNOT_ATTACK pattern.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardEnergy, playFromZone } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Crushing Stench', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellHandPlayChoice: {
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes('Bograth');
    },
  },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);
    checkCreatureDefeats(ctx.state, ctx.cardDb, 'spell', undefined, ctx.rng);
    // "IF the chosen Creature is discarded from play" -- ask the DISCARD PILE, not "is it still in
    // play". #536 C6f (2026-07-27): this used to poll findInPlayById and infer the discard from
    // absence, which silently became wrong once Kybar's Echo started firing on the defeat path
    // (C6c). Echo REPLACES the discard by returning the Creature to its owner's hand -- so it is
    // absent from play but was never discarded, and the old poll fired this follow-up anyway.
    // Verified live before changing. Same reasoning covers any future return-to-hand or
    // shuffle-into-deck replacement.
    const targetOwner = ctx.state.players.get(target.controllerId);
    const wasDiscarded = targetOwner?.discardPile.some((c) => c.instanceId === target.instanceId) ?? false;
    if (!wasDiscarded) return; // survived, or was replaced out of play some other way

    if (!ctx.chosenHandPlayId) return;
    const handCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    const def = handCard ? ctx.cardDb.get(handCard.definitionKey) : undefined;
    if (!def || def.card_type !== 'Creature' || !def.regions.includes('Bograth')) return;

    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: ctx.chosenHandPlayId },
      ctx.controllingPlayer,
      2
    , ctx.rng);
    if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
  },
});
