// Korremar (Sands of d'Resh Shadow Magi, printed under Core per rules-reference.md's Shadow Magi
// convention -- distinct from Korremar, Avatar's own Cald costModifier clause, korremarAvatar.ts)
// -- "Mind Shock: Choose any one player. Skip your Draw Step this turn. During the chosen
// player's next turn, he or she may only draw one card." "Choose any one player" targeted via
// that player's own Magi instance, same pattern as Warlum's Materialize. "Skip your Draw Step
// this turn" is the CASTER's own skip, unconditional -- same skipDrawStepThisTurn primitive and
// "actually consumed next time this player's draw phase runs" interpretation already established
// by Celebrated Hero's identical clause. The chosen player's cap uses the new PlayerState.
// pendingDrawCap (task #35, 2026-07-16) -- a one-shot future-turn restriction, unlike the
// continuously-re-checked capsDrawCountAt broadcast, since Mind Shock has no ongoing in-play
// source once it resolves.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay } from '../targeting.js';

registerCardEffect('Korremar', {
  powerTargets: (state) => allMagiInPlay(state),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mind Shock') return;
    if (ctx.chosenTargetId === undefined) return;
    const targetMagi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!targetMagi) return;
    const chosenPlayer = ctx.state.players.get(targetMagi.controllerId);
    if (!chosenPlayer) return;

    ctx.state.skipDrawStepThisTurn = true;
    chosenPlayer.pendingDrawCap = 1;
  },
});
