// Shared "Roar" shape for Moga ("the next time the chosen Creature attacks a Creature, it removes
// twice as much energy from that Creature") and Moga Pup ("...it removes four additional energy
// from that Creature") -- task #42, 2026-07-17, the Kybar's Teeth region pass. Both Powers pick a
// target immediately (powerTargets/resolvePower, not a post-hoc pending choice -- this is an
// active Power activation, the player already picks the target when using it) and apply a one-shot
// duration tag to the CHOSEN Creature (which may not be self), consumed by combat.ts on that
// Creature's next attack against another Creature (not a direct Magi attack, per "attacks a
// Creature" in both printed texts).

import { allCreaturesInPlay } from '../targeting.js';
import { addDurationTag } from '../durationTags.js';
import type { CardEffectDefinition } from './registry.js';

export function roarPowerHooks(tag: string): Pick<CardEffectDefinition, 'powerTargets' | 'resolvePower'> {
  return {
    powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
    resolvePower: (ctx) => {
      if (ctx.powerName !== 'Roar') return;
      if (ctx.chosenTargetId === undefined) return;
      const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
      if (!target) return;
      addDurationTag(ctx.state, ctx.cardDb, target, tag, ctx.state.turnNumber);
    },
  };
}
