// Odavast -- "Ice Wall": "Your frozen Creatures lose two less energy in attacks." Reduces what a
// frozen Creature under Odavast's control loses on either side of combat (attacker or defender),
// floored at 0 -- same "reduce the locked value that determines THIS side's own loss" shape as
// polarEebit.ts's cap. The other printed clause ("Each of your non-Nar, non-Universal cards costs
// one additional energy to play.") is narSurcharge.ts's shared helper (2026-07-11).

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { isFrozen } from '../durationTags.js';
import { narSurcharge } from './narSurcharge.js';

registerCardEffect('Odavast', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Only Ice Wall is named; the narSurcharge clause
  // is unnamed and Taglat's pool skips unnamed effects.
  effectHooks: {
    'Ice Wall': ['onAttack'],
  },
  onAttack: (ctx, self) => {
    if (ctx.attacker.controllerId === self.controllerId && isFrozen(ctx.state, ctx.cardDb, ctx.attacker)) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = Math.max(0, ctx.locked.defenderEnergy - 2);
    }
    if (ctx.defender !== null && ctx.defender.controllerId === self.controllerId && isFrozen(ctx.state, ctx.cardDb, ctx.defender)) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.max(0, ctx.locked.attackerEnergy - 2);
    }
  },
  costModifier: narSurcharge,
});
