// Shard of the Great Fossil -- "Shield (2): Choose one of your Creatures with the effect
// 'Invulnerability'. The chosen Creature loses no energy in attacks until the end of the turn."
// Same NO_ENERGY_LOST_IN_ATTACKS duration tag as Vaal/Parmalag's own Shield. Target pool checks
// the printed Effect by name (cardDb), same trick Targ'n/Celebrated Hero already use.
//
// EXCLUDES Rock Hyren specifically: granting total attack immunity is itself a way of "preventing
// Rock Hyren from losing energy," which its own text explicitly forbids beyond its printed -2 --
// confirmed with the project owner 2026-07-11, see rockHyren.ts's doc comment for the full
// reasoning (same exclusion as Targ'n's Enhanced Invulnerability).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addDurationTag, NO_ENERGY_LOST_IN_ATTACKS } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';

function printsInvulnerability(cardDb: CardDatabase, key: number): boolean {
  const def = cardDb.get(key);
  if (def?.name === 'Rock Hyren') return false;
  return def?.effects?.some((e) => e.name === 'Invulnerability') ?? false;
}

registerCardEffect('Shard of the Great Fossil', {
  powerTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => printsInvulnerability(cardDb, c.definitionKey)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shield') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!printsInvulnerability(ctx.cardDb, target.definitionKey)) return;

    addDurationTag(ctx.state, ctx.cardDb, target, NO_ENERGY_LOST_IN_ATTACKS, ctx.state.turnNumber, ctx.source.instanceId);
  },
});
