// Yark Gloves -- "Deplete: Once per turn, when one of your Kybar's Teeth Creatures is attacked by
// a non-Kybar's Teeth Creature that has more than its starting energy, before energy is removed,
// you may reduce the attacking Creature to its starting energy." Real energy set ->
// onBeforeEnergyRemoved, once-per-turn guard, "may" auto-taken.

import { registerCardEffect } from './registry.js';
import { restoreEnergy } from '../effects.js';
import { effectiveRegions, effectiveStartingEnergy } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const USED_THIS_TURN = 'yarkGlovesUsedThisTurn';

registerCardEffect('Yark Gloves', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes("Kybar's Teeth")) return;
    if (effectiveRegions(ctx.state, ctx.cardDb, ctx.attacker).includes("Kybar's Teeth")) return;
    const attackerStart = effectiveStartingEnergy(ctx.state, ctx.cardDb, ctx.attacker);
    if ((ctx.attacker.currentEnergy ?? 0) <= attackerStart) return;
    if (hasDurationTag(self, USED_THIS_TURN)) return;
    restoreEnergy(ctx.state, ctx.cardDb, ctx.attacker, attackerStart);
    addDurationTag(ctx.state, ctx.cardDb, self, USED_THIS_TURN, ctx.state.turnNumber);
  },
});
