/**
 * The effective metadata for one prompt: whatever the card's own prompt function returned wins
 * (that is the escape hatch for dynamic cases), then this table, then the safe default of
 * mandatory-and-unsorted.
 */
export function resolvePendingChoiceMeta(
  cardName: string | undefined,
  familyName: string,
  returned: PendingChoiceMeta | undefined
): Required<Pick<PendingChoiceMeta, 'optional'>> & PendingChoiceMeta {
  const fromTable =
    (cardName ? PROMPT_META[`${cardName}|${familyName}`] : undefined) ??
    (cardName ? PROMPT_META[cardName] : undefined);
  return {
    optional: returned?.optional ?? fromTable?.optional ?? false,
    intent: returned?.intent ?? fromTable?.intent,
  };
}

/**
 * Intent for a card's MAIN target pool, by card name alone.
 *
 * Exists because the pending-choice families are not the only prompts that pick a target. A Spell's
 * or Power's own `targets` pool is built by spellTargets/powerTargets and rendered straight by the
 * UI, which never passed through resolvePendingChoiceMeta -- so ordering silently did nothing there
 * (found in playtest 2026-07-25: Sunbeam's End, which ADDS energy, listed opposing Creatures first).
 *
 * Same table, same defaults: unknown card -> undefined -> pool left untouched.
 */
export function targetPoolIntent(cardName: string | undefined): PendingChoiceMeta['intent'] {
  if (!cardName) return undefined;
  return PROMPT_META[cardName]?.intent;
}

/**
 * Orders a prompt's pool so the likeliest target comes first, per the owner's requested heuristic
 * (2026-07-25): a BENEFICIAL effect leads with the chooser's own cards, weakest first (the one most
 * in need of the energy); a HARMFUL one leads with opponents' cards, strongest first (the biggest
 * threat). Returns the pool untouched when `intent` is undefined.
 *
 * PURELY COSMETIC. This is a display order, not a filter -- every card in the pool stays selectable,
 * and nothing about legality or resolution depends on the order. A wrong guess costs the player one
 * extra scroll, never a legal option.
 *
 * A stable copy is returned rather than sorting in place: the caller's array is often a live
 * `player.inPlay` slice, and reordering the real zone would be a genuine state bug.
 */
export function sortPoolByIntent<T extends CardInstance>(
  pool: readonly T[],
  intent: PendingChoiceMeta['intent'],
  chooserPlayerId: PlayerId
): T[] {
  if (!intent) return [...pool];
  const ownFirst = intent === 'beneficial';
  return [...pool].sort((a, b) => {
    const aOwn = a.controllerId === chooserPlayerId;
    const bOwn = b.controllerId === chooserPlayerId;
    if (aOwn !== bOwn) return aOwn === ownFirst ? -1 : 1;
    const aEnergy = a.currentEnergy ?? 0;
    const bEnergy = b.currentEnergy ?? 0;
    return ownFirst ? aEnergy - bEnergy : bEnergy - aEnergy;
  });
}
