// Rayje -- "You can play with more than one copy of Rayje in your deck. When you reveal Rayje, he
// gains all Powers and Effects on all of your defeated Rayjes and any one other of the following
// Powers or Effects until the end of the game: Aid (Power: move one energy from one Creature to
// another), Lore (draw an extra card during your Draw step), Defense (when one of your Creatures is
// attacked, add one energy to it before energy is removed), Wily (once per turn, instead of drawing
// a card, place any one Universal Spell from your discard pile into your hand), Charge (when one of
// your Creatures attacks, add one energy to it before energy is removed)."
//
// The multi-copy deck rule is handled in deck.ts (allowsMultipleInMagiStack). Here: each option a
// Rayje holds is a permanent tag (`rayjeGrant:X`). On reveal, Rayje inherits the UNION of grant tags
// from all defeated Rayjes (defeatedMagi, Pok precedent) and arms a reveal menu (pendingCategoryChoice)
// to pick one more it doesn't yet hold. Only the ACTIVE Rayji's hooks fire (defeated Magi aren't
// broadcast to), so the revealed Rayje applies the whole accumulated set. Each option's build:
//   Lore   -> drawCountModifier +1, gated on the tag.
//   Defense/Charge -> onBeforeEnergyRemoved broadcast (reaches Magi, runs pre-damage), gated.
//   Aid    -> granted as a copiedPower whose fromDefinitionKey is Rayje's own key, so it dispatches
//             back to this file's resolvePower; a 2-slot picker (from-Creature, to-Creature) drives
//             rearrangeEnergy.
//   Wily   -> reactive on the controller's own draw (Artimillies' onAnyCardDrawn + pending-choice
//             shape). "Instead of drawing" is modelled as: undo the just-drawn card (return it to the
//             top of the deck) and take a chosen Universal Spell from the discard instead -- so the
//             deck is left untouched, exactly like never drawing. Once per turn; not phase-locked.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingRevealChoiceTag, removePermanentTag, addDurationTag, hasDurationTag } from '../durationTags.js';
import { addEnergy, rearrangeEnergy, retrieveFromDiscardPile, checkHandEmptied } from '../effects.js';
import { addCopiedPower } from '../copiedPowers.js';
import { allCreaturesInPlay } from '../targeting.js';
import { removeFromZone, addToZone } from '../zones.js';
import { isUniversal } from '../regions.js';
import type { CardDatabase, Power } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const GRANT_PREFIX = 'rayjeGrant:';
const OPTIONS = ['Aid', 'Lore', 'Defense', 'Wily', 'Charge'] as const;
const AWAITING = 'rayjeAwaitingChoice';
const WILY_USED = 'rayjeWilyUsedThisTurn';
const WILY_PENDING_PREFIX = 'rayjeWilyPending:';
const AID_POWER: Power = { name: 'Aid', cost: 0, text: 'Move one energy from one Creature to another.' };

function hasGrant(self: CardInstance, name: string): boolean {
  return self.tags.has(GRANT_PREFIX + name);
}
function heldGrants(self: CardInstance): Set<string> {
  const set = new Set<string>();
  for (const t of self.tags) if (t.startsWith(GRANT_PREFIX)) set.add(t.slice(GRANT_PREFIX.length));
  return set;
}
function grantOption(state: GameState, cardDb: CardDatabase, self: CardInstance, name: string): void {
  if (hasGrant(self, name)) return; // idempotent -- reveal can re-fire on succession checks
  addPermanentTag(state, cardDb, self, GRANT_PREFIX + name);
  if (name === 'Aid') addCopiedPower(self, AID_POWER, self.definitionKey); // dispatches to Rayje's own resolvePower
}
function wilyPendingDrawnId(self: CardInstance): string | undefined {
  for (const t of self.tags) if (t.startsWith(WILY_PENDING_PREFIX)) return t.slice(WILY_PENDING_PREFIX.length);
  return undefined;
}
function universalSpellsInDiscard(state: GameState, cardDb: CardDatabase, playerId: string): CardInstance[] {
  const player = state.players.get(playerId);
  if (!player) return [];
  return player.discardPile.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return def?.card_type === 'Spell' && isUniversal(def.regions);
  });
}

registerCardEffect('Rayje', {
  onMagiRevealed: (state, cardDb, revealedMagi, self) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    for (const magi of owner.defeatedMagi) {
      if (cardDb.get(magi.definitionKey)?.name !== 'Rayje') continue;
      for (const t of magi.tags) if (t.startsWith(GRANT_PREFIX)) grantOption(state, cardDb, self, t.slice(GRANT_PREFIX.length));
    }
    const held = heldGrants(self);
    if (OPTIONS.some((o) => !held.has(o))) addPendingRevealChoiceTag(self, AWAITING); // "any one other" -- pick a new one
  },

  pendingCategoryChoice: (state, cardDb, self) => {
    if (self.tags.has(AWAITING)) {
      const held = heldGrants(self);
      const options = OPTIONS.filter((o) => !held.has(o));
      if (options.length === 0) return undefined;
      return { prompt: 'Rayje: choose one Power or Effect to gain for the rest of the game', options };
    }
    if (wilyPendingDrawnId(self)) {
      const names = [...new Set(universalSpellsInDiscard(state, cardDb, self.controllerId).map((s) => cardDb.get(s.definitionKey)!.name))];
      if (names.length === 0) return undefined;
      return { prompt: "Rayje's Wily: put the card you just drew back and take a Universal Spell from your discard instead? (choose one, or decline)", options: names };
    }
    return undefined;
  },
  resolveCategoryChoice: (state, cardDb, self, chosen, rng) => {
    if (self.tags.has(AWAITING)) {
      removePermanentTag(self, AWAITING);
      if (chosen && (OPTIONS as readonly string[]).includes(chosen)) grantOption(state, cardDb, self, chosen);
      return;
    }
    const drawnId = wilyPendingDrawnId(self);
    if (drawnId) {
      removePermanentTag(self, WILY_PENDING_PREFIX + drawnId);
      if (!chosen) return; // declined -> keep the draw
      const owner = state.players.get(self.controllerId);
      if (!owner) return;
      const spell = universalSpellsInDiscard(state, cardDb, self.controllerId).find((s) => cardDb.get(s.definitionKey)!.name === chosen);
      if (!spell) return;
      const drawn = owner.hand.find((c) => c.instanceId === drawnId);
      if (drawn) {
        removeFromZone(owner, 'hand', drawnId);
        addToZone(owner, 'deck', drawn, 'top'); // "instead of drawing" -- deck left as it was
      }
      retrieveFromDiscardPile(state, owner, spell.instanceId, 'hand');
      checkHandEmptied(state, cardDb, rng);
    }
  },

  // Lore
  drawCountModifier: (_state, _cardDb, self) => (hasGrant(self, 'Lore') ? 1 : 0),

  // Defense + Charge -- add 1 energy to your combatant before energy is removed
  onBeforeEnergyRemoved: (ctx, self) => {
    if (hasGrant(self, 'Defense') && ctx.defender && ctx.defender.controllerId === self.controllerId) {
      addEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect');
    }
    if (hasGrant(self, 'Charge') && ctx.attacker.controllerId === self.controllerId) {
      addEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect');
    }
  },

  // Wily -- arm on the controller's own draw (once per turn)
  onAnyCardDrawn: (state, cardDb, self, drawingPlayerId, drawnCard) => {
    if (!hasGrant(self, 'Wily') || drawingPlayerId !== self.controllerId) return;
    if (hasDurationTag(self, WILY_USED)) return;
    if (universalSpellsInDiscard(state, cardDb, self.controllerId).length === 0) return;
    addDurationTag(state, cardDb, self, WILY_USED, state.turnNumber);
    addPermanentTag(state, cardDb, self, WILY_PENDING_PREFIX + drawnCard.instanceId);
  },

  // Aid (granted copiedPower dispatches here) -- move 1 energy between two chosen Creatures
  powerTargetSlots: (_state, _cardDb, _playerId, powerName) => {
    if (powerName !== 'Aid') return [];
    return [
      { label: 'Move one energy FROM this Creature', pool: (s: GameState, db: CardDatabase) => allCreaturesInPlay(s, db).filter((c) => (c.currentEnergy ?? 0) > 0), min: 1, max: 1 },
      { label: 'Move one energy TO this Creature', pool: (s: GameState, db: CardDatabase) => allCreaturesInPlay(s, db), min: 1, max: 1 },
    ];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Aid') return;
    const fromId = ctx.chosenSlotIds?.[0]?.[0];
    const toId = ctx.chosenSlotIds?.[1]?.[0];
    if (!fromId || !toId || fromId === toId) return;
    const from = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === fromId);
    const to = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === toId);
    if (!from || !to) return;
    rearrangeEnergy(ctx.state, ctx.cardDb, from, to, 1, ctx.rng);
  },
});
