// Thast -- both printed pieces:
//   "Ice Grinder (2): Choose any one Creature in play. Discard energy from the chosen Creature
//   equal to Thast's Energize."
//   "Invigorate: Increase Thast's Energize by one for each of your frozen Nar Creatures."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, creaturesControlledBy, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { isFrozen } from '../durationTags.js';
import { effectiveEnergizeRate } from '../turn.js';

registerCardEffect('Thast', {
  // Per-Effect hook narrowing (2026-08-13 Batch A closure: Wind Hyren Invigorate cap). The
  // Invigorate entry mapping `energizeRateModifier` is what lets turn.ts's `effectiveEnergizeRate`
  // identify this as an Invigorate-named contribution eligible for Wind Hyren's global "only the
  // highest applies" cap.
  effectHooks: {
    'Ice Grinder': ['resolvePower'],
    Invigorate: ['energizeRateModifier'],
  },
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Ice Grinder') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;

    // Uses the EFFECTIVE rate (including Invigorate's own bonus below), not just the printed
    // stat -- "equal to Thast's Energize" means whatever Thast's Energize currently is.
    const amount = effectiveEnergizeRate(ctx.state, ctx.cardDb, ctx.source);
    discardEnergy(ctx.state, ctx.cardDb, target, amount, undefined, undefined, ctx.rng);
  },
  energizeRateModifier: (state, cardDb, energizing, self) => {
    if (energizing.instanceId !== self.instanceId) return 0;
    return creaturesControlledBy(state, cardDb, self.controllerId).filter(
      (c) => isFrozen(state, cardDb, c) && effectiveRegions(state, cardDb, c).includes('Nar')
    ).length;
  },
});
