// Kybar's Scroll -- "Lore (2): Roll one die. Look at that number of cards from the top of your
// deck. Put one of those cards into your hand and shuffle the rest into your deck." Rolls
// directly in resolvePower (same shape as Great Pool of Wisdom's Stagnant Energy) rather than
// using the declarative deckTopReveal field, since that field's reveal `count` is resolved before
// the UI prompt opens and has no existing way to depend on a die roll made during resolution.
// Which of the revealed cards goes to hand is unspecified by any real prompt at this trigger
// point -- auto-picks the first (top) of the revealed cards; since the top card is always within
// the revealed pool regardless of the roll's size (a die never rolls 0), the roll only needs to
// be made (for flavor/logging), not consulted.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724). Note: Whimsy interception on
// this roll is effectively cosmetic given the auto-pick simplification -- kept for consistency
// with every other die-roll site being interceptable.

import { registerCardEffect } from './registry.js';
import { requestDieRoll, searchDeck } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { getPlayer } from '../types/state.js';

registerCardEffect("Kybar's Scroll", {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Lore') return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'kybarsScroll:lore',
      { controllingPlayerId: ctx.controllingPlayer.playerId },
      ctx.rng
    );
  },
});

registerRollConsumer('kybarsScroll:lore', (state, _cardDb, _source, payload, _finalRoll, rng) => {
  const { controllingPlayerId } = payload as { controllingPlayerId: string };
  const controllingPlayer = getPlayer(state, controllingPlayerId);
  const topCard = controllingPlayer.deck[0];
  if (!topCard) return;
  searchDeck(state, controllingPlayer, [topCard.instanceId], rng);
});
