// Sprout (Weave Spell, cost 2) -- "Choose an opposing Magi. Add one energy to your Magi for each
// of the chosen Magi's Creatures in play."
//
// Weave Spell pass (2026-07-26), Category A. Two-player reality means there is only ever one
// opposing Magi, but the choice is still modelled properly via spellTargets rather than auto-picked
// -- the project's standing rule after task #42c's "no-prompt auto-pick" sweep, and it costs
// nothing here. Counts the CHOSEN Magi's controller's Creatures, not "all opposing Creatures", so
// it stays correct if a third player ever exists.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { opposingMagi, creaturesControlledBy, findCreatureOrMagiById } from '../targeting.js';

registerCardEffect('Sprout', {
  spellTargets: (state, cardDb, playerId) => opposingMagi(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const chosen = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosen) return;
    const count = creaturesControlledBy(ctx.state, ctx.cardDb, chosen.controllerId).length;
    const ownMagi = ctx.controllingPlayer.activeMagi;
    if (ownMagi && count > 0) addEnergy(ctx.state, ctx.cardDb, ownMagi, count, 'spell');
  },
});
