// Quor -- only "Battering Ram" is built here: "When Quor attacks an opposing Creature, discard
// two energy from that Creature's Magi." Self as the attacker, Creature-defender only (not a
// direct Magi attack) -- targets the DEFENDING player's Magi, not the Creature itself.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Quor', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    const magi = ctx.defendingPlayer.activeMagi;
    if (!magi) return;

    discardEnergy(ctx.state, ctx.cardDb, magi, 2, 'effect', undefined, ctx.rng);
  },
});
