// Barreling Vemment -- "One-Two (1): Choose a Creature. Remove one energy from that Creature for
// each Vemment you control." "Vemment" is a naming family (Barreling Vemment + plain "Vemment"),
// matched by substring like Chogus/Xyx elsewhere -- Barreling Vemment counts itself.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, creaturesControlledBy, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Barreling Vemment', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn (see flexibleTargetPool's doc).
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'One-Two') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    const vemmentCount = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter((c) =>
      ctx.cardDb.get(c.definitionKey)?.name.includes('Vemment')
    ).length;
    discardEnergy(ctx.state, ctx.cardDb, target, vemmentCount, undefined, undefined, ctx.rng);
  },
});
