// Scyalla (Weave Magi) -- "Pet Project (Power): Once per game, choose any non-Hyren Creature type.
// Until the end of the game, you may play Creatures of that type as if they were Weave, and all
// Creatures of the chosen type that you play are Weave Creatures instead of their original region."
// Built in the Weave region pass #49, Category C.
//
// "Creature type" = the name-family convention this codebase already uses (targeting.ts's
// creatureType = the last word of the name: Hyren, Korrit, Furok, ...), same as the Korrit pass.
//
// Mechanism reuse:
//   - The pick is a real pendingCategoryChoice/resolveCategoryChoice (Sarazen Outcast / Bria / Niffer
//     shape), armed by the Power and stored in CardInstance.persistentCategoryChoice. Options are the
//     distinct non-Hyren Creature types in the controller's deck/hand/in-play (the types they could
//     actually play), same rational deck-scan approach as Bria.
//   - "Once per game" -> the Power is SPENT on activation: resolvePower stamps a permanent
//     CANNOT_USE_POWER tag on Scyalla (her only Power), which power.ts's isLegalPowerUse honors, so
//     it can never be used again this game (stronger than the default once-per-turn gate).
//   - "play ... as if they were Weave" -> regionOverride (Sorrowing Ogar / Bria shape) lets the
//     controller play a Creature of the chosen type ignoring regional restrictions.
//   - "are Weave Creatures instead of their original region" -> onPlay stamps a permanent
//     effectiveRegionOverride = { region: 'Weave' } on each such Creature (Ruid's Mutate / Yog's Turn
//     shape).

import { registerCardEffect } from './registry.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import { creatureType } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag, CANNOT_USE_POWER } from '../durationTags.js';

const AWAITING_CHOICE = 'scyallaPetProjectAwaitingChoice';

function petProjectTypeOptions(state: GameState, cardDb: CardDatabase, self: CardInstance): string[] {
  const player = state.players.get(self.controllerId);
  const types = new Set<string>();
  if (player) {
    for (const zone of [player.deck, player.hand, player.inPlay]) {
      for (const card of zone) {
        if (cardDb.get(card.definitionKey)?.card_type !== 'Creature') continue;
        const t = creatureType(cardDb, card.definitionKey);
        if (t !== 'Hyren') types.add(t);
      }
    }
  }
  return [...types];
}

registerCardEffect('Scyalla', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Pet Project') return;
    addPendingChoiceTag(ctx.source, AWAITING_CHOICE);
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, CANNOT_USE_POWER); // "Once per game" -- spent on activation
  },
  pendingCategoryChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const options = petProjectTypeOptions(state, cardDb, self);
    if (options.length === 0) return undefined;
    return { prompt: "Scyalla's Pet Project: choose a non-Hyren Creature type to play as Weave", options };
  },
  resolveCategoryChoice: (state, cardDb, self, chosen) => {
    removePermanentTag(self, AWAITING_CHOICE);
    if (chosen && chosen !== 'Hyren') self.persistentCategoryChoice = chosen;
  },
  regionOverride: (_state, cardDb, playedDef, _magi, contributor) =>
    contributor.persistentCategoryChoice !== null &&
    playedDef.card_type === 'Creature' &&
    creatureType(cardDb, playedDef.key) === contributor.persistentCategoryChoice,
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (self.persistentCategoryChoice === null) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (creatureType(cardDb, played.definitionKey) !== self.persistentCategoryChoice) return;
    played.effectiveRegionOverride = { region: 'Weave' }; // permanent -- "until the end of the game"
  },
});
