// Gorath -- "Enslave (X): Choose any one Creature in play with less than X energy. Gain control
// of the chosen Creature. The chosen Creature may not attack this turn. If Gorath leaves play,
// return all Creatures Enslaved by Gorath to their owners' control."
//
// Same "target pool is unfiltered by X, resolvePower validates the supplied X against the
// target's own current energy and fizzles otherwise" shape as Zet's Treachery (X isn't freely
// computable at pool time -- registry.ts's powerTargets doc comment confirms it never receives
// chosenXValue) + Darkbreed Hyren's plain gainControl/CANNOT_ATTACK pattern for the control-grab
// itself. The revert-on-leaving-play clause is new (task #35, 2026-07-16): CardInstance.
// gainedControlOf tracks which creatures THIS specific Gorath enslaved, read back by its own
// self-reactive onCardDiscardedFromPlay to return each still-in-play one to its owner
// (gainControl leaves `ownerId` untouched, so `target.ownerId` is always the right destination).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { gainControl } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Gorath', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Enslave') return;
    if (ctx.chosenTargetId === undefined || ctx.chosenXValue === undefined) return;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    if ((target.currentEnergy ?? 0) >= ctx.chosenXValue) return;

    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);
    ctx.source.gainedControlOf.push(target.instanceId);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return; // Gorath itself just left play
    for (const instanceId of self.gainedControlOf) {
      const target = findInPlayById(state, instanceId);
      if (target) gainControl(state, cardDb, target, target.ownerId);
    }
    self.gainedControlOf = [];
  },
});
