// Quido Swarm -- two printed clauses:
//   "Calling: Quido Swarm's starting energy is equal to the number of your other Paradwyn and
//   Bograth Creatures in play." -- fixedXValue, computed at play time (self is still in hand, not
//   yet counted among "your other" Creatures).
//   "Swarm: At the beginning of each of your turns, restore Quido Swarm to its starting energy."
//   -- onOwnTurnStart, recomputing the SAME Calling formula fresh (the count can have changed
//   since Quido Swarm was played) and restoring to that live value.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { restoreEnergy } from '../effects.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { PlayerId } from '../types/state.js';
import type { CardInstance } from '../types/instance.js';

function callingCount(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  excludeInstanceId?: string
): number {
  return creaturesControlledBy(state, cardDb, playerId).filter((c) => {
    if (c.instanceId === excludeInstanceId) return false;
    const def = cardDb.get(c.definitionKey);
    return def?.regions.some((r) => r === 'Paradwyn' || r === 'Bograth');
  }).length;
}

registerCardEffect('Quido Swarm', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Calling owns the play-time fixedX
  // starting-energy formula. Swarm owns the turn-start re-restore.
  effectHooks: {
    Calling: ['fixedXValue'],
    Swarm: ['onOwnTurnStart'],
  },
  fixedXValue: (state, cardDb, playerId) => callingCount(state, cardDb, playerId),
  onOwnTurnStart: (state, cardDb, self: CardInstance) => {
    const count = callingCount(state, cardDb, self.controllerId, self.instanceId);
    restoreEnergy(state, cardDb, self, count);
  },
});
