// Lasada, Emissary -- "Diplomacy: After Lasada, Emissary is defeated, choose up to one Relic, one
// Spell and one Creature in your discard pile and add them to your hand. Discard a card for each
// non-Arderial card you added to your hand in this way."
//
// Three INDEPENDENT, each-optional choices -- reuses the existing single-choice
// pendingTargetChoice/resolveTargetChoice mechanism three times in sequence (Relic, then Spell,
// then Creature) rather than building a new multi-slot pending mechanism: all three tags are
// marked simultaneously by onOwnMagiDefeated, `pendingTargetChoice` returns whichever ONE is
// still pending (checked in a fixed priority order), and `resolveTargetChoice` re-derives that
// SAME "which one is pending" order to know which tag to clear -- safe since the UI always calls
// pendingTargetChoice immediately before showing a prompt and resolveTargetChoice immediately
// after, with no other action able to interleave in this single-threaded engine. Needed
// attachedCards.ts's findPendingTargetChoices to be widened to scan `defeatedMagi` too (2026-07-12)
// since Lasada, Emissary herself is sitting there, not in inPlay/hand, by the time this fires.
// "Discard a card for each non-Arderial card added" has no specified choice of WHICH card to
// discard -- same "first eligible in hand order" simplification as Elios/Adis, excluding the
// just-added card itself.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { retrieveFromDiscardPile, discardFromHand } from '../effects.js';
import type { CardInstance } from '../types/instance.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

const RELIC_PENDING = 'lasadaEmissaryRelicPending';
const SPELL_PENDING = 'lasadaEmissarySpellPending';
const CREATURE_PENDING = 'lasadaEmissaryCreaturePending';

function nextPendingSlot(self: CardInstance): { tag: string; cardType: 'Relic' | 'Spell' | 'Creature' } | undefined {
  if (self.tags.has(RELIC_PENDING)) return { tag: RELIC_PENDING, cardType: 'Relic' };
  if (self.tags.has(SPELL_PENDING)) return { tag: SPELL_PENDING, cardType: 'Spell' };
  if (self.tags.has(CREATURE_PENDING)) return { tag: CREATURE_PENDING, cardType: 'Creature' };
  return undefined;
}

registerCardEffect('Lasada, Emissary', {
  onOwnMagiDefeated: (state, cardDb, self) => {
    addPermanentTag(state, cardDb, self, RELIC_PENDING);
    addPermanentTag(state, cardDb, self, SPELL_PENDING);
    addPermanentTag(state, cardDb, self, CREATURE_PENDING);
  },
  pendingTargetChoice: (state: GameState, cardDb: CardDatabase, self) => {
    const slot = nextPendingSlot(self);
    if (!slot) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player) return undefined;
    const pool = player.discardPile.filter((c) => cardDb.get(c.definitionKey)?.card_type === slot.cardType);
    return {
      prompt: `Lasada, Emissary's Diplomacy: choose up to one ${slot.cardType} from your discard pile to add to your hand`,
      pool,
    };
  },
  resolveTargetChoice: (state: GameState, cardDb: CardDatabase, self, chosenInstanceId) => {
    const slot = nextPendingSlot(self);
    if (!slot) return;
    removePermanentTag(self, slot.tag);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const card = player.discardPile.find((c) => c.instanceId === chosenInstanceId && cardDb.get(c.definitionKey)?.card_type === slot.cardType);
    if (!card) return;
    const retrieved = retrieveFromDiscardPile(state, player, chosenInstanceId, 'hand');
    if (!retrieved) return;
    const isArderial = cardDb.get(retrieved.definitionKey)?.regions.includes('Arderial') ?? false;
    if (!isArderial) {
      const toDiscard = player.hand.find((c) => c.instanceId !== retrieved.instanceId);
      if (toDiscard) discardFromHand(state, cardDb, player, [toDiscard.instanceId]);
    }
  },
});
