// Shock Ring -- "Storm Seeker: After one of your Arderial Spells or Powers removes energy from
// one or more opposing Creatures, choose a Creature you control. Add one energy to it." Reuses
// task #27's onOwnPowerDiscardedOpposingEnergy hook directly (built for Amanax's Pyromaniac) --
// region-gated to Arderial instead of Cald, and unlike Amanax's fixed self-target and
// scaled-to-amount payout, this needs a real choice among the controller's own Creatures for a
// flat +1, so the trigger just marks a pending choice (same pendingTargetChoice/resolveTargetChoice
// shape as Garlak's Cold Burn) rather than applying the energy immediately. No "once per turn"
// qualifier is printed, but multiple triggers landing before the first choice resolves collapse
// into one pending choice (same simplification tradeoff accepted elsewhere for low-frequency
// stacking edge cases). Fires for both an Arderial Power AND an Arderial Spell (task #51,
// 2026-07-20 widened the underlying hook to also broadcast from Spell resolution).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const STORM_SEEKER_PENDING = 'shockRingStormSeekerPending';

registerCardEffect('Shock Ring', {
  onOwnPowerDiscardedOpposingEnergy: (state, cardDb, self, sourceCard) => {
    const sourceDef = cardDb.get(sourceCard.definitionKey);
    if (!sourceDef?.regions.includes('Arderial')) return;
    if (creaturesControlledBy(state, cardDb, self.controllerId).length === 0) return;
    addPendingChoiceTag(self, STORM_SEEKER_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(STORM_SEEKER_PENDING)) return undefined;
    const pool = creaturesControlledBy(state, cardDb, self.controllerId);
    if (pool.length === 0) return undefined;
    return { prompt: "Shock Ring's Storm Seeker: choose a Creature you control to add one energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, STORM_SEEKER_PENDING);
    if (!chosenInstanceId) return;
    const target = creaturesControlledBy(state, cardDb, self.controllerId).find((c) => c.instanceId === chosenInstanceId);
    if (target) addEnergy(state, cardDb, target, 1, 'effect');
  },
});
