// Sulfurous Spirit (Spell, cost 1, Cald Shadow Magi may play) -- "Choose any one of your Creatures
// in play. Discard the chosen Creature from play. Choose any one Creature in play. Discard four
// energy from the chosen Creature. Cald Shadow Magi may play Sulfurous Spirit." Cald Spell pass,
// Category A (2026-07-20). Same two-independent-picks abwynsGift.ts/gorglesGift.ts shape, roles
// reversed: first pick is a SACRIFICE (discardFromPlay, own Creatures only), second pick is the
// energy-loss target (discardEnergy, any Creature in play, either side). "Cald Shadow Magi may
// play" is 100% data-driven (shadow_play field), zero code needed -- already regression-tested per
// docs/deferred-card-mechanics.md.

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';

registerCardEffect('Sulfurous Spirit', {
  spellTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) =>
    allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== firstChosenId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined || ctx.chosenSecondTargetId === undefined) return;
    if (ctx.chosenTargetId === ctx.chosenSecondTargetId) return;
    const sacrificeTarget = findInPlayById(ctx.state, ctx.chosenTargetId);
    const energyTarget = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (!sacrificeTarget || sacrificeTarget.controllerId !== ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(sacrificeTarget.definitionKey)?.card_type !== 'Creature') return;
    if (!energyTarget || ctx.cardDb.get(energyTarget.definitionKey)?.card_type !== 'Creature') return;

    const owner = ctx.state.players.get(sacrificeTarget.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, sacrificeTarget.instanceId, undefined, undefined, ctx.rng);

    // The sacrifice can't BE the energy target (chosenTargetId !== chosenSecondTargetId checked
    // above), but re-verify it's still in play before discarding energy from it, same defensive
    // "stillThere" re-check gorglesGift.ts/abwynsGift.ts already use for the analogous case.
    const stillThere = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (stillThere) discardEnergy(ctx.state, ctx.cardDb, stillThere, 4, 'spell', undefined, ctx.rng);
  },
});
