// Muck Vinoc -- "Grapple: Choose any one Creature in play with seven or more energy. Discard Muck
// Vinoc and the chosen Creature from play."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Muck Vinoc', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => (c.currentEnergy ?? 0) >= 7),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Grapple') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if ((target.currentEnergy ?? 0) < 7) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    // The chosen Creature could have BEEN Muck Vinoc itself -- already gone from play now.
    const stillThere = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!stillThere) return;
    const owner = ctx.state.players.get(stillThere.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, stillThere.instanceId, undefined, undefined, ctx.rng);
  },
});
