// Celebrated Hero -- "Pump You Up: Choose a Burrowed Creature or a Creature with the Effect
// 'Invulnerability'. Restore the chosen Creature to its starting energy. Skip your Draw step this
// turn." "With the Effect 'Invulnerability'" is a printed-database check (cardDb's own effects
// array), same "does this card's data say it has effect X" trick Weave-woven Anklet/Targ'n
// already use -- doesn't require task #26 or any passive-effect system, just a data lookup. Target
// pool restricted to the controller's own Creatures (a purely beneficial restore effect).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById, effectiveStartingEnergy } from '../targeting.js';
import { restoreEnergy } from '../effects.js';
import { isBurrowed } from '../durationTags.js';

registerCardEffect('Celebrated Hero', {
  powerTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).filter(
      (c) => isBurrowed(state, cardDb, c) || (cardDb.get(c.definitionKey)?.effects?.some((e) => e.name === 'Invulnerability') ?? false)
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Pump You Up') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    const isValid =
      isBurrowed(ctx.state, ctx.cardDb, target) ||
      (ctx.cardDb.get(target.definitionKey)?.effects?.some((e) => e.name === 'Invulnerability') ?? false);
    if (!isValid) return;

    restoreEnergy(ctx.state, ctx.cardDb, target, effectiveStartingEnergy(ctx.state, ctx.cardDb, target));
    ctx.state.skipDrawStepThisTurn = true;
  },
});
