// Gravity (Spell) -- "Choose a Creature with more than its starting energy. Reduce that Creature
// to its printed starting energy." Kybar's Teeth Spell pass, Category A (2026-07-22). Any Creature
// either side, filtered to ones currently above printedStartingEnergy (so the picker never offers
// an already-legal-but-pointless target). resolveSpell re-checks the same condition and discards
// the delta via discardEnergy (cause 'spell'), same "compute the diff, route through the normal
// energy-loss pipeline" shape as Shrink.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, printedStartingEnergy, effectiveStartingEnergy } from '../targeting.js';

registerCardEffect('Gravity', {
  // "Choose a Creature with more than its STARTING energy" -- the eligibility filter is the
  // unqualified phrasing, so it reads the effective value (task #568, 2026-07-28).
  spellTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter(
      (c) => (c.currentEnergy ?? 0) > effectiveStartingEnergy(state, cardDb, c)
    ),
  resolveSpell: (ctx) => {
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    // "...Reduce that Creature to its PRINTED starting energy." Gravity is one of three cards that
    // use BOTH phrasings in one sentence, and the difference is live: a Dreamwarped or Dazzled
    // Creature qualifies on the effective value above but is still knocked all the way down to the
    // printed one here. Do not collapse these two reads back together.
    const starting = printedStartingEnergy(ctx.cardDb, target.definitionKey);
    const amount = (target.currentEnergy ?? 0) - starting;
    if (amount > 0) discardEnergy(ctx.state, ctx.cardDb, target, amount, 'spell', undefined, ctx.rng);
  },
});
