// Uwamar -- all three printed effects:
//   "Wait: Uwamar cannot attack." (permanent tag applied on entry, via onPlay)
//   "Watch: Whenever you play any other Weave Creature, add two energy to Uwamar."
//   "Weave: Whenever Uwamar is attacked, before energy is removed, you may move one energy
//   between it and one of your other Weave Creatures in play." (defend-only -- see weave.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag, CANNOT_ATTACK } from '../durationTags.js';
import { applyWeave } from './weave.js';

registerCardEffect('Uwamar', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Wait (self-CANNOT_ATTACK on entry) and
  // Watch (per-other-Weave-play buff) share the same fused `onPlay` body -- listed under both.
  // Weave is the defend-only move hook + `weaveConfig`.
  effectHooks: {
    Wait: ['onPlay'],
    Watch: ['onPlay'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) {
      addPermanentTag(state, cardDb, self, CANNOT_ATTACK);
      return;
    }
    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Creature' || !playedDef.regions.includes('Weave')) return;
    addEnergy(state, cardDb, self, 2, 'effect');
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'defendOnly' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave'], 'defendOnly'),
});
