// Twisted Dreams (Spell, Core) -- "Choose a Power on an opposing Creature. Remove energy from that
// Creature equal to the cost of the chosen Power (X equals zero)." Task #53-4, 2026-07-21, the Core
// Spell pass's A1 quick wins.
//
// "Choose a Power on a [card]" is already a fully built mechanism -- registry.ts's `copyPowerChoice`
// (Nahara/Taglat precedent, widened task #50 to also fire from the Spell-play path via
// sorreahsDream.ts) offers a pool of {card, power} pairs and encodes the answer as a composite
// `${card.instanceId}::${power.name}` chosenTargetId, no new UI plumbing needed. Twisted Dreams
// reuses the exact same picker, just scoped to the OPPOSING side's Creatures only (not Magi, not own
// side, unlike Sorreah's Dream's unrestricted pool) -- and instead of copying the Power, discards
// energy from the target equal to the Power's own printed cost. "(X equals zero)" reuses power.ts's
// own `resolveVariableCost(cost, 0)`, the same "X"/"X+N" parsing already used for a chosen-X-value
// Power, evaluated at X=0 here since no X is ever actually chosen.

import { registerCardEffect } from './registry.js';
import type { CardInstance } from '../types/instance.js';
import type { Power } from '../types/card.js';
import { findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { resolveVariableCost } from '../power.js';

registerCardEffect('Twisted Dreams', {
  copyPowerChoice: {
    pool: (state, cardDb, playerId) => {
      const result: Array<{ card: CardInstance; power: Power }> = [];
      for (const player of state.players.values()) {
        if (player.playerId === playerId) continue;
        for (const card of player.inPlay) {
          const def = cardDb.get(card.definitionKey);
          if (def?.card_type !== 'Creature') continue;
          for (const power of def.powers ?? []) {
            result.push({ card, power });
          }
        }
      }
      return result;
    },
  },
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const [cardInstanceId, powerName] = ctx.chosenTargetId.split('::');
    if (!cardInstanceId || !powerName) return;
    const target = findCreatureOrMagiById(ctx.state, cardInstanceId);
    if (!target || target.controllerId === ctx.controllingPlayer.playerId) return;
    const targetDef = ctx.cardDb.get(target.definitionKey);
    if (targetDef?.card_type !== 'Creature') return;
    const power = targetDef.powers.find((p) => p.name === powerName);
    if (!power) return;

    let amount: number;
    if (power.cost === undefined || power.cost === null) {
      amount = 0;
    } else if (typeof power.cost === 'number') {
      amount = power.cost;
    } else {
      amount = resolveVariableCost(power.cost, 0);
    }
    if (amount <= 0) return;
    discardEnergy(ctx.state, ctx.cardDb, target, amount, 'spell', undefined, ctx.rng);
  },
});
