// Primat -- "Kindle: Discard Primat from play. Discard from play each Creature with one energy.
// Discard from play each Naroom Creature with two energy." No target -- self-sacrifice then two
// filtered sweeps. Snapshots each sweep's matches into a plain array BEFORE discarding, since
// discardFromPlay mutates the very in-play lists allCreaturesInPlay reads from.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Primat', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Kindle') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const oneEnergy = allCreaturesInPlay(ctx.state, ctx.cardDb).filter((c) => (c.currentEnergy ?? 0) === 1);
    for (const creature of oneEnergy) {
      const owner = ctx.state.players.get(creature.controllerId);
      if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, creature.instanceId, undefined, undefined, ctx.rng);
    }

    const naroomTwoEnergy = allCreaturesInPlay(ctx.state, ctx.cardDb).filter(
      (c) => (c.currentEnergy ?? 0) === 2 && effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, 'Naroom'))
    );
    for (const creature of naroomTwoEnergy) {
      const owner = ctx.state.players.get(creature.controllerId);
      if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, creature.instanceId, undefined, undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (The "each Creature with one energy" clause has no region
  // gate -- only the Naroom clause is in scope.)
  specifiedTargetRegions: () => ['Naroom'],
});
