// Bulabantu -- "Ambush: When you play Bulabantu, choose a Creature. Discard three energy from
// the chosen Creature."
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first eligible in array order"
// simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice), same pattern as gumph.ts's Night's Shade.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const AMBUSH_PENDING = 'bulabantuAmbushPending';

registerCardEffect('Bulabantu', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, AMBUSH_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AMBUSH_PENDING)) return undefined;
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Bulabantu's Ambush: choose a Creature to discard 3 energy from", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, AMBUSH_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 3, 'effect', undefined, rng);
  },
});
