// Orathan Flyer -- both printed clauses:
//   "Summoning": "When your Magi plays a Creature, he or she may use energy from Orathan Flyer to
//   pay for the Creature. The Creature's entire energy cost must be paid by Orathan Flyer." New
//   task #29 redirectsPlayCostFrom hook -- see registry.ts's doc comment for the "may" ->
//   auto-applied-when-possible simplification.
//   "Caution": "Orathan Flyer may not attack." Permanent CANNOT_ATTACK, applied on entry.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, CANNOT_ATTACK } from '../durationTags.js';

registerCardEffect('Orathan Flyer', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Caution's `onPlay` self-tags CANNOT_ATTACK
  // on entry; Summoning is the cost-redirect for own-Magi Creature plays. Both are single-hook
  // Effects with no overlap -- either narrows cleanly.
  effectHooks: {
    Caution: ['onPlay'],
    Summoning: ['redirectsPlayCostFrom'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) addPermanentTag(state, cardDb, self, CANNOT_ATTACK);
  },
  redirectsPlayCostFrom: (state, cardDb, self, playedDef, playerId, totalCost) => {
    if (playerId !== self.controllerId) return false;
    if (playedDef.card_type !== 'Creature') return false;
    return (self.currentEnergy ?? 0) >= totalCost;
  },
});
