// Poad -- "Heroes' Feast (2): Add one energy to each of your Creatures in play."

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Poad', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Heroes' Feast") return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
    }
  },
});
