// Warlum -- "Materialize: Choose any one player. Discard Warlum from play. Search the chosen
// player's deck for any one Relic that you can normally play and play it without paying any
// costs. Shuffle the deck. Arderial and Orothe Shadow Magi may play Warlum." First deckSearch
// user needing an opponent's (or any player's) deck as the search target -- registry.ts's
// deckSearch widened this pass (task #29, 2026-07-15) to support `whoseDeck: 'target'`, same
// Magi-proxy pattern deckTopReveal/discardPileSearch already use. "You can normally play" is
// checked against the SEARCHING player's own Magi via regions.ts's checkRegionLegality, not the
// target's. "Without paying any costs" is naturally satisfied by effects.ts's playFromZone, which
// never charges anything regardless of what startingEnergy is passed. Shadow Magi eligibility
// note ("Arderial and Orothe Shadow Magi may play Warlum") needs no code -- a play-legality note
// about Warlum ITSELF, not a gameplay Effect.

import { registerCardEffect } from './registry.js';
import type { GameState } from '../types/state.js';
import type { CardInstance } from '../types/instance.js';
import { checkRegionLegality, effectiveMagiDef } from '../regions.js';
import { discardFromPlay, playFromZone } from '../effects.js';
import { shuffleDeck } from '../zones.js';

function allMagiInPlay(state: GameState): CardInstance[] {
  const result: CardInstance[] = [];
  for (const player of state.players.values()) {
    if (player.activeMagi) result.push(player.activeMagi);
  }
  return result;
}

registerCardEffect('Warlum', {
  powerTargets: (state) => allMagiInPlay(state),
  deckSearch: {
    count: 1,
    whoseDeck: 'target',
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      if (!def || def.card_type !== 'Relic') return false;
      const searcher = state.players.get(playerId);
      const magiDefRaw = searcher?.activeMagi ? cardDb.get(searcher.activeMagi.definitionKey) : undefined;
      if (!magiDefRaw || !searcher?.activeMagi) return false;
      return checkRegionLegality(effectiveMagiDef(magiDefRaw, searcher.activeMagi), def).legal;
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Materialize') return;
    if (ctx.chosenTargetId === undefined) return;
    const targetMagi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!targetMagi) return;
    const owner = ctx.state.players.get(targetMagi.controllerId);
    if (!owner) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const ids = ctx.chosenDeckSearchIds ?? [];
    if (ids.length === 1) {
      const [id] = ids;
      const card = owner.deck.find((c) => c.instanceId === id);
      const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
      if (card && def?.card_type === 'Relic') {
        playFromZone(ctx.state, ctx.cardDb, { owner, zone: 'deck', instanceId: id! }, ctx.controllingPlayer, null, ctx.rng);
      }
    }
    shuffleDeck(owner, ctx.rng);
  },
});
