// Cry of Thunder (Spell) -- "Play Cry of Thunder only before your Attack Step. Add two energy to
// each of your Arderial Creatures in play. Also, add one energy to each of your Xyx in play. At the
// end of your turn, discard from play each of your Creatures that did not attack this turn." No
// board target -- three broadcasts over the caster's own in-play Creatures. "Xyx" is a name family
// (Cyclone Xyx, Xyx, Xyx Elder, Xyx Minor, etc.), not a database subtype field, same
// name.includes(...) pattern already used for other named families (Hyren, etc.) -- a Xyx Creature
// that's ALSO Arderial gets BOTH bonuses (the two clauses are independent, not exclusive). The
// end-of-turn discard is registry.ts's spellLegalPhases (only 'prs1', i.e. before the Attack phase)
// plus the new MUST_ATTACK_THIS_TURN_OR_DISCARD tag, applied now and swept conditionally by
// turn.ts's sweepMustAttackOrDiscard once combat has actually happened.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addPermanentTag, MUST_ATTACK_THIS_TURN_OR_DISCARD } from '../durationTags.js';

registerCardEffect('Cry of Thunder', {
  spellLegalPhases: ['prs1'],
  resolveSpell: (ctx) => {
    const own = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    for (const creature of own) {
      const def = ctx.cardDb.get(creature.definitionKey);
      if (effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Arderial'))) addEnergy(ctx.state, ctx.cardDb, creature, 2, 'spell');
      if (def?.name.includes('Xyx')) addEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell');
      addPermanentTag(ctx.state, ctx.cardDb, creature, MUST_ATTACK_THIS_TURN_OR_DISCARD);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Also switched the raw def.regions check to
  // effectiveRegions() while here, same class of fix as Rumble Stones. The "Xyx" clause is a name
  // family, not a region -- out of scope.
  specifiedSpellTargetRegions: () => ['Arderial'],
});
