// Gulg -- "Fortify (1): Add two energy to each Creature you control that defeated a Creature in
// an attack this turn." Second use of CardInstance.defeatedThisTurn, after Great White Narth.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Gulg', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Fortify') return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      if (creature.defeatedThisTurn) addEnergy(ctx.state, ctx.cardDb, creature, 2, 'power');
    }
  },
});
