// Defender of the Sky -- "Strengthen: Whenever you play a Xyx, add two additional energy to it."
// "Xyx" is a Creature family name (Cyclone Xyx, Smoke Xyx, ...) -- matched via a word-boundary
// regex against the full card name (same robust approach used for the Furok/Bagala families,
// since targeting.ts's plain "last word" creatureType() convention has known exceptions).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

const XYX_FAMILY = /\bXyx\b/;

registerCardEffect('Defender of the Sky', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Creature') return;
    if (!XYX_FAMILY.test(def.name)) return;
    addEnergy(state, cardDb, played, 2, 'effect');
  },
});
