// Motash -- "Escape: Whenever a Creature you control in play is attacked and defeated, return
// that Creature to your hand instead of discarding it." Fires in afterCombat, after the normal
// zero-energy defeat sweep already moved the Creature to its owner's discard pile -- retrieves it
// straight back out into hand, same "undo the default discard, redirect elsewhere" pattern as
// magamsRing.ts's Rebirth (which pulls a card out of the discard pile via playFromZone instead).

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';

registerCardEffect('Motash', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.defender === null || ctx.defender.controllerId !== self.controllerId) return;
    if (outcome.defenderSurvived) return;
    retrieveFromDiscardPile(ctx.state, ctx.defendingPlayer, ctx.defender.instanceId, 'hand');
  },
});
