// Gransaber -- "Ferocity: Discard one of your other Nar Creatures from play to restore Gransaber
// to its starting energy." ("Grandsaber" in the source text is a typo for the card's own name.)
// First card to use effects.ts's restoreEnergy. "Other" excluded at the picker level (2026-07-08
// fix, same bug/fix as Flame Rudwot -- see registry.ts's powerTargets doc comment).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions, findInPlayById, regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay, restoreEnergy } from '../effects.js';

registerCardEffect('Gransaber', {
  // "Chill: Whenever Gransaber attacks, it removes two additional energy." BUILT 2026-07-28
  // (ability-count sweep) -- the file had only Ferocity. Note the deliberate difference from Spark
  // Chogo's Burnout directly above in this batch: Burnout says "from the opposing Creature" and so
  // is gated on ctx.defender !== null, while Chill has no such qualifier and therefore also applies
  // to a direct Magi attack. Same mechanic, different scope, straight from the printed wording.
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    ctx.locked.attackerEnergy += 2;
  },
  powerTargets: (state, cardDb, playerId, _powerName, sourceInstanceId) =>
    creaturesControlledBy(state, cardDb, playerId).filter(
      (c) => c.instanceId !== sourceInstanceId && effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Nar'))
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Ferocity') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.instanceId === ctx.source.instanceId) return; // "other" -- excludes itself
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Nar'))) return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId, undefined, undefined, ctx.rng);
    restoreEnergy(ctx.state, ctx.cardDb, ctx.source, effectiveStartingEnergy(ctx.state, ctx.cardDb, ctx.source));
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Nar'],
});
