// Alpine Xamf -- "Strengthen: Whenever you play a Kybar's Teeth or Naroom Creature, add one
// energy to it." Broadcast onPlay reactor (self decides relevance), same shape as Forest Wudge's
// Strengthen.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Alpine Xamf', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Creature') return;
    if (!def.regions.includes("Kybar's Teeth") && !def.regions.includes('Naroom')) return;
    addEnergy(state, cardDb, played, 1, 'effect');
  },
});
