// Yollum -- two printed pieces:
//   "Incinerate (3): Choose any one Core Creature or Magi in play. Discard six energy from the
//   chosen Creature or Magi." Region-filtered Creature-or-Magi target.
//   "Resistance: Core Spells and Powers do not affect Yollum." Built (Spell-pass audit follow-up,
//   2026-07-23) via the same blocksPowerEffectBySourceRegion hook as Lovian/Chaos Flugg, checked
//   by effects.ts's discardEnergy/addEnergy for both cause === 'power' and cause === 'spell' --
//   same "known partial-coverage limitation" as every other user of this hook (only the
//   energy-loss/gain half of "does not affect" is enforced).

// Ashio's Weave Twist (2026-07-24): every "Core" reference above is Yollum's OWN printed text, so
// under Ashio they mean its own region (Cald) instead -- see targeting.ts's ashioAdjustedRegion
// doc comment.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, ashioAdjustedRegion, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

function isCore(state: GameState, cardDb: CardDatabase, instance: CardInstance): boolean {
  return effectiveRegions(state, cardDb, instance).includes(regionForTargetFilter(state, ashioAdjustedRegion(state, cardDb, 'Core', ['Cald'])));
}

registerCardEffect('Yollum', {
  powerTargets: (state, cardDb) =>
    [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)].filter((c) => isCore(state, cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Incinerate') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isCore(ctx.state, ctx.cardDb, target)) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 6, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Only covers the "Incinerate" ability's target pool;
  // the "Resistance" ability's blocksPowerEffectBySourceRegion hook below is unrelated and
  // untouched.
  specifiedTargetRegions: (state, cardDb) => [ashioAdjustedRegion(state, cardDb, 'Core', ['Cald'])],
  blocksPowerEffectBySourceRegion: (state, cardDb) => {
    if (state.currentAction?.source !== 'power' && state.currentAction?.source !== 'spell') return false;
    const sourceKey = state.currentAction.sourceDefinitionKey;
    if (sourceKey === undefined) return false;
    const sourceDef = cardDb.get(sourceKey);
    if (!sourceDef) return false;
    return sourceDef.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Cald']));
  },
});
