// Naroom Shadow Geyser (Spell, Core, cost 5) -- "The energy cost for this Geyser is zero if played
// by a Naroom Shadow Magi. In order to play this Geyser, you must discard three of your Core
// Creatures from play. Place this Geyser on the table. Naroom Creatures lose two energy when they
// are played. Whenever you play a Core Creature, add one energy to it. You may not play another
// Naroom Shadow Geyser while this one is in play. If your Magi leaves play, you may keep all but
// one of your Shadow Geysers in play. Agram does not discard any Shadow Geysers from play when he
// leaves play." Task #53-9, 2026-07-21, the Core Spell pass's A2 checkpoint.
//
// "Discard three of your Core Creatures from play" is a genuine WHICH-THREE choice in the physical
// game -- now a real player choice via registry.ts's `spellInPlayDiscardCost` (added 2026-07-21,
// playtest bug report: this used to pick the three deterministically, lowest-energy-first, with no
// choice at all -- the same staleness class Orothe Shadow Geyser's board-discard cost shared).
// `preventsOwnPlay` still requires at least 3 qualifying Creatures so the cost is always payable
// when cast; `qualifyingOwnCoreCreatures` is now only used for that count check, not to auto-pick.
//
// "Naroom Creatures lose two energy when they are played" carries no "opposing"/"your" qualifier --
// applies table-wide, to a Naroom Creature played by EITHER player, via the same onPlay broadcast
// every in-play card + Magi on both sides already receives (effects.ts's broadcastCardEnteredPlay).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay, discardEnergy, addEnergy } from '../effects.js';
import {
  castByShadowMagiOf,
  geyserSurvivesOwnMagiDefeat,
  geyserOnOwnMagiDefeated,
  geyserPendingTargetChoice,
  geyserResolveTargetChoice,
} from './shadowGeysers.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const NAME = 'Naroom Shadow Geyser';

function qualifyingOwnCoreCreatures(state: GameState, cardDb: CardDatabase, playerId: string) {
  return creaturesControlledBy(state, cardDb, playerId)
    .filter((c) => effectiveRegions(state, cardDb, c).includes('Core'))
    .sort((a, b) => (a.currentEnergy ?? 0) - (b.currentEnergy ?? 0) || a.instanceId.localeCompare(b.instanceId));
}

registerCardEffect(NAME, {
  selfCostOverride: (state, cardDb, playerId) => (castByShadowMagiOf(state, cardDb, playerId, 'Naroom') ? 0 : undefined),
  preventsOwnPlay: (state, cardDb, playerId) => {
    if (qualifyingOwnCoreCreatures(state, cardDb, playerId).length < 3) {
      return 'Naroom Shadow Geyser requires 3 Core Creatures in play to discard as its cost';
    }
    const player = state.players.get(playerId);
    if (player?.inPlay.some((c) => cardDb.get(c.definitionKey)?.name === NAME)) {
      return 'You may not play another Naroom Shadow Geyser while this one is in play';
    }
    return false;
  },
  spellInPlayDiscardCost: {
    count: 3,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature' && effectiveRegions(state, cardDb, card).includes(regionForTargetFilter(state, 'Core')),
  },
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    const ids = ctx.chosenInPlayDiscardCostIds ?? [];
    if (ids.length !== 3) return;
    const valid = ids.every((id) => {
      const card = ctx.controllingPlayer.inPlay.find((c) => c.instanceId === id);
      const def = card && ctx.cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && !!card && effectiveRegions(ctx.state, ctx.cardDb, card).includes(regionForTargetFilter(ctx.state, 'Core'));
    });
    if (!valid) return;
    for (const id of ids) {
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, id, undefined, undefined, ctx.rng);
    }
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  onPlay: (state, cardDb, played, self) => {
    const playedDef = cardDb.get(played.definitionKey);
    if (!playedDef || playedDef.card_type !== 'Creature') return;
    if (playedDef.regions.includes('Naroom')) {
      discardEnergy(state, cardDb, played, 2, 'effect');
    }
    if (played.controllerId === self.controllerId && playedDef.regions.includes('Core')) {
      addEnergy(state, cardDb, played, 1, 'effect');
    }
  },
  survivesOwnMagiDefeat: geyserSurvivesOwnMagiDefeat,
  onOwnMagiDefeated: geyserOnOwnMagiDefeated,
  pendingTargetChoice: geyserPendingTargetChoice,
  resolveTargetChoice: geyserResolveTargetChoice,
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Only the spellInPlayDiscardCost's Core filter is in scope
  // -- the onPlay broadcast's Naroom/Core checks are a different hook shape (reactive trigger,
  // not resolveSpell/resolvePower), out of scope for this sweep.
  specifiedSpellTargetRegions: () => ['Core'],
});
