// Shadow Hyren -- both printed clauses:
//   "Feed: If your Magi is a Shadow Magi, when Shadow Hyren defeats an opposing Creature in an
//   attack, add two energy to your Magi." Unblocked by the Shadow Magi region-legality work
//   (2026-07-10) -- `original_region !== null` on a Magi IS the Shadow Magi identity check (see
//   regions.ts's checkRegionLegality doc comment).
//   "Taste: When you play Shadow Hyren, choose a Creature. Discard one energy from the chosen
//   Creature. Whenever Shadow Hyren attacks a Creature of the same region as the chosen Creature,
//   add two energy to Shadow Hyren before energy is removed." Built task #35, 2026-07-16, once
//   CardInstance.persistentCategoryChoice existed (added later in that same overall project phase
//   than this file's original stale comment claimed, for Niffer/Sarazen Outcast) -- stores the
//   chosen Creature's OWN region there, not the creature's instance id (which might leave play
//   before Shadow Hyren's next attack; the printed text compares REGIONS, not the specific
//   Creature). A dual-region chosen Creature stores only its first listed region -- same
//   documented-simplification shape as Sarazen Outcast's mostCommonType, real dual-region
//   Creatures being rare enough not to warrant persistentCategoryChoice becoming an array.
//   Real choice via pendingTargetChoice/resolveTargetChoice (Dark Furok's Revile is the reference
//   shape for a marker-tag-driven pending choice); "choose a Creature" has no "opposing" qualifier,
//   so the pool is every Creature in play on EITHER side, including Shadow Hyren's own controller's
//   own board.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { allCreaturesInPlay, effectiveRegions } from '../targeting.js';

const TASTE_PENDING = 'shadowHyrenTastePending';

registerCardEffect('Shadow Hyren', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Taste (choose-on-play, then +2 on
  // matching-region attacks) owns the onPlay/pending-choice/onBeforeEnergyRemoved chain via
  // persistentCategoryChoice; Feed (defeated opposing Creature -> +2 to your Shadow Magi) owns
  // afterCombat alone. No shared hooks -- either Effect narrows cleanly.
  effectHooks: {
    Taste: ['onPlay', 'pendingTargetChoice', 'resolveTargetChoice', 'onBeforeEnergyRemoved', 'combatRegions'],
    Feed: ['afterCombat'],
  },
  // Swirling Orshaa's Morph Effect-half (Bucket D Batch E2 closure, 2026-08-14). Taste is a
  // continuous per-attack region check ("same region as the chosen Creature") -- Orshaa's
  // controller may want a Morph opt-in to make Orshaa match Taste's stored region. Same shape
  // as Sarazen Outcast's `combatCreatureTypes` above; no chosen region yet -> empty pool -> no
  // offer. See swirlingOrshaa.ts for the framework's controller-agnostic broadcast model.
  combatRegions: (state, cardDb, _playerId, sourceInstanceId) => {
    const p = state.players.get(_playerId);
    const self = p?.inPlay.find((c) => c.instanceId === sourceInstanceId);
    if (!self || self.persistentCategoryChoice === null) return [];
    return [self.persistentCategoryChoice];
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null || outcome.defenderSurvived) return;
    const magi = ctx.attackingPlayer.activeMagi;
    if (!magi) return;
    const magiDef = ctx.cardDb.get(magi.definitionKey);
    if (!magiDef?.original_region) return; // must be a Shadow Magi specifically
    addEnergy(ctx.state, ctx.cardDb, magi, 2, 'effect');
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, TASTE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(TASTE_PENDING)) return undefined;
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: 'Taste: choose a Creature to discard one energy from', pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    if (!self.tags.has(TASTE_PENDING)) return;
    removePermanentTag(self, TASTE_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    const region = effectiveRegions(state, cardDb, target)[0];
    if (region) self.persistentCategoryChoice = region;
    discardEnergy(state, cardDb, target, 1, 'effect', undefined, rng);
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (self.persistentCategoryChoice === null) return;
    if (!ctx.defender) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes(self.persistentCategoryChoice)) return;
    addEnergy(ctx.state, ctx.cardDb, self, 2, 'effect');
  },
});
