// Pack Korrit -- "Morale (1): Add one energy to each other Korrit in play."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Pack Korrit', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Morale') return;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (creature.instanceId === ctx.source.instanceId) continue;
      if (ctx.cardDb.get(creature.definitionKey)?.name.includes('Korrit')) {
        addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
      }
    }
  },
});
