// Vortex of Knowledge (Spell, cost 1) -- "Each player draws two cards." Naroom Spell pass,
// Category A (2026-07-23). Trivial broadcast over effects.ts's own drawCards, no target/choice.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Vortex of Knowledge', {
  resolveSpell: (ctx) => {
    for (const player of ctx.state.players.values()) {
      drawCards(ctx.state, ctx.cardDb, player, 2);
    }
  },
});
