// Cinder Hyren -- "Dream Pyre (3): Shuffle up to five Cald Creatures from your discard pile into
// your deck and choose a Creature. Remove energy from that Creature equal to the number of
// Creatures you shuffled into your deck."
//
// Real choice (task #40-2, 2026-07-17, player-choice-default retrofit, Group 2): two independent
// `powerTargetSlots` -- slot 0 is "up to five" from the discard pile (`min: 0`, same "any number"
// shape kesiasFlute.ts's own doc comment names as the precedent); slot 1 is "choose a Creature,"
// widened to EVERY Creature in play (both sides, matching the literal unqualified printed text,
// same "widest, most literal reading" convention used for Yog/Flame Hyren) rather than the earlier
// auto-pick's opposing-only assumption.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { shuffleDeck } from '../zones.js';

registerCardEffect('Cinder Hyren', {
  powerTargetSlots: (state, cardDb, playerId) => {
    const player = state.players.get(playerId)!;
    const caldRegion = regionForTargetFilter(state, 'Cald');
    const caldInDiscard = player.discardPile.filter(
      (c) => cardDb.get(c.definitionKey)?.card_type === 'Creature' && cardDb.get(c.definitionKey)?.regions.includes(caldRegion)
    );
    return [
      {
        label: 'Choose up to five Cald Creatures from your discard pile to shuffle into your deck',
        pool: (s, db, pid) => {
          const region = regionForTargetFilter(s, 'Cald');
          return s.players.get(pid)!.discardPile.filter(
            (c) => db.get(c.definitionKey)?.card_type === 'Creature' && db.get(c.definitionKey)?.regions.includes(region)
          );
        },
        min: 0,
        max: Math.min(5, caldInDiscard.length),
      },
      {
        label: 'Choose a Creature to remove energy from',
        pool: (s, db) => allCreaturesInPlay(s, db),
        min: 1,
        max: 1,
      },
    ];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Pyre') return;
    const player = ctx.controllingPlayer;
    const cardDb = ctx.cardDb;
    const shuffledIds = ctx.chosenSlotIds?.[0] ?? [];
    const targetId = ctx.chosenSlotIds?.[1]?.[0];

    for (const id of shuffledIds) {
      const index = player.discardPile.findIndex((c) => c.instanceId === id);
      if (index === -1) continue;
      const [moved] = player.discardPile.splice(index, 1);
      player.deck.push(moved!);
    }
    if (shuffledIds.length > 0) shuffleDeck(player, ctx.rng);

    if (!targetId) return;
    const target = allCreaturesInPlay(ctx.state, cardDb).find((c) => c.instanceId === targetId);
    if (!target) return;
    discardEnergy(ctx.state, cardDb, target, shuffledIds.length, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (The second slot's pool is every Creature in play,
  // unrestricted -- only the discard-pile Cald filter is in scope.)
  specifiedTargetRegions: () => ['Cald'],
});
