// Nyrex -- "Catch: Whenever one of your Weave or Paradwyn Creatures is specifically discarded
// from play by an opposing card or defeated while defending, you may place it below Nyrex."
// "Release: When Nyrex is discarded from play, play any one Creature from below Nyrex ignoring
// all costs and regional restrictions. Discard all other Creatures below Nyrex."
//
// Catch's two trigger halves map onto registry.ts's offersAttachRedirect via `discarded`'s
// stamped discardedCause/discardedSource/discardedByPlayerId: "specifically discarded from play
// by an opposing card" is cause 'explicit' + opposing-caused (task #32, 2026-07-16: retrofitted
// from the old `state.activePlayerId` heuristic to `discarded.discardedByPlayerId` -- this hook is
// checked by UI polling AFTER the discard already happened, so `state.currentAction` is long since
// cleared by the time this runs; the per-CardInstance stamp persists past that, which is exactly
// what it's for); "defeated while defending" is cause 'zero-energy' + source 'combat' + the
// CardInstance's own wasAttackedThisTurn field (true when this card was the declared DEFENDER this
// turn).
//
// Release is driven by registry.ts's attachedReleasePool/resolveAttachedRelease pair -- Nyrex
// itself is the self-discarded card here, so no separate onCardDiscardedFromPlay hook is needed;
// the UI checks attachedReleasePool after any action (attachedCards.ts's
// findPendingAttachedReleases) the same way it checks offersAttachRedirect.

import { registerCardEffect } from './registry.js';
import { checkCreatureDefeats } from '../energy.js';
import { addToZone, moveToDiscardPile } from '../zones.js';

registerCardEffect('Nyrex', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Catch owns the attach-redirect
  // (opposing-caused discard or defeated-defending), plus `holdsInertContents` since Catch is
  // what creates the attachment zone that has to stay silent. Release owns the discard-triggered
  // play-from-below pair.
  effectHooks: {
    Catch: ['offersAttachRedirect', 'holdsInertContents'],
    Release: ['attachedReleasePool', 'resolveAttachedRelease'],
  },
  // Cards stored under this one are OUT of play, not markers riding on it -- see
  // registry.ts's `holdsInertContents`. Without this, every board-wide broadcast that
  // flattens `attachedCards` (to reach the marker family) also fires the abilities of
  // whatever is sitting inertly in here.
  holdsInertContents: true,
  offersAttachRedirect: (state, cardDb, discarded, discardedOwnerId, self, cause, source) => {
    if (discardedOwnerId !== self.controllerId) return false;
    const def = cardDb.get(discarded.definitionKey);
    if (def?.card_type !== 'Creature') return false;
    if (!def.regions.includes('Weave') && !def.regions.includes('Paradwyn')) return false;
    if (cause === 'explicit') {
      return discarded.discardedByPlayerId !== undefined && discarded.discardedByPlayerId !== self.controllerId; // opposing-caused
    }
    if (cause === 'zero-energy' && source === 'combat') {
      return discarded.wasAttackedThisTurn === true; // defeated while defending
    }
    return false;
  },
  attachedReleasePool: (state, cardDb, self) =>
    self.attachedCards.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature'),
  resolveAttachedRelease: (state, cardDb, self, chosenInstanceId) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const cards = self.attachedCards.splice(0, self.attachedCards.length);
    for (const card of cards) {
      if (card.instanceId === chosenInstanceId) {
        const def = cardDb.get(card.definitionKey);
        card.currentEnergy = def && typeof def.cost === 'number' ? def.cost : 0;
        addToZone(player, 'inPlay', card);
      } else {
        const owner = state.players.get(card.ownerId);
        if (owner) moveToDiscardPile(state, owner, card);
      }
    }
    checkCreatureDefeats(state, cardDb);
  },
});
