// Flame Jakla -- "Heat Syphon (3): Choose a Magi and remove three energy from it. If this Power
// removes all the energy from the chosen Magi, add two energy to Flame Jakla." The bonus only
// fires if the Magi genuinely had energy to lose (not already at 0) and this removal brought it
// to exactly 0 -- checked via before/after rather than a threshold, so it stays correct
// regardless of exactly how much this removes.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Flame Jakla', {
  powerTargets: (state) => allMagiInPlay(state),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Heat Syphon') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;
    const before = target.currentEnergy ?? 0;
    discardEnergy(ctx.state, ctx.cardDb, target, 3, undefined, undefined, ctx.rng);
    if (before > 0 && (target.currentEnergy ?? 0) === 0) {
      addEnergy(ctx.state, ctx.cardDb, ctx.source, 2, 'power');
    }
  },
});
