// Vine Bhatar -- "Whiplash: Choose a Stalked Creature. Move one energy from the Creature to Vine
// Bhatar." First target pool filtered by durationTags.ts's STALKED tag rather than by controller
// -- text doesn't restrict to opposing, so either side's Stalked Creatures qualify.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';
import { hasDurationTag, STALKED } from '../durationTags.js';

registerCardEffect('Vine Bhatar', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => hasDurationTag(c, STALKED)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Whiplash') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!hasDurationTag(target, STALKED)) return;

    rearrangeEnergy(ctx.state, ctx.cardDb, target, ctx.source, 1, ctx.rng);
  },
});
