// Canopy Hyren -- "Fear (3): Remove two energy from each Stalked Creature." No target -- a sweep
// over every STALKED creature in play, either side.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { hasDurationTag, STALKED } from '../durationTags.js';

registerCardEffect('Canopy Hyren', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Fear') return;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb).filter((c) => hasDurationTag(c, STALKED))) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 2, undefined, undefined, ctx.rng);
    }
  },
});
