// Rayje's Shield -- "Leadership: Each time you draw a card, choose one of your Creatures in play.
// Add one energy to the chosen Creature. You cannot choose a Creature more than once per turn with
// Leadership." Same "not more than once per turn, tracked on the CHOSEN creature" idea as Ring of
// Secrets' Tinker, but the trigger is a DRAW (in-play-only onAnyCardDrawn -- an in-play passive must
// never fire from hand, per the draw-reactor zone-gating rule, task #47) rather than a Relic play,
// and it is restricted to the controller's OWN Creatures ("one of your Creatures").
//
// A single draw action can draw several cards (the Draw step draws two), so each draw arms one more
// pending choice, tracked as a COUNT embedded in a tag (same "tag carries its own state" shape as
// Artimillies' Research). The count is CAPPED at the current eligible-pool size at arm time: since
// each resolution both marks one Creature used-this-turn (shrinking the pool) and decrements the
// count in lockstep, the invariant count <= eligiblePool always holds -- so pendingTargetChoice
// never offers a prompt with an empty pool, and a turn with more draws than Creatures simply stops
// arming once every Creature has been chosen once.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { addDurationTag, hasDurationTag, addPermanentTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const CHOSEN_THIS_TURN = 'rayjesShieldChosenThisTurn';
const PENDING_PREFIX = 'rayjesShieldPending:';

function pendingCount(self: CardInstance): number {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return Number(tag.slice(PENDING_PREFIX.length)) || 0;
  }
  return 0;
}

function setPendingCount(state: GameState, cardDb: CardDatabase, self: CardInstance, n: number): void {
  const old = pendingCount(self);
  if (old > 0) removePermanentTag(self, `${PENDING_PREFIX}${old}`);
  if (n > 0) addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${n}`);
}

function leadershipPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  return creaturesControlledBy(state, cardDb, self.controllerId).filter((c) => !hasDurationTag(c, CHOSEN_THIS_TURN));
}

registerCardEffect("Rayje's Shield", {
  onAnyCardDrawn: (state, cardDb, self, drawingPlayerId) => {
    if (drawingPlayerId !== self.controllerId) return; // "Each time YOU draw a card"
    const eligible = leadershipPool(state, cardDb, self);
    const current = pendingCount(self);
    if (current < eligible.length) setPendingCount(state, cardDb, self, current + 1); // cap at what can be resolved
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (pendingCount(self) <= 0) return undefined;
    const pool = leadershipPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Rayje's Shield's Leadership: choose one of your Creatures to add 1 energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    const current = pendingCount(self);
    if (current <= 0) return;
    setPendingCount(state, cardDb, self, current - 1);
    if (!chosenInstanceId) return;
    const target = leadershipPool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    addDurationTag(state, cardDb, target, CHOSEN_THIS_TURN, state.turnNumber);
    addEnergy(state, cardDb, target, 1, 'effect');
  },
});
