// Deadwood Staff -- "Calling: Once per turn, as you are playing a Bograth Creature, you may
// discard a Bograth card from your hand to reduce the Creature's energy cost by the number of
// your Bograth Creatures in play, to a minimum of zero." Built this pass (task #30, 2026-07-15)
// as the first user of the new general registry.ts optionalHandDiscardCostReduction mechanism
// (play.ts's isLegalToPlay/playCard), which the project owner asked to be built reusably since
// more cards with an additional non-energy sub-cost are expected. Note the printed "to a minimum
// of ZERO" -- a real exception to this codebase's usual floor-at-1 cost-reduction convention
// (costModifier/selfCostAdjustment/Dreamwarp all floor at 1), which is exactly why `floorAt` is
// configurable on the shared hook rather than hardcoded.
//
// Once-per-turn gated via the new onHandDiscardCostReductionUsed notify hook (only fired when the
// reduction was ACTUALLY used, never from the pure isLegalToPlay preview) -- same MOMENTUM_USED
// duration-tag shape Keggerop already uses for its own once-per-turn Creature-discard clause.
//
// Emlob retrofit (task #30, 2026-07-15): counts "your Bograth Creatures in play," exactly Emlob's
// Imaginary Friends inflates by three -- even with zero real Bograth Creatures in play, Emlob
// alone makes a nonzero reduction (her own text is unconditional), so the "is this offer worth
// anything" gate checks the COMBINED total, not the raw board count.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import { emlobBonus } from './emlob.js';

const CALLING_USED = 'deadwoodStaffCallingUsedThisTurn';

registerCardEffect('Deadwood Staff', {
  optionalHandDiscardCostReduction: (state, cardDb, playedDef, playerId, self) => {
    if (self.controllerId !== playerId) return undefined;
    if (playedDef.card_type !== 'Creature' || !playedDef.regions.includes('Bograth')) return undefined;
    if (hasDurationTag(self, CALLING_USED)) return undefined;

    const bograthCount = creaturesControlledBy(state, cardDb, playerId).filter((c) =>
      effectiveRegions(state, cardDb, c).includes('Bograth')
    ).length;
    const magi = state.players.get(playerId)?.activeMagi;
    const amount = bograthCount + emlobBonus(cardDb, magi);
    if (amount === 0) return undefined; // no reduction on offer -- discarding a card would be a pure loss

    return {
      amount,
      floorAt: 0, // "to a minimum of zero" -- this card's own printed exception to the usual floor-at-1
      filter: (_state, db, _playerId, card) => db.get(card.definitionKey)?.regions.includes('Bograth') ?? false,
    };
  },
  onHandDiscardCostReductionUsed: (state, cardDb, self) => {
    addDurationTag(state, cardDb, self, CALLING_USED, state.turnNumber);
  },
});
