// Muck Shovel -- "Depression: Choose two Bograth Creatures. Move up to five energy from one
// Creature to the other Creature." Same ordered-pair shape as Qwade's Leech (first picked loses
// energy, second gains it) -- pool restricted to Bograth Creatures, fixed amount instead of X.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Muck Shovel', {
  // Capped at the printed 5, not the loser's actual energy -- both Creatures are SLOT picks and
  // powerAmountChoices never sees chosenSlotIds. resolvePower re-clamps. Same note as Flambit.
  powerAmountChoices: (state, cardDb, playerId, powerName) =>
    powerName === 'Depression'
      ? [{ id: 'move', prompt: 'Depression: move how much energy between the chosen Creatures? (0-5)', min: 0, max: 5 }]
      : undefined,
  powerTargetSlots: (state, cardDb) => [
    {
      label: 'Choose two Bograth Creatures (first loses energy, second gains it)',
      pool: (s, db) => allCreaturesInPlay(s, db).filter((c) => effectiveRegions(s, db, c).includes(regionForTargetFilter(s, 'Bograth'))),
      min: 2,
      max: 2,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Depression') return;
    const chosen = ctx.chosenSlotIds?.[0];
    if (!chosen || chosen.length !== 2 || chosen[0] === chosen[1]) return;

    const loser = findInPlayById(ctx.state, chosen[0]!);
    const gainer = findInPlayById(ctx.state, chosen[1]!);
    if (!loser || ctx.cardDb.get(loser.definitionKey)?.card_type !== 'Creature') return;
    if (!gainer || ctx.cardDb.get(gainer.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, loser).includes(regionForTargetFilter(ctx.state, 'Bograth'))) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, gainer).includes(regionForTargetFilter(ctx.state, 'Bograth'))) return;

    // Task #532: "up to N" is a player choice of 0..N, not N. `?? cap` keeps the old maximum as the
    // fallback when no amount was supplied, so this is safe before the UI collects one.
    const cap = Math.min(5, loser.currentEnergy ?? 0);
    const amount = Math.max(0, Math.min(ctx.chosenAmounts?.['move'] ?? cap, cap));
    if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, loser, gainer, amount, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Bograth'],
});
