// Dewstone -- both printed clauses, built task #42, 2026-07-17, the Kybar's Teeth region pass:
//   "Sip: Add one energy to your Magi for each opposing Creature defeated in attacks this turn."
//   Fourth use of CardInstance.defeatedThisTurn -- since a Creature can only attack (and therefore
//   only defeat something) once per turn, and can only ever attack an OPPOSING Creature, counting
//   this player's OWN Creatures with defeatedThisTurn set is exactly the count of opposing
//   Creatures they defeated this turn.
//   "Gulp: If you have no Creatures in play and no energy on your Magi, before your Magi is
//   defeated you may discard Dewstone from play to add five energy to your Magi." The first (and,
//   at build time, only) user of registry.ts's general offersDefeatPrevention/
//   resolveDefeatPrevention pair -- see that hook's own doc comment for why it's designed
//   open-ended rather than as a Dewstone-specific one-off.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Dewstone', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Sip') return;
    if (!ctx.controllingPlayer.activeMagi) return;
    const count = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter(
      (c) => c.defeatedThisTurn
    ).length;
    if (count > 0) addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, count, 'power');
  },
  offersDefeatPrevention: (state, cardDb, self, magi) => {
    if (self.controllerId !== magi.controllerId) return false;
    const player = state.players.get(self.controllerId);
    if (!player) return false;
    const hasCreature = player.inPlay.some((c) => c.instanceId !== self.instanceId && cardDb.get(c.definitionKey)?.card_type === 'Creature');
    return !hasCreature && (magi.currentEnergy ?? 0) <= 0;
  },
  resolveDefeatPrevention: (state, cardDb, self, magi, rng) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
    addEnergy(state, cardDb, magi, 5, 'effect');
  },
});
