// Rayalon -- "Study: Whenever Rayalon defeats a non-Arderial Creature in an attack, you may place
// any one Arderial or Core Spell from your discard pile into your hand." Real choice (registry.ts's
// pendingTargetChoice/resolveTargetChoice, same shape as Lasada, Emissary's Diplomacy) -- the pool
// is Spells sitting in the discard pile, a plain zone move, no Spell effect-execution needed.
//
// Ashio's Weave Twist (2026-07-24): "Core" above is Rayalon's OWN printed text, so under Ashio it
// means its own region (Arderial) instead -- a genuine no-op in effect here, since Rayalon's other
// operand is ALSO Arderial (the pool already includes Arderial Spells either way). See
// targeting.ts's ashioAdjustedRegion doc comment for the general mechanism.

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { ashioAdjustedRegion, effectiveRegions } from '../targeting.js';

const STUDY_PENDING = 'rayalonStudyPending';

registerCardEffect('Rayalon', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (!ctx.defender) return;
    if (outcome.defenderSurvived) return;
    if (effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Arderial')) return;
    addPendingChoiceTag(self, STUDY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(STUDY_PENDING)) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player) return undefined;
    const pool = player.discardPile.filter((c) => {
      const def = cardDb.get(c.definitionKey);
      return def?.card_type === 'Spell' && (def.regions.includes('Arderial') || def.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Arderial'])));
    });
    return { prompt: "Rayalon's Study: choose an Arderial or Core Spell from your discard pile to add to your hand", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, STUDY_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    retrieveFromDiscardPile(state, player, chosenInstanceId, 'hand');
  },
});
