// Strag's Ring -- "Purity: At the end of your turn, if all Spells in your discard pile are
// Underneath, discard all of your non-Underneath cards from play and choose any one Creature in
// play. Until the end of your next turn, the chosen Creature is considered burrowed; it cannot
// attack and loses no more than two energy per turn from attacks and opposing Spells and Powers."
// The shared condition-check + mass-wipe now lives in purityRing.ts's applyPurity (2026-07-10,
// once 7 more region-specific Rings turned out to print the identical opening clause).
//
// Real choice (Phase 4c, 2026-07-11): "choose any one Creature in play" doesn't say whose --
// replaces the earlier "controller's own strongest remaining Creature" simplification with a real
// pending choice (registry.ts's pendingTargetChoice/resolveTargetChoice) over every Creature in
// play, either side, matching the printed text's lack of a qualifier.

import { registerCardEffect } from './registry.js';
import { applyPurity } from './purityRing.js';
import { applyBurrowedTag, addPermanentTag, addPendingChoiceTag, nextOwnTurnNumber, removePermanentTag } from '../durationTags.js';
import { allCreaturesInPlay } from '../targeting.js';

const PURITY_PENDING = 'stragsRingPurityPending';

registerCardEffect("Strag's Ring", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, 'Underneath', rng)) return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, PURITY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(PURITY_PENDING)) return undefined;
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Strag's Ring's Purity: choose a Creature to make burrowed until the end of your next turn", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, PURITY_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) applyBurrowedTag(state, cardDb, target, nextOwnTurnNumber(state), self.instanceId, rng);
  },
});
