// Stubborn Chogus -- "Determination: As Stubborn Chogus attacks the largest opposing Creature,
// add two energy to Stubborn Chogus." "Largest" ties are inclusive (no other opposing Creature
// has strictly more energy than the declared defender), same convention as bone Cragnoc's Frenzy.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { opposingCreatures } from '../targeting.js';

registerCardEffect('Stubborn Chogus', {
  // Corrected 2026-07-11: moved from onAttack to onBeforeEnergyRemoved so the +2 counts toward
  // this attack's own damage, not just post-combat survival -- reads live currentEnergy directly
  // rather than ctx.snapshot, since the snapshot isn't computed yet at this point in combat.
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    const opposing = opposingCreatures(ctx.state, ctx.cardDb, self.controllerId);
    const defenderEnergy = ctx.defender.currentEnergy ?? 0;
    const isLargest = opposing.every((c) => c.instanceId === ctx.defender!.instanceId || (c.currentEnergy ?? 0) <= defenderEnergy);
    if (!isLargest) return;
    addEnergy(ctx.state, ctx.cardDb, self, 2, 'effect');
  },
});
