// Yerthe -- two printed clauses:
//   "Empower Dream: All of your hyren in play gain ENERGIZE: 1." -- a flat rate GRANT, not an
//   additive bonus (2026-08-05 rules-correctness fix, owner-supplied ruling: a Baby Hyren that
//   already has Energize 2 stays at 2 when Yerthe grants it "Energize 1," it doesn't become 3) --
//   energizeRateGrant, own Hyren-family Creatures (word-boundary match, same convention as every
//   other family-text card). See registry.ts's energizeRateGrant doc comment for the MAX-not-SUM
//   combination mechanic.
//   "Hyren Affinity: You ignore regional penalties and restrictions when playing hyren." --
//   regionOverride, own controller, Hyren family.

import { registerCardEffect } from './registry.js';
import { magiCountsAs } from './magiIdentity.js';

const HYREN_FAMILY = /\bHyren\b/;

registerCardEffect('Yerthe', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Empower Dream = the MAX-not-SUM
  // Energize-1 grant to own Hyren (`energizeRateGrant`); Hyren Affinity = the
  // ignore-regional-penalties override on own Hyren plays (`regionOverride`).
  effectHooks: {
    'Empower Dream': ['energizeRateGrant'],
    'Hyren Affinity': ['regionOverride'],
  },
  energizeRateGrant: (state, cardDb, energizing, self) => {
    if (energizing.controllerId !== self.controllerId) return 0;
    const def = cardDb.get(energizing.definitionKey);
    if (def?.card_type !== 'Creature' || !HYREN_FAMILY.test(def.name)) return 0;
    return 1;
  },
  regionOverride: (state, cardDb, playedDef, magi) =>
    magiCountsAs(cardDb, magi, 'Yerthe') && HYREN_FAMILY.test(playedDef.name),
});
