// Awakening (Spell, Core, cost 1) -- "Place Awakening on the table. At the beginning of your turn,
// if you have all five Shadow Geysers in play, defeat all opposing Magi stacks. Whenever one of
// your Shadow Geysers is discarded from play by an opposing card, play that Shadow Geyser at the
// end of your next turn, ignoring all costs, restrictions, and effects of the Shadow Geyser being
// played." Task #53-9, 2026-07-21, the Core Spell pass's A2 checkpoint -- the Shadow Geyser
// subsystem's own payoff card, and this engine's first genuine alternate win condition.
//
// "Defeat all opposing Magi stacks" -- the CURRENT active Magi goes through the real `defeatMagi`
// primitive (so its own `onOwnMagiDefeated` reactions etc. fire normally, same as any other Magi
// defeat), then every remaining Magi still in `magiQueue` is moved straight to `defeatedMagi` --
// there's no "reveal the next one" step, since the whole point is ending the game in one shot, not
// grinding through the stack. `checkMagiDefeats` afterward drives the normal win-check machinery
// (`energy.ts`'s private `checkForGameEnd`), which sets `state.winnerId` once an opponent's
// `magiQueue` is empty and `activeMagi` is null -- exactly the state this leaves them in.
//
// The delayed-replay clause has no existing "queue an action for a future turn boundary" primitive
// to reuse wholesale -- `PlayerState.pendingShadowGeyserReplays` (types/state.ts, new this task) is
// the closest existing shape (`pendingMudBubbleWatch`'s "chosen thing + turn number, consumed by
// turn.ts's own end-of-turn hook" pattern) adapted for a genuine CardInstance id instead of just a
// name. "Ignoring all costs, restrictions, and effects of the Shadow Geyser being played" is read as
// skipping `resolveSpell`/`selfCostOverride`/`preventsOwnPlay` entirely -- the queued card moves
// directly from the discard pile into `inPlay`, since a Geyser's own ongoing hooks (`costModifier`,
// `onPlay`, etc.) only ever check "am I sitting in `inPlay`" and need no resolveSpell-driven setup.

import { registerCardEffect } from './registry.js';
import { defeatMagi, checkMagiDefeats } from '../energy.js';
import { getOpponents } from '../types/state.js';
import { nextTurnNumberFor } from '../durationTags.js';
import { removeFromZone, addToZone } from '../zones.js';
import { SHADOW_GEYSER_NAMES } from './shadowGeysers.js';

registerCardEffect('Awakening', {
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  onOwnTurnStart: (state, cardDb, self, rng) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const ownedNames = new Set(
      player.inPlay.map((c) => cardDb.get(c.definitionKey)?.name).filter((n): n is string => !!n)
    );
    const hasAllFive = SHADOW_GEYSER_NAMES.every((name) => ownedNames.has(name));
    if (!hasAllFive) return;

    for (const opponent of getOpponents(state, self.controllerId)) {
      if (opponent.activeMagi) {
        defeatMagi(state, cardDb, opponent, rng);
      }
      while (opponent.magiQueue.length > 0) {
        const next = opponent.magiQueue.shift()!;
        opponent.defeatedMagi.push(next);
      }
    }
    checkMagiDefeats(state, cardDb, rng);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discardedOwnerId !== self.controllerId) return;
    if (!SHADOW_GEYSER_NAMES.includes(cardDb.get(discarded.definitionKey)?.name ?? '')) return;
    if (!causedByPlayerId || causedByPlayerId === self.controllerId) return; // "by an opposing card"
    const player = state.players.get(self.controllerId);
    if (!player) return;
    if (player.pendingShadowGeyserReplays.some((r) => r.instanceId === discarded.instanceId)) return;
    player.pendingShadowGeyserReplays.push({
      instanceId: discarded.instanceId,
      atTurnNumber: nextTurnNumberFor(state, self.controllerId),
    });
  },
  onOwnTurnEnd: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const due = player.pendingShadowGeyserReplays.filter((r) => r.atTurnNumber === state.turnNumber);
    if (due.length === 0) return;
    player.pendingShadowGeyserReplays = player.pendingShadowGeyserReplays.filter((r) => r.atTurnNumber !== state.turnNumber);
    for (const entry of due) {
      const inDiscard = player.discardPile.some((c) => c.instanceId === entry.instanceId);
      if (!inDiscard) continue; // may have already moved elsewhere -- defensive, matches trust-but-verify convention
      const card = removeFromZone(player, 'discardPile', entry.instanceId);
      addToZone(player, 'inPlay', card);
    }
  },
});
