// Akkar -- both printed pieces:
//   "Rolling Thunder: If any opponent has more Creatures in play than you do, your Magi's
//   Energize rate is increased by two."
//   "Invulnerability: Akkar loses two less energy in attacks." (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingCreatures } from '../targeting.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Akkar', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Rolling Thunder owns
  // energizeRateModifier; Invulnerability owns onAttack.
  effectHooks: {
    'Rolling Thunder': ['energizeRateModifier'],
    Invulnerability: ['onAttack'],
  },
  energizeRateModifier: (state, cardDb, energizing, self) => {
    const owner = state.players.get(self.controllerId);
    if (owner?.activeMagi?.instanceId !== energizing.instanceId) return 0;
    const ownCount = creaturesControlledBy(state, cardDb, self.controllerId).length;
    const opponentHasMore = opposingCreatures(state, cardDb, self.controllerId).length > ownCount;
    return opponentHasMore ? 2 : 0;
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 2),
});
