// Ice Furok -- "When Ice Furok attacks a frozen Creature, it loses no energy in the attack."
// Zeroes what Ice Furok (the attacker) takes back -- that's ctx.locked.defenderEnergy, since
// combat.ts's step 7 computes the attacker's own loss from it.

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Ice Furok', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (!ctx.defender || !isFrozen(ctx.state, ctx.cardDb, ctx.defender)) return;
    if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = 0;
  },
});
