// Grizzled Moga -- both printed pieces:
//   "Rampage: Whenever one of your Creatures attacks, discard one energy from the defending
//   Magi." A third-party reactor -- Grizzled Moga doesn't need to be part of the combat.
//   "Invulnerability: Grizzled Moga loses one less energy in attacks." (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Grizzled Moga', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Rampage and Invulnerability both live
  // in this file's single `onAttack` body -- field-level narrowing can't split them further, so a
  // Taglat copy of either Effect exposes onAttack (which runs both). Still tighter than the
  // whole-card fallback since every other hook on this entry is masked out.
  effectHooks: {
    Rampage: ['onAttack'],
    Invulnerability: ['onAttack'],
  },
  onAttack: (ctx, self) => {
    if (ctx.attacker.controllerId === self.controllerId && ctx.defendingPlayer.activeMagi) {
      discardEnergy(ctx.state, ctx.cardDb, ctx.defendingPlayer.activeMagi, 1, 'effect', undefined, ctx.rng);
    }
    applyInvulnerability(ctx, self, 1);
  },
});
