// Zungg -- "Gnaw: Choose any one opposing Creature in play. Move one energy from the chosen
// Creature to Zungg."

import { registerCardEffect } from './registry.js';
import { opposingCreatures, findInPlayById } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Zungg', {
  powerTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Gnaw') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;

    // ctx.rng threaded (found via a fuzz-harness replay divergence, 2026-07-30): a defeat here
    // can trigger a reactor like Bagala Cub's onCardDiscardedFromPlay, which reshuffles a deck.
    rearrangeEnergy(ctx.state, ctx.cardDb, target, ctx.source, 1, ctx.rng);
  },
});
