// Vard Stampede (Spell) -- "Choose any one Magi in play. If you have at least four Bograth
// Creatures in play, discard all of the chosen Magi's Relics and Spells from play." Bograth Spell
// pass, Category B1 (2026-07-20). The new count helper + allMagiInPlay targeting (own or opposing,
// Eclipse precedent) + dreamdrainCharm.ts/icecap.ts's exact `player.inPlay.filter(card_type is
// Spell/Relic)` + discardFromPlay loop, redirected at the chosen Magi's controller instead of self.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById, effectiveBograthCreatureCount } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Vard Stampede', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;

    const count = effectiveBograthCreatureCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (count < 4) return;

    const owner = ctx.state.players.get(target.controllerId);
    if (!owner) return;
    const targets = owner.inPlay.filter((c) => {
      const def = ctx.cardDb.get(c.definitionKey);
      return def?.card_type === 'Spell' || def?.card_type === 'Relic';
    });
    for (const relicOrSpell of targets) {
      discardFromPlay(ctx.state, ctx.cardDb, owner, relicOrSpell.instanceId, undefined, undefined, ctx.rng);
    }
  },
});
