// Zassyfer -- both printed effects:
//   "Warning: Whenever one of your other Weave Creatures is attacked, add one energy to that
//   Creature before energy is removed." (a third-party reactor)
//   "Weave: Whenever Zassyfer attacks or is attacked, before energy is removed, you may move one
//   energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { applyWeave } from './weave.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Zassyfer', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Warning and Weave share the fused
  // `onBeforeEnergyRemoved` body -- listed under both. Weave additionally carries `weaveConfig`.
  effectHooks: {
    Warning: ['onBeforeEnergyRemoved'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (
      ctx.defender &&
      ctx.defender.instanceId !== self.instanceId &&
      ctx.defender.controllerId === self.controllerId &&
      effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Weave')
    ) {
      addEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect');
    }
    applyWeave(ctx, self, ['Weave']);
  },
});
