// Yog -- "Turn: When you reveal Yog, you may choose any one Creature in play. If you do, gain
// control of the chosen Creature and permanently reduce Yog's energize by two. That Creature
// becomes Bograth instead of its original region." onMagiRevealed (self-reactive) +
// effects.ts's gainControl + a permanent (no expiry) energizeModifiers.ts entry +
// CardInstance.effectiveRegionOverride (task #30's new small region-reassignment mechanism,
// shared with Ruid's Mutate).
//
// Real choice (task #40-1, 2026-07-17, player-choice-default retrofit): replaces the earlier
// "highest-CURRENT-energy opposing Creature, falling back to own board" auto-pick with a real
// pending choice (registry.ts's pendingTargetChoice/resolveTargetChoice) -- pool is "any one
// Creature in play" per the printed text (both sides, no restriction), matching the "up to now
// widest, most literal reading" convention already used for Flame Hyren-style corrections.

import { registerCardEffect } from './registry.js';
import { gainControl } from '../effects.js';
import { addEnergizeModifier } from '../energizeModifiers.js';
import { allCreaturesInPlay } from '../targeting.js';
import { addPermanentTag, addPendingRevealChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const TURN_PENDING = 'yogTurnPending';

function turnPool(state: GameState, cardDb: CardDatabase): CardInstance[] {
  return allCreaturesInPlay(state, cardDb);
}

registerCardEffect('Yog', {
  onMagiRevealed: (state, cardDb, revealedMagi, self) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    if (turnPool(state, cardDb).length === 0) return;
    addPendingRevealChoiceTag(self, TURN_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(TURN_PENDING)) return undefined;
    const pool = turnPool(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Yog's Turn: choose any one Creature in play", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, TURN_PENDING);
    if (!chosenInstanceId) return;
    const target = turnPool(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    gainControl(state, cardDb, target, self.controllerId);
    addEnergizeModifier(self, -2);
    target.effectiveRegionOverride = { region: 'Bograth' }; // permanent -- no expiresAfterTurnNumber
  },
});
