// Locke -- "Treasure Hunt (2): Reveal the top three cards of your deck and select an opponent.
// That player chooses one of the cards. Place that card in your hand. If Locke is Frozen, choose
// one of the remaining cards and place it in your hand. Discard the other cards." First user of
// deckTopReveal's `chooser: 'target'` (the OPPONENT picks, from Locke's controller's OWN deck --
// whoseDeck stays 'own'). The "if Locke is Frozen" branch is now reachable (FROZEN exists,
// 2026-07-08) -- when frozen, TWO cards go to hand instead of one: the mandatory pick is still
// the opponent's, and the text doesn't name who makes the second pick, which (same as every other
// `chooser` field in this codebase) is purely a documentation/UI-labeling distinction in this
// synchronous, no-hidden-info-between-clients engine, not a mechanical one -- both picks are
// collected from the same chosenDeckTopIds array. Required count is simply 1 or 2 depending on
// isFrozen(ctx.source) (Locke's own Magi instance).

import { registerCardEffect } from './registry.js';
import { opposingMagi } from '../targeting.js';
import { removeFromZone, moveToDiscardPile } from '../zones.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Locke', {
  powerTargets: (state, cardDb, playerId) => opposingMagi(state, cardDb, playerId),
  deckTopReveal: { count: 3, whoseDeck: 'own', chooser: 'target' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Treasure Hunt') return;
    if (ctx.chosenTargetId === undefined) return;
    const player = ctx.controllingPlayer;
    const top = player.deck.slice(0, 3);
    const topIds = top.map((c) => c.instanceId);

    const requiredCount = isFrozen(ctx.state, ctx.cardDb, ctx.source) ? 2 : 1;
    const chosenIds = [...new Set(ctx.chosenDeckTopIds ?? [])];
    if (chosenIds.length !== requiredCount) return;
    if (!chosenIds.every((id) => topIds.includes(id))) return;

    for (const id of topIds) {
      const card = removeFromZone(player, 'deck', id);
      if (chosenIds.includes(id)) {
        player.hand.push(card);
      } else {
        moveToDiscardPile(ctx.state, player, card);
      }
    }
  },
});
