// Jetstream (Spell) -- "Play an Arderial Creature from your hand with a starting energy of three or
// less, ignoring all costs. That Creature cannot gain energy this turn." registry.ts's
// spellHandPlayChoice (the Spell counterpart of a Power's handPlayChoice) offers the filtered pool;
// resolveSpell plays the chosen card via effects.ts's playFromZone with startingEnergy null (its own
// printed value, since "ignoring all costs" only waives what's PAID, not the Creature's own starting
// energy -- same play.ts/Gate to Ombor precedent), then tags it with durationTags.ts's existing
// NO_ENERGY_GAIN, expiring at the end of THIS turn.

import { registerCardEffect } from './registry.js';
import { playFromZone } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { addDurationTag, NO_ENERGY_GAIN } from '../durationTags.js';

registerCardEffect('Jetstream', {
  spellHandPlayChoice: {
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return (
        def?.card_type === 'Creature' &&
        def.regions.includes('Arderial') &&
        effectiveStartingEnergy(state, cardDb, card) <= 3
      );
    },
  },
  resolveSpell: (ctx) => {
    if (!ctx.chosenHandPlayId) return;
    const handCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    if (!handCard) return;
    const def = ctx.cardDb.get(handCard.definitionKey);
    if (def?.card_type !== 'Creature' || !def.regions.includes('Arderial')) return;
    if (effectiveStartingEnergy(ctx.state, ctx.cardDb, handCard) > 3) return;
    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: handCard.instanceId },
      ctx.controllingPlayer,
      effectiveStartingEnergy(ctx.state, ctx.cardDb, handCard)
    , ctx.rng);
    if (played) addDurationTag(ctx.state, ctx.cardDb, played, NO_ENERGY_GAIN, ctx.state.turnNumber);
  },
});
