// Storm Ring -- "Thunder Charge: Whenever one of your Creatures attacks, add one energy to that
// Creature before energy is removed. If that Creature is a hyren, add one additional energy."
// Same onBeforeEnergyRemoved shape as Strag's Claws. "Hyren" is a creature-type check
// (targeting.ts's creatureType, the last word of the card's name), same shape Whilp/Omni
// Construct already use for type-matching.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creatureType } from '../targeting.js';

registerCardEffect('Storm Ring', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    addEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect');
    if (creatureType(ctx.cardDb, ctx.attacker.definitionKey) === 'Hyren') {
      addEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect');
    }
  },
});
