// Caboodle Kit -- two onPlay effects, both now buildable under the broadcast onPlay hook:
//   "Celestial Memory: When you play Caboodle Kit, you may place a spell with energy cost 1 or
//   less from your discard pile into your hand." (self-trigger)
//   "Curious: Whenever you play a spell with energy cost 1 or less, add one energy to Caboodle
//   Kit." (broadcast -- reacts to the controller's OWN later Spell plays)
//
// Celestial Memory's "may" is still auto-taken whenever a legal target exists (out of scope for
// Phase 4c, which is specifically about WHICH target gets chosen). "A spell" is now a real pending
// choice (Phase 4c, 2026-07-11, registry.ts's pendingTargetChoice/resolveTargetChoice) instead of
// the earlier "first eligible in discard-pile order" simplification.

import { registerCardEffect } from './registry.js';
import { addEnergy, retrieveFromDiscardPile } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const CELESTIAL_MEMORY_PENDING = 'caboodleKitCelestialMemoryPending';

function celestialMemoryPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.discardPile.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return def?.card_type === 'Spell' && typeof def.cost === 'number' && def.cost <= 1;
  });
}

registerCardEffect('Caboodle Kit', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Celestial Memory (self-play pending
  // pick) and Curious (broadcast +1 on own Spell plays) both live in a single `onPlay` body that
  // branches on `played.instanceId === self.instanceId`. The pending-choice half only reacts to
  // the self-play branch, so it's Celestial Memory-only; the shared `onPlay` cannot be narrowed
  // further without restructuring. Annotated for metadata explicitness.
  effectHooks: {
    'Celestial Memory': ['onPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
    Curious: ['onPlay'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) {
      if (celestialMemoryPool(state, cardDb, self).length === 0) return;
      addPendingChoiceTag(self, CELESTIAL_MEMORY_PENDING);
      return;
    }

    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Spell') return;
    if (typeof playedDef.cost !== 'number' || playedDef.cost > 1) return;
    addEnergy(state, cardDb, self, 1, 'effect');
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(CELESTIAL_MEMORY_PENDING)) return undefined;
    const pool = celestialMemoryPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: 'Caboodle Kit\'s Celestial Memory: choose a Spell (cost 1 or less) in your discard pile to return to hand', pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, CELESTIAL_MEMORY_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    if (celestialMemoryPool(state, cardDb, self).some((c) => c.instanceId === chosenInstanceId)) {
      retrieveFromDiscardPile(state, player, chosenInstanceId, 'hand');
    }
  },
});
