// Cragnoc -- "Lend a Hand (5): Roll two dice. Add that amount of energy to your Magi."
// "Invulnerability: Cragnoc loses one less energy in attacks." (invulnerability.ts) -- was
// missing entirely, no deferral comment, caught during the Kybar's Teeth region pass's partial-file
// audit (task #42, 2026-07-17).
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724): "roll two dice" chained as
// two sequential requestDieRoll calls. Fate's Whimsy per Q2 rerolls ONE of those dice, so the
// two-die roll is modeled as two independent Whimsy-interceptable events (the first die's window
// closes, then the second die is rolled, with its own window). The sum is applied by the second
// die's consumer using the first die's result carried in payload.

import { registerCardEffect } from './registry.js';
import { addEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { getPlayer } from '../types/state.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Cragnoc', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Lend a Hand') return;
    // Kick off the two-die chain: roll die 1, then in its consumer roll die 2 and sum.
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'cragnoc:lendAHand:die1',
      { controllingPlayerId: ctx.controllingPlayer.playerId },
      ctx.rng
    );
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
});

registerRollConsumer('cragnoc:lendAHand:die1', (state, cardDb, source, payload, finalRoll, rng) => {
  if (!source) return;
  const { controllingPlayerId } = payload as { controllingPlayerId: string };
  requestDieRoll(
    state,
    cardDb,
    source,
    source.controllerId,
    6,
    'cragnoc:lendAHand:die2',
    { controllingPlayerId, die1: finalRoll },
    rng
  );
});

registerRollConsumer('cragnoc:lendAHand:die2', (state, cardDb, _source, payload, finalRoll) => {
  const { controllingPlayerId, die1 } = payload as { controllingPlayerId: string; die1: number };
  const controllingPlayer = getPlayer(state, controllingPlayerId);
  if (controllingPlayer.activeMagi) {
    addEnergy(state, cardDb, controllingPlayer.activeMagi, die1 + finalRoll, 'power');
  }
});
