// Blizzard (Spell) -- "Choose one of your Creatures in play and one opposing Creature. Discard
// both chosen Creatures. Play Blizzard only after the Attack step." Nar Spell pass, Category B
// (2026-07-22). Two independent single-target picks (spellTargets/spellSecondTargets, same shape
// as Abwyn's Gift) -- the first pool is the caster's own Creatures, the second is any opposing
// Creature, no dependency between them. "Only after the Attack step" -> registry.ts's
// spellLegalPhases narrowed to just 'prs2' (the only Spell-legal phase that comes after 'attack'
// in PHASE_ORDER -- 'playNewCreatures' also comes after Attack but was never Spell-legal to begin
// with, same reasoning as Cry of Thunder's own 'prs1'-only narrowing for "before the Attack step").

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { creaturesControlledBy, allCreaturesInPlay } from '../targeting.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Blizzard', {
  spellLegalPhases: ['prs2'],
  spellTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  spellSecondTargets: (state, cardDb, playerId) => {
    const opponentIds = new Set(getOpponents(state, playerId).map((p) => p.playerId));
    return allCreaturesInPlay(state, cardDb).filter((c) => opponentIds.has(c.controllerId));
  },
  resolveSpell: (ctx) => {
    const own = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    const opposing = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenSecondTargetId);
    if (own) discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, own.instanceId, undefined, 'spell', ctx.rng);
    if (opposing) {
      const opposingOwner = ctx.state.players.get(opposing.controllerId);
      if (opposingOwner) discardFromPlay(ctx.state, ctx.cardDb, opposingOwner, opposing.instanceId, undefined, 'spell', ctx.rng);
    }
  },
});
