// Ainjer Swarm (Spell) -- "If you have at least four Bograth Creatures in play, all opposing
// Creatures in play lose one energy." Bograth Spell pass, Category A (2026-07-20). The count gate
// is targeting.ts's new effectiveBograthCreatureCount (folds in Emlob/Bog Stench, precedent:
// slarnath.ts) + opposingCreatures (targeting.ts) + a discardEnergy loop, same shape as jaela.ts's
// unqualified "discard 1 from each Creature in play" narrowed to one side.

import { registerCardEffect } from './registry.js';
import { effectiveBograthCreatureCount, opposingCreatures } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Ainjer Swarm', {
  resolveSpell: (ctx) => {
    const count = effectiveBograthCreatureCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (count < 4) return;
    for (const creature of opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell', undefined, ctx.rng);
    }
  },
});
