// Hok -- "Resilience: While any opponent has more Creatures in play than you, your Kybar's
// Teeth Creatures may not be discarded by opposing Spells, Powers, and Effects that specifically
// discard Creatures from play." registry.ts's preventsDiscardOf -- a conditional, board-state-
// dependent category grant from the Magi to its own Kybar's Teeth Creatures (no side effect,
// unlike Orpus/Emec's Forge).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';

registerCardEffect('Hok', {
  preventsDiscardOf: (state, cardDb, target, self, cause) => {
    // "...that SPECIFICALLY discard Creatures from play" -- the Comprehensive Rules p.10 defined
    // term, i.e. removed while it still has energy. Resilience does NOT stop a Creature being
    // defeated by energy loss.
    //
    // BUG FIX (#536 C2, 2026-07-27): this gate did not exist, and preventsDiscardOf is broadcast
    // from BOTH choke points. So while Resilience's board condition held, your Kybar's Teeth
    // Creatures survived combat and every other energy drain -- and, because Hok claims the
    // protection without restoring any energy (see registry.ts: a zero-energy claimant must do
    // that itself), they stayed in play at ZERO energy indefinitely. Verified live before fixing.
    //
    // No "is this opposing?" check is needed: discardFromPlay only reaches this hook inside its
    // own `owner.playerId !== actor` branch, so the explicit path is already opposing-scoped.
    if (cause !== 'explicit') return false;
    if (target.controllerId !== self.controllerId) return false;
    const targetDef = cardDb.get(target.definitionKey);
    if (targetDef?.card_type !== 'Creature' || !targetDef.regions.includes("Kybar's Teeth")) return false;

    const ownCount = creaturesControlledBy(state, cardDb, self.controllerId).length;
    for (const [playerId, player] of state.players) {
      if (playerId === self.controllerId) continue;
      const opponentCount = player.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature').length;
      if (opponentCount > ownCount) return true;
    }
    return false;
  },
});
