// Kesia -- Weave Magi with two Effects:
//   Native Strength: "Kesia may not play non-Weave Spells. Weave Spells cost Kesia two less energy,
//     to a minimum of one." -- restrictsOwnPlayOf (block own non-Weave Spell plays, All-High King
//     Korg's Super Clever precedent) + costModifier (-2 on Weave Spells; the "minimum of one" clamp
//     is handled globally by play.ts's Math.max(1, ...) floor on any net cost reduction, same as
//     Sive's Research / Amulet of Sand).
//   Wild Growth: "Whenever any of your Creatures in play use an Effect that specifically moves
//     energy, add one energy to that Creature." -- built in the Weave pass Category C via the new
//     onOwnCreatureMovedEnergyViaEffect broadcast, fired by any energy-move Effect through the shared
//     weave.ts#broadcastEnergyMoveEffect helper: the printed-Weave family (applyWeave) AND bespoke
//     Weave-move Effects like Blade Hyren's Great Weave both trigger it. Any future card whose Effect
//     moves energy just calls that helper with itself as the mover.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Kesia', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Native Strength = the two-part
  // Spell restriction/discount (`restrictsOwnPlayOf` blocks own non-Weave Spells,
  // `costModifier` gives -2 on Weave Spells); Wild Growth = the +1 broadcast when any of
  // your Creatures uses an energy-move Effect.
  effectHooks: {
    'Native Strength': ['restrictsOwnPlayOf', 'costModifier'],
    'Wild Growth': ['onOwnCreatureMovedEnergyViaEffect'],
  },
  restrictsOwnPlayOf: (_state, _cardDb, playerId, self, playedDef) => {
    if (playerId !== self.controllerId) return false;
    return playedDef.card_type === 'Spell' && !playedDef.regions.includes('Weave');
  },
  costModifier: (_state, _cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return playedDef.card_type === 'Spell' && playedDef.regions.includes('Weave') ? -2 : 0;
  },
  onOwnCreatureMovedEnergyViaEffect: (state, cardDb, self, mover) => {
    if (mover.controllerId !== self.controllerId) return; // "any of YOUR Creatures"
    addEnergy(state, cardDb, mover, 1, 'effect'); // "add one energy to that Creature"
  },
});
