// Vaal and Parmalag -- both printed with the identical "Shield: [This Creature] is prevented from
// losing any energy from attacks until the end of your turn." A self-shield: while tagged, this
// Creature takes no damage from combat whether it's the attacker or the defender that turn --
// checked generically by combat.ts's Step 7 via the new NO_ENERGY_LOST_IN_ATTACKS duration tag.
// Same shared-definition pattern as fossik.ts/magamWeebo.ts (identical text, two card names).

import { registerCardEffect } from './registry.js';
import type { CardEffectDefinition } from './registry.js';
import { addDurationTag, NO_ENERGY_LOST_IN_ATTACKS } from '../durationTags.js';

const shield: CardEffectDefinition = {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shield') return;
    addDurationTag(ctx.state, ctx.cardDb, ctx.source, NO_ENERGY_LOST_IN_ATTACKS, ctx.state.turnNumber);
  },
};

registerCardEffect('Vaal', shield);
registerCardEffect('Parmalag', shield);
