// Warrior Olum -- "Challenge (1): Choose an opponent and any of that player's Creatures. Discard
// two energy from the chosen Creature unless the chosen player discards three energy from their
// Magi." First card using registry.ts's opponentChoice-flavored booleanChoice -- the RESPONSE
// belongs to the target's controller, not Warrior Olum's controller.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Warrior Olum', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)),
  booleanChoice: {
    prompt: 'Discard 3 energy from your Magi to spare this Creature?',
    yesLabel: 'Pay 3 from Magi',
    noLabel: "Let the Creature take it",
    respondingPlayer: 'opponent',
    // Same shape as raxis.ts -- the payer is the TARGET Creature's controller.
    yesUnavailableReason: (state, cardDb, playerId, chosenTargetId) => {
      const target = chosenTargetId ? findCreatureOrMagiById(state, chosenTargetId) : undefined;
      const owner = target && state.players.get(target.controllerId);
      const have = owner?.activeMagi?.currentEnergy ?? 0;
      return have >= 3 ? undefined : `Your Magi has only ${have} energy -- 3 is required`;
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Challenge') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead
    // (only the "else" branch below actually discards from `target` itself).
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return; // must be opposing

    // Same unaffordable-payment bug Raxis had (playtest 2026-07-26, found on Raxis; this card was
    // caught by the sweep, not reported). "Discard two energy from the chosen Creature UNLESS the
    // chosen player discards three energy from their Magi" -- a Magi that cannot discard three has
    // not discarded three, so the Creature takes its 2. See raxis.ts for the full write-up.
    const targetOwner = ctx.state.players.get(target.controllerId);
    const canAfford = (targetOwner?.activeMagi?.currentEnergy ?? 0) >= 3;
    if (ctx.chosenBoolean && canAfford) {
      discardEnergy(ctx.state, ctx.cardDb, targetOwner!.activeMagi!, 3, undefined, undefined, ctx.rng);
    } else {
      discardEnergy(ctx.state, ctx.cardDb, target, 2, undefined, undefined, ctx.rng);
    }
  },
});
