// Jore -- "Nourish (1): Add one energy to each of your other burrowed Creatures."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { isBurrowed } from '../durationTags.js';

registerCardEffect('Jore', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Nourish') return;
    const others = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter(
      (c) => c.instanceId !== ctx.source.instanceId && isBurrowed(ctx.state, ctx.cardDb, c)
    );
    for (const creature of others) {
      addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
    }
  },
});
