// Kalius' Ring -- "Purity: At the end of your turn, if all Spells in your discard pile are
// Arderial, discard all of your non-Arderial cards from play and choose any one non-Arderial
// Creature in play with three or less energy. Discard the chosen Creature from play."
//
// Real choice (Phase 4c, 2026-07-11): "choose any one... Creature" doesn't say whose -- replaces
// the earlier "prefers an opposing eligible Creature, falls back to own" simplification with a
// real pending choice (registry.ts's pendingTargetChoice/resolveTargetChoice) over every eligible
// Creature in play, either side.
//
// CORRECTED 2026-07-21 (playtest bug report): used to check a Creature's STATIC printed region
// off the card database directly, so a Creature Corrupted (or Turned/Haunted/etc.) into Core
// still read as its original region here and was wrongly excluded from (or included in) the
// "non-Arderial" pool. Now reads `effectiveRegions`, matching `purityRing.ts`'s own fix.

import { registerCardEffect } from './registry.js';
import { applyPurity } from './purityRing.js';
import { discardFromPlay } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';
import type { CardInstance } from '../types/instance.js';

const PURITY_PENDING = 'kaliusRingPurityPending';

function purityPool(state: GameState, cardDb: CardDatabase): CardInstance[] {
  return allCreaturesInPlay(state, cardDb).filter(
    (c) => (c.currentEnergy ?? 0) <= 3 && !effectiveRegions(state, cardDb, c).includes('Arderial')
  );
}

registerCardEffect("Kalius' Ring", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, 'Arderial', rng)) return;
    if (purityPool(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, PURITY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(PURITY_PENDING)) return undefined;
    const pool = purityPool(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Kalius' Ring's Purity: choose a non-Arderial Creature with 3 or less energy to discard from play", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, PURITY_PENDING);
    if (!chosenInstanceId) return;
    const target = purityPool(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    const owner = state.players.get(target.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, target.instanceId, undefined, undefined, rng);
  },
});
