// Thresh -- both printed effects:
//   "Rethresh: Whenever a Weave card is discarded from play on an opponent's turn, add one energy
//   to Thresh." First card using registry.ts's onCardDiscardedFromPlay -- see that doc comment for
//   the "explicit discardFromPlay only, not automatic zero-energy defeat" scope note (since
//   extended, 2026-07-10, to also cover the automatic sweep -- this card benefits from that fix
//   automatically).
//   "Weave: Whenever Thresh is in an attack, before energy is removed, you may move one energy
//   between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { applyWeave } from './weave.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Thresh', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Rethresh is the opponent-turn Weave-
  // discard reactor; Weave carries the pre-damage move hook plus `weaveConfig`.
  effectHooks: {
    Rethresh: ['onCardDiscardedFromPlay'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    void discardedOwnerId;
    if (!effectiveRegions(state, cardDb, discarded).includes('Weave')) return;
    if (state.activePlayerId === self.controllerId) return; // must be on an OPPONENT's turn
    addEnergy(state, cardDb, self, 1, 'effect');
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
});
