// Haunting Visions (Spell, Core, cost 2) -- "Choose an opposing Creature and attach Haunting
// Visions to it. The Creature may not be chosen by its controller's Spells and Powers." Task
// #53-7, 2026-07-21, the Core Spell pass's A4 batch.
//
// "May not be chosen by its controller's Spells and Powers" -- BUILT 2026-08-11 (post-audit
// deferred-gap closure pass, Category C), via two new hooks: `preventsBeingChosenForSpellBy` (the
// new shared gate in `play.ts#isLegalToPlay`, this pass's other headline item alongside Instant
// Fortress's own "or Spells" half) and `preventsBeingChosenForPowerBy` (existing hook, widened
// this same pass to scan globally instead of just the target's own board -- Haunting Visions is
// exactly the card that widening was for: it sits on the CASTER's `inPlay`, not the tracked
// TARGET's, so the old target-board-only scan could never find it). "Its controller" in the
// printed text means the TARGET CREATURE's own controller (the opponent of Haunting Visions'
// caster) -- gated on `actingPlayerId === target.controllerId`, not on `self.controllerId`.

import { registerCardEffect } from './registry.js';
import { opposingCreatures } from '../targeting.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { discardFromPlay } from '../effects.js';

const TARGET_PREFIX = 'hauntingVisionsTarget:';

function trackedTargetId(self: { tags: ReadonlySet<string> }): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(TARGET_PREFIX));
  return tag ? tag.slice(TARGET_PREFIX.length) : undefined;
}

function protectsAsHauntingVisions(self: { tags: ReadonlySet<string> }, target: { instanceId: string; controllerId: string }, actingPlayerId: string): boolean {
  return trackedTargetId(self) === target.instanceId && actingPlayerId === target.controllerId;
}

registerCardEffect('Haunting Visions', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${TARGET_PREFIX}${ctx.chosenTargetId}`);
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, _cause, _source, _causedByPlayerId, rng) => {
    const targetId = trackedTargetId(self);
    if (!targetId || discarded.instanceId !== targetId) return;
    removePermanentTag(self, `${TARGET_PREFIX}${targetId}`);
    const owner = state.players.get(self.controllerId);
    if (owner && owner.inPlay.some((c) => c.instanceId === self.instanceId)) {
      discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    }
  },
  preventsBeingChosenForSpellBy: (state, cardDb, target, actingPlayerId, self) => protectsAsHauntingVisions(self, target, actingPlayerId),
  preventsBeingChosenForPowerBy: (state, cardDb, target, actingPlayerId, self) => protectsAsHauntingVisions(self, target, actingPlayerId),
});
