// Jungle Jile -- "Mass Stalk (2): Choose any one player. Until the beginning of your next turn,
// all of that player's Creatures are stalked; whenever a stalked Creature is attacked, discard
// one energy from the stalked Creature before energy is removed." "Choose a player" is modeled by
// offering that player's Magi as the pickable proxy (same trick as Rask Deserter's dependent
// pool needing to identify "whichever player controls X"), and reuses the existing STALKED tag
// wholesale -- just applied to every one of that player's Creatures at once, with the
// "beginning of next turn" duration variant instead of Stalk's usual "end of next turn."

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, creaturesControlledBy, findCreatureOrMagiById } from '../targeting.js';
import { addDurationTag, STALKED, beginningOfNextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Jungle Jile', {
  powerTargets: (state) => allMagiInPlay(state),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mass Stalk') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;

    const expiry = beginningOfNextOwnTurnNumber(ctx.state);
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, chosenMagi.controllerId)) {
      addDurationTag(ctx.state, ctx.cardDb, creature, STALKED, expiry);
    }
  },
});
