// Nemsa -- "Dreamdraft: Whenever you play one of your d'Resh Magi's starting cards, you can
// immediately play one Nemsa from your hand, ignoring all costs. Nemsa cannot attack this turn."
// A broadcast onPlay reactor: self is an ALREADY-in-play Nemsa watching for a starting-card play,
// then cascade-deploying a DIFFERENT copy of Nemsa from hand for free -- lets a hand full of
// Nemsas chain-deploy off a single starting-card play. `magiDef.starting` (CardDefinition, per
// setup.ts's own tutorStartingCards) is the active Magi's own literal starting-card name list;
// checked directly rather than the fuller tutorStartingCards `allowed` set (which also folds in
// implied/alternate/bonus names) since Dreamdraft only cares about the PRINTED starting list.
// Reuses effects.ts's forcePlayFromHand (task #50h, Togoth's Darkest Magics precedent) -- it
// mutates zones directly rather than going through play.ts's playCard, so no onPlay broadcast
// re-fires for the newly played Nemsa (no risk of an uncontrolled cascade loop).
//
// The "can" choice is auto-taken whenever legal, same no-interactive-prompt convention as every
// other reactive "may" hook in this codebase.

import { registerCardEffect } from './registry.js';
import { forcePlayFromHand } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Nemsa', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const owner = state.players.get(self.controllerId);
    if (!owner || !owner.activeMagi) return;

    const magiDef = cardDb.get(owner.activeMagi.definitionKey);
    if (!magiDef || !magiDef.regions.includes("d'Resh")) return;

    const playedDef = cardDb.get(played.definitionKey);
    if (!playedDef || !(magiDef.starting ?? []).includes(playedDef.name)) return;

    const nemsaInHand = owner.hand.find((c) => cardDb.get(c.definitionKey)?.name === 'Nemsa');
    if (!nemsaInHand) return;

    const newNemsa = forcePlayFromHand(state, cardDb, owner, nemsaInHand.instanceId);
    if (newNemsa) addRestrictionTag(state, newNemsa, CANNOT_ATTACK, state.turnNumber);
  },
});
