// Pearl Hyren -- "Jealousy: If you have at least one Relic in play, choose an opponent. If that
// player controls more Relics than you, add one energy to each Creature you control." "Choose an
// opponent" collapses to "the opponent" in 2-player, so no separate player-picker is needed.
//
// "Hoard: After an opponent chooses a Relic you control with a Spell or Power, remove one energy
// from that opponent's Magi." -- RESOLVED (Orothe Spell pass, 2026-07-24), same
// onOwnRelicChosenAsTargetByOpponent broadcast as Hubdra's Chest's twin Lock Box clause -- Pearl
// Hyren is a CREATURE reacting to a DIFFERENT card (any Relic it controls) being chosen, the reason
// this hook is a broadcast rather than a self-only check.

import type { CardDatabase } from '../types/card.js';
import type { GameState, PlayerId } from '../types/state.js';
import { getOpponents } from '../types/state.js';
import { registerCardEffect } from './registry.js';
import { inPlayControlledBy, creaturesControlledBy } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

function relicCount(state: GameState, cardDb: CardDatabase, playerId: PlayerId): number {
  return inPlayControlledBy(state, playerId).filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic').length;
}

registerCardEffect('Pearl Hyren', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Jealousy') return;
    const ownRelics = relicCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (ownRelics === 0) return;

    const opponents = getOpponents(ctx.state, ctx.controllingPlayer.playerId);
    const opponentHasMore = opponents.some((p) => relicCount(ctx.state, ctx.cardDb, p.playerId) > ownRelics);
    if (!opponentHasMore) return;

    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
    }
  },
  onOwnRelicChosenAsTargetByOpponent: (state, cardDb, self, chosenRelic, actorPlayerId) => {
    const actor = state.players.get(actorPlayerId);
    if (actor?.activeMagi) discardEnergy(state, cardDb, actor.activeMagi, 1, 'effect', self.controllerId);
  },
});
