// Cloud Narth -- two Powers.
// "Healing Rain: Choose any one Creature or Magi in play. Move up to two energy from Cloud Narth
// to the chosen Creature or Magi. Discard Cloud Narth from play."
// "Healing Storm: Choose any one Creature or Magi and one of your Pharans in play. Move up to the
// chosen Pharan's printed starting energy from the Pharan to the chosen Creature or Magi. Move up
// to two energy from Cloud Narth to the chosen Creature or Magi. Add three energy to the chosen
// Creature or Magi. Discard both the chosen Pharan and Cloud Narth from play." Same Healing Storm
// mechanic as Spray Narth, different card.
//
// The "up to two energy from Cloud Narth" cap, the Pharan-move cap at its PRINTED starting energy
// (not current energy), and BOTH powers discarding Cloud Narth (Healing Storm also discards the
// Pharan) from play afterward are all official 2i Design errata -- data-pipeline/output/
// rulings.json, applied to cards_final.json 2026-07-09 (see apply-errata.js). The original
// implementation moved ALL of Cloud Narth's (and the Pharan's) current energy uncapped and never
// discarded either card -- a real, live rules bug, not just a stale comment, caught auditing
// errata against already-implemented cards (PROGRESS_LOG.md, 2026-07-09).
//
// powerTargetSlots is gated by powerName (it already receives one -- see registry.ts's doc
// comment) so Healing Rain gets its own plain single-slot shape instead of inheriting Healing
// Storm's Pharan-requiring 2-slot shape.

import { registerCardEffect } from './registry.js';
import {
  allCreaturesInPlay,
  allMagiInPlay,
  creaturesControlledBy,
  findCreatureOrMagiById,
  findInPlayById,
  printedStartingEnergy,
} from '../targeting.js';
import { addEnergy, discardFromPlay, rearrangeEnergy } from '../effects.js';

registerCardEffect('Cloud Narth', {
  powerTargetSlots: (state, cardDb, playerId, powerName) => {
    const chooseTargetSlot = {
      label: 'Choose a Creature or Magi',
      pool: (s: typeof state, db: typeof cardDb) => [...allCreaturesInPlay(s, db), ...allMagiInPlay(s)],
      min: 1,
      max: 1,
    };
    if (powerName === 'Healing Rain') return [chooseTargetSlot];
    return [
      chooseTargetSlot,
      {
        label: 'Choose a Pharan you control',
        pool: (s: typeof state, db: typeof cardDb, pid: typeof playerId) =>
          creaturesControlledBy(s, db, pid).filter((c) => db.get(c.definitionKey)?.name.includes('Pharan')),
        min: 1,
        max: 1,
      },
    ];
  },
  // Task #532. Cloud Narth needs THREE separate amounts across its two Powers, which is why
  // AmountChoice is an array. Note its Healing Storm says "Move UP TO the chosen Pharan's printed
  // starting energy" -- Spray Narth's equivalent clause has no "up to" and stays exact.
  //
  // The Pharan bound cannot be computed here: the Pharan is a SLOT pick and this hook only receives
  // `chosenTargetId`. Offered at the printed-starting-energy ceiling of the largest eligible Pharan
  // and re-clamped in resolvePower against the one actually chosen.
  powerAmountChoices: (state, cardDb, playerId, powerName, source) => {
    if (powerName === 'Healing Rain') {
      const max = Math.min(2, source.currentEnergy ?? 0);
      return [{ id: 'move', prompt: `Healing Rain: move how much energy from Cloud Narth? (0-${max})`, min: 0, max }];
    }
    if (powerName !== 'Healing Storm') return undefined;
    const player = state.players.get(playerId);
    const pharanMax = Math.max(
      0,
      ...(player?.inPlay ?? [])
        .filter((c) => cardDb.get(c.definitionKey)?.name.includes('Pharan'))
        .map((c) => Math.min(printedStartingEnergy(cardDb, c.definitionKey), c.currentEnergy ?? 0))
    );
    const narthMax = Math.min(2, source.currentEnergy ?? 0);
    return [
      { id: 'pharanMove', prompt: `Healing Storm: move how much energy from the chosen Pharan? (0-${pharanMax})`, min: 0, max: pharanMax },
      { id: 'narthMove', prompt: `Healing Storm: move how much energy from Cloud Narth? (0-${narthMax})`, min: 0, max: narthMax },
    ];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Healing Rain') {
      const targetId = ctx.chosenSlotIds?.[0]?.[0];
      if (!targetId) return;
      const target = findCreatureOrMagiById(ctx.state, targetId);
      if (!target) return;
      const cap = Math.min(2, ctx.source.currentEnergy ?? 0);
      const moveAmount = Math.max(0, Math.min(ctx.chosenAmounts?.['move'] ?? cap, cap));
      if (moveAmount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, ctx.source, target, moveAmount, ctx.rng);
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
      return;
    }
    if (ctx.powerName !== 'Healing Storm') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const targetId = slots[0]?.[0];
    const pharanId = slots[1]?.[0];
    if (!targetId || !pharanId || targetId === pharanId) return;

    const target = findCreatureOrMagiById(ctx.state, targetId);
    if (!target) return;
    const pharan = findInPlayById(ctx.state, pharanId);
    if (!pharan || ctx.cardDb.get(pharan.definitionKey)?.card_type !== 'Creature') return;
    if (pharan.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!ctx.cardDb.get(pharan.definitionKey)?.name.includes('Pharan')) return;

    const pharanCap = Math.min(printedStartingEnergy(ctx.cardDb, pharan.definitionKey), pharan.currentEnergy ?? 0);
    const pharanMoveAmount = Math.max(0, Math.min(ctx.chosenAmounts?.['pharanMove'] ?? pharanCap, pharanCap));
    if (pharanMoveAmount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, pharan, target, pharanMoveAmount, ctx.rng);
    const narthCap = Math.min(2, ctx.source.currentEnergy ?? 0);
    const narthMoveAmount = Math.max(0, Math.min(ctx.chosenAmounts?.['narthMove'] ?? narthCap, narthCap));
    if (narthMoveAmount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, ctx.source, target, narthMoveAmount, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, 3, 'power');
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, pharan.instanceId, undefined, undefined, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
  },
});
