// Eclipse (Spell) -- "Choose any one Magi in play. The chosen Magi's Creatures cannot attack during
// that Magi's next turn." Only Creatures ever attack in this engine (Magi are never attackers), so
// this is exactly durationTags.ts's CANNOT_ATTACK applied to every one of the chosen Magi's
// controller's current Creatures, expiring after that controller's next turn -- same
// nextTurnNumberFor precedent as Firefly Amulet's "cannot attack on its player's next turn".

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, creaturesControlledBy, findCreatureOrMagiById } from '../targeting.js';
import { addDurationTag, CANNOT_ATTACK, nextTurnNumberFor } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Eclipse', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;
    const expiry = nextTurnNumberFor(ctx.state, target.controllerId);
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, target.controllerId)) {
      addRestrictionTag(ctx.state, creature, CANNOT_ATTACK, expiry);
    }
  },
});
