/** registry.ts's attachedReleasePool/resolveAttachedRelease family. */
export function resolveAttachedReleaseFor(
  state: GameState,
  cardDb: CardDatabase,
  selfInstanceId: string,
  chosenInstanceId: string | undefined
): void {
  const self = findCardAnywhereById(state, selfInstanceId);
  if (!self) return;
  // nameOfInstance (via findCardAnywhereById) deliberately never scans a host's attachedCards
  // (targeting.ts's own doc comment on findCreatureOrMagiById) -- but the chosen target HERE is, by
  // definition, still riding in self.attachedCards at logging time (the resolve call below is what
  // actually releases it). Check self.attachedCards directly first so the log gets a real name
  // instead of always falling back to the raw id for this one choice family.
  const chosenAttached = chosenInstanceId ? self.attachedCards.find((c) => c.instanceId === chosenInstanceId) : undefined;
  const chosenTargetName = chosenAttached
    ? cardDb.get(chosenAttached.definitionKey)?.name ?? chosenInstanceId
    : chosenInstanceId
      ? nameOfInstance(state, cardDb, chosenInstanceId)
      : undefined;
  logEvent(state, 'attachedReleaseResolved', {
    sourceInstanceId: self.instanceId,
    sourceName: cardDb.get(self.definitionKey)?.name,
    ...(chosenInstanceId ? { chosenTargetId: chosenInstanceId, chosenTargetName } : { declined: true }),
  });
  const resolve = effectToResolve(state, cardDb, self, (e) => !!e.resolveAttachedRelease, (e) => !!e.attachedReleasePool?.(state, cardDb, self))?.resolveAttachedRelease;
  resolve?.(state, cardDb, self, chosenInstanceId);
}

/**
 * Engine-side detector for the reactive-Dreamwarp window (Phase 0, task #TBD, 2026-07-30) --
 * mirrors Play.tsx's `checkReactiveDreamwarp` exactly (same candidate order: each player's own
 * Magi then inPlay, players in `state.players` iteration order, first granter wins), but reads
 * `state.pendingReactiveDreamwarpInstanceId` instead of taking `played` as a parameter, so
 * `getPendingObligations` can call it generically the way it already does every other `find*`
 * function in this family. Before this, this was the ONE mechanism with no engine-side detector
 * at all (Play.tsx's own comment on `checkReactiveDreamwarp` flagged it as a known gap: "the
 * fuzz harness can't reach it either... there is no takeBotAction fallback to hand it to").
 * Returns at most one entry, same "first match wins, no natural tiebreak" simplification as the
 * original.
 */
export function findPendingReactiveDreamwarpChoices(
  state: GameState,
  cardDb: CardDatabase
): Array<{ self: CardInstance; played: CardInstance; min: number; max: number }> {
  const playedInstanceId = state.pendingReactiveDreamwarpInstanceId;
  if (!playedInstanceId) return [];
  const played = findCreatureOrMagiById(state, playedInstanceId);
  if (!played) return [];
  const playedDef = cardDb.get(played.definitionKey);
  if (!playedDef || playedDef.card_type !== 'Creature') return [];
  for (const owner of state.players.values()) {
    const candidates = owner.activeMagi ? [owner.activeMagi, ...owner.inPlay] : owner.inPlay;
    for (const candidate of candidates) {
      const def = cardDb.get(candidate.definitionKey);
      const range = def && getCardEffectByName(def.name)?.reactiveDreamwarpRange?.(state, cardDb, played, candidate);
      if (range) {
        return [{ self: candidate, played, min: range.min, max: range.max }];
      }
    }
  }
  return [];
}

/** registry.ts's reactiveDreamwarpRange/resolveReactiveDreamwarp family (Jungle Hyren, Boria,
 *  Gwomba, Magor's Support) -- `played` is the just-played Creature the adjustment applies to,
 *  `granterInstanceId` is the reactor whose controller chose the value. Clears the pending marker
 *  either way this is reached, so a stale marker can never re-offer the same window twice.
 *
 *  S1 mirror-fix (2026-08-12, docs/plans/_granted_effects_sites.md §3.5) -- picks WHICH effect on
 *  `granter` posted the reactive Dreamwarp offer, same "sole candidate resolves without consulting
 *  the offer hook" backward-compatible shape as `effectToResolve` above. Cannot reuse
 *  `effectToResolve` directly because `reactiveDreamwarpRange`'s postedPrompt check needs `played`
 *  as an extra parameter -- the pattern is inlined instead. */
export function resolveReactiveDreamwarpFor(
  state: GameState,
  cardDb: CardDatabase,
  playedInstanceId: string,
  granterInstanceId: string,
  chosenEnergy: number
): void {
  const played = findCreatureOrMagiById(state, playedInstanceId);
  const granter = findCreatureOrMagiById(state, granterInstanceId);
  if (played && granter) {
    const candidates = effectsFor(state, cardDb, granter).filter((e) => !!e.resolveReactiveDreamwarp);
    const resolve = candidates.length <= 1
      ? candidates[0]
      : candidates.find((e) => !!e.reactiveDreamwarpRange?.(state, cardDb, played, granter)) ?? candidates[0];
    resolve?.resolveReactiveDreamwarp?.(state, cardDb, played, granter, chosenEnergy);
  }
  if (state.pendingReactiveDreamwarpInstanceId === playedInstanceId) {
    state.pendingReactiveDreamwarpInstanceId = null;
  }
}

/** Declines the reactive-Dreamwarp window without applying an adjustment -- the "Skip" path.
 *  Also what `turn.ts`'s stale-obligation sweep calls on an unanswered window at a phase
 *  boundary, same fizzle-not-deadlock discipline as `sweepStalePendingChoiceTags`. */
export function declineReactiveDreamwarp(state: GameState): void {
  state.pendingReactiveDreamwarpInstanceId = null;
}

/**
 * The regional Spirit Spell reaction window (owner ruling, 2026-07-26). Lives here rather than in
 * spiritSpells.ts because it needs `isLegalToPlay`, and play.ts already imports spiritSpells.ts --
 * putting it there would close an import cycle, the same reason restrictions.ts exists as its own
 * module instead of living in durationTags.ts.
 *
 * Returns the Spirit Spells `playerId` can actually play into the open window. Empty means either
 * no window or nothing to answer it with -- and the UI shows no prompt (and does NOT block the
 * opponent's Next Phase) in that case, so a player holding none never stalls the game.
 */
export function previewSpiritSpellWindow(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId
): CardInstance[] {
  const player = state.players.get(playerId);
  if (!player || player.pendingSpiritSpellRegions.length === 0) return [];
  return player.hand.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return (
      hasOpenSpiritSpellWindow(state, playerId, def) &&
      isLegalToPlay(state, cardDb, playerId, c.instanceId).legal
    );
  });
}

/** "No thanks" for the window above -- the decline half. Playing a Spirit Spell closes the window
 *  through the same `closeSpiritSpellWindow`, so both answers are symmetrical and neither can leave
 *  a half-open window behind. */
export function declineSpiritSpellWindow(state: GameState, playerId: PlayerId): void {
  closeSpiritSpellWindow(state, playerId);
}
