// Salara -- "Spellcraft: Once per turn, as an opponent plays a Spell, choose an Illusion and add
// four energy to it." "An Illusion" has no "your own" qualifier, so any player's works. No "may"
// in the printed text, so this is mandatory whenever a legal target exists -- fizzles cleanly (no
// trigger, no once-per-turn consumption) if no Illusion is in play when the Spell is played.
//
// Upgraded (task #39-1, 2026-07-17) from an earlier "auto-pick the first Illusion" simplification
// to a real interactive choice via registry.ts's pendingTargetChoice/resolveTargetChoice, same
// pattern as Bulabantu (also d'Resh). `play.ts`'s onPlay broadcast already iterates both players'
// boards unconditionally (confirmed directly, no activePlayerId gate), so this correctly reacts to
// an opponent's Spell played off-turn (e.g. via a reactive-play card) with no extra wiring needed.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { isIllusion, addDurationTag, hasDurationTag, addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const USED_THIS_TURN = 'salaraSpellcraftUsedThisTurn';
const SPELLCRAFT_PENDING = 'salaraSpellcraftPending';

function illusionPool(state: GameState, cardDb: CardDatabase) {
  return allCreaturesInPlay(state, cardDb).filter((c) => isIllusion(c));
}

registerCardEffect('Salara', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return; // "an OPPONENT plays"
    if (cardDb.get(played.definitionKey)?.card_type !== 'Spell') return;
    if (hasDurationTag(self, USED_THIS_TURN)) return;
    if (illusionPool(state, cardDb).length === 0) return; // fizzle: no legal target, no consumption
    addPendingChoiceTag(self, SPELLCRAFT_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SPELLCRAFT_PENDING)) return undefined;
    const pool = illusionPool(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Salara's Spellcraft: choose an Illusion to add four energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, SPELLCRAFT_PENDING);
    if (!chosenInstanceId) return;
    const target = illusionPool(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    addDurationTag(state, cardDb, self, USED_THIS_TURN, state.turnNumber);
    addEnergy(state, cardDb, target, 4, 'effect');
  },
});
