// Coral Pyder -- "Playful: Whenever Coral Pyder attacks a Magi, it removes no energy in the
// attack. Instead, energize your Magi."
//
// SIMPLIFICATION: "energize your Magi" is approximated as a one-shot grant of the Magi's own
// printed energize rate (ignoring any energizeRateModifier bonuses that would apply during a real
// Energize step) -- there's no existing "run one card's energize outside the normal phase"
// primitive to call into instead.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Coral Pyder', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender !== null) return;
    ctx.locked.attackerEnergy = 0;
    const magi = ctx.attackingPlayer.activeMagi;
    if (magi) {
      const magiDef = ctx.cardDb.get(magi.definitionKey);
      addEnergy(ctx.state, ctx.cardDb, magi, magiDef?.energize ?? 0, 'effect');
    }
  },
});
