// Alaban Gloves -- "Undream: Choose a Creature in play. Return the chosen Creature to its owner's
// hand. Place that Creature's energy on its current Magi. If this is your Magi, you cannot add
// energy to your Magi beyond the Creature's printed starting energy." The cap (an official 2i
// Design errata -- data-pipeline/output/rulings.json, applied 2026-07-09) only applies when the
// RETURNED creature's owner is the power's own controller ("if this is YOUR Magi") -- targeting an
// opponent's Creature (the power's own text allows "any one Creature in play," not just your own)
// still dumps its full current energy onto the opponent's Magi uncapped, since the errata is only
// guarding against a self-buff exploit. Capture the energy amount and return to hand FIRST, THEN
// add it to the Magi -- NOT rearrangeEnergy(creature, magi, amount), which would leave the
// creature at 0 energy while still nominally in play and trigger the automatic zero-energy defeat
// check, discarding it before returnToHand can run.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, printedStartingEnergy } from '../targeting.js';
import { addEnergy, returnToHand } from '../effects.js';

registerCardEffect('Alaban Gloves', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Undream') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const owner = ctx.state.players.get(target.ownerId);
    if (!owner || !owner.activeMagi) return;

    let amount = target.currentEnergy ?? 0;
    if (owner.playerId === ctx.controllingPlayer.playerId) {
      amount = Math.min(amount, printedStartingEnergy(ctx.cardDb, target.definitionKey));
    }
    returnToHand(ctx.state, ctx.cardDb, owner, target.instanceId);
    if (amount > 0) addEnergy(ctx.state, ctx.cardDb, owner.activeMagi, amount, 'power');
  },
});
