// Rask Deserter -- "Skulk (1): Choose an opposing Nar Creature. Remove one energy from it and
// discard a Relic controlled by that Creature's Magi." Slot 2 genuinely DEPENDS on slot 1's
// answer -- its pool is "Relics controlled by whichever player controls slot 1's chosen
// Creature," which powerTargetSlots's priorChoices parameter exists specifically to support.
// min 0 on slot 2 since that player might control no Relics at all -- the energy removal still
// happens even if there's nothing to discard there.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Rask Deserter', {
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- this slot feeds
      // discardEnergy; the Relic slot below is unrelated (Relic type, not Creature/Magi).
      label: 'Choose an opposing Nar Creature',
      pool: (s, db, pid) =>
        flexibleTargetPool(s, db, pid, opposingCreatures(s, db, pid), opposingMagi(s, db, pid)).filter((c) =>
          effectiveRegions(s, db, c).includes(regionForTargetFilter(s, 'Nar'))
        ),
      min: 1,
      max: 1,
    },
    {
      label: "Choose a Relic controlled by that Creature's Magi (if any)",
      pool: (s, db, pid, priorChoices) => {
        const chosenCreatureId = priorChoices[0]?.[0];
        if (!chosenCreatureId) return [];
        const chosenCreature = s.players.get(pid) ? findCreatureOrMagiById(s, chosenCreatureId) : undefined;
        if (!chosenCreature) return [];
        const controller = s.players.get(chosenCreature.controllerId);
        return controller ? controller.inPlay.filter((c) => db.get(c.definitionKey)?.card_type === 'Relic') : [];
      },
      min: 0,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Skulk') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const creatureTargetId = slots[0]?.[0];
    if (!creatureTargetId) return;
    const creatureTarget = findCreatureOrMagiById(ctx.state, creatureTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!creatureTarget || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, creatureTarget, 'Creature')) return;
    if (creatureTarget.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, creatureTarget).includes(regionForTargetFilter(ctx.state, 'Nar'))) return;

    discardEnergy(ctx.state, ctx.cardDb, creatureTarget, 1, undefined, undefined, ctx.rng);

    const relicTargetId = slots[1]?.[0];
    if (!relicTargetId) return;
    const relicTarget = findCreatureOrMagiById(ctx.state, relicTargetId);
    if (!relicTarget || ctx.cardDb.get(relicTarget.definitionKey)?.card_type !== 'Relic') return;
    if (relicTarget.controllerId !== creatureTarget.controllerId) return;
    const relicOwner = ctx.state.players.get(relicTarget.controllerId);
    if (!relicOwner) return;
    discardFromPlay(ctx.state, ctx.cardDb, relicOwner, relicTarget.instanceId, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (The Relic slot's pool is unrestricted -- only the Nar
  // Creature slot is in scope.)
  specifiedTargetRegions: () => ['Nar'],
});
