// Karak Necklace -- two parts.
// Power "None for You" (free): "Choose any one Creature in play that you own. Gain control of the
// chosen Creature." -- reclaims a Creature you OWN but don't currently CONTROL (e.g. after it was
// stolen), which is exactly why the pool filters by ownerId, not controllerId/inPlay-side.
// Passive "Two for Me": "Once per turn, whenever you take control of another player's card, draw
// two cards" -- same onGainControl shape as Karak Band, just drawing cards instead of adding
// energy. "Once per turn" is an official 2i Design errata (data-pipeline/output/rulings.json,
// applied 2026-07-09) -- previously this fired every single control change, even multiple times in
// one turn -- tracked via a card-scoped duration tag, same pattern as Karak Band's Acquisition
// (also errata'd to once-per-turn in the same pass).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { gainControl, drawCards } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const TWO_FOR_ME_USED_THIS_TURN = 'karakNecklaceTwoForMeUsedThisTurn';

registerCardEffect('Karak Necklace', {
  powerTargets: (state, cardDb, playerId) => allCreaturesInPlay(state, cardDb).filter((c) => c.ownerId === playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'None for You') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target || target.ownerId !== ctx.controllingPlayer.playerId) return;

    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
  },
  onGainControl: (state, cardDb, gained, newControllerId, self) => {
    if (self.controllerId !== newControllerId) return;
    if (gained.ownerId === newControllerId) return;
    if (hasDurationTag(self, TWO_FOR_ME_USED_THIS_TURN)) return;
    const player = state.players.get(newControllerId);
    if (player) {
      drawCards(state, cardDb, player, 2);
      addDurationTag(state, cardDb, self, TWO_FOR_ME_USED_THIS_TURN, state.turnNumber);
    }
  },
});
