// Gia Pet -- "Power Siphon: Choose any one opposing Spell in play. Gia Pet gains energy equal to
// the energy cost of the chosen Spell." allSpellsInPlay filtered to opposing, mirroring how
// opposingCreatures filters allCreaturesInPlay (no dedicated opposingSpellsInPlay helper exists
// yet -- not worth adding for a single caller).
//
// "Impede: All players draw one less card during their Draw Step. Only one copy of this Effect
// may prevent players from drawing cards." (applied errata -- previously unlimited stacking.)
// Built via anyDrawCountModifier (task #35, 2026-07-16), same broadcast shape as Ebony Mirror's
// near-identical "-1" clause. The errata's stacking cap is enforced by only ever letting the
// FIRST Gia Pet found in play (stable array order, not instance-id sorting) contribute --
// every other copy returns 0, so N copies in play still only ever apply -1 total.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allSpellsInPlay, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Gia Pet', {
  powerTargets: (state, cardDb, playerId) =>
    allSpellsInPlay(state, cardDb).filter((s) => s.controllerId !== playerId),
  anyDrawCountModifier: (state, cardDb, self) => {
    const firstGiaPet = allCreaturesInPlay(state, cardDb).find((c) => cardDb.get(c.definitionKey)?.name === 'Gia Pet');
    return firstGiaPet?.instanceId === self.instanceId ? -1 : 0;
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Power Siphon') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Spell') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;

    const cost = ctx.cardDb.get(target.definitionKey)?.cost;
    if (typeof cost === 'number' && cost > 0) addEnergy(ctx.state, ctx.cardDb, ctx.source, cost, 'power');
  },
});
