// Bronn's Battle Staff -- "Slapstick: When an opposing Spell or Power chooses your Magi, you may
// discard one of your frozen cards from play. If you do, the Spell or Power does nothing." Built
// task #43, 2026-07-18, the Nar region pass -- Category D. A small widening of the already-shipped
// Checkpoint A (task #41) -- `offersPowerNegation`/`previewPowerNegationOffers` gained an optional
// trailing `currentTargetId`, since `Play.tsx#finishUsePower` already has the resolved target in
// scope by the time it calls the preview function. Auto-picks the first eligible frozen card to
// discard (no interactive "which frozen card" UI exists for this shape yet, same convention as
// Vogo's/Flameplate Armor's own auto-picks).
//
// "Or Spells" half built (Spell-pass audit follow-up, 2026-07-23) via offersSpellNegation/
// resolveSpellNegation, mirroring the Power pair 1:1 -- Treepsh's Watchful is the direct
// precedent for this exact shape (Bograth-reference-cluster, 2026-07-20).
//
// Explicit in-play zone check added (task #44 follow-up, 2026-07-18, Climbing Staff/Gear): this is
// a passive Relic ability, so it can only function while Bronn's Battle Staff itself is actually in
// play -- previously implicit (the shared candidate pool only ever scanned inPlay+Magi), now that
// `previewPowerNegationOffers` also scans HAND (for Climbing Staff/Gear's own hand-zone reactions)
// a duplicate copy sitting in hand needs to explicitly opt out rather than relying on the pool's
// old implicit guarantee.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect("Bronn's Battle Staff", {
  offersPowerNegation: (state, cardDb, self, user, powerName, currentTargetId) => {
    if (user.controllerId === self.controllerId) return false; // "an OPPOSING Spell or Power"
    const owner = state.players.get(self.controllerId);
    if (!owner?.activeMagi || currentTargetId !== owner.activeMagi.instanceId) return false; // "chooses YOUR Magi"
    if (!owner.inPlay.some((c) => c.instanceId === self.instanceId)) return false; // Bronn's Battle Staff itself must be in play
    // "one of your frozen CARDS from play" -- Creatures/Relics only, not the Magi itself
    // (discardFromPlay's own contract doesn't cover Magi removal, a separate defeat process).
    return owner.inPlay.some((c) => isFrozen(state, cardDb, c));
  },
  resolvePowerNegation: (state, cardDb, self, negatedSource, negatedPowerName, currentTargetId, rng) => {
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const frozenCard = owner.inPlay.find((c) => isFrozen(state, cardDb, c));
    if (!frozenCard) return;
    discardFromPlay(state, cardDb, owner, frozenCard.instanceId, undefined, undefined, rng);
  },
  offersSpellNegation: (state, cardDb, self, playedDef, playerId, currentTargetId) => {
    if (playerId === self.controllerId) return false; // "an OPPOSING Spell"
    const owner = state.players.get(self.controllerId);
    if (!owner?.activeMagi || currentTargetId !== owner.activeMagi.instanceId) return false; // "chooses YOUR Magi"
    if (!owner.inPlay.some((c) => c.instanceId === self.instanceId)) return false;
    return owner.inPlay.some((c) => isFrozen(state, cardDb, c));
  },
  resolveSpellNegation: (state, cardDb, self, negatedSpell, currentTargetId, rng) => {
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const frozenCard = owner.inPlay.find((c) => isFrozen(state, cardDb, c));
    if (!frozenCard) return;
    discardFromPlay(state, cardDb, owner, frozenCard.instanceId, undefined, undefined, rng);
  },
});
