// O'qua, Tracker -- "Invoke: Discard an Orothe Spell from your hand. Play an Orothe Creature from your
// hand, reducing its cost by the cost of the Spell you discarded, to a minimum of one." A
// handDiscardCost (the Orothe Spell) + handPlayChoice (the Orothe Creature). The Creature enters at
// its FULL printed starting energy (play.ts's cost model: a reduction lowers what the MAGI PAYS, not
// what the Creature enters with -- exactly Baby Hyren's corrected Growth Spurt); the Magi then pays
// max(1, creatureCost - spellCost).
//
// Shared simplification with Baby Hyren: playFromZone doesn't fire the played Creature's own onPlay,
// because the reduced-cost path can't route through the full playCard pipeline (which only ever pays
// full cost). Documented in docs/deferred-card-mechanics.md. Live-UI note: this Power collects BOTH a
// hand-discard AND a hand-play in one activation -- verify the ActionPrompt flow handles both.

import { registerCardEffect } from './registry.js';
import { playFromZone, discardFromHand } from '../effects.js';
import { regionForTargetFilter } from '../targeting.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

function isOrotheSpell(state: GameState, cardDb: CardDatabase, key: number): boolean {
  const d = cardDb.get(key);
  return d?.card_type === 'Spell' && d.regions.includes(regionForTargetFilter(state, 'Orothe'));
}
function isOrotheCreature(cardDb: CardDatabase, key: number): boolean {
  const d = cardDb.get(key);
  return d?.card_type === 'Creature' && d.regions.includes('Orothe');
}

registerCardEffect("O'qua, Tracker", {
  handDiscardCost: { count: 1, filter: (state, cardDb, playerId, card) => isOrotheSpell(state, cardDb, card.definitionKey) },
  handPlayChoice: { filter: (state, cardDb, playerId, card) => isOrotheCreature(cardDb, card.definitionKey) },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Invoke') return;
    const spellId = ctx.chosenHandCardIds?.[0];
    const creatureId = ctx.chosenHandPlayId;
    if (!spellId || !creatureId) return;
    const spell = ctx.controllingPlayer.hand.find((c) => c.instanceId === spellId);
    const creature = ctx.controllingPlayer.hand.find((c) => c.instanceId === creatureId);
    if (!spell || !creature) return;
    if (!isOrotheSpell(ctx.state, ctx.cardDb, spell.definitionKey) || !isOrotheCreature(ctx.cardDb, creature.definitionKey)) return;
    const creatureDef = ctx.cardDb.get(creature.definitionKey)!;
    const spellDef = ctx.cardDb.get(spell.definitionKey)!;
    if (typeof creatureDef.cost !== 'number') return; // X-cost Creature has no chosenXValue plumbing here
    const spellCost = typeof spellDef.cost === 'number' ? spellDef.cost : 0;
    const reducedCost = Math.max(1, creatureDef.cost - spellCost);

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [spellId], ctx.controllingPlayer.playerId, ctx.rng);
    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: creatureId },
      ctx.controllingPlayer,
      creatureDef.cost
    , ctx.rng);
    if (played) {
      const magi = ctx.controllingPlayer.activeMagi;
      if (magi) magi.currentEnergy = Math.max(0, (magi.currentEnergy ?? 0) - reducedCost);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Only the handDiscardCost's Orothe-Spell check is in scope
  // -- handPlayChoice's Orothe-Creature check is a different hook shape, out of scope here.
  specifiedTargetRegions: () => ['Orothe'],
});
