// Crushing Sands (Spell, d'Resh/d'Resh-Shadow-Magi-only) -- "Choose an opposing Creature. Discard
// four energy from the chosen Creature. If this discards that Creature from play, discard one
// energy from each of that player's Creatures. Only d'Resh Magi and d'Resh Shadow Magi can play
// Crushing Sands." Region restriction is data-driven (region_restrictive); no engine work needed
// for that half.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';
import { opposingCreatures, findInPlayById } from '../targeting.js';

registerCardEffect('Crushing Sands', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || target.controllerId === ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const ownerId = target.controllerId;

    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);
    checkCreatureDefeats(ctx.state, ctx.cardDb, 'spell', undefined, ctx.rng);
    const stillThere = findInPlayById(ctx.state, target.instanceId);
    if (stillThere) return; // wasn't discarded from play -- no sweep

    const owner = ctx.state.players.get(ownerId);
    if (!owner) return;
    for (const creature of [...owner.inPlay]) {
      if (ctx.cardDb.get(creature.definitionKey)?.card_type === 'Creature') {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell', undefined, ctx.rng);
      }
    }
  },
});
