// Helgrem -- "All for One: Discard a Creature from your hand. Choose a copy of the discarded
// Creature in play. Restore the chosen Creature to its starting energy." The target pool can't
// depend on which hand card gets discarded (powerTargets is computed independently of
// handDiscardCost's choice), so it offers every Creature in play and resolvePower does the real
// validation -- same "resolve function re-validates, base engine doesn't" pattern Xandia already
// uses for its own handDiscardCost + chosenTargetId combo. Helgrem's passive effect ("One for
// All: Players cannot play a Creature if a copy of that Creature is in play") is a static
// Play-phase restriction from the `effects` field, not this Power. BUILT 2026-07-28 (ability-count
// sweep) -- the comment below used to say "unimplemented, same documented gap as every other
// passive-effects-text card pending task #26", which went stale when preventsPlayOf landed (task
// #50c). Nothing re-read it, which is exactly the failure mode the sweep exists to catch.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveStartingEnergy } from '../targeting.js';
import { discardFromHand, restoreEnergy } from '../effects.js';

registerCardEffect('Helgrem', {
  // "One for All: PLAYERS cannot play a Creature if a copy of that Creature is in play." Both
  // sides -- no controller filter, unlike most preventsPlayOf users -- and "a copy" means the same
  // card definition anywhere in play, either player's side, matching how All for One above reads
  // "a copy of the discarded Creature in play".
  preventsPlayOf: (state, cardDb, playedDef) => {
    if (playedDef.card_type !== 'Creature') return false;
    for (const player of state.players.values()) {
      for (const card of player.inPlay) {
        if (cardDb.get(card.definitionKey)?.name === playedDef.name) return true;
      }
    }
    return false;
  },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'All for One') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;

    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandCardIds![0]);
    const discardedDef = discardedCard ? ctx.cardDb.get(discardedCard.definitionKey) : undefined;
    if (!discardedDef || discardedDef.card_type !== 'Creature') return;

    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (ctx.cardDb.get(target.definitionKey)?.name !== discardedDef.name) return; // must be "a copy"

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    restoreEnergy(ctx.state, ctx.cardDb, target, effectiveStartingEnergy(ctx.state, ctx.cardDb, target));
  },
});
