// Stalk (Spell, Paradwyn, cost 1) -- "Choose any one opposing Creature in play. Until the end of
// your next turn, the chosen Creature is stalked; whenever a stalked Creature is attacked,
// discard one energy from the stalked Creature before energy is removed." Direct application of
// the existing generic STALKED duration tag (combat.ts's own generic check), same shape Jungle
// Jile's Mass Stalk already uses for a whole player's board -- this is just the single-target Spell
// version, "until the end of your next turn" = nextOwnTurnNumber(state).

import { registerCardEffect } from './registry.js';
import { opposingCreatures } from '../targeting.js';
import { addDurationTag, STALKED, nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Stalk', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    addDurationTag(ctx.state, ctx.cardDb, target, STALKED, nextOwnTurnNumber(ctx.state));
  },
});
