// Undertow (Spell) -- "Choose any one Creature in play. Discard the chosen Creature from play.
// The chosen Creature's owner then shuffles that Creature back into his or her deck." Exact-fit
// existing helper: effects.ts's shuffleFromPlayIntoOwnersDeck (built task #46, 2026-07-18, for
// Barqua's Bubble/Parathin Shell) already removes a card from play and reshuffles it into its
// TRUE owner's deck in one step -- the printed "discard... then shuffle" phrasing is just this
// engine's usual way of describing that same net effect.

import { registerCardEffect } from './registry.js';
import { shuffleFromPlayIntoOwnersDeck } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';

registerCardEffect('Undertow', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    shuffleFromPlayIntoOwnersDeck(ctx.state, ctx.cardDb, target, ctx.rng);
  },
});
