// Forgotten Dreams -- "Choose four non-Spell cards in your discard pile. Shuffle the chosen cards
// into your deck. Draw a card." (task #350, Layer 2 of the discard-pile-visibility project,
// 2026-07-20.) First Spell-side user of registry.ts's spellDiscardPileSearch -- reuses the exact
// same shape/UI picker a Power's discardPileSearch already has (Craw/Delia/etc), and the first-ever
// count>1 discardPileSearch user across either side. That surfaced a real Play.tsx gap this pass
// fixed: the Confirm-button readiness gate used to require the chosen count to match the PRINTED
// count exactly, which would have made this Spell permanently unplayable whenever the discard pile
// had fewer than 4 matching cards -- now capped at the live pool size, same "fizzle gracefully with
// fewer" convention every other undersized pool in this codebase already gets.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { shuffleDeck } from '../zones.js';
import type { CardDatabase } from '../types/card.js';

function isNonSpell(cardDb: CardDatabase, definitionKey: number): boolean {
  return cardDb.get(definitionKey)?.card_type !== 'Spell';
}

registerCardEffect('Forgotten Dreams', {
  spellDiscardPileSearch: {
    count: 4,
    filter: (state, cardDb, playerId, card) => isNonSpell(cardDb, card.definitionKey),
  },
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    const ids = ctx.chosenDiscardPileIds ?? [];
    let movedAny = false;
    for (const id of ids) {
      const index = player.discardPile.findIndex((c) => c.instanceId === id);
      if (index === -1) continue;
      const [card] = player.discardPile.splice(index, 1);
      player.deck.push(card!);
      movedAny = true;
    }
    // Only shuffle if something actually moved -- nothing chosen (empty discard pile) is a clean
    // no-op for this clause, same "fizzle silently" convention as every other empty-pool pick.
    if (movedAny) shuffleDeck(player, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, player, 1);
  },
});
