// Carnivorous Cave (Spell, Underneath, cost 3) -- "Discard one energy from each Creature and Magi
// in play. Carnivorous Cave does not affect burrowed Creatures." No targeting: a board-wide sweep
// hitting BOTH sides, including the caster's own cards (the printed text has no "opposing"
// qualifier -- same symmetric shape as Ominous Chill and Cave In below it).
//
// The burrow exemption is a full skip, not a capped loss: burrowed Creatures normally still lose
// energy up to burrowCappedLoss' 2-per-turn ceiling, but this card's own text exempts them
// outright. Checked via isBurrowed so granted burrowing (Tunnel Hyren, Granas, Urigant, Kier,
// Muggum) counts, not just the duration tag.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, allMagiInPlay } from '../targeting.js';
import { isBurrowed } from '../durationTags.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Carnivorous Cave', {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- unconditional (no region/burrow
  // exemption applies to a Magi), so this only checks that an opposing Magi actually exists.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId) => getOpponents(state, actingPlayerId).some((opp) => !!opp.activeMagi),
  resolveSpell: (ctx) => {
    const casterId = ctx.controllingPlayer.playerId;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (isBurrowed(ctx.state, ctx.cardDb, creature)) continue;
      discardEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell', casterId, ctx.rng);
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      discardEnergy(ctx.state, ctx.cardDb, magi, 1, 'spell', casterId, ctx.rng);
    }
  },
});
