// Morag's 'Gift' (Spell, Core, cost 3) -- "If you have a Creature in play, choose an opposing Magi.
// Attach Morag's 'Gift' to the chosen Magi. Return any one of your Creatures to your hand,
// discarding all of that Creature's energy. While Morag's 'Gift' is in play, whenever the chosen
// Magi plays a Creature, add two energy to your Magi. A Magi can only be affected by one copy of
// Morag's 'Gift' at a time." Task #53-7, 2026-07-21, the Core Spell pass's A4 batch.
//
// spellStaysInPlay (Crystal Vision's mechanism), tracking the target Magi by instance id -- same
// shape as Paranoia/Stealth/Shadow Rain this pass. "Return any one of your Creatures" is a genuine
// second, independent choice (Abwyn's Gift/Sorreah's Dream precedent: `spellSecondTargets` ->
// `chosenSecondTargetId`) -- `returnToHand` already nulls the returned card's energy on its own
// (every return-to-hand does), so "discarding all of that Creature's energy" needs no extra code.
//
// "A Magi can only be affected by one copy... at a time" -- rather than a stacking-cap counter (Gia
// Pet's Impede precedent doesn't quite fit: that caps a broadcast CONTRIBUTION, this caps how many
// copies may even ATTACH to the same target), `spellTargets` derives "already claimed" live from the
// board (every in-play Morag's 'Gift' instance's own tracked-target tag), so a second copy simply
// never offers an already-affected Magi as a legal choice -- no separate mark-and-clean-up needed on
// the target itself.
//
// "Whenever the chosen Magi plays a Creature" is scoped to that SPECIFIC Magi instance, not just
// "that player" -- re-checked against `state.players.get(...).activeMagi` each time, since a
// defeated-and-succeeded Magi should no longer trigger it (matching "the chosen Magi," not "that
// player," per the printed text).
//
// BUG FIX (2026-07-24, playtest report): "Attach Morag's 'Gift' to the chosen Magi" means the card
// itself should leave play once that Magi does -- it was only gating the energy-BONUS trigger on
// the target still being active, never actually discarding itself, so it sat in the caster's play
// indefinitely (an unintended snowball if the caster's own Magi survives). Two hooks now cover
// both ways the target Magi can stop being active:
// - `onAnyMagiDefeated` (Corrupt's own exact precedent, same printed-text shape: "If the chosen
//   Magi is discarded from play, discard Corrupt from play") -- immediate, for a genuine defeat.
// - `standingConditionMet` -- the generic "continuously monitored condition" family (Rous/Vrak/
//   Furlosk's Companionship precedent), checked after any card is played/discarded anywhere.
//   Needed because a voluntary Magi swap (M'Rika's Interchange, Giant Parathin's Interchange) does
//   NOT go through defeatMagi/checkMagiDefeats at all (the old Magi goes back into magiQueue,
//   undefeated) -- onAnyMagiDefeated never fires for it. findCreatureOrMagiById only ever resolves
//   an instance id via inPlay or a player's CURRENT activeMagi, so "not found" here correctly means
//   "no longer anyone's active Magi" for BOTH the defeat and the swap case, no separate branching
//   needed. This one is delayed until the next play/discard anywhere in the game (not instantaneous
//   like onAnyMagiDefeated), same delay-tolerant shape as every other standingConditionMet user.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, creaturesControlledBy, findCreatureOrMagiById } from '../targeting.js';
import { returnToHand, addEnergy, discardFromPlay } from '../effects.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const TARGET_PREFIX = 'moragsGiftTarget:';

function trackedTargetId(self: { tags: ReadonlySet<string> }): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(TARGET_PREFIX));
  return tag ? tag.slice(TARGET_PREFIX.length) : undefined;
}

function alreadyClaimedMagiIds(state: GameState, cardDb: CardDatabase): Set<string> {
  const result = new Set<string>();
  for (const p of state.players.values()) {
    for (const c of p.inPlay) {
      if (cardDb.get(c.definitionKey)?.name !== "Morag's 'Gift'") continue;
      const id = trackedTargetId(c);
      if (id) result.add(id);
    }
  }
  return result;
}

registerCardEffect("Morag's 'Gift'", {
  preventsOwnPlay: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).length > 0
      ? false
      : "Morag's 'Gift' can only be played if you have a Creature in play",
  spellTargets: (state, cardDb, playerId) => {
    const claimed = alreadyClaimedMagiIds(state, cardDb);
    return allMagiInPlay(state).filter((m) => m.controllerId !== playerId && !claimed.has(m.instanceId));
  },
  spellSecondTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    if (alreadyClaimedMagiIds(ctx.state, ctx.cardDb).has(ctx.chosenTargetId)) return; // re-validate, stale choice
    const targetMagi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!targetMagi) return;

    if (ctx.chosenSecondTargetId) {
      const owned = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).some(
        (c) => c.instanceId === ctx.chosenSecondTargetId
      );
      if (owned) returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenSecondTargetId);
    }

    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${TARGET_PREFIX}${targetMagi.instanceId}`);
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  onPlay: (state, cardDb, played, self) => {
    const targetId = trackedTargetId(self);
    if (!targetId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    const targetMagi = findCreatureOrMagiById(state, targetId);
    if (!targetMagi) return;
    if (state.players.get(targetMagi.controllerId)?.activeMagi?.instanceId !== targetMagi.instanceId) return;
    if (played.controllerId !== targetMagi.controllerId) return;

    const casterMagi = state.players.get(self.controllerId)?.activeMagi;
    if (casterMagi) addEnergy(state, cardDb, casterMagi, 2, 'spell');
  },
  onAnyMagiDefeated: (state, cardDb, self, defeatedMagi, defeatedPlayerId, rng) => {
    const targetId = trackedTargetId(self);
    if (!targetId || defeatedMagi.instanceId !== targetId) return;
    removePermanentTag(self, `${TARGET_PREFIX}${targetId}`);
    const owner = state.players.get(self.controllerId);
    if (owner && owner.inPlay.some((c) => c.instanceId === self.instanceId)) {
      discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    }
  },
  standingConditionMet: (state, cardDb, self) => {
    const targetId = trackedTargetId(self);
    return !!targetId && !findCreatureOrMagiById(state, targetId);
  },
});
