// Keggerop -- "Momentum: Once per turn, when you play a Bograth Creature, you may add energy to
// it equal to the number of your other Bograth Creatures in play. Discard one of your Bograth
// Creatures from play." onPlay broadcast (own Bograth Creature) + once-per-turn duration tag +
// addEnergy (count of OTHER own Bograth Creatures, computed BEFORE the discard below) +
// auto-picked self-discard (a DIFFERENT own Bograth Creature, lowest current energy -- sacrificing
// the least valuable one). "You may" applied whenever there's at least one other Bograth Creature
// to discard -- with none, the trade is a pure loss (discard for zero energy), so it's skipped.
//
// Emlob retrofit (task #30, 2026-07-15): the +3 applies to the COUNTED energy amount, not to the
// actual pool of sacrificeable Bograth Creatures -- Emlob inflates the NUMBER Momentum's text
// reads, not the real board state a sacrifice still needs to exist within.
//
// Bograth-count-helper sweep (Bograth-cluster follow-up, 2026-07-21): the energy AMOUNT now reads
// targeting.ts's effectiveBograthCreatureCount (which already folds in Emlob's bonus) minus 1, to
// exclude `played` itself (already sitting in play by the time this onPlay hook fires) the same
// way the old raw `otherBograth.length` did -- picks up Bog Stench's virtual +2 for free. The real
// sacrifice pool (`otherBograth`) stays a raw filtered list of ACTUAL Creatures, unaffected by any
// virtual bonus, since there's nothing real to discard if the board doesn't have one.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { creaturesControlledBy, effectiveBograthCreatureCount, effectiveRegions } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const MOMENTUM_USED = 'kegeropMomentumUsedThisTurn';

registerCardEffect('Keggerop', {
  onPlay: (state, cardDb, played, self, rng) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    // In-play Creature region check on `played` -- routes through effectiveRegions so Glablit's
    // Dream Blur (Category D EIGHTH item, 2026-08-12, task #725) fires Momentum on a played Core
    // Creature under Glablit's controller (Dream Blur makes it also Bograth).
    if (!effectiveRegions(state, cardDb, played).includes('Bograth')) return;
    if (hasDurationTag(self, MOMENTUM_USED)) return;

    const otherBograth = creaturesControlledBy(state, cardDb, self.controllerId).filter(
      (c) => c.instanceId !== played.instanceId && effectiveRegions(state, cardDb, c).includes('Bograth')
    );
    if (otherBograth.length === 0) return; // no discard target -- trade would be a pure loss

    addDurationTag(state, cardDb, self, MOMENTUM_USED, state.turnNumber);
    const amount = Math.max(0, effectiveBograthCreatureCount(state, cardDb, self.controllerId) - 1);
    addEnergy(state, cardDb, played, amount, 'effect');
    const sacrifice = otherBograth.reduce((worst, c) => ((c.currentEnergy ?? 0) < (worst.currentEnergy ?? 0) ? c : worst));
    const owner = state.players.get(self.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, sacrifice.instanceId, undefined, undefined, rng);
  },
});
