// Pyte -- "Luck: Add one to every die you roll, to a maximum of six." Checked by effects.ts's
// rollDie itself via its optional luckContext param (task #31, 2026-07-16) -- applies to EVERY
// individual die a multi-die roller rolls (Greater Vaal's two dice each get +1, not the sum).
//
// "Respite: When you defeat an opposing Magi, draw two cards." New
// onOpponentMagiDefeatedByActivePlayer hook (energy.ts's defeatMagi).

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Pyte', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Luck is the +1 per die-roll modifier; Respite
  // is the two-card draw on opposing-Magi defeat.
  effectHooks: {
    Luck: ['addsToOwnDieRolls'],
    Respite: ['onOpponentMagiDefeatedByActivePlayer'],
  },
  addsToOwnDieRolls: () => 1,
  onOpponentMagiDefeatedByActivePlayer: (state, cardDb, self) => {
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    drawCards(state, cardDb, owner, 2);
  },
});
