// Mombak -- "Cold Pack: Choose another Creature. Add one energy to the chosen Creature. Add two
// additional energy if that Creature is frozen." The frozen bonus is now live (FROZEN shipped
// 2026-07-08, see durationTags.ts's isFrozen) -- this comment previously said it was inert
// pending task #26, which was already stale. Excludes itself at the POOL level too (via
// sourceInstanceId, same fix as Flame Rudwot's Healing Flame -- see registry.ts's powerTargets doc
// comment), not just in resolvePower's post-hoc check -- a real bug caught in playtesting
// (PROGRESS_LOG.md, 2026-07-09).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Mombak', {
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) =>
    allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== sourceInstanceId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Cold Pack') return;
    if (ctx.chosenTargetId === undefined || ctx.chosenTargetId === ctx.source.instanceId) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    addEnergy(ctx.state, ctx.cardDb, target, isFrozen(ctx.state, ctx.cardDb, target) ? 3 : 1, 'power');
  },
});
