// Osatch -- "Sentry: Your Relics and other Creatures may not be discarded from play or returned
// to your hand by opposing cards that specifically affect Creatures in this way. Opposing cards
// may not gain control of your Relics and other Creatures." Plus the unnamed clause: "At the
// beginning of your turn, discard Osatch from play." Plus "Weave: Whenever Osatch attacks or is
// attacked, before energy is removed, you may move one energy between it and one of your other
// Weave Creatures in play." (see weave.ts)
//
// Sentry BUILT 2026-08-11 (post-audit deferred-gap closure pass), all three broadcast hooks
// (`preventsDiscardOf`, `preventsReturnToHand`, `preventsGainControlOf` -- Tal'ik's Standing Tall
// is the direct precedent for all three, just board-wide-among-own-cards here instead of one
// tagged Creature). "Specifically affect" is read the same as every other "specifically discard"
// card in this codebase (Vault of Knowledge Key etc.): gate the discard clause on
// `cause === 'explicit'`, don't try to look back into the hostile card's own text. Osatch itself
// is excluded ("your Relics and OTHER Creatures").

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { applyWeave } from './weave.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

function protectsAsOsatchSentry(cardDb: CardDatabase, target: CardInstance, self: CardInstance): boolean {
  if (target.controllerId !== self.controllerId || target.instanceId === self.instanceId) return false;
  const def = cardDb.get(target.definitionKey);
  return def?.card_type === 'Relic' || def?.card_type === 'Creature';
}

registerCardEffect('Osatch', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Sentry owns the three prevent
  // broadcasts; Weave owns the move hook + `weaveConfig`. Osatch's unnamed clause ("At the
  // beginning of your turn, discard Osatch from play") has no printed name -- left unlisted per
  // E1's skip-unnamed rule; its `onOwnTurnStart` field falls back to whole-card grant if Taglat
  // ever copies the unnamed clause explicitly (which it can't, having no name to reference).
  effectHooks: {
    Sentry: ['preventsDiscardOf', 'preventsReturnToHand', 'preventsGainControlOf'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  onOwnTurnStart: (state, cardDb, self, rng) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
  preventsDiscardOf: (state, cardDb, target, self, cause) =>
    cause === 'explicit' && protectsAsOsatchSentry(cardDb, target, self),
  preventsReturnToHand: (state, cardDb, target, self) => protectsAsOsatchSentry(cardDb, target, self),
  preventsGainControlOf: (state, cardDb, target, self) => protectsAsOsatchSentry(cardDb, target, self),
});
