// Hubdra's Spear -- "Stab (4): Choose any one Magi with no Creatures in play. Discard Hubdra's
// Spear from play. Discard all but one energy from the chosen Magi."

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, creaturesControlledBy, findCreatureOrMagiById } from '../targeting.js';
import { discardFromPlay, restoreEnergy } from '../effects.js';

registerCardEffect("Hubdra's Spear", {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb) => allMagiInPlay(state).filter((m) => creaturesControlledBy(state, cardDb, m.controllerId).length === 0),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Stab') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;
    if (creaturesControlledBy(ctx.state, ctx.cardDb, target.controllerId).length > 0) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    restoreEnergy(ctx.state, ctx.cardDb, target, Math.min(1, target.currentEnergy ?? 0));
  },
});
