// Tuku -- "Restrain: (2) Until the end of your next turn, no Magi can play any non-Universal Relics
// or Spells. You cannot use Restrain on your next turn." A duration-scoped, both-sides play lockdown
// (registry.ts's preventsPlayOf, gated on a duration tag) plus a self-cooldown. Both the lockdown and
// the cooldown run through the controller's next turn (nextTurnNumberFor), so they expire together:
//   - RESTRAIN_ACTIVE gates preventsPlayOf -> blocks every player's non-Universal Relic/Spell plays.
//   - CANNOT_USE_POWER on Tuku (power.ts consults it) enforces "cannot use Restrain on your next
//     turn"; Restrain is Tuku's only Power, so a card-wide power lock is safe.

import { registerCardEffect } from './registry.js';
import { addDurationTag, hasDurationTag, nextTurnNumberFor, CANNOT_USE_POWER } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { isUniversal } from '../regions.js';

const RESTRAIN_ACTIVE = 'tukuRestrainActive';

registerCardEffect('Tuku', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Restrain') return;
    const expiry = nextTurnNumberFor(ctx.state, ctx.source.controllerId); // "until the end of your next turn"
    addDurationTag(ctx.state, ctx.cardDb, ctx.source, RESTRAIN_ACTIVE, expiry);
    addRestrictionTag(ctx.state, ctx.source, CANNOT_USE_POWER, expiry); // "cannot use Restrain on your next turn"
  },
  preventsPlayOf: (_state, _cardDb, playedDef, _playerId, self) => {
    if (!hasDurationTag(self, RESTRAIN_ACTIVE)) return false;
    if (isUniversal(playedDef.regions)) return false;
    return playedDef.card_type === 'Relic' || playedDef.card_type === 'Spell';
  },
});
