// Granite Hyren -- "Improved Invulnerability: Granite Hyren loses three less energy in attacks."
// (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Granite Hyren', {
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 3),
});
