// Mirage (Spell, d'Resh/d'Resh-Shadow-Magi-only per its own text) -- "Remove one energy from each
// opposing non-Illusion Creature. Add one energy to each Illusion. Only d'Resh and d'Resh Shadow
// Magi may play Mirage." No target, no choice -- a pure board sweep. "Opposing" scopes the first
// clause to the caster's opponents' Creatures; the second clause has no "opposing" qualifier, so it
// covers every Illusion in play regardless of side. Region restriction is already data-driven
// (region_restrictive) -- no engine work needed for that half.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';

registerCardEffect('Mirage', {
  resolveSpell: (ctx) => {
    const caster = ctx.controllingPlayer.playerId;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      const isIllusion = ctx.cardDb.get(creature.definitionKey)?.subtype === 'Illusion';
      if (isIllusion) {
        addEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell');
      } else if (creature.controllerId !== caster) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell', undefined, ctx.rng);
      }
    }
  },
});
