// Paradar -- "Wait: At the end of your Attack step, if Paradar did not attack, draw a card."

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Paradar', {
  onOwnAttackStepEnd: (state, cardDb, self) => {
    if (self.attackedThisTurn) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    drawCards(state, cardDb, player, 1);
  },
});
