// Lifeweave (Weave Spell, cost 2) -- "Discard your hand. If you discarded two or more cards, add
// two energy to each of your Weave Creatures in play."
//
// Weave Spell pass (2026-07-26), Category A. Hand size is read BEFORE the discard, since the
// bonus keys off how many were actually discarded. Lifeweave itself is already out of hand by the
// time resolveSpell runs (play.ts removes it first), so it never counts toward its own threshold.
// checkHandEmptied afterwards for Aubra's Canteen's onOwnHandEmptied reactor, same as every other
// whole-hand discard in this codebase (gremble.ts precedent).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromHand, checkHandEmptied } from '../effects.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';

registerCardEffect('Lifeweave', {
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    const handIds = player.hand.map((c) => c.instanceId);
    const discarded = handIds.length;
    if (discarded > 0) discardFromHand(ctx.state, ctx.cardDb, player, handIds, undefined, ctx.rng);
    if (discarded >= 2) {
      for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, player.playerId)) {
        if (effectiveRegions(ctx.state, ctx.cardDb, creature).includes('Weave')) {
          addEnergy(ctx.state, ctx.cardDb, creature, 2, 'spell');
        }
      }
    }
    checkHandEmptied(ctx.state, ctx.cardDb, ctx.rng);
  },
});
