// Fog Bank (Spell) -- "Choose any one Creature in play. The chosen Creature cannot be attacked
// during your opponents' next two turns. Place this card on the chosen Creature while Fog Bank is
// in effect." Uses durationTags.ts's existing CANNOT_BE_ATTACKED tag (already read by combat.ts's
// isLegalAttack), expiring after the SECOND of the caster's opponent's next two turns (2-player:
// nextTurnNumberFor + one more full round). DOCUMENTED SIMPLIFICATION: "place this card on the
// chosen Creature" is a physical marker with no separate rules effect beyond the CANNOT_BE_ATTACKED
// duration itself (which the tag already enforces) -- Fog Bank goes to the discard pile immediately
// like every other Spell, rather than sitting in attachedCards for two turns.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addDurationTag, CANNOT_BE_ATTACKED, nextTurnNumberFor } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Fog Bank', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const opponent = getOpponents(ctx.state, ctx.controllingPlayer.playerId)[0];
    if (!opponent) return;
    const expiry = nextTurnNumberFor(ctx.state, opponent.playerId) + ctx.state.turnOrder.length;
    addRestrictionTag(ctx.state, target, CANNOT_BE_ATTACKED, expiry);
  },
});
