// Dune Compass -- "True Path: During your Draw step, if you have three or more Oracles in play,
// draw an additional card." Built via registry.ts's drawCountModifier (Scarletsong Banner/Tropical
// Plith precedent). "Oracles" is a subtype (types/card.ts), not restricted to Creatures --
// Risha (Magi) and Dune Compass itself are also subtype 'Oracle', so the count is taken over the
// controller's full board (activeMagi + inPlay), same "contributors" shape used everywhere else.

import { registerCardEffect } from './registry.js';

registerCardEffect('Dune Compass', {
  drawCountModifier: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return 0;
    const contributors = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
    const oracleCount = contributors.filter((c) => cardDb.get(c.definitionKey)?.subtype === 'Oracle').length;
    return oracleCount >= 3 ? 1 : 0;
  },
});
