// Jagged Rocks (Spell) -- "Add two energy to the smallest Kybar's Teeth Creature in play. Discard
// three energy from the largest non-Kybar's Teeth Creature in play." Kybar's Teeth Spell pass,
// Category A (2026-07-22). Fully automatic, no chosen target -- no spellTargets registered (same
// shape as Tradewinds). Both halves are independent and optional (each only fires if a matching
// Creature exists); "the smallest/largest ... in play" is unowned (either player's board), not
// "your own," per the printed text.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions, smallestOf, regionForTargetFilter } from '../targeting.js';

registerCardEffect('Jagged Rocks', {
  resolveSpell: (ctx) => {
    const pool = allCreaturesInPlay(ctx.state, ctx.cardDb);
    const kybarsTeethRegion = regionForTargetFilter(ctx.state, "Kybar's Teeth");
    const kybarsTeeth = pool.filter((c) => effectiveRegions(ctx.state, ctx.cardDb, c).includes(kybarsTeethRegion));
    const smallest = smallestOf(kybarsTeeth);
    if (smallest) addEnergy(ctx.state, ctx.cardDb, smallest, 2, 'spell');

    const others = pool.filter((c) => !effectiveRegions(ctx.state, ctx.cardDb, c).includes(kybarsTeethRegion));
    if (others.length > 0) {
      const largest = others.reduce((best, c) => ((c.currentEnergy ?? 0) > (best.currentEnergy ?? 0) ? c : best));
      const amount = Math.min(largest.currentEnergy ?? 0, 3);
      if (amount > 0) discardEnergy(ctx.state, ctx.cardDb, largest, amount, 'spell', undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ["Kybar's Teeth"],
});
