// Sunbeam's End (Spell) -- "Choose a Creature and add one energy to it. If you played a copy of
// Starlight's Genesis this turn, you may remove two energy from your Magi to add two extra energy
// to that Creature." Combos with starlightsGenesis.ts -- see that file's own header comment for the
// shared playedCardNameThisTurn mechanism.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { allCreaturesInPlay, findInPlayById, playedCardNameThisTurn } from '../targeting.js';

registerCardEffect("Sunbeam's End", {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellBooleanChoice: (state, cardDb, playerId) =>
    playedCardNameThisTurn(state, playerId, "Starlight's Genesis")
      ? { prompt: 'Remove two energy from your Magi to add two extra energy to the chosen Creature?', yesLabel: 'Yes', noLabel: 'No' }
      : undefined,
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    addEnergy(ctx.state, ctx.cardDb, target, 1, 'spell');
    if (ctx.chosenBoolean && playedCardNameThisTurn(ctx.state, ctx.controllingPlayer.playerId, "Starlight's Genesis")) {
      const magi = ctx.controllingPlayer.activeMagi;
      if (magi) {
        discardEnergy(ctx.state, ctx.cardDb, magi, 2, 'spell', undefined, ctx.rng);
        addEnergy(ctx.state, ctx.cardDb, target, 2, 'spell');
      }
    }
  },
});
