// Muck Rain (Spell) -- "Choose an opposing Magi. If the number of Bograth Creatures you have in
// play is greater than the chosen Magi's Energize rate, choose one of that Magi's Creatures.
// Discard the chosen Creature." Bograth Spell pass, Category B2 (2026-07-20). effectiveEnergizeRate
// (turn.ts) for the comparison (precedent: blygtsRing.ts's Purity clause does the identical
// comparison). The "choose a Magi, THEN choose one of THAT Magi's Creatures" chain has no native
// Spell equivalent (spellTargets is single-target only -- Spells have no spellTargetSlots the way
// Powers have powerTargetSlots), so the second pick runs as a pendingTargetChoice/resolveTargetChoice
// follow-up after resolveSpell returns (same idiom blygtsRing.ts already uses for its own deferred
// pick) -- Muck Rain itself is already sitting in the discard pile by the time this fires (a Spell
// resolves once and moves there immediately), but the permanent tag marking the pending choice
// survives the zone move unchanged, and pendingTargetChoice's own 5-zone scan finds it there.

import { registerCardEffect } from './registry.js';
import { opposingMagi, findCreatureOrMagiById, creaturesControlledBy, effectiveBograthCreatureCount } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { effectiveEnergizeRate } from '../turn.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const PENDING_PREFIX = 'muckRainPendingFor:';

function pendingTargetControllerId(self: CardInstance): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(PENDING_PREFIX));
  return tag ? tag.slice(PENDING_PREFIX.length) : undefined;
}

function creaturePool(state: GameState, cardDb: CardDatabase, targetControllerId: string): CardInstance[] {
  return creaturesControlledBy(state, cardDb, targetControllerId);
}

registerCardEffect('Muck Rain', {
  spellTargets: (state, cardDb, playerId) => opposingMagi(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return; // must be opposing

    const bograthCount = effectiveBograthCreatureCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    const energizeRate = effectiveEnergizeRate(ctx.state, ctx.cardDb, target);
    if (bograthCount <= energizeRate) return;
    if (creaturePool(ctx.state, ctx.cardDb, target.controllerId).length === 0) return;

    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${PENDING_PREFIX}${target.controllerId}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const targetControllerId = pendingTargetControllerId(self);
    if (!targetControllerId) return undefined;
    const pool = creaturePool(state, cardDb, targetControllerId);
    if (pool.length === 0) return undefined;
    return { prompt: "Muck Rain: choose one of the chosen Magi's Creatures to discard", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const targetControllerId = pendingTargetControllerId(self);
    if (targetControllerId) removePermanentTag(self, `${PENDING_PREFIX}${targetControllerId}`);
    if (!chosenInstanceId || !targetControllerId) return;
    const chosen = creaturePool(state, cardDb, targetControllerId).find((c) => c.instanceId === chosenInstanceId);
    if (!chosen) return;
    const owner = state.players.get(targetControllerId);
    if (owner) discardFromPlay(state, cardDb, owner, chosen.instanceId, undefined, undefined, rng);
  },
});
