// Plith -- "Warning: If Plith is attacked, draw one card. If Evu is your Magi when Plith is
// attacked, draw one additional card." Matches Evil Evu too (magiIdentity.ts's magiCountsAs,
// 2026-07-10 fix -- was a raw name check before).

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { magiCountsAs } from './magiIdentity.js';

registerCardEffect('Plith', {
  onAttack: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    const magi = ctx.defendingPlayer.activeMagi;
    drawCards(ctx.state, ctx.cardDb, ctx.defendingPlayer, magi && magiCountsAs(ctx.cardDb, magi, 'Evu') ? 2 : 1);
  },
});
