// Stone Quor -- "Squeeze: Choose any one opposing Creature. Move half of the chosen Creature's
// energy (rounded up) to your Magi."
// "Invulnerability: Stone Quor loses one less energy in attacks." (invulnerability.ts) -- was
// missing entirely, no deferral comment, caught during the Kybar's Teeth region pass's partial-file
// audit (task #42, 2026-07-17).

import { registerCardEffect } from './registry.js';
import { opposingCreatures, findInPlayById } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Stone Quor', {
  powerTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Squeeze') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;

    const half = Math.ceil((target.currentEnergy ?? 0) / 2);
    rearrangeEnergy(ctx.state, ctx.cardDb, target, magi, half, ctx.rng);
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
});
