// Tropical Vinoc -- "Stalk: Discard a card from your hand. Choose any one opposing Creature in
// play. Until the end of your next turn, the chosen Creature is stalked; whenever a stalked
// Creature is attacked, discard one energy from the stalked Creature before energy is removed.
// You can use this Power any number of times during your turn." Bridges all three new pieces
// built this batch: hand-discard-cost, the STALKED duration tag (durationTags.ts), and the new
// `repeatable` override -- the first (and, per Bagala Hunter/Jungle Jile/Stalker's Boots'
// identical wording, far from only) card that ignores the normal once-per-turn Power rule.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, findInPlayById } from '../targeting.js';
import { discardFromHand } from '../effects.js';
import { addDurationTag, STALKED, nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Tropical Vinoc', {
  powerTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  handDiscardCost: { count: 1 },
  repeatable: true,
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Stalk') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return; // must be opposing

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    addDurationTag(ctx.state, ctx.cardDb, target, STALKED, nextOwnTurnNumber(ctx.state));
  },
});
