// Vulbor -- "Mind Shock (3): Choose any one player. The chosen player must discard two cards of
// his or her choice from his or her hand." Same "TARGET's own choice, mandatory count" pattern as
// Black Agovo -- reuses opponentHandDiscardChoice, with resolvePower requiring the target's
// controller to have chosen exactly min(2, hand.length) cards. Not to be confused with Giant
// Vulbor, a different card whose mitigation really is optional.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardFromHand } from '../effects.js';

registerCardEffect('Vulbor', {
  powerTargets: (state) => allMagiInPlay(state),
  opponentHandDiscardChoice: { maxCount: 2 },
  causesOpponentHandDiscard: true, // task #718 (Riptide clause 2, 2026-08-11)

  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mind Shock') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const targetOwner = ctx.state.players.get(chosenMagi.controllerId);
    if (!targetOwner) return;

    const required = Math.min(2, targetOwner.hand.length);
    const offered = ctx.chosenOpponentHandCardIds ?? [];
    const validIds = offered.filter((id) => targetOwner.hand.some((c) => c.instanceId === id));
    if (validIds.length !== required) return;

    discardFromHand(ctx.state, ctx.cardDb, targetOwner, validIds, undefined, ctx.rng);
  },
});
