// Emec -- "Tinker: Once per turn, when you use a Power or Effect printed on one of your Kybar's
// Teeth Relic in play that involves a die roll, you may reroll one of those dice. If you do, you
// may choose which result to use." registry.ts's grantsDieReroll, consulted only by
// effects.ts's rollDieWithRerolls (see that hook's own doc comment for why the ~19 existing
// die-rolling cards in this codebase aren't retrofitted to call it in this batch). "Choose which
// result to use" is modeled by rollDieWithRerolls always keeping the higher of the two rolls,
// the default and correct direction for the overwhelming majority of real die-roll effects.

import { registerCardEffect } from './registry.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const USED_THIS_TURN = 'emecTinkerUsedThisTurn';

registerCardEffect('Emec', {
  grantsDieReroll: (state, cardDb, roller, self) => {
    if (hasDurationTag(self, USED_THIS_TURN)) return false;
    if (roller.controllerId !== self.controllerId) return false;
    const rollerDef = cardDb.get(roller.definitionKey);
    if (rollerDef?.card_type !== 'Relic' || !rollerDef.regions.includes("Kybar's Teeth")) return false;

    addDurationTag(state, cardDb, self, USED_THIS_TURN, state.turnNumber);
    return true;
  },
});
