// Grahnna -- "Transform: When you reveal Grahnna, if your previous Magi was Wiep, place any one
// Bograth card from your discard pile into your hand." Self-reactive onMagiRevealed, checking the
// last entry of `player.defeatedMagi` (append-ordered, so the most recent is always last).
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first eligible in discard-pile order"
// simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice).
//
// "Share: Whenever you play a Bograth Creature, choose any one Bograth Creature in play. Add one
// energy to the chosen Creature." Built this pass (task #30, 2026-07-15) -- her own file's earlier
// note claiming this needed a still-self-only `onPlay` hook was STALE: `onPlay` was widened to a
// full broadcast on 2026-07-10, well before this note was written (confirmed by reading
// registry.ts's current doc comment directly rather than trusting the file's own dated claim).
// Same `pendingTargetChoice`/`resolveTargetChoice` real-choice shape as her own "Transform" clause
// just below, a second independent pending-choice tag so the two don't collide if somehow both are
// live at once (not realistically possible today, but cheap to keep separate).

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, addPendingRevealChoiceTag, removePermanentTag } from '../durationTags.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const TRANSFORM_PENDING = 'grahnnaTransformPending';
const SHARE_PENDING = 'grahnnaSharePending';

function transformPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.discardPile.filter((c) => cardDb.get(c.definitionKey)?.regions.includes('Bograth'));
}

function sharePool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  return creaturesControlledBy(state, cardDb, self.controllerId).filter((c) => effectiveRegions(state, cardDb, c).includes('Bograth'));
}

registerCardEffect('Grahnna', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Transform arms on reveal (own-Wiep predecessor);
  // Share arms on own Bograth-Creature play. Both share the pendingTargetChoice/resolveTargetChoice
  // pair, which branches on its own tag internally, so per-Effect narrowing still fires only the
  // right branch on Taglat.
  effectHooks: {
    Transform: ['onMagiRevealed', 'pendingTargetChoice', 'resolveTargetChoice'],
    Share: ['onPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  onMagiRevealed: (state, cardDb, revealedMagi, self) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const previousMagi = player.defeatedMagi[player.defeatedMagi.length - 1];
    if (!previousMagi || cardDb.get(previousMagi.definitionKey)?.name !== 'Wiep') return;
    if (transformPool(state, cardDb, self).length === 0) return;
    addPendingRevealChoiceTag(self, TRANSFORM_PENDING); // onMagiRevealed -- owner-scoped window, see durationTags.ts
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    // In-play Creature region check on `played` -- routes through effectiveRegions so Glablit's
    // Dream Blur (Category D EIGHTH item, 2026-08-12, task #725) fires this trigger for a played
    // Core Creature under Glablit's controller (Dream Blur makes it also Bograth).
    if (!effectiveRegions(state, cardDb, played).includes('Bograth')) return;
    if (sharePool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, SHARE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (self.tags.has(TRANSFORM_PENDING)) {
      const pool = transformPool(state, cardDb, self);
      if (pool.length === 0) return undefined;
      return { prompt: "Grahnna's Transform: choose a Bograth card in your discard pile to return to hand", pool };
    }
    if (self.tags.has(SHARE_PENDING)) {
      const pool = sharePool(state, cardDb, self);
      if (pool.length === 0) return undefined;
      return { prompt: "Grahnna's Share: choose a Bograth Creature in play to add one energy to", pool };
    }
    return undefined;
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    if (self.tags.has(TRANSFORM_PENDING)) {
      removePermanentTag(self, TRANSFORM_PENDING);
      if (!chosenInstanceId) return;
      const player = state.players.get(self.controllerId);
      if (!player) return;
      const index = player.discardPile.findIndex((c) => c.instanceId === chosenInstanceId);
      if (index === -1) return;
      const [card] = player.discardPile.splice(index, 1);
      player.hand.push(card!);
      return;
    }
    if (self.tags.has(SHARE_PENDING)) {
      removePermanentTag(self, SHARE_PENDING);
      if (!chosenInstanceId) return;
      const target = sharePool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
      if (target) addEnergy(state, cardDb, target, 1, 'effect');
    }
  },
});
