// Sneaky Weebo -- "Skulk (1): Choose an opposing Naroom Creature. Remove one energy from it and
// add four energy to another Creature you control." Slot 2's pool excludes Sneaky Weebo itself
// precisely (2026-07-08 fix -- see registry.ts's powerTargets doc comment, same bug/fix as Flame
// Rudwot).

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, creaturesControlledBy, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Sneaky Weebo', {
  powerTargetSlots: (state, cardDb, playerId, _powerName, sourceInstanceId) => [
    {
      // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- this slot feeds
      // discardEnergy; the OWN Creature slot below feeds addEnergy and stays Creature-only.
      label: 'Choose an opposing Naroom Creature',
      pool: (s, db, pid) =>
        flexibleTargetPool(s, db, pid, opposingCreatures(s, db, pid), opposingMagi(s, db, pid)).filter((c) =>
          effectiveRegions(s, db, c).includes(regionForTargetFilter(s, 'Naroom'))
        ),
      min: 1,
      max: 1,
    },
    {
      label: 'Choose another Creature you control',
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid).filter((c) => c.instanceId !== sourceInstanceId),
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Skulk') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const oppTargetId = slots[0]?.[0];
    const ownTargetId = slots[1]?.[0];
    if (!oppTargetId || !ownTargetId) return;
    if (ownTargetId === ctx.source.instanceId) return; // must be ANOTHER Creature

    const oppTarget = findCreatureOrMagiById(ctx.state, oppTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!oppTarget || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, oppTarget, 'Creature')) return;
    if (oppTarget.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, oppTarget).includes(regionForTargetFilter(ctx.state, 'Naroom'))) return;
    const ownTarget = findCreatureOrMagiById(ctx.state, ownTargetId);
    if (!ownTarget || ctx.cardDb.get(ownTarget.definitionKey)?.card_type !== 'Creature') return;
    if (ownTarget.controllerId !== ctx.controllingPlayer.playerId) return;

    discardEnergy(ctx.state, ctx.cardDb, oppTarget, 1, undefined, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, ownTarget, 4, 'power');
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (The own-Creature slot is unrestricted -- only the
  // opposing Naroom Creature slot is in scope.)
  specifiedTargetRegions: () => ['Naroom'],
});
