// Keru -- "Weed: Search your deck for up to three cards and discard them. Shuffle your deck and
// draw a card." Unlike every other deckSearch card this batch, the found cards go to the DISCARD
// PILE, not hand -- searchDeck (hand-bound) doesn't fit, so this moves cards directly via
// zones.ts's removeFromZone/addToZone, the same primitives effects.ts's own searchDeck is built
// on top of.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { removeFromZone, shuffleDeck, moveToDiscardPile } from '../zones.js';

registerCardEffect('Keru', {
  deckSearch: { count: 'any' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Weed') return;
    const ids = (ctx.chosenDeckSearchIds ?? []).slice(0, 3);
    for (const id of ids) {
      if (!ctx.controllingPlayer.deck.some((c) => c.instanceId === id)) continue;
      const card = removeFromZone(ctx.controllingPlayer, 'deck', id);
      moveToDiscardPile(ctx.state, ctx.controllingPlayer, card);
    }
    shuffleDeck(ctx.controllingPlayer, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
  },
});
