// Chaos Plith -- "Guile: Whenever Chaos Plith defeats a Creature in an attack, draw a card. If Evu
// is your Magi, draw an additional card." Matches Evil Evu too (magiIdentity.ts's magiCountsAs).

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { magiCountsAs } from './magiIdentity.js';

registerCardEffect('Chaos Plith', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null || outcome.defenderSurvived) return;

    const magi = ctx.attackingPlayer.activeMagi;
    drawCards(ctx.state, ctx.cardDb, ctx.attackingPlayer, magi && magiCountsAs(ctx.cardDb, magi, 'Evu') ? 2 : 1);
  },
});
