// Reef Hyren -- "Rebuke: Whenever an opponent plays a Creature, you may discard one energy from
// your Magi. If you do, discard two energy from the Creature played." Broadcast onPlay reactor,
// optional-cost-then-effect (same shape as Koza's Steal paying its own cost).
//
// The Magi's own cost is paid via raw currentEnergy math (power.ts's own cost-payment convention),
// NOT discardEnergy -- a voluntary self-payment isn't "opposing" in the sense discardEnergy's
// burrow-cap/Shifty checks care about, regardless of whose turn it happens to be during.
// The energy discarded from the JUST-PLAYED (opposing) Creature passes `self.controllerId` as
// discardEnergy's `causedByPlayerId` -- this fires on the OPPONENT's turn, so `state.activePlayerId`
// alone would incorrectly read as "not opposing" (effects.ts's discardEnergy doc comment).
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice`. The just-played Creature
// is remembered via an embedded-id permanent tag (same technique as Skullek/Wellisk/Ahron/Gloves
// of Crystal/Hubram/Magam's Ring in this same batch) since the resolve call has no target
// parameter.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { checkMagiDefeats } from '../energy.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { findInPlayById } from '../targeting.js';

const PENDING_PREFIX = 'reefHyrenPending:';

function pendingPlayedId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return tag.slice(PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Reef Hyren', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return;
    addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${played.instanceId}`);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    const playedId = pendingPlayedId(self);
    if (playedId === undefined) return undefined;
    if (!findInPlayById(state, playedId)) return undefined;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return undefined;
    return {
      prompt: "Reef Hyren's Rebuke: discard one energy from your Magi to discard two from the Creature just played?",
      yesLabel: 'Discard 1 from Magi, 2 from Creature',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const playedId = pendingPlayedId(self);
    if (playedId !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${playedId}`);
    if (!chosenBoolean || playedId === undefined) return;
    const owner = state.players.get(self.controllerId);
    const magi = owner?.activeMagi;
    const played = findInPlayById(state, playedId);
    if (!owner || !magi || !played || (magi.currentEnergy ?? 0) < 1) return;
    magi.currentEnergy = Math.max(0, (magi.currentEnergy ?? 0) - 1);
    checkMagiDefeats(state, cardDb, rng);
    discardEnergy(state, cardDb, played, 2, 'effect', self.controllerId, rng);
  },
});
