// Spirit of the Flame (Spell, cost 1) -- "Choose any one Creature in play. Discard X Cald
// Creatures from your hand. Add X energy to the chosen Creature." Cald Spell pass, Category B
// (2026-07-20). cloudSceptre.ts's "discard N, gain N" pattern (spellHandDiscardCost: {count: 'any',
// filter: Cald Creature}, ids.length used directly as X) + fireflyAmulet.ts's Cald-region hand
// filter idiom. Choosing X=0 is a legal (if pointless) "any" pick -- same "return, no-op" handling
// cloudSceptre.ts's own Mindwinds already uses for a 0-card discard.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromHand } from '../effects.js';
import { allCreaturesInPlay, findInPlayById, regionForTargetFilter } from '../targeting.js';

registerCardEffect('Spirit of the Flame', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellHandDiscardCost: {
    count: 'any',
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, 'Cald'));
    },
  },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    const ids = (ctx.chosenHandCardIds ?? []).filter((id) => {
      const card = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
      const def = card && ctx.cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(ctx.state, 'Cald'));
    });
    if (ids.length === 0) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, ids.length, 'spell');
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ['Cald'],
});
