// Brub -- "Scrub: Choose any one Korrit in play. If you control the chosen Korrit, move all its
// energy to Brub. If not, discard the chosen Korrit." Same name.includes() pool-filter pattern as
// Cloud Narth's "a Pharan you control" and Moss Trulb's "another Trulb."
//
// Swirling Orshaa's Morph (Spell-pass audit follow-up, 2026-07-24) -- routed through
// matchesCreatureFamily() (checks a live Morph identityOverride first, falls back to the printed
// name substring), same reasoning as Xyx Minor.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, matchesCreatureFamily } from '../targeting.js';
import { rearrangeEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Brub', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => matchesCreatureFamily(cardDb, c, 'Korrit')),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Scrub') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!matchesCreatureFamily(ctx.cardDb, target, 'Korrit')) return;

    if (target.controllerId === ctx.controllingPlayer.playerId) {
      rearrangeEnergy(ctx.state, ctx.cardDb, target, ctx.source, target.currentEnergy ?? 0, ctx.rng);
    } else {
      const owner = ctx.state.players.get(target.controllerId);
      if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
    }
  },
  specifiedCreatureTypes: () => ['Korrit'],
});
