// Drowl -- both printed effects:
//   "Lore: When you play Drowl, draw two cards."
//   "Weave: Whenever Drowl attacks or is attacked, before energy is removed, you may move one
//   energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { applyWeave } from './weave.js';

registerCardEffect('Drowl', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Lore is the ETB draw-two; Weave is the
  // move hook + `weaveConfig`.
  effectHooks: {
    Lore: ['onPlay'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    const player = state.players.get(self.controllerId);
    if (player) drawCards(state, cardDb, player, 2);
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
});
