// Pruitt's Robe -- "Glimmer: Whenever you energize, you may choose any one of your Creatures in
// play. Add the energy to the chosen Creature instead of your Magi. If your Magi is Pruitt, you
// may also add two energy to her." Built task #45, 2026-07-18, the Naroom region pass.
//
// Two INDEPENDENT "may" clauses off the same trigger (afterMagiEnergized, task #12's own "after a
// Magi energizes" reactor -- "whenever you energize" means the Magi's own Energize-phase gain,
// same reading Nightmare Construct's Absorb already established): a redirect (pendingTargetChoice
// -- "instead of your Magi" is modeled as a post-hoc rearrangeEnergy moving the just-applied gain
// FROM the Magi TO the chosen Creature, since nothing else can react in the gap) and, only when
// the energizing Magi is Pruitt (via magiCountsAs, so this also matches her Alternate "Pruitt,
// Ringsmith" -- printed text says "If your Magi is Pruitt", the base card, not the Alternate), a
// separate flat +2 bonus (pendingYesNoChoice) that applies independently of whatever the redirect
// choice was ("also"). Two different pending-choice tags so both can be offered from the same
// energize event without colliding.
//
// BUG FIXED 2026-08-11 (post-audit deferred-gap closure pass): this previously checked
// `magiDef?.name === 'Pruitt, Ringsmith'` -- the Alternate's own literal name, not the base
// "Pruitt" the printed text actually names -- so the bonus fired backwards from the printed rule
// (only for the Alternate, never for base Pruitt).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addEnergy, rearrangeEnergy, setCounter, getCounter } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { magiCountsAs } from './magiIdentity.js';

const REDIRECT_PENDING = 'pruittsRobeRedirectPending';
const BONUS_PENDING = 'pruittsRobeBonusPending';
const PENDING_AMOUNT = 'pruittsRobePendingAmount';

registerCardEffect("Pruitt's Robe", {
  afterMagiEnergized: (state, cardDb, energizedMagi, self, amount) => {
    if (energizedMagi.controllerId !== self.controllerId) return;
    if (amount <= 0) return;

    setCounter(self, PENDING_AMOUNT, amount);
    if (creaturesControlledBy(state, cardDb, self.controllerId).length > 0) {
      addPendingChoiceTag(self, REDIRECT_PENDING);
    }

    if (magiCountsAs(cardDb, energizedMagi, 'Pruitt')) addPendingChoiceTag(self, BONUS_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(REDIRECT_PENDING)) return undefined;
    const pool = creaturesControlledBy(state, cardDb, self.controllerId);
    if (pool.length === 0) return undefined;
    return { prompt: "Pruitt's Robe's Glimmer: add this Energize's energy to a chosen Creature instead of your Magi?", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, REDIRECT_PENDING);
    if (chosenInstanceId === undefined) return;
    const amount = getCounter(self, PENDING_AMOUNT);
    if (amount <= 0) return;
    const target = findInPlayById(state, chosenInstanceId);
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!target || !magi) return;
    rearrangeEnergy(state, cardDb, magi, target, Math.min(amount, magi.currentEnergy ?? 0), rng);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(BONUS_PENDING)) return undefined;
    return {
      prompt: "Pruitt's Robe's Glimmer: add two energy to Pruitt?",
      yesLabel: 'Add 2 energy to Pruitt',
      noLabel: 'Not now',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean) => {
    removePermanentTag(self, BONUS_PENDING);
    if (!chosenBoolean) return;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi) return;
    addEnergy(state, cardDb, magi, 2, 'effect');
  },
});
