// Yaw -- "Ice Pack: Return Yaw to your hand. Choose a frozen Creature. Restore the chosen
// Creature to its starting energy."
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "own frozen Creature preferred,
// falling back to any" simplification with a real pending choice (registry.ts's
// pendingTargetChoice/resolveTargetChoice) over every frozen Creature in play, either side --
// Yaw itself is already back in hand by the time the choice resolves, so this is a Power-driven
// (not combat-driven) pending choice, resolved after resolvePower returns.

import { registerCardEffect } from './registry.js';
import { restoreEnergy, returnToHand } from '../effects.js';
import { allCreaturesInPlay, effectiveStartingEnergy } from '../targeting.js';
import { isFrozen } from '../durationTags.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const ICE_PACK_PENDING = 'yawIcePackPending';

function icePackPool(state: Parameters<typeof allCreaturesInPlay>[0], cardDb: Parameters<typeof allCreaturesInPlay>[1], selfInstanceId: string) {
  return allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== selfInstanceId && isFrozen(state, cardDb, c));
}

registerCardEffect('Yaw', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Ice Pack') return;
    const hasTarget = icePackPool(ctx.state, ctx.cardDb, ctx.source.instanceId).length > 0;
    returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId);
    if (hasTarget) addPendingChoiceTag(ctx.source, ICE_PACK_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(ICE_PACK_PENDING)) return undefined;
    const pool = icePackPool(state, cardDb, self.instanceId);
    if (pool.length === 0) return undefined;
    return { prompt: "Yaw's Ice Pack: choose a frozen Creature to restore to its starting energy", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, ICE_PACK_PENDING);
    if (!chosenInstanceId) return;
    const target = icePackPool(state, cardDb, self.instanceId).find((c) => c.instanceId === chosenInstanceId);
    if (target) restoreEnergy(state, cardDb, target, effectiveStartingEnergy(state, cardDb, target));
  },
});
