// River Abaquist -- Power "Possess: Discard River Abaquist from play. If your Magi is Orothe or
// Paradwyn, choose any one opposing Creature in play with less energy than the number of your
// Creatures or Relics in play, whichever is less. Gain control of the chosen Creature. The chosen
// Creature cannot attack this turn." Same gainControl + CANNOT_ATTACK shape as Agram's Possess,
// but a single target (no interdependent slots) gated on the controller's Magi's region.
//
// "Dreamwarp: As you play River Abaquist, increase or decrease its starting energy by up to one,
// until the end of the turn." is built too, via registry.ts's dreamwarpRange.

import type { CardDatabase } from '../types/card.js';
import type { GameState, PlayerId } from '../types/state.js';
import { registerCardEffect } from './registry.js';
import { opposingCreatures, creaturesControlledBy, allRelicsInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay, gainControl } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

function controlThreshold(state: GameState, cardDb: CardDatabase, playerId: PlayerId): number {
  const ownCreatureCount = creaturesControlledBy(state, cardDb, playerId).length;
  const ownRelicCount = allRelicsInPlay(state, cardDb).filter((r) => r.controllerId === playerId).length;
  return Math.min(ownCreatureCount, ownRelicCount);
}

registerCardEffect('River Abaquist', {
  powerTargets: (state, cardDb, playerId) => {
    const magi = state.players.get(playerId)?.activeMagi;
    const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
    if (!magiDef || !(magiDef.regions.includes('Orothe') || magiDef.regions.includes('Paradwyn'))) return [];
    const threshold = controlThreshold(state, cardDb, playerId);
    return opposingCreatures(state, cardDb, playerId).filter((c) => (c.currentEnergy ?? 0) < threshold);
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Possess') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    const threshold = controlThreshold(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if ((target.currentEnergy ?? 0) >= threshold) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);
  },
  dreamwarpRange: () => 1,
});
