// Glacier Hyren -- two printed pieces:
//   "Frostbite (2): Move one energy from each frozen Creature to Glacier Hyren." No "opposing"
//   qualifier -- either side's frozen Creatures, self included if it happens to be frozen (no
//   exclusion in the printed text).
//   "Magic Resistance: Players must pay two additional energy from their Magi to choose Glacier
//   Hyren for a Spell." Built (Spell-pass audit follow-up, 2026-07-23) via the same
//   chargesActingMagiForChoosing hook as Laranel's Cold Shoulder, now that play.ts's Spell-target
//   flow also consults it (previously Power-only, not because this hook is architecturally
//   Power-specific). Unlike Laranel ("opponents... for a Power"), this is unconditional on
//   PLAYER ("Players must pay") and SPELL-scoped only -- no `actingPlayerId === self.controllerId`
//   carve-out, and gated to `state.currentAction?.source === 'spell'`.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { rearrangeEnergy, discardEnergy } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Glacier Hyren', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Frostbite') return;

    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (creature.instanceId === ctx.source.instanceId) continue;
      if (!isFrozen(ctx.state, ctx.cardDb, creature)) continue;
      rearrangeEnergy(ctx.state, ctx.cardDb, creature, ctx.source, 1, ctx.rng);
    }
  },
  chargesActingMagiForChoosing: (state, cardDb, target, actingPlayerId, self) => {
    if (state.currentAction?.source !== 'spell') return false; // "for a Spell" only
    if (target.instanceId !== self.instanceId) return false;
    const actingMagi = state.players.get(actingPlayerId)?.activeMagi;
    if (!actingMagi) return false;
    discardEnergy(state, cardDb, actingMagi, 2, 'spell', actingPlayerId);
    return true;
  },
});
