// Moss Trulb -- "Multiply: If you control another Trulb, move one energy from each opposing Magi
// to Moss Trulb." No target choice -- automatic sweep once the "another Trulb" condition is met.
// Same name.includes() check Cloud Narth/Spray Narth already use for "a Pharan you control."

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingMagi } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Moss Trulb', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Multiply') return;
    const anotherTrulb = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).some(
      (c) => c.instanceId !== ctx.source.instanceId && ctx.cardDb.get(c.definitionKey)?.name.includes('Trulb')
    );
    if (!anotherTrulb) return;

    for (const magi of opposingMagi(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      rearrangeEnergy(ctx.state, ctx.cardDb, magi, ctx.source, 1, ctx.rng);
    }
  },
});
