// Radget -- "Refresh (1): Choose any one Creature in play. Add one energy to the chosen Creature.
// Add two additional energy if the chosen Creature is a Parmalag."
//
// Swirling Orshaa's Morph (Spell-pass audit follow-up, 2026-07-24) -- the target pool itself is
// unrestricted, but the bonus condition is a real "references a specific Creature type" check, so
// it's routed through matchesCreatureFamily() (checks a live Morph identityOverride first, falls
// back to the printed name substring) the same as the pool-restricting cards.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, matchesCreatureFamily } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Radget', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Refresh') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    const bonus = matchesCreatureFamily(ctx.cardDb, target, 'Parmalag') ? 2 : 0;
    addEnergy(ctx.state, ctx.cardDb, target, 1 + bonus, 'power');
  },
  specifiedCreatureTypes: () => ['Parmalag'],
});
