// Green Stuff -- "Effect - Ooze: When you play Green Stuff, add one energy to it." Printed with 0
// starting energy, so without this it would be defeated by the zero-energy check the instant it
// entered play -- the first real user of registry.ts's onPlay hook, built specifically to fire
// before that defeat check runs (see play.ts's playCard).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Green Stuff', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    addEnergy(state, cardDb, self, 1, 'effect');
  },
});
