// Garadan -- "Spawn: Whenever Garadan attacks a Magi, after energy is removed, you may
// immediately play any one Core or Naroom Creature from your hand with one energy instead of its
// starting energy and without paying any costs." afterCombat (fires after the zero-energy defeat
// check already ran, so this is correctly "after energy is removed") + effects.ts's playFromZone
// (the shared play-bypass primitive, skips region/cost/phase legality entirely, matches "without
// paying any costs") with a fixed startingEnergy of 1.
//
// Real choice (task #40-1, 2026-07-17, player-choice-default retrofit): replaces the earlier
// "first eligible Core/Naroom Creature in hand" auto-pick with a real pending choice
// (registry.ts's pendingTargetChoice/resolveTargetChoice) -- the pool is HAND cards, which the
// hook supports fine (see corathan.ts's own doc comment: "pendingTargetChoice's pool type is
// plain CardInstance either way," already proven with a discard-pile pool there).

import { registerCardEffect } from './registry.js';
import { playFromZone } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const SPAWN_PENDING = 'garadanSpawnPending';

function spawnPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.hand.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return def?.card_type === 'Creature' && (def.regions.includes('Core') || def.regions.includes('Naroom'));
  });
}

registerCardEffect('Garadan', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender !== null) return; // "attacks a Magi" -- a direct Magi attack only
    if (outcome.defenderInstanceId !== 'magi') return;
    if (spawnPool(ctx.state, ctx.cardDb, self).length === 0) return;
    addPendingChoiceTag(self, SPAWN_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SPAWN_PENDING)) return undefined;
    const pool = spawnPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Garadan's Spawn: choose a Core or Naroom Creature to play from hand with 1 energy", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, SPAWN_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    if (!spawnPool(state, cardDb, self).some((c) => c.instanceId === chosenInstanceId)) return;
    playFromZone(state, cardDb, { owner: player, zone: 'hand', instanceId: chosenInstanceId }, player, 1, rng);
  },
});
