// Warrada -- "Dark Blooming: At the beginning of your turn, if Warrada has no creatures in play,
// add five energy to Warrada." Constructed-banned (see legality), but built normally per the
// project owner's task #35 scope decision -- banlist affects legality, not implementation
// completeness.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';

registerCardEffect('Warrada', {
  onOwnTurnStart: (state, cardDb, self) => {
    if (creaturesControlledBy(state, cardDb, self.controllerId).length > 0) return;
    addEnergy(state, cardDb, self, 5, 'effect');
  },
});
