// Ven -- "Vitalize (4): Choose any one Creature in play. Restore the chosen Creature to its
// starting energy. This Power may add or discard energy."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveStartingEnergy } from '../targeting.js';
import { restoreEnergy } from '../effects.js';

registerCardEffect('Ven', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Vitalize') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    restoreEnergy(ctx.state, ctx.cardDb, target, effectiveStartingEnergy(ctx.state, ctx.cardDb, target));
  },
});
