// Curse of the Abaquist (Spell, Orothe/Paradwyn, cost 4) -- "Choose any one of your Orothe or
// Paradwyn Creatures in play. Until the end of the turn, the chosen Creature gains the text:
// 'Power -- Possess: Choose any one opposing Creature in play with less energy than this Creature.
// Discard this Creature from play. Gain control of the chosen Creature. That Creature cannot attack
// this turn.'" A made-up Power granted via copiedPowers.ts's addCopiedPower (the imbueSpell.ts/
// ergar.ts precedent for a Power with no real originating card) -- unlike Imbue Spell's PERMANENT
// grant, this one has a real printed duration (afterTurnNumber: state.turnNumber, i.e. gone at the
// start of the NEXT turn). `fromDefinitionKey` points at Curse of the Abaquist's OWN definitionKey,
// dispatching to this file's own powerTargets/resolvePower below (registered under the Spell's own
// name) since Possess isn't copied from any real card and needs its own logic. No printed cost for
// Possess (no numeric prefix in the printed text) -- treated as 0, same "212 real Powers have no
// cost" default this codebase already documents (types/card.ts's Power.cost doc comment).
// "Orothe Shadow Magi and Paradwyn Shadow Magi can play Curse of the Abaquist" needs no code --
// shadow_play is data-driven (regions.ts).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingCreatures, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay, gainControl } from '../effects.js';
import { addCopiedPower } from '../copiedPowers.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Curse of the Abaquist', {
  spellTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => {
      const regions = cardDb.get(c.definitionKey)?.regions ?? [];
      return regions.includes(regionForTargetFilter(state, 'Orothe')) || regions.includes(regionForTargetFilter(state, 'Paradwyn'));
    }),
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const target = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    if (!target) return;
    addCopiedPower(
      target,
      {
        name: 'Possess',
        cost: 0,
        text: 'Choose any one opposing Creature in play with less energy than this Creature. Discard this Creature from play. Gain control of the chosen Creature. That Creature cannot attack this turn.',
      },
      ctx.source.definitionKey,
      { afterTurnNumber: ctx.state.turnNumber }
    );
  },
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    if (powerName !== 'Possess') return undefined;
    const self = creaturesControlledBy(state, cardDb, playerId).find((c) => c.instanceId === sourceInstanceId);
    if (!self) return [];
    return opposingCreatures(state, cardDb, playerId).filter((c) => (c.currentEnergy ?? 0) < (self.currentEnergy ?? 0));
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Possess') return;
    if (!ctx.chosenTargetId) return;
    const opponentTarget = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    if (!opponentTarget) return;
    if ((opponentTarget.currentEnergy ?? 0) >= (ctx.source.currentEnergy ?? 0)) return;

    const owner = ctx.state.players.get(ctx.source.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, ctx.source.instanceId, undefined, 'power', ctx.rng);
    gainControl(ctx.state, ctx.cardDb, opponentTarget, ctx.controllingPlayer.playerId);
    addRestrictionTag(ctx.state, opponentTarget, CANNOT_ATTACK, ctx.state.turnNumber);
  },
});
