// Sinder, Apprentice -- top-level text: "Universal Spells cost Sinder, Apprentice one less energy
// to play, to a minimum of one." registry.ts's costModifier, self-scoped (her OWN controller's
// plays only).
//
// "Backlash: Once per turn, when Sinder, Apprentice is attacked, remove energy in the attack as
// though he were a Creature." (task #31, 2026-07-16) -- re-checked; this deferred comment called
// it "a genuinely distinct combat-math mechanism" before combat.ts actually grew a hook for it
// (appliesCounterDamageWhenAttacked). Built via that hook: once per turn (a duration tag on
// herself, checked-and-consumed here), the attacker ALSO takes the Creature-vs-Creature-style loss
// combat.ts's Magi-defense branch normally skips.

import { registerCardEffect } from './registry.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const BACKLASH_USED_THIS_TURN = 'sinderApprenticeBacklashUsedThisTurn';

registerCardEffect('Sinder, Apprentice', {
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return playedDef.card_type === 'Spell' && playedDef.regions.includes('Universal') ? -1 : 0;
  },
  appliesCounterDamageWhenAttacked: (state, cardDb, self) => {
    if (hasDurationTag(self, BACKLASH_USED_THIS_TURN)) return false;
    addDurationTag(state, cardDb, self, BACKLASH_USED_THIS_TURN, state.turnNumber);
    return true;
  },
});
