// Strag -- "Defense: Whenever one of your Creatures is attacked, add one energy to that Creature
// before energy is removed." Same shape as Pillar Hyren's Stabilize, real energy add ->
// onBeforeEnergyRemoved.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Strag', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    addEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect');
  },
});
