// Grapple Tooth -- "Climb: Your Magi loses no energy in attacks while you control at least one
// Creature. Grapple: If your largest Creature is larger than each opposing Creature, draw a
// card." Grapple: no target -- automatic comparison. Vacuously true (and draws) if the opponent
// controls no Creatures at all, per the literal "larger than each" reading. Climb (region-audit
// follow-up, 2026-07-24): registry.ts's new grantsMagiCombatLossImmunity -- full immunity, not a
// flat reduction, so it can't reuse grantsAttackLossReductionTo; conditional on Creature count, so
// it can't be a static duration tag either. See that hook's own doc comment for the combat.ts
// wiring.

import { registerCardEffect } from './registry.js';
import { largestCreatureControlledBy, opposingCreatures } from '../targeting.js';
import { drawCards } from '../effects.js';

registerCardEffect('Grapple Tooth', {
  grantsMagiCombatLossImmunity: (state, cardDb, self, magi) => {
    if (self.controllerId !== magi.controllerId) return false;
    const owner = state.players.get(self.controllerId);
    return !!owner && owner.inPlay.some((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature');
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Grapple') return;
    const largest = largestCreatureControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (!largest) return;
    const largestEnergy = largest.currentEnergy ?? 0;
    const opposing = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (opposing.every((c) => largestEnergy > (c.currentEnergy ?? 0))) {
      drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    }
  },
});
