// Elder Vellup -- "Allies: When you play Elder Vellup, you may search your deck for any one
// non-Vellup Arderial Creature. Reveal the Creature to all players and place it in your hand.
// Shuffle your deck."
//
// The "may" choice is still auto-taken whenever a legal target exists (out of scope for Phase
// 4c, which is specifically about WHICH target gets chosen -- same tradeoff as magamsRing.ts/
// skullek.ts). "Any one" is now a real pending choice (Phase 4c, 2026-07-11, registry.ts's
// pendingTargetChoice/resolveTargetChoice) instead of the earlier "first eligible in deck array
// order" simplification. "Reveal to all players" has no distinct game-state effect beyond moving
// the card to hand, so isn't separately modeled.

import { registerCardEffect } from './registry.js';
import { searchDeck } from '../effects.js';
import { creatureType } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import type { Rng } from '../rng.js';

const ALLIES_PENDING = 'elderVellupAlliesPending';

function alliesPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.deck.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return def?.card_type === 'Creature' && def.regions.includes('Arderial') && creatureType(cardDb, c.definitionKey) !== 'Vellup';
  });
}

registerCardEffect('Elder Vellup', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    if (alliesPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, ALLIES_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(ALLIES_PENDING)) return undefined;
    const pool = alliesPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Elder Vellup's Allies: choose a non-Vellup Arderial Creature in your deck to add to hand", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng?: Rng) => {
    removePermanentTag(self, ALLIES_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    if (alliesPool(state, cardDb, self).some((c) => c.instanceId === chosenInstanceId)) {
      searchDeck(state, player, [chosenInstanceId], rng);
    }
  },
});
