// Janx -- "Bicker: Whenever Janx attacks, discard two energy from each of the defending Magi's
// stalked Creatures after energy is removed."

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { hasDurationTag, STALKED } from '../durationTags.js';

registerCardEffect('Janx', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.defendingPlayer.playerId)) {
      if (hasDurationTag(creature, STALKED)) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 2, 'effect', undefined, ctx.rng);
      }
    }
  },
});
