// Tiller -- two Powers, both a hand-discard-for-draw cycle: "Exchange: Discard any one Creature
// card from your hand. Draw one card." / "Scrounge: Discard any one Relic card from your hand.
// Draw two cards." One shared handDiscardCost offering either type (registry.ts's field has no
// per-Power filter, so it can't narrow by which Power is active) -- each Power's resolvePower
// validates the discarded card's type strictly and rejects a mismatch.

import { registerCardEffect } from './registry.js';
import { drawCards, discardFromHand } from '../effects.js';

registerCardEffect('Tiller', {
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' || def?.card_type === 'Relic';
    },
  },
  resolvePower: (ctx) => {
    const id = (ctx.chosenHandCardIds ?? [])[0];
    if (!id) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
    const discardedType = discardedCard ? ctx.cardDb.get(discardedCard.definitionKey)?.card_type : undefined;

    if (ctx.powerName === 'Exchange') {
      if (discardedType !== 'Creature') return;
      discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [id], undefined, ctx.rng);
      drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    } else if (ctx.powerName === 'Scrounge') {
      if (discardedType !== 'Relic') return;
      discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [id], undefined, ctx.rng);
      drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 2);
    }
  },
});
