// Drig -- "Leech (3): Discard one energy from each opposing Creature, and add one energy to each
// of your Bograth Creatures in play." No target -- a two-direction sweep.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingCreatures, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Drig', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Leech') return;
    for (const creature of opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
    }
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      if (effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Bograth'))) {
        addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Bograth'],
});
