// Scarletsong Lahalou -- "Screech: Discard Scarletsong Lahalou from play. Add one energy to your
// Magi for each Scarletsong card you control." Self-discard first per text order, so the count
// (read after) doesn't include Scarletsong Lahalou itself.

import { registerCardEffect } from './registry.js';
import { inPlayControlledBy } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Scarletsong Lahalou', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Screech') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    if (!ctx.controllingPlayer.activeMagi) return;
    const count = inPlayControlledBy(ctx.state, ctx.controllingPlayer.playerId).filter((c) =>
      ctx.cardDb.get(c.definitionKey)?.name.includes('Scarletsong')
    ).length;
    if (count > 0) addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, count, 'power');
  },
});
