// Khisp -- "Hunt: Whenever Khisp attacks a stalked Creature, add two energy to Khisp before
// energy is removed." Same shape as K'ly's Hunt, just a different amount.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { hasDurationTag, STALKED } from '../durationTags.js';

registerCardEffect('Khisp', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (!ctx.defender || !hasDurationTag(ctx.defender, STALKED)) return;
    addEnergy(ctx.state, ctx.cardDb, self, 2, 'effect');
  },
});
