// Tillant -- "Cleansing Strike": "Whenever Tillant attacks a Core Creature, add five energy to
// Tillant before energy is removed."
//
// "Resistance: Core Spells and Powers do not affect Tillant." Built (Spell-pass audit follow-up,
// 2026-07-23) via blocksPowerEffectBySourceRegion -- same hook and shape as Chaos Flugg's own
// Resistance clause (no "opposing" qualifier in either printed text, so both sides' Core
// Spells/Powers are blocked, unlike Leaf Chogo's own opposing-only version of this same clause).
//
// Ashio's Weave Twist (2026-07-24): both "Core" references above are Tillant's OWN printed text,
// so under Ashio they mean Tillant's own region (Naroom) instead -- see targeting.ts's
// ashioAdjustedRegion doc comment for the general mechanism.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { ashioAdjustedRegion, effectiveRegions } from '../targeting.js';

registerCardEffect('Tillant', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Cleansing Strike is the attacker-vs-
  // Core-defender +5 bonus; Resistance blocks Core Spell/Power effects both directions
  // (no "opposing" qualifier -- see file header).
  effectHooks: {
    'Cleansing Strike': ['onBeforeEnergyRemoved'],
    Resistance: ['blocksPowerEffectBySourceRegion'],
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes(ashioAdjustedRegion(ctx.state, ctx.cardDb, 'Core', ['Naroom']))) return;
    addEnergy(ctx.state, ctx.cardDb, self, 5, 'effect');
  },
  blocksPowerEffectBySourceRegion: (state, cardDb) => {
    const sourceKey = state.currentAction?.sourceDefinitionKey;
    if (sourceKey === undefined) return false;
    const sourceDef = cardDb.get(sourceKey);
    return sourceDef?.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Naroom'])) ?? false;
  },
});
