// Lightning Braggle -- "Shock (3): Choose up to three opposing Creatures. Remove one energy from
// each of them." Single slot, single pool, "up to 3" (min 0, max 3) -- simplest possible use of
// powerTargetSlots, no dependency between slots since there's only one.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Lightning Braggle', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose up to three opposing Creatures',
      pool: (s, db, pid) => flexibleTargetPool(s, db, pid, opposingCreatures(s, db, pid), opposingMagi(s, db, pid)),
      min: 0,
      max: 3,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shock') return;
    const chosen = ctx.chosenSlotIds?.[0] ?? [];
    for (const id of chosen) {
      const target = findCreatureOrMagiById(ctx.state, id);
      if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) continue;
      if (target.controllerId === ctx.controllingPlayer.playerId) continue;
      discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
    }
  },
});
