// Habob -- both halves of Serve:
//   "At the end of your turn, if your Magi is d'Resh, you may move up to five energy from Habob to
//   your Magi." No target ambiguity (always moves to the Magi) -- out of scope for Phase 4c.
//   "When you reveal a d'Resh Magi, if you have one or more Recurring cards in your discard pile,
//   you may discard one energy from your Magi to choose one recurring card in your discard pile
//   and add it to your hand." This half is shared verbatim by every Recurring-subtype card
//   (Szhar, Uban, Venger too) -- extracted to recurringReveal.ts (task #39-1, 2026-07-17) so all
//   four register the identical mechanism instead of each re-deriving it.
//
// Real choice (retrofitted 2026-07-20, playtest bug report: "not a choice, fires automatically for
// full energy"): both "may" (the move is optional) AND "up to five" (a variable amount) are real
// player picks, now a pendingNumericChoice/resolveNumericChoice (registry.ts's generic post-hoc
// numeric family, min 0 doubling as "decline") instead of always auto-moving the max. Capped at
// Habob's own current energy (can't move more than it has, even though "up to five" is the printed
// ceiling).

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { effectiveRegions } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { recurringRevealHooks } from './recurringReveal.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING_SERVE_CHOICE = 'habobAwaitingServeChoice';

function eligibleAmount(state: GameState, cardDb: CardDatabase, self: CardInstance): number {
  const player = state.players.get(self.controllerId);
  if (!player?.activeMagi) return 0;
  if (!effectiveRegions(state, cardDb, player.activeMagi).includes("d'Resh")) return 0;
  return Math.min(5, self.currentEnergy ?? 0);
}

registerCardEffect('Habob', {
  ...recurringRevealHooks,
  onOwnTurnEnd: (state, cardDb, self) => {
    if (eligibleAmount(state, cardDb, self) > 0) addPendingChoiceTag(self, AWAITING_SERVE_CHOICE);
  },
  pendingNumericChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_SERVE_CHOICE)) return undefined;
    const max = eligibleAmount(state, cardDb, self);
    if (max <= 0) {
      removePermanentTag(self, AWAITING_SERVE_CHOICE);
      return undefined;
    }
    return {
      prompt: `Habob's Serve: choose how much energy (0-${max}) to move from Habob to your Magi`,
      min: 0,
      max,
    };
  },
  resolveNumericChoice: (state, cardDb, self, chosen, rng) => {
    if (!self.tags.has(AWAITING_SERVE_CHOICE)) return;
    removePermanentTag(self, AWAITING_SERVE_CHOICE);
    const player = state.players.get(self.controllerId);
    if (!player?.activeMagi) return;
    const max = eligibleAmount(state, cardDb, self);
    const amount = Math.max(0, Math.min(chosen, max));
    if (amount > 0) rearrangeEnergy(state, cardDb, self, player.activeMagi, amount, rng);
  },
});
