// Orwin's Staff -- "Preordinance: Discard Orwin's Staff from play and discard two cards from your
// hand. Search your deck for any one card. Place that card in your hand without showing it to
// your opponents." "Without showing" is cosmetic (knowledge-only, no state effect).

import { registerCardEffect } from './registry.js';
import { discardFromHand, discardFromPlay, searchDeck } from '../effects.js';

registerCardEffect("Orwin's Staff", {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  deckSearch: { count: 1 },
  handDiscardCost: { count: 2 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Preordinance') return;
    const handIds = ctx.chosenHandCardIds ?? [];
    if (handIds.length !== 2) return;
    if (!handIds.every((id) => ctx.controllingPlayer.hand.some((c) => c.instanceId === id))) return;
    const searchIds = ctx.chosenDeckSearchIds ?? [];
    if (searchIds.length > 1) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, handIds, undefined, ctx.rng);
    searchDeck(ctx.state, ctx.controllingPlayer, searchIds, ctx.rng);
  },
});
