// Karak Band -- "Acquisition: Once per turn, whenever you gain control of an opposing player's
// card, add two energy to your Magi." A pure passive Effect, no printed Power at all -- first user
// of registry.ts's onGainControl hook with no accompanying resolvePower. "An opposing player's
// card" is checked via ownerId (which never changes), not controllerId (which just changed to
// newControllerId by the time this fires) -- a card is "opposing" if its OWNER isn't the player
// who just gained it. "Once per turn" is an official 2i Design errata (data-pipeline/output/
// rulings.json, applied 2026-07-09) -- previously this fired every single control change, even
// multiple times in one turn -- tracked via a card-scoped duration tag, same pattern as Corathan's
// Betrayal (also errata'd to once-per-turn in the same pass).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const ACQUISITION_USED_THIS_TURN = 'karakBandAcquisitionUsedThisTurn';

registerCardEffect('Karak Band', {
  onGainControl: (state, cardDb, gained, newControllerId, self) => {
    if (self.controllerId !== newControllerId) return; // only "whenever YOU gain control"
    if (gained.ownerId === newControllerId) return; // must be "an opposing player's card"
    if (hasDurationTag(self, ACQUISITION_USED_THIS_TURN)) return;
    const magi = state.players.get(newControllerId)?.activeMagi;
    if (magi) {
      addEnergy(state, cardDb, magi, 2, 'effect');
      addDurationTag(state, cardDb, self, ACQUISITION_USED_THIS_TURN, state.turnNumber);
    }
  },
});
