// Hasseth -- "Banish: Discard one of your illusions from play and discard a random card from your
// hand to choose a Creature in play. Discard the chosen Creature." "Master Illusionist: Once per
// turn, when you play an illusion, draw a card."
//
// Master Illusionist built (task #39-1, 2026-07-17) -- corrected a stale note claiming this needed
// an "onPlayCreature" hook that didn't exist; the generic `onPlay` broadcast (used by
// Ergar/Salara/many others) already fires for every played card, so this is a direct filter on it.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';
import { discardFromPlay, discardRandomFromHand, drawCards } from '../effects.js';
import { isIllusion, addDurationTag, hasDurationTag } from '../durationTags.js';

const MASTER_ILLUSIONIST_USED_THIS_TURN = 'hassethMasterIllusionistUsedThisTurn';

registerCardEffect('Hasseth', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return; // "when YOU play an illusion"
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (!isIllusion(played)) return;
    if (hasDurationTag(self, MASTER_ILLUSIONIST_USED_THIS_TURN)) return;
    addDurationTag(state, cardDb, self, MASTER_ILLUSIONIST_USED_THIS_TURN, state.turnNumber);
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    drawCards(state, cardDb, owner, 1);
  },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Banish') return;
    if (ctx.chosenTargetId === undefined) return;
    const ownIllusion = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find((c) =>
      isIllusion(c)
    );
    if (!ownIllusion) return;
    if (ctx.controllingPlayer.hand.length === 0) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ownIllusion.instanceId, undefined, undefined, ctx.rng);
    discardRandomFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1, ctx.rng);

    // The chosen target could have BEEN the illusion just discarded -- re-fetch to confirm.
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
