// Void Stone -- both printed pieces:
//   "Supply": "Discard one of your Relics from play. Draw a card."
//   "Demand": "Each opposing non-Nar Relic costs one additional energy to play." registry.ts's
//   costModifier, already broadcast to every in-play card on both sides.

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay, drawCards } from '../effects.js';

registerCardEffect('Void Stone', {
  powerTargets: (state, cardDb, playerId) => allRelicsInPlay(state, cardDb).filter((r) => r.controllerId === playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Supply') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Relic') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId, undefined, undefined, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId === self.controllerId) return 0;
    if (playedDef.card_type !== 'Relic') return 0;
    return playedDef.regions.includes('Nar') ? 0 : 1;
  },
});
