// Spark Chogo -- "Fade Away: Discard Spark Chogo from play. Choose a Creature. Discard three
// energy from the chosen Creature." Self-discard + fixed removal, unrestricted target.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Spark Chogo', {
  // "Burnout: Whenever Spark Chogo attacks, it removes two additional energy from the opposing
  // Creature." BUILT 2026-07-28 (ability-count sweep) -- the file had only Fade Away. An INCREASE
  // to the attacker's output, so unlike a reduction it needs no `cardLocalCombatReductionBlocked`
  // gate (that helper exists for Garan/Rayje's Sword-style suppression of reductions).
  // "from the opposing Creature" scopes it to Creature-vs-Creature: no bonus attacking a Magi.
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return; // Magi attacks are not "the opposing Creature"
    ctx.locked.attackerEnergy += 2;
  },
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Fade Away') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    if (target.instanceId !== ctx.source.instanceId) {
      discardEnergy(ctx.state, ctx.cardDb, target, 3, undefined, undefined, ctx.rng);
    }
  },
});
