// Relic Stalker -- "Pound Pound Pound: Choose any one Relic in play. Discard Relic Stalker from
// play. Discard the chosen Relic from play." ("from player" in the source text is a typo for
// "from play".)

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Relic Stalker', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb) => allRelicsInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Pound Pound Pound') return;
    if (ctx.chosenTargetId === undefined) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    // The chosen Relic could have BEEN Relic Stalker itself -- already gone from play now.
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Relic') return;
    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
