// Silth Giant -- "Swallow Whole: Once per turn, instead of attacking, whenever one of your other
// Creatures attacks a Creature with less energy than Silth Giant, you may discard the defending
// Creature from play before energy is removed. Your attacking Creature is still considered to
// have attacked this turn." The last sentence needs no code -- combat.ts already marks the
// attacker as having attacked before any hook runs, regardless of what happens to the defender.
//
// Real choice (task #40-3, 2026-07-17, player-choice-default retrofit, Group 3): "may" is now a
// real yes/no via `pendingPreCombatTargetChoice`, single-candidate pool (the defending Creature --
// the only possible target). Third-party reactor -- Silth Giant doesn't need to be part of the
// combat itself. No resolution supplied falls back to the old always-take default.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import type { PreCombatTargetResolution } from '../combat.js';

const USED_THIS_TURN = 'silthGiantUsedThisTurn';

registerCardEffect('Silth Giant', {
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker, isDefender, attacker, defender) => {
    if (attacker.instanceId === self.instanceId) return undefined; // "one of your OTHER Creatures"
    if (attacker.controllerId !== self.controllerId) return undefined;
    if (!defender) return undefined;
    if ((defender.currentEnergy ?? 0) >= (self.currentEnergy ?? 0)) return undefined;
    if (hasDurationTag(self, USED_THIS_TURN)) return undefined;
    return { prompt: "Silth Giant's Swallow Whole: discard the defending Creature from play?", pool: [defender] };
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId === self.instanceId) return; // "one of your OTHER Creatures"
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (!ctx.defender) return;
    if ((ctx.defender.currentEnergy ?? 0) >= (self.currentEnergy ?? 0)) return;
    if (hasDurationTag(self, USED_THIS_TURN)) return;
    const owner = ctx.state.players.get(ctx.defender.controllerId);
    if (!owner) return;

    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
    const resolution = resolutions?.[self.instanceId];
    const takeIt = resolution !== undefined ? !('skip' in resolution) : true; // unchanged auto-take default
    if (!takeIt) return;

    addDurationTag(ctx.state, ctx.cardDb, self, USED_THIS_TURN, ctx.state.turnNumber);
    discardFromPlay(ctx.state, ctx.cardDb, owner, ctx.defender.instanceId, undefined, undefined, ctx.rng);
  },
});
