// Geoh -- "Excavate (3): Reveal the top three cards of your deck. You may choose up to one
// Creature, up to one Relic, and up to one Spell from the revealed cards and place them into your
// hand. Place any remaining cards into your discard pile." Unlike Orothean Goggles/d'Rasha/Chelon
// (where unchosen cards are just left on top), Geoh's text explicitly discards whatever ISN'T
// chosen -- so this snapshots the top 3 BEFORE moving anything, then routes chosen ids to hand and
// every other originally-revealed id to the discard pile.

import { registerCardEffect } from './registry.js';
import { removeFromZone, moveToDiscardPile } from '../zones.js';

registerCardEffect('Geoh', {
  deckTopReveal: { count: 3 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Excavate') return;
    const player = ctx.controllingPlayer;
    const top = player.deck.slice(0, 3);
    const topIds = top.map((c) => c.instanceId);
    const chosenIds = (ctx.chosenDeckTopIds ?? []).filter((id) => topIds.includes(id));

    const byType = new Map<string, number>();
    for (const id of chosenIds) {
      const card = top.find((c) => c.instanceId === id)!;
      const type = ctx.cardDb.get(card.definitionKey)?.card_type ?? '';
      const count = byType.get(type) ?? 0;
      if ((type === 'Creature' || type === 'Relic' || type === 'Spell') && count >= 1) return; // more than one of a type chosen -- illegal, fizzle
      byType.set(type, count + 1);
    }

    for (const id of topIds) {
      const card = removeFromZone(player, 'deck', id);
      if (chosenIds.includes(id)) {
        player.hand.push(card);
      } else {
        moveToDiscardPile(ctx.state, player, card);
      }
    }
  },
});
