// Ababila -- "Thief: When you play Ababila, choose one opponent's deck. Reveal the top card of
// the chosen deck and place it under Ababila. When Ababila is discarded, discard all cards under
// it." "Stop!: Ababila loses two less energy in attacks against Creatures of the same region as
// the card under Ababila." Two-player engine, so "choose one opponent's deck" has only one legal
// choice -- no real decision to prompt for.

import { registerCardEffect } from './registry.js';
import { attachCard, discardAllAttached } from '../attachedCards.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Ababila', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Thief owns the attach/discard cycle
  // and its `holdsInertContents` housekeeping flag (Q4: data fields travel with grants);
  // Stop! is the combat-loss reduction against same-region defenders.
  effectHooks: {
    Thief: ['onPlay', 'onCardDiscardedFromPlay', 'holdsInertContents'],
    'Stop!': ['onAttack'],
  },
  // Cards stored under this one are OUT of play, not markers riding on it -- see
  // registry.ts's `holdsInertContents`. Without this, every board-wide broadcast that
  // flattens `attachedCards` (to reach the marker family) also fires the abilities of
  // whatever is sitting inertly in here.
  holdsInertContents: true,
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    const opponent = [...state.players.values()].find((p) => p.playerId !== self.controllerId);
    const revealed = opponent?.deck.shift();
    if (!revealed) return;
    attachCard(self, revealed);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;
    discardAllAttached(state, cardDb, self);
  },
  onAttack: (ctx, self) => {
    const attached = self.attachedCards[0];
    if (!attached) return;
    const attachedDef = ctx.cardDb.get(attached.definitionKey);
    if (!attachedDef) return;
    const opponent = ctx.attacker.instanceId === self.instanceId ? ctx.defender : ctx.attacker;
    if (!opponent) return;
    const opponentDef = ctx.cardDb.get(opponent.definitionKey);
    if (!opponentDef) return;
    const sameRegion = opponentDef.regions.some((r) => attachedDef.regions.includes(r));
    if (sameRegion) applyInvulnerability(ctx, self, 2);
  },
});
