// Abaquist -- "Possess: Choose any one Creature in play with less energy than Abaquist. Discard
// Abaquist from play. Gain control of the chosen Creature. That Creature may not attack this
// turn." The filter needs Abaquist's own CURRENT energy, read via the sourceInstanceId param
// powerTargets already receives (same "look up your own instance to read a live value" pattern
// used wherever a card's filter depends on its own current state, not just static card data).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay, gainControl } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Abaquist', {
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    const self = findInPlayById(state, sourceInstanceId);
    const ownEnergy = self?.currentEnergy ?? 0;
    return allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== sourceInstanceId && (c.currentEnergy ?? 0) < ownEnergy);
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Possess') return;
    if (ctx.chosenTargetId === undefined) return;
    const ownEnergy = ctx.source.currentEnergy ?? 0;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target || target.instanceId === ctx.source.instanceId || (target.currentEnergy ?? 0) >= ownEnergy) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);
  },
});
