// Sphor -- "Scavenge: Each time a Creature you control is discarded from play, add one energy to
// Sphor."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Sphor', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discardedOwnerId !== self.controllerId) return;
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Creature') return;

    addEnergy(state, cardDb, self, 1, 'effect');
  },
});
