// Weave Maul -- "Crush (2): Remove one energy from each Creature without the Effect 'Weave'."
// "Weave" here is a NAMED EFFECT some cards carry (checked via CardDefinition.effects), not the
// Weave region -- confirmed against the real database (58 cards have an effect literally named
// "Weave", separate from the ~region of the same name).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Weave Maul', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Crush') return;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      const hasWeaveEffect = ctx.cardDb.get(creature.definitionKey)?.effects.some((e) => e.name === 'Weave') ?? false;
      if (!hasWeaveEffect) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
      }
    }
  },
});
