// Evu -- "Lore: At the end of each of your turns, draw a card."

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Evu', {
  onOwnTurnEnd: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    drawCards(state, cardDb, player, 1);
  },
});
