// Collosit / Colossit -- two distinct card names sharing identical text: "Spare Parts: Your
// Collosus and Construct cards cost one less to play, to a minimum of one." costModifier,
// type-family matched via word-boundary regex against the played card's name (same robust
// approach used for the Furok/Bagala/Xyx/Bisiwog families).

import { registerCardEffect } from './registry.js';

const COLLOSUS_OR_CONSTRUCT = /\b(Collosus|Construct)\b/;

registerCardEffect('Collosit', {
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return COLLOSUS_OR_CONSTRUCT.test(playedDef.name) ? -1 : 0;
  },
});

registerCardEffect('Colossit', {
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return COLLOSUS_OR_CONSTRUCT.test(playedDef.name) ? -1 : 0;
  },
});
