// Darge -- all three printed effects are built here:
//   "Pummel: Whenever Darge attacks a Core Creature, Darge loses no energy in the attack."
//   "Invulnerability: Darge loses one less energy in attacks." (self-agnostic -- applies whenever
//   Darge is attacker or defender, reducing whichever locked value determines ITS OWN loss)
//   "Resistance: Core Spells and Powers do not affect Darge." Region-audit follow-up, 2026-07-24
//   -- direct reuse of registry.ts's blocksPowerEffectBySourceRegion, identical to Magor's own
//   "Resistance: Core Spells and Powers do not affect Magor" (byte-identical printed text).
// Pummel's full-zero takes priority over Invulnerability's -1 when both would apply (attacking a
// Core Creature).
//
// Ashio's Weave Twist (2026-07-24): both "Core" references above are Darge's OWN printed text, so
// under Ashio they mean Darge's own region (Kybar's Teeth) instead -- see targeting.ts's
// ashioAdjustedRegion doc comment for the general mechanism.

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { ashioAdjustedRegion, effectiveRegions } from '../targeting.js';

registerCardEffect('Darge', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Resistance owns
  // blocksPowerEffectBySourceRegion; Pummel and Invulnerability both live in the single onAttack
  // body (field-level narrowing can't split them). A Taglat copy of either exposes onAttack.
  effectHooks: {
    Resistance: ['blocksPowerEffectBySourceRegion'],
    Pummel: ['onAttack'],
    Invulnerability: ['onAttack'],
  },
  blocksPowerEffectBySourceRegion: (state, cardDb) => {
    const sourceKey = state.currentAction?.sourceDefinitionKey;
    if (sourceKey === undefined) return false;
    const sourceDef = cardDb.get(sourceKey);
    return sourceDef?.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ["Kybar's Teeth"])) ?? false;
  },
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId === self.instanceId) {
      if (ctx.defender && effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes(ashioAdjustedRegion(ctx.state, ctx.cardDb, 'Core', ["Kybar's Teeth"]))) {
        if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = 0; // Pummel
      } else {
        if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = Math.max(0, ctx.locked.defenderEnergy - 1); // Invulnerability
      }
    } else if (ctx.defender?.instanceId === self.instanceId) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.max(0, ctx.locked.attackerEnergy - 1); // Invulnerability
    }
  },
});
