// Forest Blessing (Spell, cost 5) -- "Restore each Naroom Creature in play with less than its
// starting energy to its starting energy." Naroom Spell pass, Category A (2026-07-23). Same
// printedStartingEnergy/restoreEnergy pair as sapOfLife.ts's single-target version, broadcast to
// every Naroom Creature instead of one chosen target -- no player choice at all.

import { registerCardEffect } from './registry.js';
import { restoreEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions, effectiveStartingEnergy } from '../targeting.js';

registerCardEffect('Forest Blessing', {
  resolveSpell: (ctx) => {
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes('Naroom')) continue;
      const starting = effectiveStartingEnergy(ctx.state, ctx.cardDb, creature);
      if ((creature.currentEnergy ?? 0) < starting) restoreEnergy(ctx.state, ctx.cardDb, creature, starting);
    }
  },
});
