// Pajick Pet -- both printed effects:
//   "Guard: Whenever one of your other Creatures is attacked, add one energy to your Magi." (a
//   third-party reactor -- Pajick Pet doesn't need to be the defender itself)
//   "Weave: Whenever Pajick Pet is in an attack, before energy is removed, you may move one
//   energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { applyWeave } from './weave.js';

registerCardEffect('Pajick Pet', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Guard and Weave share the same
  // `onBeforeEnergyRemoved` body -- narrowing at field granularity can't split them, so a
  // Taglat copy of either Effect still runs the fused hook. Weave additionally carries `weaveConfig`.
  effectHooks: {
    Guard: ['onBeforeEnergyRemoved'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (
      ctx.defender &&
      ctx.defender.instanceId !== self.instanceId &&
      ctx.defender.controllerId === self.controllerId
    ) {
      const magi = ctx.state.players.get(self.controllerId)?.activeMagi;
      if (magi) addEnergy(ctx.state, ctx.cardDb, magi, 1, 'effect');
    }
    applyWeave(ctx, self, ['Weave']);
  },
});
