// Voice of the Storm -- "Diplomacy: When you play a Creature, if it is Arderial and you have an
// Orothe Creature in play, reduce the played Creature's cost by one. Or, if the Creature played
// is Orothe and you have an Arderial Creature in play, reduce the played Creature's cost by one.
// Diplomacy may not reduce a Creature's cost to less than one, and may not reduce its cost by
// more than one." Own controller's plays only. The "not below 1" clause is already the generic
// costModifier floor rule; "not by more than one" is naturally satisfied since only one of the
// two symmetric conditions can apply to a single played Creature (it's either Arderial or
// Orothe, not both, for the purposes of this specific -1).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';

registerCardEffect('Voice of the Storm', {
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    if (playedDef.card_type !== 'Creature') return 0;
    const ownCreatures = creaturesControlledBy(state, cardDb, playerId);
    const hasOrothe = ownCreatures.some((c) => effectiveRegions(state, cardDb, c).includes('Orothe'));
    const hasArderial = ownCreatures.some((c) => effectiveRegions(state, cardDb, c).includes('Arderial'));
    if (playedDef.regions.includes('Arderial') && hasOrothe) return -1;
    if (playedDef.regions.includes('Orothe') && hasArderial) return -1;
    return 0;
  },
});
