// Polar Eebit -- "If Polar Eebit is Frozen, it only loses one energy when attacked." Caps the
// locked attacker energy at 1 rather than reducing it by a flat amount, same shape as Mydra's
// Watchful.

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Polar Eebit', {
  // Ordering declaration only -- see registry.ts. This card CAPS combat loss, so it resolves
  // after every flat reduction (owner ruling 2026-07-27).
  appliesCombatLossCap: true,
  onAttack: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    if (!isFrozen(ctx.state, ctx.cardDb, self)) return;
    if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.min(ctx.locked.attackerEnergy, 1);
  },
});
