// Treepsh -- two printed clauses:
//   "Supply: Discard Treepsh from play. Draw a card. If you have more Creatures in play than any
//   one opponent of your choice, draw an additional card." Creature counts are read AFTER the
//   self-discard, per the text's own sentence order (Treepsh no longer counts toward its own side
//   by the time the comparison happens). 2-player only, so "any one opponent" is unambiguous.
//   "Watchful: Whenever an opposing Spell, Power, or Effect discards energy from one or more of
//   your Creatures in play, you may discard Treepsh from play. If you do, the Spell, Power, or
//   Effect does nothing." Built (Bograth-reference-cluster follow-up, 2026-07-20) on the same
//   react-and-negate window / offersPowerNegation+offersSpellNegation architecture as Moob Ring's
//   Martyr (see that file's own header comment for the full "why a real negation prompt, not an
//   auto-apply" reasoning, the single-target/`chosenTargetId`-only scope narrowing, and why the
//   "Effect" third of "Spell, Power, or Effect" stays out of reach). Simpler than Moob Ring in one
//   respect: no sacrifice-pool sub-choice -- Treepsh always discards itself, so eligibility is just
//   "does this Power/Spell target one of my Creatures," no separate "is there anything left to
//   sacrifice" check needed.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { discardFromPlay, drawCards } from '../effects.js';
import { getOpponents } from '../types/state.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

function targetsOwnCreature(state: GameState, cardDb: CardDatabase, self: CardInstance, currentTargetId?: string): boolean {
  if (!currentTargetId) return false;
  const owner = state.players.get(self.controllerId);
  const target = owner?.inPlay.find((c) => c.instanceId === currentTargetId);
  return !!target && cardDb.get(target.definitionKey)?.card_type === 'Creature';
}

// Explicit in-play zone check (task #44 follow-up precedent, Bronn's Battle Staff / same as Moob
// Ring's own file) -- previewPowerNegationOffers also scans the opponent's HAND, so a copy sitting
// in hand must explicitly opt out.
function isInPlay(state: GameState, self: CardInstance): boolean {
  return !!state.players.get(self.controllerId)?.inPlay.some((c) => c.instanceId === self.instanceId);
}

registerCardEffect('Treepsh', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Supply') return;
    const opponent = getOpponents(ctx.state, ctx.controllingPlayer.playerId)[0];

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);

    const ownCount = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).length;
    const oppCount = opponent ? creaturesControlledBy(ctx.state, ctx.cardDb, opponent.playerId).length : 0;
    if (ownCount > oppCount) drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
  },
  offersPowerNegation: (state, cardDb, self, user, powerName, currentTargetId) => {
    if (user.controllerId === self.controllerId) return false; // "an OPPOSING Spell, Power, or Effect"
    if (!isInPlay(state, self)) return false;
    return targetsOwnCreature(state, cardDb, self, currentTargetId);
  },
  resolvePowerNegation: (state, cardDb, self, negatedSource, negatedPowerName, currentTargetId, rng) => {
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
  },
  offersSpellNegation: (state, cardDb, self, playedDef, playerId, currentTargetId) => {
    if (playerId === self.controllerId) return false; // "an OPPOSING Spell"
    if (!isInPlay(state, self)) return false;
    return targetsOwnCreature(state, cardDb, self, currentTargetId);
  },
  resolveSpellNegation: (state, cardDb, self, negatedSpell, currentTargetId, rng) => {
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
  },
});
