// Jip -- "Tap Strength: Once per turn, whenever one or more opposing Creatures gains any amount of
// energy, you may add energy to Jip equal to the total energy gained by the opposing Creatures."
// Built task #45, 2026-07-18, the Naroom region pass -- registry.ts's new
// onPowerAddedEnergyToCreatures per-Creature broadcast, summing the gains on Creatures OPPOSING
// Jip's controller (Spells never execute, so only Power-caused gains fire). Once-per-turn gate via
// a turn-reset tag (onOwnTurnStart). Auto-taken (the "you may" is always beneficial -- gaining
// energy is never a downside), same simplification as every other "may gain energy" reader.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const USED_THIS_TURN = 'jipTapStrengthUsedThisTurn';

registerCardEffect('Jip', {
  onOwnTurnStart: (state, cardDb, self) => {
    removePermanentTag(self, USED_THIS_TURN);
  },
  onPowerAddedEnergyToCreatures: (state, cardDb, self, sourceCard, gains) => {
    if (self.tags.has(USED_THIS_TURN)) return;
    const opposingTotal = gains
      .filter((g) => g.instance.controllerId !== self.controllerId)
      .reduce((sum, g) => sum + g.amount, 0);
    if (opposingTotal <= 0) return;
    addPermanentTag(state, cardDb, self, USED_THIS_TURN);
    addEnergy(state, cardDb, self, opposingTotal, 'effect');
  },
});
