// Sludge Hyren -- "Creeping Growth: After Sludge Hyren attacks, add one energy to it for each
// Bograth Creature you control." Includes Sludge Hyren itself (a Bograth Creature) in the count.
//
// Bograth-count-helper sweep (Bograth-cluster follow-up, 2026-07-21): now reads
// targeting.ts's effectiveBograthCreatureCount instead of a raw board count, so Bog Stench's
// virtual +2 and Emlob's +3 (neither previously applied here) count toward the energy amount.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { effectiveBograthCreatureCount } from '../targeting.js';

registerCardEffect('Sludge Hyren', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    const count = effectiveBograthCreatureCount(ctx.state, ctx.cardDb, self.controllerId);
    if (count > 0) addEnergy(ctx.state, ctx.cardDb, self, count, 'effect');
  },
});
