// Bungaloo -- both printed effects:
//   "Flee: Whenever Bungaloo is defeated in an attack, choose any one Creature or Magi in play.
//   Add two energy to the chosen Creature or Magi."
//   "Weave: Whenever Bungaloo attacks or is attacked, before energy is removed, you may move one
//   energy between it and one of your other Weave or Naroom Creatures in play." (see weave.ts)
//
// Real choice (Phase 4c, 2026-07-11): Flee replaces the earlier "first eligible in array order"
// simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice). Bungaloo is defeated by the time this needs resolving, so self is already
// in the discard pile -- findPendingTargetChoices scans discard piles for exactly this reason.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay, allMagiInPlay } from '../targeting.js';
import { applyWeave } from './weave.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const FLEE_PENDING = 'bungalooFleePending';

function fleePool(state: Parameters<typeof allCreaturesInPlay>[0], cardDb: Parameters<typeof allCreaturesInPlay>[1]) {
  return [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)];
}

registerCardEffect('Bungaloo', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Weave owns the standard data field
  // + combat hook; Flee owns the afterCombat-triggered target choice fired on either combat role
  // (see file header for the task #49 both-roles fix).
  effectHooks: {
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
    Flee: ['afterCombat', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  weaveConfig: { eligibleRegions: ['Weave', 'Naroom'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave', 'Naroom']),
  afterCombat: (ctx, outcome, self) => {
    // "defeated in an attack" = EITHER combat role (task #49 playtest fix, 2026-07-19: Flee was
    // firing only when Bungaloo was defeated while defending, not while attacking).
    const defeatedAsDefender = ctx.defender?.instanceId === self.instanceId && !outcome.defenderSurvived;
    const defeatedAsAttacker = ctx.attacker.instanceId === self.instanceId && !outcome.attackerSurvived;
    if (!defeatedAsDefender && !defeatedAsAttacker) return;
    if (fleePool(ctx.state, ctx.cardDb).length === 0) return;
    addPendingChoiceTag(self, FLEE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(FLEE_PENDING)) return undefined;
    const pool = fleePool(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Bungaloo's Flee: choose a Creature or Magi to add 2 energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, FLEE_PENDING);
    if (!chosenInstanceId) return;
    const target = fleePool(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) addEnergy(state, cardDb, target, 2, 'effect');
  },
});
