// Thunder Vashp -- "Thunderclap: Choose any one Creature in play with three or less energy.
// Discard Thunder Vashp from play. Discard the chosen Creature from play." Self-sacrifice plus a
// second discard. Guards against double-discarding if the chosen target happens to be Thunder
// Vashp itself (a legal, if pointless, choice under a literal reading of the text).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { getPlayer } from '../types/state.js';

registerCardEffect('Thunder Vashp', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => (c.currentEnergy ?? 0) <= 3),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Thunderclap') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if ((target.currentEnergy ?? 0) > 3) return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    if (target.instanceId !== ctx.source.instanceId) {
      discardFromPlay(ctx.state, ctx.cardDb, getPlayer(ctx.state, target.controllerId), target.instanceId, undefined, undefined, ctx.rng);
    }
  },
});
