// Jungle Eebit -- "Defender: If Jungle Eebit would be defeated in an attack, move up to two energy
// from your Magi to Jungle Eebit, after energy is removed, instead of discarding it from play."
// Combines Motash's Escape (afterCombat, self already in the discard pile by this point) with
// Magam's Ring's Rebirth (playFromZone pulls it back out of the discard pile into play, here with
// energy MOVED from the Magi rather than restored to printed starting energy).
//
// Real choice (playtest audit fix, 2026-08-11): "up to two" is 0/1/2, player's pick -- previously
// always moved the max available, with no way to opt into less (or zero, even with energy to
// spare). Same pendingNumericChoice/resolveNumericChoice family Gherish's Drift/Habob's Serve
// already use for an identical "move up to N energy" clause. The revival itself (playFromZone) is
// UNCONDITIONAL -- "instead of discarding it from play" doesn't depend on any energy actually
// moving -- so when the Magi has none to spare there's no real choice to offer; afterCombat revives
// immediately with 0, same as the old auto-pick produced in that case. Only a real choice (Magi has
// 1+ energy) is deferred to the numeric-choice family.

import { registerCardEffect } from './registry.js';
import { discardEnergy, playFromZone } from '../effects.js';
import { addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const AWAITING_CHOICE = 'jungleEebitAwaitingChoice';

registerCardEffect('Jungle Eebit', {
  afterCombat: (ctx, outcome, self) => {
    // "defeated in an attack" = EITHER combat role (task #49 playtest fix, 2026-07-19: was firing
    // only when Jungle Eebit was defeated while defending, not while attacking).
    const defeatedAsDefender = ctx.defender?.instanceId === self.instanceId && !outcome.defenderSurvived;
    const defeatedAsAttacker = ctx.attacker.instanceId === self.instanceId && !outcome.attackerSurvived;
    if (!defeatedAsDefender && !defeatedAsAttacker) return;
    const player = defeatedAsAttacker ? ctx.attackingPlayer : ctx.defendingPlayer;
    const magi = player.activeMagi;
    if (!magi) return;
    const max = Math.min(2, magi.currentEnergy ?? 0);
    if (max <= 0) {
      playFromZone(ctx.state, ctx.cardDb, { owner: player, zone: 'discardPile', instanceId: self.instanceId }, player, 0, ctx.rng);
      return;
    }
    addPendingChoiceTag(self, AWAITING_CHOICE);
  },
  pendingNumericChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const player = state.players.get(self.controllerId);
    const magi = player?.activeMagi;
    if (!magi) {
      removePermanentTag(self, AWAITING_CHOICE);
      return undefined;
    }
    const max = Math.min(2, magi.currentEnergy ?? 0);
    return {
      prompt: `Jungle Eebit: choose how much energy (0-${max}) to move from your Magi to Jungle Eebit`,
      min: 0,
      max,
    };
  },
  resolveNumericChoice: (state, cardDb, self, chosen, rng) => {
    if (!self.tags.has(AWAITING_CHOICE)) return;
    removePermanentTag(self, AWAITING_CHOICE);
    const player = state.players.get(self.controllerId);
    const magi = player?.activeMagi;
    if (!player) return;
    const amount = magi ? Math.max(0, Math.min(chosen, 2, magi.currentEnergy ?? 0)) : 0;
    if (amount > 0 && magi) discardEnergy(state, cardDb, magi, amount, 'effect', self.controllerId, rng);
    playFromZone(state, cardDb, { owner: player, zone: 'discardPile', instanceId: self.instanceId }, player, amount, rng);
  },
});
