// Orlon's Ring -- "Purity: At the end of your turn, if all Spells in your discard pile are
// Orothe, discard all of your non-Orothe cards from play and add one energy to your Magi for each
// Orothe Relic you have in play."
//
// CORRECTED 2026-07-21 (same bug class as Kalius' Ring/purityRing.ts, playtest bug report): used
// to check a Relic's STATIC printed region off the card database directly instead of
// `effectiveRegions`. No known card currently overrides a Relic's region at runtime (the
// gain-control cluster's `effectiveRegionOverride` is only ever set on Creatures), so this was
// latent rather than observed -- fixed for consistency with the other two confirmed sites.

import { registerCardEffect } from './registry.js';
import { applyPurity } from './purityRing.js';
import { addEnergy } from '../effects.js';
import { allRelicsInPlay, effectiveRegions } from '../targeting.js';

registerCardEffect("Orlon's Ring", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, 'Orothe', rng)) return;
    const player = state.players.get(self.controllerId);
    if (!player?.activeMagi) return;
    const orotheRelicCount = allRelicsInPlay(state, cardDb).filter(
      (r) => r.controllerId === self.controllerId && effectiveRegions(state, cardDb, r).includes('Orothe')
    ).length;
    if (orotheRelicCount === 0) return;
    addEnergy(state, cardDb, player.activeMagi, orotheRelicCount, 'effect');
  },
});
