// Bottled City -- "Capture (Power): If there are no cards on Bottled City, choose a deck. Reveal
// cards from the top of the chosen deck until you reveal a Creature. Place that Creature on
// Bottled City. Shuffle the other revealed cards into their deck." "Release (Effect): You may
// play the Creature on Bottled City as if it were in your hand. Reduce the card's cost by three
// and ignore regional restrictions. Discard Bottled City after playing a Creature in this manner."
//
// "Choose a deck" uses the same Magi-proxy pattern as deckTopReveal's `whoseDeck: 'target'` cards
// (registry.ts) -- powerTargets offers both players' activeMagi, standing in for "that player's
// deck." Release is described only in `effects[]`, not `powers[]` -- syntheticPowers, same as
// Gia's Tome's Research; both Powers share this one registration (registerCardEffect can only be
// called once per card name), dispatched by ctx.powerName same as any multi-Power card. No
// explicit floor on the reduced cost is printed (unlike Gia's Tome's stated "to a minimum of
// one"), so it's allowed to floor at 0 (a free play) rather than inventing an unstated minimum.

import { registerCardEffect } from './registry.js';
import { attachCard, discardAllAttached } from '../attachedCards.js';
import { checkCreatureDefeats } from '../energy.js';
import { addToZone, moveToDiscardPile, shuffleDeck } from '../zones.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { resolveDreamwarpDelta, commitDreamwarpDelta } from '../effects.js';
import type { CardInstance } from '../types/instance.js';

registerCardEffect('Bottled City', {
  // Cards stored under this one are OUT of play, not markers riding on it -- see
  // registry.ts's `holdsInertContents`. Without this, every board-wide broadcast that
  // flattens `attachedCards` (to reach the marker family) also fires the abilities of
  // whatever is sitting inertly in here.
  holdsInertContents: true,
  syntheticPowers: [
    {
      name: 'Release',
      cost: undefined,
      text:
        'You may play the Creature on Bottled City as if it were in your hand. Reduce the ' +
        "card's cost by three and ignore regional restrictions. Discard Bottled City after " +
        'playing a Creature in this manner.',
    },
  ],
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    if (powerName !== 'Capture') return undefined;
    const player = state.players.get(playerId);
    const self = player?.inPlay.find((c) => c.instanceId === sourceInstanceId);
    if (self && self.attachedCards.length > 0) return []; // "if there are no cards on Bottled City"
    return [...state.players.values()].map((p) => p.activeMagi).filter((m): m is NonNullable<typeof m> => m !== null);
  },
  // Task #577: Release has no target of its own -- the captured Creature is simply whatever is
  // sitting on Bottled City -- so this ignores chosenTargetId and reports that one card.
  powerPlaysCreatureAsIfFromHand: (state, cardDb, playerId, self, powerName) => {
    if (powerName !== 'Release') return undefined;
    const captured = self.attachedCards[0];
    return captured && cardDb.get(captured.definitionKey)?.card_type === 'Creature' ? captured : undefined;
  },
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Capture') {
      if (ctx.source.attachedCards.length > 0) return;
      if (!ctx.chosenTargetId) return;
      const chosenPlayer = [...ctx.state.players.values()].find((p) => p.activeMagi?.instanceId === ctx.chosenTargetId);
      if (!chosenPlayer) return;

      const revealed: CardInstance[] = [];
      let captured: CardInstance | undefined;
      while (chosenPlayer.deck.length > 0) {
        const card = chosenPlayer.deck.shift()!;
        revealed.push(card);
        if (ctx.cardDb.get(card.definitionKey)?.card_type === 'Creature') {
          captured = card;
          break;
        }
      }
      if (!captured) {
        chosenPlayer.deck.push(...revealed);
        shuffleDeck(chosenPlayer, ctx.rng);
        return;
      }
      const leftovers = revealed.filter((c) => c.instanceId !== captured!.instanceId);
      chosenPlayer.deck.push(...leftovers);
      shuffleDeck(chosenPlayer, ctx.rng);
      attachCard(ctx.source, captured);
      return;
    }

    if (ctx.powerName === 'Release') {
      const captured = ctx.source.attachedCards[0];
      const def = captured ? ctx.cardDb.get(captured.definitionKey) : undefined;
      const magi = ctx.controllingPlayer.activeMagi;
      if (!captured || !def || def.card_type !== 'Creature' || !magi) return;
      if (typeof def.cost !== 'number') return; // X-cost Creatures have no chosenXValue plumbing here

      // Dreamwarp (task #577, owner ruling 2026-07-28: Release is "another way to play a creature",
      // so it may be Dreamwarped). Folded into the PRINTED cost before the -3, matching play.ts's
      // order -- Dreamwarp moves the starting-energy stat, the -3 is a pure cost reduction that must
      // never reach it. RESOLVED here, COMMITTED only past the affordability gate, so an
      // unaffordable pick leaves the captured Creature completely untouched.
      const dreamwarpDelta = resolveDreamwarpDelta(
        ctx.state,
        ctx.cardDb,
        ctx.controllingPlayer.playerId,
        captured,
        def.cost,
        ctx.chosenDreamwarpAdjustment
      );
      const cost = Math.max(0, def.cost + dreamwarpDelta - 3);
      if ((magi.currentEnergy ?? 0) < cost) return;
      const index = ctx.source.attachedCards.findIndex((c) => c.instanceId === captured.instanceId);
      ctx.source.attachedCards.splice(index, 1);
      commitDreamwarpDelta(ctx.state, ctx.cardDb, captured, def.cost, dreamwarpDelta);
      magi.currentEnergy = (magi.currentEnergy ?? 0) - cost;
      // BUG FIXED 2026-07-28: this used to be `captured.currentEnergy = cost`, i.e. the DISCOUNTED
      // figure. "Reduce the card's cost by three" changes what the Magi PAYS; play.ts states the
      // invariant that a cost reduction "only ever changes what's PAID" and NEVER starting energy.
      //
      // Bug-for-bug the one fixed in Gia's Tome on 2026-07-27 ("under Gia a Creature entered play
      // one energy short") -- the twin was missed then, because the two cards' Release/Research
      // branches were written separately despite doing the same job. A cost-6 Creature released
      // here entered play at 3; anything printed at cost 3 or less entered at 0 and was defeated
      // on the spot, so Release simply threw the Creature away.
      //
      // effectiveStartingEnergy, not the raw printed cost, so per-instance overrides (Slime Stone)
      // and startingEnergyModifier (Liriel's Cape) are honoured -- same reader Gia's Tome uses.
      captured.currentEnergy = effectiveStartingEnergy(ctx.state, ctx.cardDb, captured);
      addToZone(ctx.controllingPlayer, 'inPlay', captured);

      const sourceIndex = ctx.controllingPlayer.inPlay.findIndex((c) => c.instanceId === ctx.source.instanceId);
      if (sourceIndex !== -1) {
        const [bottledCity] = ctx.controllingPlayer.inPlay.splice(sourceIndex, 1);
        moveToDiscardPile(ctx.state, ctx.controllingPlayer, bottledCity!);
      }
      checkCreatureDefeats(ctx.state, ctx.cardDb, 'power', undefined, ctx.rng);
    }
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;
    discardAllAttached(state, cardDb, self);
  },
});
