// Weethan -- "Impede: Whenever an opponent draws a card, you may discard one energy from Weethan to
// force that player to choose and discard any one card from their hand. Impede cannot be used more
// than once each turn and only one Weethan can use Impede each turn." Reactive via onAnyCardDrawn
// (opponent draws, any draw -- not gated to the Draw Step, unlike Snow Barl Pup). Once-per-turn AND
// one-Weethan-per-turn: a self duration tag (IMPEDE_USED) plus a scan of the controller's other
// Weethans for that same tag. "you may" + "that player chooses" are auto-applied simplifications (no
// synchronous choice point during a draw reaction): applied whenever Weethan can pay the 1-energy
// cost and the opponent has a card, discarding the opponent's lowest-cost hand card (their rational
// least-valuable choice) through the hostile-discard-aware discardFromHand (so Bagala Fangs / Harror
// Nightstalker etc. still block or substitute). "Orothe Shadow Magi may play Weethan" is a data
// shadow_play grant, not code.

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromHand, riptideBanActiveFor } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const IMPEDE_USED = 'weethanImpedeUsedThisTurn';

registerCardEffect('Weethan', {
  // task #718 (Riptide clause 2, 2026-08-11): Impede is Effect-shaped (reactive, not a play/use
  // action), so a hook-body gate is needed in addition to the declarative tag.
  causesOpponentHandDiscard: true,
  onAnyCardDrawn: (state, cardDb, self, drawingPlayerId, _drawnCard, rng) => {
    if (drawingPlayerId === self.controllerId) return; // "an opponent"
    if (riptideBanActiveFor(state, self.controllerId)) return; // Riptide ban suppresses Impede
    if ((self.currentEnergy ?? 0) <= 0) return; // must discard one energy from Weethan
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    // "only one Weethan can use Impede each turn" (and not more than once) -- skip if any of the
    // controller's Weethans already impeded this turn.
    const alreadyImpeded = owner.inPlay.some(
      (c) => cardDb.get(c.definitionKey)?.name === 'Weethan' && hasDurationTag(c, IMPEDE_USED)
    );
    if (alreadyImpeded) return;
    const drawer = state.players.get(drawingPlayerId);
    if (!drawer || drawer.hand.length === 0) return;
    const pick = drawer.hand.reduce((lo, c) =>
      (cardDb.get(c.definitionKey)?.cost ?? 0) < (cardDb.get(lo.definitionKey)?.cost ?? 0) ? c : lo
    );
    addDurationTag(state, cardDb, self, IMPEDE_USED, state.turnNumber);
    discardEnergy(state, cardDb, self, 1, 'effect', self.controllerId); // self-cost (friendly)
    discardFromHand(state, cardDb, drawer, [pick.instanceId], self.controllerId, rng);
  },
});
