// Jungle Hyren -- "Dreamwarp: Once per turn, as any player plays a Creature, you may choose to
// increase or decrease its starting energy by up to two until the end of the turn, to a minimum
// of one. Dreamwarp may not raise a Creature's starting energy above the amount of energy on that
// player's Magi." A REACTIVE grant (registry.ts's reactiveDreamwarpRange/resolveReactiveDreamwarp
// doc comments), not the plain self-adjustment shape -- fires for EITHER side's Creature play.
// The Magi-energy cap only restricts RAISING (choosing not to change, or lowering, is always
// legal regardless of the cap) -- `max` is clamped to never fall below `current` for that reason.

import { registerCardEffect } from './registry.js';
import { applyReactiveDreamwarp } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const DREAMWARP_USED_THIS_TURN = 'jungleHyrenDreamwarpUsedThisTurn';

registerCardEffect('Jungle Hyren', {
  reactiveDreamwarpRange: (state, cardDb, played, self) => {
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return undefined;
    if (hasDurationTag(self, DREAMWARP_USED_THIS_TURN)) return undefined;

    const current = played.currentEnergy ?? 0;
    const cap = state.players.get(played.controllerId)?.activeMagi?.currentEnergy ?? current;
    return {
      min: Math.max(1, current - 2),
      max: Math.max(current, Math.min(current + 2, cap)),
    };
  },
  resolveReactiveDreamwarp: (state, cardDb, played, self, chosenEnergy) => {
    applyReactiveDreamwarp(state, cardDb, played, chosenEnergy);
    addDurationTag(state, cardDb, self, DREAMWARP_USED_THIS_TURN, state.turnNumber);
  },
});
