// Wyle -- "Energy Transfer (X): Choose a Creature in play. Add X energy to the chosen Creature."
// A variable-cost, single-target Power. X is chosen once (at cost-payment time) and used again
// here for the effect amount, per the card's own text -- rules-reference.md §9's ctx carries it
// through as chosenXValue for exactly this reason.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Wyle', {
  // "Tap Strength: Whenever one or more opposing Magi gain energy outside of their Energize step,
  // add two energy to Wyle." BUILT 2026-07-28 (ability-count sweep) -- the file had only Energy
  // Transfer.
  //
  // Fires on registry.ts's onMagiGainedEnergyOutsideOwnEnergizeStep, which is deliberately
  // PHASE-gated rather than hung off addEnergy: two cards energize a Magi outside the Energize
  // step (Flood of Energy, Zajan) and both bypass addEnergy, so a code-path test would miss them.
  // Owner ruling 2026-07-28: rearrangeEnergy and restoreEnergy count as gains too, so all four
  // routes broadcast.
  //
  // "one or more opposing Magi" -- this engine is 2-player, so at most one opposing Magi can gain
  // at a time and the "one or more" plural collapses to a single +2 per event. A single gain event
  // therefore adds 2, not 2-per-Magi.
  onMagiGainedEnergyOutsideOwnEnergizeStep: (state, cardDb, magi, self) => {
    if (magi.controllerId === self.controllerId) return; // "OPPOSING Magi" only
    addEnergy(state, cardDb, self, 2, 'effect');
  },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Energy Transfer') return;
    // Fizzle (no effect) if the caller didn't supply what's needed, or the chosen target is no
    // longer legal by the time this actually resolves (§9 step 4).
    if (ctx.chosenTargetId === undefined || ctx.chosenXValue === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    addEnergy(ctx.state, ctx.cardDb, target, ctx.chosenXValue, 'power');
  },
});
