// Skullek -- "Persistence: When one of your illusions is discarded from play, you may discard
// one energy from Skullek to place the card in your hand." Self as the reactor (checks its own
// energy), but the discarded card is a DIFFERENT own Illusion-tagged Creature.
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice`. The discarded Illusion
// is remembered via an embedded-id permanent tag (same technique as Wellisk/Ahron/Gloves of
// Crystal/Hubram/Magam's Ring/Reef Hyren in this same batch) since the resolve call has no target
// parameter.
//
// "Inspire: Each of your Creatures removes one additional energy in attacks." (task #39,
// 2026-07-17.) Same self-agnostic broadcast onAttack shape as Sareb's Incompetent (sareb.ts) --
// combat.ts's onAttack loop already scans every in-play card regardless of who's attacking, so
// this needed no new mechanism.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { isIllusion } from '../durationTags.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';

const PENDING_PREFIX = 'skullekPersistencePending:';

function pendingDiscardedId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return tag.slice(PENDING_PREFIX.length);
  }
  return undefined;
}

function findInDiscardPile(state: GameState, playerId: string, instanceId: string) {
  return state.players.get(playerId)?.discardPile.find((c) => c.instanceId === instanceId);
}

registerCardEffect('Skullek', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Inspire is the your-Creatures-
  // remove-+1 attack buff; Persistence is the discard-1-to-return-a-defeated-Illusion prompt.
  effectHooks: {
    Inspire: ['onAttack'],
    Persistence: ['onCardDiscardedFromPlay', 'pendingYesNoChoice', 'resolveYesNoChoice'],
  },
  onAttack: (ctx, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    ctx.locked.attackerEnergy += 1;
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId === self.instanceId) return;
    if (discardedOwnerId !== self.controllerId) return;
    if (!isIllusion(discarded)) return;
    if ((self.currentEnergy ?? 0) < 1) return;
    if (!findInDiscardPile(state, discardedOwnerId, discarded.instanceId)) return;
    addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${discarded.instanceId}`);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    const discardedId = pendingDiscardedId(self);
    if (discardedId === undefined) return undefined;
    if ((self.currentEnergy ?? 0) < 1) return undefined;
    if (!findInDiscardPile(state, self.controllerId, discardedId)) return undefined;
    return {
      prompt: "Skullek's Persistence: discard one energy from Skullek to place the discarded Illusion in your hand?",
      yesLabel: 'Discard 1, return to hand',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const discardedId = pendingDiscardedId(self);
    if (discardedId !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${discardedId}`);
    if (!chosenBoolean || discardedId === undefined) return;
    if ((self.currentEnergy ?? 0) < 1) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const index = player.discardPile.findIndex((c) => c.instanceId === discardedId);
    if (index === -1) return;
    discardEnergy(state, cardDb, self, 1, 'effect', undefined, rng);
    const [card] = player.discardPile.splice(index, 1);
    player.hand.push(card!);
  },
});
