// Nimbulo -- "Energy Drain: Choose any two Creatures in play. Move one energy from one of the
// chosen Creatures to the other chosen Creature." Same ordered-pair shape as Qwade's Leech, fixed
// amount instead of X.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Nimbulo', {
  powerTargetSlots: (state, cardDb) => [
    {
      label: 'Choose two Creatures in play (first loses energy, second gains it)',
      pool: (s, db) => allCreaturesInPlay(s, db),
      min: 2,
      max: 2,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Energy Drain') return;
    const chosen = ctx.chosenSlotIds?.[0];
    if (!chosen || chosen.length !== 2 || chosen[0] === chosen[1]) return;

    const loser = findInPlayById(ctx.state, chosen[0]!);
    const gainer = findInPlayById(ctx.state, chosen[1]!);
    if (!loser || ctx.cardDb.get(loser.definitionKey)?.card_type !== 'Creature') return;
    if (!gainer || ctx.cardDb.get(gainer.definitionKey)?.card_type !== 'Creature') return;

    rearrangeEnergy(ctx.state, ctx.cardDb, loser, gainer, 1, ctx.rng);
  },
});
