// Hood of Hiding -- "Conceal: Your Magi cannot be attacked until after your next turn. You may
// not use this Power on your next turn." New CANNOT_BE_ATTACKED tag applied to the controller's
// own Magi, "until after your next turn" duration matching nextOwnTurnNumber exactly (same
// wording Tropical Vinoc's Stalk already established that helper for). "May not use this Power
// on your next turn" (region-audit follow-up, 2026-07-24) uses the new
// CardInstance.powerLockedOnTurnNumber mechanism -- see its own doc comment in types/instance.ts.

import { registerCardEffect } from './registry.js';
import { addDurationTag, CANNOT_BE_ATTACKED, nextOwnTurnNumber } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Hood of Hiding', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Conceal') return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;
    addRestrictionTag(ctx.state, magi, CANNOT_BE_ATTACKED, nextOwnTurnNumber(ctx.state));
    ctx.source.powerLockedOnTurnNumber.set('Conceal', nextOwnTurnNumber(ctx.state));
  },
});
