// Orish -- "Hypnotize (1): Choose any one player. The chosen player discards one card at random
// from his or her hand." Simplest card in this batch -- just a target pick plus
// discardRandomFromHand, no own-hand cost and no player choice involved on either side.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardRandomFromHand } from '../effects.js';

registerCardEffect('Orish', {
  powerTargets: (state) => allMagiInPlay(state),
  causesOpponentHandDiscard: true, // task #718 (Riptide clause 2, 2026-08-11)

  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Hypnotize') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const targetOwner = ctx.state.players.get(chosenMagi.controllerId);
    if (!targetOwner) return;
    discardRandomFromHand(ctx.state, ctx.cardDb, targetOwner, 1, ctx.rng);
  },
});
