// Crushing Surf (Spell, Orothe, cost 4) -- "Choose any one Creature in play. Discard four energy
// from the chosen Creature. If this discards the chosen Creature from play, choose any one of that
// player's Relics in play. Gain control of the chosen Relic." Orothe Spell pass, Category B
// (2026-07-24). The Relic pick is a SECOND target (registry.ts's spellSecondTargets), but only
// legal when the first pick's own current energy is <=4 -- discarding 4 will provably defeat it,
// same deterministic "predict the outcome" idiom this codebase already uses for a conditional
// second choice (Kybar's Gift's spellThirdTargets scoping to whichever Magi was chosen first).
// resolveSpell re-confirms the Creature actually left play (a reactive hook could in principle save
// it) before honoring the Relic pick, rather than trusting the UI's own prediction blindly.

import { registerCardEffect } from './registry.js';
import { discardEnergy, gainControl } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Crushing Surf', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) => {
    if (!firstChosenId) return [];
    const target = findInPlayById(state, firstChosenId);
    if (!target || (target.currentEnergy ?? 0) > 4) return [];
    const owner = state.players.get(target.controllerId);
    if (!owner) return [];
    return owner.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic');
  },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const targetOwnerId = target.controllerId;

    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);

    const stillInPlay = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (stillInPlay) return; // the discard didn't defeat it -- no Relic clause
    if (ctx.chosenSecondTargetId === undefined) return;
    const relic = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (!relic || relic.controllerId !== targetOwnerId) return;
    if (ctx.cardDb.get(relic.definitionKey)?.card_type !== 'Relic') return;
    gainControl(ctx.state, ctx.cardDb, relic, ctx.controllingPlayer.playerId);
  },
});
