// Spirit of Orothe (0-cost Spell) -- "You may play this card only when your Orothe Magi is
// defeated on an opponent's turn. Discard a card from your hand. When you reveal your next Magi,
// replace his or her starting cards line with 'STARTING: Orothean Goggles, Hubdra's Cube, One
// Orothe Creature'. You can only play one Spirit Spell per Magi defeated." The "Spirit Spell"
// family (Spirit of Arderial's own header comment) -- same PlayerState.pendingSpiritSpellRegions
// eligibility/budget mechanism, same spellHandDiscardCost: {count: 1} discard, just a different
// consequence: PlayerState.pendingMagiRevealStartingCardNames (turn.ts#revealNextMagi), consumed
// at the very next reveal rather than an immediate hand/deck shuffle-and-draw.

import { closeSpiritSpellWindow } from '../spiritSpells.js';
import { registerCardEffect } from './registry.js';
import { discardFromHand } from '../effects.js';

registerCardEffect('Spirit of Orothe', {
  preventsOwnPlay: (state, cardDb, playerId) => {
    const player = state.players.get(playerId)!;
    return player.pendingSpiritSpellRegions.includes('Orothe')
      ? false
      : "Spirit of Orothe can only be played when your Orothe Magi has just been defeated on an opponent's turn";
  },
  spellHandDiscardCost: { count: 1 },
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    if (!player.pendingSpiritSpellRegions.includes('Orothe')) return; // re-validate; state can change between UI collection and resolution
    // Closes the WHOLE window, not just this region: "only one Spirit Spell per Magi
    // defeated", and a multi-region Magi queues one entry per region (2026-07-26).
    closeSpiritSpellWindow(ctx.state, player.playerId);

    const ids = ctx.chosenHandCardIds ?? [];
    if (ids.length === 1) discardFromHand(ctx.state, ctx.cardDb, player, ids, undefined, ctx.rng);

    player.pendingMagiRevealStartingCardNames = ['Orothean Goggles', "Hubdra's Cube", '[One Orothe Creature]'];
  },
});
