// Ninx -- "Stare Down: Choose any one opposing Magi in play with more energy than Ninx. The
// chosen Magi's energy becomes equal to the energy on Ninx." restoreEnergy sets a card's energy
// to an absolute value directly (not tied to "starting energy" despite the name) -- same reuse
// Sandstorm Xyx already established for "reduce to exactly one."

import { registerCardEffect } from './registry.js';
import { findCreatureOrMagiById, opposingMagi } from '../targeting.js';
import { restoreEnergy } from '../effects.js';

registerCardEffect('Ninx', {
  powerTargets: (state, cardDb, playerId) => {
    const ninxEnergy = state.players.get(playerId)?.activeMagi?.currentEnergy ?? 0;
    return opposingMagi(state, cardDb, playerId).filter((m) => (m.currentEnergy ?? 0) > ninxEnergy);
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Stare Down') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    const ninxEnergy = ctx.source.currentEnergy ?? 0;
    if ((target.currentEnergy ?? 0) <= ninxEnergy) return;

    restoreEnergy(ctx.state, ctx.cardDb, target, ninxEnergy);
  },
});
