// Karkik -- "Flameburst: Choose any one player with more Creatures in play than you. Discard the
// chosen player's smallest Creature from play. In the case of a tie, you choose the Creature to be
// discarded." 2-player only, so "choose a player" is just the opponent (if they qualify) -- no
// target picker needed. The tie-break falls back to smallestOf's own established array-order
// convention (same tradeoff already accepted for Rock Arboll/Galiant-style "smallest" cards).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, smallestOf } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Karkik', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Flameburst') return;
    const opponent = getOpponents(ctx.state, ctx.controllingPlayer.playerId)[0];
    if (!opponent) return;

    const ownCount = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).length;
    const oppCreatures = creaturesControlledBy(ctx.state, ctx.cardDb, opponent.playerId);
    if (oppCreatures.length <= ownCount) return;

    const smallest = smallestOf(oppCreatures);
    if (smallest) discardFromPlay(ctx.state, ctx.cardDb, opponent, smallest.instanceId, undefined, undefined, ctx.rng);
  },
});
