// Vertigo (Spell) -- "Choose any one Magi in play. During that Magi's next turn, he or she must
// spend one additional energy to play each card." Kybar's Teeth Spell pass, Category C
// (2026-07-22). Either side, no "opposing" qualifier. Sets CardInstance.costSurchargeNextOwnTurn
// directly on the chosen Magi -- consulted by play.ts's cost computation as a flat addition,
// gated on the EXACT stored turn number (nextTurnNumberFor the chosen Magi's OWN controller,
// which correctly differs depending on whether the caster targets their own Magi or the
// opponent's -- "that Magi's next turn," not "my next turn").

import { registerCardEffect } from './registry.js';
import { allMagiInPlay } from '../targeting.js';
import { nextTurnNumberFor } from '../durationTags.js';

registerCardEffect('Vertigo', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    const target = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!target) return;
    target.costSurchargeNextOwnTurn = {
      amount: 1,
      turnNumber: nextTurnNumberFor(ctx.state, target.controllerId),
    };
  },
});
