// Chayla -- both printed effects are built here:
//   "Companionship: Once per turn, when you play an Eebit from your hand, draw a card." (onPlay,
//   filtered to the Eebit creature-type via targeting.ts's creatureType -- covers Eebit/Polar
//   Eebit/Jungle Eebit alike, same "type = shared last word" convention as every other
//   creature-type check in this codebase.)
//   "Swarm: All of your Eebits in play gain 'ENERGIZE: 1'." (energizeRateGrant, same shape as
//   windHyren.ts's Invigorate -- a flat rate GRANT, not additive, to every Eebit the controller
//   owns; combines via MAX not SUM against the Eebit's own rate and any other grant -- see
//   registry.ts's energizeRateGrant doc comment. 2026-08-05 rules-correctness fix.)

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { creatureType } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const COMPANIONSHIP_USED_THIS_TURN = 'chaylaCompanionshipUsedThisTurn';

registerCardEffect('Chayla', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Companionship owns the on-Eebit-play draw;
  // Swarm owns the Eebit energize rate grant.
  effectHooks: {
    Companionship: ['onPlay'],
    Swarm: ['energizeRateGrant'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (creatureType(cardDb, played.definitionKey) !== 'Eebit') return;
    if (hasDurationTag(self, COMPANIONSHIP_USED_THIS_TURN)) return;

    const player = state.players.get(self.controllerId);
    if (!player) return;
    drawCards(state, cardDb, player, 1);
    addDurationTag(state, cardDb, self, COMPANIONSHIP_USED_THIS_TURN, state.turnNumber);
  },
  energizeRateGrant: (state, cardDb, energizing, self) => {
    if (energizing.controllerId !== self.controllerId) return 0;
    if (cardDb.get(energizing.definitionKey)?.card_type !== 'Creature') return 0;
    return creatureType(cardDb, energizing.definitionKey) === 'Eebit' ? 1 : 0;
  },
});
