// Vemment -- "Evaporate (1): Choose any one non-Arderial Creature in play. Discard one energy
// from the chosen Creature. If the chosen Creature is Orothe, discard two additional energy."
// (Not to be confused with Barreling Vemment, a different card in the same naming family.)

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Vemment', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)).filter(
      (c) => !effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Arderial'))
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Evaporate') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    const regions = effectiveRegions(ctx.state, ctx.cardDb, target);
    if (regions.includes(regionForTargetFilter(ctx.state, 'Arderial'))) return;
    discardEnergy(ctx.state, ctx.cardDb, target, regions.includes('Orothe') ? 3 : 1, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Arderial'],
});
