// Ruid -- "Invigorate: Your Magi's energize rate is increased by one." Same shape and same effect
// name as Water of Life.
//
// "Mutate: Whenever you play a Bograth Creature, you may choose to have it be a Core Creature
// instead." Built this pass (task #30, 2026-07-15) via the same CardInstance.effectiveRegionOverride
// mechanism as Yog's Turn (targeting.ts's effectiveRegions). "You may" applied unconditionally --
// same documented-simplification convention as every other unprompted auto-pick this project (no
// reveal/play-time choice-prompt UI exists for this either).

import { registerCardEffect } from './registry.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Ruid', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Invigorate owns the energize-rate
  // bump on the controller's Magi. Mutate owns the onPlay Bograth->Core region override.
  effectHooks: {
    Invigorate: ['energizeRateModifier'],
    Mutate: ['onPlay'],
  },
  energizeRateModifier: (state, cardDb, energizing, self) => {
    const owner = state.players.get(self.controllerId);
    if (owner?.activeMagi?.instanceId !== energizing.instanceId) return 0;
    return 1;
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (played.instanceId === self.instanceId) return; // Ruid himself isn't "a Bograth Creature you play" here -- already in play
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    // In-play Creature region check on `played` -- routes through effectiveRegions so Ruid's
    // Mutate fires on a played Core Creature under Glablit's controller (Category D EIGHTH item,
    // 2026-08-12, task #725 -- Dream Blur makes it also Bograth). Note Ruid's effect REPLACES the
    // played card's regions with Core via effectiveRegionOverride; Q4 says Dream Blur reads AFTER
    // that replacement, so a Ruid-converted Core Creature under a same-side Glablit would then
    // become Core+Bograth per Q5's layering rules. That's an intended consequence.
    if (!effectiveRegions(state, cardDb, played).includes('Bograth')) return;
    played.effectiveRegionOverride = { region: 'Core' }; // permanent -- no expiresAfterTurnNumber
  },
});
