// Shroud of the Master -- "Absolute Authority (0): Discard a Core card from your hand. Add one
// energy to your Magi and one energy to each of your Core Creatures. If your Magi is Agram, add
// one extra energy to each of your Core Creatures."
//
// CORRECTED 2026-07-25 (project owner, re-reading Shadow Empress): this used to match Shadow
// Empress too, on the strength of a global "counts as Agram" alias. It should NOT. Her Mastery of
// Shadows grants that identity for SPELLS only ("...may play Spells as though she were Agram and
// your Spells in play treat her as though she were Agram"), and Shroud of the Master is a RELIC
// Power. Plain `magiCountsAs` (intrinsic identity: own name + database Alternates) is therefore the
// correct check here -- note her real, unconditional Alternate is WARRADA, not Agram. See
// magiIdentity.ts for the full three-way distinction.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardFromHand } from '../effects.js';
import { magiCountsAs } from './magiIdentity.js';

registerCardEffect('Shroud of the Master', {
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(state, 'Core')) ?? false,
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Absolute Authority') return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandCardIds![0]);
    if (!discardedCard || !ctx.cardDb.get(discardedCard.definitionKey)?.regions.includes(regionForTargetFilter(ctx.state, 'Core'))) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    if (ctx.controllingPlayer.activeMagi) addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, 1, 'power');
    const isAgram = !!ctx.controllingPlayer.activeMagi && magiCountsAs(ctx.cardDb, ctx.controllingPlayer.activeMagi, 'Agram');
    const perCreature = isAgram ? 2 : 1;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      if (effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Core'))) {
        addEnergy(ctx.state, ctx.cardDb, creature, perCreature, 'power');
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Covers both the energy-add broadcast and the
  // handDiscardCost's own Core filter (wired into Play.tsx via handDiscardCostWithRegionSwap).
  specifiedTargetRegions: () => ['Core'],
});
