// Essence of Naroom -- "Call of the Wild (4): Choose any one Naroom, Weave, or Paradwyn Creature
// in play. Discard Essence of Naroom from play. Gain control of the chosen Creature. That
// Creature may not attack this turn."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay, gainControl } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import type { GameState } from '../types/state.js';

const ELIGIBLE_REGIONS = ['Naroom', 'Weave', 'Paradwyn'];

// Region-swap sweep (Spell-pass audit follow-up, 2026-07-23): the eligible set is checked as
// "does this card's region overlap ELIGIBLE_REGIONS, each one individually passed through
// regionForTargetFilter" -- a swap of any ONE of the 3 fixed regions (Naroom/Weave/Paradwyn)
// substitutes cleanly since the whole thing is still an OR of 3 literals underneath.
function eligibleRegions(state: GameState) {
  return ELIGIBLE_REGIONS.map((r) => regionForTargetFilter(state, r));
}

registerCardEffect('Essence of Naroom', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter((c) => {
      const def = cardDb.get(c.definitionKey);
      return !!def && def.regions.some((r) => eligibleRegions(state).includes(r));
    }),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Call of the Wild') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    const def = target ? ctx.cardDb.get(target.definitionKey) : undefined;
    if (!target || !def || !def.regions.some((r) => eligibleRegions(ctx.state).includes(r))) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);
  },
  specifiedTargetRegions: () => ELIGIBLE_REGIONS,
});
