// Cloud Orshaa -- "Mystic Binding: As you play Cloud Orshaa, discard up to four Arderial Spells
// from your hand. Add two energy to Cloud Orshaa for each Spell discarded."
//
// Real choice (task #40-6, 2026-07-17, player-choice-default retrofit, Group 6): "up to four" is
// a real player choice (which Spells, and how many up to the cap), not an auto-pick -- now a
// `pendingMultiTargetChoice`/`resolveMultiTargetChoice` (registry.ts's new multi-select post-hoc
// family), `minCount: 0` covering "up to." No resolution falls back to the old "discard as many
// eligible Arderial Spells as are in hand, capped at four, in hand order" default.

import { registerCardEffect } from './registry.js';
import { addEnergy, checkHandEmptied } from '../effects.js';
import { moveToDiscardPile } from '../zones.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING_CHOICE = 'cloudOrshaaAwaitingChoice';

function eligibleSpells(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.hand.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return def?.card_type === 'Spell' && def.regions?.includes('Arderial');
  });
}

registerCardEffect('Cloud Orshaa', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    if (eligibleSpells(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, AWAITING_CHOICE);
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const eligible = eligibleSpells(state, cardDb, self);
    if (eligible.length === 0) return undefined;
    return {
      prompt: "Cloud Orshaa's Mystic Binding: discard up to four Arderial Spells from your hand (add two energy to Cloud Orshaa for each)",
      pool: eligible.map((c) => c.instanceId),
      minCount: 0,
      maxCount: Math.min(4, eligible.length),
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds, rng) => {
    removePermanentTag(self, AWAITING_CHOICE);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const eligible = eligibleSpells(state, cardDb, self);
    const eligibleIds = new Set(eligible.map((c) => c.instanceId));

    let chosen: CardInstance[];
    if (chosenInstanceIds) {
      const ids = [...new Set(chosenInstanceIds)].filter((id) => eligibleIds.has(id)).slice(0, 4);
      chosen = ids.map((id) => eligible.find((c) => c.instanceId === id)).filter((c): c is CardInstance => c !== undefined);
    } else {
      chosen = eligible.slice(0, 4);
    }

    for (const card of chosen) {
      const index = player.hand.findIndex((c) => c.instanceId === card.instanceId);
      if (index === -1) continue;
      player.hand.splice(index, 1);
      moveToDiscardPile(state, player, card);
    }
    if (chosen.length > 0) {
      addEnergy(state, cardDb, self, chosen.length * 2, 'effect');
    }
    checkHandEmptied(state, cardDb, rng);
  },
});
