// Ghost Bwisp -- "Glow: All of your Creatures can attack while burrowed." Same shape as Digging
// Goggles (task #26's grantsCanAttackWhileBurrowedTo broadcast, 2026-07-14) -- own Creatures only.

import { registerCardEffect } from './registry.js';

registerCardEffect('Ghost Bwisp', {
  grantsCanAttackWhileBurrowedTo: (state, cardDb, self, target) => {
    if (target.controllerId !== self.controllerId) return false;
    return cardDb.get(target.definitionKey)?.card_type === 'Creature';
  },
});
