// Tropical Plith -- "Confer: During your Draw step, if you played a Creature with the Effect
// 'Dreamwarp' this turn, draw an additional card" (registry.ts's drawCountModifier). Checks for
// any of the controller's own in-play Creatures played THIS turn (playedOnTurnNumber) whose def
// has a registered `dreamwarpRange` hook -- registering that hook IS the "prints Dreamwarp"
// signal, same presence-only check as Robe of Petals. Doesn't require the Dreamwarp choice to
// have actually been used, just that the card (which prints the Effect) was played this turn,
// matching the printed wording exactly.

import { registerCardEffect } from './registry.js';
import { effectsFor } from '../grantedEffects.js';

registerCardEffect('Tropical Plith', {
  drawCountModifier: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return 0;
    const playedDreamwarpCreatureThisTurn = player.inPlay.some((c) => {
      if (c.playedOnTurnNumber !== state.turnNumber) return false;
      const def = cardDb.get(c.definitionKey);
      if (def?.card_type !== 'Creature') return false;
      // Presence-of-Dreamwarp is now a granted-Effect-aware predicate (owner ruling 2026-07-28):
      // a Creature granted a Dreamwarp Creature's Effects IS a Dreamwarp Creature.
      return effectsFor(state, cardDb, c).some((e) => e.dreamwarpRange !== undefined);
    });
    return playedDreamwarpCreatureThisTurn ? 1 : 0;
  },
});
