// Gremble -- "Parasitic Growth: Discard Gremble from play. Discard your hand and draw three
// cards."

import { registerCardEffect } from './registry.js';
import { discardFromPlay, discardFromHand, drawCards } from '../effects.js';

registerCardEffect('Gremble', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Parasitic Growth') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const handIds = ctx.controllingPlayer.hand.map((c) => c.instanceId);
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, handIds, undefined, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 3);
  },
});
