// Gratch -- "Hunting Howl: At the beginning of your turn, if your smallest Creature in play is
// larger than the largest opposing Creature in play, add one energy to each of your other
// Kybar's Teeth Creature in play." "Your smallest Creature" includes Gratch itself as a candidate
// (no "other" qualifier on that half); "each of your OTHER Kybar's Teeth Creature" excludes Gratch
// from the benefit only.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions, opposingCreatures, smallestOf } from '../targeting.js';

registerCardEffect('Gratch', {
  onOwnTurnStart: (state, cardDb, self) => {
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    const smallestOwn = smallestOf(own);
    const opposing = opposingCreatures(state, cardDb, self.controllerId);
    if (opposing.length === 0 || !smallestOwn) return;
    const largestOpposing = opposing.reduce((best, c) => ((c.currentEnergy ?? 0) > (best.currentEnergy ?? 0) ? c : best));
    if ((smallestOwn.currentEnergy ?? 0) <= (largestOpposing.currentEnergy ?? 0)) return;

    for (const creature of own) {
      if (creature.instanceId === self.instanceId) continue;
      if (!effectiveRegions(state, cardDb, creature).includes("Kybar's Teeth")) continue;
      addEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
});
