// Digging Goggles -- "Tunneling Attack: Your burrowed Creatures may attack as normal." Built via
// task #26's `grantsCanAttackWhileBurrowedTo` broadcast (2026-07-14), checked by combat.ts's
// isLegalAttack alongside the existing self-only canAttackWhileBurrowed check. "Your" scopes this
// to the controller's own Creatures only.

import { registerCardEffect } from './registry.js';

registerCardEffect('Digging Goggles', {
  grantsCanAttackWhileBurrowedTo: (state, cardDb, self, target) => {
    if (target.controllerId !== self.controllerId) return false;
    return cardDb.get(target.definitionKey)?.card_type === 'Creature';
  },
});
