// Tony Jones -- two printed clauses:
//   "Animite Affinity: Non-Universal Creatures Tony plays cost one less energy, to a minimum of
//   one." -- plain costModifier.
//   "Favors (2): Play any one Relic from your hand, regardless of region." -- registry.ts's
//   handPlayChoice (same "play a card straight from hand, outside the normal play.ts flow" shape
//   as Whall/Shimmering Orshaa), filtered to Relics. The printed text bypasses REGION legality
//   only, not cost -- the Relic's own printed cost is still paid from the Magi, same as a normal
//   Relic play, just without play.ts's own region check.

import { registerCardEffect } from './registry.js';
import { playFromZone } from '../effects.js';

registerCardEffect('Tony Jones', {
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    if (playedDef.card_type !== 'Creature') return 0;
    return playedDef.regions.includes('Universal') ? 0 : -1;
  },
  handPlayChoice: {
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Relic',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Favors') return;
    if (!ctx.chosenHandPlayId) return;
    const card = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
    if (!card || def?.card_type !== 'Relic') return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;
    const cost = typeof def.cost === 'number' ? def.cost : 0;
    if ((magi.currentEnergy ?? 0) < cost) return;
    // Direct cost payment, same as play.ts's own Magi payment -- not effects.ts's discardEnergy,
    // which is for opposing-caused energy loss (Shifty/burrow-cap), not a self-paid cost.
    magi.currentEnergy = (magi.currentEnergy ?? 0) - cost;
    playFromZone(ctx.state, ctx.cardDb, { owner: ctx.controllingPlayer, zone: 'hand', instanceId: card.instanceId }, ctx.controllingPlayer, null, ctx.rng);
  },
});
