// Lightning Hyren -- "Shockstorm (4): Discard one energy from each non-Arderial Creature in
// play." No target. (Distinct card from Thunder Hyren's own "Shockstorm" -- same Power name,
// different amount, each registered separately since the registry keys by card name.)

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Lightning Hyren', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shockstorm') return;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Arderial'))) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Arderial'],
});
