// Icecap -- all three printed clauses, built task #43, 2026-07-18, the Nar region pass --
// Category B:
//   "When Icecap comes into play, choose an opposing Magi. That Magi gains control of Icecap." A
//   plain onPlay + effects.ts's existing gainControl -- handing the Relic to the CHOSEN opponent
//   instead of the more common "gain control of an opponent's card" direction. Simplified to "the"
//   opposing Magi, matching every other "choose an opposing Magi" card in a 2-player game.
//   "Chilling Thought: Your cards cost one extra energy to play." Self-referential to whichever
//   player CURRENTLY controls Icecap (checked live via self.controllerId, not a fixed side --
//   after the swap above, that's always the opponent who received it).
//   "At the end of your turn, you may discard all of your Relics from play." onOwnTurnEnd +
//   pendingYesNoChoice/resolveYesNoChoice, same "may" family as Freep's Refresh.

import { registerCardEffect } from './registry.js';
import { gainControl, discardFromPlay } from '../effects.js';
import { opposingMagi } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const DISCARD_RELICS_PENDING = 'icecapDiscardRelicsPending';

registerCardEffect('Icecap', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    const opponentMagi = opposingMagi(state, cardDb, self.controllerId)[0];
    if (!opponentMagi) return;
    gainControl(state, cardDb, self, opponentMagi.controllerId);
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return 1;
  },
  onOwnTurnEnd: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const hasOtherRelic = player.inPlay.some((c) => c.instanceId !== self.instanceId && cardDb.get(c.definitionKey)?.card_type === 'Relic');
    if (!hasOtherRelic) return;
    addPendingChoiceTag(self, DISCARD_RELICS_PENDING);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(DISCARD_RELICS_PENDING)) return undefined;
    return {
      prompt: "Icecap: discard all of your Relics from play?",
      yesLabel: 'Discard all Relics',
      noLabel: 'Keep them',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, DISCARD_RELICS_PENDING);
    if (!chosenBoolean) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const relics = player.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic');
    for (const relic of relics) {
      discardFromPlay(state, cardDb, player, relic.instanceId, undefined, undefined, rng);
    }
  },
});
