// Rous -- "Hit: Choose one opposing Creature. Move one energy from the chosen Creature to Rous."
// No printed cost (one of the 212 real free Powers -- power.ts treats that as 0). Exercises
// effects.ts's rearrangeEnergy primitive for the first time (previous cards only ever added to or
// discarded from a single instance).
//
// "Myth"'s first sentence ("Rous cannot be attacked") is implemented below via canBeAttacked --
// a static attack-legality restriction, checked by combat.ts's isLegalAttack. Its second sentence
// ("If all of your Creatures in play are Rous, discard Rous from play") is a continuously-
// monitored state condition -- post-playtest correctness pass, P4 (2026-07-12), via registry.ts's
// standingConditionMet hook (effects.ts's sweepStandingConditions).

import { registerCardEffect } from './registry.js';
import { opposingCreatures, findInPlayById, creaturesControlledBy } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Rous', {
  powerTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Hit') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return; // must still be opposing
    rearrangeEnergy(ctx.state, ctx.cardDb, target, ctx.source, 1, ctx.rng);
  },
  canBeAttacked: () => false,
  standingConditionMet: (state, cardDb, self) => {
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    return own.length > 0 && own.every((c) => cardDb.get(c.definitionKey)?.name === 'Rous');
  },
});
