// Targ'n -- "Enhanced Invulnerability: All of your Creatures in play with Invulnerability lose
// one less energy in attacks." "With Invulnerability" is read as PRINTING the named Effect
// (cardDb's own effects array), same "does this card's data say it has effect X" check
// Weave-woven Anklet already uses for Weave -- a temporarily GRANTED Invulnerability (Grej's
// Toughen) doesn't count, since the target's own printed card data is unchanged.
//
// EXCLUDES Rock Hyren specifically: its own Invulnerability text ("Your Spells, Powers, and other
// Effects may not prevent Rock Hyren from losing energy") is an anti-stacking clause confirmed
// with the project owner 2026-07-11 to block exactly this kind of additional reduction -- see
// rockHyren.ts's doc comment for the full reasoning.

import { registerCardEffect } from './registry.js';
import { applyInvulnerability } from './invulnerability.js';
import type { CardInstance } from '../types/instance.js';
import type { CardDatabase } from '../types/card.js';

function printsInvulnerability(cardDb: CardDatabase, instance: CardInstance): boolean {
  return cardDb.get(instance.definitionKey)?.effects?.some((e) => e.name === 'Invulnerability') ?? false;
}

registerCardEffect("Targ'n", {
  onAttack: (ctx, self) => {
    for (const combatant of [ctx.attacker, ctx.defender]) {
      if (!combatant) continue;
      if (
        combatant.controllerId === self.controllerId &&
        printsInvulnerability(ctx.cardDb, combatant) &&
        ctx.cardDb.get(combatant.definitionKey)?.name !== 'Rock Hyren'
      ) {
        // 4th arg: granted BY Targ'N to another card -- see graniteParmalag.ts.
        applyInvulnerability(ctx, combatant, 1, self);
      }
    }
  },
});
