// Resonate (Spell, Underneath, cost 1) -- "Choose any or all of the following: Choose any one Relic
// in play. Discard the chosen Relic from play. OR Choose any one Creature in play. Discard one
// energy from the chosen Creature. OR Choose any one Magi in play. Discard two energy from the
// chosen Magi. For each action chosen, Resonate's cost is increased by one."
// Underneath Spell pass, Category C (2026-07-25).
//
// First (and so far only) user of registry.ts's `spellModes` -- see SpellModeShape's doc comment
// for why a modal Spell whose cost depends on the selection can't use the existing
// spellBooleanChoice/pending-choice machinery: the modes have to be picked BEFORE isLegalToPlay
// computes the cost, so they ride on PlayCardOptions like chosenXValue does.
//
// Effective costs: 1 mode = 2, 2 modes = 3, all 3 = 4. play.ts rejects a zero-mode play outright.
//
// Every pool is "any ... in play," i.e. BOTH sides -- Resonate can hit the caster's own board, and
// the Magi clause can target the caster's own Magi. That is the printed card, not an oversight.
// Modes resolve in the card's own printed order regardless of the order the player checked them.

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById, findInPlayById } from '../targeting.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

function relicsInPlay(state: GameState, cardDb: CardDatabase): CardInstance[] {
  const result: CardInstance[] = [];
  for (const player of state.players.values()) {
    for (const card of player.inPlay) {
      if (cardDb.get(card.definitionKey)?.card_type === 'Relic') result.push(card);
    }
  }
  return result;
}

registerCardEffect('Resonate', {
  spellModes: [
    { id: 'relic', label: 'Discard a Relic from play', costIncrease: 1, targets: (state, cardDb) => relicsInPlay(state, cardDb) },
    { id: 'creature', label: 'Discard one energy from a Creature', costIncrease: 1, targets: (state, cardDb) => allCreaturesInPlay(state, cardDb) },
    { id: 'magi', label: 'Discard two energy from a Magi', costIncrease: 1, targets: (state) => allMagiInPlay(state) },
  ],
  resolveSpell: (ctx) => {
    const chosen = new Set(ctx.chosenSpellModeIds ?? []);
    const targetOf = (modeId: string): string | undefined => ctx.chosenSpellModeTargets?.[modeId];

    if (chosen.has('relic')) {
      const id = targetOf('relic');
      const relic = id ? findInPlayById(ctx.state, id) : undefined;
      if (relic && ctx.cardDb.get(relic.definitionKey)?.card_type === 'Relic') {
        const owner = ctx.state.players.get(relic.controllerId);
        if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, relic.instanceId, undefined, 'spell', ctx.rng);
      }
    }

    if (chosen.has('creature')) {
      const id = targetOf('creature');
      const creature = id ? findInPlayById(ctx.state, id) : undefined;
      if (creature && ctx.cardDb.get(creature.definitionKey)?.card_type === 'Creature') {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell', undefined, ctx.rng);
      }
    }

    if (chosen.has('magi')) {
      const id = targetOf('magi');
      const magi = id ? findCreatureOrMagiById(ctx.state, id) : undefined;
      // Re-check it's still an ACTIVE Magi -- an earlier mode this same resolution could have
      // defeated it (Resonate can discard a Relic propping a Magi up, for instance).
      const stillActive = magi && [...ctx.state.players.values()].some((p) => p.activeMagi?.instanceId === magi.instanceId);
      if (magi && stillActive) discardEnergy(ctx.state, ctx.cardDb, magi, 2, 'spell', undefined, ctx.rng);
    }
  },
});
