// Mountain Trulb -- both printed clauses, built task #42, 2026-07-17, the Kybar's Teeth region
// pass -- Category D, own design checkpoint (the plan's "genuinely novel single-card mechanism"):
//   "Rolling Stone: If you control another Trulb or another Kybar's Teeth creature, you may play
//   Mountain Trulb at the beginning of your attack step, paying all costs." No existing hook
//   rescheduled WHEN a card may be played -- built a NEW registry.ts hook, onOwnAttackStepStart,
//   broadcast over the active player's HAND specifically (turn.ts's new runAttackStepStart, see
//   both doc comments for the full reasoning), feeding the same pendingYesNoChoice/
//   resolveYesNoChoice "may" shape as every other Group-4 card (Freep's Refresh is the closest
//   precedent). The "yes" branch calls play.ts's existing playFromZonePayingCost (Looph/Black
//   Stuff's "play from hand, paying full cost, phase gate bypassed" primitive) -- "paying all
//   costs" is exactly that primitive's own contract, not a discount or a free play.
//   "Gathers No Moss: Mountain Trulb removes additional energy when attacking equal to the number
//   of Trulbs or Kybar's Teeth creatures in play, whichever is greater." No "your" qualifier on
//   either count (unlike Rolling Stone's own "you control"), read literally as BOTH players'
//   boards combined -- allCreaturesInPlay (targeting.ts) is already board-wide for exactly this
//   reason. onBeforeEnergyRemoved, same "add energy to the attacker before the damage snapshot"
//   shape as Bleph's Fu.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, allCreaturesInPlay, effectiveRegions } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { playFromZonePayingCost } from '../play.js';

const ROLLING_STONE_PENDING = 'mountainTrulbRollingStonePending';

function rollingStoneEligible(state: Parameters<typeof addEnergy>[0], cardDb: Parameters<typeof addEnergy>[1], self: { controllerId: string }): boolean {
  return creaturesControlledBy(state, cardDb, self.controllerId).some((c) => {
    const def = cardDb.get(c.definitionKey);
    return !!def && (def.name.includes('Trulb') || effectiveRegions(state, cardDb, c).includes("Kybar's Teeth"));
  });
}

registerCardEffect('Mountain Trulb', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Rolling Stone owns the
  // attack-step-start yes/no play trigger; Gathers No Moss owns the pre-damage +bonus.
  effectHooks: {
    'Rolling Stone': ['onOwnAttackStepStart', 'pendingYesNoChoice', 'resolveYesNoChoice'],
    'Gathers No Moss': ['onBeforeEnergyRemoved'],
  },
  onOwnAttackStepStart: (state, cardDb, self) => {
    removePermanentTag(self, ROLLING_STONE_PENDING);
    if (rollingStoneEligible(state, cardDb, self)) addPendingChoiceTag(self, ROLLING_STONE_PENDING);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(ROLLING_STONE_PENDING)) return undefined;
    if (!rollingStoneEligible(state, cardDb, self)) return undefined;
    return {
      prompt: "Mountain Trulb's Rolling Stone: play Mountain Trulb now, paying all costs?",
      yesLabel: 'Play Mountain Trulb',
      noLabel: 'Not now',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, ROLLING_STONE_PENDING);
    if (!chosenBoolean) return;
    if (!rollingStoneEligible(state, cardDb, self)) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    playFromZonePayingCost(state, cardDb, player, 'hand', self.instanceId, {}, rng);
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    const trulbCount = allCreaturesInPlay(ctx.state, ctx.cardDb).filter((c) => ctx.cardDb.get(c.definitionKey)?.name.includes('Trulb')).length;
    const kybarsTeethCount = allCreaturesInPlay(ctx.state, ctx.cardDb).filter((c) => effectiveRegions(ctx.state, ctx.cardDb, c).includes("Kybar's Teeth")).length;
    const bonus = Math.max(trulbCount, kybarsTeethCount);
    if (bonus > 0) addEnergy(ctx.state, ctx.cardDb, self, bonus, 'effect');
  },
});
