// Kiesel's Hammer -- "Daze: Choose a Creature and remove one energy from it. That Creature may not
// gain energy until the beginning of your next turn." Built task #48, 2026-07-18, the Underneath
// region pass -- Category B. A targeted energy removal plus the new NO_ENERGY_GAIN duration tag
// (durationTags.ts): removing 1 energy is `discardEnergy`; the "may not gain energy until the
// beginning of your next turn" clause tags the chosen Creature with NO_ENERGY_GAIN (a full
// energy-gain block, gated at the top of effects.ts's addEnergy), expiring at
// beginningOfNextOwnTurnNumber. "Choose a Creature" is unrestricted (either side).

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, NO_ENERGY_GAIN, beginningOfNextOwnTurnNumber } from '../durationTags.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect("Kiesel's Hammer", {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Daze') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    discardEnergy(ctx.state, ctx.cardDb, target, 1, 'power', undefined, ctx.rng);
    addDurationTag(ctx.state, ctx.cardDb, target, NO_ENERGY_GAIN, beginningOfNextOwnTurnNumber(ctx.state));
  },
});
