// Blizzard Hyren -- two Powers, no target needed for either:
//   "Storm (1): Discard one energy from each opposing frozen Creature. Discard one energy from
//   each opposing frozen Magi for each of that Magi's frozen Creatures."
//   "Fury (1): Blizzard Hyren can attack twice this turn."

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { getOpponents } from '../types/state.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Blizzard Hyren', {
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Storm') {
      const opponent = getOpponents(ctx.state, ctx.controllingPlayer.playerId)[0];
      if (!opponent) return;
      const frozenCreatures = opponent.inPlay.filter(
        (c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature' && isFrozen(ctx.state, ctx.cardDb, c)
      );
      for (const creature of frozenCreatures) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
      }
      if (opponent.activeMagi && isFrozen(ctx.state, ctx.cardDb, opponent.activeMagi)) {
        discardEnergy(ctx.state, ctx.cardDb, opponent.activeMagi, frozenCreatures.length, undefined, undefined, ctx.rng);
      }
      return;
    }
    if (ctx.powerName === 'Fury') {
      ctx.source.oneShotBonusAttacks += 1;
    }
  },
});
