// Bhatar -- "Tunneling Charge: If Bhatar attacks an Underneath Creature, add three energy to
// Bhatar before energy is removed." "Charge: If Bhatar attacks a non-Underneath Creature, add one
// energy to Bhatar before energy is removed." Self as the attacker, Creature-defender only
// (a direct Magi attack triggers neither clause), region-gated on the DEFENDER. The "Charge"
// else-branch added task #45, 2026-07-18, the Naroom region pass -- the file previously only
// implemented Tunneling Charge and didn't acknowledge the second clause existed.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Bhatar', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Tunneling Charge and Charge share a
  // single onBeforeEnergyRemoved body (isUnderneath ? +3 : +1 branch inside one hook), so both
  // Effects list the same hook -- a Taglat narrowed grant of either surfaces the shared branch
  // and its own defender-region gate picks the right bonus.
  effectHooks: {
    'Tunneling Charge': ['onBeforeEnergyRemoved'],
    Charge: ['onBeforeEnergyRemoved'],
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;

    const isUnderneath = effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Underneath');
    addEnergy(ctx.state, ctx.cardDb, self, isUnderneath ? 3 : 1, 'effect');
  },
});
