// Syphon Vortex (Spell, cost X+4) -- "Choose any one Creature in play. Discard X energy from the
// chosen Creature. Add X energy to your Magi." Cald Spell pass, Category B (2026-07-20).
// sandswirl.ts's X-cost Spell shape (getCounter(ctx.source, 'startingX'), auto-populated by
// play.ts's generic X-cost plumbing for any card type) + a plain spellTargets pool;
// discardEnergy(X) + addEnergy(X).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy, getCounter } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Syphon Vortex', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;
    const x = getCounter(ctx.source, 'startingX');
    if (x <= 0) return;

    discardEnergy(ctx.state, ctx.cardDb, target, x, 'spell', undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, magi, x, 'spell');
  },
});
