// Tidal Wave (Spell, Orothe, cost 6) -- "Choose any one Creature in play. Discard the chosen
// Creature from play. For an additional four energy you may choose and discard a second Creature
// from play." The optional second Creature IS the "additional four energy" payment -- registry.ts's
// spellSecondTargets pool is offered only when the caster's own Magi can actually afford the extra
// 4, so picking a second target and paying for it are the same UI action (no separate boolean
// prompt needed, matching the "presence of a chosen optional target is the decision" idiom). Not
// choosing a second target (pool present but nothing picked) is a legal decline.

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Tidal Wave', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) => {
    const player = state.players.get(playerId);
    if (!player?.activeMagi || (player.activeMagi.currentEnergy ?? 0) < 4) return [];
    return allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== firstChosenId);
  },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const first = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!first || ctx.cardDb.get(first.definitionKey)?.card_type !== 'Creature') return;
    const owner1 = ctx.state.players.get(first.controllerId);
    if (owner1) discardFromPlay(ctx.state, ctx.cardDb, owner1, first.instanceId, undefined, 'spell', ctx.rng);

    if (ctx.chosenSecondTargetId === undefined) return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 4) return;
    if (ctx.chosenSecondTargetId === ctx.chosenTargetId) return;
    const second = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (!second || ctx.cardDb.get(second.definitionKey)?.card_type !== 'Creature') return;

    discardEnergy(ctx.state, ctx.cardDb, magi, 4, 'spell', undefined, ctx.rng);
    const owner2 = ctx.state.players.get(second.controllerId);
    if (owner2) discardFromPlay(ctx.state, ctx.cardDb, owner2, second.instanceId, undefined, 'spell', ctx.rng);
  },
});
