// Tundra Hyren -- "Freeze (3): Choose an opposing Magi. That Magi's Creatures are Frozen until
// the beginning of your next turn. Powers of Frozen cards cost one extra energy to use." First
// user of durationTags.ts's FROZEN tag -- a discrete, Power-applied mass status, same "choose a
// player via their Magi, apply a duration tag to every Creature they control" shape as Jungle
// Jile's Mass Stalk. The "Powers... cost one extra energy" clause is FROZEN's own baseline rule
// (power.ts's isLegalPowerUse), not something this card needs to implement itself.

import { registerCardEffect } from './registry.js';
import { opposingMagi, creaturesControlledBy, findCreatureOrMagiById } from '../targeting.js';
import { addDurationTag, beginningOfNextOwnTurnNumber, FROZEN } from '../durationTags.js';

registerCardEffect('Tundra Hyren', {
  powerTargets: (state, cardDb, playerId) => opposingMagi(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Freeze') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;

    const expiry = beginningOfNextOwnTurnNumber(ctx.state);
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, chosenMagi.controllerId)) {
      addDurationTag(ctx.state, ctx.cardDb, creature, FROZEN, expiry);
    }
  },
});
