// Quirle (Weave Magi) -- "Gift of Life: At the start of each player's turn, you may choose any one
// Weave Creature in play. Add one energy to the chosen Creature." Built in the Weave region pass
// #49, Category B.
//
// "the start of EACH player's turn" -> fire on BOTH onOwnTurnStart and onOpponentTurnStart, each
// arming a pending target choice (Koza's Steal pattern: permanent tag + pendingTargetChoice/
// resolveTargetChoice, surfaced by the UI's checkAttachChoices after the phase/turn advances).
// "any one Weave Creature in play" -> the pool is EITHER player's Weave Creatures (effectiveRegions
// so a region-reassigned Creature, e.g. via Scyalla's Pet Project, still counts). "you may" ->
// resolveTargetChoice with null declines.

import { registerCardEffect } from './registry.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const GIFT_PENDING = 'quirleGiftOfLifePending';

function weaveCreaturesInPlay(state: GameState, cardDb: CardDatabase): CardInstance[] {
  return allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes('Weave'));
}

function armGift(state: GameState, cardDb: CardDatabase, self: CardInstance): void {
  if (weaveCreaturesInPlay(state, cardDb).length === 0) return; // nothing to choose -> leave unarmed
  addPendingChoiceTag(self, GIFT_PENDING);
}

registerCardEffect('Quirle', {
  onOwnTurnStart: (state, cardDb, self) => armGift(state, cardDb, self),
  onOpponentTurnStart: (state, cardDb, self) => armGift(state, cardDb, self),
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(GIFT_PENDING)) return undefined;
    const pool = weaveCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Quirle's Gift of Life: choose any Weave Creature in play to add 1 energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, GIFT_PENDING);
    if (!chosenInstanceId) return;
    const target = weaveCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) addEnergy(state, cardDb, target, 1, 'effect');
  },
});
