// Frenzy (Spell) -- "If you have at least three Bograth Creatures in play, add two energy to each
// Creature in play." Bograth Spell pass, Category A (2026-07-20). Identical count-gate shape to
// Ainjer Swarm, just an addEnergy loop over allCreaturesInPlay (unqualified pool, both sides), same
// shape as jaela.ts again.

import { registerCardEffect } from './registry.js';
import { effectiveBograthCreatureCount, allCreaturesInPlay } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Frenzy', {
  resolveSpell: (ctx) => {
    const count = effectiveBograthCreatureCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (count < 3) return;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      addEnergy(ctx.state, ctx.cardDb, creature, 2, 'spell');
    }
  },
});
