// Scarletsong Hwit -- both printed clauses:
//   "Call of the Riled: All of your Paradwyn Creatures lose one less energy whenever they are
//   attacked, and remove one additional energy whenever they attack." A third-party reactor
//   granting a passive combat buff to every own Paradwyn Creature (including Scarletsong Hwit
//   itself, a Paradwyn Creature).
//   "Dreamwarp: As you play Scarletsong Hwit, increase or decrease its starting energy by up to
//   one, until the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { effectiveRegions } from '../targeting.js';
import type { CombatContext } from '../combat.js';
import type { CardInstance } from '../types/instance.js';

function isOwnParadwynCreature(ctx: CombatContext, self: CardInstance, candidate: CardInstance | null): boolean {
  if (!candidate) return false;
  if (candidate.controllerId !== self.controllerId) return false;
  return effectiveRegions(ctx.state, ctx.cardDb, candidate).includes('Paradwyn');
}

registerCardEffect('Scarletsong Hwit', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Call of the Riled is the passive
  // combat buff for own Paradwyn Creatures; Dreamwarp is the standard self-play data field.
  effectHooks: {
    'Call of the Riled': ['onAttack'],
    Dreamwarp: ['dreamwarpRange'],
  },
  onAttack: (ctx, self) => {
    if (isOwnParadwynCreature(ctx, self, ctx.attacker)) {
      ctx.locked.attackerEnergy += 1; // "remove one additional energy whenever they attack"
    }
    if (isOwnParadwynCreature(ctx, self, ctx.defender)) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.max(0, ctx.locked.attackerEnergy - 1); // "lose one less... attacked"
    }
  },
  dreamwarpRange: () => 1,
});
