// Ooze Arboll -- "Amplify: Discard Ooze Arboll from play. Add one energy to each of your Bograth
// Creatures in play." Self-discard happens FIRST per text order -- Ooze Arboll is itself Bograth,
// so it must not receive its own bonus, and it doesn't since the sweep runs after the discard.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Ooze Arboll', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Amplify') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      if (effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Bograth'))) {
        addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Bograth'],
});
