// Book of Ages -- "Lore (2): Draw one card." A Relic (no energy pool of its own -- paid from the
// controlling Magi's energy automatically by power.ts), same effect shape as Agovo/Rayje's
// Construct.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Book of Ages', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Lore') return;
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
  },
});
