// Flambit -- "Immolate: Discard Flambit from play. Choose a Magi and a Creature. Move up to
// three energy from the chosen Magi to the chosen Creature." Two independent typed slots (any
// Magi, any Creature -- neither restricted to a side). "Up to three" is implemented as moving
// a real player choice via `powerAmountChoices` (registry.ts, task #532, 2026-07-26). It used to
// move min(available, 3) unconditionally, on the since-falsified note that "this engine has no
// existing mechanism for a player to voluntarily move less than the offered maximum" -- that
// mechanism now exists and eleven cards share it.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById, findInPlayById } from '../targeting.js';
import { discardFromPlay, rearrangeEnergy } from '../effects.js';

registerCardEffect('Flambit', {
  // Capped at the printed 3 rather than the source Magi's actual energy: the Magi here is a SLOT
  // pick, and powerAmountChoices only receives `chosenTargetId`, never chosenSlotIds. resolvePower
  // re-clamps against the real energy, so an over-large pick is simply reduced.
  powerAmountChoices: (state, cardDb, playerId, powerName) =>
    powerName === 'Immolate'
      ? [{ id: 'move', prompt: 'Immolate: move how much energy from the chosen Magi? (0-3)', min: 0, max: 3 }]
      : undefined,
  powerTargetSlots: (state, cardDb) => [
    {
      label: 'Choose a Magi',
      pool: (s) => allMagiInPlay(s),
      min: 1,
      max: 1,
    },
    {
      label: 'Choose a Creature',
      pool: (s, db) => allCreaturesInPlay(s, db),
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Immolate') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const magiId = slots[0]?.[0];
    const creatureId = slots[1]?.[0];
    if (!magiId || !creatureId) return;

    const magi = findCreatureOrMagiById(ctx.state, magiId);
    if (!magi) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    // The chosen Creature could have BEEN Flambit itself -- already gone from play now.
    const creature = findInPlayById(ctx.state, creatureId);
    if (!creature || ctx.cardDb.get(creature.definitionKey)?.card_type !== 'Creature') return;

    // Task #532: "up to three" is a player choice of 0-3, not 3. `?? cap` keeps the old maximum as
    // the fallback when no amount was supplied, so this is safe before the UI collects one.
    const cap = Math.min(3, magi.currentEnergy ?? 0);
    const amount = Math.max(0, Math.min(ctx.chosenAmounts?.['move'] ?? cap, cap));
    if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, magi, creature, amount, ctx.rng);
  },
});
