// Izmer -- both halves:
//   Power "Abrade: Choose an opposing Creature. Discard one energy from the chosen Creature."
//   Effect "Sandomancy: Whenever you play a d'Resh Relic, choose a Creature. Discard one energy
//   from the chosen Creature." Built 2026-07-20 (playtest bug report: "Sandomancy not firing" --
//   the effect had simply never been implemented, only the Power half was). No "opposing"
//   qualifier on the printed text -- either side's Creatures are legal targets, same shape as
//   Gumph's Night's Shade. Real choice via the generic pendingTargetChoice/resolveTargetChoice
//   family (registry.ts), broadcast via the generic onPlay hook (effects.ts's
//   broadcastCardEnteredPlay already calls every in-play card's onPlay for every card entering
//   play on either side -- Izmer just filters for its own controller playing a d'Resh Relic).

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, allCreaturesInPlay, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const SANDOMANCY_PENDING = 'izmerSandomancyPending';

registerCardEffect('Izmer', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Abrade') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) return;
    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Relic') return;
    if (!playedDef.regions.includes("d'Resh")) return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, SANDOMANCY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SANDOMANCY_PENDING)) return undefined;
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Izmer's Sandomancy: choose a Creature to discard 1 energy from", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, SANDOMANCY_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 1, 'effect', undefined, rng);
  },
});
