// Crystal Lascinth -- two clauses. Built task #48, 2026-07-18, the Underneath region pass --
// Category B.
//   "Resistance: Crystal Lascinth is not affected by Core Spells or Powers." -> registry.ts's
//   `blocksPowerEffectBySourceRegion` (verbatim Hunter Jile / Magor shape), checked by effects.ts
//   for cause === 'power' (Spells never execute), resolving the acting Power's source via
//   state.currentAction.sourceDefinitionKey.
//   "Spines: Whenever one of your Underneath Creatures is attacked, remove one energy from the
//   attacking Creature before energy is removed. Remove an additional energy if the attacking
//   Creature is Core." -> `onBeforeEnergyRemoved` (Crown of Grath's exact broadcast shape): when the
//   defender is one of self's controller's Underneath Creatures, discard 1 from the attacker (2 if
//   the attacker is Core), timed "before energy is removed" so it counts toward this same combat.
//
// Ashio's Weave Twist (2026-07-24): both "Core" references above are Crystal Lascinth's OWN
// printed text, so under Ashio they mean its own region (Underneath) instead -- see targeting.ts's
// ashioAdjustedRegion doc comment. ("Underneath Creatures" in Spines is the DEFENDER filter, not a
// "Core" reference, so untouched.)

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { ashioAdjustedRegion, effectiveRegions } from '../targeting.js';

registerCardEffect('Crystal Lascinth', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Resistance owns
  // blocksPowerEffectBySourceRegion; Spines owns onBeforeEnergyRemoved.
  effectHooks: {
    Resistance: ['blocksPowerEffectBySourceRegion'],
    Spines: ['onBeforeEnergyRemoved'],
  },
  blocksPowerEffectBySourceRegion: (state, cardDb) => {
    const sourceKey = state.currentAction?.sourceDefinitionKey;
    if (sourceKey === undefined) return false;
    return cardDb.get(sourceKey)?.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Underneath'])) ?? false;
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return; // "one of YOUR ... Creatures"
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Underneath')) return; // "Underneath Creatures"
    const attackerIsCore = effectiveRegions(ctx.state, ctx.cardDb, ctx.attacker).includes(ashioAdjustedRegion(ctx.state, ctx.cardDb, 'Core', ['Underneath']));
    discardEnergy(ctx.state, ctx.cardDb, ctx.attacker, attackerIsCore ? 2 : 1, 'effect', undefined, ctx.rng);
  },
});
