// Kyroll -- both printed pieces:
//   "Drift Back: If Kyroll is defeated in an attack while frozen, return it to its owner's hand."
//   FIXED #536 C6e, 2026-07-27. This used to be modeled as "whenever Kyroll is discarded from play
//   at zero energy while frozen", on the stated grounds that the hook's cause "covers both combat
//   and Power/Effect defeats, not just combat specifically -- same documented limitation as Brog's
//   Fertilize". That justification was STALE in both directions: the hook has carried `source`
//   since task #32 (2026-07-16), and brog.ts had already been fixed to check
//   `source !== 'combat'`. Kyroll was left behind, so a Spell or Power draining a frozen Kyroll to
//   zero wrongly bounced it to hand for free. "In an attack" means source === 'combat'.
//   "Smash (4): Choose a frozen Creature in play. Discard the chosen Creature from play."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { removeFromZone, addToZone } from '../zones.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Kyroll', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => isFrozen(state, cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Smash') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!isFrozen(ctx.state, ctx.cardDb, target)) return;
    const owner = ctx.state.players.get(target.controllerId);
    if (!owner) return;
    discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source) => {
    if (discarded.instanceId !== self.instanceId) return;
    if (cause !== 'zero-energy') return; // "DEFEATED", not specifically discarded
    if (source !== 'combat') return; // "in an ATTACK"
    if (!isFrozen(state, cardDb, self)) return;
    const owner = state.players.get(discardedOwnerId);
    if (!owner) return;
    const card = removeFromZone(owner, 'discardPile', self.instanceId);
    addToZone(owner, 'hand', card);
  },
});
