// Rehlya -- "Counterweave: Whenever one of your Weave Creatures is attacked, move one energy from
// the attacking Creature to the defending Creature before energy is removed." Real energy move ->
// onBeforeEnergyRemoved, same shape as the shipped Weave family.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Rehlya', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Weave')) return;
    rearrangeEnergy(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 1, ctx.rng);
  },
});
