// Wellisk -- "Dream Barrier: Immediately after a Creature is played, you may discard Wellisk from
// play. If you do so, also discard the Creature played and all energy used to play the Creature."
// Broadcast onPlay reactor for EITHER side's Creature plays -- "all energy used to play the
// Creature" is flavor text for the normal outcome of discarding it (its energy leaves with it),
// not a separate refund/tracking mechanism.
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice`. The just-played
// Creature is remembered via an embedded-id permanent tag (same technique as Ahron/Gloves of
// Crystal/Hubram/Magam's Ring/Reef Hyren/Skullek in this same batch) since the resolve call has no
// target parameter.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { findInPlayById } from '../targeting.js';

const PENDING_PREFIX = 'wellisksDreamBarrierPending:';

function pendingPlayedId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return tag.slice(PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Wellisk', {
  onPlay: (state, cardDb, played, self) => {
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${played.instanceId}`);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    const playedId = pendingPlayedId(self);
    if (playedId === undefined) return undefined;
    if (!findInPlayById(state, playedId)) return undefined;
    return {
      prompt: 'Wellisk\'s Dream Barrier: discard Wellisk from play to also discard the Creature just played?',
      yesLabel: 'Discard both',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const playedId = pendingPlayedId(self);
    if (playedId !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${playedId}`);
    if (!chosenBoolean || playedId === undefined) return;
    const played = findInPlayById(state, playedId);
    const selfOwner = state.players.get(self.controllerId);
    if (!played || !selfOwner) return;
    discardFromPlay(state, cardDb, selfOwner, self.instanceId, undefined, undefined, rng);
    const playedOwner = state.players.get(played.controllerId);
    if (playedOwner) discardFromPlay(state, cardDb, playedOwner, played.instanceId, undefined, undefined, rng);
  },
});
