// Frusk -- both printed effects:
//   "Magic Scent: Whenever an opposing player plays a Spell or Relic, draw a card."
//   "Weave: Whenever Frusk attacks or is attacked, before energy is removed, you may move one
//   energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { applyWeave } from './weave.js';

registerCardEffect('Frusk', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Magic Scent is the opponent-Spell/Relic
  // draw reactor; Weave is the move hook + `weaveConfig`.
  effectHooks: {
    'Magic Scent': ['onPlay'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return; // "an OPPOSING player"
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Spell' && playedDef?.card_type !== 'Relic') return;
    const player = state.players.get(self.controllerId);
    if (player) drawCards(state, cardDb, player, 1);
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
});
