// Olabra's Staff -- "Training Drills (0): If you have five or more Bograth Creatures in play,
// add one energy to each of your Bograth Creatures. Skip your Attack step. You may only use this
// Power before your Attack step." First card using GameState's new skipAttackPhaseThisTurn flag.
//
// Bograth-count-helper sweep (Bograth-cluster follow-up, 2026-07-21): the THRESHOLD check now
// reads targeting.ts's effectiveBograthCreatureCount (so Bog Stench's virtual +2 and Emlob's +3
// can push it over 5), but the energy-ADD loop still iterates real Creatures only (`ownBograth`)
// -- a virtual bonus creature doesn't exist to add energy to.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveBograthCreatureCount, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect("Olabra's Staff", {
  legalPhases: ['prs1'],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Training Drills') return;
    if (effectiveBograthCreatureCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId) < 5) return;

    const ownBograth = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter((c) =>
      effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, 'Bograth'))
    );
    for (const creature of ownBograth) {
      addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
    }
    ctx.state.skipAttackPhaseThisTurn = true;
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (The threshold check above uses
  // effectiveBograthCreatureCount, a fixed Bograth-only counter unrelated to target filtering --
  // out of scope, same as every other count-only clause.)
  specifiedTargetRegions: () => ['Bograth'],
});
