// Iceberg Hyren -- "The Rest Is Unseen: The first time Iceberg Hyren is attacked, you may discard
// one energy from your Magi. If you do, add nine energy to Iceberg Hyren before energy is removed.
// This Effect cannot be copied." One-time-ever (not once-per-turn) guard via a PERMANENT tag.
// "Cannot be copied" needs no code -- this codebase's copy-a-Power mechanism (copiedPowers.ts)
// only ever copies printed Powers, never passive/triggered Effects like this one.
//
// Real choice (task #40-3, 2026-07-17, player-choice-default retrofit, Group 3): "may" is now a
// real yes/no via `pendingPreCombatTargetChoice` with a single-candidate pool (the controller's
// own Magi -- the only possible "target," so picking it in the UI's dropdown means yes, Skip means
// no; same single-item-pool-as-yes/no shape used throughout this group). No resolution supplied
// falls back to the old always-take default (a near-always-good trade, 1 for 9).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag } from '../durationTags.js';
import type { PreCombatTargetResolution } from '../combat.js';

const ALREADY_TRIGGERED = 'icebergHyrenAlreadyTriggered';

registerCardEffect('Iceberg Hyren', {
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker, isDefender) => {
    if (!isDefender) return undefined;
    if (self.tags.has(ALREADY_TRIGGERED)) return undefined;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return undefined;
    return { prompt: "Iceberg Hyren's The Rest Is Unseen: discard one energy from your Magi to add nine to Iceberg Hyren?", pool: [magi] };
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender || ctx.defender.instanceId !== self.instanceId) return;
    if (self.tags.has(ALREADY_TRIGGERED)) return;
    const magi = ctx.state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return;

    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
    const resolution = resolutions?.[self.instanceId];
    const takeIt = resolution !== undefined ? !('skip' in resolution) : true; // unchanged auto-take default

    if (takeIt) {
      addPendingChoiceTag(self, ALREADY_TRIGGERED);
      discardEnergy(ctx.state, ctx.cardDb, magi, 1, 'effect', self.controllerId, ctx.rng);
      addEnergy(ctx.state, ctx.cardDb, self, 9, 'effect');
    }
  },
});
