// Gremm's Hammer -- two Powers. Built task #48, 2026-07-18, the Underneath region pass -- Category B.
//   "Build: Add two Pound Counters to Gremm's Hammer." -> a plain counter bump on the generic
//   `counters` field (task #50f); needs no target (powerTargets returns undefined for Build).
//   "Break: Choose any one non-Underneath Creature in play. Discard energy from the chosen Creature
//   equal to the number of Pound counters on Gremm's Hammer. Discard Gremm's Hammer from play." ->
//   powerTargets scoped (for Break only) to non-Underneath Creatures; resolvePower discards that many
//   energy from the chosen Creature, then discards Gremm's Hammer.

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions, findInPlayById, regionForTargetFilter } from '../targeting.js';

registerCardEffect("Gremm's Hammer", {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb, _playerId, powerName) => {
    if (powerName !== 'Break') return undefined; // Build needs no target
    return allCreaturesInPlay(state, cardDb).filter(
      (c) => !effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Underneath'))
    );
  },
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Build') {
      ctx.source.counters.pound = (ctx.source.counters.pound ?? 0) + 2;
      return;
    }
    if (ctx.powerName !== 'Break') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Underneath'))) return; // "non-Underneath"
    const pound = ctx.source.counters.pound ?? 0;
    if (pound > 0) discardEnergy(ctx.state, ctx.cardDb, target, pound, 'power', undefined, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Underneath'],
});
