// Quallon's Quest (Weave Spell, cost 2) -- "Discard a Weave Creature from your hand. Reveal a number
// of cards from the top of your deck equal to the Creature's starting energy. Choose up to two
// Creatures from the revealed cards and add them to your hand. Shuffle the rest of the revealed
// cards into your deck."
//
// Weave + Universal Spell pass, Category C (2026-07-27).
//
// NO new reveal mechanism was needed, and that is the whole point of this file. The pass's own
// scoping notes had this down as "Spell-side deckTopReveal: registry + play.ts + Play.tsx" --
// registry.ts's `deckTopReveal` really is Power-only, with no Spell-side wiring anywhere. But
// Dark Portents (Core Spell pass, 2026-07-21) already solved exactly this shape without touching
// that mechanism, and its trick applies verbatim:
//
//   Nothing is ever REMOVED from the deck to "reveal" it. The top N are read in place
//   (`deck.slice(0, N)`, deck[0] is the top -- confirmed convention), their ids stashed as tags on
//   this Spell's own already-discarded instance, and only the CHOSEN cards are actually moved. The
//   revealed-but-unchosen cards therefore need no putting back: they never left.
//
// That also makes the last clause free. "Shuffle the rest of the revealed cards into your deck" is
// satisfied by shuffling the deck once at the end -- the unchosen cards are already in it, and the
// shuffle is what randomises their position.
//
// The pick reuses `pendingMultiTargetChoice` (Group 6, already wired in Play.tsx), which is why
// this card needs no UI work either. `findPendingMultiTargetChoices` scans discard piles as well as
// boards, which is what lets a one-shot Spell surface a choice AFTER it has been discarded -- the
// same confirmed pattern Bombard/Muck Rain/Trulbble! and Dark Portents all ride on.
//
// "Up to two" is a genuine `minCount: 0` optional choice, not an auto-pick of the best two.

import { registerCardEffect } from './registry.js';
import { discardFromHand } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { addPendingChoiceTag, addPermanentTag, removePermanentTag } from '../durationTags.js';
import { shuffleDeck } from '../zones.js';
import { defaultRng } from '../rng.js';
import { regionForTargetFilter } from '../targeting.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING = 'quallonsQuestAwaitingPick';
const REVEALED_PREFIX = 'quallonsQuestRevealed:';

function revealedIds(self: CardInstance): string[] {
  return [...self.tags].filter((t) => t.startsWith(REVEALED_PREFIX)).map((t) => t.slice(REVEALED_PREFIX.length));
}

registerCardEffect("Quallon's Quest", {
  spellHandDiscardCost: {
    count: 1,
    filter: (state, cardDb, _playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, 'Weave'));
    },
  },
  resolveSpell: (ctx) => {
    const id = (ctx.chosenHandCardIds ?? [])[0];
    if (id === undefined) return;
    const creature = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
    if (!creature) return;
    const def = ctx.cardDb.get(creature.definitionKey);
    // Re-validated at resolution rather than trusted from the UI, same as every other cost-filtered
    // Spell in this pass.
    if (def?.card_type !== 'Creature' || !def.regions.includes(regionForTargetFilter(ctx.state, 'Weave'))) return;

    // Starting energy read BEFORE the discard -- printedStartingEnergy needs the live instance.
    const count = effectiveStartingEnergy(ctx.state, ctx.cardDb, creature);
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [id], undefined, ctx.rng);
    if (count <= 0) return; // a 0-energy Weave Creature reveals nothing; nothing to choose

    const revealed = ctx.controllingPlayer.deck.slice(0, count);
    if (revealed.length === 0) return;
    for (const card of revealed) addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${REVEALED_PREFIX}${card.instanceId}`);
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, AWAITING);
    addPendingChoiceTag(ctx.source, AWAITING);
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING)) return undefined;
    const owner = state.players.get(self.controllerId);
    if (!owner) return undefined;
    const ids = revealedIds(self);
    // Looked back up fresh from the deck: the pool is only the revealed cards still there, and only
    // the Creatures among them.
    const pool = owner.deck
      .filter((c) => ids.includes(c.instanceId) && cardDb.get(c.definitionKey)?.card_type === 'Creature')
      .map((c) => c.instanceId);
    if (pool.length === 0) {
      // Nothing pickable -- still shuffle, since the reveal happened.
      return { prompt: "Quallon's Quest revealed no Creatures", pool: [], minCount: 0, maxCount: 0, optional: true };
    }
    return {
      prompt: "Quallon's Quest: choose up to two revealed Creatures to add to your hand",
      pool,
      minCount: 0,
      maxCount: 2,
      optional: true,
    };
  },
  resolveMultiTargetChoice: (state, _cardDb, self, chosenInstanceIds, rng) => {
    if (!self.tags.has(AWAITING)) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const ids = revealedIds(self);
    // "up to two" -- a caller that declines takes nothing, which is a legal line of play here (unlike
    // the Group 6 cards, whose own text is mandatory and which auto-pick instead).
    const chosen = (chosenInstanceIds ?? []).filter((id) => ids.includes(id)).slice(0, 2);
    for (const id of chosen) {
      const index = owner.deck.findIndex((c) => c.instanceId === id);
      if (index === -1) continue;
      const [card] = owner.deck.splice(index, 1);
      owner.hand.push(card!);
    }
    // "Shuffle the rest of the revealed cards into your deck" -- they never left it, so one shuffle
    // is the whole clause. See the header.
    //
    // `rng` is threaded through `resolveMultiTargetChoice` for exactly this (added with this card).
    // Falling back to `defaultRng` would silently re-break the save/replay determinism the
    // rng-threading sweep closed, so the fallback is deliberately explicit and documented here
    // rather than hidden in the hook's default.
    shuffleDeck(owner, rng ?? defaultRng);
    removePermanentTag(self, AWAITING);
    for (const id of ids) removePermanentTag(self, `${REVEALED_PREFIX}${id}`);
  },
});
