// Grakanden -- "Grounding: Once per turn, as an opposing player plays a Spell, you may discard
// three energy from Grakanden to cancel all effects of that Spell. Return the Spell to that
// player's hand at the end of the turn." Built task #41, 2026-07-17, the "react-and-negate window"
// architecture project, Checkpoint A -- at the time, "cancel all effects" was moot (Spells had no
// effect execution in this engine at all), so only the delayed return-to-hand was buildable.
// REWORKED task #50-4 rules-fidelity fix (2026-07-20): once resolveSpell/spellTargets landed (task
// #50, this session), the old "let it resolve normally, then bounce it back" shape became WRONG --
// a negated Shooting Star would still add its energy. Now uses registry.ts's real
// offersSpellNegation/resolveSpellNegation, which skips the Spell's resolveSpell entirely. See
// docs/plans/react-and-negate-window-plan.md for the original design.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, addPermanentTag, hasDurationTag, RETURN_TO_HAND_AT_END_OF_TURN } from '../durationTags.js';

const USED_THIS_TURN = 'grakandenUsedThisTurn';

registerCardEffect('Grakanden', {
  offersSpellNegation: (state, cardDb, self, playedDef, playerId) => {
    if (playerId === self.controllerId) return false; // "an OPPOSING player"
    if (hasDurationTag(self, USED_THIS_TURN)) return false; // "Once per turn"
    return (self.currentEnergy ?? 0) >= 3;
  },
  resolveSpellNegation: (state, cardDb, self, negatedSpell, _currentTargetId, rng) => {
    addDurationTag(state, cardDb, self, USED_THIS_TURN, state.turnNumber);
    discardEnergy(state, cardDb, self, 3, undefined, undefined, rng);
    addPermanentTag(state, cardDb, negatedSpell, RETURN_TO_HAND_AT_END_OF_TURN);
  },
});
