// Robe of Vines -- "Strengthen: Whenever you play a Naroom Creature, add one additional energy to
// it." Built task #45, 2026-07-18, the Naroom region pass -- direct reuse of Alpine Xamf / Forest
// Wudge's own "Strengthen" onPlay-broadcast pattern (self decides relevance).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Robe of Vines', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Creature' || !def.regions.includes('Naroom')) return;
    addEnergy(state, cardDb, played, 1, 'effect');
  },
});
