// Furok Protector -- "Thick Coat: When you play Furok Protector, choose an opposing Magi. Set
// Furok Protector's energy equal to the chosen Magi's energize." Simplified to "the" opposing
// Magi -- in this engine's 2-player games there's only ever one.
// "Resistance: Furok Protector is not affected by Core Spells and Powers." Built task #43,
// 2026-07-18, the Nar region pass -- Category A, exact `blocksPowerEffectBySourceRegion` reuse,
// byte-for-byte the same shape as Chaos Flugg's own Resistance clause (chaosFlugg.ts).
//
// Ashio's Weave Twist (2026-07-24): "Core" above is Furok Protector's OWN printed text, so under
// Ashio it means its own region (Nar) instead -- see targeting.ts's ashioAdjustedRegion doc comment.

import { registerCardEffect } from './registry.js';
import { restoreEnergy } from '../effects.js';
import { ashioAdjustedRegion, opposingMagi } from '../targeting.js';

registerCardEffect('Furok Protector', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Thick Coat is the on-play energize-
  // match; Resistance is the Core-Spells/Powers immunity.
  effectHooks: {
    'Thick Coat': ['onPlay'],
    Resistance: ['blocksPowerEffectBySourceRegion'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    const opponentMagi = opposingMagi(state, cardDb, self.controllerId)[0];
    if (!opponentMagi) return;
    const magiDef = cardDb.get(opponentMagi.definitionKey);
    restoreEnergy(state, cardDb, self, magiDef?.energize ?? 0);
  },
  blocksPowerEffectBySourceRegion: (state, cardDb) => {
    const sourceKey = state.currentAction?.sourceDefinitionKey;
    if (sourceKey === undefined) return false;
    const sourceDef = cardDb.get(sourceKey);
    if (!sourceDef) return false;
    return sourceDef.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Nar']));
  },
});
