// Magma Armor -- "Defense: Whenever a Creature attacks your Magi directly, add two energy to that
// Magi before energy is removed." A direct self-buff to the defending Magi (same pattern as
// Brannix's self-boost), added before lock-in so the extra energy is present when the Magi takes
// this attack's damage.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Magma Armor', {
  onAttack: (ctx, self) => {
    if (ctx.defender !== null) return;
    if (ctx.defendingPlayer.playerId !== self.controllerId) return;
    const magi = ctx.defendingPlayer.activeMagi;
    if (magi) addEnergy(ctx.state, ctx.cardDb, magi, 2, 'effect');
  },
});
