// Abwyn's Gift (Spell) -- "If you have a Creature in play, choose any one Creature in play. Discard
// the chosen Creature from play. Return any one of your Creatures in play to your hand, discarding
// all of that Creature's energy." Two INDEPENDENT single picks -- registry.ts's new
// spellSecondTargets (first user). "If you have a Creature in play" is the castability gate for the
// whole Spell (no legal second target otherwise); spellTargets returning [] when the caster has no
// Creature makes it correctly unplayable via the normal "needs a target but none available" path.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, returnToHand } from '../effects.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';

registerCardEffect("Abwyn's Gift", {
  // "Ummm...NO!" (task #565): this Spell reaches effects.ts#discardFromPlay on a single
  // chosenTargetId Creature, so it is answerable. See registry.ts for the flag contract.
  spellSpecificallyDiscardsCreature: true,
  spellTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).length > 0 ? allCreaturesInPlay(state, cardDb) : [],
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => c.instanceId !== firstChosenId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined || ctx.chosenSecondTargetId === undefined) return;
    if (ctx.chosenTargetId === ctx.chosenSecondTargetId) return;
    const discardTarget = findInPlayById(ctx.state, ctx.chosenTargetId);
    const returnTarget = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (!discardTarget || ctx.cardDb.get(discardTarget.definitionKey)?.card_type !== 'Creature') return;
    if (!returnTarget || returnTarget.controllerId !== ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(returnTarget.definitionKey)?.card_type !== 'Creature') return;

    const owner = ctx.state.players.get(discardTarget.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, discardTarget.instanceId, undefined, undefined, ctx.rng);

    // The return target can never BE the discard target (chosenTargetId !== chosenSecondTargetId is
    // checked above), but discarding the first Creature could still ripple into the second one being
    // gone too (e.g. a reactive hook) -- re-verify it's still in play before returning it (same
    // "stillThere" re-check Muck Vinoc's Grapple already uses for the analogous self-discard case).
    const stillThere = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (stillThere) returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, stillThere.instanceId);
  },
});
