// Galiant -- both printed pieces:
//   "Riding Tail: Your largest Creature in play gains energy equal to the current energy on the
//   smallest opposing Creature in play." No target -- both ends computed automatically via
//   largestCreatureControlledBy/smallestOf.
//   "Invulnerability: Galiant loses one less energy in attacks." (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { largestCreatureControlledBy, opposingCreatures, smallestOf } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Galiant', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Riding Tail') return;
    const largest = largestCreatureControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (!largest) return;
    const smallestOpposing = smallestOf(opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId));
    if (!smallestOpposing) return;

    const amount = smallestOpposing.currentEnergy ?? 0;
    if (amount > 0) addEnergy(ctx.state, ctx.cardDb, largest, amount, 'power');
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
});
