// Vrak -- "Really Really Big: When you play Vrak, add six energy to it. If Vrak is your only Nar
// Creature in play, discard it." The second clause is a continuous/standing check -- post-playtest
// correctness pass, P4 (2026-07-12), via registry.ts's standingConditionMet hook
// (effects.ts's sweepStandingConditions).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';

registerCardEffect('Vrak', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Only Really Really Big is mapped;
  // the second (unnamed) "if only Nar Creature, discard self" standing check has no name to
  // key on and falls through to whole-card grant.
  effectHooks: {
    'Really Really Big': ['onPlay'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    addEnergy(state, cardDb, self, 6, 'effect');
  },
  standingConditionMet: (state, cardDb, self) => {
    const ownNarCreatures = creaturesControlledBy(state, cardDb, self.controllerId).filter((c) =>
      effectiveRegions(state, cardDb, c).includes('Nar')
    );
    return ownNarCreatures.length === 1 && ownNarCreatures[0]!.instanceId === self.instanceId;
  },
});
