// Forest Wudge -- two effects:
//   "Strengthen: Whenever an opponent plays a Creature, add one energy to Forest Wudge. If the
//   Creature played is Naroom, add an additional energy to Forest Wudge." (broadcast -- the first
//   real motivator for widening onPlay beyond a self-only hook)
//   "Home Turf: When you play Forest Wudge, if any opposing Magi is Naroom or Naroom Shadow, draw
//   a card." (self-trigger)
//
// "Naroom Shadow" has no corresponding region or Magi name anywhere in the card database (checked
// 2026-07-10) -- treated as already covered by the plain "Naroom" region check, since there's
// nothing else to distinguish it from.

import { registerCardEffect } from './registry.js';
import { addEnergy, drawCards } from '../effects.js';
import { opposingMagi } from '../targeting.js';

registerCardEffect('Forest Wudge', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Both Effects live in a single onPlay
  // body -- Home Turf is the self-play card-draw branch (gated on played === self); Strengthen
  // is the opponent-play energy-add branch. Listing both under 'onPlay' means a Taglat pick of
  // either includes the shared body; the internal self-vs-opposing gates keep the wrong branch
  // from firing (Home Turf only fires when Forest Wudge itself is played, which doesn't happen
  // for a Taglat-copied grant since self is Taglat).
  effectHooks: {
    Strengthen: ['onPlay'],
    'Home Turf': ['onPlay'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) {
      const opponentMagi = opposingMagi(state, cardDb, self.controllerId)[0];
      const magiDef = opponentMagi ? cardDb.get(opponentMagi.definitionKey) : undefined;
      if (magiDef?.regions.includes('Naroom')) {
        const player = state.players.get(self.controllerId);
        if (player) drawCards(state, cardDb, player, 1);
      }
      return;
    }

    if (played.controllerId === self.controllerId) return; // Strengthen is opponent-plays only
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Creature') return;
    addEnergy(state, cardDb, self, playedDef.regions.includes('Naroom') ? 2 : 1, 'effect');
  },
});
