// Scarletsong Lilt (Spell, Paradwyn, cost 2) -- "Choose an opposing Creature and attach
// Scarletsong Lilt to it. As the chosen Creature loses energy in an attack, remove two energy from
// the Creature's Magi. Discard Scarletsong Lilt from play at the beginning of your turn."
// spellStaysInPlay + attachCard (Sunburn/Volt Shield precedent); the combat drain uses the new
// drainsHolderMagiOnCombatLoss hook (registry.ts, combat.ts#applyCombatCounterLoss); the
// self-discard uses ticksWhileAttached (Tar Hyren's Cling precedent, which fires every turn --
// gated here to only the CASTER's own turn start, matching "at the beginning of YOUR turn").

import { registerCardEffect } from './registry.js';
import { opposingCreatures, findCreatureOrMagiById } from '../targeting.js';
import { attachCard, detachCard } from '../attachedCards.js';
import { moveToDiscardPile } from '../zones.js';

registerCardEffect('Scarletsong Lilt', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId ?? '');
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    attachCard(target, ctx.source);
  },
  drainsHolderMagiOnCombatLoss: () => 2,
  ticksWhileAttached: (state, cardDb, self, holder) => {
    if (state.activePlayerId !== self.controllerId) return;
    const detached = detachCard(holder, self.instanceId);
    if (!detached) return;
    const owner = state.players.get(detached.ownerId);
    if (owner) moveToDiscardPile(state, owner, detached);
  },
});
