// Lasada -- printed text: "Warning: If Lasada is defeated, draw three cards." The simplest
// possible shape in the onOwnMagiDefeated family. Distinct card from "Lasada, Emissary" (her
// Alternate), which has its own separate file (lasadaEmissary.ts).

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Lasada', {
  onOwnMagiDefeated: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    drawCards(state, cardDb, player, 3);
  },
});
