// Shockwave (Spell) -- "Choose any one Creature in play. Discard the chosen Creature from play."
// Targeted at ANY Creature (either side). resolveSpell runs under state.currentAction (source
// 'spell', actor set by play.ts), so discardFromPlay's opposing-caused checks (canBeDiscardedFromPlay,
// preventsDiscardOf) apply exactly like a Power's discard would against an opponent's Creature.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Shockwave', {
  // "Ummm...NO!" (task #565): this Spell reaches effects.ts#discardFromPlay on a single
  // chosenTargetId Creature, so it is answerable. See registry.ts for the flag contract.
  spellSpecificallyDiscardsCreature: true,
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const owner = ctx.state.players.get(target.controllerId);
    if (!owner) return;
    discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
