// Vellup -- "Flock: When you play Vellup, you may search through your deck for another Vellup.
// Show it to your opponents and put it into your hand. Shuffle your deck."
//
// The "may" choice is still auto-taken whenever a legal target exists (out of scope for Phase
// 4c). "Another Vellup" is now a real pending choice (Phase 4c, 2026-07-11, registry.ts's
// pendingTargetChoice/resolveTargetChoice) instead of the earlier "first eligible in deck array
// order" simplification. "Show to your opponents" has no distinct game-state effect beyond
// moving the card to hand, so isn't separately modeled.

import { registerCardEffect } from './registry.js';
import { searchDeck } from '../effects.js';
import { creatureType } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import type { Rng } from '../rng.js';

const FLOCK_PENDING = 'vellupFlockPending';

function flockPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.deck.filter((c) => creatureType(cardDb, c.definitionKey) === 'Vellup');
}

registerCardEffect('Vellup', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    if (flockPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, FLOCK_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(FLOCK_PENDING)) return undefined;
    const pool = flockPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Vellup's Flock: choose another Vellup in your deck to add to hand", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng?: Rng) => {
    removePermanentTag(self, FLOCK_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    if (flockPool(state, cardDb, self).some((c) => c.instanceId === chosenInstanceId)) {
      searchDeck(state, player, [chosenInstanceId], rng);
    }
  },
});
