// Iximin -- "Spite: If Iximin is defeated in an attack, discard three energy from the Creature
// that defeated it." Reacts to its own defeat while defending -> afterCombat (deliberately still
// fires for a just-defeated defender, per combat.ts's own doc comment).

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Iximin', {
  afterCombat: (ctx, outcome, self) => {
    if (!ctx.defender || ctx.defender.instanceId !== self.instanceId) return;
    if (outcome.defenderSurvived) return;
    discardEnergy(ctx.state, ctx.cardDb, ctx.attacker, 3, 'effect', self.controllerId, ctx.rng);
  },
});
