// Weebat -- "Grounded: Whenever Weebat is attacked, add one energy to Weebat before energy is
// removed. If the attacking Creature is Naroom, add three additional energy to Weebat before
// energy is removed."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Weebat', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    const isNaroom = effectiveRegions(ctx.state, ctx.cardDb, ctx.attacker).includes('Naroom');
    addEnergy(ctx.state, ctx.cardDb, self, isNaroom ? 4 : 1, 'effect');
  },
});
