// Ancestral Flute -- "Song of the Family: Choose any one Creature in play. Discard Ancestral
// Flute from play. Search your deck for up to two copies of the chosen Creature. Show the cards
// to your opponents, and put them into your hand." "Show" is cosmetic. The deck-search filter
// can't depend on the separately-chosen target (registry.ts's deckSearch.filter has no access to
// chosenTargetId), so it offers the whole deck and resolvePower validates the name match --
// same "offer broad, resolve validates" pattern as Helgrem/Raega.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay, searchDeck } from '../effects.js';

registerCardEffect('Ancestral Flute', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  deckSearch: { count: 'any' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Song of the Family') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const targetName = ctx.cardDb.get(target.definitionKey)?.name;

    const ids = (ctx.chosenDeckSearchIds ?? []).slice(0, 2);
    for (const id of ids) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      if (!card || ctx.cardDb.get(card.definitionKey)?.name !== targetName) return;
    }

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    searchDeck(ctx.state, ctx.controllingPlayer, ids, ctx.rng);
  },
});
