// Redream (Spell) -- "Search your discard pile, then your deck for one copy of each of your
// Magi's starting cards. Add those cards to your hand. You can only play Redream once per turn. If
// your Magi is not d'Resh, discard a card from your hand for each card you added to your hand with
// Redream."
//
// The search half is a near-exact match for setup.ts's tutorStartingCards -- its eligibility gate
// (starting names UNION impliedStartingCardNames UNION alternateStartingCardNames UNION
// bonusStartingCardNames, minus category entries) is precisely "your Magi's starting cards," and
// its body already does "discard pile first, then deck" in that exact order. resolveSpell computes
// the SAME allowed-name set setup.ts computes internally and calls tutorStartingCards directly with
// all of them -- a real 1:1 reuse, not an adaptation.
//
// The discard half follows the project owner's explicit sequencing spec (2026-07-20): do NOT
// determine a discard count before the search runs, and do NOT resolve search+discard as one
// simultaneous choice (a player could legitimately want to discard one of the cards Redream just
// added, so the discard pool must be the POST-search hand, and the count must be the ACTUAL number
// of cards tutorStartingCards found -- its return value's length, not the requested-name count,
// since some starting cards may already be unavailable). Sequencing: (1) search unconditionally,
// capture addedCount; (2) if the Magi is d'Resh or addedCount is 0, stop; (3) otherwise arm a
// genuine SEPARATE follow-up choice (pendingMultiTargetChoice, minCount === maxCount === addedCount,
// pool = the player's full CURRENT hand post-search) -- the same "mutate now, arm a distinct pending
// choice resolved by a later UI round-trip" shape already used by Rayje's Wily, not a same-tick
// simultaneous resolution. Redream itself is discarded normally right after resolveSpell returns
// (no spellStaysInPlay), and the pending-choice scan still finds it sitting in the discard pile --
// same "still-findable after resolving" shape Heat of Day's own pending choice relies on.

import { registerCardEffect } from './registry.js';
import { tutorStartingCards, impliedStartingCardNames, alternateStartingCardNames } from '../setup.js';
import { isStartingCategory } from '../startingCards.js';
import { discardFromHand } from '../effects.js';
import { addDurationTag, hasDurationTag, removeDurationTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const AWAITING_DISCARD = 'redreamAwaitingDiscard';
const USED_THIS_TURN = 'redreamUsedThisTurn';

function allowedStartingNames(state: GameState, cardDb: CardDatabase, playerId: string): string[] {
  const player = state.players.get(playerId);
  const magi = player?.activeMagi;
  if (!player || !magi) return [];
  const def = cardDb.get(magi.definitionKey);
  if (!def) return [];
  return [
    ...new Set([
      ...(def.starting ?? []),
      ...impliedStartingCardNames(cardDb, def, player),
      ...alternateStartingCardNames(cardDb, def, player),
      ...magi.bonusStartingCardNames.filter((name) => !isStartingCategory(name)),
    ]),
  ];
}

registerCardEffect('Redream', {
  preventsOwnPlay: (state, cardDb, playerId) => {
    const magi = state.players.get(playerId)?.activeMagi;
    return magi && hasDurationTag(magi, USED_THIS_TURN) ? 'You can only play Redream once per turn' : false;
  },
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    if (player.activeMagi) addDurationTag(ctx.state, ctx.cardDb, player.activeMagi, USED_THIS_TURN, ctx.state.turnNumber);

    const names = allowedStartingNames(ctx.state, ctx.cardDb, player.playerId);
    // ctx.rng, not the implicit defaultRng: tutorStartingCards reshuffles the deck after a
    // discard-pile miss falls through to a deck search -- found via a fuzz-harness replay
    // divergence (2026-07-30) traced to this call silently drawing from Math.random instead of the
    // seeded stream, unlike every other tutorStartingCards call site (setup.ts's own turn-start
    // tutoring, replay.ts), both of which already thread rng correctly.
    const found = tutorStartingCards(ctx.state, ctx.cardDb, player.playerId, names, ctx.rng);
    if (found.length === 0) return;

    const magiDef = player.activeMagi ? ctx.cardDb.get(player.activeMagi.definitionKey) : undefined;
    if (magiDef?.regions.includes("d'Resh")) return;

    addDurationTag(ctx.state, ctx.cardDb, ctx.source, AWAITING_DISCARD, ctx.state.turnNumber);
    ctx.source.counters.redreamDiscardCount = found.length;
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!hasDurationTag(self, AWAITING_DISCARD)) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player) return undefined;
    const count = Math.min(self.counters.redreamDiscardCount ?? 0, player.hand.length);
    if (count <= 0) return undefined;
    return {
      prompt: `Redream: your Magi is not d'Resh -- discard ${count} card(s) from your hand`,
      pool: player.hand.map((c) => c.instanceId),
      minCount: count,
      maxCount: count,
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds) => {
    // Redream sits in the discard pile once resolveSpell returns -- sweepExpiredDurationTags only
    // scans inPlay + activeMagi, so this tag must be cleared explicitly here or the prompt would
    // keep re-firing on every subsequent poll of the (now-answered) discarded card.
    removeDurationTag(self, AWAITING_DISCARD);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const count = Math.min(self.counters.redreamDiscardCount ?? 0, player.hand.length);
    const poolIds = new Set(player.hand.map((c) => c.instanceId));
    let chosen = [...new Set(chosenInstanceIds ?? [])].filter((id) => poolIds.has(id)).slice(0, count);
    if (chosen.length !== count) chosen = player.hand.slice(0, count).map((c) => c.instanceId);
    if (chosen.length > 0) discardFromHand(state, cardDb, player, chosen);
  },
});
