// Orok -- "Undermine: Whenever Orok loses energy in an attack, choose any one Magi in play.
// Discard half as much energy as Orok just loses from the chosen Magi, rounded down." Reacts
// whether Orok is attacking or defending -- compares ctx.snapshot (pre-damage) to Orok's own
// currentEnergy at afterCombat time (post-damage) to measure the real loss.
//
// Real choice (task #35, 2026-07-16, replacing the earlier "first Magi with energy" auto-pick
// simplification) -- same pendingTargetChoice/resolveTargetChoice-from-afterCombat shape as Dark
// Furok's Revile, with the per-trigger amount riding along in the pending tag's own string since
// it varies by how much Orok actually lost that specific attack.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allMagiInPlay } from '../targeting.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';

const UNDERMINE_PENDING_PREFIX = 'orokUnderminePending:';

function pendingUndermineAmount(self: CardInstance): number | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(UNDERMINE_PENDING_PREFIX)) return Number(tag.slice(UNDERMINE_PENDING_PREFIX.length));
  }
  return undefined;
}

registerCardEffect('Orok', {
  afterCombat: (ctx, outcome, self) => {
    let before: number;
    if (ctx.attacker.instanceId === self.instanceId) {
      before = ctx.snapshot.attackerEnergy;
    } else if (ctx.defender && ctx.defender.instanceId === self.instanceId) {
      before = ctx.snapshot.defenderEnergy;
    } else {
      return;
    }
    const lost = before - (self.currentEnergy ?? 0);
    if (lost <= 0) return;
    const amount = Math.floor(lost / 2);
    if (amount <= 0) return;
    if (allMagiInPlay(ctx.state).length === 0) return;
    addPermanentTag(ctx.state, ctx.cardDb, self, `${UNDERMINE_PENDING_PREFIX}${amount}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const amount = pendingUndermineAmount(self);
    if (amount === undefined) return undefined;
    const pool = allMagiInPlay(state);
    if (pool.length === 0) return undefined;
    return { prompt: `Orok's Undermine: choose a Magi to discard ${amount} energy from`, pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const amount = pendingUndermineAmount(self);
    if (amount === undefined) return;
    removePermanentTag(self, `${UNDERMINE_PENDING_PREFIX}${amount}`);
    if (!chosenInstanceId) return;
    const target = allMagiInPlay(state).find((m) => m.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, amount, 'effect', self.controllerId, rng);
  },
});
