// Porphin -- "Bolster: As Porphin attacks, add energy to it equal to the number of Relics you
// control. At the end of your Attack Step, discard Porphin from play." The first sentence is a
// plain onAttack self-buff; the second is the first real user of the new onOwnAttackStepEnd hook
// (registry.ts, added specifically for this card 2026-07-10).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { allRelicsInPlay } from '../targeting.js';

registerCardEffect('Porphin', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    const relicCount = allRelicsInPlay(ctx.state, ctx.cardDb).filter((r) => r.controllerId === self.controllerId).length;
    if (relicCount > 0) addEnergy(ctx.state, ctx.cardDb, self, relicCount, 'effect');
  },
  onOwnAttackStepEnd: (state, cardDb, self, rng) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
  },
});
