// Monsoon Hyren -- "Ravaging Storm (9): Discard Monsoon Hyren from play. Discard all opposing
// Creatures with less than five energy." No target -- a self-sacrifice plus a filtered sweep.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, creaturesControlledBy } from '../targeting.js';
import { discardFromPlay, rearrangeEnergy } from '../effects.js';

registerCardEffect('Monsoon Hyren', {
  // "Ebb: When you play Monsoon Hyren, move one energy from each of your other Creatures in play to
  // Monsoon Hyren." BUILT 2026-07-28 (ability-count sweep) -- the file had only Ravaging Storm.
  // `rearrangeEnergy` rather than discard+add, so this is a MOVE: the total on the board is
  // unchanged and nothing reads it as an energy loss. Creatures already on 0 contribute nothing
  // (guarded), since "move one energy" cannot take what isn't there.
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return; // only on Monsoon Hyren's OWN play
    for (const creature of creaturesControlledBy(state, cardDb, self.controllerId)) {
      if (creature.instanceId === self.instanceId) continue; // "each of your OTHER Creatures"
      if ((creature.currentEnergy ?? 0) < 1) continue;
      rearrangeEnergy(state, cardDb, creature, self, 1);
    }
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Ravaging Storm') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const toSweep = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter(
      (c) => (c.currentEnergy ?? 0) < 5
    );
    for (const creature of toSweep) {
      const owner = ctx.state.players.get(creature.controllerId);
      if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, creature.instanceId, undefined, undefined, ctx.rng);
    }
  },
});
