// Raveled Drush -- two Powers, plus a printed "Weave" effect.
// "Ravel: Add one energy to Raveled Drush." No target.
// "Unravel: Discard all energy from Raveled Drush to discard an equal amount of energy from each
// opposing Magi." No target. Previously Ravel had no branch in resolvePower at all -- cost was
// paid but nothing happened, a silent fizzle caught in playtesting (PROGRESS_LOG.md, 2026-07-09).
// "Weave: Whenever Raveled Drush is attacked, before energy is removed, you may move up to one
// energy between it and one of your other Core or Weave Creatures in play." (defend-only -- see
// weave.ts)

import { registerCardEffect } from './registry.js';
import { opposingMagi } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { applyWeave } from './weave.js';

registerCardEffect('Raveled Drush', {
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Ravel') {
      addEnergy(ctx.state, ctx.cardDb, ctx.source, 1, 'power');
    } else if (ctx.powerName === 'Unravel') {
      const amount = ctx.source.currentEnergy ?? 0;
      if (amount <= 0) return;
      discardEnergy(ctx.state, ctx.cardDb, ctx.source, amount, undefined, undefined, ctx.rng);
      for (const magi of opposingMagi(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
        discardEnergy(ctx.state, ctx.cardDb, magi, amount, undefined, undefined, ctx.rng);
      }
    }
  },
  weaveConfig: { eligibleRegions: ['Core', 'Weave'], mode: 'defendOnly' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Core', 'Weave'], 'defendOnly'),
});
