// Bronn -- "Snowball (3): Choose one of your Creatures. Double the chosen Creature's energy. That
// Creature cannot add energy to other cards and its energy cannot be moved to other cards.
// Discard that Creature at the end of the turn." First card using durationTags.ts's
// DISCARD_AT_END_OF_TURN tag. The "cannot add/move energy to other cards" restriction is an
// accepted, documented gap -- it would need every energy-giving primitive (rearrangeEnergy and
// any card that adds energy to something else) to check a tag on its SOURCE, not just its target,
// which nothing does yet; not enforced, same tradeoff as the "must attack" cards. The other
// printed clause ("Each of your non-Nar, non-Universal cards costs one additional energy to
// play.") is narSurcharge.ts's shared helper (2026-07-11).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag, DISCARD_AT_END_OF_TURN } from '../durationTags.js';
import { narSurcharge } from './narSurcharge.js';

registerCardEffect('Bronn', {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Snowball') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;

    const current = target.currentEnergy ?? 0;
    if (current > 0) addEnergy(ctx.state, ctx.cardDb, target, current, 'power');
    addPermanentTag(ctx.state, ctx.cardDb, target, DISCARD_AT_END_OF_TURN);
  },
  costModifier: narSurcharge,
});
