// Lanyx -- "Harvest (5): Choose any one non-Core Creature in play. Discard the chosen Creature
// from play." Not to be confused with "Lanyx, Reaper", a different card already implemented.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveRegions, findInPlayById, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Lanyx', {
  powerTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter((c) => !effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Core'))),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Harvest') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Core'))) return;

    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Core'],
});
