// Arawan -- "Warp Driven: Search your deck for any one Creature with the effect \"Dreamwarp\".
// Place the chosen Creature into your hand."

import { registerCardEffect } from './registry.js';
import { searchDeck } from '../effects.js';

registerCardEffect('Arawan', {
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && (def.effects.some((e) => e.name === 'Dreamwarp'));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Warp Driven') return;
    const ids = ctx.chosenDeckSearchIds ?? [];
    if (ids.length > 1) return;
    for (const id of ids) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
      if (!def || def.card_type !== 'Creature' || !(def.effects.some((e) => e.name === 'Dreamwarp'))) return;
    }
    searchDeck(ctx.state, ctx.controllingPlayer, ids, ctx.rng);
  },
});
