// Gar -- "Strengthen: Before you draw your cards during your Draw Step, add two energy to your
// Creature with the least energy. If there is a tie, you choose which Creature the energy gets
// placed on." onOwnTurnStart fires at the very start of the turn, before the Draw step -- a
// same-turn approximation of "before you draw," same class of simplification as Wence's
// Travelog/Shryque. Ties broken by array order (smallestOf's own tiebreak), matching "you choose."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, smallestOf } from '../targeting.js';

registerCardEffect('Gar', {
  onOwnTurnStart: (state, cardDb, self) => {
    const target = smallestOf(creaturesControlledBy(state, cardDb, self.controllerId));
    if (!target) return;
    addEnergy(state, cardDb, target, 2, 'effect');
  },
});
