// Kesia's Flute -- "Bend (1): Discard one energy from any number of your Weave Creatures in
// play, if Kesia is your Magi, you may move all energy to Kesia instead of discarding it. Add two
// energy to an equal number of other Creatures in play." First card needing a DEPENDENT slot
// count -- slot 2 must match however many were picked in slot 1, which registry.ts's
// PowerTargetSlot.min/max now support as a function of priorChoices (deferred from the
// hand-discard-cost/multi-target batch specifically for this card).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creaturesControlledBy, effectiveRegions, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect("Kesia's Flute", {
  powerTargetSlots: (state, cardDb, playerId) => {
    // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- this slot feeds
    // discardEnergy, the "other Creatures" slot below feeds addEnergy and stays Creature-only.
    const weaveSlotPool = (s: typeof state, db: typeof cardDb, pid: typeof playerId) => {
      const weaveRegion = regionForTargetFilter(s, 'Weave');
      const weaveCreatures = creaturesControlledBy(s, db, pid).filter((c) => effectiveRegions(s, db, c).includes(weaveRegion));
      const ownMagi = s.players.get(pid)?.activeMagi;
      const ownWeaveMagi = ownMagi && effectiveRegions(s, db, ownMagi).includes(weaveRegion) ? [ownMagi] : [];
      return flexibleTargetPool(s, db, pid, weaveCreatures, ownWeaveMagi);
    };
    return [
      {
        label: 'Discard 1 energy from any number of your Weave Creatures',
        pool: weaveSlotPool,
        min: 0,
        max: weaveSlotPool(state, cardDb, playerId).length,
      },
      {
        label: 'Add 2 energy to an equal number of OTHER Creatures in play',
        pool: (s, db, pid, priorChoices) => allCreaturesInPlay(s, db).filter((c) => !priorChoices[0]?.includes(c.instanceId)),
        min: (priorChoices) => priorChoices[0]?.length ?? 0,
        max: (priorChoices) => priorChoices[0]?.length ?? 0,
      },
    ];
  },
  booleanChoice: {
    prompt: 'If Kesia is your Magi: move the discarded energy to Kesia instead?',
    yesLabel: 'Move to Kesia',
    noLabel: 'Discard normally',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Bend') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const weaveIds = slots[0] ?? [];
    const otherIds = slots[1] ?? [];
    if (otherIds.length !== weaveIds.length) return;

    const weaveCreatures: ReturnType<typeof findInPlayById>[] = [];
    for (const id of weaveIds) {
      const c = findCreatureOrMagiById(ctx.state, id);
      // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead
      // (this loop only feeds discardEnergy below -- the "otherCreatures" loop feeds addEnergy
      // and stays Creature-only, Dreamburn doesn't cover it).
      if (!c || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, c, 'Creature')) return;
      if (c.controllerId !== ctx.controllingPlayer.playerId) return;
      if (!effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, 'Weave'))) return;
      weaveCreatures.push(c);
    }
    const otherCreatures: ReturnType<typeof findInPlayById>[] = [];
    for (const id of otherIds) {
      if (weaveIds.includes(id)) return; // must be an OTHER Creature
      const c = findCreatureOrMagiById(ctx.state, id);
      if (!c || ctx.cardDb.get(c.definitionKey)?.card_type !== 'Creature') return;
      otherCreatures.push(c);
    }

    const kesiaMagi = ctx.controllingPlayer.activeMagi;
    const isKesiaMagi = !!kesiaMagi && ctx.cardDb.get(kesiaMagi.definitionKey)?.name === 'Kesia';
    const moveToKesia = ctx.chosenBoolean && isKesiaMagi;

    let movedTotal = 0;
    for (const c of weaveCreatures) {
      const removed = Math.min(1, c!.currentEnergy ?? 0);
      discardEnergy(ctx.state, ctx.cardDb, c!, 1, undefined, undefined, ctx.rng);
      movedTotal += removed;
    }
    if (moveToKesia && movedTotal > 0) {
      addEnergy(ctx.state, ctx.cardDb, kesiaMagi!, movedTotal, 'power');
    }

    for (const c of otherCreatures) {
      addEnergy(ctx.state, ctx.cardDb, c!, 2, 'power');
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (The "other Creatures" slot is unrestricted -- only the
  // Weave slot's filter is in scope.)
  specifiedTargetRegions: () => ['Weave'],
});
