// Wence the Wanderer -- "Wence is Here (0): Look at the top card of your deck. If it is a Naroom
// Spell or a Creature with the Effect 'Weave', reveal it to all players and place it into your
// hand. Otherwise, discard it or return it to the top of your deck." "Reveal to all players" has
// no distinct game-state effect beyond moving the card to hand, so isn't separately modeled.
// "Otherwise, discard it or return it" -- no meaningful difference to either player, so returns it
// to the top rather than discarding (the less-destructive default).

import { registerCardEffect } from './registry.js';
import { peekTopOfDeck } from '../targeting.js';
import { removeFromZone, addToZone } from '../zones.js';

registerCardEffect('Wence the Wanderer', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Wence is Here') return;
    const [top] = peekTopOfDeck(ctx.controllingPlayer, 1);
    if (!top) return;
    const topDef = ctx.cardDb.get(top.definitionKey);
    const qualifies =
      (topDef?.card_type === 'Spell' && topDef.regions.includes('Naroom')) ||
      (topDef?.card_type === 'Creature' && topDef.effects.some((e) => e.name === 'Weave'));
    if (!qualifies) return;

    const card = removeFromZone(ctx.controllingPlayer, 'deck', top.instanceId);
    addToZone(ctx.controllingPlayer, 'hand', card);
  },
});
