// Gorath Cub -- "Chain Whip (1): Choose a Creature or Magi with more than its printed starting
// energy. Remove three energy from it." First card to use targeting.ts's printedStartingEnergy.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById, printedStartingEnergy } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

function isAboveStarting(cardDb: CardDatabase, c: CardInstance): boolean {
  return (c.currentEnergy ?? 0) > printedStartingEnergy(cardDb, c.definitionKey);
}

registerCardEffect('Gorath Cub', {
  powerTargets: (state, cardDb) =>
    [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)].filter((c) => isAboveStarting(cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Chain Whip') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isAboveStarting(ctx.cardDb, target)) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 3, undefined, undefined, ctx.rng);
  },
});
