// Tunneler's Boots -- "Strengthen: At the end of each of your turns, add one energy to each
// burrowed Creature in play." Literal reading of "in play" (no "your" qualifier before "burrowed
// Creature," unlike e.g. d'Jarvish's own Strengthen) -- applies to EVERY burrowed Creature on
// either side, not just the controller's own.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { isBurrowed } from '../durationTags.js';

registerCardEffect("Tunneler's Boots", {
  onOwnTurnEnd: (state, cardDb) => {
    for (const creature of allCreaturesInPlay(state, cardDb)) {
      if (isBurrowed(state, cardDb, creature)) addEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
});
