// T'Dek -- "Vitalize: Choose a Creature with less than its starting energy and restore it to its
// printed starting energy." Target pool filtered by the energy comparison, unlike Ven's
// unrestricted "any Creature" version of the same restore.
//
// "T'Dek may only play Naroom and Universal cards." Built 2026-07-24 -- a prior deferred-doc entry
// wrongly compared this to `regionOverride` (grant-only). The actually-relevant mechanism,
// `restrictsOwnPlayOf`, already existed (All-High King Korg's Super Clever, 2026-07-15); this is
// just an allow-list instead of Korg's block-list.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, printedStartingEnergy, effectiveStartingEnergy } from '../targeting.js';
import { restoreEnergy } from '../effects.js';

registerCardEffect("T'Dek", {
  // "Choose a Creature with less than its STARTING energy and restore it to its PRINTED starting
  // energy." Both phrasings in one sentence (task #568, 2026-07-28) -- eligibility reads the
  // effective value, the restore target reads the printed one. So T'Dek can legally target a
  // Dazzled/Dreamwarped Creature sitting above its printed value and still only heal it up to
  // printed, which for such a Creature means no heal at all. That asymmetry is what the card says.
  powerTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter((c) => (c.currentEnergy ?? 0) < effectiveStartingEnergy(state, cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Vitalize') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if ((target.currentEnergy ?? 0) >= effectiveStartingEnergy(ctx.state, ctx.cardDb, target)) return;
    const printed = printedStartingEnergy(ctx.cardDb, target.definitionKey);
    if ((target.currentEnergy ?? 0) >= printed) return;

    restoreEnergy(ctx.state, ctx.cardDb, target, printed);
  },
  restrictsOwnPlayOf: (state, cardDb, playerId, self, playedDef) =>
    !playedDef.regions.includes('Naroom') && !playedDef.regions.includes('Universal'),
});
