// Kiersta -- "Swoon: At the beginning of your turn, you may add five energy to Kiersta. If you
// do, skip your Attack step this turn. You cannot use Swoon on your next turn." Built task #37
// (Paradwyn pass, Category B, 2026-07-17) via the same pendingOwnTurnStartChoice/
// resolveOwnTurnStartChoice yes/no prompt Warrada's Ring uses, plus GameState's
// skipAttackPhaseThisTurn flag (Olabra's Staff's own precedent) and a duration tag for the
// one-turn lockout (same nextOwnTurnNumber-expiry shape as Shadow Cloak's Protection lockout).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag, nextOwnTurnNumber } from '../durationTags.js';

const SWOON_LOCKED = 'kierstaSwoonLocked';

registerCardEffect('Kiersta', {
  pendingOwnTurnStartChoice: (state, cardDb, self) => {
    if (hasDurationTag(self, SWOON_LOCKED)) return undefined;
    return {
      prompt: 'Kiersta: add five energy to Kiersta and skip your Attack step this turn?',
      yesLabel: 'Swoon (skip Attack step)',
      noLabel: 'No',
    };
  },
  resolveOwnTurnStartChoice: (state, cardDb, self, chosenBoolean) => {
    if (!chosenBoolean) return;
    addEnergy(state, cardDb, self, 5, 'effect');
    state.skipAttackPhaseThisTurn = true;
    addDurationTag(state, cardDb, self, SWOON_LOCKED, nextOwnTurnNumber(state));
  },
});
