// Warrior's Boots -- "Warpath: Discard Warrior's Boots from play. Immediately play a Creature
// from your hand. You must still pay all costs for the Creature." Unlike the rest of this batch,
// this DOESN'T ignore costs or regions -- it only bypasses the normal Play-New-Creatures-phase
// restriction (this Power fires during a Powers/Relics/Spells phase instead). Re-derives
// play.ts's own region/cost legality inline (checkRegionLegality + the Magi's energy) since
// play.ts's playCard itself is hand-only AND phase-gated, so it can't be called directly here.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, playFromZone, spellPlayCostWithModifiers } from '../effects.js';
import { checkRegionLegality, effectiveMagiDef } from '../regions.js';

registerCardEffect("Warrior's Boots", {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  handPlayChoice: {
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Warpath') return;
    if (!ctx.chosenHandPlayId) return;
    const handCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    const def = handCard ? ctx.cardDb.get(handCard.definitionKey) : undefined;
    const magi = ctx.controllingPlayer.activeMagi;
    const magiDefRaw = magi ? ctx.cardDb.get(magi.definitionKey) : undefined;
    if (!def || def.card_type !== 'Creature' || !magi || !magiDefRaw) return;
    if (typeof def.cost !== 'number') return; // X-cost Creatures have no chosenXValue plumbing here
    const magiDef = effectiveMagiDef(magiDefRaw, magi);

    const regionCheck = checkRegionLegality(magiDef, def);
    if (!regionCheck.legal) return;
    // BUG FIXED 2026-07-27, alongside Gia's Tome's identical one (found by grepping for the other
    // in-card re-derivations of `+ regionalPenalty`). This charged `def.cost` and never consulted
    // `costModifier`, so Marella/Void Stone/Jasker's Mask/the Nar surcharge were all invisible --
    // squarely against this card's own printed "You must still pay all costs for the Creature."
    // Priced through the shared helper now; see docs/hook-reference.md §13 and giasTome.ts's fuller
    // note on the modifiers-then-floor-then-regional-penalty ordering, which mirrors play.ts.
    const totalCost =
      spellPlayCostWithModifiers(ctx.state, ctx.cardDb, def, ctx.controllingPlayer.playerId, def.cost) +
      regionCheck.regionalPenalty;
    if ((magi.currentEnergy ?? 0) < totalCost) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    magi.currentEnergy = (magi.currentEnergy ?? 0) - totalCost;
    playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: ctx.chosenHandPlayId },
      ctx.controllingPlayer,
      def.cost
    , ctx.rng);
  },
});
