// Magma Parmalag -- "Immolation: Discard Magma Parmalag from play. Discard one energy from each
// of your Creatures in play. Until the end of your turn, your Creatures in play lose no energy in
// attacks." The "no energy loss in attacks" clause reuses vaalParmalag.ts's NO_ENERGY_LOST_IN_ATTACKS
// duration tag (task #26's Shield) -- that comment's "deferred, same category as Vaal's Shield" was
// written before Shield itself was actually built via that tag; re-checked and applied here (task
// #31, 2026-07-16). Vaal/Parmalag's Shield applies the tag to a single Creature (itself); this
// applies it to EVERY one of the controller's own Creatures, since the printed text has no
// "chosen Creature" -- it's a board-wide grant, not a self-buff.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { addDurationTag, NO_ENERGY_LOST_IN_ATTACKS } from '../durationTags.js';

registerCardEffect('Magma Parmalag', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Immolation') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
      addDurationTag(ctx.state, ctx.cardDb, creature, NO_ENERGY_LOST_IN_ATTACKS, ctx.state.turnNumber, ctx.source.instanceId);
    }
  },
});
