// Arboll -- "Life Channel: Choose any one Magi in play. Discard Arboll from play. Add four energy
// to the chosen Magi."

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Arboll', {
  powerTargets: (state) => allMagiInPlay(state),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Life Channel') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!findCreatureOrMagiById(ctx.state, ctx.chosenTargetId)) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;
    addEnergy(ctx.state, ctx.cardDb, target, 4, 'power');
  },
});
