// Cave In (Spell, Underneath, cost 4) -- "Discard one energy from each non-Underneath Creature and
// Magi in play. Discard one additional energy from each Arderial Creature and Magi." Arderial is
// itself non-Underneath, so an Arderial card takes BOTH hits (2 total); the "additional" is a
// second discard on top, not a replacement.
//
// Both named regions go through regionForTargetFilter so an active region swap (Abwyn's Quill /
// Niffer's Overwrite / Obgren's Delusions) retargets them, matching the 34-file region-swap sweep's
// rule for any card naming a specific region. ashioAdjustedRegion is deliberately NOT used -- it
// only ever rewrites a 'Core' reference, and neither region here is Core.
//
// Creature regions read via effectiveRegions (honours effectiveRegionOverride / identityOverride);
// Magi regions via effectiveMagiDef, which is the ONLY correct Magi-side reader -- a raw
// def.regions read would miss a Shadow-Magi identity override or League Elder's chosen region
// (that exact bug was fixed in regions.ts on 2026-07-24).

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, allMagiInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { effectiveMagiDef } from '../regions.js';
import { getOpponents } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

/** A Magi's CURRENT regions -- see this file's header for why effectiveMagiDef is mandatory here. */
function magiRegions(cardDb: CardDatabase, magi: CardInstance): readonly string[] {
  const def = cardDb.get(magi.definitionKey);
  return def ? effectiveMagiDef(def, magi).regions : [];
}

registerCardEffect('Cave In', {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- static region check mirroring
  // resolveSpell's own two-clause gating below, no execution.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId) => {
    const underneath = regionForTargetFilter(state, 'Underneath');
    const arderial = regionForTargetFilter(state, 'Arderial');
    return getOpponents(state, actingPlayerId).some((opp) => {
      if (!opp.activeMagi) return false;
      const regions = magiRegions(cardDb, opp.activeMagi);
      return !regions.includes(underneath) || regions.includes(arderial);
    });
  },
  resolveSpell: (ctx) => {
    const casterId = ctx.controllingPlayer.playerId;
    const underneath = regionForTargetFilter(ctx.state, 'Underneath');
    const arderial = regionForTargetFilter(ctx.state, 'Arderial');

    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      const regions = effectiveRegions(ctx.state, ctx.cardDb, creature);
      // ctx.rng threaded (found via a fuzz-harness replay divergence, 2026-07-30): a defeat here
      // can trigger a reactor like Bagala Cub's onCardDiscardedFromPlay, which reshuffles a deck.
      if (!regions.includes(underneath)) discardEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell', casterId, ctx.rng);
      if (regions.includes(arderial)) discardEnergy(ctx.state, ctx.cardDb, creature, 1, 'spell', casterId, ctx.rng);
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      const regions = magiRegions(ctx.cardDb, magi);
      if (!regions.includes(underneath)) discardEnergy(ctx.state, ctx.cardDb, magi, 1, 'spell', casterId, ctx.rng);
      if (regions.includes(arderial)) discardEnergy(ctx.state, ctx.cardDb, magi, 1, 'spell', casterId, ctx.rng);
    }
  },
});
