// Dryte Fiend -- "Condemn: At the beginning of each of your opponent's turns, you may choose any
// one Creature in play. Until the end of that opponent's turn, each time the chosen Creature
// loses energy as a result of Powers, Spells, or attacks, discard three energy from that
// Creature." Applies durationTags.ts's CONDEMNED tag (see that tag's own doc comment for the full
// mechanism -- checked directly in combat.ts/effects.ts, same "generic tag" shape as STALKED/
// WEAKENED, not a broadcast hook). "Cald Magi may play Dryte Fiend" is shadow_play, already
// generic/data-driven.
//
// Real choice (task #40-1, 2026-07-17, player-choice-default retrofit): replaces the earlier
// "first opposing Creature in array order" auto-pick with a real pending choice
// (registry.ts's pendingTargetChoice/resolveTargetChoice, habob.ts's template) -- fizzles (no
// trigger) when no opposing Creature is in play.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { addDurationTag, addPermanentTag, addPendingChoiceTag, removePermanentTag, CONDEMNED } from '../durationTags.js';

const CONDEMN_PENDING = 'dryteFiendCondemnPending';

function condemnPool(state: Parameters<typeof allCreaturesInPlay>[0], cardDb: Parameters<typeof allCreaturesInPlay>[1], self: { controllerId: string }) {
  return allCreaturesInPlay(state, cardDb).filter((c) => c.controllerId !== self.controllerId);
}

registerCardEffect('Dryte Fiend', {
  onOpponentTurnStart: (state, cardDb, self) => {
    if (condemnPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, CONDEMN_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(CONDEMN_PENDING)) return undefined;
    const pool = condemnPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Dryte Fiend's Condemn: choose an opposing Creature", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, CONDEMN_PENDING);
    if (!chosenInstanceId) return;
    const target = condemnPool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    addDurationTag(state, cardDb, target, CONDEMNED, state.turnNumber);
  },
});
