// Dark Vellup -- "Purge: Discard a card from your hand and draw a card. If a copy of the card you
// discarded is in play, draw an extra card."

import { registerCardEffect } from './registry.js';
import { drawCards, discardFromHand } from '../effects.js';
import { allCreaturesInPlay, allRelicsInPlay, allSpellsInPlay } from '../targeting.js';

registerCardEffect('Dark Vellup', {
  handDiscardCost: { count: 1 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Purge') return;
    const id = (ctx.chosenHandCardIds ?? [])[0];
    if (!id) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
    if (!discardedCard) return;
    const discardedName = ctx.cardDb.get(discardedCard.definitionKey)?.name;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [id], undefined, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);

    const inPlay = [
      ...allCreaturesInPlay(ctx.state, ctx.cardDb),
      ...allRelicsInPlay(ctx.state, ctx.cardDb),
      ...allSpellsInPlay(ctx.state, ctx.cardDb),
    ];
    if (discardedName && inPlay.some((c) => ctx.cardDb.get(c.definitionKey)?.name === discardedName)) {
      drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    }
  },
});
