// Kayliel -- "Relic Subversion: When you reveal Kayliel, gain control of all opposing Relics."
// The first card needing registry.ts's onMagiRevealed hook -- reacts only to her OWN reveal.

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay } from '../targeting.js';
import { gainControl } from '../effects.js';

registerCardEffect('Kayliel', {
  onMagiRevealed: (state, cardDb, revealedMagi, self) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    const opposingRelics = allRelicsInPlay(state, cardDb).filter((r) => r.controllerId !== self.controllerId);
    for (const relic of opposingRelics) {
      gainControl(state, cardDb, relic, self.controllerId);
    }
  },
});
