// Aegris -- two Effects:
//   "Bypass: If Aegris is frozen, it can attack Magi directly." (bypasses the normal "opponent
//   controls a Creature" block on attacking a Magi directly.)
//   "Shatter: Whenever Aegris attacks a Magi, choose one of that Magi's Creatures. You may
//   discard Aegris from play before energy is removed to discard the chosen Creature from play."
//
// The "may discard [Aegris]" choice is still auto-taken whenever legal (same tradeoff as
// freep.ts/leafChogo.ts -- out of scope for Phase 4c, which is specifically about WHICH target
// gets chosen, not WHETHER an optional ability activates). "Choose one of that Magi's Creatures"
// is now a real pending choice (Phase 4c, 2026-07-11, registry.ts's pendingTargetChoice/
// resolveTargetChoice) instead of the earlier "first eligible in array order" simplification.
// Aegris discards ITSELF as part of applying its own effect, so by the time the choice needs
// resolving self is already in the discard pile -- findPendingTargetChoices scans both discard
// piles for exactly this reason. Resolved in afterCombat rather than literally "before energy is
// removed" -- a Creature-vs-Magi attack never costs the attacker any energy either way (combat.ts
// step 7: "only the Magi loses energy, the Creature isn't damaged back"), so Aegris surviving to
// afterCombat changes nothing observable, and this avoids removing the live attacker from play
// mid-onAttack before damage lock-in.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { isFrozen } from '../durationTags.js';
import { opposingCreatures } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const SHATTER_PENDING = 'aegrisShatterPending';

registerCardEffect('Aegris', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Bypass is the frozen-attack-Magi
  // allowance; Shatter is the whenever-attacks-a-Magi discard-a-Creature sequence.
  effectHooks: {
    Bypass: ['canAttackMagiDirectly'],
    Shatter: ['afterCombat', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  canAttackMagiDirectly: (state, cardDb, instance) => isFrozen(state, cardDb, instance),
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender !== null) return; // "attacks a Magi" only
    const hasTarget = ctx.defendingPlayer.inPlay.some((c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature');
    if (!hasTarget) return;
    addPendingChoiceTag(self, SHATTER_PENDING);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.attackingPlayer, self.instanceId, undefined, undefined, ctx.rng);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SHATTER_PENDING)) return undefined;
    // 2-player-only engine, so "that Magi" is always simply "the opponent" -- self.controllerId
    // still correctly identifies Aegris's own controller even after being discarded.
    const pool = opposingCreatures(state, cardDb, self.controllerId);
    if (pool.length === 0) return undefined;
    return { prompt: "Aegris's Shatter: choose one of that Magi's Creatures to discard from play", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, SHATTER_PENDING);
    if (!chosenInstanceId) return;
    const target = opposingCreatures(state, cardDb, self.controllerId).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    const owner = state.players.get(target.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, target.instanceId, undefined, undefined, rng);
  },
});
