// Flutter Yup -- "Dodge: Whenever Flutter Yup attacks or is attacked by a Creature with more than
// three energy, Flutter Yup loses no energy in the attack." Self-agnostic (attacker or defender);
// zeroes whichever locked value determines Flutter Yup's OWN loss, not the damage it deals.

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';

registerCardEffect('Flutter Yup', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId === self.instanceId) {
      if (ctx.defender && ctx.snapshot.defenderEnergy > 3) {
        if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = 0; // zeroes what Flutter Yup (the attacker) takes back
      }
    } else if (ctx.defender?.instanceId === self.instanceId) {
      if (ctx.snapshot.attackerEnergy > 3) {
        if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = 0; // zeroes what Flutter Yup (the defender) takes
      }
    }
  },
});
