// Magam, Flamesmith -- "Flame Boost: Add two energy to the first Creature played on your turn."
// "Flame Strike: Discard two energy from the first Creature played on each opposing turn." Neither
// clause says "your Creature" -- it's the first Creature played during the relevant turn,
// regardless of who played it. onPlay broadcast + a once-per-turn duration tag on Magam herself
// (same shape as Keggerop's Momentum), gated on whose turn it currently is via
// state.activePlayerId rather than a played-count field.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const FLAME_BOOST_USED = 'magamFlameBoostUsedThisTurn';
const FLAME_STRIKE_USED = 'magamFlameStrikeUsedThisTurn';

registerCardEffect('Magam, Flamesmith', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Both Effects live in a single onPlay function
  // that branches on activePlayerId. Narrowing is per-hook-name, not per-branch, so a Taglat
  // copy of either Effect still fires the full onPlay body (i.e. the other clause tags along).
  // Same shape/tradeoff as Halsted; annotated for explicitness -- fallback would produce the
  // same result here since onPlay is the only hook.
  effectHooks: {
    'Flame Boost': ['onPlay'],
    'Flame Strike': ['onPlay'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;

    if (state.activePlayerId === self.controllerId) {
      if (hasDurationTag(self, FLAME_BOOST_USED)) return;
      addDurationTag(state, cardDb, self, FLAME_BOOST_USED, state.turnNumber);
      addEnergy(state, cardDb, played, 2, 'effect');
    } else {
      if (hasDurationTag(self, FLAME_STRIKE_USED)) return;
      addDurationTag(state, cardDb, self, FLAME_STRIKE_USED, state.turnNumber);
      discardEnergy(state, cardDb, played, 2, 'effect');
    }
  },
});
