// Book of Life -- "Relearn (3): Choose any one Spell in your discard pile. Move the chosen card to
// the top of your deck." Same discardPileSearch shape as Sperri/Delia/Bog Stone, filtered by
// card_type instead of creature family/region, and destination is deckTop instead of hand.

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';

registerCardEffect('Book of Life', {
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Spell',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Relearn') return;
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    if (!card || ctx.cardDb.get(card.definitionKey)?.card_type !== 'Spell') return;
    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'deckTop');
  },
});
