// Yebed -- "Rolling Stones: At the beginning of your turn, if your largest Creature in play is
// smaller than the smallest opposing Creature in play, all opposing Creatures in play lose one
// energy."

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { creaturesControlledBy, opposingCreatures, smallestOf } from '../targeting.js';

registerCardEffect('Yebed', {
  onOwnTurnStart: (state, cardDb, self) => {
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    if (own.length === 0) return;
    const largestOwn = own.reduce((best, c) => ((c.currentEnergy ?? 0) > (best.currentEnergy ?? 0) ? c : best));
    const opposing = opposingCreatures(state, cardDb, self.controllerId);
    const smallestOpposing = smallestOf(opposing);
    if (!smallestOpposing) return;
    if ((largestOwn.currentEnergy ?? 0) >= (smallestOpposing.currentEnergy ?? 0)) return;

    for (const creature of opposing) {
      discardEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
});
