// Dream Balm -- "Vitalize: Choose any one Creature in play with less than its starting energy.
// Discard Dream Balm from play. Restore the chosen Creature to its starting energy." Same
// Vitalize shape as Magam/Weebo/T'Dek, plus a self-discard.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay, restoreEnergy } from '../effects.js';

registerCardEffect('Dream Balm', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter((c) => (c.currentEnergy ?? 0) < effectiveStartingEnergy(state, cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Vitalize') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const starting = effectiveStartingEnergy(ctx.state, ctx.cardDb, target);
    if ((target.currentEnergy ?? 0) >= starting) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    restoreEnergy(ctx.state, ctx.cardDb, target, starting);
  },
});
