// Implosion (Spell, Orothe, cost 1) -- "Choose any one Creature or Magi in play. Discard X Orothe
// cards from your hand. Discard X energy from the chosen Creature or Magi." X is a free player
// choice, not this Spell's own printed cost -- it reuses spiritOfTheFlame.ts's "discard N, gain N"
// idiom exactly (spellHandDiscardCost: {count: 'any', filter: <region> cards}, ids.length used
// directly as X), just discarding energy instead of adding it.

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromHand } from '../effects.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById, regionForTargetFilter } from '../targeting.js';

registerCardEffect('Implosion', {
  spellTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)],
  spellHandDiscardCost: {
    count: 'any',
    filter: (state, cardDb, playerId, card) =>
      cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(state, 'Orothe')) ?? false,
  },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;

    const ids = (ctx.chosenHandCardIds ?? []).filter((id) => {
      const card = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
      const def = card && ctx.cardDb.get(card.definitionKey);
      return def?.regions.includes(regionForTargetFilter(ctx.state, 'Orothe')) ?? false;
    });
    if (ids.length === 0) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids, undefined, ctx.rng);
    discardEnergy(ctx.state, ctx.cardDb, target, ids.length, 'spell', undefined, ctx.rng);
  },
  specifiedSpellTargetRegions: () => ['Orothe'],
});
