// Lanyx, Reaper -- "Hatred (4): Remove two energy from each opposing Creature. Remove one extra
// energy from each d'Resh Creature." No target -- a sweep with a region-conditional bonus.

import { registerCardEffect } from './registry.js';
import { effectiveRegions, opposingCreatures, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Lanyx, Reaper', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Hatred') return;
    for (const creature of opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      const isDResh = effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, "d'Resh"));
      discardEnergy(ctx.state, ctx.cardDb, creature, isDResh ? 3 : 2, undefined, undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Every opposing Creature is hit regardless of region --
  // only the bonus magnitude clause names d'Resh, but Abwyn's Quill's text still applies to it.
  specifiedTargetRegions: () => ["d'Resh"],
});
