// Ergar -- Effect: Ignite: "While Ergar is in play, each of your Cald Creatures in play gains the
// following text: 'Power -- Spark: (1) Choose any one Creature or Magi in play. Discard one energy
// from the chosen Creature or Magi.'"
//
// Reuses copiedPowers.ts's addCopiedPower with `expiresWhenInstanceLeavesPlay: <Ergar's own
// instanceId>` -- the same shape K'teeb already uses for its near-identical "grant this Power,
// remove it when the source leaves" lifecycle (kteeb.ts), just granting to MULTIPLE targets at
// once instead of one, and granting a made-up Power (SPARK_POWER below) rather than a copy of a
// REAL printed Power elsewhere. `fromDefinitionKey` is set to ERGAR's own key (not the granted
// Creature's), so power.ts's findPower routes activation back to Ergar's OWN resolvePower below
// (dispatchDef = cardDb.get(fromDefinitionKey)) -- the same "dispatch runs the ORIGINAL card's
// implementation" rule K'teeb's copied Powers already rely on.
//
// Granted on two occasions, both via this file's own onPlay hook (broadcast to every in-play
// card on every play, not just Ergar's own -- play.ts's onPlay doc comment): (1) when Ergar
// itself is the card just played, granted to every currently-in-play Cald Creature the same
// controller has; (2) when any OTHER Cald Creature is played while Ergar is already in play,
// granted to just that Creature. Together these keep the grant "live" rather than a one-time
// snapshot, matching the "while Ergar is in play" ongoing wording. No cleanup code needed when
// Ergar itself leaves play -- expiresWhenInstanceLeavesPlay is checked live by
// isCopiedPowerActive, not swept.

import { registerCardEffect } from './registry.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import { creaturesControlledBy, allCreaturesInPlay, allMagiInPlay } from '../targeting.js';
import { addCopiedPower, activeCopiedPowers } from '../copiedPowers.js';
import { discardEnergy } from '../effects.js';

const SPARK_POWER = {
  cost: 1,
  name: 'Spark',
  text: 'Choose any one Creature or Magi in play. Discard one energy from the chosen Creature or Magi.',
};

function grantSparkIfEligible(state: GameState, cardDb: CardDatabase, ergar: CardInstance, target: CardInstance): void {
  const targetDef = cardDb.get(target.definitionKey);
  if (!targetDef || targetDef.card_type !== 'Creature') return;
  if (!targetDef.regions.includes('Cald')) return;
  if (target.controllerId !== ergar.controllerId) return;
  const ergarDef = cardDb.get(ergar.definitionKey);
  if (!ergarDef) return;
  const alreadyGranted = activeCopiedPowers(state, target).some(
    (cp) => cp.power.name === 'Spark' && cp.fromDefinitionKey === ergarDef.key
  );
  if (alreadyGranted) return;
  addCopiedPower(target, SPARK_POWER, ergarDef.key, { whenInstanceLeavesPlay: ergar.instanceId });
}

registerCardEffect('Ergar', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) {
      for (const creature of creaturesControlledBy(state, cardDb, self.controllerId)) {
        grantSparkIfEligible(state, cardDb, self, creature);
      }
    } else {
      grantSparkIfEligible(state, cardDb, self, played);
    }
  },
  powerTargets: (state, cardDb, playerId, powerName) => {
    if (powerName !== 'Spark') return undefined;
    return [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Spark') return;
    if (!ctx.chosenTargetId) return;
    const target = [...allCreaturesInPlay(ctx.state, ctx.cardDb), ...allMagiInPlay(ctx.state)].find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    if (!target) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
  },
});
