// Vuryip -- both printed effects:
//   "Random Change: Whenever Vuryip attacks or is attacked, before energy is removed, draw a
//   card."
//   "Weave: Whenever Vuryip attacks or is attacked, before energy is removed, you may move one
//   energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { applyWeave } from './weave.js';

registerCardEffect('Vuryip', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Random Change (draw on either side of
  // an attack) and Weave share the fused `onBeforeEnergyRemoved` body -- listed under both.
  // Weave additionally carries `weaveConfig`.
  effectHooks: {
    'Random Change': ['onBeforeEnergyRemoved'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => {
    const isAttacker = ctx.attacker.instanceId === self.instanceId;
    const isDefender = ctx.defender?.instanceId === self.instanceId;
    if (isAttacker || isDefender) {
      const player = ctx.state.players.get(self.controllerId);
      if (player) drawCards(ctx.state, ctx.cardDb, player, 1);
    }
    applyWeave(ctx, self, ['Weave']);
  },
});
