// Trug (Magi) -- "Cataclysm: Discard ALL cards in play. Each Magi is defeated and go to his or her
// owner's Magi pile." Built task #48, 2026-07-18, the Underneath region pass -- Category C. A
// deliberately game-ending Power (cost 15): first every in-play card on BOTH boards is discarded (so
// each card's own leaves-play hooks fire via discardFromPlay), then every active Magi is defeated
// through energy.ts's defeatMagi -- the same choke point a normal energy-loss defeat uses, which
// moves the Magi to its owner's Magi pile, wipes its remaining Relics, and reveals the next Magi (or
// ends the game). Trug's own Magi is defeated too, exactly as printed.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { defeatMagi, checkMagiDefeats } from '../energy.js';

registerCardEffect('Trug', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Cataclysm') return;
    // Discard ALL cards in play, both boards, before any Magi is defeated (so leaves-play hooks see
    // a still-standing Magi and fire normally). Snapshot each inPlay list -- discardFromPlay mutates it.
    for (const player of ctx.state.players.values()) {
      for (const card of [...player.inPlay]) {
        discardFromPlay(ctx.state, ctx.cardDb, player, card.instanceId, undefined, undefined, ctx.rng);
      }
    }
    // Then defeat every active Magi.
    for (const player of ctx.state.players.values()) {
      if (player.activeMagi) defeatMagi(ctx.state, ctx.cardDb, player, ctx.rng);
    }
    checkMagiDefeats(ctx.state, ctx.cardDb, ctx.rng);
  },
});
