// Whilp -- "Plague (1): Choose a Creature type. All Creatures of the chosen type lose two
// energy." Sweep version of Omni Construct's categoryChoice pattern: instead of counting matches
// and adding energy to self, this discards 2 energy from every matching Creature in play on
// EITHER side of the board (the text says "all Creatures," not "your Creatures"). "Type" means
// the Creature's species/family (Hyren, Xyx, Arboll, etc. -- targeting.ts's creatureType), NOT
// region -- fixed 2026-07-08, this originally (incorrectly) grouped by region, same mistake as
// Omni Construct's first implementation. Options are computed from whichever types are actually
// present among Creatures in play right now.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creatureType } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Whilp', {
  categoryChoice: {
    prompt: 'Choose a Creature type',
    options: (state, cardDb) => {
      const types = new Set<string>();
      for (const creature of allCreaturesInPlay(state, cardDb)) {
        types.add(creatureType(cardDb, creature.definitionKey));
      }
      return [...types];
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Plague') return;
    if (!ctx.chosenCategory) return;
    const matching = allCreaturesInPlay(ctx.state, ctx.cardDb).filter(
      (c) => creatureType(ctx.cardDb, c.definitionKey) === ctx.chosenCategory
    );
    for (const creature of matching) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 2, undefined, undefined, ctx.rng);
    }
  },
});
