// Alaban -- "Undream (5): Choose any one Creature in play. Return the chosen creature to its
// owner's hand. Discard the chosen Creature's energy."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { returnToHand } from '../effects.js';

registerCardEffect('Alaban', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Undream') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const owner = ctx.state.players.get(target.ownerId);
    if (!owner) return;

    returnToHand(ctx.state, ctx.cardDb, owner, target.instanceId); // also discards its energy (returnToHand's own contract)
  },
});
