// Core Hyren -- "Dissect: Each turn, during your Draw Step, draw one additional card for each
// Creature Core Hyren attacked and defeated that turn." A per-turn counter (task #50f's
// CardInstance.counters), incremented by afterCombat whenever Core Hyren itself is the attacker
// and the (Creature, not Magi) defender didn't survive, reset at the start of Core Hyren's own
// controller's turn (before that same turn's Attack phase can add to it again), read by
// drawCountModifier once that same turn's Draw Step arrives.

import { registerCardEffect } from './registry.js';

const DEFEATS_THIS_TURN = 'coreHyrenDefeatsThisTurn';

registerCardEffect('Core Hyren', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (!ctx.defender) return; // "a Creature" -- not a direct Magi attack
    if (outcome.defenderSurvived) return;
    self.counters[DEFEATS_THIS_TURN] = (self.counters[DEFEATS_THIS_TURN] ?? 0) + 1;
  },
  onOwnTurnStart: (state, cardDb, self) => {
    self.counters[DEFEATS_THIS_TURN] = 0;
  },
  drawCountModifier: (state, cardDb, self) => self.counters[DEFEATS_THIS_TURN] ?? 0,
});
