// Slinking Greal -- "Skulk (1): Choose an opposing Core Creature and remove one energy from it.
// That Creature's controller chooses a Creature he or she controls and removes two energy from
// it." Slot 2 is the OPPONENT's follow-up pick (registry.ts's PowerTargetSlot.respondingPlayer),
// dependent on slot 1's target's controller -- same dependent-pool shape as Rask Deserter.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, creaturesControlledBy, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Slinking Greal', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- BOTH slots feed
  // discardEnergy, so both may accept a Magi. The flexibility grant is checked against
  // `playerId` (Slinking Greal's controller, the Power's user) even for slot 2, whose PICKER is
  // the opponent (respondingPlayer) -- Dreamburn belongs to the Power's controller, not whoever
  // makes a given choice.
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose an opposing Core Creature',
      pool: (s, db, pid) =>
        flexibleTargetPool(s, db, pid, opposingCreatures(s, db, pid), opposingMagi(s, db, pid)).filter((c) =>
          effectiveRegions(s, db, c).includes(regionForTargetFilter(s, 'Core'))
        ),
      min: 1,
      max: 1,
    },
    {
      label: 'Opponent: choose one of your Creatures',
      pool: (s, db, pid, priorChoices) => {
        const firstId = priorChoices[0]?.[0];
        if (!firstId) return [];
        const first = findCreatureOrMagiById(s, firstId);
        if (!first) return [];
        // first.controllerId is guaranteed to be pid's opponent (slot 1's pool is opposing-only).
        return flexibleTargetPool(s, db, pid, creaturesControlledBy(s, db, first.controllerId), opposingMagi(s, db, pid));
      },
      min: 1,
      max: 1,
      respondingPlayer: 'opponent',
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Skulk') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const coreTargetId = slots[0]?.[0];
    if (!coreTargetId) return;
    const coreTarget = findCreatureOrMagiById(ctx.state, coreTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!coreTarget || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, coreTarget, 'Creature')) return;
    if (coreTarget.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, coreTarget).includes(regionForTargetFilter(ctx.state, 'Core'))) return;

    discardEnergy(ctx.state, ctx.cardDb, coreTarget, 1, undefined, undefined, ctx.rng);

    const followUpId = slots[1]?.[0];
    if (!followUpId) return;
    const followUp = findCreatureOrMagiById(ctx.state, followUpId);
    if (!followUp || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, followUp, 'Creature')) return;
    if (followUp.controllerId !== coreTarget.controllerId) return;
    discardEnergy(ctx.state, ctx.cardDb, followUp, 2, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Core'],
});
