// Gia -- "Unearth: Discard any one of your Relics from play to search your deck for any one Relic
// and put it directly into play. Shuffle your deck afterwards." Unlike the "into hand" deckSearch
// cards, this uses the new searchDeckIntoPlay primitive (Gia is a Magi, so it's a Power on the
// Magi itself, not a Creature/Relic source).

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, findInPlayById, printedStartingEnergy } from '../targeting.js';
import { discardFromPlay, searchDeckIntoPlay } from '../effects.js';
import { shuffleDeck } from '../zones.js';

registerCardEffect('Gia', {
  powerTargets: (state, cardDb, playerId) => allRelicsInPlay(state, cardDb).filter((r) => r.controllerId === playerId),
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Relic',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Unearth') return;
    if (ctx.chosenTargetId === undefined) return;
    const costRelic = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!costRelic || ctx.cardDb.get(costRelic.definitionKey)?.card_type !== 'Relic') return;
    if (costRelic.controllerId !== ctx.controllingPlayer.playerId) return;

    const searchIds = ctx.chosenDeckSearchIds ?? [];
    if (searchIds.length > 1) return;
    for (const id of searchIds) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      if (!card || ctx.cardDb.get(card.definitionKey)?.card_type !== 'Relic') return;
    }

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, costRelic.instanceId, undefined, undefined, ctx.rng);
    for (const id of searchIds) {
      const key = ctx.controllingPlayer.deck.find((c) => c.instanceId === id)?.definitionKey;
      if (key === undefined) continue;
      searchDeckIntoPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, id, printedStartingEnergy(ctx.cardDb, key), false, ctx.rng);
    }
    shuffleDeck(ctx.controllingPlayer, ctx.rng);
  },
});
