// Firefly Swarm (Spell, cost 2) -- "Choose any one non-Cald Creature in play. Discard two energy
// from the chosen Creature. That Creature may not attack on its controller's next turn." Cald
// Spell pass, Category A (2026-07-20). fireflyAmulet.ts's CANNOT_ATTACK +
// nextTurnNumberFor(state, target.controllerId) pattern, pool = allCreaturesInPlay filtered to
// non-Cald (same effectiveRegions filter idiom as golthub.ts).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveRegions, findInPlayById, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK, nextTurnNumberFor } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Firefly Swarm', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => !effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Cald'))),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Cald'))) return; // "non-Cald" -- re-validated at resolution

    discardEnergy(ctx.state, ctx.cardDb, target, 2, 'spell', undefined, ctx.rng);
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, nextTurnNumberFor(ctx.state, target.controllerId));
  },
  specifiedSpellTargetRegions: () => ['Cald'],
});
