// Bo'Ahsa's Shield (Weave Relic) -- "Weave Tactics: Once per turn, when one of your Weave Creatures
// is attacked, you may discard one energy from your Magi. If you do, choose one of your Weave
// Creatures in play. Replace the defending Creature with the chosen Creature." Built in the Weave
// region pass #49, Category C.
//
// Same defender-substitution reuse (offersDefenderRedirect) as Bo'Ahsa, but a Relic and with a COST:
// the offer is only made when the controller's Magi has >= 1 energy to spend, and the new
// onDefenderRedirectAccepted callback discards that 1 energy from the Magi (and marks once-per-turn)
// the moment the switch is accepted -- the cost is paid only on a real accept, never on the preview.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import { discardEnergy } from '../effects.js';

const WEAVE_TACTICS_USED = 'boAhsasShieldWeaveTacticsUsedThisTurn';

registerCardEffect("Bo'Ahsa's Shield", {
  offersDefenderRedirect: (state, cardDb, self, _attacker, declaredDefender) => {
    if (hasDurationTag(self, WEAVE_TACTICS_USED)) return undefined; // "once per turn"
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return undefined; // needs 1 energy for the cost
    if (declaredDefender.controllerId !== self.controllerId) return undefined; // "one of YOUR Weave Creatures"
    if (!effectiveRegions(state, cardDb, declaredDefender).includes('Weave')) return undefined;
    const pool = creaturesControlledBy(state, cardDb, self.controllerId).filter(
      (c) => c.instanceId !== declaredDefender.instanceId && effectiveRegions(state, cardDb, c).includes('Weave')
    );
    return pool.length > 0 ? pool : undefined;
  },
  onDefenderRedirectAccepted: (state, cardDb, self) => {
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (magi) discardEnergy(state, cardDb, magi, 1, 'effect', self.controllerId); // "discard one energy from your Magi"
    addDurationTag(state, cardDb, self, WEAVE_TACTICS_USED, state.turnNumber);
  },
});
