// Karse -- two printed clauses:
//   "Vengeance: If any opposing Magi is Cald, increase Karse's energize by two." --
//   energizeRateModifier, self-scoped (only Karse's own energize), checks every opposing player's
//   active Magi for the Cald region.
//   "Fury: Each of your Orothe and Universal cards that costs seven or more energy costs three
//   less energy to play." -- costModifier, own controller, printed cost >= 7 (the card's own
//   printed `cost`, unaffected by other modifiers -- matches every other cost-threshold card in
//   this codebase, which reads the printed value, not a live recomputed one).

import { registerCardEffect } from './registry.js';

registerCardEffect('Karse', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Vengeance is the +2 self-only
  // energize bonus when any opposing Magi is Cald; Fury is the -3 cost discount on own
  // Orothe/Universal cards printed >= 7.
  effectHooks: {
    Vengeance: ['energizeRateModifier'],
    Fury: ['costModifier'],
  },
  energizeRateModifier: (state, cardDb, energizing, self) => {
    if (energizing.instanceId !== self.instanceId) return 0;
    for (const [playerId, player] of state.players) {
      if (playerId === self.controllerId) continue;
      const magiDef = player.activeMagi && cardDb.get(player.activeMagi.definitionKey);
      if (magiDef?.regions.includes('Cald')) return 2;
    }
    return 0;
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    if (!playedDef.regions.some((r) => r === 'Orothe' || r === 'Universal')) return 0;
    const printedCost = typeof playedDef.cost === 'number' ? playedDef.cost : 0;
    return printedCost >= 7 ? -3 : 0;
  },
});
