// Orothean Horn -- "Call of the Sea: Use this Power only after your Play Creatures Step, and only
// if you have no Creatures in play. Place the top card of your deck into your discard pile. If the
// card is a Creature, discard Orothean Horn from play. Play the Creature with its starting energy,
// ignoring all costs. While it remains in play, the Creature cannot attack." Fully automatic -- no
// player choice at all, since which card is on top of the deck isn't something the player picks.
// "After your Play Creatures Step" -> legalPhases: ['prs2'] (the only Powers-usable phase after
// playNewCreatures). The "cannot attack while it remains in play" clause is an official 2i Design
// errata (data-pipeline/output/rulings.json, applied 2026-07-09) -- a PERMANENT restriction (not
// "this turn only"), so it's added via addPermanentTag onto CardInstance.tags rather than the
// turn-expiring durationTags array -- combat.ts's isLegalAttack already checks both.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay, discardTopOfDeck, playFromZone } from '../effects.js';
import { addPermanentTag, CANNOT_ATTACK } from '../durationTags.js';

registerCardEffect('Orothean Horn', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  legalPhases: ['prs2'],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Call of the Sea') return;
    if (creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).length > 0) return;

    const card = discardTopOfDeck(ctx.state, ctx.controllingPlayer);
    if (!card) return;
    if (ctx.cardDb.get(card.definitionKey)?.card_type !== 'Creature') return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'discardPile', instanceId: card.instanceId },
      ctx.controllingPlayer,
      effectiveStartingEnergy(ctx.state, ctx.cardDb, card)
    , ctx.rng);
    if (played) addPermanentTag(ctx.state, ctx.cardDb, played, CANNOT_ATTACK);
  },
});
