// Mydra -- both printed clauses:
//   "Watchful: Mydra loses only one energy whenever it is attacked." Caps the locked attacker
//   energy at 1 rather than reducing it by a flat amount.
//   "Dreamwarp: As you play Mydra, increase or decrease its starting energy by up to one, until
//   the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';

registerCardEffect('Mydra', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Watchful owns the combat-loss cap
  // (both the ordering-declaration data field and the onAttack cap itself, per Q4 data-field
  // rulings). Dreamwarp owns the dreamwarpRange data field.
  effectHooks: {
    Watchful: ['appliesCombatLossCap', 'onAttack'],
    Dreamwarp: ['dreamwarpRange'],
  },
  // Ordering declaration only -- see registry.ts. This card CAPS combat loss, so it resolves
  // after every flat reduction (owner ruling 2026-07-27).
  appliesCombatLossCap: true,
  onAttack: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.min(ctx.locked.attackerEnergy, 1);
  },
  dreamwarpRange: () => 1,
});
