// Rokarum -- "White Wind (2): Add two energy to each of your other Kybar's Teeth Creatures with
// less than their starting energy."

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions, regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Rokarum', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'White Wind') return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      if (creature.instanceId === ctx.source.instanceId) continue;
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, "Kybar's Teeth"))) continue;
      if ((creature.currentEnergy ?? 0) < effectiveStartingEnergy(ctx.state, ctx.cardDb, creature)) {
        addEnergy(ctx.state, ctx.cardDb, creature, 2, 'power');
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Also switched the raw def.regions check to
  // effectiveRegions() while here, same class of fix as Rumble Stones.
  specifiedTargetRegions: () => ["Kybar's Teeth"],
});
