// Pharan -- "Healing Rain: Choose any one Creature or Magi in play. Move up to three energy from
// Pharan to the chosen Creature or Magi. Discard Pharan from play." The cap is an official 2i
// Design errata (data-pipeline/output/rulings.json, applied 2026-07-09) -- previously this moved
// (as an addEnergy conjuring energy from nowhere, not even a real move) ALL of Pharan's current
// energy uncapped. Now uses rearrangeEnergy (a real move, draining Pharan) capped at 3, done BEFORE
// the discard (matching the errata's own stated order) -- a self-target (Pharan choosing itself)
// is a harmless no-op under rearrangeEnergy's from===to case, so no special-casing needed.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardFromPlay, rearrangeEnergy } from '../effects.js';

registerCardEffect('Pharan', {
  powerAmountChoices: (state, cardDb, playerId, powerName, source) => {
    if (powerName !== 'Healing Rain') return undefined;
    const max = Math.min(3, source.currentEnergy ?? 0);
    return [{ id: 'move', prompt: `Healing Rain: move how much energy from Pharan? (0-${max})`, min: 0, max }];
  },
  powerTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Healing Rain') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;

  // Task #532 (2026-07-26): "up to N" is a PLAYER CHOICE of 0..N, not N. This used to hard-code the
  // maximum (playtest: Giant Arboll "automatically is moving the max energy instead of giving a
  // picker"). `?? cap` keeps the old max as the fallback when no amount was supplied, so the engine
  // half is safe on its own -- an absent choice behaves exactly as before rather than moving 0.
    const cap = Math.min(3, ctx.source.currentEnergy ?? 0);
    const amount = Math.max(0, Math.min(ctx.chosenAmounts?.['move'] ?? cap, cap));
    if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, ctx.source, target, amount, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
  },
});
