// Delia -- both printed pieces:
//   "Recurring Dreams (1): Choose any one Vellup in your discard pile. Put the chosen Vellup into
//   your hand." Same shape as Sperri's Preserve, filtered to "Vellup" type instead of "Furok".
//   "Strengthen: Whenever you play a Vellup, add one energy to it." Re-verified 2026-07-15 (task
//   #29) -- this does NOT need a new "onPlayCreature" hook as an earlier pass assumed: the
//   existing `onPlay` broadcast already fires for every play, so a plain `creatureType` filter
//   inside it is enough (same pattern this file already uses for the Power's own filter).

import { registerCardEffect } from './registry.js';
import { creatureType } from '../targeting.js';
import { retrieveFromDiscardPile, addEnergy } from '../effects.js';

registerCardEffect('Delia', {
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => creatureType(cardDb, card.definitionKey) === 'Vellup',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Recurring Dreams') return;
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    if (!card || creatureType(ctx.cardDb, card.definitionKey) !== 'Vellup') return;
    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'hand');
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (creatureType(cardDb, played.definitionKey) !== 'Vellup') return;
    addEnergy(state, cardDb, played, 1, 'effect');
  },
});
