// Boil (Spell, Orothe, cost 5) -- "Choose any one Magi in play. Discard one energy from each of the
// chosen Magi's Creatures in play. Discard two additional energy from each of the chosen Magi's
// Orothe and Bograth Creatures in play." Pure discard sweep, no per-player choice needed.
//
// "Cald Magi may play still Spell without a regional penalty" -- confirmed OCR garble (project
// owner, 2026-07-24) for "Cald Magi may play THIS Spell without a regional penalty." A Cald Magi
// playing an Orothe Spell defaults to Tier 1 (regionalPenalty=1, regions.ts's checkRegionLegality);
// registry.ts's selfCostAdjustment (a card's own printed text adjusting ITS OWN cost, checked once
// against the card being played, not broadcast-scanned like costModifier) applies a flat -1 when the
// ACTING player's own Magi is Cald -- since totalCost = baseCost + regionalPenalty
// (play.ts#isLegalToPlay), a -1 to baseCost exactly cancels the +1 penalty, netting the same total
// cost as "no regional penalty" without needing to touch regionCheck itself.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, creaturesControlledBy, effectiveRegions } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Boil', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const targetMagi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!targetMagi) return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, targetMagi.controllerId)) {
      const regions = ctx.cardDb.get(creature.definitionKey)?.regions ?? [];
      const amount = regions.includes('Orothe') || regions.includes('Bograth') ? 3 : 1;
      discardEnergy(ctx.state, ctx.cardDb, creature, amount, 'spell', undefined, ctx.rng);
    }
  },
  selfCostAdjustment: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player?.activeMagi) return 0;
    return effectiveRegions(state, cardDb, player.activeMagi).includes('Cald') ? -1 : 0;
  },
});
