// Magma Hyren -- two fixed-cost, single-target Powers sharing the same target pool (any Creature
// in play, either player's):
//   "Fireball (1): Choose any one Creature in play. Discard one energy from the chosen Creature."
//   "Healing Flame (1): Choose any one Creature in play. Add two energy to the chosen Creature."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Magma Hyren', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- Fireball only (it discards
  // energy); Healing Flame adds energy, Dreamburn doesn't cover it, stays untouched.
  powerTargets: (state, cardDb, playerId, powerName) =>
    powerName === 'Fireball' ? flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)) : allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Fireball' && ctx.powerName !== 'Healing Flame') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    if (ctx.powerName === 'Fireball') {
      // task #34, 2026-07-16: Abraxin's Crown's Dreamburn covers this DISCARD Power.
      if (!isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
      discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
    } else {
      // Dreamburn only covers energy-DISCARD Powers, not this ADD Power -- stays Creature-only.
      if (ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
      addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
    }
  },
});
