// Greater Gargagnor -- "Unearth: Discard a card from your hand. Search your discard pile for any
// one Kybar's Teeth card and place it into your hand." RECLASSIFIED while implementing this batch:
// despite being surveyed into the play-bypass bucket (its passive "Expect It" Effect text matches
// "ignoring all costs"), the printed POWER itself is a plain hand-discard-cost +
// discard-pile-search-to-hand card, the exact shape already built for Sperri/Delia/Bog Stone in
// the discard-pile-retrieval bucket -- no play-bypass machinery needed at all. Also
// "Invulnerability: loses one less energy in attacks" (invulnerability.ts). Remaining passive
// Effects ("Expect It" -- play instead of discard if targeted by an opposing discard effect;
// "Solid" -- can't be Spell-discarded) are the separate, already-tracked passive/triggered-effect
// gap (task #26).

import { registerCardEffect } from './registry.js';
import { discardFromHand, retrieveFromDiscardPile } from '../effects.js';
import { applyInvulnerability } from './invulnerability.js';
import { regionForTargetFilter } from '../targeting.js';

registerCardEffect('Greater Gargagnor', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Only Invulnerability is built here
  // (onAttack). Expect It and Solid are still on task #26's passive/triggered-effect gap and
  // have no hooks on this entry -- listing them with an empty array so a Taglat copy runs
  // nothing, rather than falling back to whole-card (which would surface the Unearth-Power
  // machinery via any shared hook name reuse). Unearth itself is a Power, surfaced separately
  // via Taglat's Power branch.
  effectHooks: {
    'Expect It': [],
    Solid: [],
    Invulnerability: ['onAttack'],
  },
  handDiscardCost: { count: 1 },
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return !!def && def.regions.includes(regionForTargetFilter(state, "Kybar's Teeth"));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Unearth') return;
    const handIds = ctx.chosenHandCardIds ?? [];
    if (handIds.length !== 1) return;
    if (!ctx.controllingPlayer.hand.some((c) => c.instanceId === handIds[0])) return;
    const pileIds = ctx.chosenDiscardPileIds ?? [];
    if (pileIds.length !== 1) return;
    const [pileId] = pileIds;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === pileId);
    if (!card || !ctx.cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(ctx.state, "Kybar's Teeth"))) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, handIds, undefined, ctx.rng);
    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, pileId!, 'hand');
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (handDiscardCost above has no region filter of its own.)
  specifiedTargetRegions: () => ["Kybar's Teeth"],
});
