// Fire Chogo -- "Heat Storm: Discard Fire Chogo from play to discard one energy from each
// non-Cald Creature in play." Self-discard framed as the activation cost, no target picker.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Fire Chogo', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Heat Storm') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Cald'))) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Cald'],
});
