// Culla -- "Surround: Whenever one of your Creatures in play attacks a stalked Creature, add one
// energy to the attacking Creature before energy is removed." Real energy add -> onBeforeEnergyRemoved,
// same "combat-time real mutation" timing as Junjertrug's Rage.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { STALKED, hasDurationTag } from '../durationTags.js';

registerCardEffect('Culla', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (!ctx.defender || !hasDurationTag(ctx.defender, STALKED)) return;
    addEnergy(ctx.state, ctx.cardDb, ctx.attacker, 1, 'effect');
  },
});
