// Traitor's Reach (Universal Spell, cost 2) -- "Choose a Creature and a Magi controlled by the same
// player. If the chosen Creature does not share a region with the chosen Magi, discard that
// Creature from play and remove two energy from that Magi."
//
// Weave + Universal Spell pass, Category B (2026-07-27). Two picks (spellSecondTargets, Abwyn's
// Gift precedent), with the second pool CONSTRAINED by the first: "controlled by the same player"
// is a targeting restriction, not a resolution-time condition, so spellSecondTargets filters to the
// chosen Creature's own controller's Magi rather than offering every Magi and failing later.
//
// The region comparison goes through `effectiveRegions` on BOTH sides, which is the whole point of
// the card in a format full of region-shifting: a Naroom Creature that Yog's Turn has made Bograth
// really is a traitor to a Naroom Magi, and a Creature whose Magi has been re-regioned really is
// not. Reading printed `def.regions` here would silently invert both cases.
//
// "Does not share a region" -- a multi-region Creature is safe if ANY of its regions matches any of
// the Magi's. Both clauses fire together or not at all; there is no partial resolution.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, discardEnergy } from '../effects.js';
import { allCreaturesInPlay, allMagiInPlay, effectiveRegions, findInPlayById } from '../targeting.js';

registerCardEffect("Traitor's Reach", {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- reads the already-chosen
  // Creature+Magi pair the same way resolveSpell re-validates it (same controller, regions do
  // NOT overlap), no execution. Note this card's Creature-side hit is a full `discardFromPlay`,
  // not energy loss -- exactly why THREE_LEAF_CLOVER_PROTECTED is also checked at the
  // discardFromPlay choke point, not just discardEnergy's.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options) => {
    const creatureId = options.chosenTargetId as string | undefined;
    const magiId = options.chosenSecondTargetId as string | undefined;
    if (!creatureId || !magiId) return false;
    const creature = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === creatureId);
    const magi = allMagiInPlay(state).find((m) => m.instanceId === magiId);
    if (!creature || !magi) return false;
    if (magi.controllerId === actingPlayerId) return false;
    if (creature.controllerId !== magi.controllerId) return false;
    const magiRegionList = effectiveRegions(state, cardDb, magi);
    const shares = effectiveRegions(state, cardDb, creature).some((r) => magiRegionList.includes(r));
    return !shares;
  },
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellSecondTargets: (state, cardDb, _playerId, _sourceInstanceId, firstChosenId) => {
    const creature = firstChosenId ? findInPlayById(state, firstChosenId) : undefined;
    if (!creature) return [];
    return allMagiInPlay(state).filter((m) => m.controllerId === creature.controllerId);
  },
  resolveSpell: (ctx) => {
    const creature = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    const magi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenSecondTargetId);
    if (!creature || !magi) return;
    if (creature.controllerId !== magi.controllerId) return; // re-validated, not trusted from the UI

    const magiRegions = effectiveRegions(ctx.state, ctx.cardDb, magi);
    const shares = effectiveRegions(ctx.state, ctx.cardDb, creature).some((r) => magiRegions.includes(r));
    if (shares) return;

    const owner = ctx.state.players.get(creature.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, creature.instanceId, undefined, 'spell', ctx.rng);
    discardEnergy(ctx.state, ctx.cardDb, magi, 2, 'spell', undefined, ctx.rng);
  },
});
