// Garlak -- "Cold Burn: At the beginning of your turn, choose a Creature. Discard one energy from
// the chosen Creature. Discard two additional energy if that Creature is frozen." No "your"/
// "opposing" qualifier in the printed text -- either side is a legal choice.
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "auto-picks an opposing Creature,
// preferring a frozen one" simplification with a real pending choice (registry.ts's
// pendingTargetChoice/resolveTargetChoice) -- the pool is now every Creature in play, either
// side, matching the printed text's lack of a qualifier; the amount discarded still depends on
// whether the CHOSEN Creature happens to be frozen, resolved at choice time.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { isFrozen } from '../durationTags.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const COLD_BURN_PENDING = 'garlakColdBurnPending';

registerCardEffect('Garlak', {
  onOwnTurnStart: (state, cardDb, self) => {
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, COLD_BURN_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(COLD_BURN_PENDING)) return undefined;
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Garlak's Cold Burn: choose a Creature to discard 1 energy from (2 additional if frozen)", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, COLD_BURN_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, isFrozen(state, cardDb, target) ? 3 : 1, 'effect', undefined, rng);
  },
});
