// Crushing Vines (Spell, Paradwyn, cost 4) -- "Choose any one Creature in play. Remove four energy
// from the chosen Creature. If the chosen Creature is discarded from play, until the end of your
// turn, all of that player's Creatures are stalked; whenever a stalked Creature is attacked,
// discard one energy from the stalked Creature before energy is removed. Only Paradwyn Magi and
// Paradwyn Shadow Magi can play Crushing Vines." The Magi-restriction clause needs no code here --
// `region_restrictive: true` + `shadow_play: "Paradwyn"` are already set on this card's own data
// (part of the "Crushing [Element]" cycle regions.ts's checkRegionLegality/isExemptFromRestriction
// already handle generically). Re-confirms the target actually left play (Crushing Surf precedent)
// before applying the STALKED sweep, rather than trusting a same-turn energy-4 prediction.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addDurationTag, STALKED } from '../durationTags.js';

registerCardEffect('Crushing Vines', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const targetOwnerId = target.controllerId;

    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);

    // "IF the chosen Creature is discarded from play" -- ask the DISCARD PILE, not "is it still in
    // play". #536 C6f (2026-07-27): see crushingStench.ts for the full reasoning. Kybar's Echo
    // returning the Creature to hand leaves it absent from play WITHOUT it having been discarded,
    // and the old presence poll fired the stalk clause anyway.
    const owner = ctx.state.players.get(targetOwnerId);
    const wasDiscarded = owner?.discardPile.some((c) => c.instanceId === ctx.chosenTargetId) ?? false;
    if (!wasDiscarded) return; // survived the discard, or was replaced out of play -- no stalk clause

    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, targetOwnerId)) {
      addDurationTag(ctx.state, ctx.cardDb, creature, STALKED, ctx.state.turnNumber);
    }
  },
});
