// Magam's Ring -- "Rebirth: As one of your Cald Creatures is discarded from play on an opponent's
// turn, you may discard Magam's Ring to restore the Creature to its starting energy instead." The
// discarded Creature is already in the discard pile by the time this hook fires (both
// onCardDiscardedFromPlay paths move the card there first) -- "restore... instead" is implemented
// as pulling it back out via playFromZone, same "discard pile -> play" primitive Remember Ring
// already uses.
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice`. The discarded Creature
// is remembered via an embedded-id permanent tag (same technique as Reef Hyren/Skullek/Wellisk/
// Ahron/Gloves of Crystal/Hubram in this same batch) since the resolve call has no target
// parameter.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, playFromZone } from '../effects.js';
import { effectiveRegions, effectiveStartingEnergy } from '../targeting.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const PENDING_PREFIX = 'magamsRingPending:';

function pendingDiscardedId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return tag.slice(PENDING_PREFIX.length);
  }
  return undefined;
}

function findInDiscardPile(state: Parameters<typeof playFromZone>[0], playerId: string, instanceId: string) {
  return state.players.get(playerId)?.discardPile.find((c) => c.instanceId === instanceId);
}

registerCardEffect("Magam's Ring", {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discardedOwnerId !== self.controllerId) return;
    if (state.activePlayerId === self.controllerId) return; // must be an opponent's turn
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(state, cardDb, discarded).includes('Cald')) return;
    if (!findInDiscardPile(state, discardedOwnerId, discarded.instanceId)) return;
    addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${discarded.instanceId}`);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    const discardedId = pendingDiscardedId(self);
    if (discardedId === undefined) return undefined;
    if (!findInDiscardPile(state, self.controllerId, discardedId)) return undefined;
    return {
      prompt: "Magam's Ring's Rebirth: discard Magam's Ring to restore the Creature to its starting energy instead?",
      yesLabel: 'Discard Ring, restore Creature',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const discardedId = pendingDiscardedId(self);
    if (discardedId !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${discardedId}`);
    if (!chosenBoolean || discardedId === undefined) return;
    const player = state.players.get(self.controllerId);
    const discarded = discardedId !== undefined ? findInDiscardPile(state, self.controllerId, discardedId) : undefined;
    if (!player || !discarded) return;
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
    playFromZone(
      state,
      cardDb,
      { owner: player, zone: 'discardPile', instanceId: discarded.instanceId },
      player,
      effectiveStartingEnergy(state, cardDb, discarded),
      rng
    );
  },
});
