// Xandia -- "Burning Desire (3): Discard a Cald Creature from your hand. Choose an opposing
// Creature and remove energy from it equal to the starting energy of the Creature you discarded.
// This energy loss may not be modified." (The last sentence is a static "can't be modified"
// clause -- nothing in this engine currently implements loss-modifying effects, so it's a no-op
// by omission, same reasoning as Shock Vashp's identical clause.)

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';
import { discardEnergy, discardFromHand } from '../effects.js';

registerCardEffect('Xandia', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)),
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, 'Cald'));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Burning Desire') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandCardIds![0]);
    const discardedDef = discardedCard ? ctx.cardDb.get(discardedCard.definitionKey) : undefined;
    if (!discardedDef || discardedDef.card_type !== 'Creature' || !discardedDef.regions.includes(regionForTargetFilter(ctx.state, 'Cald'))) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;

    const amount = effectiveStartingEnergy(ctx.state, ctx.cardDb, discardedCard!);
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    discardEnergy(ctx.state, ctx.cardDb, target, amount, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Cald'],
});
