// Carillion -- "Resilience: If Carillion attacks a Creature that starts the attack with less than
// three energy, Carillion loses no energy in the attack." Self as the attacker, reads the
// defender's energy at the moment onAttack fires (before locked energy is computed). Zeroes
// `ctx.locked.defenderEnergy`, not `attackerEnergy` -- see mowat.ts's doc comment for why (each
// side's locked value is what the OTHER side loses).

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';

registerCardEffect('Carillion', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    if ((ctx.defender.currentEnergy ?? 0) >= 3) return;

    if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = 0;
  },
});
