// Thin Ice (Spell) -- "Add one energy to each of your frozen Creatures. Remove one energy from
// each opposing frozen Creature." Nar Spell pass, Category A (2026-07-22). No target -- a plain
// board-wide loop using the existing isFrozen(state, cardDb, instance) reader, same shape as any
// other unconditional "all X Creatures" Spell.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingCreatures } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Thin Ice', {
  resolveSpell: (ctx) => {
    for (const c of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      if (isFrozen(ctx.state, ctx.cardDb, c)) addEnergy(ctx.state, ctx.cardDb, c, 1, 'spell');
    }
    for (const c of opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      if (isFrozen(ctx.state, ctx.cardDb, c)) discardEnergy(ctx.state, ctx.cardDb, c, 1, 'spell', undefined, ctx.rng);
    }
  },
});
