// Grega -- "Thermal Blast (2): Roll one die. Choose any one Creature or Magi in play. Discard
// energy equal to the die roll from the chosen Creature or Magi." Same named Power as Drakan and
// Grega's Ring, but each is a distinct card with its own registration (registry is keyed by card
// name).
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';

registerCardEffect('Grega', {
  powerTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Thermal Blast') return;
    if (ctx.chosenTargetId === undefined) return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'grega:thermalBlast',
      { chosenTargetId: ctx.chosenTargetId },
      ctx.rng
    );
  },
});

registerRollConsumer('grega:thermalBlast', (state, cardDb, _source, payload, finalRoll, rng) => {
  const { chosenTargetId } = payload as { chosenTargetId: string };
  const target = findCreatureOrMagiById(state, chosenTargetId);
  if (!target) return;
  discardEnergy(state, cardDb, target, finalRoll, 'power', undefined, rng);
});
