// Gremm's Helmet -- "Mimic: Choose any one opposing Magi in play. Your Magi gains all Powers and
// Effects on the chosen Magi until the beginning of your next turn." Unlike Taglat/K'teeb/Nahara
// (which copy onto THEMSELVES), the copied Powers/Effects land on the CONTROLLER'S MAGI, not on
// Gremm's Helmet -- the Relic is just the trigger. No "cannot copy a Power/Effect it already has"
// restriction is stated in this card's text (unlike Taglat/K'teeb), so none is enforced. The
// Powers ride copiedPowers.ts's whole-Power copy; the Effects ride grantedEffects.ts's whole-card
// grant (built S8/C3 2026-08-12) -- the exact whole-Magi shape grantedEffects.ts was designed for.
// Q2/Q3 apply: no dedupe on grants (§3.4 test-verified the "doubles up" premise was wrong), and
// Q5's `findPower` fourth arm carries any donor `syntheticPowers` (Gia's Tome's Research, Bottled
// City's Release) through the grant automatically.

import { registerCardEffect } from './registry.js';
import { opposingMagi } from '../targeting.js';
import { addCopiedPower } from '../copiedPowers.js';
import { addGrantedEffect } from '../grantedEffects.js';
import { beginningOfNextOwnTurnNumber } from '../durationTags.js';

registerCardEffect("Gremm's Helmet", {
  powerTargets: (state, cardDb, playerId) => opposingMagi(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mimic') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = opposingMagi(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (m) => m.instanceId === ctx.chosenTargetId
    );
    const myMagi = ctx.controllingPlayer.activeMagi;
    if (!target || !myMagi) return;
    const def = ctx.cardDb.get(target.definitionKey);
    if (!def) return;

    const expiry = beginningOfNextOwnTurnNumber(ctx.state);
    for (const power of def.powers) {
      addCopiedPower(myMagi, power, def.key, { afterTurnNumber: expiry });
    }
    addGrantedEffect(myMagi, def.key, { afterTurnNumber: expiry });
  },
});
