// Malevolent Corf -- "Skulk (1): Choose an opposing Orothe Creature and remove one energy from
// it. Place that Creature's remaining energy on its Magi and return it to its owner's hand."

import { registerCardEffect } from './registry.js';
import { effectiveRegions, opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy, returnToHand } from '../effects.js';

registerCardEffect('Malevolent Corf', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)).filter(
      (c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Orothe'))
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Skulk') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Orothe'))) return;

    discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
    const remaining = target.currentEnergy ?? 0;
    const controller = ctx.state.players.get(target.controllerId);
    const owner = ctx.state.players.get(target.ownerId); // "return it to its OWNER's hand"
    if (!controller || !owner) return;
    if (remaining > 0 && controller.activeMagi) addEnergy(ctx.state, ctx.cardDb, controller.activeMagi, remaining, 'power');
    returnToHand(ctx.state, ctx.cardDb, owner, target.instanceId);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Orothe'],
});
