// Stalker's Boots -- "Stalk (1): Until the end of your turn, whenever one of your Creatures is
// attacking, the defending Creature is stalked; whenever a stalked Creature is attacked, discard
// one energy from the stalked Creature before energy is removed." Doesn't need to actually TAG
// the defender as STALKED (which would outlive the single attack it applies to) -- the whole
// clause just describes "this specific attack's defender takes 1 extra energy loss," so the
// onAttack hook applies that discard directly. Uses a card-specific turn-scoped marker (not a
// shared tag) on Stalker's Boots itself, read by its own onAttack hook -- registry.ts's existing
// hook, no new engine mechanism.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const BOOTS_ACTIVE = 'stalkersBootsActive';

registerCardEffect("Stalker's Boots", {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Stalk') return;
    addDurationTag(ctx.state, ctx.cardDb, ctx.source, BOOTS_ACTIVE, ctx.state.turnNumber);
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!hasDurationTag(self, BOOTS_ACTIVE)) return;
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (ctx.defender === null) return;
    discardEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect', undefined, ctx.rng);
  },
});
