// Baldar Amulet -- both printed clauses, built task #42, 2026-07-17, the Kybar's Teeth region pass:
//   "Affinity: Baldars cost you one less to play, to a minimum of one." Trivial costModifier,
//   name-substring "Baldar," own side only.
//   "Hammer: Once per turn, after one of your Baldars is discarded from play by an opposing
//   Creature or Relic, you may discard a card from your hand. If you do, discard the opposing card
//   from play." `onCardDiscardedFromPlay` doesn't carry the instigating card's INSTANCE (only
//   `causedByPlayerId` and, via `state.currentAction`, the source's `sourceDefinitionKey`) -- "an
//   opposing Creature or Relic" specifically (as opposed to a Spell/Magi-text) isn't tracked at
//   this granularity, so this is simplified to "any opposing-caused discard," same class of
//   documented simplification as Oranragan's Vengeance. `sourceDefinitionKey` is captured into an
//   embedded-id tag AT TRIGGER TIME (Venger's technique), not re-read from `state.currentAction` at
//   resolution time -- that field is transient (overwritten by whatever action runs next) and would
//   be stale by the time a post-hoc pending choice actually resolves. "You may discard a card from
//   your hand" is a real WHICH-card choice, not a plain yes/no -- built via `pendingTargetChoice`/
//   `resolveTargetChoice` with the pool set to the controller's own hand (declining is
//   `chosenInstanceId === undefined`), same shape used elsewhere in this codebase for a "choose
//   from my own hand" cost. The retaliation target is resolved by matching the captured
//   `sourceDefinitionKey` against an in-play card on the opponent's side (first match, same "no
//   safe default but a rational one" convention used throughout this codebase for array-order
//   picks) -- if that lookup fails (source already left play, or wasn't a Creature/Relic at all),
//   the discard-from-hand still happens (matching the printed "if you do" phrasing) but no
//   retaliation occurs.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, removePermanentTag, hasDurationTag, addDurationTag } from '../durationTags.js';
import { discardFromHand, discardFromPlay } from '../effects.js';

const HAMMER_PENDING_PREFIX = 'baldarAmuletHammerPending:'; // suffix: sourceDefinitionKey, or 'none'
const HAMMER_USED_THIS_TURN = 'baldarAmuletHammerUsedThisTurn';

function pendingSourceKey(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(HAMMER_PENDING_PREFIX)) return tag.slice(HAMMER_PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Baldar Amulet', {
  // Per-Effect hook narrowing (deep-dive audit, 2026-08-13). Affinity is the Baldar cost
  // discount; Hammer is the reactive retaliation on an opposing-caused Baldar discard.
  effectHooks: {
    Affinity: ['costModifier'],
    Hammer: ['onCardDiscardedFromPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return /\bBaldar/.test(playedDef.name) ? -1 : 0;
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discardedOwnerId !== self.controllerId) return;
    if (!/\bBaldar/.test(cardDb.get(discarded.definitionKey)?.name ?? '')) return;
    if (causedByPlayerId === undefined || causedByPlayerId === self.controllerId) return;
    if (hasDurationTag(self, HAMMER_USED_THIS_TURN)) return;
    if (pendingSourceKey(self) !== undefined) return; // already armed
    const sourceKey = state.currentAction?.sourceDefinitionKey;
    addPermanentTag(state, cardDb, self, `${HAMMER_PENDING_PREFIX}${sourceKey ?? 'none'}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const sourceKey = pendingSourceKey(self);
    if (sourceKey === undefined) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player || player.hand.length === 0) return undefined;
    return { prompt: "Baldar Amulet's Hammer: discard a card from your hand to discard the opposing card that caused this?", pool: player.hand };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const sourceKey = pendingSourceKey(self);
    if (sourceKey === undefined) return;
    removePermanentTag(self, `${HAMMER_PENDING_PREFIX}${sourceKey}`);
    addDurationTag(state, cardDb, self, HAMMER_USED_THIS_TURN, state.turnNumber);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    discardFromHand(state, cardDb, player, [chosenInstanceId]);

    if (sourceKey === 'none') return;
    const key = Number(sourceKey);
    for (const opponent of state.players.values()) {
      if (opponent.playerId === self.controllerId) continue;
      const target = opponent.inPlay.find((c) => c.definitionKey === key);
      if (target) {
        discardFromPlay(state, cardDb, opponent, target.instanceId, undefined, undefined, rng);
        return;
      }
    }
  },
});
