// Boria -- "Dreamwarp: As an opposing player plays a Creature, increase or decrease its starting
// energy by up to one until the end of the turn, to a minimum starting energy of one. This Effect
// cannot raise a Creature's starting energy above the amount of energy on that player's Magi." A
// REACTIVE grant (registry.ts's reactiveDreamwarpRange/resolveReactiveDreamwarp doc comments),
// scoped to OPPOSING plays only (relative to Boria's own controller) -- unlike Jungle Hyren, no
// "once per turn" limit is printed. Same "the Magi cap only restricts raising" reasoning as Jungle
// Hyren for why `max` never falls below `current`.

import { registerCardEffect } from './registry.js';
import { applyReactiveDreamwarp } from '../effects.js';

registerCardEffect('Boria', {
  reactiveDreamwarpRange: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return undefined; // must be an OPPOSING player's Creature
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return undefined;

    const current = played.currentEnergy ?? 0;
    const cap = state.players.get(played.controllerId)?.activeMagi?.currentEnergy ?? current;
    return {
      min: Math.max(1, current - 1),
      max: Math.max(current, Math.min(current + 1, cap)),
    };
  },
  resolveReactiveDreamwarp: (state, cardDb, played, self, chosenEnergy) => {
    applyReactiveDreamwarp(state, cardDb, played, chosenEnergy);
  },
});
