// Olum Mystic -- "Plague: At the end of each player's turn, that player chooses a non-Olum
// Creature. Discard one energy from the chosen Creature." Unusual among this bucket: the CHOOSING
// player is whoever's turn just ended, not necessarily Olum Mystic's own controller. Registers
// both onOwnTurnEnd (acting player = self's own controller) and onOpponentTurnEnd (acting player
// = the opponent) with bodies that differ only in who's deciding.
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first non-Olum Creature not
// controlled by the acting player" simplification with a real pending choice (registry.ts's
// pendingTargetChoice/resolveTargetChoice) over every non-Olum Creature in play. This is a shared
// hotseat game (per the project's Test Match mode), so presenting the choice generically -- not
// tracking exactly which player is "supposed" to answer -- is fine; whichever player's decision
// it is resolves it same as any other prompt.
//
// turnBoundaryCreatureTypes (Swirling Orshaa's Morph, Effect-half turn-boundary bucket,
// 2026-07-24) declares the "Olum" reference for previewIdentityOverrideOffersForTurnBoundary to
// read, offering a reactive Morph right before either turn-end sweep runs.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveCreatureType } from '../targeting.js';
import { addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const PLAGUE_PENDING = 'olumMysticPlaguePending';

// effectiveCreatureType (Swirling Orshaa's Morph, Effect-half turn-boundary bucket, 2026-07-24) --
// a morphed Orshaa becomes exempt from Plague the same way a printed Olum Creature is.
function plaguePool(state: GameState, cardDb: CardDatabase) {
  return allCreaturesInPlay(state, cardDb).filter((c) => effectiveCreatureType(cardDb, c) !== 'Olum');
}

function markPlaguePending(state: GameState, cardDb: CardDatabase, self: CardInstance): void {
  if (plaguePool(state, cardDb).length === 0) return;
  addPendingChoiceTag(self, PLAGUE_PENDING);
}

registerCardEffect('Olum Mystic', {
  onOwnTurnEnd: (state, cardDb, self) => markPlaguePending(state, cardDb, self),
  onOpponentTurnEnd: (state, cardDb, self) => markPlaguePending(state, cardDb, self),
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(PLAGUE_PENDING)) return undefined;
    const pool = plaguePool(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Olum Mystic's Plague: choose a non-Olum Creature to discard 1 energy from", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, PLAGUE_PENDING);
    if (!chosenInstanceId) return;
    const target = plaguePool(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 1, 'effect', undefined, rng);
  },
  turnBoundaryCreatureTypes: () => ['Olum'],
});
