// Velouria -- "Adore: Choose one of your Creatures. The chosen Creature can attack Magi directly
// this turn. When that Creature does, add energy to Velouria equal to the amount removed from the
// opposing Magi in the attack." Same shape as Groll the Fallen (a card-specific link tag read by
// an afterCombat hook) combined with the CAN_ATTACK_MAGI_DIRECTLY tag Flying Darbok/Icefang
// Battlesled/Olum Digger already use -- flagged in docs/deferred-card-mechanics.md as buildable
// once those existed, picked up now.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag, CAN_ATTACK_MAGI_DIRECTLY } from '../durationTags.js';

const VELOURIA_LINKED = 'velouriaLinked';

registerCardEffect('Velouria', {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Adore') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;

    addDurationTag(ctx.state, ctx.cardDb, target, CAN_ATTACK_MAGI_DIRECTLY, ctx.state.turnNumber);
    addDurationTag(ctx.state, ctx.cardDb, target, VELOURIA_LINKED, ctx.state.turnNumber);
  },
  afterCombat: (ctx, outcome, self) => {
    if (!hasDurationTag(ctx.attacker, VELOURIA_LINKED)) return;
    if (ctx.defender !== null) return; // "removed from the opposing MAGI" -- a direct Magi attack
    // "the amount removed from the opposing Magi" = the Magi's ACTUAL loss (fixed 2026-07-19):
    // outcome.magiEnergyLost accounts for overkill AND a Magi's own opposingEnergyLossCap (Myka's
    // Burrow), where the old min(attackerLockedEnergy, snapshot) only capped overkill.
    const actualRemoved = outcome.magiEnergyLost;
    if (actualRemoved > 0) addEnergy(ctx.state, ctx.cardDb, self, actualRemoved, 'effect');
  },
});
