// Desiccate (Spell) -- "Choose one of your Creatures. Discard one energy from the chosen Creature.
// If you do, choose a Creature in play. Discard all energy from the chosen Creature." Reuses
// spellTargets + spellSecondTargets (registry.ts, Abwyn's Gift/Sorreah's Dream precedent) purely
// for the two-sequential-single-target UI plumbing. IMPORTANT: unlike Abwyn's Gift, neither clause
// discards a Creature FROM PLAY directly -- both are pure discardEnergy calls, going through the
// normal reduction pipeline (BURROWED cap, Garan/T'lok/Rayje unreducible-loss blocks, etc.) exactly
// like any other energy-loss card. If the second target's energy hits 0, checkCreatureDefeats'
// normal energy-depletion path (already run by play.ts after every playCard) handles it -- calling
// discardFromPlay here would incorrectly trigger discard-from-play-specific immunities
// (canBeDiscardedFromPlay/preventsDiscardOf) that have nothing to do with energy loss.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';

registerCardEffect('Desiccate', {
  spellTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) =>
    allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== firstChosenId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const first = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!first || first.controllerId !== ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(first.definitionKey)?.card_type !== 'Creature') return;
    discardEnergy(ctx.state, ctx.cardDb, first, 1, 'spell', undefined, ctx.rng);

    if (ctx.chosenSecondTargetId === undefined || ctx.chosenSecondTargetId === ctx.chosenTargetId) return;
    const second = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (!second || ctx.cardDb.get(second.definitionKey)?.card_type !== 'Creature') return;
    discardEnergy(ctx.state, ctx.cardDb, second, second.currentEnergy ?? 0, 'spell', undefined, ctx.rng);
  },
});
