// Ripple (Spell, Orothe, cost 1) -- "All Creatures with less energy than their starting energy gain
// one energy. All Creatures with more energy than their starting energy lose one energy." A pure
// board sweep, no targeting -- printedStartingEnergy (targeting.ts, task #144's per-instance
// override) is the existing "a Creature's own starting energy" reader every comparable card already
// uses (Anarchy's restore-to-starting, Slime Stone's override).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveStartingEnergy } from '../targeting.js';

registerCardEffect('Ripple', {
  resolveSpell: (ctx) => {
    for (const target of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      const starting = effectiveStartingEnergy(ctx.state, ctx.cardDb, target);
      const current = target.currentEnergy ?? 0;
      if (current < starting) addEnergy(ctx.state, ctx.cardDb, target, 1, 'spell');
      else if (current > starting) discardEnergy(ctx.state, ctx.cardDb, target, 1, 'spell', undefined, ctx.rng);
    }
  },
});
