// Vaporize (Spell, Core) -- "Choose any one Magi in play. Discard one energy from the chosen Magi
// for each Relic he or she has in play. Discard all of that Magi's Relics from play." Task #53-4,
// 2026-07-21, the Core Spell pass's A1 quick wins.
//
// Plain single-target Spell (`spellTargets` -> `allMagiInPlay`, either side, no restriction) --
// `effectiveCardType` (via `allRelicsInPlay`) is reused so a Jingjack-toggled Creature-as-Relic still
// counts, matching every other Relic-counting card in this engine.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, allRelicsInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { getPlayer } from '../types/state.js';

registerCardEffect('Vaporize', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;

    const relics = allRelicsInPlay(ctx.state, ctx.cardDb).filter((r) => r.controllerId === target.controllerId);
    if (relics.length > 0) {
      discardEnergy(ctx.state, ctx.cardDb, target, relics.length, 'spell', undefined, ctx.rng);
    }
    const owner = getPlayer(ctx.state, target.controllerId);
    for (const relic of relics) {
      discardFromPlay(ctx.state, ctx.cardDb, owner, relic.instanceId, undefined, undefined, ctx.rng);
    }
  },
});
