// Pillar Hyren -- "Stabilize: As one of your Creatures is attacked, add one energy to it." A
// blanket defensive buff for every own Creature, real energy add -> onBeforeEnergyRemoved.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Pillar Hyren', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    addEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect');
  },
});
