// Grej -- both printed pieces:
//   "Toughen: Choose any one of your Underneath Creatures in play. Until the start of your next
//   turn, the chosen Creature gains 'Effect - Invulnerability: This Creature loses one less energy
//   in attacks.'" Uses durationTags.ts's INVULNERABLE tag (a TEMPORARY grant, checked generically
//   by combat.ts, distinct from the ~20 cards that print Invulnerability permanently).
//   "Kinship: Grej may play Underneath cards, ignoring regional penalties and restrictions." A
//   per-Magi personal region-legality override -- registry.ts's new `regionOverride` hook, checked
//   by play.ts's isLegalToPlay against the active Magi's own registered effect. Grej himself is
//   the granting card (a Magi's standing text, not a Relic), so this only needs to fire when
//   `magi` IS Grej.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions, findInPlayById, regionForTargetFilter } from '../targeting.js';
import { addDurationTag, INVULNERABLE, beginningOfNextOwnTurnNumber } from '../durationTags.js';
import { magiCountsAs } from './magiIdentity.js';

registerCardEffect('Grej', {
  powerTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Underneath'))),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Toughen') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Underneath'))) return;

    addDurationTag(ctx.state, ctx.cardDb, target, INVULNERABLE, beginningOfNextOwnTurnNumber(ctx.state), ctx.source.instanceId);
  },
  regionOverride: (state, cardDb, playedDef, magi) => magiCountsAs(cardDb, magi, 'Grej') && playedDef.regions.includes('Underneath'),
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Underneath'],
});
