// Corathan -- "Betrayal: Once per turn, whenever you gain control of an opposing card, choose any
// one Core or Orothe card in your discard pile and place it into your hand. Only one Betrayal may
// be used for each card you gain control of." A pure passive Effect, no printed Power. The
// "once per turn" cap is an official 2i Design errata (data-pipeline/output/rulings.json, applied
// 2026-07-09) -- previously this fired every single time control changed hands, even multiple
// times in one turn. Tracked via a card-scoped duration tag (expiring at the current turn number,
// same "this turn only" pattern as durationTags.ts's CAN_ATTACK_MAGI_DIRECTLY) rather than a
// shared constant, since it's specific to this one card's own trigger. ("Only one Betrayal per
// card gained" is already true for free -- onGainControl fires once per gainControl() call, never
// more than once for the same single control change.)
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first eligible in discard-pile order"
// simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice) -- the pool is discard-pile CARDS, not in-play Creatures, but
// pendingTargetChoice's pool type is plain CardInstance either way.

import { registerCardEffect } from './registry.js';
import { addDurationTag, addPermanentTag, addPendingChoiceTag, hasDurationTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const BETRAYAL_USED_THIS_TURN = 'corathanBetrayalUsedThisTurn';
const BETRAYAL_PENDING = 'corathanBetrayalPending';

function betrayalPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.discardPile.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return !!def && (def.regions.includes('Core') || def.regions.includes('Orothe'));
  });
}

registerCardEffect('Corathan', {
  onGainControl: (state, cardDb, gained, newControllerId, self) => {
    if (self.controllerId !== newControllerId) return;
    if (gained.ownerId === newControllerId) return;
    if (hasDurationTag(self, BETRAYAL_USED_THIS_TURN)) return;
    if (betrayalPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, BETRAYAL_PENDING);
    addDurationTag(state, cardDb, self, BETRAYAL_USED_THIS_TURN, state.turnNumber);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(BETRAYAL_PENDING)) return undefined;
    const pool = betrayalPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Corathan's Betrayal: choose a Core or Orothe card in your discard pile to return to hand", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, BETRAYAL_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const index = player.discardPile.findIndex((c) => c.instanceId === chosenInstanceId);
    if (index === -1) return;
    const [card] = player.discardPile.splice(index, 1);
    player.hand.push(card!);
  },
});
