// Bythan's Gift (Spell, cost 3) -- "If you have a Creature in play, choose any one Creature in
// play. Add seven energy to the chosen Creature. Return any one of your Creatures in play to your
// hand, discarding all of that Creature's energy." Naroom Spell pass, Category B (2026-07-23).
// Near-1:1 structural match with gorglesGift.ts (Cald Spell pass) -- same castability gate
// (spellTargets returns [] with no Creature in play), same spellSecondTargets two-independent-picks
// shape, addEnergy(7)/returnToHand swapped in for Cald's discardEnergy(7)/returnToHand.
// returnToHand already zeroes the returned card's energy, so "discarding all of that Creature's
// energy" needs no extra code.

import { registerCardEffect } from './registry.js';
import { addEnergy, returnToHand } from '../effects.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';

registerCardEffect("Bythan's Gift", {
  spellTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).length > 0 ? allCreaturesInPlay(state, cardDb) : [],
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => c.instanceId !== firstChosenId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined || ctx.chosenSecondTargetId === undefined) return;
    if (ctx.chosenTargetId === ctx.chosenSecondTargetId) return;
    const addTarget = findInPlayById(ctx.state, ctx.chosenTargetId);
    const returnTarget = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (!addTarget || ctx.cardDb.get(addTarget.definitionKey)?.card_type !== 'Creature') return;
    if (!returnTarget || returnTarget.controllerId !== ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(returnTarget.definitionKey)?.card_type !== 'Creature') return;

    addEnergy(ctx.state, ctx.cardDb, addTarget, 7, 'spell');

    const stillThere = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (stillThere) returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, stillThere.instanceId);
  },
});
