// Fiend of Furoks -- two printed clauses:
//   "Affinity: Fiend of Furoks ignores regional penalties and restrictions when playing Furoks." --
//   regionOverride, Furok-family match (word-boundary, same convention as Xyx/Bisiwog/Hyren
//   families elsewhere in this codebase).
//   "Reconstruct: Once per turn, you can play a Furok from your discard pile as if it were in your
//   hand, paying all costs." -- Built 2026-08-13 (deferred-list full re-audit, starter closure).
//   Sand Cape's Memory is the exact same "may play one <family> Creature from discard pile as if
//   it were in your hand, paying all costs" shape and is the pattern reused here -- armed by
//   `onOwnPlayCreaturesStepStart` at the phase boundary the player would use it, exposed via
//   `pendingTargetChoice`/`resolveTargetChoice`, resolved through `playFromZonePayingCost` (the
//   existing Looph/Black Stuff/Sand Cape primitive that moves the card back to hand, runs the full
//   legality check, and plays it normally paying real costs). Reconstruct differs from Sand Cape's
//   Memory only in that the "once per turn" gate lives on the Magi via a duration tag stamped
//   AFTER a successful resolve -- skipping does NOT consume the ability. The prior file comment
//   claimed Reconstruct needed "a standing action, not a reactive hook or a costed Power" -- stale;
//   the phase-boundary offer is exactly what Sand Cape shipped in Layer 2 of the discard-pile-
//   visibility project (task #350, 2026-07-20), which unblocked this whole shape.

import { registerCardEffect } from './registry.js';
import { magiCountsAs } from './magiIdentity.js';
import { getPlayer } from '../types/state.js';
import { playFromZonePayingCost } from '../play.js';
import { addDurationTag, hasDurationTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const FUROK_FAMILY = /\bFurok\b/;
const RECONSTRUCT_PENDING = 'fiendOfFuroksReconstructPending';
const RECONSTRUCT_USED_THIS_TURN = 'fiendOfFuroksReconstructUsedThisTurn';

function reconstructPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = getPlayer(state, self.controllerId);
  return player.discardPile.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return def?.card_type === 'Creature' && FUROK_FAMILY.test(def.name);
  });
}

registerCardEffect('Fiend of Furoks', {
  // Per-Effect hook narrowing (E1, 2026-08-12; Reconstruct added 2026-08-13). A Taglat copy of
  // one Effect must NOT drag the other's hooks along, so both named Effects are listed here with
  // their exact hook keys.
  effectHooks: {
    Affinity: ['regionOverride'],
    Reconstruct: ['onOwnPlayCreaturesStepStart', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  regionOverride: (state, cardDb, playedDef, magi) =>
    magiCountsAs(cardDb, magi, 'Fiend of Furoks') && FUROK_FAMILY.test(playedDef.name),
  onOwnPlayCreaturesStepStart: (state, cardDb, self) => {
    if (hasDurationTag(self, RECONSTRUCT_USED_THIS_TURN)) return;
    if (reconstructPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, RECONSTRUCT_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(RECONSTRUCT_PENDING)) return undefined;
    const pool = reconstructPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Fiend of Furoks' Reconstruct: choose a Furok in your discard pile to play, paying all costs", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, RECONSTRUCT_PENDING);
    if (!chosenInstanceId) return;
    const player = getPlayer(state, self.controllerId);
    if (!reconstructPool(state, cardDb, self).some((c) => c.instanceId === chosenInstanceId)) return;
    const played = playFromZonePayingCost(state, cardDb, player, 'discardPile', chosenInstanceId, {}, rng);
    // Stamp the once-per-turn tag only on a successful play -- if the pick couldn't be paid for
    // and playFromZonePayingCost rolled the card back to the discard pile, the ability wasn't
    // actually used and the player retains the "once this turn" slot.
    if (played) addDurationTag(state, cardDb, self, RECONSTRUCT_USED_THIS_TURN, state.turnNumber);
  },
});
