// Snow Barl Pup -- "Dream Draft: When an opponent draws a card outside their Draw step, you may
// play Snow Barl Pup, paying all costs. If your Magi is Nar, ignore all costs when you use this
// Effect. You can only play one Snow Barl Pup this way per turn." Built task #44, 2026-07-18 --
// the outside-Draw-Step trigger sweep. Uses the HAND-zone draw hook `onAnyCardDrawnWhileInHand`
// (registry.ts) -- Snow Barl Pup is the one card that reacts to a draw while sitting in HAND (it
// plays ITSELF from hand), unlike the in-play draw-reactors (Cactus Dryte/Artimillies) that use
// the sibling `onAnyCardDrawn`. (Originally both shared a single hand-scanning `onAnyCardDrawn`;
// split in task #47, 2026-07-18, after that shared scan was found to leak in-play Effects from
// hand.) The in-hand self-check below is now redundant with the hook's own zone scoping but kept
// as a harmless belt-and-suspenders guard. "Outside their Draw step" reads as `state.phase !==
// 'draw'`. Real choice (player-choice-default convention): `pendingYesNoChoice`/
// `resolveYesNoChoice`, same "play it now?" shape as Mountain Trulb/Wasperine Stalker
// (`onOwnAttackStepStart` + `playFromZonePayingCost`, task #42/#43) -- here the arming trigger is
// `onAnyCardDrawn` instead of a phase-start hook. "Ignore all costs" for a Nar Magi uses
// `forcePlayFromHand` (effects.ts, Togoth's Darkest Magics' own primitive) instead of
// `playFromZonePayingCost`. "Only one... per turn" is a standard self-scoped once-per-turn guard.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag, addDurationTag, hasDurationTag } from '../durationTags.js';
import { playFromZonePayingCost } from '../play.js';
import { forcePlayFromHand } from '../effects.js';

const DREAM_DRAFT_PENDING = 'snowBarlPupDreamDraftPending';
const DREAM_DRAFT_USED_THIS_TURN = 'snowBarlPupDreamDraftUsedThisTurn';

registerCardEffect('Snow Barl Pup', {
  onAnyCardDrawnWhileInHand: (state, cardDb, self, drawingPlayerId) => {
    if (state.phase === 'draw') return; // "outside their Draw step"
    if (drawingPlayerId === self.controllerId) return; // "an opponent"
    if (hasDurationTag(self, DREAM_DRAFT_USED_THIS_TURN)) return; // "one... per turn"
    const player = state.players.get(self.controllerId);
    if (!player?.hand.some((c) => c.instanceId === self.instanceId)) return; // must be in hand
    addPendingChoiceTag(self, DREAM_DRAFT_PENDING);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(DREAM_DRAFT_PENDING)) return undefined;
    return {
      prompt: "Snow Barl Pup's Dream Draft: play it now?",
      yesLabel: 'Play Snow Barl Pup',
      noLabel: 'Not now',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, DREAM_DRAFT_PENDING);
    if (!chosenBoolean) return;
    addDurationTag(state, cardDb, self, DREAM_DRAFT_USED_THIS_TURN, state.turnNumber);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const magiDef = player.activeMagi ? cardDb.get(player.activeMagi.definitionKey) : undefined;
    if (magiDef?.regions.includes('Nar')) {
      forcePlayFromHand(state, cardDb, player, self.instanceId, rng);
    } else {
      playFromZonePayingCost(state, cardDb, player, 'hand', self.instanceId, {}, rng);
    }
  },
});
