// Crystal Goblet -- "Renew: After a Crystal Creature is discarded from play on an opposing turn,
// draw a card." "Crystal" is a name-prefix family (Crystal Arboll/Hyren/Jile/Saris/Twinklet, etc.),
// not the shared-last-word `creatureType()` convention -- matched directly against the card's
// name. "On an opposing turn" reads as "while it's not your own turn," independent of who or what
// actually caused the discard.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Crystal Goblet', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (state.activePlayerId === self.controllerId) return;
    const def = cardDb.get(discarded.definitionKey);
    if (def?.card_type !== 'Creature' || !def.name.startsWith('Crystal ')) return;

    const owner = state.players.get(self.controllerId);
    if (owner) drawCards(state, cardDb, owner, 1);
  },
});
