// Fire Flow (Spell, cost 1) -- "Choose any one Creature in play. Move up to four energy from your
// Magi to the chosen Creature." Cald Spell pass, Category B (2026-07-20). No existing Spell-side
// "pick a target AND an amount" field (ugger.ts's pendingPreCombatTargetChoice.amount is the only
// precedent and it's combat-scoped only) -- per the task's own build-time call, defaults to the
// pragmatic "always move the fixed max of 4" simplification (no printed downside to moving less,
// same shape diobor.ts's Energy Transfer already uses for its own "move up to six") rather than
// bolting on a new Spell-side amount-picker field for one card.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Fire Flow', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellAmountChoices: (state, cardDb, playerId) => {
    const magi = state.players.get(playerId)?.activeMagi;
    const max = Math.min(4, magi?.currentEnergy ?? 0);
    return [{ id: 'move', prompt: `Fire Flow: move how much energy from your Magi? (0-${max})`, min: 0, max }];
  },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;

  // Task #532 (2026-07-26): "up to N" is a PLAYER CHOICE of 0..N, not N. This used to hard-code the
  // maximum (playtest: Giant Arboll "automatically is moving the max energy instead of giving a
  // picker"). `?? cap` keeps the old max as the fallback when no amount was supplied, so the engine
  // half is safe on its own -- an absent choice behaves exactly as before rather than moving 0.
    const cap = Math.min(4, magi.currentEnergy ?? 0);
    const amount = Math.max(0, Math.min(ctx.chosenAmounts?.['move'] ?? cap, cap));
    if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, magi, target, amount, ctx.rng);
  },
});
