// Nahara -- "Remembrance (X): Choose a Power on a Creature card in any discard pile that does not
// reference the name of the card it is printed on. Treat this Power as a copy of the chosen
// Power. X is the cost of the chosen Power. Shuffle the Creature whose Power was chosen into its
// owner's deck." First user of registry.ts's copyPowerChoice + copiedPowers.ts's addCopiedPower.
// A PERMANENT copy (no expiry) -- unlike Taglat/K'teeb/Gremm's Helmet, Nahara's own text never
// mentions a duration.

import { registerCardEffect } from './registry.js';
import type { CardInstance } from '../types/instance.js';
import type { Power } from '../types/card.js';
import type { PlayerState } from '../types/state.js';
import { addCopiedPower } from '../copiedPowers.js';
import { removeFromZone, addToZone, shuffleDeck } from '../zones.js';

registerCardEffect('Nahara', {
  copyPowerChoice: {
    pool: (state, cardDb) => {
      const result: Array<{ card: CardInstance; power: Power }> = [];
      for (const player of state.players.values()) {
        for (const card of player.discardPile) {
          const def = cardDb.get(card.definitionKey);
          if (def?.card_type !== 'Creature') continue;
          for (const power of def.powers) {
            if (!power.text.includes(def.name)) result.push({ card, power });
          }
        }
      }
      return result;
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Remembrance') return;
    if (!ctx.chosenTargetId) return;
    const [cardInstanceId, powerName] = ctx.chosenTargetId.split('::');
    if (!cardInstanceId || !powerName) return;

    let owner: PlayerState | undefined;
    let card: CardInstance | undefined;
    for (const player of ctx.state.players.values()) {
      const found = player.discardPile.find((c) => c.instanceId === cardInstanceId);
      if (found) {
        owner = player;
        card = found;
        break;
      }
    }
    if (!owner || !card) return;
    const def = ctx.cardDb.get(card.definitionKey);
    const power = def?.powers.find((p) => p.name === powerName);
    if (!def || def.card_type !== 'Creature' || !power || power.text.includes(def.name)) return;
    if (ctx.chosenXValue !== (typeof power.cost === 'number' ? power.cost : 0)) return;

    addCopiedPower(ctx.source, power, def.key);
    removeFromZone(owner, 'discardPile', card.instanceId);
    addToZone(owner, 'deck', card);
    shuffleDeck(owner, ctx.rng);
  },
});
