  onOwnTurnEndWhileDefeated?: (state: GameState, cardDb: CardDatabase, self: CardInstance, rng: Rng) => void;
  /** @see onOwnTurnEndWhileDefeated */
  onOpponentTurnEndWhileDefeated?: (state: GameState, cardDb: CardDatabase, self: CardInstance, rng: Rng) => void;
