// M'ck -- both printed clauses:
//   "Flint": "Once per turn, when you play a card with the word 'stone' or 'stones' in its name,
//   draw a card."
//   "Rock Out": "Each of your cards with the word 'rock' or 'rocks' in its name costs two less
//   energy to play, to a minimum of one." registry.ts's costModifier, already broadcast to every
//   in-play card + Magi on both sides.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const FLINT_USED_THIS_TURN = 'mckFlintUsedThisTurn';

registerCardEffect("M'ck", {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Flint is the one-per-turn draw
  // reactor on `onPlay`; Rock Out is the broadcast cost discount on `costModifier`.
  effectHooks: {
    Flint: ['onPlay'],
    'Rock Out': ['costModifier'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (hasDurationTag(self, FLINT_USED_THIS_TURN)) return;
    const name = cardDb.get(played.definitionKey)?.name ?? '';
    if (!/\bstones?\b/i.test(name)) return;

    const player = state.players.get(self.controllerId);
    if (!player) return;
    drawCards(state, cardDb, player, 1);
    addDurationTag(state, cardDb, self, FLINT_USED_THIS_TURN, state.turnNumber);
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return /\brocks?\b/i.test(playedDef.name) ? -2 : 0;
  },
});
