// Rayje's Band -- "Non-Universal Magi may not play non-Universal Spells that are not of their
// region." A passive lockdown (registry.ts's preventsPlayOf, task #50c), checked BEFORE any play
// resolves and broadcast over BOTH players' boards, so it restricts every player's non-Universal
// Magi -- including Rayje's Band's own controller. Universal Magi are unaffected; Universal Spells
// are always playable; a Spell that shares a region with the acting Magi is "of their region" and
// stays legal.

import { registerCardEffect } from './registry.js';
import { isUniversal } from '../regions.js';

registerCardEffect("Rayje's Band", {
  preventsPlayOf: (state, cardDb, playedDef, playerId) => {
    if (playedDef.card_type !== 'Spell' || isUniversal(playedDef.regions)) return false;
    const magi = state.players.get(playerId)?.activeMagi;
    const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
    if (!magiDef || isUniversal(magiDef.regions)) return false; // only NON-Universal Magi are restricted
    return !magiDef.regions.some((r) => playedDef.regions.includes(r)); // "not of their region"
  },
});
