// Giant Parmalag -- "Withdraw: Giant Parmalag cannot be attacked until after your next turn."
// Same CANNOT_BE_ATTACKED tag as Hood of Hiding, applied to itself instead of the Magi.

import { registerCardEffect } from './registry.js';
import { addDurationTag, CANNOT_BE_ATTACKED, nextOwnTurnNumber } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Giant Parmalag', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Withdraw') return;
    addRestrictionTag(ctx.state, ctx.source, CANNOT_BE_ATTACKED, nextOwnTurnNumber(ctx.state));
  },
});
