// Adis -- printed text: "If Adis is defeated, your opponents each choose and discard three cards
// from each of their hands." The printed "choose" is each OPPONENT's own choice -- simplified to
// "first three in hand order" (same array-order tradeoff as Elios/Corathan, no interactive prompt
// available mid-resolution for a reactive hook; unlike Shadow Empress's Treacherous Bargain, this
// isn't a single target pick an opponent might decline, it's an unconditional forced discard of a
// FIXED count from their own hand, which doesn't fit the existing pendingTargetChoice shape).

import { registerCardEffect } from './registry.js';
import { getOpponents } from '../types/state.js';
import { discardFromHand, riptideBanActiveFor } from '../effects.js';

registerCardEffect('Adis', {
  // task #718 (Riptide clause 2, 2026-08-11): Effect-shaped hostile hand-discard. Tag + in-body
  // gate -- if Adis's owner has an active Riptide ban, the on-defeat discard is suppressed. The
  // tag alone doesn't reach here (this fires from a passive `onOwnMagiDefeated` broadcast, not a
  // play/use action), so the hook body has to consult the ban itself.
  causesOpponentHandDiscard: true,
  onOwnMagiDefeated: (state, cardDb, self) => {
    if (riptideBanActiveFor(state, self.controllerId)) return;
    for (const opponent of getOpponents(state, self.controllerId)) {
      const toDiscard = opponent.hand.slice(0, 3).map((c) => c.instanceId);
      if (toDiscard.length > 0) {
        discardFromHand(state, cardDb, opponent, toDiscard);
      }
    }
  },
});
