// Barak the Red -- "Command (1): Search your deck for any one Cald Creature and place it into
// your hand. Discard a card from your hand. Reshuffle your deck afterwards." First card using
// registry.ts's deckSearch -- the "searching" archetype, expected to recur. Known simplification:
// the hand-discard picker's pool is computed from the hand BEFORE the search runs (same timing
// constraint as every other UI-collects-choices-before-resolving Power), so the player can't
// choose to discard the just-found card in the same action -- they can still discard any OTHER
// hand card, which satisfies the card's text either way.

import { registerCardEffect } from './registry.js';
import { discardFromHand, searchDeck } from '../effects.js';
import { regionForTargetFilter } from '../targeting.js';

registerCardEffect('Barak the Red', {
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, 'Cald'));
    },
  },
  handDiscardCost: { count: 1 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Command') return;
    const searchIds = ctx.chosenDeckSearchIds ?? [];
    if (searchIds.length > 1) return;
    const specifiedRegion = regionForTargetFilter(ctx.state, 'Cald');
    for (const id of searchIds) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
      if (!def || def.card_type !== 'Creature' || !def.regions.includes(specifiedRegion)) return;
    }
    // Always reshuffle, even if nothing was found or chosen -- rules-reference.md §12: "Searching
    // the deck -- always reshuffle afterward" isn't conditional on finding a match.
    searchDeck(ctx.state, ctx.controllingPlayer, searchIds, ctx.rng);

    if (ctx.chosenHandCardIds && ctx.chosenHandCardIds.length >= 1) {
      discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. This was the file a live playtest actually caught missing
  // from the original 61-file sweep.
  specifiedTargetRegions: () => ['Cald'],
});
