// Crystal Hyren -- both printed abilities.
//
//   "Illuminate: Choose a Spell in play and discard it."
//
//   "Ricochet: Once per turn, as Crystal Hyren is attacked, remove one energy from each opposing
//   Creature." BUILT 2026-07-28 (ability-count sweep) -- the file had only Illuminate.
//
// "AS Crystal Hyren is attacked" fires on onAttack with self as the DEFENDER, and removes real
// energy rather than adjusting `ctx.locked` -- unlike Rock Yajo's Invulnerability, this is not a
// combat-damage modifier, it is a separate energy discard that happens to be triggered by combat.
// "Each OPPOSING Creature" is opposing from Crystal Hyren's own controller's side, so the attacker
// is included along with the rest of that player's board.

import { registerCardEffect } from './registry.js';
import { allSpellsInPlay, findInPlayById, opposingCreatures } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const RICOCHET_USED_THIS_TURN = 'crystalHyrenRicochetUsedThisTurn';

registerCardEffect('Crystal Hyren', {
  onAttack: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return; // "as Crystal Hyren IS ATTACKED"
    if (hasDurationTag(self, RICOCHET_USED_THIS_TURN)) return;
    addDurationTag(ctx.state, ctx.cardDb, self, RICOCHET_USED_THIS_TURN, ctx.state.turnNumber);

    // Snapshot first: discardEnergy can defeat a Creature, which mutates the live inPlay array.
    for (const creature of [...opposingCreatures(ctx.state, ctx.cardDb, self.controllerId)]) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
    }
  },
  powerTargets: (state, cardDb) => allSpellsInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Illuminate') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Spell') return;

    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
