// Timber Hyren -- "Tribute: Take up to five energy from your Magi and place it on Timber Hyren."
// "Take X and place it on Y" is a synonym for "move" that the original move-energy survey missed
// entirely -- mechanically identical to Zungg/Kelthet/etc., just rearrangeEnergy again.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Timber Hyren', {
  powerAmountChoices: (state, cardDb, playerId, powerName) => {
    if (powerName !== 'Tribute') return undefined;
    const magi = state.players.get(playerId)?.activeMagi;
    const max = Math.min(5, magi?.currentEnergy ?? 0);
    return [{ id: 'take', prompt: `Tribute: take how much energy from your Magi? (0-${max})`, min: 0, max }];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Tribute') return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;
  // Task #532 (2026-07-26): "up to N" is a PLAYER CHOICE of 0..N, not N. This used to hard-code the
  // maximum (playtest: Giant Arboll "automatically is moving the max energy instead of giving a
  // picker"). `?? cap` keeps the old max as the fallback when no amount was supplied, so the engine
  // half is safe on its own -- an absent choice behaves exactly as before rather than moving 0.
    const cap = Math.min(5, magi.currentEnergy ?? 0);
    const amount = Math.max(0, Math.min(ctx.chosenAmounts?.['take'] ?? cap, cap));
    if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, magi, ctx.source, amount, ctx.rng);
  },
});
