// Warrada's Ring -- "Phenomenal Cosmic Power: At the beginning of each of your turns, choose
// either to draw an additional card at the end of the turn, or to have all of your Core cards
// cost one less energy to play, to a minimum of one, until the end of the turn."
//
// Rebuilt 2026-07-11 with a REAL turn-start choice (registry.ts's pendingOwnTurnStartChoice/
// resolveOwnTurnStartChoice), replacing the earlier "always draw" hardcode. onOwnTurnStart clears
// last turn's choice and marks a new one pending; the UI prompt resolves it into one of two
// permanent tags, read live by drawCountModifier/costModifier for the rest of the turn.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const AWAITING_CHOICE = 'warradasRingAwaitingChoice';
const DRAW_ACTIVE = 'warradasRingDrawActive';
const COST_REDUCTION_ACTIVE = 'warradasRingCostReductionActive';

registerCardEffect("Warrada's Ring", {
  onOwnTurnStart: (state, cardDb, self) => {
    removePermanentTag(self, DRAW_ACTIVE);
    removePermanentTag(self, COST_REDUCTION_ACTIVE);
    addPermanentTag(state, cardDb, self, AWAITING_CHOICE);
  },
  pendingOwnTurnStartChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    return {
      prompt: "Warrada's Ring: draw an extra card at the end of the turn, or Core cards cost one less (min 1) this turn?",
      yesLabel: 'Draw an extra card',
      noLabel: 'Core cards cost 1 less',
    };
  },
  resolveOwnTurnStartChoice: (state, cardDb, self, chosenBoolean) => {
    removePermanentTag(self, AWAITING_CHOICE);
    addPermanentTag(state, cardDb, self, chosenBoolean ? DRAW_ACTIVE : COST_REDUCTION_ACTIVE);
  },
  drawCountModifier: (state, cardDb, self) => (self.tags.has(DRAW_ACTIVE) ? 1 : 0),
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    if (!self.tags.has(COST_REDUCTION_ACTIVE)) return 0;
    return playedDef.regions.includes('Core') ? -1 : 0;
  },
});
