// Storm Cloud (Spell) -- "Choose any one Creature in play. Discard all but one energy from the
// chosen Creature." Targeted at ANY Creature (either side). "All but one" never reduces a Creature
// already at 0 or 1 energy, so the discard amount floors at 0 (no-op) rather than going negative.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Storm Cloud', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const amount = Math.max(0, (target.currentEnergy ?? 0) - 1);
    if (amount > 0) discardEnergy(ctx.state, ctx.cardDb, target, amount, 'spell', undefined, ctx.rng);
  },
});
