// Weed Hyren -- all three printed clauses:
//   "Weave: Whenever Weed Hyren attacks or is attacked, before energy is removed, you may move one
//   energy between it and one of your other Paradwyn or Weave Creatures in play." (see weave.ts)
//   "Withdraw: If Weed Hyren is discarded from play outside of an attack, place it in your hand
//   instead of the discard pile." Previously deferred pending a "was this discard combat-caused or
//   not" distinction -- now built via energy.ts's `DefeatSource` (the Gorgle's Glasses/Brog/Koil
//   work, 2026-07-11): fires for any discard EXCEPT `source === 'combat'`, covering explicit
//   discards and Power/Effect-caused zero-energy alike.
//   "Dreamwarp: As you play Weed Hyren, increase or decrease its starting energy by up to one,
//   until the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import { applyWeave } from './weave.js';
import { removeFromZone, addToZone } from '../zones.js';

registerCardEffect('Weed Hyren', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Three printed Effects, each on its
  // own hook: Weave (data field + combat hook), Withdraw (own-discard reactor gated on
  // source !== 'combat'), Dreamwarp (standard self-play data field).
  effectHooks: {
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
    Withdraw: ['onCardDiscardedFromPlay'],
    Dreamwarp: ['dreamwarpRange'],
  },
  weaveConfig: { eligibleRegions: ['Paradwyn', 'Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Paradwyn', 'Weave']),
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source) => {
    if (discarded.instanceId !== self.instanceId) return;
    if (source === 'combat') return;

    const owner = state.players.get(discardedOwnerId);
    if (!owner) return;
    // Fuzz finding (2026-08-01), same "verify presence, no-op if already gone" convention as task
    // #600 bucket A -- another onCardDiscardedFromPlay watcher earlier in the same broadcast can
    // already have moved this exact card out of the discard pile (yogsMaul's own multi-discard Power
    // resolution is what surfaced it) before Weed Hyren's own Withdraw gets its turn.
    if (!owner.discardPile.some((c) => c.instanceId === discarded.instanceId)) return;
    const card = removeFromZone(owner, 'discardPile', discarded.instanceId);
    addToZone(owner, 'hand', card);
  },
  dreamwarpRange: () => 1,
});
