// Nymat -- "Sandstorm: After an opponent plays a Creature with six or more energy, remove two
// energy from that Creature." Broadcast onPlay reactor, reads the played Creature's freshly-set
// starting energy directly off currentEnergy.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Nymat', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if ((played.currentEnergy ?? 0) < 6) return;

    discardEnergy(state, cardDb, played, 2, 'effect', self.controllerId);
  },
});
