// Korok -- "Empower: Powers on your Kybar's Teeth cards cost one less energy to use, to a minimum
// of one." Plain powerCostModifier, region-filtered on the Power's SOURCE card, + powerCostFloorsAtOne
// (task 2026-07-19 playtest fix -- was floored at power.ts's shared default of 0, not this card's own
// printed minimum of 1; see registry.ts's powerCostFloorsAtOne doc comment).

import { registerCardEffect } from './registry.js';

function empowerApplies(powerUserId: string, sourceDef: { regions: readonly string[] }, self: { controllerId: string }): boolean {
  return powerUserId === self.controllerId && sourceDef.regions.includes("Kybar's Teeth");
}

registerCardEffect('Korok', {
  powerCostModifier: (state, cardDb, powerUserId, sourceDef, self) => (empowerApplies(powerUserId, sourceDef, self) ? -1 : 0),
  powerCostFloorsAtOne: (state, cardDb, powerUserId, sourceDef, self) => empowerApplies(powerUserId, sourceDef, self),
});
