// Rolling Baldar -- "Collision: After Rolling Baldar defeats a Creature while attacking, remove
// three energy from the smallest opposing Creature. If there is a tie, an opponent of your choice
// chooses the Creature to be affected."
//
// BUILT 2026-08-11 (post-audit deferred-gap closure pass): the tie-break now routes to the
// OPPONENT via `pendingTargetChoice`'s `answeringPlayerId` field (the same opponent-routed-choice
// shape Orothe Shadow Geyser's opponent hand-discard already uses) -- previously deferred (task
// #40-7, 2026-07-17) because no mechanism existed to route a prompt to a specific player rather
// than "whoever's turn it is." That mechanism now exists engine-wide, closing the gap. Falls back
// to the first array-order tied candidate if unanswered, matching the old deterministic behavior
// exactly (same convention every pending-choice family in this codebase uses).

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { opposingCreatures } from '../targeting.js';
import { addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { GameState, PlayerId } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const TIE_PENDING = 'rollingBaldarTiePending';

function tiedForSmallest(state: GameState, cardDb: CardDatabase, controllerId: PlayerId) {
  const candidates = opposingCreatures(state, cardDb, controllerId);
  if (candidates.length === 0) return [];
  const minEnergy = Math.min(...candidates.map((c) => c.currentEnergy ?? 0));
  return candidates.filter((c) => (c.currentEnergy ?? 0) === minEnergy);
}

registerCardEffect('Rolling Baldar', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (!ctx.defender) return;
    if (outcome.defenderSurvived) return;
    const tied = tiedForSmallest(ctx.state, ctx.cardDb, self.controllerId);
    if (tied.length === 0) return;
    if (tied.length === 1) {
      discardEnergy(ctx.state, ctx.cardDb, tied[0]!, 3, 'effect', self.controllerId, ctx.rng);
      return;
    }
    addPendingChoiceTag(self, TIE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(TIE_PENDING)) return undefined;
    const tied = tiedForSmallest(state, cardDb, self.controllerId);
    if (tied.length === 0) return undefined;
    return {
      prompt: "Rolling Baldar's Collision: choose which tied Creature loses three energy",
      pool: tied,
      answeringPlayerId: tied[0]!.controllerId, // 2-player engine: all opposing tied Creatures share one controller
    };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    if (!self.tags.has(TIE_PENDING)) return;
    removePermanentTag(self, TIE_PENDING);
    const tied = tiedForSmallest(state, cardDb, self.controllerId);
    const target = (chosenInstanceId && tied.find((c) => c.instanceId === chosenInstanceId)) || tied[0];
    if (!target) return;
    discardEnergy(state, cardDb, target, 3, 'effect', self.controllerId, rng);
  },
});
