// Drakan -- "Thermal Blast (3): Roll one die. Choose any one Creature in play. Discard energy
// equal to the die roll from the chosen Creature."
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';

registerCardEffect('Drakan', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Thermal Blast') return;
    if (ctx.chosenTargetId === undefined) return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'drakan:thermalBlast',
      { controllingPlayerId: ctx.controllingPlayer.playerId, chosenTargetId: ctx.chosenTargetId },
      ctx.rng
    );
  },
});

registerRollConsumer('drakan:thermalBlast', (state, cardDb, _source, payload, finalRoll, rng) => {
  const { controllingPlayerId, chosenTargetId } = payload as { controllingPlayerId: string; chosenTargetId: string };
  const target = findCreatureOrMagiById(state, chosenTargetId);
  if (!target || !isValidTargetGivenFlexibility(state, cardDb, controllingPlayerId, target, 'Creature')) return;
  discardEnergy(state, cardDb, target, finalRoll, 'power', undefined, rng);
});
