// Polar Rudwot -- "If Polar Rudwot attacks while it is Frozen, add two energy to your Magi."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Polar Rudwot', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (!isFrozen(ctx.state, ctx.cardDb, self)) return;
    const magi = ctx.attackingPlayer.activeMagi;
    if (magi) addEnergy(ctx.state, ctx.cardDb, magi, 2, 'effect');
  },
});
