// Elder Yark -- both printed pieces:
//   "Regal Presence: Whenever an opposing Creature attacks, it removes energy from the defending
//   Creature equal to either its starting energy or current energy, whichever is less." A
//   third-party reactor on Elder Yark's controller's own defending side -- caps the attacker's
//   locked energy at its own printed starting energy (undoing any boost above that).
//   "Invulnerability: Elder Yark loses one less energy in attacks." (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Elder Yark', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Both printed Effects fold into a single
  // `onAttack` body -- Regal Presence's cap (with its `appliesCombatLossCap` ordering flag) and
  // Invulnerability's -1 combat loss are structurally inseparable. A Taglat narrow-copy of either
  // surfaces the same shared hook, matching whole-card grant behavior. Annotated for metadata
  // explicitness.
  effectHooks: {
    'Regal Presence': ['onAttack', 'appliesCombatLossCap'],
    Invulnerability: ['onAttack'],
  },
  // Ordering declaration only -- see registry.ts. This card CAPS combat loss, so it resolves
  // after every flat reduction (owner ruling 2026-07-27).
  appliesCombatLossCap: true,
  onAttack: (ctx, self) => {
    if (ctx.defendingPlayer.playerId === self.controllerId && ctx.attacker.controllerId !== self.controllerId) {
      const cap = effectiveStartingEnergy(ctx.state, ctx.cardDb, ctx.attacker);
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.min(ctx.locked.attackerEnergy, cap);
    }
    applyInvulnerability(ctx, self, 1);
  },
});
