// Weave-woven Anklet -- two Effects:
//   "Tied to the Weave: If each Creature you control has the Effect 'Weave', increase your Magi's
//   energize by one." A continuous conditional grant, same shape as windHyren.ts's Invigorate --
//   checked fresh every energize via the energizeRateModifier hook rather than a stored value.
//   Vacuously true (no Creature FAILS the check) when the controller has zero Creatures in play.
//
//   "Memento: If Weave-woven Anklet is discarded from play by an opposing Spell or Power, choose
//   one Weave Spell in your discard pile and add it to your hand."
//
// BUILT #536 C6d, 2026-07-27. This was deferred with the reason "needs a 'discarded specifically
// by an opposing Spell/Power' distinction onCardDiscardedFromPlay's `cause` field doesn't carry."
// That reason was STALE: the hook has carried `source` ('combat' | 'power' | 'effect' | 'spell')
// and `causedByPlayerId` since task #32 (2026-07-16), which is exactly the distinction needed.
// Re-verify a deferral's stated REASON, not just its cost.
//
// Anklet is a Relic, so it can never be defeated -- `source` alone does the work and no `cause`
// filter is needed. Self-reactor: it reacts to its OWN discard, which is why the broadcast
// explicitly re-includes the departing card.
//
// The choice is a REAL prompt (registry.ts's pendingTargetChoice/resolveTargetChoice), not an
// auto-pick -- same Aegris shape, and findPendingTargetChoices scans discard piles precisely so a
// card that has just left play can still offer one.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { retrieveFromDiscardPile } from '../effects.js';
import { addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const MEMENTO_PENDING = 'weaveWovenAnkletMementoPending';

/** "one Weave Spell" -- a Spell whose regions include Weave. */
function isWeaveSpell(cardDb: CardDatabase, card: CardInstance): boolean {
  const def = cardDb.get(card.definitionKey);
  return def?.card_type === 'Spell' && def.regions.includes('Weave');
}

registerCardEffect('Weave-woven Anklet', {
  // Per-Effect hook narrowing (deep-dive audit, 2026-08-13). Tied to the Weave is the
  // conditional +1 energize; Memento is the reactive "return a Weave Spell from discard" on
  // self-discard by opposing Spell/Power.
  effectHooks: {
    'Tied to the Weave': ['energizeRateModifier'],
    Memento: ['onCardDiscardedFromPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discarded.instanceId !== self.instanceId) return; // "If WEAVE-WOVEN ANKLET is discarded"
    if (source !== 'spell' && source !== 'power') return; // "by an opposing SPELL OR POWER"
    if (causedByPlayerId === undefined || causedByPlayerId === self.controllerId) return; // "OPPOSING"
    const owner = state.players.get(discardedOwnerId);
    if (!owner?.discardPile.some((c) => isWeaveSpell(cardDb, c))) return; // nothing to choose
    addPendingChoiceTag(self, MEMENTO_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(MEMENTO_PENDING)) return undefined;
    const owner = state.players.get(self.controllerId);
    const pool = (owner?.discardPile ?? []).filter((c) => isWeaveSpell(cardDb, c));
    if (pool.length === 0) return undefined;
    return { prompt: "Weave-woven Anklet's Memento: choose a Weave Spell to return to your hand", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    if (!self.tags.has(MEMENTO_PENDING)) return;
    removePermanentTag(self, MEMENTO_PENDING);
    if (chosenInstanceId === undefined) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const chosen = owner.discardPile.find((c) => c.instanceId === chosenInstanceId);
    if (!chosen || !isWeaveSpell(cardDb, chosen)) return;
    retrieveFromDiscardPile(state, owner, chosen.instanceId, 'hand');
  },
  energizeRateModifier: (state, cardDb, energizing, self) => {
    if (energizing.controllerId !== self.controllerId) return 0;
    const owner = state.players.get(self.controllerId);
    if (owner?.activeMagi?.instanceId !== energizing.instanceId) return 0;
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    const allWeave = own.every((c) => cardDb.get(c.definitionKey)?.effects.some((e) => e.name === 'Weave'));
    return allWeave ? 1 : 0;
  },
});
