// Ancient's Puzzlebox -- "Mind Games (1): Discard Ancient's Puzzlebox from play. Reveal any
// number of cards in your hand and choose a Creature. Add one energy to it for each Ancient's
// Puzzlebox you reveal. Draw a card. You may not play another Ancient's Puzzlebox this turn." The
// reveal pool is restricted to copies of Ancient's Puzzlebox itself -- the point of revealing is
// proving how many duplicates you're holding. The "may not play another copy" restriction is an
// accepted, documented gap (a NAME-keyed play restriction, unlike this engine's existing
// per-instance tags) -- not enforced, same tradeoff as the "must attack" cards.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy, discardFromPlay, drawCards } from '../effects.js';

registerCardEffect("Ancient's Puzzlebox", {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  handRevealCost: {
    count: 'any',
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.name === "Ancient's Puzzlebox",
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mind Games') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const revealedIds = ctx.chosenHandRevealIds ?? [];
    const validIds = revealedIds.filter((id) => {
      const card = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
      return card && ctx.cardDb.get(card.definitionKey)?.name === "Ancient's Puzzlebox";
    });

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    if (validIds.length > 0) addEnergy(ctx.state, ctx.cardDb, target, validIds.length, 'power');
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
  },
});
