// Jakla Prowler -- "Skulk (1): Choose an opposing Cald Creature. Remove one energy from it and
// remove one energy from its controller's Magi for each Spell in YOUR discard pile." ("your" =
// the controlling player using the Power, not the target's controller.)

import { registerCardEffect } from './registry.js';
import { effectiveRegions, findInPlayById, opposingCreatures, opposingMagi, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Jakla Prowler', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- opposingMagi, not
  // allMagiInPlay (see creepingAinjer.ts).
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)).filter(
      (c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Cald'))
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Skulk') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Cald'))) return;

    discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
    const targetOwner = ctx.state.players.get(target.controllerId);
    if (targetOwner?.activeMagi) {
      const ownDiscardSpellCount = ctx.controllingPlayer.discardPile.filter(
        (c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Spell'
      ).length;
      discardEnergy(ctx.state, ctx.cardDb, targetOwner.activeMagi, ownDiscardSpellCount, undefined, undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Cald'],
});
