// Bottomless Pit (Spell, Underneath, cost 3) -- "Choose any one Creature in play with less than
// five energy. Discard the chosen Creature." Plain targeting filter + discardFromPlay. The <5 gate
// is re-checked at resolution, since another card resolving in between (or this Spell's own
// negation window) can change the target's energy after the pool was offered.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

function eligible(state: GameState, cardDb: CardDatabase): CardInstance[] {
  return allCreaturesInPlay(state, cardDb).filter((c) => (c.currentEnergy ?? 0) < 5);
}

registerCardEffect('Bottomless Pit', {
  // "Ummm...NO!" (task #565): this Spell reaches effects.ts#discardFromPlay on a single
  // chosenTargetId Creature, so it is answerable. See registry.ts for the flag contract.
  spellSpecificallyDiscardsCreature: true,
  spellTargets: (state, cardDb) => eligible(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = eligible(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, ctx.controllingPlayer.playerId, 'spell', ctx.rng);
  },
});
