// Heat Lens -- "Mind Burn (2): Choose any one player. Look at the chosen player's hand. You may
// choose any one card in that player's hand. The player discards the chosen card." Second user of
// chooseFromOpponentHand (see Epik) -- no Creature-type filter here, any card qualifies.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardFromHand } from '../effects.js';

registerCardEffect('Heat Lens', {
  powerTargets: (state) => allMagiInPlay(state),
  chooseFromOpponentHand: { maxCount: 1 },
  causesOpponentHandDiscard: true, // task #718 (Riptide clause 2, 2026-08-11)

  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mind Burn') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const targetOwner = ctx.state.players.get(chosenMagi.controllerId);
    if (!targetOwner) return;

    const offered = ctx.chosenFromOpponentHandIds ?? [];
    const validIds = offered.filter((id) => targetOwner.hand.some((c) => c.instanceId === id));
    if (validIds.length > 0) discardFromHand(ctx.state, ctx.cardDb, targetOwner, validIds.slice(0, 1), undefined, ctx.rng);
  },
});
