// Dark Portents (Spell, Core) -- "Choose a player. Reveal the top five cards of the chosen player's
// deck. Add one energy to your Magi for each Creature revealed. You may discard one of the revealed
// cards. Put the remaining cards back on the chosen player's deck in the same order." Task #53-4,
// 2026-07-21, the Core Spell pass's A1 quick wins.
//
// "Choose a player" reuses the standard Magi-proxy pattern (`spellTargets` -> `allMagiInPlay`, the
// chosen Magi's `controllerId` IS the chosen player -- same convention `deckSearch`'s
// `whoseDeck: 'target'`/`discardPileSearch`'s `whoseDiscardPile: 'target'` use via `powerTargets`,
// just on the Spell side).
//
// registry.ts's `deckTopReveal` field is Power-only (no Spell-side wiring exists anywhere in
// play.ts/Play.tsx) -- rather than widening a whole generic mechanism for this one card, this reads
// the top 5 directly (deck[0] is the top of the deck, confirmed convention -- artimillies.ts/
// kybarsScroll.ts/parathin.ts all read `deck[0]` the same way) WITHOUT removing anything from the
// deck, so "put the remaining cards back... in the same order" is automatic: nothing ever moved.
// "You may discard one" is a genuine optional choice, built via Bombard/Muck Rain/Trulbble!'s
// confirmed "tag survives the Spell's own move to the discard pile, pendingTargetChoice's 5-zone
// scan finds it there" pattern -- the revealed ids (and which player's deck they're on) are stashed
// as tags on Dark Portents' own (already-discarded) instance; the pool for the picker is looked back
// up fresh from that player's deck by id, and only the CHOSEN card is ever actually removed
// (via `removeFromZone` + `moveToDiscardPile`), preserving the other four's relative order exactly.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { removeFromZone, moveToDiscardPile } from '../zones.js';
import { getPlayer } from '../types/state.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING_DISCARD = 'darkPortentsAwaitingDiscard';
const REVEALED_PREFIX = 'darkPortentsRevealed:';
const CHOSEN_PLAYER_PREFIX = 'darkPortentsChosenPlayer:';

function revealedIds(self: CardInstance): string[] {
  return [...self.tags].filter((t) => t.startsWith(REVEALED_PREFIX)).map((t) => t.slice(REVEALED_PREFIX.length));
}

function chosenPlayerId(self: CardInstance): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(CHOSEN_PLAYER_PREFIX));
  return tag ? tag.slice(CHOSEN_PLAYER_PREFIX.length) : undefined;
}

registerCardEffect('Dark Portents', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const magi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!magi) return;
    const chosenPlayer = getPlayer(ctx.state, magi.controllerId);

    const revealed = chosenPlayer.deck.slice(0, 5);
    const creatureCount = revealed.filter((c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature').length;
    if (creatureCount > 0) {
      const casterMagi = ctx.controllingPlayer.activeMagi;
      if (casterMagi) addEnergy(ctx.state, ctx.cardDb, casterMagi, creatureCount, 'spell');
    }
    if (revealed.length === 0) return;

    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${CHOSEN_PLAYER_PREFIX}${chosenPlayer.playerId}`);
    for (const card of revealed) addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${REVEALED_PREFIX}${card.instanceId}`);
    addPendingChoiceTag(ctx.source, AWAITING_DISCARD);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_DISCARD)) return undefined;
    const playerId = chosenPlayerId(self);
    const player = playerId ? state.players.get(playerId) : undefined;
    if (!player) return undefined;
    const ids = new Set(revealedIds(self));
    const pool = player.deck.filter((c) => ids.has(c.instanceId));
    if (pool.length === 0) return undefined;
    return { prompt: 'Dark Portents: you may discard one of the revealed cards', pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, AWAITING_DISCARD);
    const playerId = chosenPlayerId(self);
    for (const id of revealedIds(self)) removePermanentTag(self, `${REVEALED_PREFIX}${id}`);
    if (playerId) removePermanentTag(self, `${CHOSEN_PLAYER_PREFIX}${playerId}`);
    if (!chosenInstanceId || !playerId) return;
    const player = state.players.get(playerId);
    if (!player || !player.deck.some((c) => c.instanceId === chosenInstanceId)) return;
    const card = removeFromZone(player, 'deck', chosenInstanceId);
    moveToDiscardPile(state, player, card, 'explicit', 'spell', self.controllerId);
  },
});
