// Lahalou -- both printed clauses:
//   "Grow: Add one energy to Lahalou." No target, no condition.
//   "Dreamwarp: As you play Lahalou, increase or decrease its starting energy by up to one, until
//   the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Lahalou', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Grow') return;
    addEnergy(ctx.state, ctx.cardDb, ctx.source, 1, 'power');
  },
  dreamwarpRange: () => 1,
});
