// Looph -- "Regroup: If Looph attacks and is defeated, you may immediately play a Bograth
// Creature from your hand, paying all costs." afterCombat (fires even for a just-defeated
// attacker, per its own doc comment -- re-included after the zero-energy sweep) + the new
// play.ts's playFromZonePayingCost primitive (task #30, 2026-07-15), shared with Black Stuff's
// Regenerate.
//
// Real choice (task #40-1, 2026-07-17, player-choice-default retrofit): replaces the earlier
// "highest-cost affordable Bograth Creature in hand" auto-pick with a real pending choice
// (registry.ts's pendingTargetChoice/resolveTargetChoice, hand-pool, same shape as garadan.ts).
// `self` (Looph) is already in the discard pile by the time this pending choice is offered/
// resolved -- `findPendingTargetChoices` scans discardPile for exactly this reason (a card's own
// trigger firing after its own defeat).

import { registerCardEffect } from './registry.js';
import { playFromZonePayingCost } from '../play.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const REGROUP_PENDING = 'loophRegroupPending';

function regroupPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.hand.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return def?.card_type === 'Creature' && def.regions.includes('Bograth');
  });
}

registerCardEffect('Looph', {
  afterCombat: (ctx, outcome, self) => {
    if (self.instanceId !== ctx.attacker.instanceId) return;
    if (outcome.attackerSurvived) return;
    if (regroupPool(ctx.state, ctx.cardDb, self).length === 0) return;
    addPendingChoiceTag(self, REGROUP_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(REGROUP_PENDING)) return undefined;
    const pool = regroupPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Looph's Regroup: choose a Bograth Creature to play from hand, paying all costs", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, REGROUP_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    if (!regroupPool(state, cardDb, self).some((c) => c.instanceId === chosenInstanceId)) return;
    playFromZonePayingCost(state, cardDb, player, 'hand', chosenInstanceId, {}, rng);
  },
});
