// Rock Slide (Spell) -- "Discard the Creature with the most energy from play. In the case of a
// tie, you choose which Creature to discard." Kybar's Teeth Spell pass, Category A (2026-07-22).
// No new tie-break mechanism needed: spellTargets returns every Creature tied for the current max
// energy across ALL players' in-play Creatures, and the normal target picker already lets the
// player choose among a filtered pool -- a single-Creature pool (no tie) just offers one option,
// same as any other single-target Spell.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';

registerCardEffect('Rock Slide', {
  spellTargets: (state, cardDb) => {
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return [];
    const max = Math.max(...pool.map((c) => c.currentEnergy ?? 0));
    return pool.filter((c) => (c.currentEnergy ?? 0) === max);
  },
  resolveSpell: (ctx) => {
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    const owner = ctx.state.players.get(target.controllerId)!;
    discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, ctx.controllingPlayer.playerId, 'spell', ctx.rng);
  },
});
