// Ripcurl (Spell, Orothe, cost 4) -- "Choose two opposing Creatures. Move up to four energy from the
// first Creature to the second Creature." "Opposing" is relative to the CASTER -- both picks come
// from the caster's opponent's board. The first pick is spellTargets; the second pick + amount
// reuses Topple's exact spellMultiTargets/spellMultiTargetAllocatesEnergy machinery (registry.ts),
// just constrained to the FIRST chosen id in chosenMultiTargetIds since this card only ever needs
// one destination, not "any number of" -- same UI/engine plumbing, no new mechanism needed.
// rearrangeEnergy (effects.ts) does the actual move and already clamps to the source's own energy.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { opposingCreatures } from '../targeting.js';

registerCardEffect('Ripcurl', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  spellMultiTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) =>
    opposingCreatures(state, cardDb, playerId).filter((c) => c.instanceId !== firstChosenId),
  spellMultiTargetAllocatesEnergy: true,
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const pool = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    const from = pool.find((c) => c.instanceId === ctx.chosenTargetId);
    if (!from) return;
    const toId = (ctx.chosenMultiTargetIds ?? [])[0];
    if (!toId || toId === ctx.chosenTargetId) return;
    const to = pool.find((c) => c.instanceId === toId);
    if (!to) return;

    const requested = ctx.chosenEnergyAllocation?.[toId] ?? 0;
    const amount = Math.max(0, Math.min(4, requested, from.currentEnergy ?? 0));
    if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, from, to, amount, ctx.rng);
  },
});
