// Solar Flare (Spell) -- "Add four energy to each of your Arderial Creatures that attacked and
// defeated an opposing Creature this turn." No board target -- a broadcast over the caster's own
// in-play Creatures, reading CardInstance.defeatedThisTurn (set by combat.ts right after damage
// resolves, cleared at the start of the attacker's controller's own next turn -- same field Great
// White Narth/Gulg already read for this exact "defeated an opposing Creature in an attack this
// turn" clause).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';

registerCardEffect('Solar Flare', {
  resolveSpell: (ctx) => {
    const own = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    for (const creature of own) {
      if (!creature.defeatedThisTurn) continue;
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Arderial'))) continue;
      addEnergy(ctx.state, ctx.cardDb, creature, 4, 'spell');
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ['Arderial'],
});
