// Horizon's Mirage (Spell) -- "Attach Horizon's Mirage to your Magi and place a d'Resh Creature
// from your hand under it. At the end of your next turn, play the Creature under Horizon's Mirage,
// ignoring all costs and discard Horizon's Mirage."
//
// Delayed re-entry into play, one full turn out -- a small synthesis of three existing primitives:
// (1) sits directly in `player.inPlay` (not via attachedCards.ts's attachCard onto the Magi), same
// "broadcasts only scan activeMagi + inPlay" reasoning as Crystal Vision -- onOwnTurnStart needs to
// find it; (2) the chosen Creature is stored via attachCard onto HORIZON'S MIRAGE'S OWN instance
// (not the Magi's) -- fine here since only this card's own onOwnTurnStart hook ever needs to read
// it back, no external broadcast has to discover it; (3) the trigger turn is stored via the
// existing generic `counters` field (task #50f), checked each of the controller's own turn starts,
// same "onOwnTurnStart gated on a stored future turn number" shape Furok Guardian's re-entry uses
// for its own (same-turn) delayed play, just extended one turn further out.

import { registerCardEffect } from './registry.js';
import { attachCard, detachCard } from '../attachedCards.js';
import { discardFromPlay, setCounter, getCounter, broadcastCardEnteredPlay } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';
import { nextOwnTurnNumber } from '../durationTags.js';
import { regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';

registerCardEffect("Horizon's Mirage", {
  // Cards stored under this one are OUT of play, not markers riding on it -- see
  // registry.ts's `holdsInertContents`. Without this, every board-wide broadcast that
  // flattens `attachedCards` (to reach the marker family) also fires the abilities of
  // whatever is sitting inertly in here.
  holdsInertContents: true,
  spellStaysInPlay: true,
  spellTargets: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player) return [];
    return player.hand.filter((c) => {
      const def = cardDb.get(c.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, "d'Resh"));
    });
  },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const player = ctx.controllingPlayer;
    const index = player.hand.findIndex((c) => c.instanceId === ctx.chosenTargetId);
    if (index === -1) return;
    const def = ctx.cardDb.get(player.hand[index]!.definitionKey);
    if (def?.card_type !== 'Creature' || !def.regions.includes(regionForTargetFilter(ctx.state, "d'Resh"))) return;

    const [creature] = player.hand.splice(index, 1);
    attachCard(ctx.source, creature!);
    setCounter(ctx.source, 'triggerTurn', nextOwnTurnNumber(ctx.state));
    player.inPlay.push(ctx.source);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ["d'Resh"],
  onOwnTurnStart: (state, cardDb, self, rng) => {
    const triggerTurn = getCounter(self, 'triggerTurn');
    if (triggerTurn <= 0 || state.turnNumber < triggerTurn) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;

    const creature = detachCard(self, self.attachedCards[0]?.instanceId ?? '');
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
    if (!creature) return;
    creature.currentEnergy = effectiveStartingEnergy(state, cardDb, creature);
    player.inPlay.push(creature);
    broadcastCardEnteredPlay(state, cardDb, player.playerId, creature);
    checkCreatureDefeats(state, cardDb);
  },
});
