// Paralit -- "Lie Channel (1): Discard Paralit from play. Add five energy to your Magi. Discard
// one energy from each of your Creatures in play." No target. Self-discard happens first (per
// text order), so the own-Creature sweep correctly excludes Paralit itself (already gone).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { addEnergy, discardEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Paralit', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Lie Channel') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    if (ctx.controllingPlayer.activeMagi) {
      addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, 5, 'power');
    }
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
    }
  },
});
