// Brushfire (Spell, Cald/Weave) -- "Choose any one Creature in play. Discard two energy from the
// chosen Creature. Once per turn, you may play any one Brushfire from your discard pile as if it
// were in your hand." Layer 3 of the discard-pile-visibility project (2026-07-20) -- discovered
// riding the same gap as Quanjuel's Timewalk while scoping that mechanism, built alongside it.
//
// Main clause is a plain targeted Spell, same "any Creature in play" pool + discardEnergy shape as
// Shockwave/Storm Cloud etc. The recurring-play clause is UNLIKE Quanjuel's: it's printed on every
// copy of Brushfire itself (no external granter), self-scoped ("any ONE Brushfire," not "any
// Recurring card"), and gated "once per turn" -- tracked via a plain duration tag on the
// controller's activeMagi (BRUSHFIRE_DISCARD_PLAY_USED, set by registry.ts's onPlayedFromDiscardPile
// hook once a Brushfire is actually played this way), same "grant lives on the Magi, not the card
// itself" idiom as Quanjuel's TIMEWALK_GRANTED -- needed here too since the just-played Brushfire
// immediately leaves the discard pile (or ends up back in it after resolving), so tagging ITSELF
// wouldn't correctly block a DIFFERENT copy from being played the same turn.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import { getPlayer } from '../types/state.js';

const BRUSHFIRE_DISCARD_PLAY_USED = 'brushfireDiscardPlayUsedThisTurn';

registerCardEffect('Brushfire', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    discardEnergy(ctx.state, ctx.cardDb, target, 2, 'spell', undefined, ctx.rng);
  },
  offersPlayFromDiscardPile: (state, cardDb, self, playerId) => {
    if (self.controllerId !== playerId) return false;
    const player = getPlayer(state, playerId);
    if (!player.activeMagi) return false;
    return !hasDurationTag(player.activeMagi, BRUSHFIRE_DISCARD_PLAY_USED);
  },
  onPlayedFromDiscardPile: (state, cardDb, self) => {
    const player = getPlayer(state, self.controllerId);
    if (player.activeMagi) addDurationTag(state, cardDb, player.activeMagi, BRUSHFIRE_DISCARD_PLAY_USED, state.turnNumber);
  },
});
