// Harban -- "Browbeat: Choose any one opposing Creature in play with only one energy. Gain
// control of the chosen Creature." No "cannot attack this turn" clause here, unlike most of this
// bucket -- the stolen Creature can attack immediately if otherwise able to.

import { registerCardEffect } from './registry.js';
import { opposingCreatures } from '../targeting.js';
import { gainControl } from '../effects.js';

registerCardEffect('Harban', {
  powerTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId).filter((c) => (c.currentEnergy ?? 0) === 1),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Browbeat') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    if (!target || (target.currentEnergy ?? 0) !== 1) return;

    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
  },
});
