// K'teeb -- both printed clauses:
//   "Dream Cross: Choose any one of your other Creatures in play. Until the chosen Creature
//   leaves play, all Powers printed on the chosen Creature are also considered to be printed on
//   K'teeb. K'teeb cannot copy a Power that it already has. All of K'teeb's Powers that reference
//   the card that they are printed on now reference K'teeb." Simpler than Taglat -- copies ALL
//   Powers off ONE chosen card (not one specific Power off a pool spanning many cards), so this
//   just uses the normal single-target powerTargets/chosenTargetId shape.
//   "Dreamwarp: As you play K'teeb, increase or decrease its starting energy by up to one, until
//   the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { allUsablePowers } from '../power.js';
import { addCopiedPower } from '../copiedPowers.js';

registerCardEffect("K'teeb", {
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => c.instanceId !== sourceInstanceId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Cross') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId && c.instanceId !== ctx.source.instanceId
    );
    if (!target) return;
    const def = ctx.cardDb.get(target.definitionKey);
    if (!def) return;

    const alreadyHave = new Set(allUsablePowers(ctx.state, ctx.cardDb, ctx.source).map((p) => p.name));
    for (const power of def.powers) {
      if (alreadyHave.has(power.name)) continue;
      addCopiedPower(ctx.source, power, def.key, { whenInstanceLeavesPlay: target.instanceId });
      alreadyHave.add(power.name); // don't copy the same-named power twice if K'teeb prints duplicates
    }
  },
  dreamwarpRange: () => 1,
});
