// Staff of Vines -- Effect "imbue": "All of your Creatures in play gain 'Power -- Strengthen: (1)
// Choose any one Creature in play. Add one energy to the chosen Creature.'" Built task #37
// (Paradwyn pass, Category C, 2026-07-17), reusing Ergar's Ignite pattern (ergar.ts) almost
// verbatim: copiedPowers.ts's addCopiedPower with `expiresWhenInstanceLeavesPlay` grants a made-up
// Power to every own Creature, `fromDefinitionKey` set to Staff of Vines' own key so power.ts's
// dispatch routes activation back to THIS file's own resolvePower. Unlike Ergar's Cald-only grant,
// Staff of Vines has no region restriction ("All of your Creatures").

import { registerCardEffect } from './registry.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import { creaturesControlledBy, allCreaturesInPlay } from '../targeting.js';
import { addCopiedPower, activeCopiedPowers } from '../copiedPowers.js';
import { addEnergy } from '../effects.js';

const STRENGTHEN_POWER = {
  cost: 1,
  name: 'Strengthen',
  text: 'Choose any one Creature in play. Add one energy to the chosen Creature.',
};

function grantIfEligible(state: GameState, cardDb: CardDatabase, staff: CardInstance, target: CardInstance): void {
  const targetDef = cardDb.get(target.definitionKey);
  if (!targetDef || targetDef.card_type !== 'Creature') return;
  if (target.controllerId !== staff.controllerId) return;
  const staffDef = cardDb.get(staff.definitionKey);
  if (!staffDef) return;
  const alreadyGranted = activeCopiedPowers(state, target).some(
    (cp) => cp.power.name === 'Strengthen' && cp.fromDefinitionKey === staffDef.key
  );
  if (alreadyGranted) return;
  addCopiedPower(target, STRENGTHEN_POWER, staffDef.key, { whenInstanceLeavesPlay: staff.instanceId });
}

registerCardEffect('Staff of Vines', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) {
      for (const creature of creaturesControlledBy(state, cardDb, self.controllerId)) {
        grantIfEligible(state, cardDb, self, creature);
      }
    } else {
      grantIfEligible(state, cardDb, self, played);
    }
  },
  powerTargets: (state, cardDb, playerId, powerName) => {
    if (powerName !== 'Strengthen') return undefined;
    return allCreaturesInPlay(state, cardDb);
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Strengthen') return;
    if (!ctx.chosenTargetId) return;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    addEnergy(ctx.state, ctx.cardDb, target, 1, 'power');
  },
});
