// Arderial's Crown -- "Strengthen: At the beginning of your turn, choose any one Creature in
// play. Add one energy to the chosen Creature." No "your"/"opposing" qualifier -- either side.
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first eligible in array order"
// simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const STRENGTHEN_PENDING = 'arderialsCrownStrengthenPending';

registerCardEffect("Arderial's Crown", {
  onOwnTurnStart: (state, cardDb, self) => {
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, STRENGTHEN_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(STRENGTHEN_PENDING)) return undefined;
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Arderial's Crown's Strengthen: choose a Creature to add 1 energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, STRENGTHEN_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) addEnergy(state, cardDb, target, 1, 'effect');
  },
});
