// Shared helper for the "cannot be discarded from play by opposing cards that specifically
// discard Relics from play. Discard [this] from play if your Magi is not a [region] Magi" family
// (Kybar's Fang, Vault of Knowledge Key, Gift of the Weave, Gate to Ombor) -- the immunity half is
// each card's own `canBeDiscardedFromPlay` hook (registry.ts); this covers the self-discard half,
// checked at the start of the controller's own turn (the same "standing condition, react each
// turn" cadence used throughout this codebase for continuous checks with no dedicated trigger
// event).

import type { GameState } from '../types/state.js';
import type { CardDatabase, CardDefinition } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { Rng } from '../rng.js';
import { discardFromPlay } from '../effects.js';

export function applyRegionLockedRelic(
  state: GameState,
  cardDb: CardDatabase,
  self: CardInstance,
  isEligible: (magiDef: CardDefinition) => boolean,
  rng?: Rng
): void {
  const owner = state.players.get(self.controllerId);
  const magi = owner?.activeMagi;
  const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
  if (magiDef && isEligible(magiDef)) return;
  if (owner) discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
}
