// Vim and Vigor (Spell, cost 4) -- "Choose an opposing Creature in play. Move all energy above the
// chosen Creature's starting energy to your Magi. Naroom Shadow Magi may play Vim and Vigor."
// Naroom Spell pass, Category B (2026-07-23). "Naroom Shadow Magi may play" is already fully
// data-driven (region_restrictive: false, shadow_magi_excluded: false in cards_final.json) -- no
// code needed, same as every other unrestricted card. printedStartingEnergy + effects.ts's
// rearrangeEnergy (the inverse direction of tapRoots.ts's own two-Creature transfer): move only the
// excess above starting energy from the opposing Creature to the caster's own Magi.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { findInPlayById, opposingCreatures, effectiveStartingEnergy } from '../targeting.js';

registerCardEffect('Vim and Vigor', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return; // must be opposing
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;

    const starting = effectiveStartingEnergy(ctx.state, ctx.cardDb, target);
    const excess = (target.currentEnergy ?? 0) - starting;
    if (excess > 0) rearrangeEnergy(ctx.state, ctx.cardDb, target, magi, excess, ctx.rng);
  },
});
