// d'Rasha -- "Foretelling (1): Choose a player's deck. Look at the top three cards of the chosen
// deck. You may choose one of the cards and place it at the bottom of that deck. Place the
// remaining cards on the top of that deck in any order." First user of deckTopReveal's
// `whoseDeck: 'target'` -- "a player's deck" means ANY player, including d'Rasha's own controller,
// so powerTargets uses allMagiInPlay (not opposingMagi). The chosen card moves to the BOTTOM; the
// other two are left alone, which -- since only the chosen one is removed from the top -- keeps
// them on top in their original relative order (the documented "any order" simplification, same
// as Orothean Goggles).

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { addToZone, removeFromZone } from '../zones.js';

registerCardEffect("d'Rasha", {
  powerTargets: (state) => allMagiInPlay(state),
  deckTopReveal: { count: 3, whoseDeck: 'target' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Foretelling') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const owner = ctx.state.players.get(chosenMagi.controllerId);
    if (!owner) return;

    const ids = ctx.chosenDeckTopIds ?? [];
    if (ids.length > 1) return;
    if (ids.length === 0) return;
    const [id] = ids;
    const top = owner.deck.slice(0, 3).map((c) => c.instanceId);
    if (!top.includes(id!)) return;

    const card = removeFromZone(owner, 'deck', id!);
    addToZone(owner, 'deck', card, 'bottom');
  },
});
