export interface PowerContext {
  state: GameState;
  cardDb: CardDatabase;
  source: CardInstance;
  controllingPlayer: PlayerState;
  powerName: string;
  /** The X value chosen at cost-payment time, if this Power has a variable cost -- effect text
   *  often references the same X (e.g. "Add X energy to the chosen Creature"). */
  chosenXValue?: number;
  /** A target instance id the caller (UI) collected before invoking usePower, if this Power
   *  needs one. Card resolve functions must re-validate it's still a legal target, not assume
   *  it still is -- state can change between when the UI collected it and now. */
  chosenTargetId?: string;
  /** Instance ids of the player's OWN hand cards chosen to satisfy a handDiscardCost
   *  (registry.ts), if this Power has one -- the card's own resolve function does the actual
   *  discard (via effects.ts's discardFromHand) and re-validates the choice, same as
   *  chosenTargetId. Undefined for the overwhelming majority of Powers, which have no
   *  hand-discard-cost at all. */
  chosenHandCardIds?: string[];
  /** One array of instance ids per powerTargetSlots (registry.ts) slot, in slot order, if this
   *  Power uses multi-slot targeting instead of the simpler single chosenTargetId. */
  chosenSlotIds?: readonly string[][];
  /** The answer to a registry.ts booleanChoice, if this Power has one. */
  chosenBoolean?: boolean;
  /** Instance ids of the TARGET's controller's OWN hand cards chosen to satisfy an
   *  opponentHandDiscardChoice (registry.ts), e.g. Giant Vulbor's "That Creature's Magi may
   *  discard up to two cards." Distinct from chosenHandCardIds, which is always the ACTIVE
   *  player's own hand. */
  chosenOpponentHandCardIds?: string[];
  /** Instance ids the ACTIVE player chose from the TARGET's hand to satisfy a
   *  chooseFromOpponentHand (registry.ts), e.g. Epik's "choose up to two Creature cards there" --
   *  the target then discards these. Distinct from chosenOpponentHandCardIds, which is the
   *  TARGET's own choice from their own hand, not the active player's. */
  chosenFromOpponentHandIds?: string[];
  /** Instance ids of the player's OWN deck cards chosen to satisfy a deckSearch (registry.ts),
   *  e.g. Barak the Red's "Search your deck for any one Cald Creature." */
  chosenDeckSearchIds?: string[];
  /** Instance ids of the player's OWN discard pile cards chosen to satisfy a discardPileSearch
   *  (registry.ts), e.g. Delia's "Choose any one Vellup in your discard pile." Destination (hand /
   *  deck top / shuffled into deck) is decided by each card's own resolvePower, not this field. */
  chosenDiscardPileIds?: string[];
  /** Instance ids chosen from a deckTopReveal (registry.ts) pool, in whatever order the chooser
   *  picked them -- e.g. Geoh's "choose up to one Creature, up to one Relic, and up to one Spell
   *  from the revealed cards." What happens to chosen vs. unchosen cards is entirely up to each
   *  card's own resolvePower. */
  chosenDeckTopIds?: string[];
  /** Instance ids of the player's OWN hand cards chosen to satisfy a handRevealCost (registry.ts)
   *  -- these stay in hand, unlike chosenHandCardIds. */
  chosenHandRevealIds?: string[];
  /** Player-chosen amounts for `powerAmountChoices` (registry.ts, task #532), keyed by each
   *  choice's `id`. `resolvePower` MUST re-clamp what it reads -- the UI collects these, so treat
   *  them the same trust-but-verify way as every other pre-collected choice here. */
  chosenAmounts?: Record<string, number>;
  /** The instance id of the player's OWN hand card chosen to satisfy a handPlayChoice
   *  (registry.ts), e.g. Warrior's Boots' "Immediately play a Creature from your hand." Always a
   *  single id, not an array -- every real card using this picks exactly one. */
  chosenHandPlayId?: string;
  /** The answer to a registry.ts categoryChoice, if this Power has one. */
  chosenCategory?: string;
  /**
   * Task #577 (2026-07-28, owner ruling): the Dreamwarp delta chosen for a Creature this Power
   * plays "as if it were in your hand" -- Gia's Tome's Research and Bottled City's Release. Owner:
   * "the intent for cards like Tome and Bottled City is to give you another way to play a creature,
   * which should allow you to dreamwarp when attempting to play them."
   *
   * Needed as its own channel because neither card can call `play.ts#playCard` (hand-only by
   * construction), and `PlayCardOptions.chosenDreamwarpAdjustment` is read at exactly one place
   * inside that hand-play path. `resolvePower` MUST clamp what it reads against
   * `targeting.ts#effectiveDreamwarpRange` -- the UI collects this, so it is trust-but-verify like
   * every other pre-collected field here, and a Creature with no Dreamwarp must ignore it entirely.
   */
  chosenDreamwarpAdjustment?: number;
  /**
   * Task #405 (2026-07-21, playtest bug report): the OWN resolve-time choices (target/cost/etc.)
   * of a Spell this Power discovers/steals mid-resolution and plays via effects.ts's
   * `playFromZone`/`castSpellFromOpponentZone` (Tomes of the Great Library's Research, Maelstrom
   * Flask's Uncork, Hand of the Sky's/Heart of the Sky's Dream Steal). Distinct from this
   * PowerContext's OWN `chosen*` fields above (which answer THIS Power's own targeting/choices,
   * e.g. Hand of the Sky's `chosenTargetId` already means "which Spell to steal" -- a DIFFERENT
   * question from "what does the stolen Spell's own resolveSpell need"). The UI collects this via
   * a second, nested action prompt (Play.tsx's `maybeOpenNestedSpellPrompt`) once it knows which
   * specific Spell this Power's own choice resolves to, mirroring how Tempest Hyren/Good Ol' Ashgar
   * already collect a SECOND prompt for a Spell played straight from hand -- generalized here to a
   * Spell discovered in a deck or an opponent's zone. Undefined for every Power except these four.
   */
  nestedSpellChoices?: NestedSpellChoices;
  /** For dice-rolling and other randomized Powers (effects.ts's rollDie) -- threaded through from
   *  usePower's own rng param (defaults to defaultRng) so tests can seed it deterministically,
   *  same pattern combat.ts/turn.ts/setup.ts already use. */
  rng: Rng;
}

export interface PowerEffectHooks {
  /**
   * Steps 4-5: make choices/targets and apply results. If omitted, usePower automatically looks
   * up the source card's name in the cardEffects registry (see cardEffects/registry.ts) and uses
   * its resolvePower, if one has been implemented -- this override exists mainly for tests, and
   * for the long tail of cards that don't have a registry entry yet (an omitted hook and no
   * registry entry both mean "cost paid, no effect," which is the correct, honest default per
   * rules-reference.md §14 rather than a bug). The Power's cost is paid regardless of whether
   * an effect ends up running -- per §9, announcing and paying (steps 1-2) happen before
   * targeting is even checked (step 4).
   */
  resolveEffect?: (ctx: PowerContext) => void;
}

