export type PowerLegality =
  | {
      legal: true;
      cost: number;
      paidBy: 'source' | 'magi';
      // Identifies exactly which card's `reactsToWindow`/`grantsExtraPowerUse` PURE check granted
      // this use, if any -- so usePower can invoke that SAME card's `confirmReactionToWindow`/
      // `confirmExtraPowerUse` exactly once, at the real moment of action, instead of the grant's
      // once-per-turn bookkeeping living inside the (repeatedly-probed) legality check itself. See
      // those hooks' own doc comments in registry.ts for the full split rationale.
      reactedViaInstanceId?: string;
      extraUseGrantedByInstanceId?: string;
      // Set when this use was granted by Bloom's PlayerState.bloomBonusActionPending flag rather
      // than a normal active-player/reactive-window grant -- so usePower knows to clear that flag
      // exactly once, at the real moment of action (see grantedViaBloomBonus's own comment above).
      grantedViaBloomBonus?: boolean;
      /** Why `cost` is what it is -- purely informational, see costBreakdown.ts. Nothing in the
       *  engine reads it. */
      breakdown?: CostBreakdown;
    }
  | {
      legal: false;
      reason: string;
      /** Present ONLY on the "not enough energy" refusal, which is exactly the case where the
       *  player is staring at a printed cost that doesn't match the number in the reason string
       *  and needs to know what moved it (the Kybar's Fang / Essence of Frost report). */
      breakdown?: CostBreakdown;
    };

/**
 * Finds a named Power on `instance`, checking its own printed powers first and then its
 * currently-active copied ones (copiedPowers.ts). `def` is always the instance's OWN card
 * (used for identity/card_type purposes, e.g. Relic-vs-not for who pays); `dispatchDef` is whose
 * registry entry should actually RUN the Power's logic -- the instance's own def for a native
 * Power, or the ORIGINAL card's def for a copied one (targeting/legalPhases/resolvePower all need
 * to run the original implementation, not a nonexistent one on the copier). Exported for
 * queries.ts and the UI, which both need the exact same "own or copied" dispatch logic power.ts
 * itself uses, not just this file's internal callers.
 */
export function findPower(
  state: GameState,
  cardDb: CardDatabase,
  instance: CardInstance,
  powerName: string
): { def: CardDefinition | undefined; power: Power | undefined; dispatchDef: CardDefinition | undefined } {
  const def = cardDb.get(instance.definitionKey);
  const ownPower = def?.powers.find((p) => p.name === powerName);
  if (ownPower) return { def, power: ownPower, dispatchDef: def };

  // registry.ts's syntheticPowers -- a player-activatable action described only in a card's
  // Effect text, not a real entry in the database's own `powers[]` array (Gia's Tome's Research,
  // Bottled City's Release). Checked before copied Powers, same "this card's own ability first"
  // ordering as ownPower above.
  const syntheticPower = def && getCardEffectByName(def.name)?.syntheticPowers?.find((p) => p.name === powerName);
  if (syntheticPower) return { def, power: syntheticPower, dispatchDef: def };

  for (const cp of activeCopiedPowers(state, instance)) {
    if (cp.power.name === powerName) {
      return { def, power: cp.power, dispatchDef: cardDb.get(cp.fromDefinitionKey) };
    }
  }

  // C3 Q5 (2026-07-28 ruling): a granted Effect from a card whose activatable ability lives in
  // syntheticPowers (Gia's Tome's Research, Bottled City's Release -- described only in Effect
  // text, not in the database's `powers[]`) must still be usable on the recipient. Handled here as
  // a fourth findPower arm, NOT via effectsFor, so every Power-activation site downstream stays
  // unchanged and the two mechanisms never overlap. A narrowed grant (Taglat's per-Effect copy,
  // `effectName` set) only surfaces synthetic Powers whose OWN name matches -- so grabbing a
  // different named Effect from the same donor card doesn't also unlock this one.
  for (const granted of activeGrantedEffects(state, instance)) {
    if (granted.effectName !== undefined && granted.effectName !== powerName) continue;
    const grantedDef = cardDb.get(granted.fromDefinitionKey);
    const grantedSynth = grantedDef && getCardEffectByName(grantedDef.name)?.syntheticPowers?.find((p) => p.name === powerName);
    if (grantedSynth) return { def, power: grantedSynth, dispatchDef: grantedDef };
  }

  return { def, power: undefined, dispatchDef: undefined };
}

/** Every Power currently usable on `instance` -- its own printed powers plus any active copied
 *  ones -- for queries.ts's getLegalMoves, which needs to enumerate ALL of them, not just find
 *  one by name. */
export function allUsablePowers(state: GameState, cardDb: CardDatabase, instance: CardInstance): Power[] {
  const def = cardDb.get(instance.definitionKey);
  const syntheticPowers = (def && getCardEffectByName(def.name)?.syntheticPowers) ?? [];
  // Granted syntheticPowers (Q5, 2026-07-28) -- see findPower's own fourth arm above. A narrowed
  // grant (Taglat) only exposes synthetics whose OWN name matches the granted effectName.
  const grantedSyntheticPowers: Power[] = [];
  for (const granted of activeGrantedEffects(state, instance)) {
    const grantedDef = cardDb.get(granted.fromDefinitionKey);
    const synth = grantedDef && getCardEffectByName(grantedDef.name)?.syntheticPowers;
    if (!synth) continue;
    for (const p of synth) {
      if (granted.effectName === undefined || granted.effectName === p.name) grantedSyntheticPowers.push(p);
    }
  }
  return [...(def?.powers ?? []), ...syntheticPowers, ...activeCopiedPowers(state, instance).map((cp) => cp.power), ...grantedSyntheticPowers];
}

/** True for a Power cost that needs a player-chosen X -- either the plain 'X' (chosenXValue IS
 *  the cost) or an "X+N" pattern like Qwade's Leech ("X+4": cost = chosenXValue + 4). Shared with
 *  queries.ts so the UI knows to prompt for X in both shapes, not just the plain 'X' one. */
export function isVariableCostPower(cost: Power['cost']): boolean {
  return cost === 'X' || (typeof cost === 'string' && /^X\+\d+$/.test(cost));
}

/** Resolves an 'X' or 'X+N' cost (Power OR card) against a chosen X value. Exported so play.ts can
 *  reuse the exact same "X+N" parsing for a card's own printed cost (e.g. Turn/Stone Storm/Syphon
 *  Vortex/Burrow/Wanderlust's "X+N" Spell costs), instead of duplicating the regex. */
export function resolveVariableCost(cost: number | string, chosenXValue: number): number {
  if (cost === 'X') return chosenXValue;
  const match = /^X\+(\d+)$/.exec(String(cost));
  return chosenXValue + (match ? Number(match[1]) : 0);
}

function findSource(player: PlayerState, sourceInstanceId: string): CardInstance | undefined {
  if (player.activeMagi?.instanceId === sourceInstanceId) return player.activeMagi;
  return player.inPlay.find((c) => c.instanceId === sourceInstanceId);
}

export function isLegalPowerUse(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  options: UsePowerOptions = {}
): PowerLegality {
  // A one-shot off-turn reactive Power use (task #37, 2026-07-17: Yricho's Athletic/Bazha's
  // Pendant's Reply/T'kanzam's Dream Loops) -- same "the only way a non-active player's action is
  // ever legal" shape as play.ts's isReactiveWindowCandidate. Narrowed below (once `source` is
  // known) by a `reactsToWindow` check -- first against the source card's OWN hook (T'kanzam's
  // shape: reacts by using its OWN Power), falling back to a broadcast over every OTHER of the
  // reacting player's own cards (Yricho/Bazha's Pendant's shape: grants a reactive use on ANY of
  // the reacting player's cards, not just themselves).
  const isReactiveWindowCandidate =
    state.activePlayerId !== playerId &&
    state.reactiveWindow?.kind === 'opponentPlayOrPower' &&
    state.reactiveWindow.reactingPlayerId === playerId;
  // Bloom's own PlayerState.bloomBonusActionPending (own doc comment) -- a plain flag grant,
  // independent of GameState.reactiveWindow, since Bloom itself is long gone from play by the
  // time this bonus action is taken.
  const isBloomBonusCandidate = state.activePlayerId !== playerId && state.players.get(playerId)?.bloomBonusActionPending === true;
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) {
    return { legal: false, reason: 'Source card is not in play under your control' };
  }
  const { def, power, dispatchDef } = findPower(state, cardDb, source, powerName);
  if (!def || !power) {
    return { legal: false, reason: `No Power named "${powerName}" on this card` };
  }
  // Phase gate. Powers default to the prs1/prs2 (Powers/Relics/Spells) step, but a Power may declare
  // its OWN legalPhases (registry.ts), which REPLACES that default -- so a Power can be usable in a
  // DIFFERENT step, e.g. Gia's Tome's Research plays a Creature "as if from hand," so it belongs in
  // playNewCreatures, not prs1/prs2 (task #49 playtest fix, 2026-07-19: Research was usable at the
  // wrong time). legalPhases travels with a copied Power via dispatchDef (its OWN rules text).
  const declaredPhases = dispatchDef ? getCardEffectByName(dispatchDef.name)?.legalPhases : undefined;
  const inAllowedPhase = declaredPhases
    ? declaredPhases.includes(state.phase)
    : state.phase === 'prs1' || state.phase === 'prs2';
  if (!inAllowedPhase && !isReactiveWindowCandidate && !isBloomBonusCandidate) {
    return {
      legal: false,
      reason: declaredPhases
        ? `This Power can only be used during ${declaredPhases.join(' or ')}`
        : 'Powers can only be used during a Powers/Relics/Spells phase',
    };
  }
  if (state.activePlayerId !== playerId && !isReactiveWindowCandidate && !isBloomBonusCandidate) {
    return { legal: false, reason: 'Only the active player may use Powers' };
  }
  // registry.ts's preventsBeingChosenForPowerBy (task #43, 2026-07-18, the Nar region pass:
  // Instant Fortress's Bastion) -- checked here, BEFORE cost is paid, since a hard block has to
  // happen earlier than offersPowerTargetRedirect's own injection point inside usePower (which
  // runs after cost is already committed). Scanned over EVERY in-play card + Magi on BOTH sides
  // (widened 2026-08-11, post-audit deferred-gap closure pass, Category C: Haunting Visions --
  // see the hook's own doc comment in registry.ts for why the old target-board-only scan couldn't
  // find a card like Haunting Visions, attached to an opponent's Creature while remaining under
  // its own caster's control) -- first match wins.
  if (options.chosenTargetId) {
    const chosenTarget = findCreatureOrMagiById(state, options.chosenTargetId);
    if (chosenTarget) {
      for (const p of state.players.values()) {
        const contributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
        for (const contributor of contributors) {
          for (const effect of effectsFor(state, cardDb, contributor)) {
            if (effect.preventsBeingChosenForPowerBy?.(state, cardDb, chosenTarget, playerId, contributor)) {
              return { legal: false, reason: `${cardDb.get(contributor.definitionKey)?.name ?? 'A card'} prevents you from choosing that target right now` };
            }
          }
        }
      }
    }
  }
  // Set below when the reactive-candidate block finds a granting card, and threaded through to the
  // final `legal: true` return so usePower knows exactly which card to confirm the grant on -- see
  // PowerLegality's own doc comment for why this can't just be re-derived from a second call.
  let reactedViaInstanceId: string | undefined;
  if (isReactiveWindowCandidate) {
    let sourceReacts = false;
    for (const effect of effectsFor(state, cardDb, source)) {
      if (effect.reactsToWindow?.(state, cardDb, state.reactiveWindow!, playerId, source)) {
        sourceReacts = true;
        break;
      }
    }
    if (sourceReacts) {
      reactedViaInstanceId = source.instanceId;
    } else {
      const contributors: CardInstance[] = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
      for (const contributor of contributors) {
        if (contributor.instanceId === source.instanceId) continue;
        for (const effect of effectsFor(state, cardDb, contributor)) {
          if (effect.reactsToWindow?.(state, cardDb, state.reactiveWindow!, playerId, contributor)) {
            reactedViaInstanceId = contributor.instanceId;
            break;
          }
        }
        if (reactedViaInstanceId) break;
      }
    }
    if (!reactedViaInstanceId) {
      return { legal: false, reason: 'No card grants a reactive Power use right now' };
    }
  }
  // Bloom's PlayerState.bloomBonusActionPending grants directly -- no card needs to be scanned for
  // a reactsToWindow match, since Bloom itself is long gone from play by the time this bonus Power
  // use happens. usePower clears the flag exactly once, gated on this same field in PowerLegality.
  const grantedViaBloomBonus = isBloomBonusCandidate;
  // legalPhases (a Power's OWN allowed phases, which travel with a copied Power via dispatchDef) is
  // now checked up-front in the phase gate near the top, so it can WIDEN the default prs1/prs2 window
  // (e.g. Gia's Tome's Research in playNewCreatures), not merely narrow it. `repeatable` (also
  // dispatchDef-scoped) is read below at the usedPowerNames once-per-turn check.
  // registry.ts's blocksDeckOrDiscardSearch (task #50k, 2026-07-12: Reality Anchor) -- a Power
  // that declares deckSearch/discardPileSearch is blocked outright while any in-play card + Magi
  // on either side claims the block.
  const dispatchEffect = dispatchDef && getCardEffectByName(dispatchDef.name);
  // Resolve per-Power (a card can declare deckSearch/discardPileSearch for ONE of its Powers only,
  // e.g. Monarch Hyren's Demand-but-not-Command) so this block-check doesn't wrongly reject a
  // non-searching Power on the same card (2026-07-18 bug audit).
  if (
    resolvePerPowerField(dispatchEffect?.deckSearch, powerName) ||
    resolvePerPowerField(dispatchEffect?.discardPileSearch, powerName)
  ) {
    for (const p of state.players.values()) {
      const candidates: CardInstance[] = p.activeMagi ? [...p.inPlay, p.activeMagi] : p.inPlay;
      for (const candidate of candidates) {
        const candidateDef = cardDb.get(candidate.definitionKey);
        for (const effect of effectsFor(state, cardDb, candidate)) {
          if (effect.blocksDeckOrDiscardSearch?.(state, cardDb, candidate)) {
            return { legal: false, reason: `${candidateDef!.name} prevents searching decks or discard piles` };
          }
        }
      }
    }
  }
  // registry.ts's preventsAttackAndPowerUseSameTurn (task #37, 2026-07-17: Archid's Stunning).
  if (source.attackedThisTurn) {
    for (const p of state.players.values()) {
      const contributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
      for (const contributor of contributors) {
        const contributorDef = cardDb.get(contributor.definitionKey);
        for (const effect of effectsFor(state, cardDb, contributor)) {
          if (effect.preventsAttackAndPowerUseSameTurn?.(state, cardDb, contributor, source)) {
            return { legal: false, reason: `${contributorDef!.name} prevents a Creature that attacked this turn from using a Power` };
          }
        }
      }
    }
  }
  // CardInstance.powerLockedOnTurnNumber (region-audit follow-up, 2026-07-24: Hood of Hiding's
  // Conceal -- "You may not use this Power on your next turn") -- a targeted, single-future-turn
  // lock on one named Power, unlike usedPowerNames' own "already used, refreshes each turn" gate
  // just below. A hard block, not bypassable by grantsExtraPowerUse (that hook's own doc comment
  // scopes it to the "already used" case specifically).
  if (source.powerLockedOnTurnNumber.get(powerName) === state.turnNumber) {
    return { legal: false, reason: `${def.name} cannot use ${powerName} this turn` };
  }
  // Set below when the already-used block finds a granting card, and threaded through to the final
  // `legal: true` return alongside reactedViaInstanceId -- same "identify the granter, confirm it
  // exactly once from usePower" split.
  let extraUseGrantedByInstanceId: string | undefined;
  const repeatable = (dispatchDef && getCardEffectByName(dispatchDef.name)?.repeatable) ?? false;
  // Only a mark from THIS SAME game turn still counts as "already used" -- see
  // CardInstance.usedPowerNames's own doc comment (task #38, 2026-07-17) for why a stale mark from
  // a prior turn (which turn.ts's reset only clears on this card's own controller's turn) must not
  // block a genuinely fresh reactive opportunity on a turn that has already moved on.
  if (!repeatable && source.usedPowerNames.get(powerName) === state.turnNumber) {
    // registry.ts's grantsExtraPowerUsePerTurn (Vault of Knowledge Key's Animite Infusion,
    // Bucket D Batch C part 1 closure 2026-08-14) -- persistent cap-raise (not a one-shot
    // override): sum grants across the ACTING player's board, compute the effective cap as
    // `1 + sum(grants)`, and if the actual use count is still under the cap, allow the use
    // without needing a `grantsExtraPowerUse` one-shot override below. Same acting-player-only
    // scope as `restrictsOwnPlayCountAt` (Korg's play-count limiter, Batch B) -- each
    // contributor's hook body filters its own target scope (Vault gates to own-controller
    // Relics only, so an opponent Vault doesn't help you use YOUR Powers more times).
    let animiteInfusionExtraGrants = 0;
    const animiteContributors: CardInstance[] = player.activeMagi
      ? [player.activeMagi, ...player.inPlay]
      : [...player.inPlay];
    for (const c of animiteContributors) {
      for (const e of effectsFor(state, cardDb, c)) {
        animiteInfusionExtraGrants += e.grantsExtraPowerUsePerTurn?.(state, cardDb, c, source, powerName) ?? 0;
      }
    }
    const animiteInfusionEffectiveCap = 1 + animiteInfusionExtraGrants;
    const animiteInfusionUsedCount = source.usedPowerCounts.get(powerName) ?? 0;
    if (animiteInfusionUsedCount < animiteInfusionEffectiveCap) {
      // Under the cap -- Animite Infusion (or a future similar effect) has raised the once-per-turn
      // ceiling for this Power this turn. Skip the blocker + one-shot-grant paths below entirely.
    } else {
    // registry.ts's grantsExtraPowerUse (task #50d, 2026-07-12: Bazha's and Rala Tail's Wild
    // Blooming) -- broadcast to every in-play card + Magi on both sides; if any contributor
    // claims a one-time override for THIS specific (source, powerName) pair, the already-used
    // block above is bypassed for this one use. A claimant is responsible for its own "once per
    // turn"/stacking bookkeeping (Rala Tail); this only ever fires once more per Power, since
    // `usedPowerNames` stays a plain boolean Set -- a third attempt hits this same check again
    // and needs a FRESH grant to succeed.
    // registry.ts's blocksFurtherExtraPowerUseGrants -- checked BEFORE the grant loop, because a
    // blocker's whole job is to stop a grant the loop would otherwise hand out. Rala Tail's applied
    // errata ("None of your other card effects may allow the Creature to use the Power again this
    // turn, and Wild Blooming cannot be used on Powers that have been used more than once already
    // this turn") is the only user today.
    //
    // BUG FIXED 2026-07-27 (owner playtest: "Rala Tail and Bazha currently can triple up on
    // powers"). Neither errata clause existed. The loop below takes the FIRST contributor that says
    // yes and, per its own comment, expects each claimant to police itself -- which works only while
    // one card is granting. With Rala Tail AND Bazha out, one granted use #2 and the other granted
    // use #3, and each was individually within its own limit.
    for (const p of state.players.values()) {
      const blockers = p.activeMagi ? [...p.inPlay, p.activeMagi] : p.inPlay;
      for (const blocker of blockers) {
        for (const effect of effectsFor(state, cardDb, blocker)) {
          if (effect.blocksFurtherExtraPowerUseGrants?.(state, cardDb, source, powerName, blocker)) {
            return { legal: false, reason: `"${powerName}" has already been used this turn` };
          }
        }
      }
    }
    for (const p of state.players.values()) {
      const candidates = p.activeMagi ? [...p.inPlay, p.activeMagi] : p.inPlay;
      for (const candidate of candidates) {
        for (const effect of effectsFor(state, cardDb, candidate)) {
          if (effect.grantsExtraPowerUse?.(state, cardDb, source, powerName, candidate)) {
            extraUseGrantedByInstanceId = candidate.instanceId;
            break;
          }
        }
        if (extraUseGrantedByInstanceId) break;
      }
      if (extraUseGrantedByInstanceId) break;
    }
    if (!extraUseGrantedByInstanceId) {
      return { legal: false, reason: `"${powerName}" has already been used this turn` };
    }
    } // end Animite Infusion cap raise's else branch (over-cap path)
  }
  // CANNOT_USE_POWER as either a temporary duration tag (Bubble Xyx's "not the turn played") or a
  // PERMANENT one (Karak/Umbu's per-instance target lock, applied to the TARGET card via
  // registry.ts's selfDiscardTargetPool/resolveSelfDiscardTarget doc comments -- durationTags.ts's
  // removePermanentTag lifts it again when the locking card releases its hold) -- same
  // duration-OR-permanent shape as isFrozen/isIllusion.
  // isRestrictionActive (task #26, 2026-07-26): Rayje's Cloak cancels an opposing card's
  // CANNOT_USE_POWER -- "opposing cards do not prevent your cards from using their Powers".
  if (isRestrictionActive(state, cardDb, source, CANNOT_USE_POWER)) {
    return { legal: false, reason: 'This card cannot use Powers right now' };
  }
  // Will of Orothe (Orothe Spell pass, Category C, 2026-07-24) -- PlayerState.creaturePowersLockedUntilTurn,
  // a PLAYER-level lock (covers Creatures played after the Spell resolves too, unlike a per-instance
  // duration tag) checked here for any Power whose source is a Creature controlled by the locked player.
  if (
    def.card_type === 'Creature' &&
    player.creaturePowersLockedUntilTurn !== null &&
    state.turnNumber <= player.creaturePowersLockedUntilTurn
  ) {
    return { legal: false, reason: 'Your Creatures cannot use Powers right now (Will of Orothe)' };
  }
  // registry.ts's blocksPowerUse (Sorreah's Suppress, Cactus Dryte's Deny, Rayje's Belt's
  // Lockdown) -- scans every in-play card + Magi on both sides, same broadcast shape as
  // onAttack/onPlay, since any of these three could be locking `source` right now regardless of
  // which side controls the locking card.
  // Rayje's Cloak (task #26, 2026-07-26): "Opposing cards do not prevent your cards from using
  // their Powers." Skips any blocker controlled by someone other than `source`'s controller when
  // that controller holds a Cloak. A blocker on your OWN side still applies -- it isn't opposing.
  const sourceHasCloak = hasActiveRayjesCloak(state, cardDb, source.controllerId);
  for (const p of state.players.values()) {
    if (sourceHasCloak && p.playerId !== source.controllerId) continue;
    const candidates = p.activeMagi ? [...p.inPlay, p.activeMagi] : p.inPlay;
    for (const candidate of candidates) {
      const candidateDef = cardDb.get(candidate.definitionKey);
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (effect.blocksPowerUse?.(state, cardDb, source, powerName, candidate)) {
          return { legal: false, reason: `${candidateDef!.name} prevents this Power from being used right now` };
        }
      }
    }
  }

  // Riptide's clause 2 (task #718, 2026-08-11) -- SELF-scoped ban on the caster's own subsequent
  // hand-discard Powers. Same shape as play.ts#isLegalToPlay's own gate for Spells (see that
  // comment). Uses `dispatchEffect` rather than the raw source's effect so a copied Power (Koza's
  // Borrow copying Iyori's Lost Wisdom) is judged by the DISPATCHED Power's own text, not the
  // source card's -- matching how every other declarative-per-Power check in this file already
  // resolves. Owner ruling: only the CASTER of Riptide is restricted; opponents' hand-discard
  // Powers continue to work.
  if (
    player.riptideBanExpiresAfterTurnNumber !== null &&
    state.turnNumber <= player.riptideBanExpiresAfterTurnNumber &&
    (dispatchEffect ?? getCardEffectByName(def.name))?.causesOpponentHandDiscard === true
  ) {
    return { legal: false, reason: 'Riptide prevents you from using another opponent-hand-discard Power until end of your next turn' };
  }

  // Tranquility clause 1 (Wave DD1 of the deferred coverage audit, 2026-08-13) -- Powers half of
  // the same ban play.ts's `isLegalToPlay` handles for Spells. Global-scoped (no "you"/"opponent"
  // qualifier in printed text) -- scan BOTH players' `tranquilityBanExpiresAfterTurnNumber`, not
  // just the acting player's. Uses `dispatchEffect ?? getCardEffectByName(def.name)` like the
  // Riptide gate above so a copied Power (Koza's Borrow copying an energy-discarding Power) is
  // judged by the DISPATCHED Power's own text, not the source card's. The Effects half of
  // Tranquility's printed clause is an accepted simplification -- see tranquility.ts's header.
  if ((dispatchEffect ?? getCardEffectByName(def.name))?.causesEnergyDiscard === true) {
    for (const p of state.players.values()) {
      if (p.tranquilityBanExpiresAfterTurnNumber !== null && state.turnNumber <= p.tranquilityBanExpiresAfterTurnNumber) {
        return { legal: false, reason: 'Tranquility prevents Powers that discard energy from being used right now' };
      }
    }
  }

  // K'teeb Cub's Empower (task #572) -- see POWER_COST_ZEROED's doc comment in durationTags.ts.
  // Checked here so an X-cost Power does NOT demand a chosenXValue the player has no say over
  // ("if there is an X in the cost, X equals zero"), and applied again after the floor below.
  const powerCostZeroed = hasDurationTag(source, POWER_COST_ZEROED);

  let cost: number;
  if (isVariableCostPower(power.cost)) {
    if (!powerCostZeroed && (options.chosenXValue === undefined || options.chosenXValue < 0)) {
      return { legal: false, reason: 'This Power has a variable X cost -- chosenXValue is required' };
    }
    cost = powerCostZeroed ? 0 : resolveVariableCost(power.cost!, options.chosenXValue!);
  } else if (power.cost === undefined || power.cost === null) {
    // Real data quirk, not an error: 212 real Powers have no `cost` field at all -- a
    // genuinely free activated ability (often with a different, non-energy cost baked into its
    // own text instead, e.g. "Discard [this card] from play"). Caught live: paying "undefined"
    // energy produced NaN instead of leaving energy untouched.
    cost = 0;
  } else if (typeof power.cost === 'number') {
    cost = power.cost;
  } else {
    // Real data quirk (pre-existing, not introduced by isVariableCostPower above): a handful of
    // real Powers have their numeric cost stored as a numeric-looking STRING ("6" instead of 6) --
    // the declared Power.cost type doesn't officially allow this, but the raw JSON does. Number()
    // recovers the intended value; falls back to 0 only if it's truly unparseable.
    const parsed = Number(power.cost);
    cost = Number.isFinite(parsed) ? parsed : 0;
  }

  // Cost breakdown (tasks #24 + #529, 2026-07-26) -- purely informational, see costBreakdown.ts.
  // Snapshotted HERE, after the printed/variable cost resolves and before the first adjustment, so
  // `printed` is exactly the number on the card face that the player is comparing against.
  const printedCost = cost;
  const costAdjustments: CostAdjustment[] = [];

  // FROZEN's baseline rule (durationTags.ts): "Powers on frozen cards cost one additional energy
  // to use" -- based on the SOURCE card itself being frozen (e.g. a frozen Relic still costs +1
  // even though its Power is paid from the Magi, not the Relic's own energy).
  if (isFrozen(state, cardDb, source)) {
    cost += 1;
    // Name the freezing card, not just "Frozen" -- this exact +1 on a Relic (Essence of Frost
    // freezes ALL card types) is the playtest report that motivated the whole breakdown.
    noteAdjustment(costAdjustments, frozenByLabel(state, cardDb, source) ?? 'Frozen', 1);
  }

  // registry.ts's powerCostModifier (Drajan's Fight: "Opposing Powers cost one additional energy
  // to use") -- same broadcast-and-sum shape as costModifier above. Floored at 0 by default (a
  // genuinely free Power staying free if a reduction ever outweighs its cost is fine; Powers don't
  // have the same universal "at least 1" convention Creature/Relic/Spell plays do) -- UNLESS at
  // least one applicable contributor's own printed text says "to a minimum of one"
  // (powerCostFloorsAtOne, task 2026-07-19 playtest fix: Rainbow Hyren's Shining Light was taking
  // Monarch Hyren's Command to 0 instead of its own stated floor of 1; same bug affected Korok's
  // Empower and Orothean Gloves).
  let floorsAtOne = false;
  for (const p of state.players.values()) {
    const candidates = p.activeMagi ? [...p.inPlay, p.activeMagi] : p.inPlay;
    for (const candidate of candidates) {
      const candidateDef = cardDb.get(candidate.definitionKey);
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (effect.powerCostModifier) {
          const delta = effect.powerCostModifier(state, cardDb, playerId, def, candidate, source);
          cost += delta;
          noteAdjustment(costAdjustments, candidateDef!.name, delta);
        }
        if (effect.powerCostFloorsAtOne?.(state, cardDb, playerId, def, candidate, source)) {
          floorsAtOne = true;
        }
      }
    }
  }
  // CardInstance.regionPowerCostReduction, held on the power-user's own activeMagi (task #53-4,
  // 2026-07-21: Shadow Ritual -- "Until the end of the turn, all Powers on your Core cards cost two
  // less energy to use") -- read directly, not via a per-card registerCardEffect hook, since an
  // arbitrary Shadow Magi could be holding this one-turn grant and shouldn't need its own bespoke
  // powerCostModifier registration just to carry it. See the field's own doc comment for why it
  // can't live on Shadow Ritual's own (immediately-discarded) instance the way costReductionGrant
  // does for Nashiq/Lens of Truth.
  const regionDiscount = player.activeMagi?.regionPowerCostReduction;
  if (regionDiscount && state.turnNumber <= regionDiscount.expiresAfterTurnNumber && effectiveRegions(state, cardDb, source).includes(regionDiscount.region)) {
    cost -= regionDiscount.amount;
    // No card name available -- the grant is a bare field on the Magi (see its doc comment above),
    // so the region it applies to is the most identifying thing that can be said about it.
    noteAdjustment(costAdjustments, `${regionDiscount.region} Power discount`, -regionDiscount.amount);
  }
  // Icepack (Nar Spell pass, Category A, 2026-07-22): "attach to a Creature; if the Creature is
  // Frozen, its Powers cost two less energy, to a minimum of one." Checked directly here (not via
  // a per-card registerCardEffect hook) since the discount belongs to whichever ARBITRARY host
  // Creature Icepack is attached to, not to Icepack's own registration -- the powerCostModifier
  // broadcast loop above only scans top-level inPlay/activeMagi, never attachedCards, so an
  // attached card's own hook would never be reached. Same "generic direct consultation, not a
  // per-card hook" pattern this project already uses for arbitrary-host grants (e.g. Vertigo's
  // costSurchargeNextOwnTurn, Ominous Presence's temporaryRegionGrant).
  const icepack = source.attachedCards?.find((a) => cardDb.get(a.definitionKey)?.name === 'Icepack');
  if (icepack && isFrozen(state, cardDb, source)) {
    cost -= 2;
    floorsAtOne = true;
    noteAdjustment(costAdjustments, 'Icepack', -2);
  }
  const beforeFloor = cost;
  cost = Math.max(floorsAtOne ? 1 : 0, cost);
  // Only recorded when the clamp actually binds -- otherwise it's a no-op the player never needs
  // to see. Named for the rule ("minimum of one") rather than a card, since several different
  // cards' printed text can be what raised the floor.
  noteAdjustment(costAdjustments, floorsAtOne ? 'minimum of one' : 'minimum of zero', cost - beforeFloor);

  // Empower, applied LAST -- after every modifier and after the floor. "The cost for that Power is
  // zero" is an absolute override, not a reduction, so it has to beat a printed "to a minimum of
  // one" (Rainbow Hyren, Korok, Orothean Gloves) as well as any surcharge. Recorded as an
  // adjustment so the cost-breakdown tooltip explains where the discount came from.
  if (powerCostZeroed && cost !== 0) {
    noteAdjustment(costAdjustments, 'Empower', -cost);
    cost = 0;
  }

  // Confirmed with the project owner (2026-07-07): Creature/Magi Powers are paid from the
  // source's own energy; Relics have no energy pool of their own, so a Relic's Power is paid
  // from the controlling Magi's energy instead.
  // effectiveCardType (task #35, 2026-07-16: Jingjack's Spring Back/Forth) -- once a Creature is
  // toggled to a Relic mid-game, its OWN Power (Jingjack's Spring Forth is usable in either state)
  // switches to the standard Relic payment rule same as any other Relic.
  const paidBy: 'source' | 'magi' = effectiveCardType(cardDb, source) === 'Relic' ? 'magi' : 'source';
  const payer = paidBy === 'source' ? source : player.activeMagi;
  if (!payer) {
    return { legal: false, reason: 'No Magi available to pay for this Relic Power' };
  }
  const available = payer.currentEnergy ?? 0;
  const breakdown: CostBreakdown = { printed: printedCost, total: cost, adjustments: costAdjustments };
  // Affordability widened 2026-08-12 (owner playtest follow-up on the Warrior's Boots / Tony,
  // Returned pass, sibling of the same widening in `isLegalToPlay`): a card that redirects a
  // Power cost to a different payer (Dreamthread Bracelet's Loan Strength -> Magi; Sylorum's
  // Relic Affinity -> Sylorum itself) can cover a shortfall the default payer can't. Previously
  // this branch refused as "Not enough energy" up front and the redirect never fired.
  const canAfford = available >= cost || anyPowerCostRedirectorCanAfford(state, cardDb, player, source, playerId, cost);
  if (!canAfford) {
    return { legal: false, reason: `Not enough energy: need ${cost}, have ${available}`, breakdown };
  }

  return {
    legal: true,
    cost,
    paidBy,
    breakdown,
    reactedViaInstanceId,
    extraUseGrantedByInstanceId,
    ...(grantedViaBloomBonus ? { grantedViaBloomBonus: true as const } : {}),
  };
}

/** Small helper: true if ANY in-play card on the Power user's side would redirect this Power's
 *  cost via `redirectsPowerCostFrom` AND the resulting payer has enough energy. Read-only; no
 *  state mutation (see `redirectsPowerCostFrom`'s doc for why the two registered users -- Sylorum
 *  and Dreamthread Bracelet -- must stay pure now that this preview scan exists). */
function anyPowerCostRedirectorCanAfford(
  state: GameState,
  cardDb: CardDatabase,
  player: PlayerState,
  source: CardInstance,
  playerId: PlayerId,
  cost: number
): boolean {
  for (const contributor of player.inPlay) {
    for (const effect of effectsFor(state, cardDb, contributor)) {
      const altPayer = effect.redirectsPowerCostFrom?.(state, cardDb, contributor, source, playerId, cost);
      if (altPayer && (altPayer.currentEnergy ?? 0) >= cost) return true;
    }
  }
  return false;
}

/** UI preview 2026-08-12 (owner playtest follow-up): enumerates the payment options for a Power
 *  use, so the UI can offer a real "may I pay from X instead?" prompt for the
 *  `redirectsPowerCostFrom` family (Dreamthread Bracelet, Sylorum). Read-only -- the two
 *  registered hooks are pure now (Dreamthread's `onRedirectPowerCostConfirmed` companion hook
 *  carries the once-per-turn stamping, called by `usePower` on commit).
 *
 *  Returns:
 *    - `defaultPayer` -- the source card (for Creature/Magi Powers) or the Magi (for Relic
 *      Powers), whichever would pay by default.
 *    - `defaultPayerCanAfford` -- whether that default alone covers `cost`.
 *    - `redirectors` -- one entry per in-play card whose `redirectsPowerCostFrom` claims this
 *      Power AND whose returned payer has enough energy. Each entry is
 *      `{ contributor, payer }` -- `contributor` is the redirecting card (what the UI shows in
 *      the picker), `payer` is who its cost actually lands on (may or may not be the same).
 *    - `cost` -- the same figure `isLegalPowerUse` would compute for this Power.
 *
 *  UI convention: if `defaultPayerCanAfford && redirectors.length > 0`, show a picker
 *  (default payer + each redirector as a distinct button). If only one side can afford, no
 *  prompt is needed -- pass the sole affordable option as `chosenCostRedirectInstanceId` (or
 *  `null` for the default payer).
 *
 *  Returns `null` when the Power use isn't legal in the first place. */
export function previewPowerCostRedirectOffers(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  options: UsePowerOptions = {}
): { defaultPayer: CardInstance; defaultPayerCanAfford: boolean; redirectors: Array<{ contributor: CardInstance; payer: CardInstance }>; cost: number } | null {
  const legality = isLegalPowerUse(state, cardDb, playerId, sourceInstanceId, powerName, options);
  if (!legality.legal) return null;
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return null;
  const defaultPayer = legality.paidBy === 'source' ? source : player.activeMagi;
  if (!defaultPayer) return null;
  const defaultPayerCanAfford = (defaultPayer.currentEnergy ?? 0) >= legality.cost;
  const redirectors: Array<{ contributor: CardInstance; payer: CardInstance }> = [];
  for (const contributor of player.inPlay) {
    for (const effect of effectsFor(state, cardDb, contributor)) {
      const altPayer = effect.redirectsPowerCostFrom?.(state, cardDb, contributor, source, playerId, legality.cost);
      if (altPayer && (altPayer.currentEnergy ?? 0) >= legality.cost) {
        redirectors.push({ contributor, payer: altPayer });
        break;
      }
    }
  }
  return { defaultPayer, defaultPayerCanAfford, redirectors, cost: legality.cost };
}

/** Vault of Knowledge Key's `archiveUsedThisTurn` once-per-turn tag key (Bucket D Batch C part 2,
 *  2026-08-14). Exported so `effects.ts#discardFromPlay`'s intercept branch and the preview below
 *  read exactly the same tag string. Expiry via `nextOwnTurnNumber` on the Vault holding the tag. */
export const VAULT_ARCHIVE_USED_THIS_TURN = 'archiveUsedThisTurn';

/** True if Vault of Knowledge Key's Archive Effect is currently Rayje-Belt-locked on `vault`.
 *  Inlined here since `lockdown.ts`'s public API only exposes the "any-effect-locked" aggregate,
 *  and the Archive intercept must reason per-name (Vault's other Effect, Animite Infusion, may not
 *  be locked). Same pattern as `grantedEffects.ts#isEffectNameLockedDownForCard` uses privately. */
function isArchiveLockedForVault(state: GameState, vault: CardInstance): boolean {
  const tag = 'lockdown:Archive';
  for (const player of state.players.values()) {
    const holders = player.activeMagi ? [...player.inPlay, player.activeMagi] : player.inPlay;
    for (const holder of holders) {
      if (holder.durationTags.some((dt) => dt.tag === tag)) return true;
    }
  }
  return false;
}

/** UI preview for Vault of Knowledge Key's Archive (Bucket D Batch C part 2, 2026-08-14): "Once
 *  per turn, when one of your Relics discards itself from play, you may remove one energy from
 *  your Magi to discard one of your other Relics from play instead." Owner ruling 2026-08-14 Q5
 *  is Option C -- the Play.tsx UI calls this BEFORE it commits to a Power/Spell click that would
 *  self-discard its own Relic, so the answer rides through as `UsePowerOptions.archiveRedirect`
 *  / `PlayCardOptions.archiveRedirect` and is available synchronously inside
 *  `effects.ts#discardFromPlay` when the intercept fires. This preview is the sole gate on
 *  whether the picker gets shown at all.
 *
 *  Returns `null` (no picker) if ANY of these fail:
 *   - No Vault of Knowledge Key on `playerId`'s side in play (either `inPlay` or `activeMagi`;
 *     Vault is a Relic so only ever in `inPlay`, but scanned uniformly for future-proofing).
 *   - Vault's `Archive` Effect is currently Rayje-Belt-locked (owner Q9, standard).
 *   - The `invokingCard`'s registered effect does NOT declare `causesOwnRelicSelfDiscard: true`
 *     -- i.e. this action isn't one Archive can intercept.
 *   - Vault already has its once-per-turn `archiveUsedThisTurn` tag set (owner Q8: tag stamped
 *     whenever Archive intervenes, so a second attempt in the same turn is silently unavailable).
 *   - The controller's active Magi has 0 energy (can't pay the 1-energy cost).
 *   - The substitute pool is empty -- no in-play own Relics other than the invoking card itself
 *     (owner Q7 correction: Vault IS a valid substitute, only the currently-discarding Relic is
 *     excluded).
 *
 *  Returns `{ vault, substitutes }` when all gates pass. `substitutes` is the controller's own
 *  `inPlay` Relics excluding `invokingCard.instanceId` -- Vault itself IS in the pool (Q7), and a
 *  self-discard of Vault would allow OTHER own Relics as substitutes (Q10, Vault can spare
 *  itself). `powerName` is only relevant for a future per-Effect lockdown scope; currently unused
 *  in the body but part of the signature so callers can pass it symmetrically.
 *
 *  UI convention: if non-null, show a picker whose choices are `substitutes` (buttons) plus a
 *  "skip" option; thread the answer back through the option field before invoking usePower/playCard.
 *
 *  The intercept in `effects.ts#discardFromPlay` re-validates every gate above (Vault still in
 *  play, substitute still in play, Magi still has energy, tag not stamped since preview) -- if any
 *  precondition changed between preview and commit, the original discard proceeds unchanged. */
export function previewArchiveRedirectOffer(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  invokingCard: CardInstance,
  _actionKind: 'power' | 'spell',
  _powerName?: string
): { vault: CardInstance; substitutes: CardInstance[] } | null {
  const player = getPlayer(state, playerId);
  if (!player) return null;
  // Invoking card must declare the "I discard myself" flag.
  const invokingDef = cardDb.get(invokingCard.definitionKey);
  if (!invokingDef) return null;
  const invokingEffect = getCardEffectByName(invokingDef.name);
  if (!invokingEffect?.causesOwnRelicSelfDiscard) return null;
  // Find Vault of Knowledge Key on this player's side.
  const vault = player.inPlay.find((c) => cardDb.get(c.definitionKey)?.name === 'Vault of Knowledge Key');
  if (!vault) return null;
  // Rayje-lock of "Archive" silences the hook (owner Q9).
  if (isArchiveLockedForVault(state, vault)) return null;
  // Once-per-turn tag stamped (owner Q8).
  if (hasDurationTag(vault, VAULT_ARCHIVE_USED_THIS_TURN)) return null;
  // Magi must have >= 1 energy to pay the redirect cost.
  const magi = player.activeMagi;
  if (!magi || (magi.currentEnergy ?? 0) < 1) return null;
  // Substitute pool: own in-play Relics OTHER THAN the invoking Relic itself (Q7 correction --
  // Vault CAN be a substitute, only the currently-discarding Relic is out).
  const substitutes = player.inPlay.filter(
    (c) => c.instanceId !== invokingCard.instanceId && cardDb.get(c.definitionKey)?.card_type === 'Relic'
  );
  if (substitutes.length === 0) return null;
  return { vault, substitutes };
}

/** Called by the UI once a Power's target/etc. is collected, BEFORE the real usePower call --
 *  task #41, 2026-07-17, the "react-and-negate window" architecture project, Checkpoint A (Xala's
 *  Piercing Scream). Scans every OPPOSING in-play card + Magi (the source's own side can't negate
 *  its own Power) for registry.ts's offersPowerNegation, same "broadcast, self decides relevance"
 *  shape as combat.ts's previewDefenderRedirectOffers. Returns the pool of cards willing to
 *  negate -- the UI lets the defending player pick at most one (or decline), then passes the
 *  chosen instance id as UsePowerOptions.negatedByInstanceId. Widened (task #43, 2026-07-18, the
 *  Nar region pass: Bronn's Battle Staff) with an optional `currentTargetId`, passed straight
 *  through to `offersPowerNegation` -- the UI already has the resolved target in scope by the time
 *  it calls this (see finishUsePower's own comment in Play.tsx). Widened again (task #44
 *  follow-up, 2026-07-18: Climbing Staff/Gear) to also scan the opponent's HAND, not just
 *  inPlay/Magi -- Climbing Staff can discard itself "from your hand or from play," and Climbing
 *  Gear's own hand-zone clause only works while it's sitting in hand. Every `offersPowerNegation`
 *  implementer MUST gate on its own current zone if its printed text requires one (Bronn's Battle
 *  Staff was retrofitted with an explicit in-play check for exactly this reason -- see that file's
 *  own comment) -- this function no longer implicitly guarantees "candidate is in play." */
export function previewPowerNegationOffers(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  currentTargetId?: string
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return [];

  const pool: CardInstance[] = [];
  for (const opponent of getOpponents(state, playerId)) {
    const candidates: CardInstance[] = opponent.activeMagi
      ? [...opponent.inPlay, opponent.activeMagi, ...opponent.hand]
      : [...opponent.inPlay, ...opponent.hand];
    for (const candidate of candidates) {
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (effect.offersPowerNegation?.(state, cardDb, candidate, source, powerName, currentTargetId)) {
          pool.push(candidate);
          break;
        }
      }
    }
  }
  return pool;
}

/** Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09). Same "broadcast, self decides relevance"
 *  shape as `previewPowerNegationOffers` just above, EXCEPT gated FIRST on the SOURCE's own
 *  registry.ts `hitsOpposingMagi` -- if this Power won't hit the opponent's Magi at all given
 *  `options`, there is nothing to scan for; return `[]` immediately rather than asking every
 *  opposing card. Only relevant when it actually would hit. */
export function previewMagiProtectionOffers(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  options: Record<string, unknown>
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return [];
  const sourceDef = cardDb.get(source.definitionKey);
  const sourceEffect = sourceDef && !isCardEffectLockedDown(state, cardDb, source) ? getCardEffectByName(sourceDef.name) : undefined;
  if (!sourceEffect?.hitsOpposingMagi?.(state, cardDb, source, playerId, options, powerName)) return [];

  const pool: CardInstance[] = [];
  for (const opponent of getOpponents(state, playerId)) {
    const candidates: CardInstance[] = opponent.activeMagi ? [...opponent.inPlay, opponent.activeMagi] : [...opponent.inPlay];
    for (const candidate of candidates) {
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (effect.offersMagiProtection?.(state, cardDb, candidate, sourceInstanceId, sourceDef!, playerId)) {
          pool.push(candidate);
          break;
        }
      }
    }
  }
  return pool;
}

/** Refract's redirect (Nar Spell pass, Category C, 2026-07-22) -- same "broadcast, self decides
 *  relevance" shape and call site as previewPowerNegationOffers just above, scanning the DEFENDING
 *  (targeted) player's own side for registry.ts's offersTargetRedirect. `currentTargetId` is
 *  required (unlike negation's optional one) -- a redirect is meaningless without a resolved
 *  single target to actually swap. The UI picks at most one offer, then queries THAT card's own
 *  `redirectTargetPool` for the follow-up "which of your own cards instead" choice, and passes
 *  both ids through UsePowerOptions.redirectedByInstanceId/redirectChosenTargetId. */
export function previewPowerTargetRedirectOffers(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  currentTargetId: string
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return [];
  const sourceDef = cardDb.get(source.definitionKey);
  if (!sourceDef) return [];

  const pool: CardInstance[] = [];
  for (const opponent of getOpponents(state, playerId)) {
    const topLevel: CardInstance[] = opponent.activeMagi ? [...opponent.inPlay, opponent.activeMagi] : [...opponent.inPlay];
    // Refract attaches to its controller's Magi (Nar Spell pass, Category C, 2026-07-22) -- an
    // attached card lives in its holder's OWN attachedCards zone, never top-level inPlay/activeMagi
    // (same reason findAttachedSpellNegationOffers scans attachedCards separately from the plain
    // negation broadcast above).
    const candidates: CardInstance[] = [...topLevel, ...topLevel.flatMap((c) => activeAttachedCards(cardDb, c))];
    for (const candidate of candidates) {
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (effect.offersTargetRedirect?.(state, cardDb, candidate, currentTargetId, 'power', sourceDef)) {
          pool.push(candidate);
          break;
        }
      }
    }
  }
  return pool;
}

/** The follow-up "which of your own cards instead" pool once a `previewPowerTargetRedirectOffers`
 *  offer is accepted (task #591 Phase 4, 2026-07-30) -- lifted verbatim from Play.tsx's own
 *  `powerTargetRedirectPool()` so `attemptUsePower`'s `targetRedirectTarget` stage can compute it
 *  without any UI-layer code. `redirector` may be an attached card (Refract attaches to its
 *  controller's Magi), hence the `findAttachedCardById` fallback. `regionSwap` is whatever
 *  `UsePowerOptions.regionSwap` already carries at this point in the attempt -- Checkpoint B's own
 *  swap-confirmation prompt runs BEFORE `attemptUsePower` is ever called, so it is already baked
 *  into `options` by the time this stage is reached, same as the real `usePower` call itself reads
 *  it. Returns `[]` (never throws) when the redirector or its own `redirectTargetPool` hook can't be
 *  resolved -- `registry.ts`'s own doc comment calls this "the offer silently fails," not an error. */
export function redirectTargetPoolForPower(
  state: GameState,
  cardDb: CardDatabase,
  redirectorInstanceId: string,
  actingPlayerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  regionSwap: { fromRegion: string; toRegion: string } | undefined
): CardInstance[] {
  const redirector = findCreatureOrMagiById(state, redirectorInstanceId) ?? findAttachedCardById(state, redirectorInstanceId);
  const def = redirector && cardDb.get(redirector.definitionKey);
  if (!redirector || !def) return [];
  const sourceCard = findCreatureOrMagiById(state, sourceInstanceId);
  const sourceDef = sourceCard && cardDb.get(sourceCard.definitionKey);
  const ability: RedirectSourceAbility | undefined = sourceDef ? { kind: 'power', def: sourceDef, actingPlayerId, sourceInstanceId, powerName } : undefined;
  return withRegionSwap(state, regionSwap, () => getCardEffectByName(def.name)?.redirectTargetPool?.(state, cardDb, redirector, ability) ?? []);
}

/** Fird Stone's Fird Favor (Naroom Spell-interaction audit, Category C, 2026-07-23) -- same
 *  "broadcast, self decides relevance" shape and DEFENDING-side scan as
 *  `previewPowerTargetRedirectOffers` just above, for registry.ts's `offersFurokProtection`.
 *  `currentTargetId` is required, same "meaningless without a resolved single target" reasoning as
 *  the redirect preview -- Fird Stone only ever reacts to a Power whose CHOSEN target is one of its
 *  controller's own Furoks (see that hook's own doc comment for the accepted narrower scope: a
 *  board-wide/multi-target Power that merely happens to include a Furok isn't covered). The UI
 *  picks at most one offer (or declines), then passes the chosen instance id through
 *  `UsePowerOptions.firdStoneProtectedByInstanceId`. */
/**
 * Live pool for an `opponentHandDiscardChoice`/`chooseFromOpponentHand` Power (registry.ts, PvP
 * Step 3.5 item 4, 2026-08-02) -- both are "pick 0..maxCount from the TARGET's hand" declarations
 * that can only resolve once the Power's OWN target (`options.chosenTargetId`) is already known,
 * same ordering `queries.ts`'s `describeMoveChoices` already established for these two hooks.
 * Returns `undefined` if the source declares neither hook, its target hasn't been chosen yet, the
 * corresponding `UsePowerOptions` field is already supplied (nothing to pause for), or the pool
 * would be empty (same "return undefined when there's nothing to offer" convention every other
 * pending-choice discovery function in this codebase already follows -- see this file's own
 * `previewPowerNegationOffers` and friends). `reactiveOffers.ts`'s `attemptUsePower` is the only
 * caller; it turns a defined result into a `state.pendingOpponentHandChoice` pause. */
export function previewOpponentHandPickOffer(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  options: UsePowerOptions
): { kind: 'opponentHandDiscardChoice' | 'chooseFromOpponentHand'; pool: CardInstance[]; maxCount: number; owedToPlayerId: PlayerId; handOwnerPlayerId: PlayerId } | undefined {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return undefined;
  const sourceDef = cardDb.get(source.definitionKey);
  const effect = sourceDef && getCardEffectByName(sourceDef.name);
  if (!effect) return undefined;

  const targetOwner = (): PlayerState | undefined => {
    if (!options.chosenTargetId) return undefined;
    const target = findCreatureOrMagiById(state, options.chosenTargetId);
    return target ? state.players.get(target.controllerId) : undefined;
  };

  if (effect.opponentHandDiscardChoice && options.chosenOpponentHandCardIds === undefined) {
    const owner = targetOwner();
    if (!owner) return undefined;
    const decl = effect.opponentHandDiscardChoice;
    const pool = withRegionSwap(state, options.regionSwap, () => owner.hand.filter((c) => !decl.filter || decl.filter(state, cardDb, playerId, c)));
    if (pool.length === 0) return undefined;
    return { kind: 'opponentHandDiscardChoice', pool, maxCount: decl.maxCount, owedToPlayerId: owner.playerId, handOwnerPlayerId: owner.playerId };
  }
  if (effect.chooseFromOpponentHand && options.chosenFromOpponentHandIds === undefined) {
    const decl = effect.chooseFromOpponentHand;
    // noPriorTarget (Task C, 2026-08-02, Hand of the Sky) -- this Power has no powerTargets step of
    // its own, so there is no options.chosenTargetId to derive the hand owner from; the hand owner
    // IS the single opponent (2-player-only simplification, same as this declaration's own doc
    // comment). Every other user of chooseFromOpponentHand (Epik, Heat Lens) keeps the original
    // targetOwner()-derived lookup.
    const owner = decl.noPriorTarget ? getOpponents(state, playerId)[0] : targetOwner();
    if (!owner) return undefined;
    const pool = withRegionSwap(state, options.regionSwap, () => owner.hand.filter((c) => !decl.filter || decl.filter(state, cardDb, playerId, c)));
    if (pool.length === 0) return undefined;
    return { kind: 'chooseFromOpponentHand', pool, maxCount: decl.maxCount, owedToPlayerId: playerId, handOwnerPlayerId: owner.playerId };
  }
  return undefined;
}

/**
 * "Group B" fix (bug fix 2026-08-09, Raxis's Shatterfire and 5 siblings) -- live pool/legality for
 * a `booleanChoice` or `powerTargetSlots` slot declared `respondingPlayer: 'opponent'`: a
 * sub-decision the printed card assigns to the player being acted upon, not the Power's user.
 * Returns `undefined` if the source declares no such choice, the choice is already answered, or
 * (slot case only) the first unanswered slot isn't opponent-owned at all -- same "return undefined
 * when there's nothing to offer" convention `previewOpponentHandPickOffer` just above already
 * follows. `reactiveOffers.ts`'s `attemptUsePower` is the only caller; it turns a defined result
 * into a `state.pendingOpponentSubChoice` pause.
 *
 * `owedToPlayerId` resolution: for Raxis/Frost Raxis, whose own target pool is unrestricted "any
 * Relic in play" (can include the acting player's own), this reads the ALREADY-CHOSEN target's own
 * `controllerId` -- correct even in the rare self-target case. Every other card's target pool is
 * opponent-only by construction (`opposingCreatures`/`opposingMagi`), so "the target's controller"
 * and "the one opponent" always agree for them; reading the target's controllerId when one is
 * available covers both groups with one code path, falling back to "the one opponent" only for the
 * Rockslide Hyren case, whose printed text ("AN OPPONENT of your choice") has no single target to
 * derive a controller from at all.
 */
export function previewOpponentSubChoiceOffer(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  options: UsePowerOptions
):
  | { kind: 'boolean'; legalValues: boolean[]; owedToPlayerId: PlayerId }
  | { kind: 'slot'; slotIndex: number; pool: readonly CardInstance[]; min: number; max: number; owedToPlayerId: PlayerId }
  | undefined {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return undefined;
  const sourceDef = cardDb.get(source.definitionKey);
  const effect = sourceDef && !isCardEffectLockedDown(state, cardDb, source) ? getCardEffectByName(sourceDef.name) : undefined;
  if (!effect) return undefined;

  const owedToPlayerId = (): PlayerId | undefined => {
    if (options.chosenTargetId) {
      const target = findCreatureOrMagiById(state, options.chosenTargetId);
      if (target) return target.controllerId;
    }
    return getOpponents(state, playerId)[0]?.playerId;
  };

  if (effect.booleanChoice?.respondingPlayer === 'opponent' && options.chosenBoolean === undefined) {
    const owedTo = owedToPlayerId();
    if (!owedTo) return undefined;
    const decl = effect.booleanChoice;
    const legalValues: boolean[] = [true, false];
    if (decl.yesUnavailableReason?.(state, cardDb, playerId, options.chosenTargetId) !== undefined) {
      legalValues.splice(legalValues.indexOf(true), 1);
    }
    return { kind: 'boolean', legalValues, owedToPlayerId: owedTo };
  }

  if (effect.powerTargetSlots) {
    const slots = effect.powerTargetSlots(state, cardDb, playerId, powerName, sourceInstanceId);
    const answered = options.chosenSlotIds ?? [];
    if (answered.length < slots.length) {
      const index = answered.length;
      const slot = slots[index]!;
      if (slot.respondingPlayer === 'opponent') {
        const owedTo = owedToPlayerId();
        if (!owedTo) return undefined;
        const pool = slotPoolWithRegionSwap(state, slot, cardDb, playerId, answered, sourceInstanceId, options.regionSwap);
        const min = resolveSlotBound(slot.min, answered);
        const max = resolveSlotBound(slot.max, answered);
        // Defensive only -- unreachable in every real registrant today (Rockslide Hyren's own
        // opponent-owned slots are gated on the EARLIER slot's min:3/max:3, so priorChoices[0]
        // always has exactly 3 entries by the time either of these is checked). If some future
        // card's dependent bound ever legitimately resolves to 0 here, returning undefined leaves
        // that slot's chosenSlotIds entry unset, which resolvePower's own defensive `?.[N]` reads
        // already treat as "no answer, no-op" -- the same safe fallback every other absent-choice
        // field in this codebase already has, not a new gap.
        if (max === 0) return undefined;
        return { kind: 'slot', slotIndex: index, pool, min, max, owedToPlayerId: owedTo };
      }
    }
  }

  return undefined;
}

export function previewFurokProtectionOffers(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  currentTargetId: string
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return [];
  const sourceDef = cardDb.get(source.definitionKey);
  if (!sourceDef) return [];

  const pool: CardInstance[] = [];
  for (const opponent of getOpponents(state, playerId)) {
    const candidates: CardInstance[] = opponent.activeMagi ? [...opponent.inPlay, opponent.activeMagi] : [...opponent.inPlay];
    for (const candidate of candidates) {
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (effect.offersFurokProtection?.(state, cardDb, candidate, currentTargetId, 'power', sourceDef)) {
          pool.push(candidate);
          break;
        }
      }
    }
  }
  return pool;
}

/** Checkpoint B's own preview (Spell-pass audit follow-up, 2026-07-23: Abwyn's Quill/Niffer/
 *  Obgren) -- returns [] immediately if `sourceDef` never registered `specifiedTargetRegions`
 *  (not on the ~34-file swap-support list, same "absence means not swappable" convention
 *  `regionForTargetFilter`'s own doc comment describes). Otherwise broadcasts over BOTH players'
 *  boards (unlike `previewPowerNegationOffers`/`previewPowerTargetRedirectOffers`, which only ever
 *  scan the opposing side) -- Abwyn's Quill's own text is "as A PLAYER plays...", unrestricted to
 *  either side; Niffer/Obgren narrow themselves to their own controller inside their own hook
 *  bodies. Called by the UI BEFORE the target-picker opens, i.e. before `powerTargets` is even
 *  queried for display -- the swap, once confirmed, changes what THAT query returns. */
export function previewRegionSwapOffersForPower(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return [];
  const sourceDef = cardDb.get(source.definitionKey);
  if (!sourceDef) return [];
  if (hasImmutableText(sourceDef.name)) return [];
  const specifiedRegions = getCardEffectByName(sourceDef.name)?.specifiedTargetRegions?.(state, cardDb, playerId, sourceInstanceId);
  if (!specifiedRegions || specifiedRegions.length === 0) return [];

  const pool: CardInstance[] = [];
  for (const p of state.players.values()) {
    const candidates: CardInstance[] = p.activeMagi ? [...p.inPlay, p.activeMagi] : [...p.inPlay];
    for (const candidate of candidates) {
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (effect.offersRegionSwapBeforeChoices?.(state, cardDb, candidate, playerId, 'power', sourceDef, sourceInstanceId, specifiedRegions)) {
          pool.push(candidate);
          break;
        }
      }
    }
  }
  return pool;
}

/** Applies a confirmed Checkpoint B swap (Spell-pass audit follow-up, 2026-07-23) -- calls the
 *  swapper's own `resolveRegionSwap` (its cost/consequence, e.g. Abwyn's Quill discarding 2
 *  energy from its controller's Magi) and logs the swap. Called ONCE by the UI, immediately after
 *  the player confirms both "yes, swap" and the new region, BEFORE the target-picker is shown --
 *  the picker's own pool computation (`powerTargetsWithRegionSwap`, just below) and the eventual
 *  real `usePower` call (via `UsePowerOptions.regionSwap`) both need the SAME `{fromRegion,
 *  toRegion}` pair the UI keeps in its own local state for the rest of this flow; this function
 *  does not itself set `state.activeRegionSwap` -- see that field's own hygiene-rule doc comment
 *  for why it's scoped to individual calls instead. */
export function confirmRegionSwapForPower(
  state: GameState,
  cardDb: CardDatabase,
  swapperInstanceId: string,
  fromRegion: string,
  toRegion: string
): void {
  const swapper = findCreatureOrMagiById(state, swapperInstanceId);
  if (!swapper) return;
  const swapperDef = cardDb.get(swapper.definitionKey);
  const swapperEffect = swapperDef && getCardEffectByName(swapperDef.name);
  logEvent(state, 'regionSwapConfirmed', { swapperInstanceId, fromRegion, toRegion });
  swapperEffect?.resolveRegionSwap?.(state, cardDb, swapper, fromRegion, toRegion);
}

/** Swirling Orshaa's Morph (Spell-pass audit follow-up, 2026-07-24) -- Power-side sibling of
 *  `previewRegionSwapOffersForPower`, same broadcast shape and same "absence means not swappable"
 *  guard on `specifiedTargetRegions`, but checking `offersIdentityOverrideBeforeChoices` instead
 *  of `offersRegionSwapBeforeChoices`. */
export function previewIdentityOverrideOffersForPower(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return [];
  const sourceDef = cardDb.get(source.definitionKey);
  if (!sourceDef) return [];
  const sourceEffect = getCardEffectByName(sourceDef.name);
  const specifiedRegions = sourceEffect?.specifiedTargetRegions?.(state, cardDb, playerId, sourceInstanceId) ?? [];
  const specifiedCreatureTypes = sourceEffect?.specifiedCreatureTypes?.(state, cardDb, playerId, sourceInstanceId) ?? [];
  if (specifiedRegions.length === 0 && specifiedCreatureTypes.length === 0) return [];

  const pool: CardInstance[] = [];
  for (const p of state.players.values()) {
    const candidates: CardInstance[] = p.activeMagi ? [...p.inPlay, p.activeMagi] : [...p.inPlay];
    for (const candidate of candidates) {
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (
          effect.offersIdentityOverrideBeforeChoices?.(
            state,
            cardDb,
            candidate,
            playerId,
            'power',
            sourceDef,
            sourceInstanceId,
            specifiedRegions,
            specifiedCreatureTypes
          )
        ) {
          pool.push(candidate);
          break;
        }
      }
    }
  }
  return pool;
}

/** Applies a confirmed Swirling Orshaa-style identity override -- calls the reactor's own
 *  `resolveIdentityOverride`, which sets `self.identityOverride` directly (unlike
 *  `confirmRegionSwapForPower`, no separate `state.activeRegionSwap` plumbing is needed since the
 *  consequence lives entirely on the reactor's own instance). */
export function confirmIdentityOverrideForPower(
  state: GameState,
  cardDb: CardDatabase,
  reactorInstanceId: string,
  kind: 'region' | 'creatureType',
  value: string
): void {
  const reactor = findCreatureOrMagiById(state, reactorInstanceId);
  if (!reactor) return;
  const reactorDef = cardDb.get(reactor.definitionKey);
  const reactorEffect = reactorDef && getCardEffectByName(reactorDef.name);
  logEvent(state, 'identityOverrideConfirmed', { reactorInstanceId, kind, value });
  reactorEffect?.resolveIdentityOverride?.(state, cardDb, reactor, kind, value, state.turnNumber);
}

/**
 * Swirling Orshaa's Morph, Effect-half (2026-07-24) -- previews whether the ABOUT-TO-BE-CHOSEN
 * target of a Power should get a reactive Morph offer before the real `usePower` call runs
 * (Ulk Prodigy's Resistance: "Korrits you control may not be chosen by opposing Powers"). Unlike
 * every other identity-override preview in this codebase, the reactor here is fixed -- only the
 * TARGET itself becoming the referenced type can save it (`preventsBeingChosenForPowerBy` checks
 * the target's own type, not some other card's), so there's no broadcast pool to build; this either
 * returns the target itself (if eligible) or `undefined`. `chosenTargetId` is the target the acting
 * player is about to submit, BEFORE `isLegalPowerUse` has run its own (unreactive) check on it.
 */
export function previewIdentityOverrideOfferForPowerTargetProtection(
  state: GameState,
  cardDb: CardDatabase,
  chosenTargetId: string
): { target: CardInstance; specifiedCreatureTypes: string[] } | undefined {
  const target = findCreatureOrMagiById(state, chosenTargetId);
  if (!target) return undefined;
  const targetDef = cardDb.get(target.definitionKey);
  const targetEffects = effectsFor(state, cardDb, target);
  const targetOfferHooks = targetEffects
    .map((e) => e.offersIdentityOverrideBeforeChoices)
    .filter((h): h is NonNullable<typeof h> => h !== undefined);
  if (targetOfferHooks.length === 0) return undefined;

  const targetOwner = getPlayer(state, target.controllerId);
  const contributors: CardInstance[] = targetOwner.activeMagi ? [targetOwner.activeMagi, ...targetOwner.inPlay] : [...targetOwner.inPlay];
  const candidateTypes = new Set<string>();
  for (const contributor of contributors) {
    for (const effect of effectsFor(state, cardDb, contributor)) {
      const types = effect.preventsBeingChosenForPowerByCreatureTypes?.(state, cardDb, target.controllerId, contributor.instanceId) ?? [];
      for (const t of types) candidateTypes.add(t);
    }
  }
  // Only offer types the target doesn't already effectively have -- no point re-offering a type
  // that would change nothing about its current protection.
  const eligibleTypes = [...candidateTypes].filter((t) => effectiveCreatureType(cardDb, target) !== t);
  if (eligibleTypes.length === 0) return undefined;

  const offered = eligibleTypes.filter((t) =>
    targetOfferHooks.some((hook) =>
      hook(state, cardDb, target, target.controllerId, 'power', targetDef!, target.instanceId, [], [t])
    )
  );
  if (offered.length === 0) return undefined;
  return { target, specifiedCreatureTypes: offered };
}

/** Computes a Power's `powerTargets` pool with a region swap TENTATIVELY applied, for the UI's
 *  picker display -- Spell-pass audit follow-up, 2026-07-23. Sets `state.activeRegionSwap`,
 *  queries the pool, then restores the previous value before returning, all within this one
 *  synchronous call (same "set/restore, never leak past one call" hygiene rule
 *  `GameState.activeRegionSwap`'s own doc comment requires). Pass `swap: undefined` to just read
 *  the normal (unswapped) pool through this same call site. */
export function powerTargetsWithRegionSwap(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  swap: { fromRegion: string; toRegion: string } | undefined
): CardInstance[] | undefined {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return undefined;
  // dispatchDef (not the source's own def) so a COPIED Power (copiedPowers.ts, e.g. Ergar's Spark
  // granted to another Cald Creature) resolves against the ORIGINAL card's registry entry, same as
  // handleUsePower's own `effect` lookup just above this call site -- a bug fix, 2026-07-23: this
  // previously used the source's own def unconditionally, so a granted Power's target pool was
  // computed from the RECEIVING card's own (unrelated) powerTargets function instead of the
  // granting card's, live-playtest-reported as Raxis's copied Spark returning an empty/wrong pool.
  const { dispatchDef } = findPower(state, cardDb, source, powerName);
  if (!dispatchDef) return undefined;
  const previous = state.activeRegionSwap;
  state.activeRegionSwap = swap ?? null;
  try {
    return getCardEffectByName(dispatchDef.name)?.powerTargets?.(state, cardDb, playerId, powerName, sourceInstanceId);
  } finally {
    state.activeRegionSwap = previous;
  }
}

/** Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- same set/restore contract as
 *  `powerTargetsWithRegionSwap` above, but for `handDiscardCost`'s hand-filter pool instead of a
 *  target pool (e.g. Firefly Amulet/Shock Vashp's region-gated hand-discard cost). Play.tsx calls
 *  this instead of building the pool inline with a raw `game!` so a confirmed swap (Abwyn's
 *  Quill/Niffer/Obgren) is visible in the filter without this file ever mutating
 *  `game.activeRegionSwap` itself. */
export function handDiscardCostWithRegionSwap(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  swap: { fromRegion: string; toRegion: string } | undefined
): { count: number | 'X' | 'any'; pool: CardInstance[] } | undefined {
  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId);
  if (!source) return undefined;
  // dispatchDef, not the source's own def -- same copied-Power bug fix as powerTargetsWithRegionSwap
  // above (2026-07-23).
  const { dispatchDef } = findPower(state, cardDb, source, powerName);
  if (!dispatchDef) return undefined;
  const effect = getCardEffectByName(dispatchDef.name);
  const resolved = effect?.handDiscardCost ? resolvePerPowerField(effect.handDiscardCost, powerName) : undefined;
  if (!resolved) return undefined;
  const previous = state.activeRegionSwap;
  state.activeRegionSwap = swap ?? null;
  try {
    return {
      count: resolved.count,
      pool: player.hand.filter((c) => !resolved.filter || resolved.filter(state, cardDb, playerId, c)),
    };
  } finally {
    state.activeRegionSwap = previous;
  }
}

/** Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- same set/restore contract as
 *  `powerTargetsWithRegionSwap`/`handDiscardCostWithRegionSwap` above, but for a single
 *  `powerTargetSlots` slot's live-recomputed pool (e.g. Blygt/Muck Shovel/Muggum's region-gated
 *  slots). Unlike those two, the caller already has the resolved `PowerTargetSlot` object in hand
 *  (Play.tsx's `slotPool()` is called with one already fetched from `effect.powerTargetSlots(...)`),
 *  so this only needs to wrap the ONE `slot.pool(...)` call in the same set/restore, not re-derive
 *  the slot from the card's registry entry. */
export function slotPoolWithRegionSwap(
  state: GameState,
  slot: PowerTargetSlot,
  cardDb: CardDatabase,
  playerId: PlayerId,
  priorChoices: readonly string[][],
  sourceInstanceId: string,
  swap: { fromRegion: string; toRegion: string } | undefined
): CardInstance[] {
  const previous = state.activeRegionSwap;
  state.activeRegionSwap = swap ?? null;
  try {
    return slot.pool(state, cardDb, playerId, priorChoices, sourceInstanceId);
  } finally {
    state.activeRegionSwap = previous;
  }
}

export function usePower(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  sourceInstanceId: string,
  powerName: string,
  hooks: PowerEffectHooks = {},
  options: UsePowerOptions = {},
  rng: Rng = defaultRng
): void {
  // Checkpoint B (Spell-pass audit follow-up, 2026-07-23) -- set for the WHOLE call, not just
  // around resolveEffect, since a re-validation of `chosenTargetId` against `powerTargets` can
  // happen before resolveEffect too. Restored at the very end, same plain "set near entry, restore
  // at exit" convention this function's own `currentAction` handling already uses (not a
  // try/finally -- an early throw leaving this stale is the same already-accepted tradeoff
  // `currentAction` has).
  const previousActiveRegionSwap = state.activeRegionSwap;
  state.activeRegionSwap = options.regionSwap ?? null;

  // PvP Step 3.5 item 2 (2026-08-02) -- see play.ts's `playCard`, identical rationale/shape.
  if (options.regionSwap?.swapperInstanceId) {
    confirmRegionSwapForPower(state, cardDb, options.regionSwap.swapperInstanceId, options.regionSwap.fromRegion, options.regionSwap.toRegion);
  }
  if (options.identityOverride) {
    const { reactorInstanceId, kind, value } = options.identityOverride;
    const reactor = findCreatureOrMagiById(state, reactorInstanceId);
    const alreadyApplied = reactor?.identityOverride?.kind === kind && reactor?.identityOverride?.value === value;
    if (!alreadyApplied) confirmIdentityOverrideForPower(state, cardDb, reactorInstanceId, kind, value);
  }

  const legality = isLegalPowerUse(state, cardDb, playerId, sourceInstanceId, powerName, options);
  if (!legality.legal) {
    throw new Error(`Illegal Power use: ${legality.reason}`);
  }

  const player = getPlayer(state, playerId);
  const source = findSource(player, sourceInstanceId)!;

  // Confirm exactly once, here, at the real moment of action -- NOT inside isLegalPowerUse's own
  // check above, which queries.ts's getLegalMoves also calls speculatively (via Play.tsx's render
  // loop) to build the "what's clickable" list. reactsToWindow/grantsExtraPowerUse are pure reads;
  // the once-per-turn bookkeeping they used to perform inline lives here instead, so a mere
  // legality probe can never silently consume a one-time grant before the player acts on it.
  if (legality.reactedViaInstanceId) {
    const reactedCard = findSource(player, legality.reactedViaInstanceId);
    const reactedDef = reactedCard && cardDb.get(reactedCard.definitionKey);
    const reactedEffect = reactedDef && getCardEffectByName(reactedDef.name);
    reactedEffect?.confirmReactionToWindow?.(state, cardDb, state.reactiveWindow!, playerId, reactedCard!);
  }
  // Empower is a one-time grant and belongs in exactly this block for exactly the reason above:
  // consumed at the real moment of action, never during a legality probe. Read BEFORE removal so
  // the resolution context below can force X to zero.
  const wasPowerCostZeroed = hasDurationTag(source, POWER_COST_ZEROED);
  if (wasPowerCostZeroed) removeDurationTag(source, POWER_COST_ZEROED);
  if (legality.extraUseGrantedByInstanceId) {
    const grantorCard = findCreatureOrMagiById(state, legality.extraUseGrantedByInstanceId);
    const grantorDef = grantorCard && cardDb.get(grantorCard.definitionKey);
    const grantorEffect = grantorDef && getCardEffectByName(grantorDef.name);
    grantorEffect?.confirmExtraPowerUse?.(state, cardDb, source, powerName, grantorCard!);
    // Generic record of "an extra use of THIS Power on THIS card was granted this turn", stamped
    // once here rather than left to each grantor's own bookkeeping. `usedPowerNames` is a plain
    // "used at all this turn" mark with no count, so without this there is no way to ask "has this
    // Power already been used more than once?" -- which is exactly what Rala Tail's errata turns on.
    // See extraPowerUseGrantedTag's doc comment in durationTags.ts.
    addDurationTagRaw(source, extraPowerUseGrantedTag(powerName), state.turnNumber);
  }
  if (legality.grantedViaBloomBonus) {
    player.bloomBonusActionPending = false;
  }

  // Steps 1-2: announce and pay cost simultaneously.
  let payer = legality.paidBy === 'source' ? source : player.activeMagi!;
  // registry.ts's redirectsPowerCostFrom (task #29, 2026-07-15: Dreamthread Bracelet's Loan
  // Strength; Sylorum's Relic Affinity) -- broadcast to the Power user's own in-play cards;
  // whichever one the caller chose (via `options.chosenCostRedirectInstanceId`, collected up
  // front via `previewPowerCostRedirectOffers`) pays instead of the default.
  //
  // Choice model 2026-08-12 (owner playtest follow-up): the printed "may" is now a real UI
  // prompt. Three semantics on `chosenCostRedirectInstanceId`, exact mirror of the play-cost
  // side in `play.ts#playCard`:
  //   * `null`      -- player explicitly chose the default payer; no redirect fires.
  //   * an id       -- pay from that in-play card's returned payer.
  //   * `undefined` -- legacy auto-apply: first willing/able contributor wins.
  //
  // The confirming card's `onRedirectPowerCostConfirmed` hook fires once, after the payment
  // resolves -- used by Dreamthread Bracelet to stamp its once-per-turn tag. That mutation used
  // to live inside `redirectsPowerCostFrom` itself, which was incompatible with a preview scan
  // (the preview would stamp the tag on every hover). See dreamthreadBracelet.ts's header.
  let redirectingContributor: CardInstance | undefined;
  if (options.chosenCostRedirectInstanceId !== undefined) {
    const chosen = options.chosenCostRedirectInstanceId;
    if (chosen !== null) {
      const contributor = player.inPlay.find((c) => c.instanceId === chosen);
      if (contributor) {
        for (const effect of effectsFor(state, cardDb, contributor)) {
          const altPayer = effect.redirectsPowerCostFrom?.(state, cardDb, contributor, source, playerId, legality.cost);
          if (altPayer) {
            payer = altPayer;
            redirectingContributor = contributor;
            break;
          }
        }
      }
    }
  } else {
    // Legacy auto-apply path -- keep byte-for-byte identical to pre-2026-08-12 behaviour so
    // callers that never set the field see no change.
    for (const contributor of player.inPlay) {
      let altPayer: CardInstance | undefined;
      for (const effect of effectsFor(state, cardDb, contributor)) {
        altPayer = effect.redirectsPowerCostFrom?.(state, cardDb, contributor, source, playerId, legality.cost);
        if (altPayer) break;
      }
      if (altPayer) {
        payer = altPayer;
        redirectingContributor = contributor;
        break;
      }
    }
  }
  payer.currentEnergy = Math.max(0, (payer.currentEnergy ?? 0) - legality.cost);
  // Fire the confirmation hook exactly once for the actually-committed redirect (see the block
  // above for why this can't live inside `redirectsPowerCostFrom` any more).
  if (redirectingContributor) {
    for (const effect of effectsFor(state, cardDb, redirectingContributor)) {
      effect.onRedirectPowerCostConfirmed?.(state, cardDb, redirectingContributor, source, playerId);
    }
  }
  source.usedPowerNames.set(powerName, state.turnNumber); // "once per turn, full stop" -- marked even if it ends up fizzling
  // Vault of Knowledge Key's Animite Infusion (Bucket D Batch C part 1, 2026-08-14): parallel
  // per-name counter for the "used a Power more than once this turn" end-of-turn discard sweep.
  // Increments even on fizzled uses, same convention as `usedPowerNames` above (owner Q4).
  source.usedPowerCounts.set(powerName, (source.usedPowerCounts.get(powerName) ?? 0) + 1);
  // Task #38 follow-up (2026-07-17): thread the grant attribution through to the log, so a
  // reactive/extra Power use shows WHY it was allowed rather than just that it happened. Found
  // missing during a live playtest -- the project owner couldn't tell from the log alone that
  // Yricho was what let a Power fire mid-opponent's-turn.
  // Choice-visibility pass (2026-08-09): captured so the choices this Power use actually made
  // (chosenCategory, a target, etc.) can be BACKFILLED into this same entry's `detail` once they're
  // known -- see the backfill right before resolveEffect?.(ctx) below. `detail`'s readonly modifier
  // only locks the property, not the object it points to, so mutating it in place later is legal
  // and keeps this at one log line per Power use instead of two.
  const powerUsedEvent = logEvent(state, 'powerUsed', {
    playerId,
    sourceInstanceId: source.instanceId,
    powerName,
    cost: legality.cost,
    paidBy: legality.paidBy,
    ...(legality.reactedViaInstanceId ? { reactedViaInstanceId: legality.reactedViaInstanceId } : {}),
    ...(legality.extraUseGrantedByInstanceId
      ? { extraUseGrantedByInstanceId: legality.extraUseGrantedByInstanceId }
      : {}),
    ...(legality.grantedViaBloomBonus ? { grantedViaBloomBonus: true } : {}),
  });

  // Step 3: Creature-defeat check from the cost payment specifically. Magi-defeat is NOT
  // checked yet, even if the payer (Magi or source Creature) just hit 0 -- deferred to step 7.
  checkCreatureDefeats(state, cardDb, 'power', undefined, rng);

  // Steps 4-5: choices/targets and results (see PowerEffectHooks doc comment).
  const ctx: PowerContext = {
    state,
    cardDb,
    source,
    controllingPlayer: player,
    powerName,
    // "If there is an X in the cost, X equals zero" -- the effect sees 0, not whatever the caller
    // passed, so an Empowered X-Power cannot buy a large X for free (POWER_COST_ZEROED's doc).
    chosenXValue: wasPowerCostZeroed ? 0 : options.chosenXValue,
    chosenTargetId: options.chosenTargetId,
    chosenHandCardIds: options.chosenHandCardIds,
    chosenSlotIds: options.chosenSlotIds,
    chosenBoolean: options.chosenBoolean,
    chosenOpponentHandCardIds: options.chosenOpponentHandCardIds,
    chosenFromOpponentHandIds: options.chosenFromOpponentHandIds,
    chosenDeckSearchIds: options.chosenDeckSearchIds,
    chosenDiscardPileIds: options.chosenDiscardPileIds,
    chosenDeckTopIds: options.chosenDeckTopIds,
    chosenHandRevealIds: options.chosenHandRevealIds,
    chosenAmounts: options.chosenAmounts, // task #532
    chosenHandPlayId: options.chosenHandPlayId,
    chosenCategory: options.chosenCategory,
    chosenDreamwarpAdjustment: options.chosenDreamwarpAdjustment, // task #577
    nestedSpellChoices: options.nestedSpellChoices,
    rng,
  };
  // dispatchDef (not source's own def) so a copied Power runs the ORIGINAL card's resolvePower --
  // ctx.source is still THIS card (the copier), so any "discard this card from play" style text
  // in the original's logic already discards the copier, matching "copied Powers... now reference
  // [the copier]" with no special-casing (see copiedPowers.ts's header comment).
  const { dispatchDef } = findPower(state, cardDb, source, powerName);
  const resolveEffect = hooks.resolveEffect ?? (dispatchDef ? getCardEffectByName(dispatchDef.name)?.resolvePower : undefined);

  // Cliff Hyren's Shield / Vogo's Interrupt (task #42, 2026-07-17, Kybar's Teeth region pass) --
  // registry.ts's offersPowerTargetRedirect/resolvePowerTargetRedirect, checked right after
  // dispatchDef is known (needed to re-validate the redirect target against the Power's own
  // powerTargets pool, matching Cliff Hyren's own "if Cliff Hyren can be affected by the Spell or
  // Power" printed qualifier) but BEFORE resolveEffect (or the negation check below) ever reads
  // ctx.chosenTargetId. Broadcast over the CURRENT target's own controller's board only -- first
  // offering card wins. A Power with no powerTargets pool at all (no legality restriction defined)
  // is treated as accepting any target, same permissive default the rest of this codebase uses.
  if (ctx.chosenTargetId) {
    const currentTarget = findCreatureOrMagiById(state, ctx.chosenTargetId);
    if (currentTarget) {
      const targetOwner = getPlayer(state, currentTarget.controllerId);
      const contributors: CardInstance[] = targetOwner.activeMagi ? [targetOwner.activeMagi, ...targetOwner.inPlay] : [...targetOwner.inPlay];
      let handled = false;
      for (const contributor of contributors) {
        if (handled) break;
        for (const effect of effectsFor(state, cardDb, contributor)) {
          if (!effect.offersPowerTargetRedirect?.(state, cardDb, contributor, source, powerName, currentTarget.instanceId)) continue;
          const newTargetId = effect.resolvePowerTargetRedirect?.(state, cardDb, contributor, currentTarget.instanceId);
          if (newTargetId) {
            const legalPool = dispatchDef && getCardEffectByName(dispatchDef.name)?.powerTargets?.(state, cardDb, playerId, powerName, source.instanceId);
            if (!legalPool || legalPool.some((c) => c.instanceId === newTargetId)) {
              logEvent(state, 'powerTargetRedirected', {
                fromInstanceId: currentTarget.instanceId,
                toInstanceId: newTargetId,
                byInstanceId: contributor.instanceId,
              });
              ctx.chosenTargetId = newTargetId;
            }
          }
          handled = true;
          break;
        }
      }
    }
  }

  // registry.ts's chargesActingMagiForChoosing (task #43, 2026-07-18, the Nar region pass:
  // Laranel's Cold Shoulder) -- checked right after any redirect above, using whatever
  // ctx.chosenTargetId ends up being. Broadcast over the FINAL target's own controller's board,
  // first claimant wins; the hook body applies its own consequence (discardEnergy on the ACTING
  // player's own Magi) and reports back.
  if (ctx.chosenTargetId) {
    const finalTarget = findCreatureOrMagiById(state, ctx.chosenTargetId);
    if (finalTarget) {
      const targetOwner = getPlayer(state, finalTarget.controllerId);
      const contributors: CardInstance[] = targetOwner.activeMagi ? [targetOwner.activeMagi, ...targetOwner.inPlay] : [...targetOwner.inPlay];
      let charged = false;
      for (const contributor of contributors) {
        if (charged) break;
        for (const effect of effectsFor(state, cardDb, contributor)) {
          if (effect.chargesActingMagiForChoosing?.(state, cardDb, finalTarget, playerId, contributor)) {
            charged = true;
            break;
          }
        }
      }
    }
  }

  // Hubdra's Chest's Lock Box / Pearl Hyren's Hoard (Orothe Spell pass, Category C, 2026-07-24) --
  // registry.ts's onOwnRelicChosenAsTargetByOpponent, fired once ctx.chosenTargetId is fully
  // finalized (post-redirect) but before resolveEffect runs -- a no-op unless it actually names a
  // Relic controlled by someone other than this acting player.
  if (ctx.chosenTargetId) {
    const chosenCard = findCreatureOrMagiById(state, ctx.chosenTargetId);
    if (chosenCard) broadcastOwnRelicChosenAsTargetByOpponent(state, cardDb, chosenCard, playerId);
  }

  // registry.ts's onOwnPowerDiscardedOpposingEnergy (Amanax's Pyromaniac) -- snapshot every
  // opposing Creature's energy before this Power resolves, so the diff after can tell whoever's
  // listening how much of it this ONE Power's own resolution actually discarded. A creature that
  // left play entirely counts its full pre-resolution energy as discarded (it can only have left
  // via hitting zero).
  const opposingBefore = new Map<string, number>();
  for (const opponent of getOpponents(state, source.controllerId)) {
    for (const c of opponent.inPlay) {
      opposingBefore.set(c.instanceId, c.currentEnergy ?? 0);
    }
  }
  // registry.ts's onAnyPowerAddedEnergyToCreature (task #29, 2026-07-15: Flying Hinko's Empower)
  // -- same before/after snapshot idea as the opposing-discard tracking above, but for GAINS on
  // EVERY Creature in play (either side, not just opponents -- Flying Hinko's text has no "your"
  // qualifier on either the source Power's controller or the target Creature), and broadcast to
  // every in-play card on BOTH sides afterward (not just the acting player's), since Flying
  // Hinko needs to react regardless of who used the Power.
  const allCreatureEnergyBefore = new Map<string, number>();
  for (const p of state.players.values()) {
    for (const c of p.inPlay) {
      if (cardDb.get(c.definitionKey)?.card_type === 'Creature') allCreatureEnergyBefore.set(c.instanceId, c.currentEnergy ?? 0);
    }
  }

  // state.currentAction (task #32, 2026-07-16) -- the real actor+mechanism for everything from
  // here through the end of this function (resolveEffect itself, every post-resolution broadcast
  // hook below, and the two defeat checks -- all consequences of THIS Power's resolution), read by
  // discardFromPlay/discardEnergy/addEnergy/checkCreatureDefeats as their attribution default.
  // Restored to its PRIOR value (not hardcoded null) right before returning (see the bottom of
  // this function) -- no try/finally, matching this codebase's existing convention of not
  // guarding against exceptions mid-resolution (no other function in the engine does either; a
  // card's resolvePower throwing is already treated as a bug to fix, not a normal flow this needs
  // to be robust against), but save-then-restore so a Power that nests another entry point inside
  // its own resolution (task #35, 2026-07-16 precedent: Rabid Wasperine's onPlay calling
  // declareAttack) doesn't clobber the outer caller's context.
  const previousCurrentAction = state.currentAction;
  // sourceDefinitionKey (task #35, 2026-07-16: Shadow Cloak's Protection) -- `source` is this
  // Power's own acting card, already in scope; see the field's own doc comment in types/state.ts
  // for why only THIS entry point (of the three that set currentAction) populates it.
  state.currentAction = {
    actorPlayerId: playerId,
    source: 'power',
    sourceDefinitionKey: source.definitionKey,
    sourceInstanceId: source.instanceId,
    // Vault of Knowledge Key's Archive (Bucket D Batch C part 2, 2026-08-14) -- pre-collected
    // pre-Power answer, threaded through `state.currentAction` so `effects.ts#discardFromPlay`'s
    // intercept sees it. Same save-then-restore lifetime as the rest of `state.currentAction`.
    ...(options.archiveRedirect !== undefined ? { archiveRedirect: options.archiveRedirect } : {}),
  };

  // task #41, 2026-07-17: the "react-and-negate window" architecture project, Checkpoint A (Xala's
  // Piercing Scream) -- options.negatedByInstanceId was pre-collected by the UI via
  // previewPowerNegationOffers, BEFORE this usePower call, from the DEFENDING player. Costs for
  // THIS Power are already paid (the block above) -- negating only skips resolveEffect, matching
  // Xala's own "all costs for the Power must still be paid" text. The negating card's own
  // resolvePowerNegation applies ITS OWN consequence (e.g. discarding its own energy) instead.
  // PlayerState.lightningSandChargeUntilTurn (task #349, 2026-07-20) -- an AUTOMATIC one-shot
  // negation (no player choice, unlike offersPowerNegation just above), consumed by the FIRST
  // opposing Power targeting one of the charge-holder's own cards. Checked here, not via the
  // offer/accept UI round-trip offersPowerNegation uses, since there's nothing to offer -- it just
  // happens. Cost for THIS Power is already paid (the block above); only resolveEffect is skipped.
  const targetOwnerId = ctx.chosenTargetId ? findCreatureOrMagiById(state, ctx.chosenTargetId)?.controllerId : undefined;
  const targetPlayer = targetOwnerId && targetOwnerId !== playerId ? state.players.get(targetOwnerId) : undefined;
  const lightningSandActive =
    !!targetPlayer &&
    targetPlayer.lightningSandChargeUntilTurn !== null &&
    state.turnNumber <= targetPlayer.lightningSandChargeUntilTurn;

  // Refract's redirect (Nar Spell pass, Category C, 2026-07-22) -- options.redirectedByInstanceId/
  // redirectChosenTargetId were pre-collected by the UI via previewPowerTargetRedirectOffers,
  // BEFORE this usePower call. Unlike negation, resolveEffect is NOT skipped -- ctx.chosenTargetId
  // (a plain mutable field) is swapped to the redirecting player's own replacement pick, and
  // resolveEffect still runs below (negation and lightningSand can still separately apply against
  // the NEW target, though no card exercises that combination today).
  if (options.redirectedByInstanceId && options.redirectChosenTargetId) {
    // Refract attaches to its controller's Magi, so it's never found by findCreatureOrMagiById
    // (top-level inPlay/activeMagi only) -- fall back to findAttachedCardById.
    const redirector = findCreatureOrMagiById(state, options.redirectedByInstanceId) ?? findAttachedCardById(state, options.redirectedByInstanceId);
    const redirectorDef = redirector && cardDb.get(redirector.definitionKey);
    const redirectorEffect = redirectorDef && getCardEffectByName(redirectorDef.name);
    logEvent(state, 'powerTargetRedirected', {
      sourceInstanceId: source.instanceId,
      powerName,
      redirectedByInstanceId: options.redirectedByInstanceId,
      newTargetId: options.redirectChosenTargetId,
    });
    redirectorEffect?.resolveTargetRedirect?.(state, cardDb, redirector!);
    ctx.chosenTargetId = options.redirectChosenTargetId;
  }

  if (options.negatedByInstanceId) {
    const negator = findCreatureOrMagiById(state, options.negatedByInstanceId);
    const negatorDef = negator && cardDb.get(negator.definitionKey);
    const negatorEffect = negatorDef && getCardEffectByName(negatorDef.name);
    logEvent(state, 'powerNegated', { negatedInstanceId: source.instanceId, powerName, negatedByInstanceId: options.negatedByInstanceId });
    negatorEffect?.resolvePowerNegation?.(state, cardDb, negator!, source, powerName, ctx.chosenTargetId, rng);
  } else if (lightningSandActive) {
    targetPlayer!.lightningSandChargeUntilTurn = null;
    logEvent(state, 'powerNegatedByLightningSand', { negatedInstanceId: source.instanceId, powerName, playerId: targetOwnerId });
  } else {
    // Fird Stone's Fird Favor (Naroom Spell-interaction audit, Category C, 2026-07-23) --
    // options.firdStoneProtectedByInstanceId was pre-collected by the UI via
    // previewFurokProtectionOffers, BEFORE this usePower call. Unlike negation, resolveEffect is
    // NOT skipped -- registry.ts's resolveFurokProtection tags the threatened Furok, resolveEffect
    // still runs against every OTHER target it was going to affect, and the tag is removed again
    // right after (a one-shot flag scoped to this single resolution only).
    let firdStoneProtectedTargetId: string | undefined;
    if (options.firdStoneProtectedByInstanceId && ctx.chosenTargetId) {
      const protector = findCreatureOrMagiById(state, options.firdStoneProtectedByInstanceId);
      const protectorDef = protector && cardDb.get(protector.definitionKey);
      const protectorEffect = protectorDef && getCardEffectByName(protectorDef.name);
      if (protectorEffect?.resolveFurokProtection) {
        logEvent(state, 'furokProtected', {
          protectedInstanceId: ctx.chosenTargetId,
          sourceInstanceId: source.instanceId,
          powerName,
          protectedByInstanceId: options.firdStoneProtectedByInstanceId,
        });
        protectorEffect.resolveFurokProtection(state, cardDb, protector!, ctx.chosenTargetId);
        firdStoneProtectedTargetId = ctx.chosenTargetId;
      }
    }
    // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- options.magiProtectedByInstanceId was
    // pre-collected by the UI via previewMagiProtectionOffers, BEFORE this usePower call. Same
    // "resolveEffect NOT skipped" shape as Fird Stone just above, but resolveMagiProtection runs
    // FIRST (discards Clover, draws a card) so the protected-player board snapshot taken right after
    // naturally excludes the now-gone Clover -- then every one of THOSE cards is tagged, resolveEffect
    // runs harmlessly against them, and the tag is stripped again right after.
    let magiProtectedInstanceIds: string[] | undefined;
    if (options.magiProtectedByInstanceId) {
      const protector = findCreatureOrMagiById(state, options.magiProtectedByInstanceId);
      const protectorDef = protector && cardDb.get(protector.definitionKey);
      const protectorEffect = protectorDef && getCardEffectByName(protectorDef.name);
      if (protectorEffect?.resolveMagiProtection) {
        const protectedPlayerId = protector!.controllerId;
        logEvent(state, 'magiProtected', {
          protectedPlayerId,
          sourceInstanceId: source.instanceId,
          powerName,
          protectedByInstanceId: options.magiProtectedByInstanceId,
        });
        protectorEffect.resolveMagiProtection(state, cardDb, protector!, rng);
        const protectedPlayer = state.players.get(protectedPlayerId);
        const protectedCards: CardInstance[] = protectedPlayer?.activeMagi
          ? [protectedPlayer.activeMagi, ...protectedPlayer.inPlay]
          : (protectedPlayer?.inPlay ?? []);
        magiProtectedInstanceIds = protectedCards.map((c) => c.instanceId);
        for (const c of protectedCards) addDurationTagRaw(c, THREE_LEAF_CLOVER_PROTECTED, state.turnNumber, options.magiProtectedByInstanceId);
      }
    }
    // Choice-visibility pass (2026-08-09): backfill powerUsedEvent's detail with whichever choices
    // this Power use actually collected, now that ctx is fully assembled AND every redirect
    // (offersPowerTargetRedirect/Refract above) has settled ctx.chosenTargetId to its FINAL value --
    // logging any earlier would show a pre-redirect target. Deliberately excludes
    // chosenDeckSearchIds/chosenDiscardPileIds/chosenHandCardIds/chosenHandPlayId: those already get
    // logged, more accurately, at the point they're actually consumed (searchDeck/
    // retrieveFromDiscardPile/discardFromHand/the follow-on cardPlayed event) -- logging the raw
    // pre-mutation option ids here too would risk a stale duplicate if a card's own resolvePower
    // ignores some of them.
    const choiceBackfill: Record<string, unknown> = {};
    if (ctx.chosenCategory) choiceBackfill.chosenCategory = ctx.chosenCategory;
    if (ctx.chosenBoolean !== undefined) choiceBackfill.chosenBoolean = ctx.chosenBoolean;
    if (ctx.chosenTargetId) {
      choiceBackfill.chosenTargetId = ctx.chosenTargetId;
      choiceBackfill.chosenTargetName = nameOfInstance(state, cardDb, ctx.chosenTargetId);
    }
    if (ctx.chosenSlotIds && ctx.chosenSlotIds.length > 0) {
      choiceBackfill.chosenSlotIds = ctx.chosenSlotIds;
      choiceBackfill.chosenSlotNames = ctx.chosenSlotIds.map((slot) => slot.map((id) => nameOfInstance(state, cardDb, id)));
    }
    if (ctx.chosenAmounts && Object.keys(ctx.chosenAmounts).length > 0) choiceBackfill.chosenAmounts = ctx.chosenAmounts;
    if (ctx.chosenXValue !== undefined) choiceBackfill.chosenXValue = ctx.chosenXValue;
    if (ctx.chosenDeckTopIds && ctx.chosenDeckTopIds.length > 0) {
      choiceBackfill.chosenDeckTopIds = ctx.chosenDeckTopIds;
      choiceBackfill.chosenDeckTopNames = ctx.chosenDeckTopIds.map((id) => nameOfInstance(state, cardDb, id));
    }
    if (ctx.chosenHandRevealIds && ctx.chosenHandRevealIds.length > 0) {
      choiceBackfill.chosenHandRevealIds = ctx.chosenHandRevealIds;
      choiceBackfill.chosenHandRevealNames = ctx.chosenHandRevealIds.map((id) => nameOfInstance(state, cardDb, id));
    }
    if (ctx.chosenDreamwarpAdjustment !== undefined) choiceBackfill.chosenDreamwarpAdjustment = ctx.chosenDreamwarpAdjustment;
    if (ctx.chosenOpponentHandCardIds && ctx.chosenOpponentHandCardIds.length > 0) {
      choiceBackfill.chosenOpponentHandCardIds = ctx.chosenOpponentHandCardIds;
      choiceBackfill.chosenOpponentHandCardNames = ctx.chosenOpponentHandCardIds.map((id) => nameOfInstance(state, cardDb, id));
    }
    if (ctx.chosenFromOpponentHandIds && ctx.chosenFromOpponentHandIds.length > 0) {
      choiceBackfill.chosenFromOpponentHandIds = ctx.chosenFromOpponentHandIds;
      choiceBackfill.chosenFromOpponentHandNames = ctx.chosenFromOpponentHandIds.map((id) => nameOfInstance(state, cardDb, id));
    }
    if (ctx.nestedSpellChoices) choiceBackfill.nestedSpellChoices = true;
    Object.assign(powerUsedEvent.detail, choiceBackfill);

    resolveEffect?.(ctx);
    if (firdStoneProtectedTargetId) {
      const protectedTarget = findCreatureOrMagiById(state, firdStoneProtectedTargetId);
      if (protectedTarget) removeDurationTag(protectedTarget, FIRD_STONE_PROTECTED);
    }
    if (magiProtectedInstanceIds) {
      for (const id of magiProtectedInstanceIds) {
        const c = findCreatureOrMagiById(state, id);
        if (c) removeDurationTag(c, THREE_LEAF_CLOVER_PROTECTED);
      }
    }
  }

  // registry.ts's onOpponentPowerUsed (task #39-3b, 2026-07-17: Gherish's Abrade) -- unconditional,
  // fires for every Power use regardless of what it actually did; broadcast to every in-play card +
  // Magi on both sides, each card's own body filters for "was the user really my opponent."
  for (const p of state.players.values()) {
    const contributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
    for (const contributor of contributors) {
      for (const effect of effectsFor(state, cardDb, contributor)) {
        effect.onOpponentPowerUsed?.(state, cardDb, contributor, source, powerName);
        // registry.ts's onOwnPowerUsed (task #48, 2026-07-19: Sive's Knowledge) -- own-side sibling,
        // same unconditional post-resolution broadcast; each card's body filters for "was this MY use."
        effect.onOwnPowerUsed?.(state, cardDb, contributor, source, powerName);
      }
    }
  }

  const stillInPlayAfter = new Map<string, CardInstance>();
  for (const opponent of getOpponents(state, source.controllerId)) {
    for (const c of opponent.inPlay) stillInPlayAfter.set(c.instanceId, c);
  }

  // registry.ts's onOwnPowerDiscardedOpposingEnergyFromCreature (task #31, 2026-07-16: The Last
  // Words / Scroll of Fire's Pyromancy, Ithapher's Combustion) -- fires once per opposing Creature
  // that actually lost energy this resolution, so "+N per Creature affected"-style bonuses apply
  // correctly when a single Power hits multiple Creatures. A Creature that left play entirely is
  // skipped (no live target left for a further bonus discard). Fired BEFORE the resolution-wide
  // TOTAL below (bug fix, 2026-07-23, live playtest report: Amanax's Pyromaniac wasn't counting
  // Scroll of Fire's own bonus discard) -- this hook's own reactions (e.g. Scroll of Fire calling
  // discardEnergy again) must settle first, or a TOTAL computed from a snapshot taken before they
  // ran would silently miss them.
  const perCreatureOpposingDiscarded = new Map<string, number>();
  for (const [instanceId, before] of opposingBefore) {
    const afterInstance = stillInPlayAfter.get(instanceId);
    if (!afterInstance) continue;
    const lost = before - (afterInstance.currentEnergy ?? 0);
    if (lost > 0) perCreatureOpposingDiscarded.set(instanceId, lost);
  }
  if (perCreatureOpposingDiscarded.size > 0) {
    const actingPlayer = getPlayer(state, source.controllerId);
    const contributors: CardInstance[] = actingPlayer.activeMagi ? [actingPlayer.activeMagi, ...actingPlayer.inPlay] : [...actingPlayer.inPlay];
    for (const [instanceId, amount] of perCreatureOpposingDiscarded) {
      const targetInstance = stillInPlayAfter.get(instanceId)!;
      for (const contributor of contributors) {
        for (const effect of effectsFor(state, cardDb, contributor)) {
          effect.onOwnPowerDiscardedOpposingEnergyFromCreature?.(
            state,
            cardDb,
            contributor,
            source,
            targetInstance,
            amount,
            perCreatureOpposingDiscarded.size
          );
        }
      }
    }
  }

  // registry.ts's onOpponentPowerDiscardedEnergyFromOwnCreature (task #713, 2026-08-11: Heppeswip's
  // Unravel) -- victim-side sibling of the broadcast just above, off the SAME per-Creature loss map,
  // but broadcast to the AFFECTED Creature's OWN CONTROLLER's board instead of the acting player's,
  // so a card can react to one of its own Creatures having just been hit by an opponent's Power.
  if (perCreatureOpposingDiscarded.size > 0) {
    for (const [instanceId, amount] of perCreatureOpposingDiscarded) {
      const targetInstance = stillInPlayAfter.get(instanceId)!;
      const victimPlayer = getPlayer(state, targetInstance.controllerId);
      const victimContributors: CardInstance[] = victimPlayer.activeMagi ? [victimPlayer.activeMagi, ...victimPlayer.inPlay] : [...victimPlayer.inPlay];
      for (const contributor of victimContributors) {
        for (const effect of effectsFor(state, cardDb, contributor)) {
          effect.onOpponentPowerDiscardedEnergyFromOwnCreature?.(state, cardDb, contributor, source, targetInstance, amount, rng);
        }
      }
    }
  }

  // registry.ts's onOwnPowerDiscardedOpposingEnergy (Amanax's Pyromaniac) -- a FRESH after-snapshot,
  // taken AFTER the per-Creature block above, so a same-resolution bonus (Scroll of Fire, Ithapher,
  // The Last Words) is already reflected in the total this broadcasts.
  const opposingAfterBonuses = new Map<string, CardInstance>();
  for (const opponent of getOpponents(state, source.controllerId)) {
    for (const c of opponent.inPlay) opposingAfterBonuses.set(c.instanceId, c);
  }
  let opposingEnergyDiscarded = 0;
  for (const [instanceId, before] of opposingBefore) {
    const after = opposingAfterBonuses.get(instanceId)?.currentEnergy ?? 0;
    opposingEnergyDiscarded += Math.max(0, before - after);
  }
  if (opposingEnergyDiscarded > 0) {
    const actingPlayer = getPlayer(state, source.controllerId);
    const contributors: CardInstance[] = actingPlayer.activeMagi ? [actingPlayer.activeMagi, ...actingPlayer.inPlay] : [...actingPlayer.inPlay];
    for (const contributor of contributors) {
      for (const effect of effectsFor(state, cardDb, contributor)) {
        effect.onOwnPowerDiscardedOpposingEnergy?.(state, cardDb, contributor, source, opposingEnergyDiscarded);
      }
    }
  }

  let anyCreatureEnergyAdded = 0;
  // registry.ts's onPowerAddedEnergyToCreatures (task #45, 2026-07-18: Poad's Secret Sauce, Forest
  // Hyren's Underbrush, Jip's Tap Strength) -- the per-Creature list of gains, off the same
  // snapshot as the resolution-wide total below. A Creature that left play entirely is skipped (no
  // live target to hand to a reactor, same as the per-Creature loss broadcast).
  const perCreatureGains: { instance: CardInstance; amount: number }[] = [];
  for (const p of state.players.values()) {
    for (const c of p.inPlay) {
      const before = allCreatureEnergyBefore.get(c.instanceId);
      if (before === undefined) continue;
      const gained = Math.max(0, (c.currentEnergy ?? 0) - before);
      anyCreatureEnergyAdded += gained;
      if (gained > 0) perCreatureGains.push({ instance: c, amount: gained });
    }
  }
  if (anyCreatureEnergyAdded > 0) {
    for (const p of state.players.values()) {
      const contributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
      for (const contributor of contributors) {
        for (const effect of effectsFor(state, cardDb, contributor)) {
          effect.onAnyPowerAddedEnergyToCreature?.(state, cardDb, contributor, source, anyCreatureEnergyAdded);
        }
      }
    }
  }
  if (perCreatureGains.length > 0) {
    for (const p of state.players.values()) {
      const contributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
      for (const contributor of contributors) {
        for (const effect of effectsFor(state, cardDb, contributor)) {
          effect.onPowerAddedEnergyToCreatures?.(state, cardDb, contributor, source, perCreatureGains);
        }
      }
    }
  }

  // registry.ts's onAnyPowerDiscardedEnergyFromCreature (task #31, 2026-07-16: Caldera Aq's
  // Heartwarming) -- same before/after-snapshot shape as onOwnPowerDiscardedOpposingEnergy above,
  // unscoped to "opposing": a Creature that left play entirely still counts its full pre-resolution
  // energy as discarded (it can only have left via hitting zero), same reasoning as that block.
  const stillInPlayAllAfter = new Map<string, CardInstance>();
  for (const p of state.players.values()) {
    for (const c of p.inPlay) stillInPlayAllAfter.set(c.instanceId, c);
  }
  let anyCreatureEnergyDiscarded = 0;
  for (const [instanceId, before] of allCreatureEnergyBefore) {
    const after = stillInPlayAllAfter.get(instanceId)?.currentEnergy ?? 0;
    anyCreatureEnergyDiscarded += Math.max(0, before - after);
  }
  if (anyCreatureEnergyDiscarded > 0) {
    for (const p of state.players.values()) {
      const contributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
      for (const contributor of contributors) {
        for (const effect of effectsFor(state, cardDb, contributor)) {
          effect.onAnyPowerDiscardedEnergyFromCreature?.(state, cardDb, contributor, source, anyCreatureEnergyDiscarded, rng);
        }
      }
    }
  }

  // registry.ts's onOwnPowerAddedEnergyToAllOwnCreatures (task #30, 2026-07-15: Torpar's
  // Community) -- distinct from onAnyPowerAddedEnergyToCreature just above (which only sums a
  // TOTAL, not which specific Creatures were touched): this checks, per-Creature, whether EVERY
  // one of the acting player's own Creatures that already existed before this resolution gained
  // energy from it. Only fires for the SOURCE card's own controller's board ("one of YOUR cards").
  const actingPlayer = getPlayer(state, source.controllerId);
  const ownCreaturesBefore = actingPlayer.inPlay.filter((c) => allCreatureEnergyBefore.has(c.instanceId));
  if (ownCreaturesBefore.length > 0) {
    const allGained = ownCreaturesBefore.every((c) => (c.currentEnergy ?? 0) > (allCreatureEnergyBefore.get(c.instanceId) ?? 0));
    if (allGained) {
      const contributors: CardInstance[] = actingPlayer.activeMagi ? [actingPlayer.activeMagi, ...actingPlayer.inPlay] : [...actingPlayer.inPlay];
      for (const contributor of contributors) {
        for (const effect of effectsFor(state, cardDb, contributor)) {
          effect.onOwnPowerAddedEnergyToAllOwnCreatures?.(state, cardDb, contributor, source);
        }
      }
    }
  }

  // Step 6: Creature-defeat check again, from whatever the effect just did.
  checkCreatureDefeats(state, cardDb, 'power', undefined, rng);

  // Step 7: only now check Magi-defeat -- after the full Power has resolved, not mid-resolution.
  checkMagiDefeats(state, cardDb, rng);

  // reactiveWindow (task #37, 2026-07-17: Yricho/Bazha's Pendant/T'kanzam) -- unconditional, every
  // Power use ends by writing a fresh 'opponentPlayOrPower' window for the actor's opponent(s), same
  // "self-overwriting, single-slot" convention combat.ts's declareAttack already established for
  // 'cardAttacked'. Multi-opponent games have no real precedent for this mechanism yet, so this
  // targets a single opponent (the first), matching this codebase's existing 2-player-primary scope.
  const reactionOpponents = getOpponents(state, playerId);
  if (reactionOpponents.length > 0) {
    const reactingPlayerId = reactionOpponents[0]!.playerId;
    state.reactiveWindow = {
      kind: 'opponentPlayOrPower',
      reactingPlayerId,
      actingPlayerId: playerId,
      trigger: 'power',
      powerName,
      powerSourceInstanceId: source.instanceId,
      powerSourceIsCreature: cardDb.get(source.definitionKey)?.card_type === 'Creature',
    };
    // registry.ts's prepareReactionToWindow (task #37, 2026-07-17: T'kanzam's Dream Loops) --
    // fired once, immediately, over the REACTING player's own board only.
    const reactingPlayer = state.players.get(reactingPlayerId);
    const reactingContributors: CardInstance[] = reactingPlayer?.activeMagi
      ? [reactingPlayer.activeMagi, ...reactingPlayer.inPlay]
      : [...(reactingPlayer?.inPlay ?? [])];
    for (const contributor of reactingContributors) {
      for (const effect of effectsFor(state, cardDb, contributor)) {
        effect.prepareReactionToWindow?.(state, cardDb, state.reactiveWindow, contributor);
      }
    }
  }

  consumeIntensifyIfUsed(state); // Intensify -- see effects.ts's own doc comment
  state.currentAction = previousCurrentAction;
  state.activeRegionSwap = previousActiveRegionSwap;
}
