// Agram -- Power "Possess (2): Choose any one of your Creatures in play and any one opposing
// Creature in play with less energy than your chosen Creature. Discard your chosen Creature.
// Gain control of the chosen opposing Creature. That Creature may not attack this turn." Slot 2
// genuinely depends on slot 1's answer -- same interdependent-slot shape as raskDeserter.ts.
//
// Focus: "Before Agram energizes during your Energize Step, permanently add one to his energize
// rate." Uses the new registry.ts `beforeOwnEnergize` hook (2026-07-12) -- fires right before
// turn.ts's runEnergizePhase reads his effective rate, so the bump applies to THIS energize event
// and ratchets for every one after (energizeModifiers.ts's addEnergizeModifier with no expiry).
//
// Opportunist: "At the beginning of your turn, if Agram's energize rate is 10 or more, and if you
// have another Magi in your Magi pile, place Agram at the bottom of your Magi pile face down.
// Discard all of your cards from play, and play your next Magi face up. If Agram energizes for 11
// or more, and he is your last Magi, you lose the game." Two mutually-exclusive branches on
// `isLastMagi` (the swap needs "another Magi," the loss needs to BE the last one). The swap wipes
// inPlay entirely ("discard all of your cards from play" -- unlike M'Rika/Giant Parathin's
// Interchange, nothing is kept) and does NOT skip starting-card tutoring for the new Magi (the
// text doesn't say "you do not get the new Magi's starting cards" the way theirs does). The loss
// reuses energy.ts's now-exported `defeatMagi` (the exact same zone move a normal defeat uses),
// then `checkMagiDefeats` to run the normal win-check machinery.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingCreatures, findInPlayById } from '../targeting.js';
import { discardFromPlay, gainControl } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { addEnergizeModifier } from '../energizeModifiers.js';
import { effectiveEnergizeRate, revealNextMagi } from '../turn.js';
import { moveToDiscardPile } from '../zones.js';
import { defeatMagi, checkMagiDefeats } from '../energy.js';
import { isShadowGeyserName } from './shadowGeysers.js';
import type { CardInstance } from '../types/instance.js';

registerCardEffect('Agram', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Focus is the pre-energize ratchet; Opportunist is
  // the beginning-of-turn swap/loss branch. Possess is a printed Power (Taglat's "or Power"
  // branch), not an Effect -- powerTargetSlots/resolvePower travel with the Power grant, not with
  // Focus or Opportunist.
  effectHooks: {
    Focus: ['beforeOwnEnergize'],
    Opportunist: ['onOwnTurnStart'],
  },
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose one of your Creatures',
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid),
      min: 1,
      max: 1,
    },
    {
      label: 'Choose an opposing Creature with less energy than your chosen Creature',
      pool: (s, db, pid, priorChoices) => {
        const ownId = priorChoices[0]?.[0];
        if (!ownId) return [];
        const own = findInPlayById(s, ownId);
        if (!own) return [];
        return opposingCreatures(s, db, pid).filter((c) => (c.currentEnergy ?? 0) < (own.currentEnergy ?? 0));
      },
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Possess') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const ownId = slots[0]?.[0];
    const oppId = slots[1]?.[0];
    if (!ownId || !oppId) return;

    const own = findInPlayById(ctx.state, ownId);
    if (!own || ctx.cardDb.get(own.definitionKey)?.card_type !== 'Creature') return;
    if (own.controllerId !== ctx.controllingPlayer.playerId) return;

    const opp = findInPlayById(ctx.state, oppId);
    if (!opp || ctx.cardDb.get(opp.definitionKey)?.card_type !== 'Creature') return;
    if (opp.controllerId === ctx.controllingPlayer.playerId) return;
    if ((opp.currentEnergy ?? 0) >= (own.currentEnergy ?? 0)) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, own.instanceId, undefined, undefined, ctx.rng);
    gainControl(ctx.state, ctx.cardDb, opp, ctx.controllingPlayer.playerId);
    addRestrictionTag(ctx.state, opp, CANNOT_ATTACK, ctx.state.turnNumber);
  },
  beforeOwnEnergize: (state, cardDb, self) => {
    addEnergizeModifier(self, 1);
  },
  onOwnTurnStart: (state, cardDb, self, rng) => {
    const player = state.players.get(self.controllerId);
    if (!player || player.activeMagi?.instanceId !== self.instanceId) return;
    const rate = effectiveEnergizeRate(state, cardDb, self);
    const isLastMagi = player.magiQueue.length === 0;

    if (rate >= 11 && isLastMagi) {
      defeatMagi(state, cardDb, player, rng);
      checkMagiDefeats(state, cardDb, rng);
      return;
    }

    if (rate >= 10 && !isLastMagi) {
      // Shadow Geyser subsystem (task #53-9, 2026-07-21): "Agram does not discard any Shadow
      // Geysers from play when he leaves play" -- this swap is a manual wipe, not a real Magi
      // defeat (defeatMagi is never called here), so the Geysers' own survivesOwnMagiDefeat hook
      // (which only fires inside defeatMagi) never gets consulted -- this exception has to be
      // handled directly in Agram's own wipe loop instead.
      const keptGeysers: CardInstance[] = [];
      for (const card of player.inPlay) {
        if (isShadowGeyserName(cardDb.get(card.definitionKey)?.name)) {
          keptGeysers.push(card);
          continue;
        }
        moveToDiscardPile(state, player, card);
      }
      player.inPlay = keptGeysers;
      player.magiQueue.push(self);
      player.activeMagi = null;
      revealNextMagi(state, cardDb, player, undefined, rng); // no skipStartingCards -- his text doesn't forbid them
    }
  },
});
