// Flint Staff -- "Tremor: Choose an opposing Creature. If it is larger than your largest
// Creature, move two energy from the chosen Creature to your largest Creature."

import { registerCardEffect } from './registry.js';
import { opposingCreatures, largestCreatureControlledBy, findInPlayById } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Flint Staff', {
  powerTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Tremor') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;

    const largest = largestCreatureControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (!largest) return; // nothing to move to
    if ((target.currentEnergy ?? 0) <= (largest.currentEnergy ?? 0)) return; // not larger

    rearrangeEnergy(ctx.state, ctx.cardDb, target, largest, 2, ctx.rng);
  },
});
