// Ember Hyren -- "Singe (2): Choose a Creature. Discard two energy from the chosen Creature."
// Unrestricted target (either player's Creatures, not just opposing). Also implements "Heat
// Feed": "Whenever one of your other Creatures attacks, add one energy to Ember Hyren" -- an
// onAttack trigger that reacts to attacks it's not itself part of (neither attacker nor
// defender), which is exactly why combat.ts scans every in-play card rather than just those two.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Ember Hyren', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Singe') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 2, undefined, undefined, ctx.rng);
  },
  onAttack: (ctx, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return; // must be "your" Creature
    if (ctx.attacker.instanceId === self.instanceId) return; // "one of your OTHER Creatures"
    addEnergy(ctx.state, ctx.cardDb, self, 1, 'effect');
  },
});
