// Beeb -- "Underfoot: Whenever Beeb is in an attack with a Creature with more than twice Beeb's
// current energy, Beeb removes three additional energy from the opposing Creature." Self-agnostic
// -- Beeb can be either the attacker or the defender, checked against whichever side it's on.

import { registerCardEffect } from './registry.js';

registerCardEffect('Beeb', {
  onAttack: (ctx, self) => {
    const beebEnergy = self.currentEnergy ?? 0;
    if (ctx.attacker.instanceId === self.instanceId) {
      const opposingEnergy = ctx.defender ? ctx.snapshot.defenderEnergy : 0;
      if (ctx.defender && opposingEnergy > beebEnergy * 2) {
        ctx.locked.attackerEnergy += 3;
      }
    } else if (ctx.defender?.instanceId === self.instanceId) {
      const opposingEnergy = ctx.snapshot.attackerEnergy;
      if (opposingEnergy > beebEnergy * 2) {
        ctx.locked.defenderEnergy += 3;
      }
    }
  },
});
