// Alaban Kit -- "Undream: Whenever one of your other Arderial Creatures in play is attacked, you
// may discard Alaban Kit from play. If you do, at the end of the current turn, return the
// attacking Creature from play to its owner's hand, discarding that Creature's energy." "You may"
// applied unconditionally -- bouncing an opponent's attacker is a strong, essentially always-worth
// -it effect, same "no real reason to decline" convention used elsewhere (Amanax, Ullig's
// Slingshot). Uses the new task #29 RETURN_TO_HAND_AT_END_OF_TURN tag (durationTags.ts), same
// generic-sweep shape as DISCARD_AT_END_OF_TURN.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { addPermanentTag, RETURN_TO_HAND_AT_END_OF_TURN } from '../durationTags.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Alaban Kit', {
  onAttack: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    if (ctx.defender.instanceId === self.instanceId) return; // "one of your OTHER Arderial Creatures"
    if (ctx.cardDb.get(ctx.defender.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Arderial')) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.defendingPlayer, self.instanceId, undefined, undefined, ctx.rng);
    addPermanentTag(ctx.state, ctx.cardDb, ctx.attacker, RETURN_TO_HAND_AT_END_OF_TURN);
  },
});
