// Flame Geyser (Spell, cost 7) -- "Discard three energy from each Creature and Magi in play."
// Cald Spell pass, Category A (2026-07-20). No target at all (no spellTargets declared) -- a plain
// broadcast discardEnergy loop over every player's Creatures + Magi, same shape as ainjerSwarm.ts's
// unqualified sweep, just symmetric (both sides) and covering Magi too. Already cited in
// docs/deferred-card-mechanics.md as a correctness worked-example proving the BURROWED energy-loss
// cap handles a fully symmetric sweep with no special-casing.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Flame Geyser', {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- unconditional, so this only checks
  // that an opposing Magi actually exists.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId) => getOpponents(state, actingPlayerId).some((opp) => !!opp.activeMagi),
  resolveSpell: (ctx) => {
    // ctx.rng threaded (found via a fuzz-harness replay divergence, 2026-07-30): a defeat here
    // can trigger a reactor like Bagala Cub's onCardDiscardedFromPlay, which reshuffles a deck.
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 3, 'spell', undefined, ctx.rng);
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      discardEnergy(ctx.state, ctx.cardDb, magi, 3, 'spell', undefined, ctx.rng);
    }
  },
});
