// Cyclone Xyx -- "Storm Front (1): Discard one energy from each opposing Arderial Creature." No
// target picker needed -- the effect applies automatically to every matching Creature, not a
// single chosen one. Also implements "Backlash": "Whenever Cyclone Xyx is attacked, before energy
// is removed, remove one energy from each of the attacking player's Creature[s]" -- fires when
// Cyclone Xyx is specifically the declared DEFENDER (not just any of its controller's Creatures),
// before damage locks in, matching the card's own "before energy is removed" timing.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Cyclone Xyx', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Storm Front') return;
    const targets = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    for (const creature of targets) {
      if (effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Arderial'))) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng); // Power-sourced, unaffected by Shifty
      }
    }
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return; // must be attacked directly
    for (const creature of ctx.attackingPlayer.inPlay) {
      if (ctx.cardDb.get(creature.definitionKey)?.card_type === 'Creature') {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, 'effect', undefined, ctx.rng);
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Arderial'],
});
