// Cloud Sceptre -- "Mindwinds (1): Discard up to five cards from your hand to draw the same
// number of cards." Originally scraped/printed as a variable "discard X, draw X" (handDiscardCost's
// 'any' count, same shape as Vinoc's Generate) -- officially errata'd (data-pipeline/output/
// rulings.json, applied 2026-07-09) to cap the discard at five. handDiscardCost's 'any' shape has
// no built-in upper bound, so the cap is enforced in resolvePower itself (rejecting an
// over-the-limit selection), same "resolvePower is the final authority, not just the UI's offered
// pool" pattern used throughout this codebase.

import { registerCardEffect } from './registry.js';
import { drawCards, discardFromHand } from '../effects.js';

registerCardEffect('Cloud Sceptre', {
  handDiscardCost: { count: 'any' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mindwinds') return;
    const ids = (ctx.chosenHandCardIds ?? []).filter((id) => ctx.controllingPlayer.hand.some((c) => c.instanceId === id));
    if (ids.length === 0 || ids.length > 5) return;
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids, undefined, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids.length);
  },
});
