// Grendile -- "Snow Plow: Whenever Grendile attacks a Creature, after energy is removed, discard
// energy from that Creature's Magi equal to the energy on Grendile." afterCombat -- reads
// Grendile's OWN energy post-damage (it already took its counter-damage by this point, matching
// "after energy is removed").

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Grendile', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    const magi = ctx.defendingPlayer.activeMagi;
    if (!magi) return;
    discardEnergy(ctx.state, ctx.cardDb, magi, self.currentEnergy ?? 0, 'effect', undefined, ctx.rng);
  },
});
