// Orwin's Ring -- "Purity: At the end of your turn, if all Spells in your discard pile are
// Naroom, discard all of your non-Naroom cards from play and add one energy to each of your
// Creatures in play."

import { registerCardEffect } from './registry.js';
import { applyPurity } from './purityRing.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';

registerCardEffect("Orwin's Ring", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, 'Naroom', rng)) return;
    for (const creature of creaturesControlledBy(state, cardDb, self.controllerId)) {
      addEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
});
