// Poad's Secret Sauce -- "Flavor: Whenever one of your Spells or Powers adds energy to exactly one
// of your Creatures, add an additional energy to that Creature." Built task #45, 2026-07-18, the
// Naroom region pass -- registry.ts's new onPowerAddedEnergyToCreatures per-Creature broadcast (see
// its own doc comment). "Exactly one of your Creatures" == the whole resolution added energy to
// exactly one Creature AND it's yours (Spells never execute, so only the Power half fires here).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect("Poad's Secret Sauce", {
  onPowerAddedEnergyToCreatures: (state, cardDb, self, sourceCard, gains) => {
    if (sourceCard.controllerId !== self.controllerId) return; // "one of YOUR Spells or Powers"
    if (gains.length !== 1) return; // "exactly one ... Creature"
    const only = gains[0]!.instance;
    if (only.controllerId !== self.controllerId) return; // "of YOUR Creatures"
    addEnergy(state, cardDb, only, 1, 'effect');
  },
});
