// Makoor -- "Onslaught: Discard all of your Bograth Creatures from play. For each Creature
// discarded, choose an opposing Creature in play. Discard three energy from each chosen
// Creature. You can choose the same Creature more than once with this Power." Makoor itself is
// Bograth, so it sacrifices itself along with any other Bograth Creatures it controls -- N (the
// slot's pick count) is simply "how many Bograth Creatures you control right now," computed
// before any of this Power's own resolution has happened, which is exactly what the slot-building
// step sees. allowRepeats: true is the point of this card -- the "same Creature more than once"
// clause is explicit, unlike every other multi-slot card so far.
//
// "Opposing cards do not affect Onslaught when it is used and cannot alter the amount of energy
// discarded by Onslaught" -- same "cannot be altered" clause as Rockslide Hyren's Crush, so each
// chosen Creature's energy loss bypasses discardEnergy entirely (raw currentEnergy math + a
// manual checkCreatureDefeats call) instead of respecting the burrow cap/Shifty.

import type { CardDatabase } from '../types/card.js';
import type { GameState, PlayerId } from '../types/state.js';
import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions, opposingCreatures, findInPlayById, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';

function ownBograthCreatures(state: GameState, cardDb: CardDatabase, playerId: PlayerId) {
  return creaturesControlledBy(state, cardDb, playerId).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Bograth')));
}

registerCardEffect('Makoor', {
  powerTargetSlots: (state, cardDb, playerId) => {
    const count = ownBograthCreatures(state, cardDb, playerId).length;
    return [
      {
        label: `Choose an opposing Creature for each of your ${count} Bograth Creature(s) (repeats allowed)`,
        pool: (s, db, pid) => opposingCreatures(s, db, pid),
        min: count,
        max: count,
        allowRepeats: true,
      },
    ];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Onslaught') return;
    const toSacrifice = ownBograthCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    const chosen = ctx.chosenSlotIds?.[0] ?? [];
    if (chosen.length !== toSacrifice.length) return;
    for (const id of chosen) {
      const target = findInPlayById(ctx.state, id);
      if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
      if (target.controllerId === ctx.controllingPlayer.playerId) return;
    }

    for (const creature of toSacrifice) {
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, creature.instanceId, undefined, undefined, ctx.rng);
    }
    for (const id of chosen) {
      const target = findInPlayById(ctx.state, id);
      if (target) target.currentEnergy = Math.max(0, (target.currentEnergy ?? 0) - 3);
    }
    checkCreatureDefeats(ctx.state, ctx.cardDb, 'power', undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Only the sacrifice-side Bograth check is in scope --
  // the opposing-target slot pool (powerTargetSlots above) is unrestricted.
  specifiedTargetRegions: () => ['Bograth'],
});
