// Sagawal -- two printed clauses:
//   "Invulnerability: Sagawal loses one less energy in attacks." (invulnerability.ts)
//   "Watchful: When an opposing Spell is discarding only one of your other Kybar's Teeth
//   Creatures from play, you may discard Sagawal from play instead." Region-audit follow-up,
//   2026-07-24 -- the deferral reason ("Spell effect-resolution isn't built yet") is stale (Spell
//   resolution shipped in task #330, and registry.ts's `preventsDiscardOfViaOwnCost` -- Mijji's
//   Guardian's exact mechanism -- was ALSO already widened to consult `resolvedSource === 'spell'`
//   back in the 2026-07-21 audit correction, before this pass even started). Sagawal narrows it
//   further to Spell-only (Mijji covers both Spell and Power).

import { registerCardEffect } from './registry.js';
import { applyInvulnerability } from './invulnerability.js';
import { effectiveRegions } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Sagawal', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Invulnerability owns onAttack;
  // Watchful owns preventsDiscardOfViaOwnCost (the Spell-only self-discard-substitute reactor).
  effectHooks: {
    Invulnerability: ['onAttack'],
    Watchful: ['preventsDiscardOfViaOwnCost'],
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
  preventsDiscardOfViaOwnCost: (state, cardDb, target, self, rng) => {
    if (target.instanceId === self.instanceId) return false; // "your OTHER Kybar's Teeth Creatures"
    if (target.controllerId !== self.controllerId) return false;
    if (state.currentAction?.source !== 'spell') return false; // "an opposing SPELL" specifically
    const targetDef = cardDb.get(target.definitionKey);
    if (targetDef?.card_type !== 'Creature' || !effectiveRegions(state, cardDb, target).includes("Kybar's Teeth")) return false;
    const owner = state.players.get(self.controllerId);
    if (!owner) return false;
    discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    return true;
  },
});
