// Rock Arboll -- "Infuse: Discard Rock Arboll from play. Add energy to your Magi equal to the
// energy on the smallest opposing Creature." First use of targeting.ts's new smallestOf helper.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, smallestOf } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Rock Arboll', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Infuse') return;
    const smallest = smallestOf(opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId));
    const amount = smallest?.currentEnergy ?? 0;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    if (amount > 0 && ctx.controllingPlayer.activeMagi) {
      addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, amount, 'power');
    }
  },
});
