// Bone Grag -- "Advance: Choose another Oracle Creature. Add two energy to the chosen Creature."
// "Oracle" is a structured `subtype` field (confirmed against the real database), not a name
// family -- first card filtering by subtype rather than name-includes or regions. Excludes itself
// at the POOL level too (via sourceInstanceId, same fix as Flame Rudwot's Healing Flame -- see
// registry.ts's powerTargets doc comment) -- matters if Bone Grag is ever itself an Oracle.

// "Reclaim: Whenever one of your cards is discarded from play by an opposing card, add one energy
// to Bone Grag. If the discarded card was an Oracle, draw a card." (#536 C6d, 2026-07-27 -- the
// card-pool reconciliation found this Effect had no hook at all, so it never fired.)
//
// BROAD: "discarded from play" is unqualified, so per Comprehensive Rules p.11 a defeated Creature
// counts too -- no `cause` filter. "By an opposing card" is the standard causedByPlayerId test,
// same shape as Everburning Wick's Short Fuse.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy, drawCards } from '../effects.js';

registerCardEffect('Bone Grag', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discardedOwnerId !== self.controllerId) return; // "one of YOUR cards"
    if (causedByPlayerId === undefined || causedByPlayerId === self.controllerId) return; // "by an OPPOSING card"
    const owner = state.players.get(self.controllerId);
    // The broadcast includes the departing card itself, and Bone Grag can be the thing discarded.
    // Adding energy to a card sitting in the discard pile would be meaningless, so require that
    // Bone Grag is still in play to collect.
    if (!owner?.inPlay.some((c) => c.instanceId === self.instanceId)) return;

    addEnergy(state, cardDb, self, 1, 'effect');
    // Same structured `subtype` field Advance already filters on, not a name family.
    if (cardDb.get(discarded.definitionKey)?.subtype === 'Oracle') drawCards(state, cardDb, owner, 1);
  },
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) =>
    allCreaturesInPlay(state, cardDb).filter(
      (c) => c.instanceId !== sourceInstanceId && cardDb.get(c.definitionKey)?.subtype === 'Oracle'
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Advance') return;
    if (ctx.chosenTargetId === undefined || ctx.chosenTargetId === ctx.source.instanceId) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (ctx.cardDb.get(target.definitionKey)?.subtype !== 'Oracle') return;

    addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
  },
});
