// Typhoon (Spell, Orothe, cost 8) -- "Roll one die. Discard energy equal to the die roll from each
// non-Orothe Creature in play." No targeting -- a pure board sweep, using the injected ctx.rng (not
// a raw Math.random/rollDie call) per this project's own rng-determinism convention.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';

registerCardEffect('Typhoon', {
  resolveSpell: (ctx) => {
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.controllingPlayer.playerId,
      6,
      'typhoon:resolve',
      {},
      ctx.rng
    );
  },
});

registerRollConsumer('typhoon:resolve', (state, cardDb, _source, _payload, finalRoll, rng) => {
  const targets = allCreaturesInPlay(state, cardDb).filter(
    (c) => !effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Orothe'))
  );
  for (const target of targets) {
    discardEnergy(state, cardDb, target, finalRoll, 'spell', undefined, rng);
  }
});
