// Kazm -- "Hunter: Whenever an opposing Magi plays a Creature with starting energy less than the
// current energy of your smallest Kybar's Teeth Creature in play, add three energy to Kazm."
// Broadcast onPlay reactor on the Magi itself (onPlay already fires for both players' Magi, same
// as Ora/Wudge) -- no Kybar's Teeth Creature in play means the comparison has nothing to check
// against, so it silently doesn't fire (matches the printed text's own dependency on having one).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions, smallestOf, effectiveStartingEnergy } from '../targeting.js';

registerCardEffect('Kazm', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;

    const ownKybarsTeeth = creaturesControlledBy(state, cardDb, self.controllerId).filter((c) =>
      effectiveRegions(state, cardDb, c).includes("Kybar's Teeth")
    );
    const smallest = smallestOf(ownKybarsTeeth);
    if (!smallest) return;
    if (effectiveStartingEnergy(state, cardDb, played) >= (smallest.currentEnergy ?? 0)) return;

    addEnergy(state, cardDb, self, 3, 'effect');
  },
});
