// Grow (Spell, cost 3) -- "Roll one die. Choose any one Creature in play. Add energy equal to the
// die roll to the chosen Creature." Naroom Spell pass, Category A (2026-07-23). Identical shape to
// thermalBlast.ts (Cald Spell pass) -- plain rollDie (not rollDieWithRerolls), addEnergy instead
// of discardEnergy.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { addEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Grow', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.controllingPlayer.playerId,
      6,
      'grow:resolve',
      { chosenTargetId: ctx.chosenTargetId },
      ctx.rng
    );
  },
});

registerRollConsumer('grow:resolve', (state, cardDb, _source, payload, finalRoll) => {
  const { chosenTargetId } = payload as { chosenTargetId: string };
  const target = findInPlayById(state, chosenTargetId);
  if (!target || cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
  addEnergy(state, cardDb, target, finalRoll, 'spell');
});
