// Yayek -- "Seeds of Deceit: At the beginning of your turn, choose a Spell or Relic in an
// opposing discard pile and shuffle it into its owner's deck. Increase Yayek's energize by that
// card's energy cost until the end of your turn (X equals zero)."
//
// onOwnTurnStart + effects.ts's retrieveFromDiscardPile ('deckShuffled' destination) +
// energizeModifiers.ts's addEnergizeModifier (registry.ts's energizeRateModifier doc comment
// names this exact card as the STORED, "until end of turn"-expiring precedent that hook is
// distinct from). "That card's energy cost" -- a variable ('X'/'X+N') cost counts as 0, same
// "X equals zero" the printed text itself calls out.
//
// Real choice (task #40-1, 2026-07-17, player-choice-default retrofit): replaces the earlier
// "first eligible Spell/Relic found (opponent order, then discard-pile order)" auto-pick with a
// real pending choice (registry.ts's pendingTargetChoice/resolveTargetChoice) -- the pool is
// discard-pile cards (Corathan's own precedent: "pendingTargetChoice's pool type is plain
// CardInstance either way").

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';
import { addEnergizeModifier } from '../energizeModifiers.js';
import { getOpponents } from '../types/state.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import type { Rng } from '../rng.js';

const SEEDS_PENDING = 'yayekSeedsPending';

function numericCost(cost: number | string): number {
  if (typeof cost === 'number') return cost;
  const parsed = Number(cost);
  return Number.isFinite(parsed) ? parsed : 0; // 'X'/'X+N' -- "X equals zero" per the printed text
}

function seedsPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  return getOpponents(state, self.controllerId).flatMap((p) =>
    p.discardPile.filter((c) => {
      const def = cardDb.get(c.definitionKey);
      return def?.card_type === 'Spell' || def?.card_type === 'Relic';
    })
  );
}

registerCardEffect('Yayek', {
  onOwnTurnStart: (state, cardDb, self) => {
    if (seedsPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, SEEDS_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SEEDS_PENDING)) return undefined;
    const pool = seedsPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Yayek's Seeds of Deceit: choose a Spell or Relic in an opposing discard pile", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng?: Rng) => {
    removePermanentTag(self, SEEDS_PENDING);
    if (!chosenInstanceId) return;
    const target = seedsPool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    const owner = state.players.get(target.ownerId);
    if (!owner) return;
    const def = cardDb.get(target.definitionKey)!;
    // rng threaded (found via a fuzz-harness replay divergence, 2026-07-30): the shuffle below was
    // silently falling back to Math.random, same bug class as Nashiq's Salvage's own precedent
    // (the OTHER 'deckShuffled' caller, which already threads ctx.rng correctly).
    retrieveFromDiscardPile(state, owner, target.instanceId, 'deckShuffled', rng);
    addEnergizeModifier(self, numericCost(def.cost), { expiresAfterTurnNumber: state.turnNumber });
  },
});
