// Speag -- all three printed effects:
//   "Work: Speag cannot attack." (permanent tag applied on entry, via onPlay)
//   "Watch: Whenever one of your Creatures is attacked, add two energy to Speag before energy is
//   removed." (a third-party reactor -- Speag doesn't need to be the defender itself)
//   "Weave: Whenever Speag is attacked, before energy is removed, you may move up to one energy
//   between it and one of your other Weave Creatures in play." (defend-only -- see weave.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag, CANNOT_ATTACK } from '../durationTags.js';
import { applyWeave } from './weave.js';

registerCardEffect('Speag', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Work self-tags CANNOT_ATTACK on entry
  // via `onPlay`; Watch and Weave share the same fused `onBeforeEnergyRemoved` body (both listed
  // under `onBeforeEnergyRemoved`). Weave additionally carries `weaveConfig`.
  effectHooks: {
    Work: ['onPlay'],
    Watch: ['onBeforeEnergyRemoved'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'defendOnly' },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    addPermanentTag(state, cardDb, self, CANNOT_ATTACK);
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.defender && ctx.defender.controllerId === self.controllerId) {
      addEnergy(ctx.state, ctx.cardDb, self, 2, 'effect');
    }
    applyWeave(ctx, self, ['Weave'], 'defendOnly');
  },
});
