// Bagala Hunter -- "Stalk: Choose any one opposing Creature in play. Until the end of your next
// turn, the chosen Creature is stalked; whenever a stalked Creature is attacked, discard one
// energy from the stalked Creature before energy is removed." Identical wording to Tropical
// Vinoc's Stalk minus the hand-discard cost and the repeatable clause -- the plainest possible
// reuse of the STALKED duration tag.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, findInPlayById } from '../targeting.js';
import { addDurationTag, STALKED, nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Bagala Hunter', {
  powerTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Stalk') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;

    addDurationTag(ctx.state, ctx.cardDb, target, STALKED, nextOwnTurnNumber(ctx.state));
  },
});
