// Harmony (Weave Spell, cost 6) -- "All Creatures in play with more than three energy are reduced
// to three energy. All Creatures in play with less than three energy are raised to three energy.
// Non-Weave Magi may not play Harmony."
//
// Weave Spell pass (2026-07-26), Category A. Both halves are one levelling pass to exactly 3.
// Routed through discardEnergy/addEnergy rather than assigning currentEnergy directly, so the
// reduction is visible to every energy-loss reactor and reducer (Rayje's Sword, Garan, Bulomp's
// Shiftier, etc.) exactly as a Spell-sourced change should be.
//
// "Non-Weave Magi may not play Harmony" is the card's `region_restrictive` data flag, enforced
// generically by play.ts -- zero code here, crushingSands.ts's header established that convention.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';

const HARMONY_LEVEL = 3;

registerCardEffect('Harmony', {
  resolveSpell: (ctx) => {
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      const current = creature.currentEnergy ?? 0;
      if (current > HARMONY_LEVEL) {
        discardEnergy(ctx.state, ctx.cardDb, creature, current - HARMONY_LEVEL, 'spell', undefined, ctx.rng);
      } else if (current < HARMONY_LEVEL) {
        addEnergy(ctx.state, ctx.cardDb, creature, HARMONY_LEVEL - current, 'spell');
      }
    }
  },
});
