// Cactus Hyren -- "Pierce: As Cactus Hyren attacks a Creature with six or more energy, remove
// three energy from that Creature." Same shape as Sand Sark's Hunt, different threshold/amount.

import { registerCardEffect } from './registry.js';

registerCardEffect('Cactus Hyren', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    if (ctx.snapshot.defenderEnergy < 6) return;
    ctx.locked.attackerEnergy += 3;
  },
});
