// Tropical Rain (Spell, Paradwyn, cost 2) -- "Choose any one Creature in play with the Effect
// 'Dreamwarp'. Add three energy to the chosen Creature. You can play Tropical Rain on an opponent's
// turn, immediately after one of your Creatures is attacked, but before energy is removed."
//
// The resolve half is an ordinary single-target spellTargets/resolveSpell pair. The off-turn play
// window is the new registry.ts reactsToImpendingCreatureAttack -- the Creature-defender sibling of
// Jingjack's Spring Out (reactsToImpendingMagiAttack), checked by Play.tsx at the SAME
// pre-declareAttack checkpoint Good Ol' Ashgar's Combat Reflexes uses for the Magi-defender case.
// That checkpoint (not GameState.reactiveWindow) is the right one: reactiveWindow only exists
// AFTER an attack fully resolves, and "before energy is removed" has to land earlier than that.
// Unlike Spring Out, an accepted play doesn't change the attack -- Tropical Rain resolves at its
// normal cost, then the same attack proceeds.
//
// "Creature in play with the Effect 'Dreamwarp'" == any Effect currently on the Creature that
// registers a `dreamwarpRange` hook -- its own PRINTED one, or one arriving via a card-level grant
// (Rock Yajo / Taglat: owner ruling 2026-07-28 -- "a Creature granted a Dreamwarp Creature's Effects
// is a Dreamwarp Creature"). `grantedDreamwarpRange` is still deliberately NOT consulted here: that
// hook conveys a range at play-from-hand time only (Grass Etiki), so a Creature already in play
// never has Dreamwarp through it.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { effectsFor } from '../grantedEffects.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

function dreamwarpCreaturesInPlay(state: GameState, cardDb: CardDatabase) {
  return allCreaturesInPlay(state, cardDb).filter((c) =>
    effectsFor(state, cardDb, c).some((e) => e.dreamwarpRange !== undefined)
  );
}

registerCardEffect('Tropical Rain', {
  spellTargets: (state, cardDb) => dreamwarpCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = dreamwarpCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    addEnergy(ctx.state, ctx.cardDb, target, 3, 'spell');
  },
  // "one of YOUR Creatures is attacked" -- the defender must belong to Tropical Rain's controller.
  reactsToImpendingCreatureAttack: (state, cardDb, playerId, self, _attackingInstanceId, defendingInstanceId) => {
    if (self.controllerId !== playerId) return false;
    const player = state.players.get(playerId);
    return player?.inPlay.some((c) => c.instanceId === defendingInstanceId) === true;
  },
});
