// Wessig -- "Landslide: If Wessig is discarded from play, discard all non-Kybar's Teeth Creatures
// and Relics from play." Built task #42, 2026-07-17, the Kybar's Teeth region pass. A Magi's only
// way to leave play in this engine is defeat (there's no separate "Magi discarded from play" path)
// -- confirmed no other precedent maps a Magi's "discarded from play" text to anything but
// `onOwnMagiDefeated`, checked right when Wessig herself is defeated. No "your"/"opposing" qualifier
// on the printed text -- read as affecting EVERY player's board (both sides), same established
// convention as Bone Cragnoc's "largest Creature, either side" and Sagawal's own region-agnostic
// wording elsewhere in this pass.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Wessig', {
  onOwnMagiDefeated: (state, cardDb, self, magi, rng) => {
    for (const player of state.players.values()) {
      const toDiscard = player.inPlay.filter((c) => {
        const def = cardDb.get(c.definitionKey);
        return def && (def.card_type === 'Creature' || def.card_type === 'Relic') && !def.regions.includes("Kybar's Teeth");
      });
      for (const card of toDiscard) {
        discardFromPlay(state, cardDb, player, card.instanceId, undefined, undefined, rng);
      }
    }
  },
});
