// Snare (Spell, Paradwyn, cost 1) -- "Play Snare at the beginning of an opponent's Attack step.
// Choose one of that player's Creatures. The chosen Creature cannot attack this turn. If your Magi
// is not Paradwyn, discard a card from your hand."
//
// Play window: the new GameState.reactiveWindow kind 'opponentAttackStepBegan' (own doc comment in
// types/state.ts), opened by turn.ts#runAttackStepStart on entering the Attack step. That rides the
// existing generic reactsToWindow + Play.tsx checkReactiveWindow plumbing -- no new prompt UI. It
// is deliberately NOT the beginAttack pre-declareAttack checkpoint Tropical Rain uses: that fires
// per attack, once an attacker and defender are already chosen, which is strictly too late for
// "cannot attack this turn" to stop the attack being declared in the first place.
//
// Effect: the existing CANNOT_ATTACK duration tag, checked generically by combat.ts's isLegalAttack
// -- no new combat plumbing needed. Tagged for state.turnNumber (the CURRENT turn, i.e. the
// opponent's), matching "this turn" and the Abaquist/Agram precedent.
//
// Conditional discard: the new HandDiscardCostShape.condition (registry.ts) -- Snare is the only
// card in the database whose printed text conditions the discard ITSELF rather than which cards may
// pay it, so the sub-cost simply doesn't apply when the caster's Magi is Paradwyn (no prompt, no
// discard). Read through effectiveMagiDef so a region-overridden/Shadow Magi is judged by its
// CURRENT identity, not its printed one.

import { registerCardEffect } from './registry.js';
import { discardFromHand, checkHandEmptied } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { effectiveMagiDef } from '../regions.js';
import { regionForTargetFilter } from '../targeting.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState, PlayerId } from '../types/state.js';

/** True when the player's active Magi is NOT Paradwyn (the case that costs a hand card). A player
 *  with no active Magi at all counts as "not Paradwyn" -- the conservative reading. */
function magiIsNotParadwyn(state: GameState, cardDb: CardDatabase, playerId: PlayerId): boolean {
  const magi = state.players.get(playerId)?.activeMagi;
  if (!magi) return true;
  const def = cardDb.get(magi.definitionKey);
  if (!def) return true;
  return !effectiveMagiDef(def, magi).regions.includes(regionForTargetFilter(state, 'Paradwyn'));
}

registerCardEffect('Snare', {
  reactsToWindow: (state, cardDb, window) => window.kind === 'opponentAttackStepBegan',
  // "one of THAT PLAYER's Creatures" -- the active player whose Attack step just began. Derived
  // from the live window rather than getOpponents so the pool can never disagree with the window
  // that legalized the play.
  spellTargets: (state, cardDb, playerId) => {
    const window = state.reactiveWindow;
    const targetPlayerId = window?.kind === 'opponentAttackStepBegan' ? window.actingPlayerId : undefined;
    if (targetPlayerId === undefined || targetPlayerId === playerId) return [];
    return [...(state.players.get(targetPlayerId)?.inPlay ?? [])];
  },
  spellHandDiscardCost: { count: 1, condition: magiIsNotParadwyn },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const window = ctx.state.reactiveWindow;
    const targetPlayerId = window?.kind === 'opponentAttackStepBegan' ? window.actingPlayerId : undefined;
    if (targetPlayerId === undefined || targetPlayerId === ctx.controllingPlayer.playerId) return;
    const target = ctx.state.players.get(targetPlayerId)?.inPlay.find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);

    // Re-validated at resolution (state can change between UI collection and resolution), same
    // trust model every other spellHandDiscardCost user uses.
    if (magiIsNotParadwyn(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      const ids = ctx.chosenHandCardIds ?? [];
      if (ids.length === 1) discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids, undefined, ctx.rng);
      checkHandEmptied(ctx.state, ctx.cardDb, ctx.rng);
    }
  },
});
