// Aerial Flist -- both printed clauses:
//   "Charge: Whenever Aerial Flist attacks, add one energy to it before energy is removed."
//   "Dreamwarp: As you play Aerial Flist, increase or decrease its starting energy by one, until
//   the end of the turn." (registry.ts's dreamwarpRange -- play.ts's playCard consults this
//   directly, no resolvePower/onPlay body needed here.)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Aerial Flist', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Charge is the +1 on any attack;
  // Dreamwarp travels as the `dreamwarpRange` data field per Q4 sum ruling (see targeting.ts's
  // effectiveDreamwarpRange). No shared hooks -- either Effect narrows cleanly.
  effectHooks: {
    Charge: ['onBeforeEnergyRemoved'],
    Dreamwarp: ['dreamwarpRange'],
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    addEnergy(ctx.state, ctx.cardDb, self, 1, 'effect');
  },
  dreamwarpRange: () => 1,
});
