// Shadow Dryte -- "Descendance: After Shadow Dryte defeats a Creature while attacking, add four
// energy to Shadow Dryte." Post-combat outcome -> afterCombat, same shape as many already-shipped
// "after defeats X, gain Y" readers.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Shadow Dryte', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (!ctx.defender) return; // "a Creature" -- not a direct Magi attack
    if (outcome.defenderSurvived) return;
    addEnergy(ctx.state, ctx.cardDb, self, 4, 'effect');
  },
});
