// Nagsis' Sigil -- "Purity: At the end of your turn, if all Spells in your discard pile are
// Core, discard each of your non-Core cards from play and choose any Magi. Move up to two energy
// from the chosen Magi to your Magi."
//
// Real choice (Phase 4c, 2026-07-11): "choose any Magi" doesn't say whose -- replaces the earlier
// "prefers the opposing Magi" simplification with a real pending choice (registry.ts's
// pendingTargetChoice/resolveTargetChoice) over every Magi in play (including the controller's
// own, matching the printed text's lack of a qualifier).

import { registerCardEffect } from './registry.js';
import { applyPurity } from './purityRing.js';
import { rearrangeEnergy } from '../effects.js';
import { allMagiInPlay } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const PURITY_PENDING = 'nagsisSigilPurityPending';

registerCardEffect("Nagsis' Sigil", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, 'Core', rng)) return;
    const player = state.players.get(self.controllerId);
    if (!player?.activeMagi) return;
    if (allMagiInPlay(state).filter((m) => (m.currentEnergy ?? 0) > 0).length === 0) return;
    addPendingChoiceTag(self, PURITY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(PURITY_PENDING)) return undefined;
    const pool = allMagiInPlay(state).filter((m) => (m.currentEnergy ?? 0) > 0);
    if (pool.length === 0) return undefined;
    return { prompt: "Nagsis' Sigil's Purity: choose a Magi to move up to 2 energy from to your Magi", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, PURITY_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player?.activeMagi) return;
    const target = allMagiInPlay(state).find((m) => m.instanceId === chosenInstanceId);
    if (!target) return;
    const amount = Math.min(2, target.currentEnergy ?? 0);
    if (amount > 0) rearrangeEnergy(state, cardDb, target, player.activeMagi, amount, rng);
  },
});
