// Crag Quor -- "Rebound" and "Invulnerability" are built here:
//   "At the beginning of your turn, if Crag Quor is smaller than the smallest opposing Creature in
//   play, add four energy to Crag Quor."
//   "Invulnerability: Crag Quor loses one less energy in attacks." (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { opposingCreatures, smallestOf } from '../targeting.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Crag Quor', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Rebound owns onOwnTurnStart,
  // Invulnerability owns onAttack.
  effectHooks: {
    Rebound: ['onOwnTurnStart'],
    Invulnerability: ['onAttack'],
  },
  onOwnTurnStart: (state, cardDb, self) => {
    const smallestOpposing = smallestOf(opposingCreatures(state, cardDb, self.controllerId));
    if (!smallestOpposing) return;
    if ((self.currentEnergy ?? 0) >= (smallestOpposing.currentEnergy ?? 0)) return;
    addEnergy(state, cardDb, self, 4, 'effect');
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
});
