// Harvest Feast (Spell, cost 3) -- "Choose up to three Naroom Creatures. Add two energy to each of
// them." Naroom Spell pass, Category B (2026-07-23). registry.ts's spellMultiTargets (Topple's own
// "any number of" precedent) offers the full Naroom-Creature pool; since no existing multi-target
// picker enforces an upper bound, the "up to three" cap is applied defensively in resolveSpell
// (first three chosen ids) -- documented simplification, same "trust but verify" re-clamp shape
// every other pre-collected choice on this type already uses.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions, findInPlayById } from '../targeting.js';

const MAX_CHOSEN = 3;

registerCardEffect('Harvest Feast', {
  spellMultiTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes('Naroom')),
  resolveSpell: (ctx) => {
    const ids = (ctx.chosenMultiTargetIds ?? []).slice(0, MAX_CHOSEN);
    for (const id of ids) {
      const target = findInPlayById(ctx.state, id);
      if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') continue;
      if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes('Naroom')) continue;
      addEnergy(ctx.state, ctx.cardDb, target, 2, 'spell');
    }
  },
});
