// Amara -- top-level text: "Amara may play Kybar's Teeth Spells, ignoring regional penalties." --
// registry.ts's `regionOverride`, same shape as Urhail's Tainted Dreams (Core Spells instead of
// Kybar's Teeth).
//
// "Soothing Song: After a Spell is played, choose a Creature and add one energy to it." -- NOT a
// new mechanism after all (originally deferred as one): same onPlay-broadcast + pendingTargetChoice/
// resolveTargetChoice shape Caboodle Kit's Celestial Memory already uses (Phase 4c, task #42's
// playtest caught this precedent when Celestial Memory itself turned out to be already built).
// Unlike Celestial Memory (a SELF-trigger only) or Caboodle Kit's own Curious (a "you played"
// broadcast), Soothing Song has no "you" qualifier -- it reacts to ANY player's Spell, not just
// Amara's controller's own.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { allCreaturesInPlay } from '../targeting.js';

const SOOTHING_SONG_PENDING = 'amaraSoothingSongPending';

registerCardEffect('Amara', {
  regionOverride: (state, cardDb, playedDef) =>
    playedDef.card_type === 'Spell' && playedDef.regions.includes("Kybar's Teeth"),
  onPlay: (state, cardDb, played, self) => {
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Spell') return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, SOOTHING_SONG_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SOOTHING_SONG_PENDING)) return undefined;
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Amara's Soothing Song: choose a Creature to add one energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, SOOTHING_SONG_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) addEnergy(state, cardDb, target, 1, 'effect');
  },
});
