// Moga Fang Necklace -- two Effects:
//   Unnamed: "At the end of your Attack Step, if you attacked with any Creatures this turn,
//   discard all of your Creatures and Relics from play."
//   Roar (task #714, 2026-08-11, Category C deferred-gap closure pass): "At the beginning of your
//   Attack Step, roll a die. Until the end of your turn, whenever one of your Creatures attacks,
//   it gains energy equal to the die roll, before energy is removed."
//
// Roar needed two things that didn't exist yet: a "beginning of Attack Step" trigger point
// (registry.ts's new onOwnAttackStepBegin, the opposite-boundary sibling of onOwnAttackStepEnd,
// which this card's own OTHER clause already uses) and somewhere to remember the rolled value for
// the rest of the turn -- solved with the existing generic per-instance counters field
// (effects.ts's setCounter/getCounter) rather than a new mechanism, since duration tags carry only
// a tag name, not a value. The "until the end of your turn" window itself is the same
// addDurationTag(self, TAG, state.turnNumber) shape Swamp Moga's Roar already uses (auto-expires
// via the existing sweepExpiredDurationTags at the start of the turn after). Once armed, the
// energy gain itself is a plain onBeforeEnergyRemoved bonus (Storm Ring's own precedent) rather
// than a grantsAttackEnergyBonusTo grant -- that hook is for bonus DAMAGE dealt to the DEFENDER,
// not energy gained by the attacker itself.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay, requestDieRoll, setCounter, getCounter } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { inPlayControlledBy } from '../targeting.js';
import { addDurationTag, hasDurationTag, MOGA_FANG_NECKLACE_ROAR_ACTIVE } from '../durationTags.js';

const ROAR_AMOUNT_COUNTER = 'mogaFangNecklaceRoarAmount';

registerCardEffect('Moga Fang Necklace', {
  onOwnAttackStepBegin: (state, cardDb, self, rng) => {
    requestDieRoll(state, cardDb, self, self.controllerId, 6, 'mogaFangNecklace:roar', {}, rng);
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (!hasDurationTag(self, MOGA_FANG_NECKLACE_ROAR_ACTIVE)) return;
    const amount = getCounter(self, ROAR_AMOUNT_COUNTER);
    if (amount > 0) addEnergy(ctx.state, ctx.cardDb, ctx.attacker, amount, 'effect');
  },
  onOwnAttackStepEnd: (state, cardDb, self, rng) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const attackedThisTurn = player.inPlay.some((c) => c.attackedThisTurn);
    if (!attackedThisTurn) return;

    const toDiscard = inPlayControlledBy(state, self.controllerId).filter((c) => {
      const type = cardDb.get(c.definitionKey)?.card_type;
      return type === 'Creature' || type === 'Relic';
    });
    for (const card of toDiscard) {
      discardFromPlay(state, cardDb, player, card.instanceId, undefined, undefined, rng);
    }
  },
});

registerRollConsumer('mogaFangNecklace:roar', (state, cardDb, source, _payload, finalRoll) => {
  if (!source) return;
  setCounter(source, ROAR_AMOUNT_COUNTER, finalRoll);
  addDurationTag(state, cardDb, source, MOGA_FANG_NECKLACE_ROAR_ACTIVE, state.turnNumber);
});
