// Forest Jile -- "Reinforce (2): Add two energy to each of your Creatures that attacked this
// turn."

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Forest Jile', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Reinforce') return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      if (creature.attackedThisTurn) addEnergy(ctx.state, ctx.cardDb, creature, 2, 'power');
    }
  },
});
