// N'kala -- both printed clauses:
//   "Support: Add one energy to your Magi." Free, no target.
//   "Dreamwarp: As you play N'kala, increase or decrease its starting energy by up to one, until
//   the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect("N'kala", {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Support') return;
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return; // possible mid-turn if the Magi was just defeated (succession isn't until next turn)
    addEnergy(ctx.state, ctx.cardDb, magi, 1, 'power');
  },
  dreamwarpRange: () => 1,
});
