// Trulbble! (Spell) -- "Discard up to four Trulbs you control from play. Draw two cards for each
// Trulb you discarded." Bograth Spell pass, Category B2 (2026-07-20). creatureType(cardDb,
// definitionKey) (targeting.ts) is the exact filter for "Trulbs you control" (matches any Creature
// whose name's last word is "Trulb," not just the plain card named "Trulb"). The "up to N of my own
// cards" pick reuses the existing GENERIC pendingMultiTargetChoice/resolveMultiTargetChoice family
// (registry.ts, proven by Ballistic Baldar/Cloud Orshaa/Weave Mat, not hook-restricted to Powers) as
// a post-resolveSpell follow-up, same idiom as Muck Rain's second pick in this same pass. Trulbble!
// itself is already sitting in the discard pile by the time the pending choice fires (a Spell
// resolves once and moves there immediately), but the permanent tag marking it survives the zone
// move, and pendingMultiTargetChoice's own 5-zone scan finds it there. drawCards() x
// discardedCount closes it out.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, creatureType } from '../targeting.js';
import { discardFromPlay, drawCards } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING_CHOICE = 'trulbbleAwaitingChoice';

function ownTrulbs(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  return creaturesControlledBy(state, cardDb, self.controllerId).filter((c) => creatureType(cardDb, c.definitionKey) === 'Trulb');
}

registerCardEffect('Trulbble!', {
  resolveSpell: (ctx) => {
    if (ownTrulbs(ctx.state, ctx.cardDb, ctx.source).length === 0) return;
    addPendingChoiceTag(ctx.source, AWAITING_CHOICE);
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const pool = ownTrulbs(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return {
      prompt: 'Trulbble!: discard up to four Trulbs you control from play (draw two cards for each discarded)',
      pool: pool.map((c) => c.instanceId),
      minCount: 0,
      maxCount: Math.min(4, pool.length),
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds, rng) => {
    removePermanentTag(self, AWAITING_CHOICE);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const pool = ownTrulbs(state, cardDb, self);
    const poolIds = new Set(pool.map((c) => c.instanceId));

    let chosen: string[];
    if (chosenInstanceIds) {
      chosen = [...new Set(chosenInstanceIds)].filter((id) => poolIds.has(id)).slice(0, 4);
    } else {
      chosen = pool.slice(0, 4).map((c) => c.instanceId);
    }

    for (const id of chosen) {
      discardFromPlay(state, cardDb, player, id, undefined, undefined, rng);
    }
    if (chosen.length > 0) {
      drawCards(state, cardDb, player, chosen.length * 2);
    }
  },
});
