// Xamf -- "Windchill: At the beginning of your turn, if your smallest Creature in play is larger
// than the largest opposing Creature in play, add four energy to your Magi." (Printed text has a
// typo, "add for energy" -- read as "four," matching every other numeric grant of this shape.)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, opposingCreatures, smallestOf } from '../targeting.js';

registerCardEffect('Xamf', {
  onOwnTurnStart: (state, cardDb, self) => {
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    const smallestOwn = smallestOf(own);
    const opposing = opposingCreatures(state, cardDb, self.controllerId);
    if (opposing.length === 0 || !smallestOwn) return;
    const largestOpposing = opposing.reduce((best, c) => ((c.currentEnergy ?? 0) > (best.currentEnergy ?? 0) ? c : best));
    if ((smallestOwn.currentEnergy ?? 0) <= (largestOpposing.currentEnergy ?? 0)) return;

    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (magi) addEnergy(state, cardDb, magi, 4, 'effect');
  },
});
