// Stored, possibly-expiring numeric adjustments to a card's Energize rate (Tree Hinko's one-shot
// "next energize +2," Yayek's "+N until the end of your turn," Agram's permanent ratcheting
// "+1 every time he energizes") -- see the EnergizeModifier doc comment (types/instance.ts) for
// the data shape, and turn.ts's effectiveEnergizeRate for how these combine with printed
// def.energize and registry.ts's energizeRateModifier hook (continuous/conditional modifiers,
// e.g. Water of Life's flat +1 while in play) into a single per-energize total.

import type { CardInstance, EnergizeModifier } from './types/instance.js';
import type { GameState } from './types/state.js';

/** Adds a stored energize-rate modifier to `instance`, with an optional turn-number expiry
 *  and/or one-shot (consumed the next time this card actually energizes) behavior. */
export function addEnergizeModifier(
  instance: CardInstance,
  amount: number,
  options?: { expiresAfterTurnNumber?: number; oneShot?: boolean; isGrant?: boolean }
): void {
  instance.energizeModifiers.push({
    amount,
    expiresAfterTurnNumber: options?.expiresAfterTurnNumber,
    oneShot: options?.oneShot,
    isGrant: options?.isGrant,
  });
}

/** True if `mod` hasn't expired yet by turn number. One-shot modifiers stay active until
 *  explicitly consumed by consumeOneShotEnergizeModifiers, regardless of turn number. */
export function isEnergizeModifierActive(state: GameState, mod: EnergizeModifier): boolean {
  if (mod.expiresAfterTurnNumber !== undefined && state.turnNumber > mod.expiresAfterTurnNumber) {
    return false;
  }
  return true;
}

/** Every currently-active stored energize modifier on `instance`, filtering out expired ones. */
export function activeEnergizeModifiers(state: GameState, instance: CardInstance): EnergizeModifier[] {
  return instance.energizeModifiers.filter((mod) => isEnergizeModifierActive(state, mod));
}

/** Removes any one-shot modifiers from `instance` -- called right after this card actually
 *  energizes, so a "next energize +2" effect applies exactly once. */
export function consumeOneShotEnergizeModifiers(instance: CardInstance): void {
  instance.energizeModifiers = instance.energizeModifiers.filter((mod) => !mod.oneShot);
}
