// Naran Lights (Spell) -- "Reveal the top three cards of your deck. You may choose one revealed
// Arctic Creature and play it with five energy, ignoring all costs and place the remaining cards
// at the bottom of your deck in any order. If you did not reveal a creature this way, place the
// cards into your hand instead." Nar Spell pass, Category C (2026-07-22). No new mechanism needed
// -- reuses the plain spellTargets/chosenTargetId plumbing (the pool IS "the top three cards of
// your deck, filtered to Arctic Creatures," computed live from player.deck; "you MAY choose" maps
// onto chosenTargetId being optional, same as every other optional-target Spell). The actual
// deck->play move is effects.ts's searchDeckIntoPlay (Grubble's Dreamform's own precedent: "play
// that Creature with [energy], ignoring all costs" is exactly what that primitive already does).
// "any order" for the bottom-of-deck placement is auto-resolved (same simplification this project
// applies to every other "in any order" clause with no gameplay-relevant distinction) -- there's no
// existing UI affordance for re-ordering a small revealed set, and the two orderings are otherwise
// equivalent (both cards are equally hidden at the bottom either way).

import { registerCardEffect } from './registry.js';
import { searchDeckIntoPlay } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';
import { addToZone } from '../zones.js';
import { effectiveCardType } from '../targeting.js';

registerCardEffect('Naran Lights', {
  spellTargets: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player) return [];
    return player.deck
      .slice(0, 3)
      .filter((c) => cardDb.get(c.definitionKey)?.subtype === 'Arctic' && effectiveCardType(cardDb, c) === 'Creature');
  },
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    const revealed = player.deck.slice(0, 3);
    const chosen = ctx.chosenTargetId ? revealed.find((c) => c.instanceId === ctx.chosenTargetId) : undefined;
    if (chosen) {
      searchDeckIntoPlay(ctx.state, ctx.cardDb, player, chosen.instanceId, 5, true, ctx.rng);
      for (const card of revealed) {
        if (card.instanceId === chosen.instanceId) continue;
        const index = player.deck.findIndex((c) => c.instanceId === card.instanceId);
        if (index !== -1) {
          const [removed] = player.deck.splice(index, 1);
          addToZone(player, 'deck', removed!, 'bottom');
        }
      }
      checkCreatureDefeats(ctx.state, ctx.cardDb);
    } else {
      for (const card of revealed) {
        const index = player.deck.findIndex((c) => c.instanceId === card.instanceId);
        if (index !== -1) {
          const [removed] = player.deck.splice(index, 1);
          addToZone(player, 'hand', removed!);
        }
      }
    }
  },
});
