// Diobor -- two Powers.
// "Fireball: Choose any one Creature in play. Discard Diobor from play. Remove two energy from
// the chosen Creature."
// "Energy Transfer: Move up to six energy from Diobor to your Magi." Needs no target at all --
// powerTargets returns undefined for it specifically (registry.ts's powerTargets doc comment), so
// the UI doesn't wrongly ask for one. Originally printed/scraped as an X-cost Power ("Add X Energy
// to your Magi"), officially errata'd (data-pipeline/output/rulings.json, applied 2026-07-09) into
// a flat "move up to six" statement with NO player-chosen X at all -- the power's own `cost` field
// was hand-corrected from 'X' to 0 to match (see cards_final.json's `errata.cost_note` on this
// entry), and this now uses rearrangeEnergy (a capped MOVE, draining Diobor) instead of addEnergy
// (which conjured energy from nowhere). Previously Energy Transfer had no branch in resolvePower at
// all -- cost was paid but nothing happened, a silent fizzle caught auditing for the same bug class
// as Thunder Hyren's Replenish (PROGRESS_LOG.md, 2026-07-09).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, discardFromPlay, rearrangeEnergy } from '../effects.js';

registerCardEffect('Diobor', {
  powerAmountChoices: (state, cardDb, playerId, powerName, source) => {
    if (powerName !== 'Energy Transfer') return undefined;
    const max = Math.min(6, source.currentEnergy ?? 0);
    return [{ id: 'move', prompt: `Energy Transfer: move how much energy from Diobor to your Magi? (0-${max})`, min: 0, max }];
  },
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- Fireball only (it's the one
  // that discards energy); Energy Transfer needs no target at all, untouched.
  powerTargets: (state, cardDb, playerId, powerName) =>
    powerName === 'Fireball' ? flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)) : undefined,
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Fireball') {
      if (ctx.chosenTargetId === undefined) return;
      const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
      // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
      if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
      if (target.instanceId !== ctx.source.instanceId) {
        discardEnergy(ctx.state, ctx.cardDb, target, 2, undefined, undefined, ctx.rng);
      }
    } else if (ctx.powerName === 'Energy Transfer') {
      const magi = ctx.controllingPlayer.activeMagi;
      if (!magi) return;
  // Task #532 (2026-07-26): "up to N" is a PLAYER CHOICE of 0..N, not N. This used to hard-code the
  // maximum (playtest: Giant Arboll "automatically is moving the max energy instead of giving a
  // picker"). `?? cap` keeps the old max as the fallback when no amount was supplied, so the engine
  // half is safe on its own -- an absent choice behaves exactly as before rather than moving 0.
      const cap = Math.min(6, ctx.source.currentEnergy ?? 0);
      const amount = Math.max(0, Math.min(ctx.chosenAmounts?.['move'] ?? cap, cap));
      if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, ctx.source, magi, amount, ctx.rng);
    }
  },
});
