// Weave Powder -- "Sculpt: Discard Weave Powder from play. Search your deck for any one Weave
// Relic, show it to your opponent, and put it into your hand. You may not use Sculpt the turn you
// play Weave Powder." "Show it to your opponent" is cosmetic (knowledge-only).
//
// FIXED 2026-07-25 (playtest report: Sculpt was usable immediately). This file's prior comment said
// the restriction "needs a 'was this card played this turn' flag that doesn't exist yet" -- stale
// twice over: CardInstance.playedOnTurnNumber landed 2026-07-16 (Grim Goblet), and the CANNOT_USE_POWER
// duration tag used here predates even that. Tremor Stones and Bubble Xyx already carry this exact
// printed clause via `onPlay` + a self-applied CANNOT_USE_POWER expiring at the end of the turn it
// was played, which isLegalPowerUse checks generically -- so the Power's button is DISABLED with a
// reason rather than clickable-but-silently-dead. Reused verbatim here.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, searchDeck } from '../effects.js';
import { regionForTargetFilter } from '../targeting.js';
import { addDurationTag, CANNOT_USE_POWER } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Weave Powder', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    addRestrictionTag(state, self, CANNOT_USE_POWER, state.turnNumber);
  },
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Relic' && def.regions.includes(regionForTargetFilter(state, 'Weave'));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Sculpt') return;
    const ids = ctx.chosenDeckSearchIds ?? [];
    if (ids.length > 1) return;
    for (const id of ids) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
      if (!def || def.card_type !== 'Relic' || !def.regions.includes(regionForTargetFilter(ctx.state, 'Weave'))) return;
    }

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    searchDeck(ctx.state, ctx.controllingPlayer, ids, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Weave'],
});
