// Slarnath -- "Demand: If you have four or more Bograth Creatures in play, draw a card."
//
// Bograth-count-helper sweep (Bograth-cluster follow-up, 2026-07-21): now reads
// targeting.ts's effectiveBograthCreatureCount instead of a raw board count, so Bog Stench's
// virtual +2 and Emlob's +3 (neither previously applied here) can push it over the threshold.

import { registerCardEffect } from './registry.js';
import { effectiveBograthCreatureCount } from '../targeting.js';
import { drawCards } from '../effects.js';

registerCardEffect('Slarnath', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Demand') return;
    if (effectiveBograthCreatureCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId) >= 4) {
      drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    }
  },
});
