// Spell Pulse (Spell, Paradwyn, cost 2) -- "Choose either Spells or Relics. Discard all cards of
// the chosen card type from play." Category choice reuses spellCategoryChoice (Storm of Fishes
// precedent), but "from play" (not "from hand") needs its own sweep, since most Spells in this
// engine resolve straight to the discard pile and were never "in play" to begin with. "Spells...
// in play" only ever means the small set of Spells that opt into `registry.ts`'s
// `spellStaysInPlay` (Shadow Geysers, Overgrowth, Crystallize, Sunburn, Volt Shield, etc) -- these
// sit in one of TWO places depending on how their own resolveSpell placed them: directly in
// `player.inPlay` (most of them), or attached to a holder's `attachedCards` (Sunburn/Volt
// Shield/Scarletsong Lilt's own precedent -- confirmed via `attachCard`'s own doc comment: attached
// cards are a genuinely separate zone from `inPlay`). Both are swept. No owner qualifier in the
// printed text -- applies to every card of the chosen type on BOTH sides, same symmetric shape as
// Storm of Fishes' own hand sweep.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { detachCard } from '../attachedCards.js';
import { moveToDiscardPile } from '../zones.js';

registerCardEffect('Spell Pulse', {
  spellCategoryChoice: {
    prompt: 'Choose Spells or Relics -- all cards of that type are discarded from play',
    options: () => ['Spell', 'Relic'],
  },
  resolveSpell: (ctx) => {
    const category = ctx.chosenCategory;
    if (category !== 'Spell' && category !== 'Relic') return;
    const { state, cardDb } = ctx;

    for (const player of state.players.values()) {
      const ids = player.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === category).map((c) => c.instanceId);
      for (const id of ids) discardFromPlay(state, cardDb, player, id, undefined, 'spell', ctx.rng);
    }

    if (category === 'Spell') {
      for (const player of state.players.values()) {
        const holders: typeof player.inPlay = player.activeMagi ? [...player.inPlay, player.activeMagi] : [...player.inPlay];
        for (const holder of holders) {
          const attachedSpellIds = holder.attachedCards.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Spell').map((c) => c.instanceId);
          for (const id of attachedSpellIds) {
            const detached = detachCard(holder, id);
            if (!detached) continue;
            const owner = state.players.get(detached.ownerId);
            if (owner) moveToDiscardPile(state, owner, detached);
          }
        }
      }
    }
  },
});
