// Trogovo -- two clauses. Built task #48, 2026-07-18, the Underneath region pass.
//   "Inspire: Draw two additional cards during your Draw step. Reduce your Magi's Energize by two."
//   (Category A) -> `drawCountModifier` (+2, consulted only for the drawing player's own board) +
//   `energizeRateModifier` (-2 when Trogovo's own controller's Magi energizes). Both existing hooks.
//   "Frightened: At the beginning of your turn, any Core Magi may discard three energy to discard
//   Trogovo." (Category B) -> the Dreamdrain Charm pattern (`onOwnTurnStart` arms a
//   `pendingYesNoChoice`; task #43). Fires at Trogovo's controller's turn start; armed only when an
//   opposing Core Magi in play can actually pay 3. On "yes" that Magi discards 3 and Trogovo is
//   discarded from play. Documented simplification: the deciding party is really the opposing Core
//   Magi's controller, but this single-UI engine surfaces the pendingYesNoChoice during Trogovo's
//   controller's own turn (same "whose turn drives the prompt" shape Dreamdrain Charm uses); the
//   mechanic itself -- an opponent MAY spend 3 to kill Trogovo at the start of your turn -- is exact.

// Ashio's Weave Twist (2026-07-24): "Core" in Frightened above is Trogovo's OWN printed text, so
// under Ashio it means its own region (Underneath) instead -- see targeting.ts's
// ashioAdjustedRegion doc comment.

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { ashioAdjustedRegion } from '../targeting.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const FRIGHTENED_PENDING = 'trogovoFrightenedPending';

/** An opposing Core Magi in play with at least 3 energy to spend, or undefined. */
function payingCoreMagi(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance | undefined {
  for (const player of state.players.values()) {
    const magi = player.activeMagi;
    if (!magi || magi.controllerId === self.controllerId) continue; // "any Core Magi" -- the opposing one
    const def = cardDb.get(magi.definitionKey);
    if (def?.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Underneath'])) && (magi.currentEnergy ?? 0) >= 3) return magi;
  }
  return undefined;
}

registerCardEffect('Trogovo', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Inspire owns drawCountModifier +
  // energizeRateModifier (both data-field hooks per Q4). Frightened owns the turn-start
  // pending-yes/no arm-and-resolve trio.
  effectHooks: {
    Inspire: ['drawCountModifier', 'energizeRateModifier'],
    Frightened: ['onOwnTurnStart', 'pendingYesNoChoice', 'resolveYesNoChoice'],
  },
  drawCountModifier: () => 2, // "draw two ADDITIONAL cards" -- consulted only for the drawing player's own contributors
  energizeRateModifier: (state, cardDb, energizing, self) =>
    energizing.controllerId === self.controllerId && cardDb.get(energizing.definitionKey)?.card_type === 'Magi'
      ? -2
      : 0,
  onOwnTurnStart: (state, cardDb, self) => {
    removePermanentTag(self, FRIGHTENED_PENDING);
    if (payingCoreMagi(state, cardDb, self)) addPendingChoiceTag(self, FRIGHTENED_PENDING);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(FRIGHTENED_PENDING)) return undefined;
    if (!payingCoreMagi(state, cardDb, self)) return undefined; // re-verify it's still payable
    return {
      prompt: "Trogovo's Frightened: a Core Magi may discard 3 energy to discard Trogovo. Do it?",
      yesLabel: 'Pay 3, discard Trogovo',
      noLabel: 'Leave Trogovo alone',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, FRIGHTENED_PENDING);
    if (!chosenBoolean) return;
    const magi = payingCoreMagi(state, cardDb, self);
    if (!magi) return;
    discardEnergy(state, cardDb, magi, 3, 'effect', magi.controllerId, rng);
    const owner = state.players.get(self.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
  },
});
