// Dryte -- "Snowball: The first time each turn that Dryte attacks a frozen Creature, add three
// energy to Dryte after energy is removed and it can immediately attack a second Creature."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { isFrozen, hasDurationTag, addDurationTag } from '../durationTags.js';

const USED_THIS_TURN = 'dryteSnowballUsedThisTurn';

registerCardEffect('Dryte', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (!ctx.defender || !isFrozen(ctx.state, ctx.cardDb, ctx.defender)) return;
    if (hasDurationTag(self, USED_THIS_TURN)) return;
    addDurationTag(ctx.state, ctx.cardDb, self, USED_THIS_TURN, ctx.state.turnNumber);
    addEnergy(ctx.state, ctx.cardDb, self, 3, 'effect');
    self.oneShotBonusAttacks += 1;
  },
});
