// Sea Barl -- "Lore (3): Draw two cards." Fixed cost, no target.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Sea Barl', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Lore') return;
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 2);
  },
});
