// Orothean Goggles -- "Foresight: Look at the top two cards of your deck. You may discard either
// or both of these cards, or put them back on top of your deck in any order." Chosen cards ->
// discard pile (effects.ts's discardFromDeck); UNCHOSEN cards are simply left alone -- since only
// the chosen ones are removed from the top of the deck, the rest naturally stay on top in their
// original relative order, which is the documented simplification of the "any order" choice (see
// deckTopReveal's doc comment).

import { registerCardEffect } from './registry.js';
import { discardFromDeck } from '../effects.js';

registerCardEffect('Orothean Goggles', {
  deckTopReveal: { count: 2 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Foresight') return;
    const ids = ctx.chosenDeckTopIds ?? [];
    if (ids.length === 0) return;
    const top = ctx.controllingPlayer.deck.slice(0, 2).map((c) => c.instanceId);
    const validIds = ids.filter((id) => top.includes(id));
    if (validIds.length === 0) return;
    discardFromDeck(ctx.state, ctx.controllingPlayer, validIds);
  },
});
