// Kwup -- "Fear (1): Choose any one stalked Creature. Discard three energy from the chosen
// Creature." Pure reuse of durationTags.ts's STALKED tag, built for Tropical Vinoc.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { hasDurationTag, STALKED } from '../durationTags.js';

registerCardEffect('Kwup', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn. STALKED is a Creature-only tag
  // (durationTags.ts), so a Crown-granted Magi option is never actually stalked -- but the filter
  // still runs on the widened pool for consistency; a Magi would just never pass it, harmlessly.
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)).filter((c) =>
      hasDurationTag(c, STALKED)
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Fear') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead --
    // but STALKED (durationTags.ts) is only ever applied to Creatures in this engine, so a Magi
    // would fail the hasDurationTag check below regardless, same "harmless, never actually
    // reachable" note as the pool filter above.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (!hasDurationTag(target, STALKED)) return;

    discardEnergy(ctx.state, ctx.cardDb, target, 3, undefined, undefined, ctx.rng);
  },
});
