// Storm Wings -- Power "All-Out: Whenever one of your Creatures attacks this turn, it removes
// twice as much energy as it would normally. At the end of your Attack step, discard Storm Wings
// and each of your Creatures that attacked this turn." First card using the new
// attackEnergyMultiplier counter (types/instance.ts) for the doubling half -- a blanket grant
// over the current board, same "snapshot at resolve time" shape as Swamp Moga's Roar (a Creature
// played AFTER All-Out is used won't retroactively gain the doubling, a documented
// simplification). The discard clause (2026-07-10) now uses onOwnAttackStepEnd (built for
// Porphin, didn't exist when this file was first written).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const ALL_OUT_USED_THIS_TURN = 'stormWingsAllOutUsedThisTurn';

registerCardEffect('Storm Wings', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'All-Out') return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      creature.attackEnergyMultiplier *= 2;
    }
    addDurationTag(ctx.state, ctx.cardDb, ctx.source, ALL_OUT_USED_THIS_TURN, ctx.state.turnNumber);
  },
  // Discarding self + attacked Creatures is a CONSEQUENCE of activating All-Out this turn, not an
  // unconditional passive -- without this guard, an unused Storm Wings sitting inertly in play
  // would discard itself at the end of every single Attack Step, a real bug caught by the Kayliel
  // succession test (an unrelated filler Relic that had never had its Power used).
  onOwnAttackStepEnd: (state, cardDb, self, rng) => {
    if (!hasDurationTag(self, ALL_OUT_USED_THIS_TURN)) return;
    const player = state.players.get(self.controllerId);
    if (!player || !player.inPlay.some((c) => c.instanceId === self.instanceId)) return;
    const attackedCreatures = creaturesControlledBy(state, cardDb, self.controllerId).filter((c) => c.attackedThisTurn);
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
    for (const creature of attackedCreatures) {
      discardFromPlay(state, cardDb, player, creature.instanceId, undefined, undefined, rng);
    }
  },
});
