// Agovo -- "Lore (2): Draw one card." Fixed cost, no target. Same effect shape as Rayje's
// Construct's Lore, but a distinct card -- the registry is keyed by exact card name, so each
// needs its own (tiny) registration.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Agovo', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Lore') return;
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
  },
});
