// Dream Rift (Spell, Core, cost 5) -- "Take all Creature cards from your discard pile and shuffle
// them into your decK. Draw three cards. Arderial Magi may play Dream Rift." Task #53-4, 2026-07-21,
// the Core Spell pass's A1 quick wins.
//
// Bulk discard-pile retrieval + a single shuffle at the end (not per-card via
// effects.ts's retrieveFromDiscardPile, which shuffles once EACH call -- fine for a single-card
// retrieval like Nashiq/Delia, wasteful and semantically odd for "take ALL of them"), then a plain
// `drawCards(3)`.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { shuffleDeck } from '../zones.js';

registerCardEffect('Dream Rift', {
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    const creatures = player.discardPile.filter((c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature');
    if (creatures.length > 0) {
      const ids = new Set(creatures.map((c) => c.instanceId));
      player.discardPile = player.discardPile.filter((c) => !ids.has(c.instanceId));
      player.deck.push(...creatures);
      shuffleDeck(player, ctx.rng);
    }
    drawCards(ctx.state, ctx.cardDb, player, 3);
  },
});
