// M'lady Iyori -- alternate identity from Iyori (a different card entirely -- iyori.ts's "Lost
// Wisdom" is a DE-set Weave Magi with a different cost/power; M'lady Iyori is the ND-set
// Paradwyn+Weave Magi built here, confirmed against cards_final.json keys 815 vs 1023, task #37).
//
// "Natural Selection: Use this Power only before your Attack Step (registry.ts's legalPhases).
// Discard one Creature from your hand. Choose any one player. The chosen player must discard one
// of his or her Creatures from play." Built task #37 (Paradwyn pass, 2026-07-17) -- same
// handDiscardCost + chosen-target shape as several existing Powers. "Choose any one player" +
// "the chosen player discards one of their Creatures" collapses to a single powerTargets pick of
// any Creature currently in play (the printed text names no chooser for WHICH Creature, and a
// player who owns zero Creatures is never a rational choice to begin with, so the two-step
// "pick a player, then that empty-handed player has nothing to discard" edge case never matters
// in practice) -- same simplification this codebase already applies elsewhere for
// player-vs-card-target ambiguity.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromHand, discardFromPlay } from '../effects.js';

registerCardEffect("M'lady Iyori", {
  legalPhases: ['prs1'],
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature',
  },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Natural Selection') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const ownIds = (ctx.chosenHandCardIds ?? []).filter((id) => ctx.controllingPlayer.hand.some((c) => c.instanceId === id));
    if (ownIds.length !== 1) return;
    const targetOwner = ctx.state.players.get(target.controllerId);
    if (!targetOwner) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ownIds, undefined, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, targetOwner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
