// Grax -- "Tendril (4): Choose any one Creature in play. Discard half of the chosen Creature's
// energy, rounded up."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Grax', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Tendril') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;

    discardEnergy(ctx.state, ctx.cardDb, target, Math.ceil((target.currentEnergy ?? 0) / 2), undefined, undefined, ctx.rng);
  },
});
