// Spray Narth -- "Congregate: As you play Spray Narth, if you have at least two Creatures in play,
// one of which is Arderial and another one of which is Orothe, ignore Spray Narth's cost. You can
// only play one Spray Narth in this way per turn. Healing Storm: Choose any one Creature or Magi
// and one of your Pharans in play. Move up to the chosen Pharan's printed starting energy from the
// Pharan to the chosen Creature or Magi. Move up to three energy from Spray Narth to the chosen
// Creature or Magi. Add three energy to the chosen Creature or Magi. Discard both the chosen
// Pharan and Spray Narth from play." Healing Storm's "up to three"/"printed starting energy" caps
// and the double-discard are official 2i Design errata (data-pipeline/output/rulings.json, applied
// to cards_final.json 2026-07-09). Congregate (region-audit follow-up, 2026-07-24) uses the new
// registry.ts selfCostOverride/onSelfCostOverrideConsumed pair -- a TRUE zero, board-state-
// conditional, once-per-turn (state.congregateUsedThisTurn). "One of which is Arderial and
// ANOTHER one of which is Orothe" requires two DISTINCT Creatures, not one dual-region Creature
// satisfying both roles alone -- checked below via `distinctPairPossible`.

import { registerCardEffect } from './registry.js';
import {
  allCreaturesInPlay,
  allMagiInPlay,
  creaturesControlledBy,
  effectiveRegions,
  findCreatureOrMagiById,
  findInPlayById,
  printedStartingEnergy,
} from '../targeting.js';
import { addEnergy, discardFromPlay, rearrangeEnergy } from '../effects.js';

registerCardEffect('Spray Narth', {
  selfCostOverride: (state, cardDb, playerId) => {
    if (state.congregateUsedThisTurn) return undefined;
    const own = creaturesControlledBy(state, cardDb, playerId);
    const arderialCreatures = own.filter((c) => effectiveRegions(state, cardDb, c).includes('Arderial'));
    const orotheCreatures = own.filter((c) => effectiveRegions(state, cardDb, c).includes('Orothe'));
    if (arderialCreatures.length === 0 || orotheCreatures.length === 0) return undefined;
    const distinctPairPossible =
      arderialCreatures.length > 1 || orotheCreatures.length > 1 || arderialCreatures[0]!.instanceId !== orotheCreatures[0]!.instanceId;
    return distinctPairPossible ? 0 : undefined;
  },
  onSelfCostOverrideConsumed: (state) => {
    state.congregateUsedThisTurn = true;
  },
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose a Creature or Magi',
      pool: (s, db) => [...allCreaturesInPlay(s, db), ...allMagiInPlay(s)],
      min: 1,
      max: 1,
    },
    {
      label: 'Choose one of your Pharans',
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid).filter((c) => db.get(c.definitionKey)?.name.includes('Pharan')),
      min: 1,
      max: 1,
    },
  ],
  // Task #532. ONLY the Spray Narth move is a choice: this card's Pharan clause reads "Move the
  // chosen Pharan's printed starting energy" -- an EXACT amount, no "up to". Cloud Narth's
  // otherwise-identical Healing Storm DOES say "up to" there, so the two cards differ and must not
  // be swept together.
  powerAmountChoices: (state, cardDb, playerId, powerName, source) => {
    if (powerName !== 'Healing Storm') return undefined;
    const max = Math.min(3, source.currentEnergy ?? 0);
    return [{ id: 'narthMove', prompt: `Healing Storm: move how much energy from Spray Narth? (0-${max})`, min: 0, max }];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Healing Storm') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const targetId = slots[0]?.[0];
    const pharanId = slots[1]?.[0];
    if (!targetId || !pharanId || targetId === pharanId) return;

    const target = findCreatureOrMagiById(ctx.state, targetId);
    if (!target) return;
    const pharan = findInPlayById(ctx.state, pharanId);
    if (!pharan || ctx.cardDb.get(pharan.definitionKey)?.card_type !== 'Creature') return;
    if (pharan.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!ctx.cardDb.get(pharan.definitionKey)?.name.includes('Pharan')) return;

    const pharanMoveAmount = Math.min(printedStartingEnergy(ctx.cardDb, pharan.definitionKey), pharan.currentEnergy ?? 0);
    rearrangeEnergy(ctx.state, ctx.cardDb, pharan, target, pharanMoveAmount, ctx.rng);
    const narthCap = Math.min(3, ctx.source.currentEnergy ?? 0);
    const narthMoveAmount = Math.max(0, Math.min(ctx.chosenAmounts?.['narthMove'] ?? narthCap, narthCap));
    if (narthMoveAmount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, ctx.source, target, narthMoveAmount, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, 3, 'power');
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, pharan.instanceId, undefined, undefined, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
  },
});
