// Rockslide Hyren -- both printed pieces:
//   "Crush: Discard Rockslide Hyren from play. Choose three opposing Creatures in play. An
//   opponent of your choice discards two energy from one of the chosen Creatures, four energy
//   from the second chosen Creature and eight energy from the third chosen Creature. Opposing
//   cards do not affect Crush when it is used and cannot alter the amount of energy discarded by
//   Crush." "Cannot be altered" means the BURROWED cap must NOT apply here, unlike the
//   overwhelming majority of energy loss in this codebase -- raw currentEnergy math is used
//   instead of effects.ts's discardEnergy specifically for that reason.
//   "Invulnerability: Rockslide Hyren loses one less energy in attacks." (invulnerability.ts)
//
// Real choice (task #40-2, 2026-07-17, player-choice-default retrofit, Group 2): "an opponent of
// your choice" assigning 2/4/8 to the three chosen Creatures is now two dependent
// `powerTargetSlots` (slots 1-2, `respondingPlayer: 'opponent'`) instead of an array-order
// auto-pick -- slot 1 picks which of the three chosen Creatures loses 2, slot 2 picks which of the
// REMAINING two loses 4 (pool filtered via `priorChoices` to exclude slot 1's pick, same dependent-
// pool shape as raskDeserter.ts), and the one Creature left unpicked by either takes the last
// amount (8) by elimination -- no third slot needed since there's no real choice left once two of
// three are assigned.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';
import { opposingCreatures } from '../targeting.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Rockslide Hyren', {
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose three opposing Creatures',
      pool: (s, db, pid) => opposingCreatures(s, db, pid),
      min: 3,
      max: 3,
    },
    {
      label: 'Opponent chooses which of the three loses two energy',
      pool: (s, db, pid, priorChoices) => {
        const chosenIds = priorChoices[0] ?? [];
        return opposingCreatures(s, db, pid).filter((c) => chosenIds.includes(c.instanceId));
      },
      min: (priorChoices) => (priorChoices[0]?.length === 3 ? 1 : 0),
      max: (priorChoices) => (priorChoices[0]?.length === 3 ? 1 : 0),
      respondingPlayer: 'opponent',
    },
    {
      label: 'Opponent chooses which of the remaining two loses four energy (the last loses eight)',
      pool: (s, db, pid, priorChoices) => {
        const chosenIds = priorChoices[0] ?? [];
        const twoEnergyId = priorChoices[1]?.[0];
        return opposingCreatures(s, db, pid).filter((c) => chosenIds.includes(c.instanceId) && c.instanceId !== twoEnergyId);
      },
      min: (priorChoices) => (priorChoices[0]?.length === 3 ? 1 : 0),
      max: (priorChoices) => (priorChoices[0]?.length === 3 ? 1 : 0),
      respondingPlayer: 'opponent',
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Crush') return;
    const chosenIds = ctx.chosenSlotIds?.[0] ?? [];
    if (chosenIds.length !== 3) return;
    const twoEnergyId = ctx.chosenSlotIds?.[1]?.[0];
    const fourEnergyId = ctx.chosenSlotIds?.[2]?.[0];
    if (!twoEnergyId || !fourEnergyId) return;
    const eightEnergyId = chosenIds.find((id) => id !== twoEnergyId && id !== fourEnergyId);
    if (!eightEnergyId) return;

    const pool = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    const assignments: Array<[string, number]> = [
      [twoEnergyId, 2],
      [fourEnergyId, 4],
      [eightEnergyId, 8],
    ];
    const targets = assignments.map(([id, amount]) => [pool.find((c) => c.instanceId === id), amount] as const);
    if (targets.some(([t]) => !t)) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    for (const [target, amount] of targets) {
      target!.currentEnergy = Math.max(0, (target!.currentEnergy ?? 0) - amount);
    }
    checkCreatureDefeats(ctx.state, ctx.cardDb, 'power', undefined, ctx.rng);
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
});
