// Fray -- "Big Chill: Whenever one of your frozen Creatures is in an attack, remove one energy
// from the opposing Magi before energy is removed." A third-party reactor -- Fray doesn't need to
// be part of the combat itself, just needs to control a frozen Creature on either side of it.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { getOpponents } from '../types/state.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Fray', {
  onAttack: (ctx, self) => {
    const ownFrozenInvolved =
      (ctx.attacker.controllerId === self.controllerId && isFrozen(ctx.state, ctx.cardDb, ctx.attacker)) ||
      (ctx.defender !== null && ctx.defender.controllerId === self.controllerId && isFrozen(ctx.state, ctx.cardDb, ctx.defender));
    if (!ownFrozenInvolved) return;
    const opponent = getOpponents(ctx.state, self.controllerId)[0];
    if (opponent?.activeMagi) {
      discardEnergy(ctx.state, ctx.cardDb, opponent.activeMagi, 1, 'effect', undefined, ctx.rng);
    }
  },
});
