// Vrill -- "Nightfall: All of your Core Creatures in play gain energy equal to their starting
// energy." No target -- automatic sweep of own Core Creatures, each gains its OWN starting
// energy (effectively doubling from a fresh starting point).
//
// "Succor: At the end of your Energize Steps, move two energy from your Magi to Vrill." (task
// #35, 2026-07-16 -- previously missing entirely.) Built via afterMagiEnergized, which fires
// right after the Magi's own currentEnergy has already landed for that turn's Energize -- the
// natural "end of your Energize Step" moment in this engine, since Creatures don't have their own
// Energize rate. `rearrangeEnergy` is a net-zero move, not additive from nowhere.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveRegions, regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';
import { addEnergy, rearrangeEnergy } from '../effects.js';

registerCardEffect('Vrill', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Nightfall') return;
    const coreCreatures = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter((c) =>
      effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, 'Core'))
    );
    for (const creature of coreCreatures) {
      addEnergy(ctx.state, ctx.cardDb, creature, effectiveStartingEnergy(ctx.state, ctx.cardDb, creature), 'power');
    }
  },
  afterMagiEnergized: (state, cardDb, energizedMagi, self) => {
    if (energizedMagi.controllerId !== self.controllerId) return;
    rearrangeEnergy(state, cardDb, energizedMagi, self, 2);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Core'],
});
