// Worgle -- "Share: Discard Worgle from play. Choose a number of Creatures equal to the number of
// your frozen Creatures in play. Discard two energy from each of the chosen Creatures."
//
// "Choose a number of Creatures" doesn't say whose -- read as opposing Creatures (a harmful
// effect, same rational-default reasoning as garlak.ts).
//
// Real choice (task #40-2, 2026-07-17, player-choice-default retrofit, Group 2): replaces the
// earlier "first N opposing Creatures in array order" auto-pick with a real `powerTargetSlots`
// choice (registry.ts's `min`/`max` support a fixed number computed at slot-build time -- N here
// is the frozen count at the moment the Power is used, computed once inside `powerTargetSlots`
// itself since that function already receives `state`, same as Rockslide Hyren's fixed-3 slot).

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { creaturesControlledBy, opposingCreatures } from '../targeting.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Worgle', {
  powerTargetSlots: (state, cardDb, playerId) => {
    const frozenCount = creaturesControlledBy(state, cardDb, playerId).filter((c) => isFrozen(state, cardDb, c)).length;
    const poolSize = opposingCreatures(state, cardDb, playerId).length;
    const count = Math.min(frozenCount, poolSize);
    return [
      {
        label: `Choose ${count} opposing Creature${count === 1 ? '' : 's'} (equal to your frozen Creature count)`,
        pool: (s, db, pid) => opposingCreatures(s, db, pid),
        min: count,
        max: count,
      },
    ];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Share') return;
    const chosenIds = ctx.chosenSlotIds?.[0] ?? [];
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const pool = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    for (const id of chosenIds) {
      const target = pool.find((c) => c.instanceId === id);
      if (target) discardEnergy(ctx.state, ctx.cardDb, target, 2, undefined, undefined, ctx.rng);
    }
  },
});
