// Jaela -- "Spite: If Jaela is defeated, discard one energy from each Creature in play." No
// "opposing" qualifier, unlike Emaal's Sabotage -- hits every Creature, either side.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Jaela', {
  onOwnMagiDefeated: (state, cardDb, self) => {
    for (const creature of allCreaturesInPlay(state, cardDb)) {
      discardEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
});
