// Darkbreed Hyren -- "Subvert (6): Choose any one hyren in play. Gain control of the chosen
// hyren. That hyren may not attack this turn." First user of effects.ts's gainControl -- targets
// by effectiveCreatureType() (the shared species/family helper, whose own doc comment uses "Hyren"
// as its worked example) rather than region, since "hyren" spans nearly every region.
//
// Swirling Orshaa's Morph (Spell-pass audit follow-up, 2026-07-24) -- one of only ~7 real
// Power-target-gate cards verified to fit Checkpoint B's exact timing; registers
// specifiedCreatureTypes so Orshaa can react before this Power's own target-picker opens.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveCreatureType } from '../targeting.js';
import { gainControl } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Darkbreed Hyren', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => effectiveCreatureType(cardDb, c) === 'Hyren'),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Subvert') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target || effectiveCreatureType(ctx.cardDb, target) !== 'Hyren') return;

    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);
  },
  specifiedCreatureTypes: () => ['Hyren'],
});
