// Granas -- two Effects:
//   "Burrow: On all opponents' turns, Granas is burrowed; it cannot attack and loses no more than
//   two energy per turn from attacks and opposing Spells and Powers." (isConditionallyBurrowed.)
//   "Pummel: Whenever Granas attacks a Creature, Granas removes an additional energy from the
//   defending Creature."

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Granas', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Burrow owns the isConditionallyBurrowed
  // predicate (opponent-turn burrowed state; the "loses no more than two energy" cap half is
  // handled by a burrowed-flag reader elsewhere, not a card-side hook here). Pummel owns the
  // onBeforeEnergyRemoved reactor.
  effectHooks: {
    Burrow: ['isConditionallyBurrowed'],
    Pummel: ['onBeforeEnergyRemoved'],
  },
  isConditionallyBurrowed: (state, cardDb, instance) => state.activePlayerId !== instance.controllerId,
  // Pummel reduces the defender's own real energy during the attack step, corrected 2026-07-11 to
  // run in onBeforeEnergyRemoved so it counts toward the counter-damage the defender deals back
  // this same attack, not just a separate after-the-fact discard.
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId || !ctx.defender) return;
    discardEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect', undefined, ctx.rng);
  },
});
