// Flood of Energy (Spell, cost 2) -- "Energize all cards with an energize rate." Naroom Spell
// pass, Category A (2026-07-23). Reuses turn.ts's own applyEnergizeToInstance (now exported) --
// the exact same per-card gain the normal Energize step uses (afterMagiEnergized broadcast,
// one-shot modifier consumption, energized log event all included) -- just invoked early/extra
// over every in-play card + Magi on BOTH sides, filtered to effectiveEnergizeRate > 0 to match
// "cards WITH an energize rate" (the function itself already no-ops at amount 0 with no pending
// one-shot modifier, so this filter is mostly documentation).

import { registerCardEffect } from './registry.js';
import { applyEnergizeToInstance, effectiveEnergizeRate } from '../turn.js';

registerCardEffect('Flood of Energy', {
  resolveSpell: (ctx) => {
    for (const player of ctx.state.players.values()) {
      const candidates = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
      for (const instance of candidates) {
        if (effectiveEnergizeRate(ctx.state, ctx.cardDb, instance) > 0) {
          applyEnergizeToInstance(ctx.state, ctx.cardDb, player, instance, ctx.rng);
        }
      }
    }
  },
});
