// Sarf -- both printed Powers:
//   "Snatch: Choose an opposing Relic. Discard the chosen Relic. Sarf cannot attack this turn.
//   Use this Power only before your Attack step." Same this-turn CANNOT_ATTACK + legalPhases
//   shape as Blue Yajo's Strengthen.
//   "Freezerburn: If Sarf is frozen, choose a Magi. Discard energy from the chosen Magi equal to
//   that Magi's energize. Discard Sarf." No "opposing" qualifier -- either Magi is a legal
//   choice. "Energize" (no "printed" qualifier) reads as the EFFECTIVE rate, same interpretation
//   Thast's Ice Grinder already established for identical wording.

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay, discardEnergy } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK, isFrozen } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { effectiveEnergizeRate } from '../turn.js';

function allMagiInPlay(state: Parameters<typeof effectiveEnergizeRate>[0]) {
  const result = [];
  for (const player of state.players.values()) {
    if (player.activeMagi) result.push(player.activeMagi);
  }
  return result;
}

registerCardEffect('Sarf', {
  legalPhases: ['prs1'],
  powerTargets: (state, cardDb, playerId, powerName) => {
    if (powerName === 'Snatch') return allRelicsInPlay(state, cardDb).filter((r) => r.controllerId !== playerId);
    if (powerName === 'Freezerburn') return allMagiInPlay(state);
    return [];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Snatch') {
      if (ctx.chosenTargetId === undefined) return;
      const target = findInPlayById(ctx.state, ctx.chosenTargetId);
      if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Relic') return;
      if (target.controllerId === ctx.controllingPlayer.playerId) return;

      const owner = ctx.state.players.get(target.controllerId);
      if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
      addRestrictionTag(ctx.state, ctx.source, CANNOT_ATTACK, ctx.state.turnNumber);
      return;
    }
    if (ctx.powerName === 'Freezerburn') {
      if (!isFrozen(ctx.state, ctx.cardDb, ctx.source)) return;
      if (ctx.chosenTargetId === undefined) return;
      const magi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
      if (!magi) return;

      const amount = effectiveEnergizeRate(ctx.state, ctx.cardDb, magi);
      discardEnergy(ctx.state, ctx.cardDb, magi, amount, 'power', undefined, ctx.rng);
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    }
  },
});
