// Sellia -- "Whirlpool: Choose a non-Magi card of more than one Region. Discard it from play."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allRelicsInPlay, allSpellsInPlay, findInPlayById, effectiveRegions } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Sellia', {
  powerTargets: (state, cardDb) =>
    [...allCreaturesInPlay(state, cardDb), ...allRelicsInPlay(state, cardDb), ...allSpellsInPlay(state, cardDb)].filter(
      (c) => effectiveRegions(state, cardDb, c).length > 1
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Whirlpool') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    if (effectiveRegions(ctx.state, ctx.cardDb, target).length <= 1) return;

    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
