// Sand Sark -- "Hunt: As Sand Sark attacks a Creature with five or more energy, remove two energy
// from that Creature." Checked against the snapshot (the defender's energy at declare time), not
// the locked value, since "with five or more energy" describes the Creature being attacked, not
// the damage math in progress.

import { registerCardEffect } from './registry.js';

registerCardEffect('Sand Sark', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    if (ctx.snapshot.defenderEnergy < 5) return;
    ctx.locked.attackerEnergy += 2;
  },
});
