// Black Stuff -- "Regenerate: At the beginning of your turn, if your Magi is Bograth, you may
// play one copy of Black Stuff from your discard pile, paying all costs." registry.ts's
// reactsFromDiscardPileAtOwnTurnStart (task #30, 2026-07-15) -- onOwnTurnStart's own broadcast
// only ever scans `inPlay` + Magi, so a discarded Black Stuff would never be reached by it; this
// is checked separately by turn.ts's runStartOfTurnHooks, scanning the discard pile directly. Uses
// the same play.ts's playFromZonePayingCost primitive as Looph's Regroup.
//
// Real "may" prompt (playtest audit fix, 2026-08-11): previously auto-fired unconditionally
// whenever affordable, with no way to decline. The obvious-looking pendingOwnTurnStartChoice family
// (Kiersta's Swoon) does NOT work here -- its resolver looks the card up via
// findCreatureOrMagiById, which never scans the discard pile, where Black Stuff sits at trigger
// time. Instead mirrors Shadow Fird's Feed (shadowFird.ts): stage a pendingTargetChoice with a
// single-element pool (just self) from the discard-pile reactor hook -- that family's resolver uses
// findCardAnywhereById, which DOES scan the discard pile.

import { registerCardEffect } from './registry.js';
import { playFromZonePayingCost } from '../play.js';
import { effectiveRegions } from '../targeting.js';
import { addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const REGENERATE_PENDING = 'blackStuffRegeneratePending';

registerCardEffect('Black Stuff', {
  reactsFromDiscardPileAtOwnTurnStart: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const magi = player.activeMagi;
    if (!magi || !effectiveRegions(state, cardDb, magi).includes('Bograth')) return;
    addPendingChoiceTag(self, REGENERATE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(REGENERATE_PENDING)) return undefined;
    return { prompt: 'Regenerate: play Black Stuff from your discard pile, paying all costs?', pool: [self] };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    if (!self.tags.has(REGENERATE_PENDING)) return;
    removePermanentTag(self, REGENERATE_PENDING);
    if (chosenInstanceId !== self.instanceId) return; // declined
    const player = state.players.get(self.controllerId);
    if (!player) return;
    playFromZonePayingCost(state, cardDb, player, 'discardPile', self.instanceId, {}, rng);
  },
});
