// Gargagnor -- both printed clauses, built task #42, 2026-07-17, the Kybar's Teeth region pass:
//   "Invulnerability: Gargagnor loses one less energy in attacks." (invulnerability.ts)
//   "Perpetual Motion: When you play Gargagnor, choose any one other player. All of your Effects
//   that ordinarily happen at the beginning of your turn happen at the beginning of the chosen
//   player's turn instead." 2-player-only, so "any one other player" is unambiguous (no real choice
//   needed, matching Treepsh's own "any one opponent" simplification) -- durationTags.ts's
//   PERPETUAL_MOTION tag (shared with Jagt's identical clause) is set once, permanently, and
//   `turn.ts`'s `runStartOfTurnHooks` reroutes the whole onOwnTurnStart-family broadcast generically
//   off that tag, not a per-card hook.

import { registerCardEffect } from './registry.js';
import { applyInvulnerability } from './invulnerability.js';
import { addPermanentTag, PERPETUAL_MOTION } from '../durationTags.js';

registerCardEffect('Gargagnor', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Invulnerability owns onAttack;
  // Perpetual Motion owns onPlay (which stamps the PERPETUAL_MOTION permanent tag).
  effectHooks: {
    Invulnerability: ['onAttack'],
    'Perpetual Motion': ['onPlay'],
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    addPermanentTag(state, cardDb, self, PERPETUAL_MOTION);
  },
});
