// Yog's Maul -- "Thump Thump Wham!: Discard one of your Bograth Creatures from play. Choose any
// one opposing Creature in play. Discard energy from the chosen Creature equal to the number of
// your Bograth Creatures in play." Yog's Maul is a Relic, not itself a Bograth Creature, so
// (unlike Swamp Weebo) no pre-subtraction is needed -- the count naturally excludes the
// sacrificed Creature once it's actually been discarded, since the count is read AFTER that step
// inside resolvePower.
//
// Emlob retrofit (task #30, 2026-07-15): counts "your Bograth Creatures in play," exactly Emlob's
// Imaginary Friends inflates by three.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { emlobBonus } from './emlob.js';

registerCardEffect("Yog's Maul", {
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose one of your Bograth Creatures to sacrifice',
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid).filter((c) => effectiveRegions(s, db, c).includes(regionForTargetFilter(s, 'Bograth'))),
      min: 1,
      max: 1,
    },
    {
      // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- this slot feeds
      // discardEnergy, the sacrifice slot above only feeds discardFromPlay.
      label: 'Choose an opposing Creature',
      pool: (s, db, pid) => flexibleTargetPool(s, db, pid, opposingCreatures(s, db, pid), opposingMagi(s, db, pid)),
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Thump Thump Wham!') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const sacrificeId = slots[0]?.[0];
    const oppTargetId = slots[1]?.[0];
    if (!sacrificeId || !oppTargetId) return;

    const sacrifice = findCreatureOrMagiById(ctx.state, sacrificeId);
    if (!sacrifice || ctx.cardDb.get(sacrifice.definitionKey)?.card_type !== 'Creature') return;
    if (sacrifice.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, sacrifice).includes(regionForTargetFilter(ctx.state, 'Bograth'))) return;
    const oppTarget = findCreatureOrMagiById(ctx.state, oppTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!oppTarget || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, oppTarget, 'Creature')) return;
    if (oppTarget.controllerId === ctx.controllingPlayer.playerId) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, sacrifice.instanceId, undefined, undefined, ctx.rng);
    const bograthCount =
      creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter((c) =>
        effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, 'Bograth'))
      ).length + emlobBonus(ctx.cardDb, ctx.controllingPlayer.activeMagi);
    discardEnergy(ctx.state, ctx.cardDb, oppTarget, bograthCount, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (The opposing-Creature slot is unrestricted -- the
  // sacrifice slot's Bograth filter and the count computation are both in scope.)
  specifiedTargetRegions: () => ['Bograth'],
});
