// Chaos Flugg -- "Dark Demanding: Discard Chaos Flugg from play. Discard all Core and all Weave
// Creatures from play."
//
// "Resistance: Core and Weave Spells and Powers do not affect Chaos Flugg." Fixed 2026-07-17 --
// this was the ORIGINAL motivating card for registry.ts's blocksPowerEffectBySourceRegion hook
// (built task #35), but the hook was never actually registered on Chaos Flugg itself, leaving the
// wiring (effects.ts's discardEnergy/addEnergy) live and correct but pointed at nothing. Caught
// while re-scoping Magor's own (structurally identical) Resistance clause during the Paradwyn pass
// (task #37). Checks the acting Power's source card via state.currentAction?.sourceDefinitionKey,
// same as every other user of this hook.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Chaos Flugg', {
  blocksPowerEffectBySourceRegion: (state, cardDb) => {
    const sourceKey = state.currentAction?.sourceDefinitionKey;
    if (sourceKey === undefined) return false;
    const sourceDef = cardDb.get(sourceKey);
    if (!sourceDef) return false;
    return sourceDef.regions.includes('Core') || sourceDef.regions.includes('Weave');
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dark Demanding') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const targets = allCreaturesInPlay(ctx.state, ctx.cardDb).filter((c) => {
      const regions = effectiveRegions(ctx.state, ctx.cardDb, c);
      return regions.includes(regionForTargetFilter(ctx.state, 'Core')) || regions.includes(regionForTargetFilter(ctx.state, 'Weave'));
    });
    for (const creature of targets) {
      const owner = ctx.state.players.get(creature.controllerId);
      if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, creature.instanceId, undefined, undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (blocksPowerEffectBySourceRegion above is a Resistance
  // check against the ACTING Power's own source card, not a target filter -- out of scope.)
  specifiedTargetRegions: () => ['Core', 'Weave'],
});
