// Emaya -- "Improvise: Discard a Relic from your hand to choose a Creature. Discard two energy
// from or add two energy to the chosen Creature." First card needing registry.ts's booleanChoice
// -- the controller picks the direction. "Each of your non-Nar, non-Universal cards costs one
// additional energy to play" is narSurcharge.ts's shared helper (2026-07-11).
// "At the beginning of your turn, choose an opponent. Increase your energize by one for each
// Relic the chosen opponent has in play." Built task #43, 2026-07-18, the Nar region pass --
// in a 2-player game there's only one legal opponent, so "choose" resolves automatically, no
// pendingTargetChoice needed. Same energizeRateModifier shape Kyg'n's own energize-rate clause
// just proved (kygn.ts), simplified further since there's no persistent choice to store.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, opposingMagi } from '../targeting.js';
import { addEnergy, discardEnergy, discardFromHand } from '../effects.js';
import { narSurcharge } from './narSurcharge.js';

registerCardEffect('Emaya', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- the pool can't know the
  // player's upcoming booleanChoice in advance, so it offers a Magi even though only the discard
  // branch (chosenBoolean !== false) actually accepts one; resolvePower below is the final
  // authority and safely rejects a Magi + "add" combo, same "pool is a hint, resolve validates"
  // pattern this codebase already relies on elsewhere (e.g. Darbok's self-exclusion note).
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Relic',
  },
  booleanChoice: { prompt: 'Discard energy or add energy?', yesLabel: 'Discard 2', noLabel: 'Add 2' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Improvise') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandCardIds![0]);
    if (!discardedCard || ctx.cardDb.get(discardedCard.definitionKey)?.card_type !== 'Relic') return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    if (ctx.chosenBoolean === false) {
      // Dreamburn only covers energy-DISCARD Powers, not this ADD branch -- stays Creature-only.
      if (ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    } else {
      // task #34, 2026-07-16: Abraxin's Crown's Dreamburn covers this DISCARD branch --
      // it may allow a Magi target here instead.
      if (!isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    }

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    if (ctx.chosenBoolean === false) {
      addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
    } else {
      discardEnergy(ctx.state, ctx.cardDb, target, 2, undefined, undefined, ctx.rng);
    }
  },
  costModifier: narSurcharge,
  energizeRateModifier: (state, cardDb, energizing, self) => {
    const owner = state.players.get(self.controllerId);
    if (owner?.activeMagi?.instanceId !== energizing.instanceId) return 0;
    const opponentMagi = opposingMagi(state, cardDb, self.controllerId)[0];
    if (!opponentMagi) return 0;
    return state.players.get(opponentMagi.controllerId)?.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic').length ?? 0;
  },
});
