// Ominous Chill (Spell, Bograth/Nar) -- "Choose any one of your Creatures in play. Discard the
// chosen Creature from play. Until the end of your next turn, all of your Creatures in play gain
// 'Effect -- Chill: Whenever this Creature attacks, it removes two additional energy from the
// defending Creature.'" Bograth Spell pass, Category B2 (2026-07-20). The self-sacrifice half is a
// plain discardFromPlay call. The granted ability reads as a PASSIVE trigger, not an activated
// Power, so (unlike Darkness) this uses a new duration tag (durationTags.ts's
// CHILL_BONUS_ATTACK_DAMAGE) checked generically in combat.ts's onBeforeEnergyRemoved path -- same
// shape as the WEAKENED-family extra-discard-on-attack tags, applied at cast time to every Creature
// CURRENTLY in play (not retroactively to Creatures played later in the window, matching the plan's
// own "applied at cast time" framing).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { addDurationTag, CHILL_BONUS_ATTACK_DAMAGE, nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Ominous Chill', {
  spellTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId, undefined, undefined, ctx.rng);

    const expiry = nextOwnTurnNumber(ctx.state);
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      addDurationTag(ctx.state, ctx.cardDb, creature, CHILL_BONUS_ATTACK_DAMAGE, expiry);
    }
  },
});
