// Icefield Ashryte -- "Thermal Stress: Choose a card in play of a different region than its Magi.
// Discard the chosen card." Pool spans Creatures, Relics, and Spells -- any in-play card whose
// OWN region set doesn't overlap its controller's Magi's region set.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allRelicsInPlay, allSpellsInPlay, effectiveRegions, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

function hasDifferentRegionThanMagi(state: GameState, cardDb: CardDatabase, card: CardInstance): boolean {
  const owner = state.players.get(card.controllerId);
  const magi = owner?.activeMagi;
  if (!magi) return false;
  const cardRegions = effectiveRegions(state, cardDb, card);
  const magiRegions = effectiveRegions(state, cardDb, magi);
  return !cardRegions.some((r) => magiRegions.includes(r));
}

registerCardEffect('Icefield Ashryte', {
  powerTargets: (state, cardDb) =>
    [...allCreaturesInPlay(state, cardDb), ...allRelicsInPlay(state, cardDb), ...allSpellsInPlay(state, cardDb)].filter(
      (c) => hasDifferentRegionThanMagi(state, cardDb, c)
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Thermal Stress') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    if (!hasDifferentRegionThanMagi(ctx.state, ctx.cardDb, target)) return;

    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
