// Bagala -- "Pack Charge: Whenever Bagala attacks, before energy is removed, add one energy to it
// for each of your Bagala Creatures in play." Includes Bagala itself in the count (it's one of
// "your Bagala Creatures in play" too, since it's attacking from play). NOT filtered via
// targeting.ts's creatureType -- the Bagala family breaks the usual "type = shared LAST word"
// convention the same way the Furok family did (Bagala Cub, Bagala Hunter have "Bagala" as the
// FIRST word, so creatureType() would return "Cub"/"Hunter" instead). Matched by a word-boundary
// check against the card's full name instead, same fix as darkwoodFurok.ts.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';

registerCardEffect('Bagala', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    const count = creaturesControlledBy(ctx.state, ctx.cardDb, self.controllerId).filter((c) =>
      /\bBagala\b/.test(ctx.cardDb.get(c.definitionKey)?.name ?? '')
    ).length;
    if (count > 0) addEnergy(ctx.state, ctx.cardDb, self, count, 'effect');
  },
});
