// Raega -- "Cremate (X): Choose any one Creature in play with X energy. Discard the chosen
// Creature from play." The pool can't be pre-filtered by X (powerTargets has no access to the
// chosenXValue, only resolvePower does), so it offers every Creature and validates the exact
// energy match in resolvePower -- same "offer broad, resolve validates" pattern as Helgrem.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Raega', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Cremate') return;
    if (ctx.chosenTargetId === undefined) return;
    if (ctx.chosenXValue === undefined || ctx.chosenXValue < 0) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if ((target.currentEnergy ?? 0) !== ctx.chosenXValue) return;

    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
