// Grand Epik -- two printed clauses:
//   "Reduce your Magi's Energize by two." -- energizeRateModifier, own Magi only, flat -2 (composes
//   naturally with Dream Binge below: if the reduced Magi is Arderial, Dream Binge sees the
//   already-reduced amount, since energizeRateModifier resolves before turn.ts applies `amount`
//   and fires afterMagiEnergized with that same final amount).
//   "Dream Binge: Whenever an Arderial Magi energizes, add an equal amount of energy to Grand
//   Epik." -- afterMagiEnergized, unqualified ("an Arderial Magi," no "your"/"opposing"), so it
//   reacts to either side's Arderial Magi, same reasoning as Nightmare Construct's Absorb.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Grand Epik', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Only Dream Binge is a printed named
  // Effect; the "Reduce your Magi's Energize by two" clause has `name: null` in cards_final.json
  // (unnamed), so `energizeRateModifier` is left out of the map -- a Taglat-copied 'Dream Binge'
  // fires only the afterMagiEnergized reactor, not the Magi energize penalty.
  effectHooks: {
    'Dream Binge': ['afterMagiEnergized'],
  },
  energizeRateModifier: (state, cardDb, energizing, self) => {
    if (energizing.controllerId !== self.controllerId) return 0;
    if (cardDb.get(energizing.definitionKey)?.card_type !== 'Magi') return 0;
    return -2;
  },
  afterMagiEnergized: (state, cardDb, energizedMagi, self, amount) => {
    const magiDef = cardDb.get(energizedMagi.definitionKey);
    if (!magiDef?.regions.includes('Arderial')) return;
    if (amount <= 0) return;
    addEnergy(state, cardDb, self, amount, 'effect');
  },
});
