// Ithapher -- "Combustion (2): Until the end of your turn, each Spell or Power that discards
// energy from a single Creature discards one additional energy." Both halves are live (task #51,
// 2026-07-20: play.ts/effects.ts's own Spell-side broadcast reuses the same hook power.ts already
// fires) -- this file never had a card_type/cause guard to begin with, so nothing here needed to
// change. Activating the Power sets a duration tag on Ithapher lasting for the rest of THIS turn
// (addDurationTag(self, tag,
// state.turnNumber) -- same "present for the entire turn named, gone by the start of the next"
// shape every other until-end-of-turn buff in this codebase uses). While active, the new
// onOwnPowerDiscardedOpposingEnergyFromCreature hook (power.ts) applies the extra energy loss, but
// ONLY when exactly one opposing Creature was hit this resolution -- "a SINGLE Creature," unlike
// The Last Words/Scroll of Fire's Pyromancy, which apply per-Creature with no such cap. No region
// or source-card-type restriction on the printed text (unlike those two), and the hook is already
// broadcast only to the acting player's own board, so no extra "your Power" check is needed here.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const COMBUSTION_ACTIVE = 'ithapherCombustionActiveThisTurn';

registerCardEffect('Ithapher', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Combustion') return;
    addDurationTag(ctx.state, ctx.cardDb, ctx.source, COMBUSTION_ACTIVE, ctx.state.turnNumber);
  },
  onOwnPowerDiscardedOpposingEnergyFromCreature: (state, cardDb, self, _sourceCard, target, _amount, distinctCreaturesAffected) => {
    if (!hasDurationTag(self, COMBUSTION_ACTIVE)) return;
    if (distinctCreaturesAffected !== 1) return;
    discardEnergy(state, cardDb, target, 1, 'power');
  },
});
