// N'ssah -- "Fearless: As one of your Creatures attacks a larger Creature, add two energy to your
// Creature." Real energy add -> onBeforeEnergyRemoved.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect("N'ssah", {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.controllerId !== self.controllerId) return;
    if (!ctx.defender) return;
    if ((ctx.defender.currentEnergy ?? 0) <= (ctx.attacker.currentEnergy ?? 0)) return;
    addEnergy(ctx.state, ctx.cardDb, ctx.attacker, 2, 'effect');
  },
});
