// Gumph -- "Night's Shade: Once per turn, when a Creature is discarded from play, choose a
// Creature. Discard two energy from the chosen Creature." Broadcast trigger (any Creature,
// either side, either cause), once-per-turn guard via a card-scoped duration tag (same pattern as
// corathan.ts's Betrayal).
//
// Real choice (Phase 4c, 2026-07-11): the trigger no longer picks and applies immediately --
// it marks a pending choice (registry.ts's pendingTargetChoice/resolveTargetChoice), which the UI
// resolves into an actual player pick. Replaces the earlier "first eligible in array order"
// simplification.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, addPermanentTag, addPendingChoiceTag, hasDurationTag, removePermanentTag } from '../durationTags.js';

const NIGHTS_SHADE_USED_THIS_TURN = 'gumphNightsShadeUsedThisTurn';
const NIGHTS_SHADE_PENDING = 'gumphNightsShadePending';

registerCardEffect('Gumph', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Creature') return;
    if (hasDurationTag(self, NIGHTS_SHADE_USED_THIS_TURN)) return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;

    addPendingChoiceTag(self, NIGHTS_SHADE_PENDING);
    addDurationTag(state, cardDb, self, NIGHTS_SHADE_USED_THIS_TURN, state.turnNumber);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(NIGHTS_SHADE_PENDING)) return undefined;
    const pool = allCreaturesInPlay(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Gumph's Night's Shade: choose a Creature to discard 2 energy from", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, NIGHTS_SHADE_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 2, 'effect', undefined, rng);
  },
});
