// Flame Rudwot -- two Powers with DIFFERENT target pools, the reason powerTargets now takes the
// Power's name (2026-07-08):
//   "Healing Flame (2): Choose any one other Cald or Naroom Creature in play. Add three energy
//    to the chosen Creature."
//   "Burning Branches (2): Choose any one non-Cald, non-Naroom Creature in play. Discard three
//    energy from the chosen Creature."
// This was the exact card that caught the once-per-turn-is-per-Power-not-per-card bug (see
// PROGRESS_LOG.md 2026-07-08) -- now properly registered rather than just live-tested ad hoc.
//
// Healing Flame's "other" (excluding Rudwot itself) is now excluded at the picker level too
// (2026-07-08 fix -- see registry.ts's powerTargets doc comment): the picker receives the exact
// source instanceId, so it can filter out precisely THIS copy even with 2-3 copies in play,
// rather than relying solely on resolvePower's post-hoc rejection (which left a dead-end
// selection in the UI that still cost energy for nothing -- a real bug the project owner caught
// live). resolvePower still re-validates, same "the resolve function is the final authority"
// pattern every other card's powerTargets already relies on.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

// Region-swap sweep (Spell-pass audit follow-up, 2026-07-23): each of the two literals is
// independently passed through regionForTargetFilter, so swapping EITHER 'Cald' or 'Naroom'
// changes just that one term of the OR, not the whole condition.
function isCaldOrNaroom(state: GameState, cardDb: CardDatabase, instance: CardInstance): boolean {
  const regions = effectiveRegions(state, cardDb, instance);
  return regions.includes(regionForTargetFilter(state, 'Cald')) || regions.includes(regionForTargetFilter(state, 'Naroom'));
}

registerCardEffect('Flame Rudwot', {
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    const pool = allCreaturesInPlay(state, cardDb);
    if (powerName === 'Burning Branches') {
      // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- this Power discards
      // energy; Healing Flame (below) adds energy, Dreamburn doesn't cover it, stays untouched.
      return flexibleTargetPool(state, cardDb, playerId, pool, allMagiInPlay(state)).filter((c) => !isCaldOrNaroom(state, cardDb, c));
    }
    return pool.filter((c) => c.instanceId !== sourceInstanceId && isCaldOrNaroom(state, cardDb, c));
  },
  resolvePower: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    if (ctx.powerName === 'Healing Flame') {
      // Dreamburn only covers energy-DISCARD Powers, not this ADD Power -- stays Creature-only.
      if (ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
      if (target.instanceId === ctx.source.instanceId) return; // "other" -- excludes itself
      if (!isCaldOrNaroom(ctx.state, ctx.cardDb, target)) return;
      addEnergy(ctx.state, ctx.cardDb, target, 3, 'power');
    } else if (ctx.powerName === 'Burning Branches') {
      // task #34, 2026-07-16: Abraxin's Crown's Dreamburn covers this DISCARD Power --
      // it may allow a Magi target here instead.
      if (!isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
      if (isCaldOrNaroom(ctx.state, ctx.cardDb, target)) return;
      discardEnergy(ctx.state, ctx.cardDb, target, 3, undefined, undefined, ctx.rng);
    }
  },
  specifiedTargetRegions: () => ['Cald', 'Naroom'],
});
