// Crushing Stones (4-cost Spell, Kybar's Teeth-Magi-only) -- "Choose any one Creature in play.
// Discard four energy from the chosen Creature. If this discards the chosen Creature from play,
// add one energy to each of your Kybar's Teeth Creatures in play. Only Kybar's Teeth Magi and
// Kybar's Teeth Shadow Magi can play Crushing Stones." Kybar's Teeth Spell pass, Category B
// (2026-07-22). The "Kybar's Teeth Magi/Shadow Magi only" restriction is 100% data-driven
// (region_restrictive, per crushingStench.ts's own header comment -- zero code needed here). The
// "discard 4; if it dies, do X" half is crushingStench.ts's own exact structure (discardEnergy ->
// checkCreatureDefeats -> re-check findInPlayById).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy, addEnergy } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';

registerCardEffect('Crushing Stones', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);
    checkCreatureDefeats(ctx.state, ctx.cardDb, 'spell', undefined, ctx.rng);
    const stillThere = findInPlayById(ctx.state, target.instanceId);
    if (stillThere) return; // wasn't discarded from play -- no bonus

    const yours = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter((c) =>
      effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, "Kybar's Teeth"))
    );
    for (const c of yours) addEnergy(ctx.state, ctx.cardDb, c, 1, 'spell');
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (spellTargets above is the discard-target picker, an
  // open "any Creature in play" pool with no region gate -- only the bonus clause's Kybar's
  // Teeth check is in scope here.)
  specifiedSpellTargetRegions: () => ["Kybar's Teeth"],
});
