// Flying Darbok -- "Airlift: Choose one of your Creatures in play. Move all energy from Flying
// Darbok to the chosen Creature, and add two energy to the chosen Creature. The chosen Creature
// can attack Magi directly this turn. Use this Power only before the Attack step." First card
// using durationTags.ts's new CAN_ATTACK_MAGI_DIRECTLY tag.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addEnergy, rearrangeEnergy } from '../effects.js';
import { addDurationTag, CAN_ATTACK_MAGI_DIRECTLY } from '../durationTags.js';

registerCardEffect('Flying Darbok', {
  legalPhases: ['prs1'],
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Airlift') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;

    rearrangeEnergy(ctx.state, ctx.cardDb, ctx.source, target, ctx.source.currentEnergy ?? 0, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
    addDurationTag(ctx.state, ctx.cardDb, target, CAN_ATTACK_MAGI_DIRECTLY, ctx.state.turnNumber);
  },
});
