// Robes of the Ages -- "Ancestral Favor: Your Spells cost one less energy to play, to a minimum
// of one." Plain costModifier.

import { registerCardEffect } from './registry.js';

registerCardEffect('Robes of the Ages', {
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return playedDef.card_type === 'Spell' ? -1 : 0;
  },
});
