// Forgotten Dancer -- "Excise (3): Choose any one Core Creature in play. Discard Forgotten Dancer
// from play. Take control of the chosen Creature. That Creature loses energy equal to the amount
// of energy on your Magi and may not attack this turn."

// Ashio's Weave Twist (2026-07-24): "Core" above is Forgotten Dancer's OWN printed text, so under
// Ashio it means its own region (Universal) instead -- see targeting.ts's ashioAdjustedRegion doc
// comment.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, ashioAdjustedRegion, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay, discardEnergy, gainControl } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Forgotten Dancer', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, ashioAdjustedRegion(state, cardDb, 'Core', ['Universal'])))),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Excise') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target || !effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, ashioAdjustedRegion(ctx.state, ctx.cardDb, 'Core', ['Universal'])))) return;

    const magiEnergy = ctx.controllingPlayer.activeMagi?.currentEnergy ?? 0;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
    discardEnergy(ctx.state, ctx.cardDb, target, magiEnergy, undefined, undefined, ctx.rng);
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);
  },
  specifiedTargetRegions: (state, cardDb) => [ashioAdjustedRegion(state, cardDb, 'Core', ['Universal'])],
});
