// Speag Sprouts -- "Weave": "As this Creature attacks or is attacked, you may move one energy
// between it and one of your other Weave Creatures." (see weave.ts)
//
// "Weave Strength: After energy is moved to Speag Sprouts on an opponent's turn, add one energy to
// Speag Sprouts." -- BUILT 2026-08-11 (post-audit deferred-gap closure pass, Category B), via the
// `to` parameter newly added to registry.ts's `onOwnCreatureMovedEnergyViaEffect` broadcast (weave.ts's
// `broadcastEnergyMoveEffect`) -- fires whenever ANY energy-move Effect (not just Speag Sprouts' own
// Weave) lands energy on it, checked against `state.activePlayerId` for "on an opponent's turn."

import { registerCardEffect } from './registry.js';
import { applyWeave } from './weave.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Speag Sprouts', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Weave owns the standard energy-move
  // hook + `weaveConfig`; Weave Strength owns the post-move reactor.
  effectHooks: {
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
    'Weave Strength': ['onOwnCreatureMovedEnergyViaEffect'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
  onOwnCreatureMovedEnergyViaEffect: (state, cardDb, self, mover, from, to) => {
    if (to?.instanceId !== self.instanceId) return;
    if (state.activePlayerId === self.controllerId) return; // "on an opponent's turn"
    addEnergy(state, cardDb, self, 1, 'effect');
  },
});
