// Amanax -- "Pyromaniac: Once per turn, when one of your Cald Spells or Powers discards energy
// from one or more opposing Creatures, you may add one energy to Amanax for each energy
// discarded." Built via the `onOwnPowerDiscardedOpposingEnergy` hook (task #27, 2026-07-14),
// broadcast by power.ts right after any of Amanax's controller's own Powers finishes resolving,
// and (task #51, 2026-07-20) also by play.ts/effects.ts right after any of Amanax's controller's
// own Spells finishes resolving -- both a Cald Power AND a Cald Spell now actually trigger this,
// matching the full printed text. "You may" is applied unconditionally: adding energy to your own
// Magi has no downside, so there's no real choice to prompt for.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const PYROMANIAC_USED_THIS_TURN = 'amanaxPyromaniacUsedThisTurn';

registerCardEffect('Amanax', {
  onOwnPowerDiscardedOpposingEnergy: (state, cardDb, self, sourceCard, amount) => {
    if (hasDurationTag(self, PYROMANIAC_USED_THIS_TURN)) return;
    const sourceDef = cardDb.get(sourceCard.definitionKey);
    if (!sourceDef?.regions.includes('Cald')) return;

    addDurationTag(state, cardDb, self, PYROMANIAC_USED_THIS_TURN, state.turnNumber);
    addEnergy(state, cardDb, self, amount, 'effect');
  },
});
