// Emaal -- "Sabotage: When Emaal is defeated, discard all energy from all opposing Magi and draw
// a card." Uses the new registry.ts `onOwnMagiDefeated` hook (2026-07-12), the simplest shape in
// that family -- no target choice, no delay.

import { registerCardEffect } from './registry.js';
import { getOpponents } from '../types/state.js';
import { discardEnergy, drawCards } from '../effects.js';

registerCardEffect('Emaal', {
  onOwnMagiDefeated: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    for (const opponent of getOpponents(state, self.controllerId)) {
      if (opponent.activeMagi && (opponent.activeMagi.currentEnergy ?? 0) > 0) {
        discardEnergy(state, cardDb, opponent.activeMagi, opponent.activeMagi.currentEnergy ?? 0, 'effect');
      }
    }
    drawCards(state, cardDb, player, 1);
  },
});
