// Iain -- "Beginning's End (4): Choose any one opposing Creature in play. Discard energy from
// the chosen Creature equal to that Creature's starting energy."

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveStartingEnergy } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Iain', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Beginning's End") return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;

    discardEnergy(ctx.state, ctx.cardDb, target, effectiveStartingEnergy(ctx.state, ctx.cardDb, target), undefined, undefined, ctx.rng);
  },
});
