// Whall -- "Dream Twist (5): Choose any one of your Creatures in play. Discard the chosen
// Creature. Play a Creature from your hand without paying its energy cost. Put energy onto the
// played Creature equal to its starting energy. That Creature may not attack this turn." Same
// discard-then-handPlayChoice shape as Shimmering Orshaa, just no region filter on the hand pick.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay, playFromZone } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Whall', {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  handPlayChoice: {
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Twist') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = ctx.controllingPlayer.inPlay.find(
      (c) => c.instanceId === ctx.chosenTargetId && ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature'
    );
    if (!target) return;
    if (!ctx.chosenHandPlayId) return;
    const handCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    const def = handCard ? ctx.cardDb.get(handCard.definitionKey) : undefined;
    if (!def || def.card_type !== 'Creature') return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId, undefined, undefined, ctx.rng);
    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: ctx.chosenHandPlayId },
      ctx.controllingPlayer,
      effectiveStartingEnergy(ctx.state, ctx.cardDb, handCard!)
    , ctx.rng);
    if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
  },
});
