// Ormalet -- "Tantrum (4): Discard two energy from each non-Underneath Creature in play." No
// target -- a region-filtered sweep across both sides.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Ormalet', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Tantrum') return;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Underneath'))) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 2, undefined, undefined, ctx.rng);
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Underneath'],
});
