// Crystal Arboll -- "Healing Light: Choose any one Creature in play. Discard Crystal Arboll from
// play. Add two energy to the chosen Creature. If the chosen Creature is Underneath, add two
// additional energy."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveRegions } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Crystal Arboll', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Healing Light') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    const bonus = effectiveRegions(ctx.state, ctx.cardDb, target).includes('Underneath') ? 2 : 0;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, 2 + bonus, 'power');
  },
});
