// Abger -- "Shrewd: Opposing Paradwyn Creatures cost one additional energy to play"
// (registry.ts's costModifier).
//
// "Barter: Once per turn, when an opposing Magi plays a Relic, you may discard one energy from
// Abger to draw two cards." Built this pass (task #30, 2026-07-15) -- an ordinary reactive-play
// shape (onPlay broadcast + once-per-turn tag + optional self-cost + payoff), same as several
// other cards built this pass (Bog Wellisk, Baa). Was only deferred earlier because that session
// was scoped narrowly to cost-modification, not because anything was actually blocking it.

import { registerCardEffect } from './registry.js';
import { discardEnergy, drawCards } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const BARTER_USED = 'abgerBarterUsedThisTurn';

registerCardEffect('Abger', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Shrewd is the opposing-Paradwyn cost surcharge;
  // Barter is the once-per-turn opposing-Relic-play reaction.
  effectHooks: {
    Shrewd: ['costModifier'],
    Barter: ['onPlay'],
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId === self.controllerId) return 0;
    if (playedDef.card_type !== 'Creature' || !playedDef.regions.includes('Paradwyn')) return 0;
    return 1;
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return; // "an opposing Magi"
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;
    if (hasDurationTag(self, BARTER_USED)) return;
    if ((self.currentEnergy ?? 0) < 1) return;

    addDurationTag(state, cardDb, self, BARTER_USED, state.turnNumber);
    discardEnergy(state, cardDb, self, 1, 'effect', self.controllerId);
    const player = state.players.get(self.controllerId);
    if (player) drawCards(state, cardDb, player, 2);
  },
});
