// Spirit of Bograth (0-cost Spell) -- "You may play this card only when your Bograth Magi is
// defeated on an opponent's turn. Discard a card from your hand. When you reveal your next Magi,
// add energy to it equal to one opposing Magi's Energize rate. You can only play one Spirit Spell
// per Magi defeated." Bograth Spell pass, Category B2 (2026-07-20). Near-total reuse of
// spiritOfArderial.ts (the only other built Spirit Spell): identical preventsOwnPlay eligibility
// against PlayerState.pendingSpiritSpellRegions.includes('Bograth') (pushed generically by
// energy.ts#defeatMagi for ANY region on the defeated Magi -- no engine change needed to unblock
// this), identical spellHandDiscardCost: {count: 1}. Only the payload differs: "one opposing Magi's
// Energize rate" is read live off the current opposing Magi at RESOLUTION time (2-player game, so
// "one opposing Magi" is unambiguous -- same simplification Icecap's own comment already uses for
// "the opposing Magi"), snapshotted into PlayerState.pendingMagiRevealEnergyBonus (a new small
// field -- see its own doc comment in types/state.ts) since the bonus applies at a FUTURE Magi
// reveal, long after this Spell itself is gone; consumed by turn.ts#revealNextMagi.

import { closeSpiritSpellWindow } from '../spiritSpells.js';
import { registerCardEffect } from './registry.js';
import { opposingMagi } from '../targeting.js';
import { discardFromHand, checkHandEmptied } from '../effects.js';
import { effectiveEnergizeRate } from '../turn.js';

registerCardEffect('Spirit of Bograth', {
  preventsOwnPlay: (state, cardDb, playerId) => {
    const player = state.players.get(playerId)!;
    return player.pendingSpiritSpellRegions.includes('Bograth')
      ? false
      : "Spirit of Bograth can only be played when your Bograth Magi has just been defeated on an opponent's turn";
  },
  spellHandDiscardCost: { count: 1 },
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    if (!player.pendingSpiritSpellRegions.includes('Bograth')) return; // re-validate; state can change between UI collection and resolution
    // Closes the WHOLE window, not just this region: "only one Spirit Spell per Magi
    // defeated", and a multi-region Magi queues one entry per region (2026-07-26).
    closeSpiritSpellWindow(ctx.state, player.playerId);

    const ids = ctx.chosenHandCardIds ?? [];
    if (ids.length === 1) discardFromHand(ctx.state, ctx.cardDb, player, ids, undefined, ctx.rng);

    const opponentMagi = opposingMagi(ctx.state, ctx.cardDb, player.playerId)[0];
    if (opponentMagi) {
      player.pendingMagiRevealEnergyBonus = effectiveEnergizeRate(ctx.state, ctx.cardDb, opponentMagi);
    }
    checkHandEmptied(ctx.state, ctx.cardDb, ctx.rng);
  },
});
