// Rainbow Hyren -- two printed clauses:
//   "Shining Light: Powers on your Hyren cost one less energy to use, to a minimum of one." --
//   powerCostModifier + powerCostFloorsAtOne, "Hyren" family match on the Power's source (task
//   2026-07-19 playtest fix -- was floored at power.ts's shared default of 0, e.g. Monarch Hyren's
//   Command (1) going to 0 instead of this card's own printed minimum of 1; see registry.ts's
//   powerCostFloorsAtOne doc comment).
//   "Gift: If your Magi is Arderial, your Universal Hyren cost one less energy to play, to a
//   minimum of one." -- costModifier (play.ts already floors a negative costModifier sum at 1 for
//   ALL card plays, so this clause needed no change).

import { registerCardEffect } from './registry.js';

const HYREN_FAMILY = /\bHyren\b/;

function shiningLightApplies(powerUserId: string, sourceDef: { name: string }, self: { controllerId: string }): boolean {
  return powerUserId === self.controllerId && HYREN_FAMILY.test(sourceDef.name);
}

registerCardEffect('Rainbow Hyren', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Shining Light is the Hyren-Power discount
  // (cost modifier + floor-at-one on the same predicate); Gift is the Universal-Hyren play discount.
  // No shared hooks -- either Effect narrows cleanly.
  effectHooks: {
    'Shining Light': ['powerCostModifier', 'powerCostFloorsAtOne'],
    Gift: ['costModifier'],
  },
  powerCostModifier: (state, cardDb, powerUserId, sourceDef, self) => (shiningLightApplies(powerUserId, sourceDef, self) ? -1 : 0),
  powerCostFloorsAtOne: (state, cardDb, powerUserId, sourceDef, self) => shiningLightApplies(powerUserId, sourceDef, self),
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    if (!playedDef.regions.includes('Universal') || !HYREN_FAMILY.test(playedDef.name)) return 0;
    const magi = state.players.get(playerId)?.activeMagi;
    const magiDef = magi && cardDb.get(magi.definitionKey);
    return magiDef?.regions.includes('Arderial') ? -1 : 0;
  },
});
