// Chogulith -- "Strengthen (2): Choose any one Chogus in play. Roll one die. Add that much
// energy to the chosen Chogus." First card to use effects.ts's rollDie primitive.
//
// "Chogus" is a naming family, not a structured subtype field (there's no `subtype: "Chogus"` in
// the card database) -- matched here by substring on the card's own name (Chogus, Chogus Little,
// Giant Chogus, Stubborn Chogus, and the "Chogo" evolution-line spelling: Fire Chogo, Leaf Chogo,
// Spark Chogo). Treating both spellings as the same family is an assumption, not confirmed
// against a physical ruling -- flag if it turns out to be wrong.
//
// Swirling Orshaa's Morph (Spell-pass audit follow-up, 2026-07-24) -- routed through
// matchesCreatureFamily() for EACH spelling (checks a live Morph identityOverride first, falls
// back to the printed name substring); specifiedCreatureTypes declares BOTH spellings since Orshaa
// can Morph into either one to satisfy this check.
//
// Whimsy-refactor pilot (Category D SEVENTH item, 2026-08-12, task #724): this file is the
// SHAPE PROVER for the ~42-file Fate's Whimsy consumer migration. The body split is uniform
// across all 43 die-rolling files: `resolvePower` prepares the target payload and calls
// `requestDieRoll` with a unique consumer key; the actual roll-consuming code moves into a
// top-level `registerRollConsumer` block. The payload is a plain object (JSON-serializable, so
// `state.pendingDieRoll` can survive save/replay round-trips). Fast path (no Whimsy in hand)
// invokes the consumer inline with no state changes, matching pre-refactor behavior exactly.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, matchesCreatureFamily } from '../targeting.js';
import { addEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

function isChogusFamily(cardDb: CardDatabase, instance: CardInstance): boolean {
  return matchesCreatureFamily(cardDb, instance, 'Chogus') || matchesCreatureFamily(cardDb, instance, 'Chogo');
}

registerCardEffect('Chogulith', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => isChogusFamily(cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Strengthen') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || !isChogusFamily(ctx.cardDb, target)) return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'chogulith:strengthen',
      { targetId: target.instanceId },
      ctx.rng
    );
  },
  specifiedCreatureTypes: () => ['Chogus', 'Chogo'],
});

registerRollConsumer('chogulith:strengthen', (state, cardDb, _source, payload, finalRoll) => {
  const { targetId } = payload as { targetId: string };
  const target = findInPlayById(state, targetId);
  if (!target || !isChogusFamily(cardDb, target)) return; // target may have left play during Whimsy window
  addEnergy(state, cardDb, target, finalRoll, 'power');
});
