// Omni Construct -- "Enhance (2): Choose a Creature type. Add one energy to Omni Construct for
// each Creature of that type in play." "Type" here means the Creature's species/family (Hyren,
// Xyx, Arboll, etc. -- targeting.ts's creatureType), NOT region -- fixed 2026-07-08, this
// originally (incorrectly) grouped by region. Options are computed from whichever types are
// actually present among Creatures in play right now, not a hardcoded list of every type that
// exists (picking an empty one would be pointless).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creatureType } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Omni Construct', {
  categoryChoice: {
    prompt: 'Choose a Creature type',
    options: (state, cardDb) => {
      const types = new Set<string>();
      for (const creature of allCreaturesInPlay(state, cardDb)) {
        types.add(creatureType(cardDb, creature.definitionKey));
      }
      return [...types];
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Enhance') return;
    if (!ctx.chosenCategory) return;
    const count = allCreaturesInPlay(ctx.state, ctx.cardDb).filter(
      (c) => creatureType(ctx.cardDb, c.definitionKey) === ctx.chosenCategory
    ).length;
    if (count > 0) addEnergy(ctx.state, ctx.cardDb, ctx.source, count, 'power');
  },
});
