// Blygt's Ring -- "Purity: At the end of your turn, if all Spells in your discard pile are
// Bograth, discard all of your non-Bograth cards from play and choose an opposing Creature. If
// that Creature has more energy than your Magi's energize, move three energy from that Creature
// to your Magi."
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first opposing Creature whose energy
// exceeds the Magi's energize" simplification with a real pending choice (registry.ts's
// pendingTargetChoice/resolveTargetChoice) -- the pool is scoped to exactly the Creatures where
// choosing them does anything, same as before, just offered as a real prompt now instead of
// auto-picked. Uses the Magi's EFFECTIVE Energize rate (turn.ts's effectiveEnergizeRate), same
// convention as Thast's Ice Grinder.

import { registerCardEffect } from './registry.js';
import { applyPurity } from './purityRing.js';
import { rearrangeEnergy } from '../effects.js';
import { opposingCreatures } from '../targeting.js';
import { effectiveEnergizeRate } from '../turn.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const PURITY_PENDING = 'blygtsRingPurityPending';

function purityPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const player = state.players.get(self.controllerId);
  if (!player?.activeMagi) return [];
  const magiEnergize = effectiveEnergizeRate(state, cardDb, player.activeMagi);
  return opposingCreatures(state, cardDb, self.controllerId).filter((c) => (c.currentEnergy ?? 0) > magiEnergize);
}

registerCardEffect("Blygt's Ring", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, 'Bograth', rng)) return;
    if (purityPool(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, PURITY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(PURITY_PENDING)) return undefined;
    const pool = purityPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Blygt's Ring's Purity: choose an opposing Creature to move 3 energy from to your Magi", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, PURITY_PENDING);
    if (!chosenInstanceId) return;
    const player = state.players.get(self.controllerId);
    if (!player?.activeMagi) return;
    const target = purityPool(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
    if (target) rearrangeEnergy(state, cardDb, target, player.activeMagi, 3, rng);
  },
});
