// Hunter Furok -- two effects:
//   "Retrieve: Whenever Hunter Furok attacks a Magi, add energy to your Magi equal to the number
//   of the defending player's Relics in play." (afterCombat -- no "before/after" wording, and adds
//   to the attacker's OWN Magi, unrelated to this attack's own damage math)
//   "Chill: When Hunter Furok attacks, it removes two additional energy." (onAttack, unconditional
//   +2 to the locked attacker energy)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allRelicsInPlay } from '../targeting.js';

registerCardEffect('Hunter Furok', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Chill is the unconditional +2
  // attack damage; Retrieve is the Magi-attack post-combat energy gain.
  effectHooks: {
    Chill: ['onAttack'],
    Retrieve: ['afterCombat'],
  },
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    ctx.locked.attackerEnergy += 2;
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender !== null) return; // Retrieve is specifically a Magi attack
    const magi = ctx.attackingPlayer.activeMagi;
    if (!magi) return;
    const relicCount = allRelicsInPlay(ctx.state, ctx.cardDb).filter(
      (r) => r.controllerId === ctx.defendingPlayer.playerId
    ).length;
    if (relicCount > 0) addEnergy(ctx.state, ctx.cardDb, magi, relicCount, 'effect');
  },
});
