// Haunt (Spell, Core, cost 5) -- "Choose an opposing Creature. Attach Haunt to the chosen Creature.
// When that Creature is discarded, play it instead, ignoring all costs and regional restrictions.
// The Creature becomes Core instead of its original region(s). The Creature cannot attack the turn
// you play it." Task #53-5, 2026-07-21, the Core Spell pass's A3 gain-control cluster.
//
// spellStaysInPlay (Crystal Vision's mechanism) -- Haunt sits in its own controller's `inPlay`,
// tracking the target by instance id, same shape as Paranoia/Corrupt this same pass.
//
// "When that Creature is discarded, play it instead" -- reacts via the standard
// `onCardDiscardedFromPlay` broadcast, which fires AFTER the target has already moved to its
// OWNER's discard pile (registry.ts's own doc comment), then immediately pulls it back out via
// effects.ts's `playFromZone` (Shadow Fird's Feed precedent: `{ owner, zone: 'discardPile',
// instanceId }` -> `destination.inPlay`, starting energy set directly, no cost, no region-legality
// check at all since `playFromZone` never calls `isLegalToPlay`) -- "you play it" is Haunt's own
// controller, per the printed "the turn YOU play it," so `destination` is Haunt's controller, not
// the Creature's original owner.
//
// "Cannot attack the turn you play it" -- combat.ts's existing CANNOT_ATTACK duration tag, expiring
// at the end of THIS turn (`state.turnNumber`), same "not the turn played" shape Bubble Xyx's
// CANNOT_USE_POWER already uses for Powers.
//
// Haunt itself is discarded once its watched Creature leaves play this way (its job is done) --
// same self-discard-after-firing shape Harror/Paranoia use elsewhere this pass.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, effectiveStartingEnergy } from '../targeting.js';
import { playFromZone, discardFromPlay } from '../effects.js';
import { addPermanentTag, removePermanentTag, addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

const TARGET_PREFIX = 'hauntTarget:';

function trackedTargetId(self: { tags: ReadonlySet<string> }): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(TARGET_PREFIX));
  return tag ? tag.slice(TARGET_PREFIX.length) : undefined;
}

registerCardEffect('Haunt', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${TARGET_PREFIX}${ctx.chosenTargetId}`);
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, _cause, _source, _causedByPlayerId, rng) => {
    const targetId = trackedTargetId(self);
    if (!targetId || discarded.instanceId !== targetId) return;
    removePermanentTag(self, `${TARGET_PREFIX}${targetId}`);

    const owner = state.players.get(discardedOwnerId);
    const hauntController = state.players.get(self.controllerId);
    if (owner && hauntController) {
      const startingEnergy = effectiveStartingEnergy(state, cardDb, discarded);
      const played = playFromZone(state, cardDb, { owner, zone: 'discardPile', instanceId: discarded.instanceId }, hauntController, startingEnergy, rng);
      if (played) {
        played.effectiveRegionOverride = { region: 'Core' };
        addRestrictionTag(state, played, CANNOT_ATTACK, state.turnNumber);
      }
    }

    if (hauntController && hauntController.inPlay.some((c) => c.instanceId === self.instanceId)) {
      discardFromPlay(state, cardDb, hauntController, self.instanceId, undefined, undefined, rng);
    }
  },
});
