// Crystal Jile -- "Earthbound (4): Choose any Magi in play. Add six energy to the chosen Magi."

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Crystal Jile', {
  powerTargets: (state) => allMagiInPlay(state),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Earthbound') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;

    addEnergy(ctx.state, ctx.cardDb, target, 6, 'power');
  },
});
