// Shadow Rain (Spell, Core, cost 2) -- "Choose any one of your Creatures in play. Transfer all of
// the energy on your Magi to the chosen Creature. At the end of your Attack Step, transfer all
// energy from the chosen Creature your Magi, and draw one card. Naroom Magi may play Shadow Rain."
// Task #53-7, 2026-07-21, the Core Spell pass's A4 batch.
//
// spellStaysInPlay (Crystal Vision's mechanism), tracking the target by instance id -- same shape
// as Paranoia/Stealth this pass. "At the end of your Attack Step" reuses the existing
// `onOwnAttackStepEnd` hook (Porphin/Storm Wings precedent), scoped to the CASTER's own turn since
// that broadcast only ever fires for the active player's own board. Discards itself once the
// delayed transfer fires -- its job is done for the rest of the game, matching "at the end of your
// Attack Step" being a same-turn, one-shot trailing effect rather than a recurring one.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { addEnergy, discardEnergy, drawCards, discardFromPlay } from '../effects.js';
import { addPermanentTag } from '../durationTags.js';

const TARGET_PREFIX = 'shadowRainTarget:';

function trackedTargetId(self: { tags: ReadonlySet<string> }): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(TARGET_PREFIX));
  return tag ? tag.slice(TARGET_PREFIX.length) : undefined;
}

registerCardEffect('Shadow Rain', {
  spellTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const target = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    const magi = ctx.controllingPlayer.activeMagi;
    if (!target || !magi) return;

    const amount = magi.currentEnergy ?? 0;
    if (amount > 0) {
      discardEnergy(ctx.state, ctx.cardDb, magi, amount, 'spell', undefined, ctx.rng);
      addEnergy(ctx.state, ctx.cardDb, target, amount, 'spell');
    }
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${TARGET_PREFIX}${target.instanceId}`);
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  onOwnAttackStepEnd: (state, cardDb, self, rng) => {
    const targetId = trackedTargetId(self);
    if (!targetId) return;
    const owner = state.players.get(self.controllerId);
    if (!owner || !owner.inPlay.some((c) => c.instanceId === self.instanceId)) return;

    const target = owner.inPlay.find((c) => c.instanceId === targetId);
    const magi = owner.activeMagi;
    if (target && magi) {
      const amount = target.currentEnergy ?? 0;
      if (amount > 0) {
        discardEnergy(state, cardDb, target, amount, 'spell');
        addEnergy(state, cardDb, magi, amount, 'spell');
      }
    }
    drawCards(state, cardDb, owner, 1);
    discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
  },
});
