// Weave Arboll -- both printed effects:
//   "Weave's Gift: After Weave Arboll is defeated in an attack, add one energy to each of your
//   Creatures with the effect 'Weave'." Checked against the card's own static `effects[]` list
//   (already available on the definition) rather than a registry lookup -- this only needs to
//   know WHICH cards print the ability, not execute it.
//   "Weave: As Weave Arboll attacks or is attacked, before energy is removed, you may move one
//   energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { applyWeave } from './weave.js';

registerCardEffect('Weave Arboll', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Weave's Gift is the on-defeat energy
  // grant to other Weave Creatures; Weave carries the move hook + `weaveConfig`.
  effectHooks: {
    "Weave's Gift": ['afterCombat'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
  afterCombat: (ctx, outcome, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    if (outcome.defenderSurvived) return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, self.controllerId)) {
      const def = ctx.cardDb.get(creature.definitionKey);
      if (def?.effects.some((e) => e.name === 'Weave')) {
        addEnergy(ctx.state, ctx.cardDb, creature, 1, 'effect');
      }
    }
  },
});
