// Terkoz -- "Spotlight: At the end of your turn, if Terkoz was the only Creature you played this
// turn, add one energy to each of your Creatures." First user of CardInstance's new
// playedOnTurnNumber field (types/instance.ts), stamped by play.ts's playCard.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';

registerCardEffect('Terkoz', {
  onOwnTurnEnd: (state, cardDb, self) => {
    if (self.playedOnTurnNumber !== state.turnNumber) return;
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    const othersPlayedThisTurn = own.some(
      (c) => c.instanceId !== self.instanceId && c.playedOnTurnNumber === state.turnNumber
    );
    if (othersPlayedThisTurn) return;

    for (const creature of own) {
      addEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
});
