// Remember Ring -- "Good Ol' Days (0): Discard Remember Ring from play. Put a Naroom Creature from
// your discard pile into play with one energy. That Creature may not attack this turn."

import { registerCardEffect } from './registry.js';
import { discardFromPlay, playFromZone } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { regionForTargetFilter } from '../targeting.js';

registerCardEffect('Remember Ring', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, 'Naroom'));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Good Ol' Days") return;
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
    if (!def || def.card_type !== 'Creature' || !def.regions.includes(regionForTargetFilter(ctx.state, 'Naroom'))) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'discardPile', instanceId: id! },
      ctx.controllingPlayer,
      1
    , ctx.rng);
    if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Naroom'],
});
