// Baldar -- "Smash: Whenever Baldar attacks a Creature that starts the attack with less energy
// than Baldar, Baldar loses no energy in the attack." Checked against the snapshot (both sides'
// energy at declare time), then zeroes what Baldar (the attacker) takes back -- that's
// ctx.locked.defenderEnergy, since combat.ts's step 7 computes the attacker's own loss from it.

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';

registerCardEffect('Baldar', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    if (ctx.snapshot.defenderEnergy >= ctx.snapshot.attackerEnergy) return;
    if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = 0;
  },
});
