// Thunder Hyren -- two Powers.
// "Shockstorm (6): Discard two energy from each non-Arderial Creature in play."
// "Replenish (2): Discard Thunder Hyren from play. Add two energy to each of your hyren in play."
// Name-family match ("Hyren"), same established pattern as Monarch Hyren's Command. Previously
// Replenish had no branch in resolvePower at all -- cost was paid but nothing happened, a silent
// fizzle caught in playtesting (PROGRESS_LOG.md, 2026-07-09).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Thunder Hyren', {
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Shockstorm') {
      for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
        if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Arderial'))) {
          discardEnergy(ctx.state, ctx.cardDb, creature, 2, undefined, undefined, ctx.rng);
        }
      }
    } else if (ctx.powerName === 'Replenish') {
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
      for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
        if (ctx.cardDb.get(creature.definitionKey)?.name.includes('Hyren')) {
          addEnergy(ctx.state, ctx.cardDb, creature, 2, 'power');
        }
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Only Shockstorm's region literal is in scope -- Replenish's
  // "Hyren" check is a name family, not a region.
  specifiedTargetRegions: () => ['Arderial'],
});
