// Borgor -- "Sever (6): Choose any two Creatures in play. Discard half of the energy from each
// of the chosen Creatures, rounded up." Both picks undergo the identical operation, so unlike
// Qwade there's no order-dependent role -- a plain "exactly two from one pool" slot.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Borgor', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose two Creatures in play',
      pool: (s, db, pid) => flexibleTargetPool(s, db, pid, allCreaturesInPlay(s, db), allMagiInPlay(s)),
      min: 2,
      max: 2,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Sever') return;
    const chosen = ctx.chosenSlotIds?.[0];
    if (!chosen || chosen.length !== 2 || chosen[0] === chosen[1]) return;

    for (const id of chosen) {
      const target = findCreatureOrMagiById(ctx.state, id);
      // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
      if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    }
    // Defect 7 (fuzz run 2026-08-15, seed 4975 crash): the validation loop above guarantees both
    // targets exist at THAT moment, but each `discardEnergy` below can defeat its own Creature and
    // cascade through onCardDiscardedFromPlay hooks / Sinder's Mantle / attached-card triggers that
    // remove OTHER Creatures from play -- including this Power's own second target. The pre-fix
    // `!` was TypeScript-only and did not stop the resulting `undefined.currentEnergy` at runtime.
    // Card text: "Discard half of the energy from each of the chosen Creatures" -- so if one of the
    // chosen has left play by the time we get to it, skip it and continue with whichever remains.
    // The energy IS measured after any prior cascade in the batch; that is the intended semantic
    // and matches the same "resolve one target at a time, current state each read" pattern every
    // other multi-target discardEnergy in the codebase already uses.
    for (const id of chosen) {
      const target = findCreatureOrMagiById(ctx.state, id);
      if (!target) continue;
      discardEnergy(ctx.state, ctx.cardDb, target, Math.ceil((target.currentEnergy ?? 0) / 2), undefined, undefined, ctx.rng);
    }
  },
});
