// Orpus -- "Relic Guard: If your opponent discards one of your Relics from play, you may discard
// one energy from Orpus instead of discarding the Relic." registry.ts's preventsDiscardOf --
// protects ANOTHER card (any of its own controller's Relics), paying its own energy as the side
// effect of claiming the protection. Auto-taken whenever Orpus has energy to pay, matching this
// codebase's "auto-take when it's an unambiguous positive trade" convention -- saving a Relic for
// 1 energy is always worth it.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Orpus', {
  preventsDiscardOf: (state, cardDb, target, self) => {
    if (target.controllerId !== self.controllerId) return false;
    if (cardDb.get(target.definitionKey)?.card_type !== 'Relic') return false;
    if ((self.currentEnergy ?? 0) < 1) return false;

    discardEnergy(state, cardDb, self, 1, 'effect', self.controllerId);
    return true;
  },
});
