// Raxis -- "Shatterfire (1): Choose any one Relic in play. The Relic's controller may discard
// four energy from his or her Magi. If he or she doesn't, discard the chosen Relic from play."

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, findInPlayById } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Raxis', {
  powerTargets: (state, cardDb) => allRelicsInPlay(state, cardDb),
  booleanChoice: {
    prompt: 'Discard 4 energy from your Magi to save this Relic?',
    yesLabel: 'Pay 4 from Magi',
    noLabel: 'Let the Relic go',
    respondingPlayer: 'opponent',
    // The payer is the TARGET Relic's controller, not Raxis' controller.
    yesUnavailableReason: (state, cardDb, playerId, chosenTargetId) => {
      const relic = chosenTargetId ? findInPlayById(state, chosenTargetId) : undefined;
      const owner = relic && state.players.get(relic.controllerId);
      const have = owner?.activeMagi?.currentEnergy ?? 0;
      return have >= 4 ? undefined : `Your Magi has only ${have} energy -- 4 is required`;
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shatterfire') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Relic') return;
    const targetOwner = ctx.state.players.get(target.controllerId);
    if (!targetOwner) return;

    // Playtest 2026-07-26: a Magi with only 1 energy could still pick "Pay 4 from Magi". The
    // payment then clamped (discardEnergy takes what's there), so the Relic was saved for less than
    // the printed price -- Kalius went 1 -> 0 and kept the Relic, while the log said "loses 4".
    //
    // The card reads "the Relic's controller MAY discard four energy... If he or she DOESN'T,
    // discard the chosen Relic." Being unable to discard four means they have not discarded four,
    // so the Relic goes. Falling through to the else branch is the faithful reading, not a refusal
    // of the whole Power.
    const canAfford = (targetOwner.activeMagi?.currentEnergy ?? 0) >= 4;
    if (ctx.chosenBoolean && canAfford) {
      discardEnergy(ctx.state, ctx.cardDb, targetOwner.activeMagi!, 4, undefined, undefined, ctx.rng);
    } else {
      discardFromPlay(ctx.state, ctx.cardDb, targetOwner, target.instanceId, undefined, undefined, ctx.rng);
    }
  },
});
