// Dark Ayebaw -- "Implode: Choose any one Creature or Magi in play. Discard Dark Ayebaw from
// play, and discard X Core and/or Arderial cards from your hand. Discard X+2 energy from the
// chosen Creature or Magi." The Power itself has no printed energy cost -- X here is purely an
// effect-text count the player chooses (handDiscardCost.count: 'X' reuses the same chosenXValue
// the UI already collects for X-cost Powers).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById, regionForTargetFilter } from '../targeting.js';
import { discardEnergy, discardFromHand, discardFromPlay } from '../effects.js';

registerCardEffect('Dark Ayebaw', {
  powerTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)],
  handDiscardCost: {
    count: 'X',
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return !!def && (def.regions.includes(regionForTargetFilter(state, 'Core')) || def.regions.includes(regionForTargetFilter(state, 'Arderial')));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Implode') return;
    if (ctx.chosenTargetId === undefined) return;
    if (ctx.chosenXValue === undefined || ctx.chosenXValue < 0) return;
    const chosenCards = ctx.chosenHandCardIds ?? [];
    if (chosenCards.length !== ctx.chosenXValue) return;
    for (const id of chosenCards) {
      const card = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
      const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
      if (!def || !(def.regions.includes(regionForTargetFilter(ctx.state, 'Core')) || def.regions.includes(regionForTargetFilter(ctx.state, 'Arderial')))) return;
    }
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, chosenCards, undefined, ctx.rng);
    // Dark Ayebaw itself may have been the chosen target -- it's already gone from play by now,
    // so re-fetch rather than trust the earlier lookup.
    const stillThere = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!stillThere) return;
    discardEnergy(ctx.state, ctx.cardDb, stillThere, ctx.chosenXValue + 2, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Core', 'Arderial'],
});
