// Dey -- "Balance: If you have fewer Creatures in play than any opponent, each opposing Creature
// costs two additional energy to play" (registry.ts's costModifier). Condition re-evaluated live
// against current board state on every play attempt, not stored.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';

registerCardEffect('Dey', {
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId === self.controllerId) return 0;
    if (playedDef.card_type !== 'Creature') return 0;
    const ownCount = creaturesControlledBy(state, cardDb, self.controllerId).length;
    const hasFewerThanSomeOpponent = [...state.players.values()].some(
      (p) => p.playerId !== self.controllerId && creaturesControlledBy(state, cardDb, p.playerId).length > ownCount
    );
    return hasFewerThanSomeOpponent ? 2 : 0;
  },
});
