// Koll -- "Dream Twist: Discard your largest Creature from play (in the case of a tie, you choose
// which one to discard). Search your deck for any one Kybar's Teeth Creature with starting energy
// less than the discarded Creature's starting energy. Play the chosen Creature with its starting
// energy. That Creature may not attack this turn." Tie-break falls back to largestCreatureControlledBy's
// own array-order convention (same tradeoff smallestOf-based cards already accept).

import { registerCardEffect } from './registry.js';
import { largestCreatureControlledBy, printedStartingEnergy, regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay, searchDeckIntoPlay } from '../effects.js';
import { shuffleDeck } from '../zones.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Koll', {
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, "Kybar's Teeth"));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Twist') return;
    const largest = largestCreatureControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (!largest) return;
    const discardedStarting = effectiveStartingEnergy(ctx.state, ctx.cardDb, largest);

    const searchIds = ctx.chosenDeckSearchIds ?? [];
    if (searchIds.length > 1) return;
    for (const id of searchIds) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
      if (!def || def.card_type !== 'Creature' || !def.regions.includes(regionForTargetFilter(ctx.state, "Kybar's Teeth"))) return;
      if (effectiveStartingEnergy(ctx.state, ctx.cardDb, card!) >= discardedStarting) return;
    }

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, largest.instanceId, undefined, undefined, ctx.rng);
    for (const id of searchIds) {
      const key = ctx.controllingPlayer.deck.find((c) => c.instanceId === id)?.definitionKey;
      if (key === undefined) continue;
      const played = searchDeckIntoPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, id, printedStartingEnergy(ctx.cardDb, key), true, ctx.rng);
      if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
    }
    shuffleDeck(ctx.controllingPlayer, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ["Kybar's Teeth"],
});
