// Scarletsong Banner -- "Morale Boost: Increase your energize by one. Draw an extra card during
// your Draw step." The extra draw is registry.ts's drawCountModifier (2026-07-11).
//
// "After an opposing card removes energy from your Magi, discard Scarletsong Banner from play."
// Built task #37 (Paradwyn pass, Category C, 2026-07-17) via the same
// onOwnMagiLostEnergyFromOpposingCard hook used by Dasia's Salvage.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Scarletsong Banner', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  energizeRateModifier: (state, cardDb, energizing, self) => {
    const owner = state.players.get(self.controllerId);
    if (owner?.activeMagi?.instanceId !== energizing.instanceId) return 0;
    return 1;
  },
  drawCountModifier: (state, cardDb, self) => 1,
  onOwnMagiLostEnergyFromOpposingCard: (state, cardDb, self, magi, amount, rng) => {
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    discardFromPlay(state, cardDb, owner, self.instanceId, self.controllerId, 'effect', rng);
  },
});
