// Blizzard Core -- "Coriolis: At the beginning of your Energize step, before you energize, choose
// a Magi. If that Magi has no Creatures in play and your Magi has more energy than the chosen
// Magi's starting energy, discard Blizzard Core and defeat the chosen Magi." Built task #43,
// 2026-07-18, the Nar region pass -- Category D, own design checkpoint. A genuinely new "defeat a
// Magi outside the normal 0-energy-and-0-Creatures check, triggered by a THIRD PARTY at an
// unrelated timing" shape -- `customDefeatCondition` (Korg/Erisa/Kyg'n) only replaces the check
// for the Magi's OWN controller reacting to their OWN Magi's state, not this. Calls
// `energy.ts#defeatMagi` directly from the new `onOwnEnergizeStepStart` hook (registry.ts/turn.ts,
// built for exactly this card).
// "Choose a Magi" has no "opposing" qualifier in the printed text -- the FULL pool (either side,
// including the controller's own Magi), via a real pendingTargetChoice, same "don't guess a
// restriction the text doesn't state" discipline as Nagsis' Sigil's own "choose any Magi" precedent.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { defeatMagi, checkMagiDefeats } from '../energy.js';
import { allMagiInPlay, effectiveStartingEnergy } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const CORIOLIS_PENDING = 'blizzardCoreCoriolisPending';

registerCardEffect('Blizzard Core', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  onOwnEnergizeStepStart: (state, cardDb, self) => {
    if (allMagiInPlay(state).length === 0) return;
    addPendingChoiceTag(self, CORIOLIS_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(CORIOLIS_PENDING)) return undefined;
    const pool = allMagiInPlay(state);
    if (pool.length === 0) return undefined;
    return { prompt: "Blizzard Core's Coriolis: choose a Magi", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, CORIOLIS_PENDING);
    if (!chosenInstanceId) return;
    const chosenMagi = allMagiInPlay(state).find((m) => m.instanceId === chosenInstanceId);
    if (!chosenMagi) return;
    const chosenOwner = state.players.get(chosenMagi.controllerId);
    if (!chosenOwner || chosenOwner.activeMagi?.instanceId !== chosenMagi.instanceId) return;
    const hasCreatures = chosenOwner.inPlay.some((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature');
    if (hasCreatures) return;
    const selfOwner = state.players.get(self.controllerId);
    const ownMagi = selfOwner?.activeMagi;
    if (!selfOwner || !ownMagi) return;
    const chosenStartingEnergy = effectiveStartingEnergy(state, cardDb, chosenMagi);
    if ((ownMagi.currentEnergy ?? 0) <= chosenStartingEnergy) return;

    discardFromPlay(state, cardDb, selfOwner, self.instanceId, undefined, undefined, rng);
    defeatMagi(state, cardDb, chosenOwner, rng);
    // defeatMagi's own doc comment: "Callers should follow up with checkMagiDefeats (or
    // checkForDefeats) to run the normal win-check machinery." Missing this left a fuzzed game
    // running past a player's actual last-Magi elimination with state.winnerId never set --
    // confirmed live (2026-08-01) via a crash several moves later ("no Magi left to reveal, game
    // should already be over") once the game tried to advance a turn nobody should have reached.
    checkMagiDefeats(state, cardDb, rng);
  },
});
