// Pagajack -- both printed effects:
//   "Familiarity: When you play Pagajack, add two energy to it for each other Pagajack in play."
//   "Weave: Whenever Pagajack attacks or is attacked, before energy is removed, you may move one
//   energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { applyWeave } from './weave.js';

registerCardEffect('Pagajack', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Familiarity is the ETB per-copy buff;
  // Weave is the move hook + `weaveConfig`.
  effectHooks: {
    Familiarity: ['onPlay'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    const otherPagajacks = creaturesControlledBy(state, cardDb, self.controllerId).filter(
      (c) => c.instanceId !== self.instanceId && cardDb.get(c.definitionKey)?.name === 'Pagajack'
    ).length;
    if (otherPagajacks > 0) addEnergy(state, cardDb, self, otherPagajacks * 2, 'effect');
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
});
