// Sandtrap (Spell) -- "Choose a Creature without any Spells attached and attach Sandtrap to it.
// While Sandtrap is attached, that Creature loses one energy at the beginning of each player's
// turn." spellStaysInPlay (Volt Shield's exact mechanism) for the attach half. The "beginning of
// EACH player's turn" clause is a direct, already-existing reuse: registry.ts's ticksWhileAttached
// hook already fires at the start of every turn, either player's, for any card sitting in another
// card's attachedCards (built for Tar Hyren's Cling, dispatched from turn.ts's
// runStartOfTurnHooks) -- no new mechanism needed at all.

import { registerCardEffect } from './registry.js';
import { attachCard } from '../attachedCards.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Sandtrap', {
  spellTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter((c) => c.attachedCards.length === 0),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.attachedCards.length > 0) return;
    attachCard(target, ctx.source);
  },
  ticksWhileAttached: (state, cardDb, self, holder, rng) => {
    // Self-caused (Tar Hyren's Cling precedent), not "opposing" from either side -- a passive
    // drain that fires on EVERY turn regardless of whose it is, not something either player did.
    discardEnergy(state, cardDb, holder, 1, 'effect', holder.controllerId, rng);
  },
});
