// Iyori -- "Lost Wisdom: Discard one card from your hand. Choose any one player. The chosen
// player discards one card at random from his or her hand." Combines handDiscardCost (own hand,
// fixed count 1) with a target's random discard (effects.ts's discardRandomFromHand, first built
// for Hasseth).

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardFromHand, discardRandomFromHand } from '../effects.js';

registerCardEffect('Iyori', {
  powerTargets: (state) => allMagiInPlay(state),
  handDiscardCost: { count: 1 },
  causesOpponentHandDiscard: true, // task #718 (Riptide clause 2, 2026-08-11): banned under Riptide.

  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Lost Wisdom') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const targetOwner = ctx.state.players.get(chosenMagi.controllerId);
    if (!targetOwner) return;
    const ownIds = (ctx.chosenHandCardIds ?? []).filter((id) => ctx.controllingPlayer.hand.some((c) => c.instanceId === id));
    if (ownIds.length !== 1) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ownIds, undefined, ctx.rng);
    discardRandomFromHand(ctx.state, ctx.cardDb, targetOwner, 1, ctx.rng);
  },
});
