// Jumbor -- "Weave: Whenever Jumbor attacks or is attacked, before energy is removed, you may
// move one energy between it and one of your other Weave Creatures in play." (see weave.ts)
// "Taunt: Choose any one player. Each of the chosen player's Creatures must attack during that
// player's next Attack Step, if able." Built task #44 Part B, 2026-07-18 (must-attack enforcement
// architecture). No printed energy cost (real, not a data gap -- power.ts already treats a
// missing cost as 0, per Power's own doc comment). "Any one player" has no "opposing" qualifier,
// so the pool is BOTH players' Magi (same "choose a Magi" precedent as Blizzard Core's Coriolis,
// task #43) -- each Magi stands in for its controller, since Powers only target CardInstances,
// not player ids directly. Tags every Creature the chosen player CURRENTLY controls -- a Creature
// played by that player later, before their next turn, is not retroactively caught (same "state
// at resolution time" reading as every other targeted effect in this engine).

import { registerCardEffect } from './registry.js';
import { applyWeave } from './weave.js';
import { allMagiInPlay } from '../targeting.js';
import { addDurationTag, MUST_ATTACK_THIS_TURN, nextTurnNumberFor } from '../durationTags.js';

registerCardEffect('Jumbor', {
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
  powerTargets: (state) => allMagiInPlay(state),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Taunt') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!chosenMagi) return;
    const chosenOwner = ctx.state.players.get(chosenMagi.controllerId);
    if (!chosenOwner) return;
    const expiry = nextTurnNumberFor(ctx.state, chosenOwner.playerId);
    for (const creature of chosenOwner.inPlay) {
      if (ctx.cardDb.get(creature.definitionKey)?.card_type !== 'Creature') continue;
      addDurationTag(ctx.state, ctx.cardDb, creature, MUST_ATTACK_THIS_TURN, expiry);
    }
  },
});
