// Weeblit -- "Season: Choose any one Weebo and any one other Creature in play. Discard Weeblit
// and the chosen Weebo from play. Add five energy to the other chosen Creature." Neither pick is
// restricted to "your" in the printed text, so both pools are unrestricted by controller.
//
// Swirling Orshaa's Morph (Spell-pass audit follow-up, 2026-07-24) -- routed through
// matchesCreatureFamily() (checks a live Morph identityOverride first, falls back to the printed
// name substring), same reasoning as Xyx Minor.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, matchesCreatureFamily } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Weeblit', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargetSlots: (state, cardDb) => [
    {
      label: 'Choose a Weebo',
      pool: (s, db) => allCreaturesInPlay(s, db).filter((c) => matchesCreatureFamily(db, c, 'Weebo')),
      min: 1,
      max: 1,
    },
    {
      label: 'Choose any other Creature in play',
      pool: (s, db, pid, priorChoices) => allCreaturesInPlay(s, db).filter((c) => c.instanceId !== priorChoices[0]?.[0]),
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Season') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const weeboId = slots[0]?.[0];
    const otherId = slots[1]?.[0];
    if (!weeboId || !otherId || weeboId === otherId) return;

    const weebo = findInPlayById(ctx.state, weeboId);
    if (!weebo || ctx.cardDb.get(weebo.definitionKey)?.card_type !== 'Creature') return;
    if (!matchesCreatureFamily(ctx.cardDb, weebo, 'Weebo')) return;
    const other = findInPlayById(ctx.state, otherId);
    if (!other || ctx.cardDb.get(other.definitionKey)?.card_type !== 'Creature') return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const weeboOwner = ctx.state.players.get(weebo.controllerId);
    if (weeboOwner) discardFromPlay(ctx.state, ctx.cardDb, weeboOwner, weebo.instanceId, undefined, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, other, 5, 'power');
  },
  specifiedCreatureTypes: () => ['Weebo'],
});
