// Firestorm Orish -- "Firestorm: Choose one of your Cald or Arderial Creatures in play. Discard
// two energy from the chosen Creature to add three energy to any one of your other Creatures in
// play." Slot 2 depends on slot 1 only to exclude whatever was picked there ("other" than the
// first choice) -- the simpler, exclusion-only flavor of slot dependency (vs. Rask Deserter's
// pool-changes-entirely dependency).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Firestorm Orish', {
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- this slot (the donor)
      // feeds discardEnergy; the receiver slot below feeds addEnergy and stays Creature-only.
      label: 'Choose one of your Cald or Arderial Creatures',
      pool: (s, db, pid) => {
        const caldRegion = regionForTargetFilter(s, 'Cald');
        const arderialRegion = regionForTargetFilter(s, 'Arderial');
        const ownMagi = s.players.get(pid)?.activeMagi;
        const regions = ownMagi ? effectiveRegions(s, db, ownMagi) : [];
        const ownEligibleMagi = ownMagi && (regions.includes(caldRegion) || regions.includes(arderialRegion)) ? [ownMagi] : [];
        return flexibleTargetPool(
          s,
          db,
          pid,
          creaturesControlledBy(s, db, pid).filter((c) => {
            const r = effectiveRegions(s, db, c);
            return r.includes(caldRegion) || r.includes(arderialRegion);
          }),
          ownEligibleMagi
        );
      },
      min: 1,
      max: 1,
    },
    {
      label: 'Choose one of your OTHER Creatures to receive the energy',
      pool: (s, db, pid, priorChoices) =>
        creaturesControlledBy(s, db, pid).filter((c) => c.instanceId !== priorChoices[0]?.[0]),
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Firestorm') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const donorId = slots[0]?.[0];
    const receiverId = slots[1]?.[0];
    if (!donorId || !receiverId || donorId === receiverId) return;

    const donor = findCreatureOrMagiById(ctx.state, donorId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!donor || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, donor, 'Creature')) return;
    if (donor.controllerId !== ctx.controllingPlayer.playerId) return;
    const donorRegions = effectiveRegions(ctx.state, ctx.cardDb, donor);
    if (!donorRegions.includes(regionForTargetFilter(ctx.state, 'Cald')) && !donorRegions.includes(regionForTargetFilter(ctx.state, 'Arderial'))) return;
    const receiver = findCreatureOrMagiById(ctx.state, receiverId);
    if (!receiver || ctx.cardDb.get(receiver.definitionKey)?.card_type !== 'Creature') return;
    if (receiver.controllerId !== ctx.controllingPlayer.playerId) return;

    discardEnergy(ctx.state, ctx.cardDb, donor, 2, undefined, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, receiver, 3, 'power');
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (The receiver slot is any OTHER own Creature, unrestricted
  // -- only the donor slot's Cald-or-Arderial filter is in scope.)
  specifiedTargetRegions: () => ['Cald', 'Arderial'],
});
