// Orathan -- "If Orathan attacks a Creature with less than three energy, add two energy to
// Orathan before energy is removed." Self as the attacker, reads the defender's energy at the
// moment onAttack fires (before locked energy is computed) -- same shape as Rudwot.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Orathan', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    if ((ctx.defender.currentEnergy ?? 0) >= 3) return;

    addEnergy(ctx.state, ctx.cardDb, self, 2, 'effect');
  },
});
