// Ebylon -- "Shatterwave: Choose any one Relic in play. Discard the chosen Relic from play."

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Ebylon', {
  powerTargets: (state, cardDb) => allRelicsInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shatterwave') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Relic') return;

    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
