// Lava Arboll -- "Healing Flame (2): Choose any one Creature or Magi in play. Discard Lava Arboll
// from play. Add three energy to the chosen Creature or Magi."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Lava Arboll', {
  powerTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Healing Flame') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!findCreatureOrMagiById(ctx.state, ctx.chosenTargetId)) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    addEnergy(ctx.state, ctx.cardDb, target, 3, 'power');
  },
});
