// Shaper's Apprentice -- "Dream Twist (4): Choose any one of your Creatures in play. Discard the
// chosen Creature to play any Kybar's Teeth or Orothe Creature from your discard pile ignoring all
// costs. Discard this Creature from play at the end of your next Energize Step." Region-audit
// follow-up, 2026-07-24 -- "this Creature" is the one just played from the discard pile (NOT
// Shaper's Apprentice herself), scheduled via the new GameState.scheduledEnergizeStepDiscards
// future-turn-trigger primitive (see that field's own doc comment in types/state.ts). "Your next
// Energize Step" is next turn's -- this turn's own Energize Step has already passed by the time a
// Power resolves -- so dueTurnNumber uses durationTags.ts's nextOwnTurnNumber, not
// beginningOfNextOwnTurnNumber (which would resolve to THIS turn).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay, playFromZone } from '../effects.js';
import { nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect("Shaper's Apprentice", {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return (
        def?.card_type === 'Creature' &&
        (def.regions.includes(regionForTargetFilter(state, "Kybar's Teeth")) || def.regions.includes(regionForTargetFilter(state, 'Orothe')))
      );
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Twist') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = ctx.controllingPlayer.inPlay.find(
      (c) => c.instanceId === ctx.chosenTargetId && ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature'
    );
    if (!target) return;
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
    if (
      !def ||
      def.card_type !== 'Creature' ||
      !(def.regions.includes(regionForTargetFilter(ctx.state, "Kybar's Teeth")) || def.regions.includes(regionForTargetFilter(ctx.state, 'Orothe')))
    )
      return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId, undefined, undefined, ctx.rng);
    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'discardPile', instanceId: id! },
      ctx.controllingPlayer,
      effectiveStartingEnergy(ctx.state, ctx.cardDb, card!)
    , ctx.rng);
    if (played) {
      ctx.state.scheduledEnergizeStepDiscards.push({
        instanceId: played.instanceId,
        playerId: ctx.controllingPlayer.playerId,
        dueTurnNumber: nextOwnTurnNumber(ctx.state),
      });
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (powerTargets above is the sacrifice-target picker, an
  // unrestricted "your own Creatures" pool -- only the discard-pile filter is in scope.)
  specifiedTargetRegions: () => ["Kybar's Teeth", 'Orothe'],
});
