// Ice Rupture (Spell) -- "Choose one of your frozen Nar Creatures. Discard your Creature to choose
// an opposing Magi and one of that Magi's Creatures. Discard as much energy as your frozen
// Creature had from each chosen card." Nar Spell pass, Category B (2026-07-22). Three
// dependency-chained picks (spellTargets -> spellSecondTargets -> spellThirdTargets, Shattershards'
// own precedent just above) -- the frozen Creature's currentEnergy has to be captured BEFORE it's
// discarded (discardFromPlay nulls currentEnergy), then applied to both the chosen Magi and the
// chosen Creature.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, discardEnergy } from '../effects.js';
import { allMagiInPlay, creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { isFrozen } from '../durationTags.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Ice Rupture', {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- reads the already-chosen chain
  // (own frozen Creature -> opposing Magi) the same way resolveSpell does, including the
  // amount > 0 gate (a 0-energy frozen Creature deals no damage), no execution.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options) => {
    const ownId = options.chosenTargetId as string | undefined;
    const magiId = options.chosenSecondTargetId as string | undefined;
    if (!ownId || !magiId) return false;
    const own = creaturesControlledBy(state, cardDb, actingPlayerId).find((c) => c.instanceId === ownId);
    if (!own || (own.currentEnergy ?? 0) <= 0) return false;
    const magi = allMagiInPlay(state).find((m) => m.instanceId === magiId);
    return !!magi && magi.controllerId !== actingPlayerId;
  },
  spellTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).filter(
      // In-play Creature check -- routes through effectiveRegions so Glablit's Dream Blur
      // (Category D EIGHTH item, 2026-08-12, task #725) applies.
      (c) => isFrozen(state, cardDb, c) && effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Nar'))
    ),
  spellSecondTargets: (state, cardDb, playerId) => {
    const opponentIds = new Set(getOpponents(state, playerId).map((p) => p.playerId));
    return allMagiInPlay(state).filter((m) => opponentIds.has(m.controllerId));
  },
  spellThirdTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId, secondChosenId) => {
    const magi = allMagiInPlay(state).find((m) => m.instanceId === secondChosenId);
    if (!magi) return [];
    return creaturesControlledBy(state, cardDb, magi.controllerId);
  },
  resolveSpell: (ctx) => {
    const own = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    const magi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenSecondTargetId);
    if (!own || !magi) return;
    const creature = creaturesControlledBy(ctx.state, ctx.cardDb, magi.controllerId).find(
      (c) => c.instanceId === ctx.chosenThirdTargetId
    );
    if (!creature) return;
    const amount = own.currentEnergy ?? 0;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, own.instanceId, undefined, 'spell', ctx.rng);
    if (amount > 0) {
      discardEnergy(ctx.state, ctx.cardDb, magi, amount, 'spell', undefined, ctx.rng);
      discardEnergy(ctx.state, ctx.cardDb, creature, amount, 'spell', undefined, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ['Nar'],
});
