// Yarothis -- "Scouring Gale (4): Choose any one Core Creature in play. Discard the chosen
// Creature from play." Region-filtered target pool (either player's Core Creatures).
// "Resistance: Core Spells and Powers do not affect Yarothis." Region-audit follow-up,
// 2026-07-24 -- direct reuse of registry.ts's blocksPowerEffectBySourceRegion, identical to
// Magor's own "Resistance: Core Spells and Powers do not affect Magor" (same printed text,
// one region over).

// Ashio's Weave Twist (2026-07-24): every "Core" reference above is Yarothis' OWN printed text, so
// under Ashio they mean its own region (Arderial) instead -- see targeting.ts's
// ashioAdjustedRegion doc comment.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, ashioAdjustedRegion, findInPlayById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { getPlayer } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

function isCoreCreature(state: GameState, cardDb: CardDatabase, instance: CardInstance): boolean {
  return effectiveRegions(state, cardDb, instance).includes(regionForTargetFilter(state, ashioAdjustedRegion(state, cardDb, 'Core', ['Arderial'])));
}

registerCardEffect('Yarothis', {
  blocksPowerEffectBySourceRegion: (state, cardDb) => {
    const sourceKey = state.currentAction?.sourceDefinitionKey;
    if (sourceKey === undefined) return false;
    const sourceDef = cardDb.get(sourceKey);
    return sourceDef?.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Arderial'])) ?? false;
  },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => isCoreCreature(state, cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Scouring Gale') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!isCoreCreature(ctx.state, ctx.cardDb, target)) return;
    discardFromPlay(ctx.state, ctx.cardDb, getPlayer(ctx.state, target.controllerId), target.instanceId, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: (state, cardDb) => [ashioAdjustedRegion(state, cardDb, 'Core', ['Arderial'])],
});
