// Comet Hyren -- "Bright Tail: Whenever Comet Hyren attacks, it removes twice as much energy as
// it has from the defending Creature." Doubles the locked attacker energy rather than reading
// Comet Hyren's raw currentEnergy directly, so it composes correctly with any other onAttack
// modifier that already adjusted ctx.locked.attackerEnergy before this one runs.

import { registerCardEffect } from './registry.js';

registerCardEffect('Comet Hyren', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    ctx.locked.attackerEnergy *= 2;
  },
});
