// Balamant -- "Hunt (2): Choose any one Magi in play. Discard four energy from the chosen Magi."
// Same shape as Xyx's Shock, but a distinct card.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Balamant', {
  powerTargets: (state) => allMagiInPlay(state),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Hunt') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;
    discardEnergy(ctx.state, ctx.cardDb, target, 4, undefined, undefined, ctx.rng);
  },
});
