// Jagt -- "Perpetual Motion: When you reveal Jagt, choose any one other player. All of your
// Effects that ordinarily happen at the beginning of your turn, instead happen at the beginning of
// the chosen player's turn." Built task #42, 2026-07-17, the Kybar's Teeth region pass -- identical
// mechanism to Gargagnor's own Perpetual Motion, just triggered by `onMagiRevealed` instead of
// `onPlay` (Jagt is a Magi). See gargagnor.ts and durationTags.ts's PERPETUAL_MOTION doc comment
// for the shared shape.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, PERPETUAL_MOTION } from '../durationTags.js';

registerCardEffect('Jagt', {
  onMagiRevealed: (state, cardDb, revealedMagi, self) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    addPermanentTag(state, cardDb, self, PERPETUAL_MOTION);
  },
});
