// Chaos Sphere -- two printed clauses:
//   "Impending: Whenever your Magi energizes, roll a die. Add Chaos Counters equal to the die
//   roll to Chaos Sphere." registry.ts's afterMagiEnergized (guarded to Chaos Sphere's OWN
//   controller's Magi -- "your Magi," unlike Nightmare Construct's Absorb which has no "your"
//   qualifier), storing the running total on CardInstance.counters (task #50f).
//   "Doom: Choose any one Magi in play. Discard 15 Chaos Counters from Chaos Sphere, and discard
//   Chaos Sphere from play. Discard from play all Creatures controlled by the chosen Magi." A
//   free-energy Power whose REAL cost is the 15 Chaos Counters -- resolvePower checks and pays
//   that itself (never wired through the normal energy-cost system), same "counters as a printed
//   physical resource" idea Evu's Jellybeans already established.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724): the Impending roll is
// Whimsy-interruptible via requestDieRoll like every other die roll.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { defaultRng } from '../rng.js';
import { allMagiInPlay } from '../targeting.js';

const CHAOS_COUNTERS = 'chaosCounters';
const DOOM_COST = 15;

registerCardEffect('Chaos Sphere', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  afterMagiEnergized: (state, cardDb, energizedMagi, self, _amount, rng) => {
    if (energizedMagi.controllerId !== self.controllerId) return;
    requestDieRoll(state, cardDb, self, self.controllerId, 6, 'chaosSphere:impending', {}, rng ?? defaultRng);
  },
  powerTargets: (state, cardDb, playerId, powerName) => (powerName === 'Doom' ? allMagiInPlay(state) : undefined),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Doom') return;
    if (ctx.chosenTargetId === undefined) return;
    if ((ctx.source.counters[CHAOS_COUNTERS] ?? 0) < DOOM_COST) return;
    const target = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!target) return;

    ctx.source.counters[CHAOS_COUNTERS] = (ctx.source.counters[CHAOS_COUNTERS] ?? 0) - DOOM_COST;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const targetController = ctx.state.players.get(target.controllerId);
    if (!targetController) return;
    for (const creature of [...targetController.inPlay]) {
      if (ctx.cardDb.get(creature.definitionKey)?.card_type !== 'Creature') continue;
      discardFromPlay(ctx.state, ctx.cardDb, targetController, creature.instanceId, undefined, undefined, ctx.rng);
    }
  },
});

registerRollConsumer('chaosSphere:impending', (state, cardDb, source, _payload, finalRoll) => {
  if (!source) return;
  source.counters[CHAOS_COUNTERS] = (source.counters[CHAOS_COUNTERS] ?? 0) + finalRoll;
});
