// O'Qua -- "Conjure: Search your deck for any Orothe Creature. Play the chosen Creature with four
// energy. The chosen Creature may not attack this turn." Plays with a FIXED 4 energy, not its own
// printed starting energy -- the one detail that differs from Grubble/Koll's shape.

import { registerCardEffect } from './registry.js';
import { searchDeckIntoPlay } from '../effects.js';
import { shuffleDeck } from '../zones.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { regionForTargetFilter } from '../targeting.js';

registerCardEffect("O'Qua", {
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, 'Orothe'));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Conjure') return;
    const searchIds = ctx.chosenDeckSearchIds ?? [];
    if (searchIds.length > 1) return;
    for (const id of searchIds) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
      if (!def || def.card_type !== 'Creature' || !def.regions.includes(regionForTargetFilter(ctx.state, 'Orothe'))) return;
    }

    for (const id of searchIds) {
      const played = searchDeckIntoPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, id, 4, true, ctx.rng);
      if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
    }
    shuffleDeck(ctx.controllingPlayer, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Orothe'],
});
