// Gloves of Crystal -- "Strengthen: Whenever you play an Underneath Creature, you may move one
// additional energy from your Magi to that Creature. If the Creature is a Bisiwog, you may move
// one additional energy to it."
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice`. The two printed "you
// may"s are the SAME resource (Magi energy) stacked back-to-back on the SAME action, unlike (say)
// Kioko's Motivate/Demotivate, which are independent strategic axes -- there's no real reason a
// rational player would take the first point but decline the second, so this is bundled into ONE
// yes/no covering the full eligible amount (1, or 2 for a Bisiwog) rather than two separate
// prompts. The just-played Creature is remembered via an embedded-id permanent tag (same technique
// as Reef Hyren/Skullek/Wellisk/Ahron in this same batch).

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { findInPlayById } from '../targeting.js';

const BISIWOG_FAMILY = /\bBisiwog\b/;
const PENDING_PREFIX = 'glovesOfCrystalPending:';

function pendingPlayedId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return tag.slice(PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Gloves of Crystal', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Creature') return;
    if (!def.regions.includes('Underneath')) return;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return;
    addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${played.instanceId}`);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    const playedId = pendingPlayedId(self);
    if (playedId === undefined) return undefined;
    const played = findInPlayById(state, playedId);
    if (!played) return undefined;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return undefined;
    const isBisiwog = BISIWOG_FAMILY.test(cardDb.get(played.definitionKey)!.name);
    return {
      prompt: `Gloves of Crystal's Strengthen: move ${isBisiwog ? 'up to two additional energy' : 'one additional energy'} from your Magi to the played Creature?`,
      yesLabel: isBisiwog ? 'Move up to 2' : 'Move 1',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const playedId = pendingPlayedId(self);
    if (playedId !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${playedId}`);
    if (!chosenBoolean || playedId === undefined) return;
    const played = findInPlayById(state, playedId);
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!played || !magi) return;
    const isBisiwog = BISIWOG_FAMILY.test(cardDb.get(played.definitionKey)!.name);
    const amount = isBisiwog ? 2 : 1;
    rearrangeEnergy(state, cardDb, magi, played, Math.min(amount, magi.currentEnergy ?? 0), rng);
  },
});
