// Megathan -- "Feed: Add one energy to Megathan at the end of any turn in which Megathan defeated
// one or more Creatures." A per-turn "did I defeat a Creature this turn" flag (task #50f's
// CardInstance.counters, same shape as Core Hyren's Dissect), set by afterCombat whenever Megathan
// destroyed the OTHER Creature in a fight -- as the attacker (defender didn't survive) OR as the
// defender via counter-damage (attacker didn't survive). Paid out (+1, flat, regardless of how many)
// and reset at the end of EVERY turn -- both onOwnTurnEnd and onOpponentTurnEnd, since "any turn"
// includes the opponent's (Megathan can defeat an attacker while defending on the opponent's turn).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const DEFEATED_THIS_TURN = 'megathanDefeatedThisTurn';

function payoutAndReset(state: GameState, cardDb: CardDatabase, self: CardInstance): void {
  if (self.counters[DEFEATED_THIS_TURN]) {
    addEnergy(state, cardDb, self, 1, 'effect');
  }
  self.counters[DEFEATED_THIS_TURN] = 0;
}

registerCardEffect('Megathan', {
  afterCombat: (ctx, outcome, self) => {
    const defeatedAsAttacker =
      ctx.attacker.instanceId === self.instanceId && !!ctx.defender && !outcome.defenderSurvived;
    const defeatedAsDefender =
      ctx.defender?.instanceId === self.instanceId && !outcome.attackerSurvived;
    if (defeatedAsAttacker || defeatedAsDefender) {
      self.counters[DEFEATED_THIS_TURN] = 1;
    }
  },
  onOwnTurnEnd: (state, cardDb, self) => payoutAndReset(state, cardDb, self),
  onOpponentTurnEnd: (state, cardDb, self) => payoutAndReset(state, cardDb, self),
});
