// Shattershards (Spell) -- "Choose a Magi in play. Discard one of the Magi's Relics. Remove
// energy from one of that Magi's Creatures equal to the Relic's cost, plus two." Nar Spell pass,
// Category B (2026-07-22). Three independent, dependency-chained picks (spellTargets ->
// spellSecondTargets -> spellThirdTargets, Kybar's Gift's own precedent) -- "the Magi's Relics"/
// "that Magi's Creatures" just means the CHOSEN MAGI'S CONTROLLER's Relics/Creatures (this engine
// only ever has one Magi in play per player at a time, so there's no separate per-Magi attachment
// tracking to do).

import { registerCardEffect } from './registry.js';
import { discardFromPlay, discardEnergy } from '../effects.js';
import { allMagiInPlay, allRelicsInPlay, creaturesControlledBy } from '../targeting.js';

registerCardEffect('Shattershards', {
  spellTargets: (state) => allMagiInPlay(state),
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) => {
    const magi = allMagiInPlay(state).find((m) => m.instanceId === firstChosenId);
    if (!magi) return [];
    return allRelicsInPlay(state, cardDb).filter((r) => r.controllerId === magi.controllerId);
  },
  spellThirdTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) => {
    const magi = allMagiInPlay(state).find((m) => m.instanceId === firstChosenId);
    if (!magi) return [];
    return creaturesControlledBy(state, cardDb, magi.controllerId);
  },
  resolveSpell: (ctx) => {
    const magi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!magi) return;
    const relic = allRelicsInPlay(ctx.state, ctx.cardDb).find((r) => r.instanceId === ctx.chosenSecondTargetId);
    const creature = creaturesControlledBy(ctx.state, ctx.cardDb, magi.controllerId).find(
      (c) => c.instanceId === ctx.chosenThirdTargetId
    );
    if (!relic || !creature) return;
    const relicCost = ctx.cardDb.get(relic.definitionKey)?.cost ?? 0;
    const relicOwner = ctx.state.players.get(relic.controllerId);
    if (relicOwner) discardFromPlay(ctx.state, ctx.cardDb, relicOwner, relic.instanceId, undefined, 'spell', ctx.rng);
    discardEnergy(ctx.state, ctx.cardDb, creature, (typeof relicCost === 'number' ? relicCost : 0) + 2, 'spell', undefined, ctx.rng);
  },
});
