// Gorgle's Glasses -- "Pyrovision: Whenever you discard all of an opposing Creature's energy with
// a Spell or Power, draw one card." Uses energy.ts's `source` distinction (2026-07-11, added
// specifically for this card) to exclude combat- and Effect-caused zero-energy defeats -- "with a
// Spell or Power" is read as "Power" in practice since Spells aren't implemented yet. "You discard"
// retrofitted (task #32, 2026-07-16) from the old `state.activePlayerId === self.controllerId`
// heuristic to the real `causedByPlayerId` param now available on `onCardDiscardedFromPlay`.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect("Gorgle's Glasses", {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (cause !== 'zero-energy' || (source !== 'power' && source !== 'spell')) return; // "with a Spell or Power"
    if (discardedOwnerId === self.controllerId) return; // must be an OPPOSING Creature
    if (causedByPlayerId !== self.controllerId) return; // must be caused by YOUR own Power
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Creature') return;

    const owner = state.players.get(self.controllerId);
    if (owner) drawCards(state, cardDb, owner, 1);
  },
});
