// Moga Boots -- "Kickback: The first time your Magi is attacked each turn, you may discard a card
// from your hand. If you do, discard the attacking Creature from play, before energy is removed."
// Built task #42, 2026-07-17, the Kybar's Teeth region pass. "Before energy is removed" and a
// direct-Magi-attack trigger -> `pendingPreCombatTargetChoice` family (Ugger's precedent for the
// third-party-reactor shape, `combat.ts`'s own doc comment: `defender` is `undefined` for a direct
// Magi attack). "You may discard a card from your hand" is a real WHICH-card choice, same shape as
// Baldar Amulet's Hammer -- the pool is the controller's own hand, `chosenInstanceId` from
// `PreCombatTargetResolution` names which hand card to discard, and paying it discards the
// attacking Creature. "First time each turn" via a duration tag, same convention as every other
// once/first-time-per-turn card in this codebase.

import { registerCardEffect } from './registry.js';
import { discardFromHand, discardFromPlay } from '../effects.js';
import { hasDurationTag, addDurationTag } from '../durationTags.js';
import type { PreCombatTargetResolution } from '../combat.js';

const USED_THIS_TURN = 'mogaBootsUsedThisTurn';

registerCardEffect('Moga Boots', {
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker, isDefender, attacker, defender) => {
    if (defender !== undefined) return undefined; // must be a direct Magi attack
    if (attacker.controllerId === self.controllerId) return undefined; // "your Magi is attacked"
    if (hasDurationTag(self, USED_THIS_TURN)) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player || player.hand.length === 0) return undefined;
    return { prompt: "Moga Boots' Kickback: discard a card from your hand to discard the attacking Creature?", pool: player.hand };
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.defender !== null) return;
    if (ctx.attacker.controllerId === self.controllerId) return;
    if (hasDurationTag(self, USED_THIS_TURN)) return;
    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
    const resolution = resolutions?.[self.instanceId];
    if (!resolution || 'skip' in resolution) return;
    addDurationTag(ctx.state, ctx.cardDb, self, USED_THIS_TURN, ctx.state.turnNumber);
    const player = ctx.state.players.get(self.controllerId);
    if (!player) return;
    const handCard = player.hand.find((c) => c.instanceId === resolution.chosenInstanceId);
    if (!handCard) return;
    discardFromHand(ctx.state, ctx.cardDb, player, [handCard.instanceId], undefined, ctx.rng);
    const attackingPlayer = ctx.state.players.get(ctx.attacker.controllerId);
    if (attackingPlayer) discardFromPlay(ctx.state, ctx.cardDb, attackingPlayer, ctx.attacker.instanceId, undefined, undefined, ctx.rng);
  },
});
