// Great White Narth -- both printed pieces:
//   "Sustain: Discard Great White Narth from play. If Great White Narth defeated an opposing
//   Creature in an attack this turn, add five energy to your Magi." First card using
//   CardInstance's new defeatedThisTurn field (types/instance.ts), set generically by combat.ts
//   whenever an attacker's damage defeats the defender.
//   "Overwhelm: Whenever Great White Narth attacks, after energy is removed, add one energy to
//   Great White Narth for each of the defending player's frozen Creatures."

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Great White Narth', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Sustain') return;
    const defeatedSomething = ctx.source.defeatedThisTurn;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    if (defeatedSomething && ctx.controllingPlayer.activeMagi) {
      addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, 5, 'power');
    }
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    const frozenCount = ctx.defendingPlayer.inPlay.filter(
      (c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature' && isFrozen(ctx.state, ctx.cardDb, c)
    ).length;
    if (frozenCount === 0) return;
    addEnergy(ctx.state, ctx.cardDb, self, frozenCount, 'effect');
  },
});
