// Nocturne (Spell, cost 4) -- "Search through your deck for any one Naroom Creature. Play that
// Creature with one energy, without paying any costs. That Creature may not attack this turn.
// Shuffle your deck afterward." Naroom Spell pass, Category B (2026-07-23). Same shape as
// hyrensCall.ts (build-together pair) -- spellTargets pool over player.deck instead of a new
// deck-search picker, filtered to Naroom Creatures instead of the "Hyren" name family, flat 1
// energy instead of full starting energy.

import { registerCardEffect } from './registry.js';
import { searchDeckIntoPlay } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';
import { shuffleDeck } from '../zones.js';
import { effectiveRegions } from '../targeting.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Nocturne', {
  spellTargets: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player) return [];
    return player.deck.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature' && effectiveRegions(state, cardDb, c).includes('Naroom'));
  },
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    if (ctx.chosenTargetId === undefined) return;
    const card = player.deck.find((c) => c.instanceId === ctx.chosenTargetId);
    const def = card ? ctx.cardDb.get(card.definitionKey) : undefined;
    if (!card || !def || def.card_type !== 'Creature' || !effectiveRegions(ctx.state, ctx.cardDb, card).includes('Naroom')) return;

    const played = searchDeckIntoPlay(ctx.state, ctx.cardDb, player, card.instanceId, 1, true, ctx.rng);
    if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
    shuffleDeck(player, ctx.rng);
    checkCreatureDefeats(ctx.state, ctx.cardDb);
  },
});
