// Olum Digger -- "Tunnel (1): Until the end of the turn, Olum Digger can attack Magi directly.
// Whenever Olum Digger attacks a Magi, choose any one of that Magi's Creatures. Discard two
// energy from the chosen Creature." Promoted out of docs/deferred-card-mechanics.md's "medium"
// bucket now that CAN_ATTACK_MAGI_DIRECTLY is built.
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "largest Creature" simplification with
// a real pending choice (registry.ts's pendingTargetChoice/resolveTargetChoice), resolved AFTER
// combat -- the target doesn't affect this attack's own damage math (it's the defending Magi's
// OTHER Creatures, not the Magi being attacked itself), so unlike Weave's donor choice there's no
// need to pre-collect this before declareAttack (same reasoning as wanderingBalamant.ts's Fetch).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, addPermanentTag, removePermanentTag, CAN_ATTACK_MAGI_DIRECTLY } from '../durationTags.js';

const TUNNEL_PENDING_PREFIX = 'olumDiggerTunnelPending:';

function pendingTunnelDefenderId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(TUNNEL_PENDING_PREFIX)) return tag.slice(TUNNEL_PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Olum Digger', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Tunnel') return;
    addDurationTag(ctx.state, ctx.cardDb, ctx.source, CAN_ATTACK_MAGI_DIRECTLY, ctx.state.turnNumber);
  },
  onAttack: (ctx, self) => {
    if (self.instanceId !== ctx.attacker.instanceId) return;
    if (ctx.defender !== null) return; // only fires for a direct Magi attack
    if (creaturesControlledBy(ctx.state, ctx.cardDb, ctx.defendingPlayer.playerId).length === 0) return;
    addPermanentTag(ctx.state, ctx.cardDb, self, `${TUNNEL_PENDING_PREFIX}${ctx.defendingPlayer.playerId}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const defenderId = pendingTunnelDefenderId(self);
    if (defenderId === undefined) return undefined;
    const pool = creaturesControlledBy(state, cardDb, defenderId);
    if (pool.length === 0) return undefined;
    return { prompt: "Olum Digger's Tunnel: choose one of that Magi's Creatures to discard 2 energy from", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const defenderId = pendingTunnelDefenderId(self);
    if (defenderId === undefined) return;
    removePermanentTag(self, `${TUNNEL_PENDING_PREFIX}${defenderId}`);
    if (!chosenInstanceId) return;
    const target = creaturesControlledBy(state, cardDb, defenderId).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 2, 'effect', undefined, rng);
  },
});
