// Grega's Ring -- "Thermal Blast (2): Roll a die. Choose any one Creature or Magi in play.
// Discard energy equal to the die roll from the chosen Creature or Magi. If the die roll is two
// or less, discard Grega's Ring from play." Same effect as grega.ts plus a die-outcome-dependent
// self-discard.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, discardFromPlay, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { getPlayer } from '../types/state.js';

registerCardEffect("Grega's Ring", {
  powerTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Thermal Blast') return;
    if (ctx.chosenTargetId === undefined) return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'gregasRing:thermalBlast',
      { chosenTargetId: ctx.chosenTargetId, controllingPlayerId: ctx.controllingPlayer.playerId },
      ctx.rng
    );
  },
});

registerRollConsumer('gregasRing:thermalBlast', (state, cardDb, source, payload, finalRoll, rng) => {
  const { chosenTargetId, controllingPlayerId } = payload as { chosenTargetId: string; controllingPlayerId: string };
  const target = findCreatureOrMagiById(state, chosenTargetId);
  if (target) discardEnergy(state, cardDb, target, finalRoll, undefined, undefined, rng);
  if (finalRoll <= 2 && source) {
    const controllingPlayer = getPlayer(state, controllingPlayerId);
    discardFromPlay(state, cardDb, controllingPlayer, source.instanceId, undefined, undefined, rng);
  }
});
