// Vorga -- "Shatter: Choose any one Creature with three or less energy, or any one Relic in play.
// Discard the chosen Creature or Relic from play."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allRelicsInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Vorga', {
  powerTargets: (state, cardDb) => [
    ...allCreaturesInPlay(state, cardDb).filter((c) => (c.currentEnergy ?? 0) <= 3),
    ...allRelicsInPlay(state, cardDb),
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shatter') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    const type = ctx.cardDb.get(target.definitionKey)?.card_type;
    if (type === 'Creature' && (target.currentEnergy ?? 0) > 3) return;
    if (type !== 'Creature' && type !== 'Relic') return;

    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
