// Staff of Keepers -- "When you play Staff of Keepers, choose any one region other than your Magi's
// region. You ignore regional penalties for Creatures of the chosen region. If your Magi is a
// Keeper, also add one energy to each Creature you play from the chosen region."
//   - The region pick at play uses pendingCategoryChoice + CardInstance.persistentCategoryChoice
//     (Niffer's shape), armed by onPlay reacting to Staff of Keepers' OWN entry.
//   - regionOverride reads that stored region and fully waives the penalty for Creatures of it
//     (Sand Hyren / Niffer shape).
//   - The Keeper bonus is an onPlay broadcast: a Creature of the chosen region played by the
//     controller, while the active Magi is a Keeper (subtype), gets +1 energy.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { addEnergy } from '../effects.js';
import { ALL_REGIONS } from '../regions.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const AWAITING = 'staffOfKeepersAwaitingRegion';

function optionsFor(state: GameState, cardDb: CardDatabase, self: CardInstance): string[] {
  const magi = state.players.get(self.controllerId)?.activeMagi;
  const magiRegions: readonly string[] = magi ? (cardDb.get(magi.definitionKey)?.regions ?? []) : [];
  return ALL_REGIONS.filter((r) => !magiRegions.includes(r));
}

registerCardEffect('Staff of Keepers', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) {
      if (self.persistentCategoryChoice === null) addPendingChoiceTag(self, AWAITING); // arm the region pick
      return;
    }
    // Keeper bonus: a Creature of the chosen region played by our controller, while our Magi is a Keeper.
    if (self.persistentCategoryChoice === null || played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Creature' || !def.regions.includes(self.persistentCategoryChoice)) return;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (magi && cardDb.get(magi.definitionKey)?.subtype === 'Keeper') addEnergy(state, cardDb, played, 1, 'effect');
  },
  pendingCategoryChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING)) return undefined;
    const options = optionsFor(state, cardDb, self);
    if (options.length === 0) return undefined;
    return { prompt: "Staff of Keepers: choose a region other than your Magi's region", options };
  },
  resolveCategoryChoice: (state, cardDb, self, chosen) => {
    removePermanentTag(self, AWAITING);
    const options = optionsFor(state, cardDb, self);
    self.persistentCategoryChoice = chosen && options.includes(chosen) ? chosen : options[0] ?? null;
  },
  regionOverride: (_state, _cardDb, playedDef, _magi, contributor) =>
    contributor.persistentCategoryChoice !== null &&
    playedDef.card_type === 'Creature' &&
    playedDef.regions.includes(contributor.persistentCategoryChoice),
});
