// Hubram -- "Dreamfetch: Whenever you play an Underneath Spell that does not remain in play, you
// may discard Hubram from play to put the Spell into your hand instead of your discard pile." No
// Spell currently "remains in play" in this engine (no lingering-Spell mechanism exists yet), so
// this condition is vacuously always true for every Spell. The just-played Spell is already
// sitting in the discard pile by the time onPlay fires (play.ts moves it there before broadcasting)
// -- retrieved straight back out via retrieveFromDiscardPile.
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice`. The just-played Spell
// is remembered via an embedded-id permanent tag (same technique as Reef Hyren/Skullek/Wellisk/
// Ahron/Gloves of Crystal in this same batch) since the resolve call has no target parameter.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, retrieveFromDiscardPile } from '../effects.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const PENDING_PREFIX = 'hubramPending:';

function pendingSpellId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return tag.slice(PENDING_PREFIX.length);
  }
  return undefined;
}

function findInDiscardPile(state: Parameters<typeof retrieveFromDiscardPile>[0], playerId: string, instanceId: string) {
  return state.players.get(playerId)?.discardPile.find((c) => c.instanceId === instanceId);
}

registerCardEffect('Hubram', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Spell') return;
    if (!def.regions.includes('Underneath')) return;
    if (!findInDiscardPile(state, self.controllerId, played.instanceId)) return;
    addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${played.instanceId}`);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    const spellId = pendingSpellId(self);
    if (spellId === undefined) return undefined;
    if (!findInDiscardPile(state, self.controllerId, spellId)) return undefined;
    return {
      prompt: 'Hubram\'s Dreamfetch: discard Hubram from play to put the Spell into your hand instead of your discard pile?',
      yesLabel: 'Discard Hubram, keep Spell in hand',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const spellId = pendingSpellId(self);
    if (spellId !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${spellId}`);
    if (!chosenBoolean || spellId === undefined) return;
    const player = state.players.get(self.controllerId);
    if (!player || !findInDiscardPile(state, self.controllerId, spellId)) return;
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
    retrieveFromDiscardPile(state, player, spellId, 'hand');
  },
});
