// Fird -- "Perch: Whenever you play a Furok, you can play one copy of Fird from your hand or discard
// pile, paying all costs. Fird cannot attack this turn." Built task #45, 2026-07-18, the Naroom
// region pass.
//
// "Furok" is a Creature TYPE (the last word of a card's printed name -- same convention Shadow
// Fird's Feed uses). Fird reacts while sitting in its controller's OWN hand or discard pile, which
// no on-play broadcast reached before -- registry.ts's new marker-only
// `reactsToOwnCardPlayFromHandOrDiscard` (play.ts) marks a pending choice, exposed via the existing
// `pendingYesNoChoice`/`resolveYesNoChoice` machinery (whose aggregator already scans hand +
// discard). The play itself goes through `playFromZonePayingCost` (full costs paid, from whichever
// zone Fird is in), then Fird is tagged CANNOT_ATTACK for this turn.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag, addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { playFromZonePayingCost } from '../play.js';

const PERCH_PENDING = 'firdPerchPending';

function isFurok(name: string): boolean {
  return name.trim().split(/\s+/).pop() === 'Furok';
}

registerCardEffect('Fird', {
  reactsToOwnCardPlayFromHandOrDiscard: (state, cardDb, self, played, playerId) => {
    if (self.controllerId !== playerId) return; // "whenever YOU play a Furok"
    if (played.instanceId === self.instanceId) return; // don't react to Fird's own play
    const playedDef = cardDb.get(played.definitionKey);
    if (!playedDef || !isFurok(playedDef.name)) return;
    addPendingChoiceTag(self, PERCH_PENDING);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(PERCH_PENDING)) return undefined;
    return {
      prompt: "Fird's Perch: play a copy of Fird from your hand or discard pile, paying all costs?",
      yesLabel: 'Play Fird',
      noLabel: 'Not now',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, PERCH_PENDING);
    if (!chosenBoolean) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const zone: 'hand' | 'discardPile' = player.hand.some((c) => c.instanceId === self.instanceId) ? 'hand' : 'discardPile';
    const played = playFromZonePayingCost(state, cardDb, player, zone, self.instanceId, {}, rng);
    if (played) addRestrictionTag(state, played, CANNOT_ATTACK, state.turnNumber);
  },
});
