// Rot Arboll -- both printed clauses:
//   "Blight: After an opponent plays a Creature with more energy than Rot Arboll, move one energy
//   from that Creature to Rot Arboll." onPlay, self=Rot Arboll, reacting to an OPPOSING played
//   Creature -- the energy comparison is read at the moment of play, before the move happens.
//   "Shifty: This Creature loses no energy from opposing Effects." No card-side logic needed --
//   effects.ts's discardEnergy itself checks printsShifty on the target and zeroes out any
//   'effect'-caused loss when the target is opposing.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Rot Arboll', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Blight owns the onPlay reactor.
  // Shifty is JSON-data-driven (effects.ts reads `printsShifty`), no registry hooks -- empty set.
  effectHooks: {
    Blight: ['onPlay'],
    Shifty: [],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if ((played.currentEnergy ?? 0) <= (self.currentEnergy ?? 0)) return;
    rearrangeEnergy(state, cardDb, played, self, 1);
  },
});
