// Oranragan -- all three printed clauses:
//   "Crush: When you play Oranragan, choose and discard an opposing Relic from play."
//   "Invulnerability: Oranragan loses one less energy in attacks." (invulnerability.ts)
//   "Vengeance: When an opposing card discards one of your cards from play or reduces one of your
//   other Creatures to zero energy, add two energy to Oranragan." "By an opposing card" retrofitted
//   (task #32, 2026-07-16) from the old `state.activePlayerId === self.controllerId` heuristic to
//   the real `causedByPlayerId` param now available on `onCardDiscardedFromPlay`.
//
// Real choice (Phase 4c, 2026-07-11): Crush's "choose" replaces the earlier "first eligible in
// array order" simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice).

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { applyInvulnerability } from './invulnerability.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const CRUSH_PENDING = 'oranraganCrushPending';

registerCardEffect('Oranragan', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Crush is the onPlay + pending-target
  // pair, Invulnerability is onAttack, Vengeance is onCardDiscardedFromPlay.
  effectHooks: {
    Crush: ['onPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
    Invulnerability: ['onAttack'],
    Vengeance: ['onCardDiscardedFromPlay'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    if (allRelicsInPlay(state, cardDb).filter((r) => r.controllerId !== self.controllerId).length === 0) return;
    addPendingChoiceTag(self, CRUSH_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(CRUSH_PENDING)) return undefined;
    const pool = allRelicsInPlay(state, cardDb).filter((r) => r.controllerId !== self.controllerId);
    if (pool.length === 0) return undefined;
    return { prompt: 'Oranragan\'s Crush: choose an opposing Relic to discard from play', pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, CRUSH_PENDING);
    if (!chosenInstanceId) return;
    const target = allRelicsInPlay(state, cardDb)
      .filter((r) => r.controllerId !== self.controllerId)
      .find((r) => r.instanceId === chosenInstanceId);
    if (!target) return;
    const owner = state.players.get(target.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, target.instanceId, undefined, undefined, rng);
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discardedOwnerId !== self.controllerId) return;
    if (causedByPlayerId === undefined || causedByPlayerId === self.controllerId) return;

    addEnergy(state, cardDb, self, 2, 'effect');
  },
});
