// Bria (base Magi -- distinct from the already-built "Bria, Relic Hunter") -- "Obsession: When you
// reveal Bria, name one Region. Bria may play Relics from that Region regardless of regional
// restrictions." Same onMagiRevealed + persistentCategoryChoice + regionOverride shape as Niffer's
// Allies, but scoped to RELICS of the chosen region and with no restrictive half. Options at reveal =
// the non-Universal regions of Relics actually in her deck (Universal Relics are unrestricted anyway;
// same rational deck-scan approach as Niffer); auto-picks the most common if a caller doesn't answer.

import { registerCardEffect } from './registry.js';
import { isUniversal } from '../regions.js';
import { addPermanentTag, addPendingRevealChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING_CHOICE = 'briaObsessionAwaitingChoice';

function relicRegionCounts(state: GameState, cardDb: CardDatabase, self: CardInstance): Map<string, number> {
  const player = state.players.get(self.controllerId);
  const counts = new Map<string, number>();
  if (!player) return counts;
  for (const card of player.deck) {
    const def = cardDb.get(card.definitionKey);
    if (def?.card_type !== 'Relic' || isUniversal(def.regions)) continue;
    for (const region of def.regions) counts.set(region, (counts.get(region) ?? 0) + 1);
  }
  return counts;
}

function bestRegion(counts: Map<string, number>): string {
  let best: string | null = null;
  let bestCount = 0;
  for (const [region, count] of counts) {
    if (count > bestCount) {
      best = region;
      bestCount = count;
    }
  }
  return best ?? 'Orothe';
}

registerCardEffect('Bria', {
  onMagiRevealed: (state, cardDb, revealedMagi, self) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    if (self.persistentCategoryChoice !== null) return;
    addPendingRevealChoiceTag(self, AWAITING_CHOICE);
  },
  pendingCategoryChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const options = [...relicRegionCounts(state, cardDb, self).keys()];
    if (options.length === 0) return undefined;
    return { prompt: "Bria's Obsession: name one Region (Bria may play its Relics freely)", options };
  },
  resolveCategoryChoice: (state, cardDb, self, chosen) => {
    removePermanentTag(self, AWAITING_CHOICE);
    const counts = relicRegionCounts(state, cardDb, self);
    self.persistentCategoryChoice = chosen && counts.has(chosen) ? chosen : bestRegion(counts);
  },
  regionOverride: (state, cardDb, playedDef, magi, contributor) =>
    contributor.persistentCategoryChoice !== null &&
    playedDef.card_type === 'Relic' &&
    playedDef.regions.includes(contributor.persistentCategoryChoice),
});
