// Shadow Bones -- "Vitalize (4): Choose any one Core Creature in play. Discard Shadow Bones from
// play. Add energy to the chosen Creature equal to that Creature's starting energy."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveRegions, regionForTargetFilter, effectiveStartingEnergy } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Shadow Bones', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Core'))),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Vitalize') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Core'))) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, effectiveStartingEnergy(ctx.state, ctx.cardDb, target), 'power');
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Core'],
});
