// Weggit (Weave Creature) -- "Whispering Winds: Discard Weggit from play. Draw a card for each
// Weave Relic you have in play." Not to be confused with Scurrying Weggit, a different card. The
// "Weave" filter is an official 2i Design errata (data-pipeline/output/rulings.json, applied
// 2026-07-09) -- previously this counted ALL Relics you control, not just Weave-region ones. Also
// prints "Weave: Whenever Weggit attacks or is attacked, before energy is removed, you may move
// one energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay } from '../targeting.js';
import { discardFromPlay, drawCards } from '../effects.js';
import { applyWeave } from './weave.js';

registerCardEffect('Weggit', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Whispering Winds') return;
    const count = allRelicsInPlay(ctx.state, ctx.cardDb).filter(
      (r) => r.controllerId === ctx.controllingPlayer.playerId && ctx.cardDb.get(r.definitionKey)?.regions.includes('Weave')
    ).length;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    if (count > 0) drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, count);
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
});
