// Kalius -- "Wind Spawn (1): Play any one Arderial Creature from your hand. Place two energy on
// it instead of its normal starting energy. Discard that Creature from play at the end of this
// turn." Same handPlayChoice/playFromZone shape as Shimmering Orshaa, fixed starting energy (2)
// instead of the card's printed cost, tagged DISCARD_AT_END_OF_TURN (swept generically) instead
// of CANNOT_ATTACK.

import { registerCardEffect } from './registry.js';
import { playFromZone } from '../effects.js';
import { addPermanentTag, DISCARD_AT_END_OF_TURN } from '../durationTags.js';

registerCardEffect('Kalius', {
  handPlayChoice: {
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes('Arderial');
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Wind Spawn') return;
    if (!ctx.chosenHandPlayId) return;
    const handCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    const def = handCard ? ctx.cardDb.get(handCard.definitionKey) : undefined;
    if (!def || def.card_type !== 'Creature' || !def.regions.includes('Arderial')) return;

    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: ctx.chosenHandPlayId },
      ctx.controllingPlayer,
      2
    , ctx.rng);
    if (played) addPermanentTag(ctx.state, ctx.cardDb, played, DISCARD_AT_END_OF_TURN);
  },
});
