// Vine Hyren -- "Dreamwarp": "As you play Vine Hyren, increase or decrease its starting energy by
// up to one, until the end of the turn." (registry.ts's dreamwarpRange.)
//
// "Dream Tap: Whenever one of your OTHER Creatures uses the Effect 'Dreamwarp', add one energy to
// Vine Hyren." Built task #37 (Paradwyn pass, Category C, 2026-07-17) via the new
// onAnyDreamwarpUsed broadcast (registry.ts), the same one Tropical Hyren's Maximum Warp uses --
// "other" excludes Vine Hyren's own Dreamwarp use, unlike Tropical Hyren's unqualified text.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Vine Hyren', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Dreamwarp is the standard self-play
  // data field; Dream Tap is the +1 to Vine Hyren when any of your OTHER Creatures uses Dreamwarp.
  effectHooks: {
    Dreamwarp: ['dreamwarpRange'],
    'Dream Tap': ['onAnyDreamwarpUsed'],
  },
  dreamwarpRange: () => 1,
  onAnyDreamwarpUsed: (state, cardDb, self, played) => {
    if (played.controllerId !== self.controllerId) return;
    if (played.instanceId === self.instanceId) return;
    addEnergy(state, cardDb, self, 1, 'effect');
  },
});
