// Heppeswip -- two clauses:
//   "Weave" (see weave.ts): "Whenever Heppeswip attacks or is attacked, before energy is removed,
//   you may move one energy between it and one of your other Weave Creatures in play."
//   "Unravel" (task #713, 2026-08-11, Category C deferred-gap closure pass): "Whenever an opposing
//   Creature or Relic uses a Power that affects one or more of your other Weave Creatures in play,
//   you may discard one energy from Heppeswip to discard the opposing Creature or Relic from play."
//
// Unravel fires off registry.ts's onOpponentPowerDiscardedEnergyFromOwnCreature (new hook, built
// alongside this card -- power.ts's own per-Creature opposing-energy-loss map, rebroadcast to the
// AFFECTED Creature's own controller instead of the acting player). "Affects" is narrowed to
// "discarded energy from" -- the only sub-case the hook covers; a Power that merely TARGETS a Weave
// Creature without changing its energy doesn't trigger this (documented narrower-than-printed-text
// scope, same as every other partial-coverage broadcast in this codebase). The source card's own
// instance id is parked on a dynamically-keyed tag between the trigger and the yes/no resolve (same
// encoding trick as gherish.ts's DRIFT_SOURCE_PREFIX). Only the FIRST opposing Power to hit a Weave
// Creature in a turn can offer Unravel -- once UNRAVEL_PENDING is set it isn't overwritten by a
// second hit, matching this codebase's general single-offer-per-resolution convention elsewhere.

import { registerCardEffect } from './registry.js';
import { applyWeave } from './weave.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { effectiveRegions, findCreatureOrMagiById } from '../targeting.js';
import { getPlayer } from '../types/state.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';

const UNRAVEL_PENDING = 'heppeswipUnravelPending';
const UNRAVEL_SOURCE_PREFIX = 'heppeswipUnravelSource:';

function unravelSourceId(self: CardInstance): string | undefined {
  for (const tag of self.tags) if (tag.startsWith(UNRAVEL_SOURCE_PREFIX)) return tag.slice(UNRAVEL_SOURCE_PREFIX.length);
  return undefined;
}

function clearUnravelSource(self: CardInstance): void {
  for (const tag of [...self.tags]) if (tag.startsWith(UNRAVEL_SOURCE_PREFIX)) removePermanentTag(self, tag);
}

registerCardEffect('Heppeswip', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Weave is the standard move hook +
  // `weaveConfig`; Unravel is the opponent-Power reactor + its yes/no follow-up.
  effectHooks: {
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
    Unravel: ['onOpponentPowerDiscardedEnergyFromOwnCreature', 'pendingYesNoChoice', 'resolveYesNoChoice'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
  onOpponentPowerDiscardedEnergyFromOwnCreature: (state, cardDb, self, source, affected) => {
    if (self.tags.has(UNRAVEL_PENDING)) return; // first opposing hit this resolution wins
    if (affected.instanceId === self.instanceId) return; // "your OTHER Weave Creatures"
    if ((self.currentEnergy ?? 0) < 1) return; // needs energy to pay Unravel's cost
    const sourceDef = cardDb.get(source.definitionKey);
    if (sourceDef?.card_type !== 'Creature' && sourceDef?.card_type !== 'Relic') return;
    if (!effectiveRegions(state, cardDb, affected).includes('Weave')) return;
    addPermanentTag(state, cardDb, self, `${UNRAVEL_SOURCE_PREFIX}${source.instanceId}`);
    addPendingChoiceTag(self, UNRAVEL_PENDING);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(UNRAVEL_PENDING)) return undefined;
    const sourceId = unravelSourceId(self);
    const source = sourceId ? findCreatureOrMagiById(state, sourceId) : undefined;
    if (!source || (self.currentEnergy ?? 0) < 1) return undefined;
    const sourceName = cardDb.get(source.definitionKey)?.name ?? 'that card';
    return {
      prompt: `Heppeswip's Unravel: discard one energy from Heppeswip to discard ${sourceName} from play?`,
      yesLabel: 'Discard',
      noLabel: 'Decline',
      optional: true,
      intent: 'beneficial' as const,
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    if (!self.tags.has(UNRAVEL_PENDING)) return;
    removePermanentTag(self, UNRAVEL_PENDING);
    const sourceId = unravelSourceId(self);
    clearUnravelSource(self);
    if (!chosenBoolean || !sourceId) return;
    const source = findCreatureOrMagiById(state, sourceId);
    if (!source || (self.currentEnergy ?? 0) < 1) return;
    const owner = getPlayer(state, source.controllerId);
    discardEnergy(state, cardDb, self, 1, 'effect', self.controllerId, rng);
    discardFromPlay(state, cardDb, owner, source.instanceId, self.controllerId, 'effect', rng);
  },
});
