// Wence -- "Wayfarer's Lore: Draw one card. If you draw a Creature card in this way, you may show
// it to your opponent and draw one additional card during your Draw Step this turn." "You may
// show" is the controller's choice -- booleanChoice, same as Emaya's direction pick.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Wence', {
  booleanChoice: {
    prompt: 'If you drew a Creature, show it to draw an additional card?',
    yesLabel: 'Show it',
    noLabel: 'Keep hidden',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Wayfarer's Lore") return;
    const drawn = drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    const card = drawn[0];
    if (card && ctx.cardDb.get(card.definitionKey)?.card_type === 'Creature' && ctx.chosenBoolean) {
      drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    }
  },
});
