// Eebit -- "Escape: If Eebit is defeated in an attack, instead of discarding it, put it back into
// its owner's hand." "Defeated in an attack" is EITHER combat role (attacking or defending) --
// distinct from Motash's Escape, whose text is "attacked and defeated" (defending only). The first
// build only handled the defender case (task #49 playtest bug fix, 2026-07-19: it wasn't firing when
// Eebit was defeated while attacking).

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';

registerCardEffect('Eebit', {
  afterCombat: (ctx, outcome, self) => {
    const defeatedAsDefender = ctx.defender?.instanceId === self.instanceId && !outcome.defenderSurvived;
    const defeatedAsAttacker = ctx.attacker.instanceId === self.instanceId && !outcome.attackerSurvived;
    if (!defeatedAsDefender && !defeatedAsAttacker) return;
    const owner = defeatedAsAttacker ? ctx.attackingPlayer : ctx.defendingPlayer;
    retrieveFromDiscardPile(ctx.state, owner, self.instanceId, 'hand');
  },
});
