// Baa -- "Hordes: Whenever you play a Bograth Creature, you may discard one energy from Baa to
// draw an additional card at the end of the turn." "The end of the turn" reads as THIS SAME
// turn's own Draw step (the last phase in this engine's phase order, chronologically after
// Play Creatures where the trigger fires) -- registry.ts's drawCountModifier, same shape as
// Scarletsong Banner's flat bonus but variable, tallied on a per-turn counter (task #50f) rather
// than a fixed number since Hordes can fire multiple times in one turn. Counter reset at the start
// of Baa's controller's own next turn -- AFTER this same turn's Draw step has already consumed it,
// so nothing leaks into a later turn.
//
// REWORKED (playtest bug fix, 2026-07-21): "you may" used to auto-apply unconditionally whenever
// Baa could afford it (task #30-1d, 2026-07-15, predates the task #40 player-choice-default-retrofit
// sweep and was missed by it). Now a real Group 4 pendingYesNoChoice/resolveYesNoChoice prompt --
// there IS a real downside to always taking it (Baa's own energy is a finite resource other cards
// may care about, and an extra card isn't free of opportunity cost), so a genuine choice matters
// here the same way it did for Moob Ring/Treepsh. Only one prompt is ever in flight at a time (a
// simple boolean tag, not a per-trigger queue) -- playing a second Bograth Creature while the first
// Hordes prompt is still open isn't reachable through the normal UI, same assumption every other
// onPlay-triggered pendingYesNoChoice reactor in this codebase already makes.

import { registerCardEffect } from './registry.js';
import { discardEnergy, getCounter, setCounter } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { effectiveRegions } from '../targeting.js';

const HORDES_BONUS_DRAWS = 'baaHordesBonusDraws';
const AWAITING_HORDES_CHOICE = 'baaAwaitingHordesChoice';

registerCardEffect('Baa', {
  onOwnTurnStart: (state, cardDb, self) => {
    setCounter(self, HORDES_BONUS_DRAWS, 0);
    removePermanentTag(self, AWAITING_HORDES_CHOICE); // safety: clear a stale offer from a turn nobody answered it in
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(state, cardDb, played).includes('Bograth')) return;
    if ((self.currentEnergy ?? 0) < 1) return;

    addPendingChoiceTag(self, AWAITING_HORDES_CHOICE);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_HORDES_CHOICE)) return undefined;
    return {
      prompt: "Baa's Hordes: discard one energy from Baa to draw an additional card at the end of the turn?",
      yesLabel: 'Discard 1 energy, +1 card at end of turn',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, AWAITING_HORDES_CHOICE);
    if (!chosenBoolean) return;
    if ((self.currentEnergy ?? 0) < 1) return; // re-validate -- energy may have changed since the offer was made
    discardEnergy(state, cardDb, self, 1, 'effect', self.controllerId, rng);
    setCounter(self, HORDES_BONUS_DRAWS, getCounter(self, HORDES_BONUS_DRAWS) + 1);
  },
  drawCountModifier: (state, cardDb, self) => getCounter(self, HORDES_BONUS_DRAWS),
});
