// Sandsifter -- two Powers.
// "Inevitable Truth (1): Choose an opposing Magi. Discard one energy from the chosen Magi for
// each Oracle you have in play." First card to target a Magi (rather than a Creature/Relic) and
// to count by subtype. Sandsifter's own subtype is "Oracle," and the text doesn't exclude itself,
// so it counts toward its own total.
// "Unearth: Choose an Oracle in your discard pile. Put the chosen card into your hand." This is
// exactly registry.ts's discardPileSearch shape (same as Delia's "Choose any one Vellup in your
// discard pile... into your hand") -- the old comment here claiming it "targets a zone none of the
// existing targeting.ts helpers search" was simply wrong (discardPileSearch doesn't go through
// targeting.ts at all, it's its own registry.ts field), caught auditing for cards silently missing
// a Power branch the same way Thunder Hyren's Replenish was (PROGRESS_LOG.md, 2026-07-09). Both
// `powerTargets` and `discardPileSearch` are scoped per-Power (registry.ts doc comments) since only
// one of the two Powers on this card uses each.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingMagi } from '../targeting.js';
import { discardEnergy, retrieveFromDiscardPile } from '../effects.js';

registerCardEffect('Sandsifter', {
  powerTargets: (state, cardDb, playerId, powerName) =>
    powerName === 'Inevitable Truth' ? opposingMagi(state, cardDb, playerId) : undefined,
  discardPileSearch: (powerName) =>
    powerName === 'Unearth'
      ? { count: 1, filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.subtype === 'Oracle' }
      : undefined,
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Inevitable Truth') {
      if (ctx.chosenTargetId === undefined) return;
      const targetMagi = opposingMagi(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
        (m) => m.instanceId === ctx.chosenTargetId
      );
      if (!targetMagi) return;
      const oracleCount = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter(
        (c) => ctx.cardDb.get(c.definitionKey)?.subtype === 'Oracle'
      ).length;
      discardEnergy(ctx.state, ctx.cardDb, targetMagi, oracleCount, undefined, undefined, ctx.rng);
    } else if (ctx.powerName === 'Unearth') {
      const ids = ctx.chosenDiscardPileIds ?? [];
      if (ids.length !== 1) return;
      const [id] = ids;
      const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
      if (!card || ctx.cardDb.get(card.definitionKey)?.subtype !== 'Oracle') return;
      retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'hand', ctx.rng);
    }
  },
});
