// Wasperine Stalker -- "Blur: If your Magi is Nar or Naroom, you may play Wasperine Stalker at
// the beginning of your Attack step. If you do, Wasperine Stalker can and must attack Magi
// directly this turn. When you play Wasperine Stalker, add two energy to it if your Magi is
// Woot!." Built task #43, 2026-07-18, the Nar region pass -- Category D. Directly reuses Mountain
// Trulb's proven `onOwnAttackStepStart` + `pendingYesNoChoice` + `playFromZonePayingCost` shape
// (Kybar's Teeth region pass, task #42) for the play-timing + CAN-attack half. The MUST half is
// built now too (task #44 Part B, 2026-07-18) -- MUST_ATTACK_THIS_TURN (durationTags.ts).
// "Naroom Shadow Magi can play Wasperine Stalker" needs no code -- already covered by the
// database's own `shadow_play: "Naroom"` field + regions.ts, same as Urhail's precedent.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag, addDurationTag, CAN_ATTACK_MAGI_DIRECTLY, MUST_ATTACK_THIS_TURN } from '../durationTags.js';
import { playFromZonePayingCost } from '../play.js';
import { addEnergy } from '../effects.js';

const BLUR_PENDING = 'wasperineStalkerBlurPending';

registerCardEffect('Wasperine Stalker', {
  onOwnAttackStepStart: (state, cardDb, self) => {
    removePermanentTag(self, BLUR_PENDING);
    const magi = state.players.get(self.controllerId)?.activeMagi;
    const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
    if (!magiDef || !(magiDef.regions.includes('Nar') || magiDef.regions.includes('Naroom'))) return;
    addPendingChoiceTag(self, BLUR_PENDING);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(BLUR_PENDING)) return undefined;
    return {
      prompt: "Wasperine Stalker's Blur: play it now, paying all costs? It can attack Magi directly this turn.",
      yesLabel: 'Play Wasperine Stalker',
      noLabel: 'Not now',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, BLUR_PENDING);
    if (!chosenBoolean) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const magiDef = player.activeMagi ? cardDb.get(player.activeMagi.definitionKey) : undefined;
    const playedInstance = playFromZonePayingCost(state, cardDb, player, 'hand', self.instanceId, {}, rng);
    if (!playedInstance) return;
    addDurationTag(state, cardDb, playedInstance, CAN_ATTACK_MAGI_DIRECTLY, state.turnNumber);
    addDurationTag(state, cardDb, playedInstance, MUST_ATTACK_THIS_TURN, state.turnNumber);
    if (magiDef?.name === 'Woot!') {
      addEnergy(state, cardDb, playedInstance, 2, 'effect');
    }
  },
});
