// Impact (Spell, Underneath, cost 1) -- "Choose any one of your Creatures and any one Magi in play.
// Discard twice as much energy as the chosen Creature has from the chosen Magi. Discard the chosen
// Creature from play." Underneath Spell pass, Category B (2026-07-25).
//
// Two INDEPENDENT picks with different pools -- own Creatures for the sacrifice, any Magi (either
// side's, per "any one Magi in play") for the target -- which is exactly registry.ts's
// spellTargets/spellSecondTargets shape, same as Abwyn's Gift/Stone Storm. The doubling is read
// from the Creature's energy BEFORE it is discarded, since discarding it zeroes that energy.

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { allMagiInPlay, creaturesControlledBy, findCreatureOrMagiById } from '../targeting.js';

registerCardEffect('Impact', {
  spellTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  spellSecondTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined || ctx.chosenSecondTargetId === undefined) return;

    const creature = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    if (!creature) return;
    const magi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenSecondTargetId);
    if (!magi) return;

    // Read BEFORE the discard below -- discardFromPlay zeroes currentEnergy on the way out.
    const amount = 2 * (creature.currentEnergy ?? 0);
    if (amount > 0) discardEnergy(ctx.state, ctx.cardDb, magi, amount, 'spell', undefined, ctx.rng);

    // Re-resolve: the Magi's energy loss can defeat it, which can cascade (e.g. an onOwnMagiDefeated
    // reactor discarding Creatures), so the sacrifice target may already be gone by now.
    if (findCreatureOrMagiById(ctx.state, creature.instanceId)) {
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, creature.instanceId, undefined, 'spell', ctx.rng);
    }
  },
});
