// Will of Orothe (Spell, Orothe, cost 6) -- "Choose any one opponent. During his or her next turn,
// the chosen opponent's Creatures may not use Powers." "Choose an opponent" collapses to "the
// opponent" in 2-player (same simplification Pearl Hyren's Jealousy already uses), so no separate
// player-picker is needed. New PlayerState.creaturePowersLockedUntilTurn field (types/state.ts),
// checked generically in power.ts#isLegalPowerUse for any Power whose source is a Creature
// controlled by the locked player -- a PLAYER-level lock, not a per-instance duration tag, since it
// must also cover Creatures played after this Spell resolves.

import { registerCardEffect } from './registry.js';
import { getOpponents } from '../types/state.js';
import { nextTurnNumberFor } from '../durationTags.js';

registerCardEffect('Will of Orothe', {
  resolveSpell: (ctx) => {
    const opponent = getOpponents(ctx.state, ctx.controllingPlayer.playerId)[0];
    if (!opponent) return;
    opponent.creaturePowersLockedUntilTurn = nextTurnNumberFor(ctx.state, opponent.playerId);
  },
});
