// Ullig's Ring -- "At the end of your turn, if all Spells in your discard pile are Kybar's Teeth,
// discard each of your non-Kybar's Teeth cards from play and choose an opposing Magi. Until the
// beginning of your next turn, each of that Magi's Creatures cost one additional energy to play."
//
// The condition + mass-wipe half was already built via purityRing.ts's shared applyPurity. The
// payoff needed play.ts's cost-modification hook to exist (Phase 3, 2026-07-11) AND the P1 cost/
// starting-energy decoupling (2026-07-12) to be buildable CORRECTLY, since it's a plain "cost"
// surcharge, not a "starting energy" change -- both landed since this was last touched. Real
// choice ("choose an opposing Magi," no qualifier beyond "opposing"): reuses the existing
// pendingTargetChoice/resolveTargetChoice mechanism, same shape as Nagsis' Sigil's own Purity
// payoff (nagsisSigil.ts is the template) -- the surcharge tag lands on the CHOSEN MAGI's own
// CardInstance (durationTags.ts's ULLIG_RING_SURCHARGE), not on Ullig's Ring itself, since the
// surcharge follows whichever Magi was picked.

import { registerCardEffect } from './registry.js';
import { applyPurity } from './purityRing.js';
import { opposingMagi } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag, addDurationTag, hasDurationTag, beginningOfNextOwnTurnNumber, ULLIG_RING_SURCHARGE } from '../durationTags.js';

const PURITY_PENDING = 'ulligsRingPurityPending';

registerCardEffect("Ullig's Ring", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, "Kybar's Teeth", rng)) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    if (opposingMagi(state, cardDb, self.controllerId).length === 0) return;
    addPendingChoiceTag(self, PURITY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(PURITY_PENDING)) return undefined;
    const pool = opposingMagi(state, cardDb, self.controllerId);
    if (pool.length === 0) return undefined;
    return { prompt: "Ullig's Ring's Purity: choose an opposing Magi -- their Creatures cost one additional energy to play until your next turn", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, PURITY_PENDING);
    if (!chosenInstanceId) return;
    const target = opposingMagi(state, cardDb, self.controllerId).find((m) => m.instanceId === chosenInstanceId);
    if (!target) return;
    addDurationTag(state, cardDb, target, ULLIG_RING_SURCHARGE, beginningOfNextOwnTurnNumber(state));
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playedDef.card_type !== 'Creature') return 0;
    const player = state.players.get(playerId);
    if (!player?.activeMagi) return 0;
    return hasDurationTag(player.activeMagi, ULLIG_RING_SURCHARGE) ? 1 : 0;
  },
});
