// Spirit Drain (Spell, Bograth/Paradwyn) -- "Choose any one player. Discard energy from the chosen
// player's Magi equal to the number of cards in that player's hand." Bograth Spell pass, Category A
// (2026-07-20). "Choose any one player" is the standard Magi-proxy pattern (registry.ts's
// DeckSearchShape.whoseDeck doc comment, Warlum's Materialize precedent) -- the target pool is
// allMagiInPlay (own included, since the text doesn't say "opposing"), and the chosen Magi's own
// instance is both the "chosen player" identifier and the energy-loss target. hand.length is read
// the same way hasseth.ts/grimGoblet.ts already read an opponent's hand size.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Spirit Drain', {
  spellTargets: (state) => allMagiInPlay(state),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Magi') return;
    const owner = ctx.state.players.get(target.controllerId);
    if (!owner) return;
    discardEnergy(ctx.state, ctx.cardDb, target, owner.hand.length, 'spell', undefined, ctx.rng);
  },
});
