// Caldera Aq -- "Heartwarming: After a Cald Power removes energy from one or more Creatures, you
// may discard Caldera Aq to draw a card." No "your"/"opposing" qualifier on either the acting
// player or the target Creature(s) -- built via the new task #31 registry.ts hook
// onAnyPowerDiscardedEnergyFromCreature, broadcast to both sides after ANY Power resolves.
// "You may" auto-applied (same no-interactive-mid-resolution-prompt convention as every other
// unprompted "may" this project has used) -- trading Caldera Aq for a card draw has no real
// decision to make without a choice-prompt UI that doesn't exist for this trigger shape yet.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, drawCards } from '../effects.js';

registerCardEffect('Caldera Aq', {
  onAnyPowerDiscardedEnergyFromCreature: (state, cardDb, self, sourceCard, _amount, rng) => {
    const sourceDef = cardDb.get(sourceCard.definitionKey);
    if (!sourceDef?.regions.includes('Cald')) return;

    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    drawCards(state, cardDb, owner, 1);
  },
});
