// Stagadan Charger -- "Siphon (X): Choose an opposing Magi and one of your other Creatures. Move
// X energy from the chosen Magi to the chosen Creature. Use this Power only before your Attack
// step." X-cost Power (power.ts's chosenXValue), same reuse pattern as Qwade's Leech. Slot 2's
// pool excludes Stagadan Charger itself precisely (2026-07-08 fix -- see registry.ts's
// powerTargets doc comment, same bug/fix as Flame Rudwot).

import { registerCardEffect } from './registry.js';
import { opposingMagi, creaturesControlledBy, findCreatureOrMagiById, findInPlayById } from '../targeting.js';
import { rearrangeEnergy } from '../effects.js';

registerCardEffect('Stagadan Charger', {
  legalPhases: ['prs1'],
  powerTargetSlots: (state, cardDb, playerId, _powerName, sourceInstanceId) => [
    {
      label: 'Choose an opposing Magi',
      pool: (s, db, pid) => opposingMagi(s, db, pid),
      min: 1,
      max: 1,
    },
    {
      label: 'Choose one of your other Creatures',
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid).filter((c) => c.instanceId !== sourceInstanceId),
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Siphon') return;
    if (ctx.chosenXValue === undefined || ctx.chosenXValue < 0) return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const magiId = slots[0]?.[0];
    const creatureId = slots[1]?.[0];
    if (!magiId || !creatureId || creatureId === ctx.source.instanceId) return;

    const magi = findCreatureOrMagiById(ctx.state, magiId);
    if (!magi) return;
    const creature = findInPlayById(ctx.state, creatureId);
    if (!creature || ctx.cardDb.get(creature.definitionKey)?.card_type !== 'Creature') return;
    if (creature.controllerId !== ctx.controllingPlayer.playerId) return;

    rearrangeEnergy(ctx.state, ctx.cardDb, magi, creature, ctx.chosenXValue, ctx.rng);
  },
});
