// Amulet of Sand -- "Native Wisdom: Once per turn, when you play a d'Resh Spell, discard one
// energy from each opposing Creature." Buildable without any Spell effect-execution system
// existing -- this reacts to the mere ACT of playing a d'Resh Spell, not to whatever the Spell's
// own (unimplemented) text does. "Native Soil: Your non-d'Resh cards cost one additional energy
// to play" is registry.ts's costModifier (2026-07-11) -- unlike narSurcharge.ts's shared "non-Nar,
// non-Universal" clause, this one has no Universal exemption (per its own printed wording), so it
// gets its own inline check rather than reusing that helper.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { opposingCreatures } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const NATIVE_WISDOM_USED_THIS_TURN = 'amuletOfSandNativeWisdomUsedThisTurn';

registerCardEffect('Amulet of Sand', {
  // Per-Effect hook narrowing (deep-dive audit, 2026-08-13). Native Wisdom fires when a d'Resh
  // Spell is played (once/turn); Native Soil is the non-d'Resh surcharge.
  effectHooks: {
    'Native Wisdom': ['onPlay'],
    'Native Soil': ['costModifier'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Spell' || !playedDef.regions.includes("d'Resh")) return;
    if (hasDurationTag(self, NATIVE_WISDOM_USED_THIS_TURN)) return;

    for (const creature of opposingCreatures(state, cardDb, self.controllerId)) {
      discardEnergy(state, cardDb, creature, 1, 'effect');
    }
    addDurationTag(state, cardDb, self, NATIVE_WISDOM_USED_THIS_TURN, state.turnNumber);
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    return playedDef.regions.includes("d'Resh") ? 0 : 1;
  },
});
