// Poison Baloo Root -- both printed clauses:
//   "Wither (1): Discard one energy from all opposing Creatures." No target.
//   "Dreamwarp: As you play Poison Baloo Root, increase or decrease its starting energy by up to
//   one, until the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import { opposingCreatures } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Poison Baloo Root', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Wither') return;
    for (const creature of opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
    }
  },
  dreamwarpRange: () => 1,
});
