// Brittlebreak (Spell) -- "All Creatures lose energy equal to the number of their Magi's Relics."
// Nar Spell pass, Category A (2026-07-22). No target -- board-wide loop; for each Creature, counts
// Relics controlled by that SAME Creature's controller (allRelicsInPlay filtered by controllerId,
// not by which Magi is "theirs" specifically -- a controller has exactly one active Magi at a time,
// so "their Magi's Relics" and "Relics they control" are the same set).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allRelicsInPlay } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Brittlebreak', {
  resolveSpell: (ctx) => {
    const relics = allRelicsInPlay(ctx.state, ctx.cardDb);
    for (const c of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      const count = relics.filter((r) => r.controllerId === c.controllerId).length;
      if (count > 0) discardEnergy(ctx.state, ctx.cardDb, c, count, 'spell', undefined, ctx.rng);
    }
  },
});
