// Saladarit -- "Guard (2): Choose any one Cald or Orothe Creature in play. Until the beginning of
// your next turn, the first time the chosen Creature is attacked, discard the attacking Creature
// from play before energy is removed." A "defensive trap": the new DISCARDS_ATTACKER_ONCE
// duration tag (durationTags.ts, task #31, 2026-07-16), checked generically in combat.ts (same
// shape as STALKED/WEAKENED -- not tied to this card's own onAttack hook, since the tag itself
// could be applied by a future card too), consumed the first time it fires rather than lasting for
// every attack until its own expiry.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addDurationTag, beginningOfNextOwnTurnNumber, DISCARDS_ATTACKER_ONCE } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

// Region-swap sweep (Spell-pass audit follow-up, 2026-07-23): each of the two literals is
// independently passed through regionForTargetFilter, so swapping EITHER 'Cald' or 'Orothe'
// changes just that one term of the OR, not the whole condition.
function isCaldOrOrothe(state: GameState, cardDb: Parameters<typeof allCreaturesInPlay>[1], c: CardInstance): boolean {
  const regions = effectiveRegions(state, cardDb, c);
  return regions.includes(regionForTargetFilter(state, 'Cald')) || regions.includes(regionForTargetFilter(state, 'Orothe'));
}

registerCardEffect('Saladarit', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => isCaldOrOrothe(state, cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Guard') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!isCaldOrOrothe(ctx.state, ctx.cardDb, target)) return;

    addDurationTag(ctx.state, ctx.cardDb, target, DISCARDS_ATTACKER_ONCE, beginningOfNextOwnTurnNumber(ctx.state));
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Cald', 'Orothe'],
});
