// Gruk -- "Undream (1): Choose any one of your Creatures in play. Return the chosen Creature to
// its owner's hand. Add energy to Gruk equal to the Creature's printed starting energy or current
// energy, whichever is less." Same shape as Mushroom Hyren's Sanctuary, but the energy goes to
// Gruk itself (the Magi using the Power) instead of the current Magi generically. The
// printed-starting-energy cap is an official 2i Design errata (data-pipeline/output/rulings.json,
// applied 2026-07-09) -- previously this moved the Creature's full CURRENT energy uncapped.
// Capture-then-return-then-add, NOT rearrangeEnergy -- see Alaban Gloves' comment for why.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById, printedStartingEnergy } from '../targeting.js';
import { addEnergy, returnToHand } from '../effects.js';

registerCardEffect('Gruk', {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Undream') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;

    const amount = Math.min(target.currentEnergy ?? 0, printedStartingEnergy(ctx.cardDb, target.definitionKey));
    returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId);
    if (amount > 0) addEnergy(ctx.state, ctx.cardDb, ctx.source, amount, 'power');
  },
});
