// Rumble Stones -- "Mini-Quake (2): Remove one energy from each non-Underneath Creature and
// Magi." No target -- a region-filtered sweep across Creatures AND Magi, both sides.
//
// Bug fix (2026-07-21, playtest report): used to read the printed region straight off the card
// database (cardDb.get(...).regions), which never reflects a live effectiveRegionOverride (e.g. a
// Creature stolen and made Core via Corrupt/Turn/Crushing Darkness/Spirit of the Core) -- so a
// stolen, now-Core Creature was still (incorrectly) treated as Underneath and exempted. Switched
// to targeting.ts's effectiveRegions(), the established opt-in helper for exactly this.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { getOpponents } from '../types/state.js';

registerCardEffect('Rumble Stones', {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- static region check mirroring
  // resolvePower's own gating below, no execution.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options, powerName) => {
    if (powerName !== 'Mini-Quake') return false;
    const specifiedRegion = regionForTargetFilter(state, 'Underneath');
    return getOpponents(state, actingPlayerId).some(
      (opp) => opp.activeMagi && !effectiveRegions(state, cardDb, opp.activeMagi).includes(specifiedRegion)
    );
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mini-Quake') return;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, 'Underneath'))) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 1, undefined, undefined, ctx.rng);
      }
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, magi).includes(regionForTargetFilter(ctx.state, 'Underneath'))) {
        discardEnergy(ctx.state, ctx.cardDb, magi, 1, undefined, undefined, ctx.rng);
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Underneath'],
});
