// Hubdra's Cube -- "Relic Subversion: Choose any one other Relic in play. Gain control of the
// chosen Relic, and place it on Hubdra's Cube. You may not use this Power if there is already a
// Relic on Hubdra's Cube. If Hubdra's Cube leaves play, discard all Relics on it." Unlike Karak,
// explicitly single-slot ("you may not use this Power if there is already a Relic on it"). No
// owner/region qualifier on the target ("any one OTHER Relic in play" -- not "opposing"), so this
// can take the controller's own Relics too, per the printed text.

import { registerCardEffect } from './registry.js';
import { attachCard, discardAllAttached } from '../attachedCards.js';
import { gainControl } from '../effects.js';
import type { CardInstance } from '../types/instance.js';

registerCardEffect("Hubdra's Cube", {
  // Cards stored under this one are OUT of play, not markers riding on it -- see
  // registry.ts's `holdsInertContents`. Without this, every board-wide broadcast that
  // flattens `attachedCards` (to reach the marker family) also fires the abilities of
  // whatever is sitting inertly in here.
  holdsInertContents: true,
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    if (powerName !== 'Relic Subversion') return undefined;
    return [...state.players.values()].flatMap((p) =>
      p.inPlay.filter((c) => c.instanceId !== sourceInstanceId && cardDb.get(c.definitionKey)?.card_type === 'Relic')
    );
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Relic Subversion') return;
    if (ctx.source.attachedCards.length > 0) return; // already holding one
    if (!ctx.chosenTargetId) return;
    let target: CardInstance | undefined;
    for (const player of ctx.state.players.values()) {
      target = player.inPlay.find((c) => c.instanceId === ctx.chosenTargetId);
      if (target) break;
    }
    if (!target || target.instanceId === ctx.source.instanceId) return;
    if (ctx.cardDb.get(target.definitionKey)?.card_type !== 'Relic') return;

    gainControl(ctx.state, ctx.cardDb, target, ctx.controllingPlayer.playerId);
    const index = ctx.controllingPlayer.inPlay.findIndex((c) => c.instanceId === target!.instanceId);
    if (index === -1) return;
    const [stolen] = ctx.controllingPlayer.inPlay.splice(index, 1);
    attachCard(ctx.source, stolen!);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;
    discardAllAttached(state, cardDb, self);
  },
});
