// Whiteout (Spell) -- "Until the end of your next turn, all Creatures in play are frozen. Powers
// on frozen cards cost one additional energy to use." Nar Spell pass, Category A (2026-07-22). No
// target -- board-wide addDurationTag(FROZEN), same "until the end of your next turn" expiry
// convention as every other nextOwnTurnNumber-based tag. The Power-cost clause needs ZERO code:
// power.ts's cost computation already applies a flat +1 to ANY frozen card's Power unconditionally
// ("FROZEN's baseline rule," durationTags.ts's own doc comment) -- Whiteout only needs to make the
// board Frozen, the surcharge follows automatically.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { addDurationTag, FROZEN, nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Whiteout', {
  resolveSpell: (ctx) => {
    const expiry = nextOwnTurnNumber(ctx.state);
    for (const c of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      addDurationTag(ctx.state, ctx.cardDb, c, FROZEN, expiry);
    }
  },
});
