// Olum Fiend -- "Skulk (1): Choose an opposing d'Resh Creature and discard one energy from it.
// That Creature is an Illusion until the end of your next turn. Illusions are not considered in
// play when checking to see if your Magi is defeated and cannot attack Magi directly." Promoted
// out of docs/deferred-card-mechanics.md's "medium" bucket now that ILLUSION is built -- the
// turn-limited counterpart to Sand Strands' permanent version of the same tag.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, ILLUSION, nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Olum Fiend', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)).filter(
      (c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, "d'Resh"))
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Skulk') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, "d'Resh"))) return;

    discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
    addDurationTag(ctx.state, ctx.cardDb, target, ILLUSION, nextOwnTurnNumber(ctx.state));
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ["d'Resh"],
});
