// Epik -- "Dream Feast (1): Choose any one player. Discard Epik from play. Look at the chosen
// player's hand and choose up to two Creature cards there. The player discards the chosen
// cards." First user of registry.ts's chooseFromOpponentHand -- the ACTIVE player (not the
// target) does the choosing here, from the TARGET's hand, filtered to Creature cards. If Dream
// Feast's cost happens to exactly zero out Epik's own energy, power.ts's automatic
// Creature-defeat check (step 3) may have already discarded it before this resolvePower runs
// (see Black Agovo, same interaction) -- tolerate that rather than assuming it's still in play.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardFromHand, discardFromPlay } from '../effects.js';

registerCardEffect('Epik', {
  powerTargets: (state) => allMagiInPlay(state),
  causesOpponentHandDiscard: true, // task #718 (Riptide clause 2, 2026-08-11)
  chooseFromOpponentHand: {
    maxCount: 2,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Feast') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const targetOwner = ctx.state.players.get(chosenMagi.controllerId);
    if (!targetOwner) return;

    if (ctx.controllingPlayer.inPlay.some((c) => c.instanceId === ctx.source.instanceId)) {
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    }

    const offered = ctx.chosenFromOpponentHandIds ?? [];
    const validIds = offered.filter((id) => {
      const card = targetOwner.hand.find((c) => c.instanceId === id);
      return !!card && ctx.cardDb.get(card.definitionKey)?.card_type === 'Creature';
    });
    if (validIds.length > 0) discardFromHand(ctx.state, ctx.cardDb, targetOwner, validIds.slice(0, 2), undefined, ctx.rng);
  },
});
