// Auraflection -- shared "copy a Power on your Magi, paying all costs" mechanism used by Rayje's
// Construct and Mirror Pendant. It reuses the EXISTING copyPowerChoice picker (registry.ts, task #30:
// Nahara/Taglat): the UI offers each of the acting Magi's Powers and encodes the pick as the
// composite `${magi.instanceId}::${powerName}` through chosenTargetId. `invokeCopiedMagiPower` parses
// that back out, pays the copied Power's own energy cost (plus any surcharge -- Mirror Pendant adds
// two) from the Magi, then re-executes the Magi's own resolvePower with the Magi as the source.
//
// A one-shot borrow, distinct from copiedPowers.ts (a REUSABLE copy). Legality/once-per-turn are
// intentionally bypassed -- "play all actions of the chosen Power" replays the actions directly.
// SIMPLIFICATION: because the copy PICK reuses chosenTargetId, there's no separate field left for the
// copied Power's OWN target, so a targeted Magi Power's target clause is dropped (chosenTargetId is
// cleared before re-execution). Non-targeting Magi Powers (draw, energy-to-self, etc.) copy fully.

import { getCardEffectByName } from './registry.js';
import { discardEnergy } from '../effects.js';
import type { CardDatabase, Power } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState, PlayerId } from '../types/state.js';
import type { PowerContext } from '../power.js';

/** copyPowerChoice pool for an Auraflection Power: every Power on the acting player's active Magi. */
export function magiPowerCopyPool(state: GameState, cardDb: CardDatabase, playerId: PlayerId): Array<{ card: CardInstance; power: Power }> {
  const magi = state.players.get(playerId)?.activeMagi;
  const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
  if (!magi || !magiDef) return [];
  return magiDef.powers.map((power) => ({ card: magi, power }));
}

export function invokeCopiedMagiPower(ctx: PowerContext, surcharge: number): void {
  const magi = ctx.controllingPlayer.activeMagi;
  if (!magi || !ctx.chosenTargetId) return;
  const [magiInstanceId, powerName] = ctx.chosenTargetId.split('::');
  if (magiInstanceId !== magi.instanceId || !powerName) return;
  const magiDef = ctx.cardDb.get(magi.definitionKey);
  const chosen = magiDef?.powers?.find((p) => p.name === powerName);
  if (!magiDef || !chosen) return;
  const copiedCost = (typeof chosen.cost === 'number' ? chosen.cost : 0) + surcharge;
  if ((magi.currentEnergy ?? 0) < copiedCost) return; // "paying all costs" -- must be affordable
  discardEnergy(ctx.state, ctx.cardDb, magi, copiedCost, 'power', ctx.controllingPlayer.playerId);
  getCardEffectByName(magiDef.name)?.resolvePower?.({ ...ctx, powerName, source: magi, chosenTargetId: undefined });
}
