// Orathan Amulet -- both printed pieces:
//   "Pod: Search your deck for an Orathan card. Place that card into your hand."
//   "Spray: At the end of your turn, add one energy to each of your Orathans in play." Routed
//   through matchesCreatureFamily (Swirling Orshaa's Morph, Effect-half turn-boundary bucket,
//   2026-07-24) so a morphed Orshaa counts too -- turnBoundaryCreatureTypes declares the
//   reference for previewIdentityOverrideOffersForTurnBoundary to read. Pod's own deckSearch
//   filter stays a raw name check (a card sitting in the deck has no identityOverride to consult).

import { registerCardEffect } from './registry.js';
import { searchDeck, addEnergy } from '../effects.js';
import { creaturesControlledBy, matchesCreatureFamily } from '../targeting.js';

registerCardEffect('Orathan Amulet', {
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.name.includes('Orathan') ?? false,
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Pod') return;
    const ids = ctx.chosenDeckSearchIds ?? [];
    if (ids.length > 1) return;
    for (const id of ids) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      if (!card || !ctx.cardDb.get(card.definitionKey)?.name.includes('Orathan')) return;
    }
    searchDeck(ctx.state, ctx.controllingPlayer, ids, ctx.rng);
  },
  onOwnTurnEnd: (state, cardDb, self) => {
    for (const creature of creaturesControlledBy(state, cardDb, self.controllerId)) {
      if (matchesCreatureFamily(cardDb, creature, 'Orathan')) {
        addEnergy(state, cardDb, creature, 1, 'effect');
      }
    }
  },
  turnBoundaryCreatureTypes: () => ['Orathan'],
});
