// Ice Lens -- "Magnify: During your Draw step, if you have a frozen card in play, draw an
// additional card." Built task #43, 2026-07-18, the Nar region pass -- Category B. Reuses the
// existing isFrozen reader (durationTags.ts) + drawCountModifier (Scarletsong Banner's own
// "own contributors only" shape, turn.ts's runDrawPhase).

import { registerCardEffect } from './registry.js';
import { isFrozen } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';

registerCardEffect('Ice Lens', {
  drawCountModifier: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return 0;
    const candidates: CardInstance[] = player.activeMagi ? [...player.inPlay, player.activeMagi] : [...player.inPlay];
    const hasFrozen = candidates.some((c) => isFrozen(state, cardDb, c));
    return hasFrozen ? 1 : 0;
  },
});
