// Aula, Mindseeker -- "Windsight: Discard a Spell from your hand. Draw a number of cards equal to
// half of the Spell's energy cost, rounded down (X equals zero) and reveal them to your opponent.
// You cannot draw any more cards this turn." A different card from plain Aula. "Reveal to your
// opponent" is a UI/knowledge concern only, unenforced (consistent with every other hidden-hand
// visibility rule this engine doesn't police). "Cannot draw any more cards this turn"
// (region-audit follow-up, 2026-07-24) uses the new PlayerState.cannotDrawThisTurn choke point --
// see its own doc comment in types/state.ts. Set AFTER Windsight's own draw completes (the
// lockout blocks FUTURE draws, not this one).

import { registerCardEffect } from './registry.js';
import { drawCards, discardFromHand } from '../effects.js';

registerCardEffect('Aula, Mindseeker', {
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Spell',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Windsight') return;
    const id = (ctx.chosenHandCardIds ?? [])[0];
    if (!id) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
    const def = discardedCard ? ctx.cardDb.get(discardedCard.definitionKey) : undefined;
    if (!def || def.card_type !== 'Spell') return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [id], undefined, ctx.rng);
    const cost = typeof def.cost === 'number' ? def.cost : 0;
    const count = Math.floor(cost / 2);
    if (count > 0) drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, count);
    ctx.controllingPlayer.cannotDrawThisTurn = true;
  },
});
