// Zajan -- two printed clauses:
//   "Work All Night: Zajan does not energize as normal during the energize step. Zajan energizes
//   during the draw step." -- registry.ts's deferEnergizeToDraw, self-only.
//   "Sleep All Day: Zajan draws two cards during the energize step. Zajan does not draw cards as
//   normal during the draw step." -- registry.ts's drawsDuringEnergizeInstead (draws 2 during
//   Energize) paired with drawCountModifier (-2, suppressing the normal Draw-step amount to 0 --
//   Zajan is the active Magi, so this reads as "the whole turn's draw," matching the printed
//   text's own framing of the draw as something Zajan personally does).

import { registerCardEffect } from './registry.js';

registerCardEffect('Zajan', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Work All Night moves the energize step; Sleep
  // All Day owns the swapped drawing pair.
  effectHooks: {
    'Work All Night': ['deferEnergizeToDraw'],
    'Sleep All Day': ['drawsDuringEnergizeInstead', 'drawCountModifier'],
  },
  deferEnergizeToDraw: (state, cardDb, candidate, self) => candidate.instanceId === self.instanceId,
  drawsDuringEnergizeInstead: () => 2,
  drawCountModifier: () => -2,
});
