// Crushing Fungus (Spell, Underneath, cost 4) -- "Choose any one Creature in play. Discard four
// energy from the chosen Creature. If this discards the chosen Creature from play, its Magi does
// not energize on his or her next turn. Only Underneath Magi and Underneath Shadow Magi can play
// Crushing Fungus." Underneath Spell pass, Category B (2026-07-25).
//
// Member of the "Crushing [Element]" cycle (Crushing Stones/Winds/Vines/Roots/...), and built to
// the same shape as its already-built siblings: the Magi-restriction clause needs no code here --
// `region_restrictive: true` + `shadow_play: "Underneath"` are already set on this card's own data,
// which regions.ts's checkRegionLegality/isExemptFromRestriction handle generically. And like
// Crushing Vines, the conditional clause re-confirms the target actually LEFT play rather than
// trusting a same-turn "it only had 4 energy" prediction (damage reduction, Mijji's Guardian, etc.
// can all leave it alive at 1).
//
// The penalty is stored against the specific Magi instance, not the player -- see types/state.ts's
// skipEnergizeForMagiInstanceId for why ("its Magi," so a replacement Magi energizes normally) and
// turn.ts#runEnergizePhase for where it is consumed.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Crushing Fungus', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const victimPlayerId = target.controllerId;

    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);

    if (findInPlayById(ctx.state, ctx.chosenTargetId)) return; // survived -- no energize penalty

    const victim = ctx.state.players.get(victimPlayerId);
    if (victim?.activeMagi) {
      victim.skipEnergizeForMagiInstanceId = victim.activeMagi.instanceId;
    }
  },
});
