// Ambush (Spell, Paradwyn, cost 4) -- "Choose any one Creature in play. The chosen Creature loses
// energy equal to its starting energy." printedStartingEnergy already accounts for a per-instance
// startingEnergyOverride (Slime Stone etc); discardEnergy clamps to whatever the Creature actually
// has, same as every other flat-amount energy-loss Spell.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveStartingEnergy } from '../targeting.js';

registerCardEffect('Ambush', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    const amount = effectiveStartingEnergy(ctx.state, ctx.cardDb, target);
    if (amount > 0) discardEnergy(ctx.state, ctx.cardDb, target, amount, 'spell', undefined, ctx.rng);
  },
});
