// Bwill -- "Karma: If any Creature attacks and defeats Bwill, discard that Creature from play."
// afterCombat, self as the DEFEATED DEFENDER -- discards the attacker in response, regardless of
// which side it belongs to.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Bwill', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    if (outcome.defenderSurvived) return;

    const owner = ctx.state.players.get(ctx.attacker.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, ctx.attacker.instanceId, undefined, undefined, ctx.rng);
  },
});
