// Underneath Shadow Geyser (Spell, Core, cost 5) -- "The energy cost for this Geyser is zero if
// played by an Underneath Shadow Magi. In order to play this Geyser, you must discard six Core
// cards from your hand. Place this Geyser on the table. All non-Core Magi with an Underneath card
// in play draw one less card during their Draw Step. Draw one additional card during your Draw
// Step. You may not play another Underneath Shadow Geyser while this one is in play. If your Magi
// leaves play, you may keep all but one of your Shadow Geysers in play. Agram does not discard any
// Shadow Geysers from play when he leaves play." Task #53-9, 2026-07-21, the Core Spell pass's A2
// checkpoint.
//
// The draw-count clauses use `anyDrawCountModifier` (Ebony Mirror precedent) rather than the
// own-side-only `drawCountModifier` -- this Geyser's controller's own bonus draw AND the penalty
// applied to a DIFFERENT player's draw both need to be expressed from the SAME broadcast-scanned
// hook, keyed off the drawing player's id. "Non-Core Magi" reads through `effectiveMagiDef` (task
// #53-6's Shadow-Magi-identity override) so a Shadow Magi of any region -- static or
// runtime-granted -- correctly counts as Core and is exempt from the penalty, matching how every
// other region-legality check in this pass already treats Shadow Magi.

import { registerCardEffect } from './registry.js';
import { effectiveMagiDef } from '../regions.js';
import { effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromHand } from '../effects.js';
import {
  castByShadowMagiOf,
  geyserSurvivesOwnMagiDefeat,
  geyserOnOwnMagiDefeated,
  geyserPendingTargetChoice,
  geyserResolveTargetChoice,
} from './shadowGeysers.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const NAME = 'Underneath Shadow Geyser';

function qualifyingHandCards(state: GameState, cardDb: CardDatabase, playerId: string): number {
  const player = state.players.get(playerId);
  if (!player) return 0;
  const specifiedRegion = regionForTargetFilter(state, 'Core');
  return player.hand.filter((c) => cardDb.get(c.definitionKey)?.regions.includes(specifiedRegion)).length;
}

registerCardEffect(NAME, {
  selfCostOverride: (state, cardDb, playerId) => (castByShadowMagiOf(state, cardDb, playerId, 'Underneath') ? 0 : undefined),
  spellHandDiscardCost: {
    count: 6,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(state, 'Core')) ?? false,
  },
  preventsOwnPlay: (state, cardDb, playerId) => {
    if (qualifyingHandCards(state, cardDb, playerId) < 6) {
      return 'Underneath Shadow Geyser requires 6 Core cards in hand to discard as its cost';
    }
    const player = state.players.get(playerId);
    if (player?.inPlay.some((c) => cardDb.get(c.definitionKey)?.name === NAME)) {
      return 'You may not play another Underneath Shadow Geyser while this one is in play';
    }
    return false;
  },
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    const ids = ctx.chosenHandCardIds ?? [];
    if (ids.length !== 6) return;
    const specifiedRegion = regionForTargetFilter(ctx.state, 'Core');
    const valid = ids.every((id) => {
      const card = ctx.controllingPlayer.hand.find((c) => c.instanceId === id);
      return card && ctx.cardDb.get(card.definitionKey)?.regions.includes(specifiedRegion);
    });
    if (!valid) return;
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids, undefined, ctx.rng);
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  // "Non-Core Magi with an Underneath card... draw one less" is a passive continuous draw-count
  // modifier, not gated by "using this Spell/Power" -- state.activeRegionSwap is only ever set for
  // the ONE usePower/playCard call the swap applies to, and is back to null by the time any later
  // Draw Step runs. Out of scope for the region-swap sweep, same reasoning as costModifier clauses.
  anyDrawCountModifier: (state, cardDb, self, drawingPlayerId) => {
    let delta = 0;
    if (drawingPlayerId === self.controllerId) delta += 1;
    const drawingPlayer = state.players.get(drawingPlayerId);
    const magiInstance = drawingPlayer?.activeMagi;
    if (magiInstance) {
      const magiDef = cardDb.get(magiInstance.definitionKey);
      const isNonCore = magiDef ? effectiveMagiDef(magiDef, magiInstance).regions.every((r) => r !== 'Core') : false;
      const hasUnderneathCardInPlay = drawingPlayer?.inPlay.some((c) => effectiveRegions(state, cardDb, c).includes('Underneath')) ?? false;
      if (isNonCore && hasUnderneathCardInPlay) delta -= 1;
    }
    return delta;
  },
  survivesOwnMagiDefeat: geyserSurvivesOwnMagiDefeat,
  onOwnMagiDefeated: geyserOnOwnMagiDefeated,
  pendingTargetChoice: geyserPendingTargetChoice,
  resolveTargetChoice: geyserResolveTargetChoice,
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Only the spellHandDiscardCost region is in scope;
  // anyDrawCountModifier above is not (see its own comment).
  specifiedSpellTargetRegions: () => ['Core'],
});
