// Amulet of Ombor -- "Energy Boost: Roll one die. 1, 2, or 3 = Your opponents add one energy to
// each of their Creatures in play. 4 or 5 = Choose any one Creature in play. Add two energy to
// the chosen Creature. 6 = Choose any one Creature in play. Add four energy to the chosen
// Creature." Same "offer the union of what any branch could need" simplification as Gorgle's Ring.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';
import { getOpponents } from '../types/state.js';
import { addEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';

registerCardEffect('Amulet of Ombor', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Energy Boost') return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'amuletOfOmbor:energyBoost',
      { controllingPlayerId: ctx.controllingPlayer.playerId, chosenTargetId: ctx.chosenTargetId },
      ctx.rng
    );
  },
});

registerRollConsumer('amuletOfOmbor:energyBoost', (state, cardDb, _source, payload, finalRoll) => {
  const { controllingPlayerId, chosenTargetId } = payload as { controllingPlayerId: string; chosenTargetId?: string };
  if (finalRoll <= 3) {
    for (const opponent of getOpponents(state, controllingPlayerId)) {
      for (const creature of creaturesControlledBy(state, cardDb, opponent.playerId)) {
        addEnergy(state, cardDb, creature, 1, 'power');
      }
    }
    return;
  }
  if (chosenTargetId === undefined) return;
  const target = findInPlayById(state, chosenTargetId);
  if (!target || cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
  addEnergy(state, cardDb, target, finalRoll <= 5 ? 2 : 4, 'power');
});
