// Ythra's Mantle -- "Prepare: Search your deck for one of your starting cards and place it into
// your hand." The Magi's starting-card list is already tracked on its own CardDefinition (the
// `starting` field, same one setup.ts's opening-hand tutoring reads).

import { registerCardEffect } from './registry.js';
import { searchDeck } from '../effects.js';

registerCardEffect("Ythra's Mantle", {
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const magi = state.players.get(playerId)?.activeMagi;
      const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
      const cardName = cardDb.get(card.definitionKey)?.name;
      return !!cardName && (magiDef?.starting?.includes(cardName) ?? false);
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Prepare') return;
    const ids = ctx.chosenDeckSearchIds ?? [];
    if (ids.length > 1) return;
    const magi = ctx.controllingPlayer.activeMagi;
    const magiDef = magi ? ctx.cardDb.get(magi.definitionKey) : undefined;
    for (const id of ids) {
      const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
      const cardName = card ? ctx.cardDb.get(card.definitionKey)?.name : undefined;
      if (!cardName || !(magiDef?.starting?.includes(cardName) ?? false)) return;
    }
    searchDeck(ctx.state, ctx.controllingPlayer, ids, ctx.rng);
  },
});
