// Ashgar -- "Nerve: If a Creature attacks Ashgar directly, draw a card before energy is removed."

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Ashgar', {
  onAttack: (ctx, self) => {
    if (ctx.defender !== null) return; // "directly" -- a Magi attack, not a Creature attack
    if (ctx.defendingPlayer.activeMagi?.instanceId !== self.instanceId) return;
    drawCards(ctx.state, ctx.cardDb, ctx.defendingPlayer, 1);
  },
});
