// Wither Twee -- "Sweet Rot: If Wither Twee is defeated in an attack, add one energy to each
// Bograth Creature and draw a card." Same combat-caused zero-energy shape as Brog's Fertilize --
// "defeated in an attack" is `cause === 'zero-energy'` with `source === 'combat'`.

import { registerCardEffect } from './registry.js';
import { addEnergy, drawCards } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions } from '../targeting.js';

registerCardEffect('Wither Twee', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source) => {
    if (discarded.instanceId !== self.instanceId) return;
    if (cause !== 'zero-energy' || source !== 'combat') return;

    for (const creature of allCreaturesInPlay(state, cardDb)) {
      if (effectiveRegions(state, cardDb, creature).includes('Bograth')) {
        addEnergy(state, cardDb, creature, 1, 'effect');
      }
    }
    const owner = state.players.get(discardedOwnerId);
    if (owner) drawCards(state, cardDb, owner, 1);
  },
});
