// Sandshape (Spell) -- "Discard a d'Resh Relic from play to play a d'Resh card in your hand,
// reducing the cost of the card by half (rounded down). Creatures played this way cannot attack
// this turn."
//
// Two sequential picks (spellTargets: which own d'Resh Relic to discard; spellSecondTargets: which
// own d'Resh card in hand to play). Cost payment and zone placement are handled manually rather
// than through play.ts's normal pipeline (Tempest Hyren's Lightning Storm precedent: compute a
// reduced cost directly, pay it from the Magi, then place the card) -- `forcePlayFromHand`
// (effects.ts) already does the "figure out the right zone/starting-energy for this card_type"
// part generically, so it's reused for placement only, AFTER cost is paid separately (unlike its
// other callers, which are all fully free).

import { registerCardEffect } from './registry.js';
import { discardFromPlay, forcePlayFromHand } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { findInPlayById, effectiveRegions, regionForTargetFilter } from '../targeting.js';

registerCardEffect('Sandshape', {
  spellTargets: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player) return [];
    return player.inPlay.filter((c) => {
      const def = cardDb.get(c.definitionKey);
      return def?.card_type === 'Relic' && effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, "d'Resh"));
    });
  },
  spellSecondTargets: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player) return [];
    return player.hand.filter((c) => cardDb.get(c.definitionKey)?.regions.includes(regionForTargetFilter(state, "d'Resh")));
  },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined || ctx.chosenSecondTargetId === undefined) return;
    const relic = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!relic || relic.controllerId !== ctx.controllingPlayer.playerId) return;
    const relicDef = ctx.cardDb.get(relic.definitionKey);
    if (relicDef?.card_type !== 'Relic' || !effectiveRegions(ctx.state, ctx.cardDb, relic).includes(regionForTargetFilter(ctx.state, "d'Resh"))) return;

    const player = ctx.controllingPlayer;
    const handCard = player.hand.find((c) => c.instanceId === ctx.chosenSecondTargetId);
    if (!handCard) return;
    const handDef = ctx.cardDb.get(handCard.definitionKey);
    if (!handDef || !handDef.regions.includes(regionForTargetFilter(ctx.state, "d'Resh"))) return;

    discardFromPlay(ctx.state, ctx.cardDb, player, relic.instanceId, undefined, undefined, ctx.rng);

    const printedCost = typeof handDef.cost === 'number' ? handDef.cost : 0;
    const reducedCost = Math.floor(printedCost / 2);
    const magi = player.activeMagi;
    if (magi) magi.currentEnergy = Math.max(0, (magi.currentEnergy ?? 0) - reducedCost);

    const played = forcePlayFromHand(ctx.state, ctx.cardDb, player, handCard.instanceId);
    if (played && handDef.card_type === 'Creature') {
      addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ["d'Resh"],
});
