// Daydreams (Spell) -- "Reverse the order of your deck. (Deal your deck, one card at a time, into
// a single face-down pile.) Draw a card." No target, no choice -- pure sequence flip + draw.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';

registerCardEffect('Daydreams', {
  resolveSpell: (ctx) => {
    ctx.controllingPlayer.deck.reverse();
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
  },
});
