// Staff of Hyren -- "Whenever you play a Hyren, add one additional energy to it." A simpler onPlay
// broadcast than Ring of Secrets' Tinker: no choice at all -- the energy goes onto the Hyren just
// played, not a chosen Creature. "You" = self's controller; "a Hyren" is a name-family match, the
// established convention in this project (Monarch Hyren's Command, Staff of Vines, etc.).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Staff of Hyren', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Creature' || !def.name.includes('Hyren')) return;
    addEnergy(state, cardDb, played, 1, 'effect');
  },
});
