import type { GameEvent, GameState } from './types/state.js';

export function logEvent(
  state: GameState,
  type: string,
  detail: Record<string, unknown> = {}
): GameEvent {
  const event: GameEvent = {
    turnNumber: state.turnNumber,
    phase: state.phase,
    type,
    detail,
  };
  state.log.push(event);
  return event;
}
