// Thrybe -- "Infuse: When you play a d'Resh Creature, you may discard Thrybe from play. If you
// do, place a d'Resh Spell from your hand under that Creature. Treat that Spell as if it were a
// Power printed on the Creature. The cost of the Power equals the cost of the Spell, and the name
// of the Power is the name of the Spell."
//
// Task #39-3e, 2026-07-17, d'Resh Category C: same imbueSpell.ts composition as Mohani's Imbue
// Spell, but bundled with "you may discard Thrybe from play" first -- the "if you do" makes the
// Spell pick and the self-discard a single decision, not two (same "may bundled with a real pick"
// shape as Ember Vard, task #40-4: declining is just an undefined answer, no separate yes/no
// needed). Guards `played.instanceId !== self.instanceId` -- Thrybe reacting to its OWN play
// wouldn't make sense (it's about to be discarded from play in the very same resolution).

import { registerCardEffect } from './registry.js';
import { isDReshSpellInHand, imbueSpellOnto } from './imbueSpell.js';
import { discardFromPlay } from '../effects.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const AWAITING_CHOICE_PREFIX = 'thrybeInfusePending:';

function pendingCreatureId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(AWAITING_CHOICE_PREFIX)) return tag.slice(AWAITING_CHOICE_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Thrybe', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) return;
    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (!playedDef || playedDef.card_type !== 'Creature' || !playedDef.regions.includes("d'Resh")) return;
    const player = state.players.get(self.controllerId);
    if (!player || !player.hand.some((c) => isDReshSpellInHand(cardDb, c))) return;
    addPermanentTag(state, cardDb, self, `${AWAITING_CHOICE_PREFIX}${played.instanceId}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const creatureId = pendingCreatureId(self);
    if (!creatureId) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player) return undefined;
    const pool = player.hand.filter((c) => isDReshSpellInHand(cardDb, c));
    if (pool.length === 0) return undefined;
    return { prompt: "Thrybe's Infuse: discard Thrybe from play and choose a d'Resh Spell to place under the Creature you just played?", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const creatureId = pendingCreatureId(self);
    if (creatureId !== undefined) removePermanentTag(self, `${AWAITING_CHOICE_PREFIX}${creatureId}`);
    if (!chosenInstanceId || !creatureId) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const creature = player.inPlay.find((c) => c.instanceId === creatureId);
    if (!creature) return;
    imbueSpellOnto(state, cardDb, player, creature, chosenInstanceId, rng);
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
  },
});
