// Game setup (rules-reference.md §4).

import type { CardDatabase, CardDefinition } from './types/card.js';
import type { GameState, PlayerId, PlayerState } from './types/state.js';
import { getPlayer } from './types/state.js';
import type { CardInstance } from './types/instance.js';
import { createCardInstance, resetInstanceCounter } from './types/instance.js';
import { shuffle, defaultRng, type Rng } from './rng.js';
import { searchDeckForNames, drawCardsRaw, shuffleDeck } from './zones.js';
import { logEvent } from './log.js';
import { beginTurn } from './turn.js';
import { parseStartingCategory, isStartingCategory } from './startingCards.js';
import { magiIdentityNames } from './deck.js';
import { addPermanentTagRaw, STARTING_CARDS_TUTORED, KNOWN_HAND_CARD } from './durationTags.js';
import { getCardEffectByName } from './cardEffects/registry.js';

export interface PlayerSetupConfig {
  playerId: PlayerId;
  /** Non-Magi deck, 40+ cards per rules-reference.md §11. Legality isn't validated here -- deck
   *  construction rules are a deck-builder concern, not the live-game engine's. */
  deckCardKeys: number[];
  /** Exactly 3 Magi identities' worth of card keys, in the order they'll be revealed (locked in
   *  face-down for the rest of the game). */
  magiOrder: number[];
  /** Bot-region stamp for a bot-controlled seat (2026-08-16, region-locked bot flow). Copied
   *  verbatim onto `PlayerState.botRegion` -- see that field's own doc comment. Omit for human
   *  seats. Never validated against `deckCardKeys` here (region ↔ deck mapping is enforced by the
   *  app-side deck picker, which restricts the bot to the shipped default decks); passing a
   *  wrong region silently mis-tags the bot but does not corrupt any game state. */
  botRegion?: string;
}

export interface SetupOptions {
  rng?: Rng;
  /** Final turn order. If omitted, defaults to playerConfigs' given order -- call
   *  rollForTurnOrder yourself first if you want an actual die-roll to decide it. */
  turnOrder?: PlayerId[];
  /** Tutorial Mode (2026-08-10): when true, skips the initial deck shuffle below AND the starting-
   *  card tutor's post-search reshuffle (`zones.ts`'s `searchDeckForNames`) -- a Tutorial deck's
   *  authored `deckCardKeys` order becomes the exact, permanent draw order. Deliberately does NOT
   *  touch the ~30 other `shuffleDeck`/`shuffleDiscardIntoDeck` call sites scattered through
   *  individual card effects (Hyren's Call, Nocturne, etc.) or the Draw-phase empty-deck reshuffle --
   *  none of those are reachable during the tutorial's scripted opening, and leaving them real lets
   *  a later, genuinely unscripted post-hand-off game behave normally if one of those cards ever
   *  gets drawn and played. See `GameState.tutorialMode`'s own doc comment for the full picture. */
  tutorialMode?: boolean;
  /** Bucket D Batch D 2026-08-14 (first-turn mechanic): OPT-IN to the new pre-game "winner
   *  chooses to go first" phase. When true (and `turnOrder` is not also given -- explicit
   *  turnOrder always wins), `setupGame` rolls the pre-game dice via
   *  `rollForTurnOrderWithHistory`, arms `state.pendingFirstPlayerChoice`, and returns
   *  WITHOUT calling `beginTurn`. The caller (UI) MUST then invoke
   *  `resolveFirstPlayerChoice(state, cardDb, winnerId, chosenFirst, rng)` to finish setup
   *  and start turn 1.
   *
   *  Opt-in rather than default-on: 50+ existing tests + driver.ts + replay.ts call
   *  setupGame without turnOrder, expecting the legacy default-to-configs-order path.
   *  Adding a NEW opt-in preserves that unchanged. Only Play.tsx's PvP and Bot flows
   *  (2026-08-14+) pass `usePreGameChoice: true`. */
  usePreGameChoice?: boolean;
}

/** Die roll, re-rolling ties; high roll goes first (rules-reference.md §4.3). Legacy shape:
 *  returns just the sorted turn order. Used by driver.ts (bot / test harness) and replay.ts
 *  when they already own the roll and just need the resulting order. New code should prefer
 *  `rollForTurnOrderWithHistory` below, which surfaces each round's rolls for the pre-game
 *  UI dramatic-tie playback (owner Q2 2026-08-14). */
export function rollForTurnOrder(playerIds: readonly PlayerId[], rng: Rng = defaultRng): PlayerId[] {
  const { winnerId } = rollForTurnOrderWithHistory(playerIds, rng);
  return [winnerId, ...playerIds.filter((id) => id !== winnerId)];
}

/** Roll for turn order, returning the FULL history of rounds. Each round's inner array is
 *  aligned to `playerIds` (rolls[roundIdx][playerIdx]). Ties surface as their own round;
 *  the final round is the tie-breaking win. Owner Q2 2026-08-14 (Bucket D Batch D
 *  first-turn mechanic): show ties dramatically -- the UI plays back the sequence of
 *  rounds one by one, proving the ties before revealing the winner. */
export function rollForTurnOrderWithHistory(
  playerIds: readonly PlayerId[],
  rng: Rng = defaultRng
): { rolls: number[][]; winnerId: PlayerId } {
  const rolls: number[][] = [];
  for (let attempt = 0; attempt < 1000; attempt += 1) {
    const round = playerIds.map(() => 1 + Math.floor(rng() * 6));
    rolls.push(round);
    const maxRoll = Math.max(...round);
    const winnerIdx = round.findIndex((r) => r === maxRoll);
    const winnersCount = round.filter((r) => r === maxRoll).length;
    if (winnersCount === 1) {
      return { rolls, winnerId: playerIds[winnerIdx]! };
    }
  }
  throw new Error('rollForTurnOrderWithHistory: too many tied re-rolls');
}

export function setupGame(
  playerConfigs: readonly PlayerSetupConfig[],
  cardDb: CardDatabase,
  options: SetupOptions = {}
): GameState {
  const rng = options.rng ?? defaultRng;
  const tutorialMode = options.tutorialMode ?? false;
  resetInstanceCounter();

  const players = new Map<PlayerId, PlayerState>();
  for (const config of playerConfigs) {
    const deck: CardInstance[] = config.deckCardKeys.map((key) =>
      createCardInstance(key, config.playerId)
    );
    if (!tutorialMode) shuffle(deck, rng);
    const magiQueue: CardInstance[] = config.magiOrder.map((key) =>
      createCardInstance(key, config.playerId)
    );
    players.set(config.playerId, {
      playerId: config.playerId,
      deck,
      magiQueue,
      activeMagi: null,
      defeatedMagi: [],
      hand: [],
      discardPile: [],
      inPlay: [],
      hasEnergizedOnce: false,
      openingHandDrawn: false,
      pendingDrawCap: null,
      cannotDrawThisTurn: false,
      handDiscardImmuneUntilMagiDefeated: false,
      riptideBanExpiresAfterTurnNumber: null,
      pendingSpiritSpellRegions: [],
      spiritOfRayjeUsesRemaining: 3,
      pendingDefeatInterrupt: null,
      defeatInterruptDeclinedFor: null,
      oasisEnergyImmunityUntilTurn: null,
      elementalShields: [],
      attackedThisTurn: false,
      playedRelicThisTurn: false,
      cardsPlayedThisTurn: 0,
      pendingExtraTurns: 0,
      justTookAdditionalTurn: false,
      aubrasWisdomExtraDrawUntilTurn: null,
      lightningSandChargeUntilTurn: null,
      pendingMudBubbleWatch: null,
      pendingShadowGeyserReplays: [],
      pendingDrawSkipOnTurnNumber: null,
      pendingMagiRevealEnergyBonus: null,
      pendingMagiRevealDamageReduction: null,
      pendingMagiRevealEternalVigor: false,
      pendingMagiRevealOmborResilience: false,
      pendingMagiRevealStartingCardNames: null,
      sneakAttackUntilTurn: null,
      creepingChillUntilTurn: null,
      handPlayLockedUntilTurn: null,
      spellPlayLockedUntilTurn: null,
      spiritOfParadwynTurn: null,
      creaturePowersLockedUntilTurn: null,
      kybarsEchoUntilTurn: null,
      shatteringWindUntilTurn: null,
      scarletsongTrillUntilTurn: null,
      aglowUntilTurn: null,
      sabertoothTauntUntilTurn: null,
      tranquilityBanExpiresAfterTurnNumber: null,
      tranquilityExtraDrawUntilTurn: null,
      skipEnergizeForMagiInstanceId: null,
      bloomBonusActionPending: false,
      botRegion: config.botRegion ?? null,
    });
  }

  // Turn-order semantics (Bucket D Batch D 2026-08-14, first-turn mechanic):
  //   - Default (legacy): `options.turnOrder` supplied -> use it verbatim; `options.turnOrder`
  //     omitted -> default to playerConfigs order. Either way, `beginTurn` fires at the end of
  //     setupGame and turn 1 starts immediately. Preserves every existing test / driver.ts /
  //     replay.ts caller unchanged (they roll + decide externally, or don't care, and this
  //     path is what they've always gotten).
  //   - NEW opt-in path: `options.usePreGameChoice === true` (only ever set by Play.tsx's PvP
  //     and Bot flows, 2026-08-14+) initializes state with a placeholder turnOrder, arms
  //     `pendingFirstPlayerChoice` with the dice roll history + winner + Togoth restriction,
  //     and RETURNS WITHOUT calling `beginTurn`. Caller MUST then invoke
  //     `resolveFirstPlayerChoice` to overwrite `state.turnOrder`/`state.activePlayerId` and
  //     start turn 1. Explicit `options.turnOrder` wins over `usePreGameChoice` (an
  //     externally-decided turn order always short-circuits the pre-game phase, matching what
  //     replay.ts and driver.ts need). Tutorial mode also always takes the legacy path.
  const usePreGameChoice = options.usePreGameChoice === true
    && options.turnOrder === undefined
    && !tutorialMode;
  const turnOrder = options.turnOrder
    ?? playerConfigs.map((c) => c.playerId);
  // ^ For the pre-game-choice branch, this is a placeholder; `resolveFirstPlayerChoice`
  //   overwrites both `state.turnOrder` and `state.activePlayerId` before `beginTurn` fires.

  const state: GameState = {
    players,
    turnOrder,
    activePlayerId: turnOrder[0]!,
    turnNumber: 0, // beginTurn below increments this to 1
    phase: 'draw', // placeholder; beginTurn sets the real phase immediately
    // 2-player asymmetry rule (§4): the player going first skips Energize on turn 1. The 3+
    // player variant (§13) never skips it in the first place.
    skipEnergizeForFirstTurn: turnOrder.length === 2,
    skipAttackPhaseThisTurn: false,
    skipDrawStepThisTurn: false,
    turnHandoffPending: false,
    energizePending: false,
    drawPending: false,
    pendingReactiveDreamwarpInstanceId: null,
    pendingSimultaneousOrderChoice: null,
    pendingReactiveOffer: null,
    pendingOpponentHandChoice: null,
    pendingOpponentSubChoice: null,
    blockedCardNamesThisTurn: new Set(),
    congregateUsedThisTurn: false,
    energizeSkippedThisTurn: false,
    currentAction: null,
    activeRegionSwap: null,
    pendingIntensify: null,
    reactiveWindow: null,
    pendingDieRoll: null,
    pendingDiscardFromPlay: null,
    pendingDiscardFromPlayQueue: [],
    preCombatDieRollAnswers: {},
    pendingKlynnSeer: null,
    pendingFirstPlayerChoice: null,
    deadfallPendingCharges: null,
    flourishUntilTurn: null,
    radiantSpringUntilTurn: null,
    spiritOfCaldPendingWatch: null,
    bannedSpellNames: [],
    pendingSpellNamingSequence: null,
    pendingBoardSacrificeSequence: null,
    pendingSequentialZonePick: null,
    pendingGloomSaves: null,
    scheduledEnergizeStepDiscards: [],
    winnerId: null,
    isDraw: false,
    tutorialMode,
    tutorialEnded: null,
    log: [],
  };

  if (usePreGameChoice) {
    // NEW pre-game path (Batch D 2026-08-14): arm pendingFirstPlayerChoice and return
    // WITHOUT calling beginTurn. Caller must invoke resolveFirstPlayerChoice next.
    const playerIds = playerConfigs.map((c) => c.playerId);
    const { rolls, winnerId } = rollForTurnOrderWithHistory(playerIds, rng);
    const winnerPlayer = players.get(winnerId)!;
    const winnerFirstMagi = winnerPlayer.magiQueue[0];
    let winnerCanChooseSelf = true;
    if (winnerFirstMagi) {
      const winnerFirstMagiDef = cardDb.get(winnerFirstMagi.definitionKey);
      if (winnerFirstMagiDef) {
        const effect = getCardEffectByName(winnerFirstMagiDef.name);
        if (effect?.preventsOwnChoosingToPlayFirst?.(state, cardDb, winnerFirstMagi)) {
          winnerCanChooseSelf = false;
        }
      }
    }
    state.pendingFirstPlayerChoice = { playerIds, rolls, winnerId, winnerCanChooseSelf };
    logEvent(state, 'firstPlayerRolled', { rolls, winnerId, winnerCanChooseSelf });
    return state;
  }

  beginTurn(state, cardDb, rng);
  return state;
}

/**
 * Resolves the pending "who goes first" choice armed by `setupGame` when no explicit
 * `turnOrder` was provided. Sets the final `turnOrder` + `activePlayerId`, clears the
 * `pendingFirstPlayerChoice` state, and calls `beginTurn` to start turn 1 (which reveals
 * the first Magi and runs the standard turn-1 startup). Bucket D Batch D closure 2026-08-14.
 *
 * `chosenFirst` MUST be one of the two players. If the winner (`playerId`) chose themselves
 * but Togoth's `preventsOwnChoosingToPlayFirst` restriction is active on their magiQueue[0],
 * the choice is silently converted to opposing-first (owner Q6 2026-08-14: asymmetric --
 * the winner can't self-select when restricted; the opposing player winning the roll can
 * still freely choose Togoth-goes-first).
 *
 * Only the roll winner may answer. Calls from any other player are silently ignored (same
 * trust model as `resolveFateWhimsyChoice` / `resolveOpponentHandChoice` / other
 * pending-answer helpers). Calling before the pending state is armed, or after it's been
 * cleared, is also a silent no-op -- the UI should read `state.pendingFirstPlayerChoice`
 * before offering the picker.
 */
export function resolveFirstPlayerChoice(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  chosenFirst: PlayerId,
  rng: Rng = defaultRng
): void {
  const pending = state.pendingFirstPlayerChoice;
  if (!pending) return;
  if (playerId !== pending.winnerId) return; // only the winner picks
  if (!pending.playerIds.includes(chosenFirst)) return; // must name one of the two players

  // Togoth's restriction (owner Q6 2026-08-14, asymmetric): if the winner is restricted
  // from choosing themselves and asked for self, silently convert to opposing. This mirrors
  // the UI's gray-out but re-enforces server-side so a client that bypassed the gray-out
  // can't cheat the rule.
  let effectiveChoice = chosenFirst;
  if (!pending.winnerCanChooseSelf && chosenFirst === pending.winnerId) {
    effectiveChoice = pending.playerIds.find((id) => id !== pending.winnerId)!;
  }
  const other = pending.playerIds.find((id) => id !== effectiveChoice)!;

  const turnOrder: PlayerId[] = [effectiveChoice, other];
  // `turnOrder` is `readonly` on GameState to prevent post-setup mutation from anywhere else;
  // legitimate reassignment only ever happens here (still inside the setup boundary, before
  // beginTurn fires). Cast is narrow and intentional.
  (state as { turnOrder: readonly PlayerId[] }).turnOrder = turnOrder;
  state.activePlayerId = turnOrder[0]!;
  state.skipEnergizeForFirstTurn = turnOrder.length === 2;
  state.pendingFirstPlayerChoice = null;

  logEvent(state, 'firstPlayerChosen', {
    winnerId: pending.winnerId,
    chosenFirst: effectiveChoice,
    restrictedByTogoth: effectiveChoice !== chosenFirst,
  });

  beginTurn(state, cardDb, rng);
}

/**
 * Some cards print their OWN "Starting: <Magi name>" (or "Starting: <region>", e.g. Weave Powder's
 * "any Weave Magi") line instead of being listed in a Magi's `starting` array -- e.g. Barak's Ring
 * says "Starting: Barak" rather than Barak's own card listing "Barak's Ring". Stored on the OTHER
 * card as `starting_magi`, so it isn't visible from the Magi's definition alone; this scans the
 * player's own deck + discard pile (same zones tutorStartingCards already searches) for any card
 * carrying a `starting_magi` that matches this Magi, and returns their (deduped) names --
 * additional legal picks alongside `magiDef.starting`'s literal names. Confirmed missing entirely
 * from gameplay via live playtesting (PROGRESS_LOG.md 2026-07-10).
 *
 * A `starting_magi` value matches this Magi if it's:
 *  - one of this Magi's identity names, via magiIdentityNames (deck.ts) -- its own printed `name`
 *    (the common case), OR any name in its `alternate` field. A Magi's card is often printed under
 *    a longer title -- e.g. "Barak the Red" carries `alternate: "Barak"` -- while other cards'
 *    "Starting:" text uses the shorter alias; this is the exact case that surfaced the bug: "Barak
 *    the Red" was being playtested, and Barak's Ring never appeared as a starting-card choice
 *    because "Barak" !== "Barak the Red". `alternate` is occasionally a dual identity too (Empress
 *    Gia's `alternate` is "Nagsis, Gia" -- an alternate of BOTH), which magiIdentityNames already
 *    splits out. OR
 *  - one of this Magi's regions (Weave Powder's "Starting: Weave" applies to any Weave Magi).
 * `starting_magi` is occasionally a string ARRAY (2 real cards print more than one Magi name --
 * "Power of the Creators": Tony Jones/Agram, "Cleansing": Kazm/Ulk/Grej), so every value is
 * normalized to an array before matching.
 *
 * Doesn't cover the broader "these are the SAME identity for deck-legality/banlist purposes"
 * question beyond starting cards -- Magi-stack distinctness (can't stack two alternates of the
 * same base Magi together) is handled separately by deck.ts's validateDeck, also via
 * magiIdentityNames. A ban on a base Magi does NOT propagate to its alternates (confirmed with the
 * project owner, PROGRESS_LOG.md 2026-07-10) -- magiIdentityNames is deliberately not used for
 * legality checks, only identity groupings like these two.
 */
export function impliedStartingCardNames(
  cardDb: CardDatabase,
  magiDef: CardDefinition,
  player: PlayerState
): string[] {
  const identities = magiIdentityNames(magiDef);
  const pool = [...player.deck, ...player.discardPile];
  const names = new Set<string>();
  for (const instance of pool) {
    const def = cardDb.get(instance.definitionKey);
    if (!def?.starting_magi) continue;
    const values = Array.isArray(def.starting_magi) ? def.starting_magi : [def.starting_magi];
    const isMatch = values.some((v) => identities.includes(v) || magiDef.regions.includes(v));
    if (isMatch) names.add(def.name);
  }
  return [...names];
}

/**
 * A Magi's `starting` list names a literal card (e.g. Vorga's "Scroll of Fire"), but a player's
 * deck might carry an ALTERNATE printing of that card instead (e.g. "The Last Words," `alternate:
 * "Scroll of Fire"`) -- the same "a card and its Alternates are the same identity" convention this
 * codebase already applies to the 3-copy deck-building limit and the one-copy-in-play restriction
 * (deck.ts's `copyLimitName`/`magiIdentityNames`), just not yet extended to starting cards.
 * Confirmed with the project owner (2026-07-10) this should work the same way here: Vorga should
 * be able to start with "The Last Words" even though her own `starting` array says "Scroll of
 * Fire" literally. Scans the player's own deck + discard pile (same zones tutorStartingCards
 * already searches) for any card whose identity (via `magiIdentityNames`, which works for any
 * card, not just Magi -- it just reads `name`/`alternate`) overlaps one of this Magi's literal
 * starting-card names, and returns the found card's own name -- additional legal picks alongside
 * `magiDef.starting`'s literal names. Category-style entries (e.g. "[One Oracle]") are skipped --
 * they're not a literal card name to alias in the first place.
 */
export function alternateStartingCardNames(
  cardDb: CardDatabase,
  magiDef: CardDefinition,
  player: PlayerState
): string[] {
  return alternateStartingCardGroups(cardDb, magiDef, player).flatMap((g) => g.alternates);
}

/**
 * The same alternates as `alternateStartingCardNames`, but grouped under the literal starting-card
 * name each one aliases.
 *
 * WHY THE GROUPING MATTERS: an alternate is an ALTERNATIVE to its base, not an extra. A Magi with
 * "Starting: Nightmare Construct" whose deck also holds an Alternate printing of Nightmare
 * Construct still gets ONE card for that slot -- the player picks which printing. The flat list
 * loses that, so the UI could not tell the two apart and happily let a player tick both (playtest
 * 2026-07-25 on Shadow Empress: "currently can select all... should only allow one to be selected
 * at a time from the added cards"). It was caught at confirm time, but only as a dead end with no
 * explanation.
 *
 * Returns only groups that actually HAVE an alternate in this player's deck -- a base with no
 * alternate needs no exclusivity rule and would just be noise for the caller to filter.
 */
export function alternateStartingCardGroups(
  cardDb: CardDatabase,
  magiDef: CardDefinition,
  player: PlayerState
): { base: string; alternates: string[] }[] {
  const literalNames = (magiDef.starting ?? []).filter((entry) => !isStartingCategory(entry));
  if (literalNames.length === 0) return [];
  const pool = [...player.deck, ...player.discardPile];
  const byBase = new Map<string, Set<string>>();
  for (const instance of pool) {
    const def = cardDb.get(instance.definitionKey);
    if (!def || literalNames.includes(def.name)) continue; // the literal card itself, not an alternate
    for (const identity of magiIdentityNames(def)) {
      if (!literalNames.includes(identity)) continue;
      const set = byBase.get(identity) ?? new Set<string>();
      set.add(def.name);
      byBase.set(identity, set);
    }
  }
  return [...byBase.entries()].map(([base, alternates]) => ({ base, alternates: [...alternates] }));
}

/**
 * A Magi's "may search the deck for any/all of its listed starting cards" (§4.4) is a player
 * choice, so it's a separate explicit call rather than something setupGame or beginTurn does
 * automatically -- the caller (UI or bot) decides which of the allowed names to actually tutor,
 * including "none of them." Also used for succession (§10), which retrieves starting cards the
 * same way but from the discard pile first, then the deck.
 */
export function tutorStartingCards(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  chosenNames: readonly string[],
  rng: Rng = defaultRng
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const magi = player.activeMagi;
  if (!magi) {
    throw new Error(`${playerId} has no active Magi to tutor starting cards for`);
  }
  const def = cardDb.get(magi.definitionKey)!;
  const allowed = new Set([
    ...(def.starting ?? []),
    ...impliedStartingCardNames(cardDb, def, player),
    ...alternateStartingCardNames(cardDb, def, player),
    // A bonus entry granted for THIS reveal specifically (e.g. Shadow Empress's succession
    // clause) -- category-style entries (e.g. "[any one Shadow Geyser]") go through
    // tutorCategoryStartingCard instead, so only literal names belong in this plain-name set.
    ...magi.bonusStartingCardNames.filter((name) => !isStartingCategory(name)),
  ]);
  for (const name of chosenNames) {
    if (!allowed.has(name)) {
      throw new Error(`"${name}" is not a legal starting card for ${def.name}`);
    }
  }

  const cardNameOf = (instance: CardInstance): string => cardDb.get(instance.definitionKey)!.name;

  // Succession (§10) checks the discard pile before the deck; a first-time reveal (§4) has
  // nothing in the discard pile yet, so this is a strict superset of both cases.
  const stillNeeded = [...chosenNames];
  const foundInDiscard: CardInstance[] = [];
  for (const name of [...stillNeeded]) {
    const index = player.discardPile.findIndex((c) => cardNameOf(c) === name);
    if (index !== -1) {
      const [card] = player.discardPile.splice(index, 1);
      foundInDiscard.push(card!);
      stillNeeded.splice(stillNeeded.indexOf(name), 1);
    }
  }

  const foundInDeck = searchDeckForNames(state, playerId, stillNeeded, cardNameOf, rng);

  const found = [...foundInDiscard, ...foundInDeck];
  for (const card of found) {
    addPermanentTagRaw(card, KNOWN_HAND_CARD);
    player.hand.push(card);
  }
  logEvent(state, 'startingCardsTutored', { playerId, names: chosenNames, foundCount: found.length });
  return found;
}

/**
 * The live pool of deck/discard-pile cards satisfying a CATEGORY-style starting-card entry (e.g.
 * Risha's "[One Oracle]") -- for the UI to show what's actually pickable, same shape as a
 * deckSearch/discardPileSearch pool elsewhere in this codebase. Searches both zones, same
 * "succession checks discard pile too" reasoning as tutorStartingCards. Returns an empty array
 * (not an error) if `entry` isn't a recognized category or isn't actually one of this Magi's
 * starting entries -- callers should already know which is which via isStartingCategory.
 */
export function startingCategoryPool(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  entry: string
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const magi = player.activeMagi;
  if (!magi) return [];
  const magiDef = cardDb.get(magi.definitionKey)!;
  if (!(magiDef.starting ?? []).includes(entry) && !magi.bonusStartingCardNames.includes(entry)) return [];
  const category = parseStartingCategory(entry);
  if (!category) return [];

  const matches = (instance: CardInstance): boolean => {
    const def = cardDb.get(instance.definitionKey);
    return !!def && category.filter(cardDb, def);
  };
  return [...player.deck.filter(matches), ...player.discardPile.filter(matches)];
}

/**
 * Tutors a CATEGORY-style starting-card entry (e.g. "[Two different Universal cards]") by chosen
 * deck/discard-pile instance ids, rather than tutorStartingCards' exact-name lookup -- a category
 * entry isn't a real card name, so there's nothing for the name-based search to find (the bug this
 * function fixes, PROGRESS_LOG.md 2026-07-09). Validates the count cap and (for entries whose text
 * says "different") that no two chosen cards share a name, then moves them to hand and reshuffles
 * the deck, same as tutorStartingCards.
 */
export function tutorCategoryStartingCard(
  state: GameState,
  cardDb: CardDatabase,
  playerId: PlayerId,
  entry: string,
  chosenInstanceIds: readonly string[],
  rng: Rng = defaultRng
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const magi = player.activeMagi;
  if (!magi) {
    throw new Error(`${playerId} has no active Magi to tutor starting cards for`);
  }
  const magiDef = cardDb.get(magi.definitionKey)!;
  if (!(magiDef.starting ?? []).includes(entry) && !magi.bonusStartingCardNames.includes(entry)) {
    throw new Error(`"${entry}" is not a legal starting card entry for ${magiDef.name}`);
  }
  const category = parseStartingCategory(entry);
  if (!category) {
    throw new Error(`"${entry}" is not a category-style starting card entry`);
  }
  if (chosenInstanceIds.length > category.count) {
    throw new Error(`"${entry}" allows at most ${category.count} card(s), got ${chosenInstanceIds.length}`);
  }

  const pool = startingCategoryPool(state, cardDb, playerId, entry);
  const chosen: CardInstance[] = [];
  const chosenNames = new Set<string>();
  for (const id of chosenInstanceIds) {
    const card = pool.find((c) => c.instanceId === id);
    if (!card) {
      throw new Error(`"${id}" is not a legal choice for starting card entry "${entry}"`);
    }
    const name = cardDb.get(card.definitionKey)!.name;
    if (category.distinctNames && chosenNames.has(name)) {
      throw new Error(`"${entry}" requires different cards -- "${name}" was chosen more than once`);
    }
    chosenNames.add(name);
    chosen.push(card);
  }

  for (const card of chosen) {
    const inDiscard = player.discardPile.some((c) => c.instanceId === card.instanceId);
    if (inDiscard) {
      player.discardPile = player.discardPile.filter((c) => c.instanceId !== card.instanceId);
    } else {
      player.deck = player.deck.filter((c) => c.instanceId !== card.instanceId);
    }
    addPermanentTagRaw(card, KNOWN_HAND_CARD);
    player.hand.push(card);
  }
  shuffleDeck(player, rng); // §12: searching the deck always reshuffles afterward, unconditionally

  logEvent(state, 'startingCardsTutored', { playerId, names: [entry], foundCount: chosen.length });
  return chosen;
}

/**
 * Draws a player's hand up to 5 cards on their own first Magi reveal (rules-reference.md §4.4;
 * confirmed with the project owner 2026-07-07 that this applies per-player, not just to whoever
 * goes first). Must be called AFTER any starting-card tutoring for that reveal has been resolved
 * (or skipped) -- the draw tops up whatever's already in hand to 5 total, it doesn't add 5 on
 * top of tutored cards. Safe to call unconditionally after any reveal; a no-op once
 * player.openingHandDrawn is already true.
 */
export function drawOpeningHandIfEligible(
  state: GameState,
  player: PlayerState
): CardInstance[] {
  if (player.openingHandDrawn) return [];
  const needed = Math.max(0, 5 - player.hand.length);
  const drawn = drawCardsRaw(player, needed);
  player.openingHandDrawn = true;
  logEvent(state, 'openingHandDrawn', { playerId: player.playerId, count: drawn.length });
  return drawn;
}

/**
 * Auto-resolves the starting-card tutor window for any active Magi that has nothing real to
 * tutor (no literal entries, and no category entry whose live pool is non-empty) -- the same
 * "nothing to ask, just draw the opening hand" branch Play.tsx's `resolveMagiRevealIfNoStartingCards`
 * and driver.ts's `resolveOneMagiReveal` both special-case, generalized here as a pure function of
 * `state` (via the `STARTING_CARDS_TUTORED` tag, durationTags.ts) instead of an external ref/Set,
 * for a stateless server (server/) that has no per-session bookkeeping to carry across requests.
 *
 * Deliberately does NOT touch a Magi that has real entries to offer -- that case surfaces as a
 * `startingCardTutor` PendingObligation (queries.ts's `previewStartingCardTutorFor`) instead, which
 * a real player must answer (possibly declining all of it) before this tag gets set.
 */
export function resolveStartingCardTutorIfEmpty(state: GameState, cardDb: CardDatabase): void {
  for (const player of state.players.values()) {
    const magi = player.activeMagi;
    if (!magi || magi.tags.has(STARTING_CARDS_TUTORED)) continue;
    const def = cardDb.get(magi.definitionKey);
    const entries = [...(def?.starting ?? []), ...magi.bonusStartingCardNames];
    const hasLiteral = entries.some((e) => !isStartingCategory(e));
    const hasCategory = entries.some(
      (e) => isStartingCategory(e) && startingCategoryPool(state, cardDb, player.playerId, e).length > 0
    );
    if (hasLiteral || hasCategory) continue; // real tutor window -- getPendingObligations surfaces it
    addPermanentTagRaw(magi, STARTING_CARDS_TUTORED);
    drawOpeningHandIfEligible(state, player);
  }
}
