// Gilded Cage (Spell, cost 2) -- "Choose any one non-Naroom Creature in play. The chosen Creature
// may not use any of its Powers or Effects until the beginning of your next turn." Naroom Spell
// pass, Category C (2026-07-23). Feet of Stone's exact CANNOT_USE_POWER + EFFECTS_LOCKED_DOWN pair
// (Kybar's Teeth Spell pass precedent), minus its own CANNOT_ATTACK third tag (not part of this
// card's text) -- expiry is beginningOfNextOwnTurnNumber (Rayje's Belt's own "beginning of your
// next turn" wording), not nextOwnTurnNumber ("end of your next turn").
//
// "If an opponent's Spell, Power, or Effect discards Gilded Cage from your hand, draw cards equal
// to the number of cards in that opponent's hand." A genuinely new reactive hook was needed here --
// the existing onForcedToDiscardFromHand only reports a COUNT to the discarding player's own board,
// never WHICH card, so this card's own identity being the one discarded couldn't be detected. Built
// via the new self-scoped onOwnHandDiscardedByOpponent hook (registry.ts), mirroring the shape
// onCardDiscardedFromPlay already has for the in-play zone, wired from effects.ts's discardFromHand.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions } from '../targeting.js';
import { addDurationTag, beginningOfNextOwnTurnNumber, CANNOT_USE_POWER, EFFECTS_LOCKED_DOWN } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Gilded Cage', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => !effectiveRegions(state, cardDb, c).includes('Naroom')),
  resolveSpell: (ctx) => {
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target || effectiveRegions(ctx.state, ctx.cardDb, target).includes('Naroom')) return;
    const expiry = beginningOfNextOwnTurnNumber(ctx.state);
    addRestrictionTag(ctx.state, target, CANNOT_USE_POWER, expiry);
    addRestrictionTag(ctx.state, target, EFFECTS_LOCKED_DOWN, expiry);
  },
  onOwnHandDiscardedByOpponent: (state, cardDb, self, actor) => {
    const you = state.players.get(self.controllerId);
    const opponent = state.players.get(actor);
    if (!you || !opponent) return;
    drawCards(state, cardDb, you, opponent.hand.length);
  },
});
