// d'Jarvish -- two Effects:
//   "Strengthen: At the end of your turn, add one energy to each of your burrowed and
//   illusionary Creatures that attacked this turn."
//   "Escape: Your burrowed and illusionary Creatures that are discarded from play by opposing
//   cards that specifically discard Creatures from play are instead returned to your hand."
//
// Escape's "by OPPOSING cards" attribution retrofitted (task #32, 2026-07-16) from the old
// `state.activePlayerId === self.controllerId` heuristic to the real `causedByPlayerId` param now
// available on `onCardDiscardedFromPlay`.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { removeFromZone, addToZone } from '../zones.js';
import { isBurrowed, isIllusion } from '../durationTags.js';

registerCardEffect("d'Jarvish", {
  // Per-Effect hook narrowing (E1, 2026-08-12). Strengthen owns the end-of-turn +1 to burrowed/
  // illusion attackers; Escape owns the hand-return-on-opponent-discard reaction.
  effectHooks: {
    Strengthen: ['onOwnTurnEnd'],
    Escape: ['onCardDiscardedFromPlay'],
  },
  onOwnTurnEnd: (state, cardDb, self) => {
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    for (const creature of own) {
      if (!creature.attackedThisTurn) continue;
      if (!isBurrowed(state, cardDb, creature) && !isIllusion(creature)) continue;
      addEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discardedOwnerId !== self.controllerId) return; // must be YOUR Creature
    if (cause !== 'explicit') return; // "cards that specifically discard Creatures from play"
    if (causedByPlayerId === undefined || causedByPlayerId === self.controllerId) return; // must be an OPPONENT's card
    if (!isBurrowed(state, cardDb, discarded) && !isIllusion(discarded)) return;

    const owner = state.players.get(discardedOwnerId);
    if (!owner) return;
    const card = removeFromZone(owner, 'discardPile', discarded.instanceId);
    addToZone(owner, 'hand', card);
  },
});
