// Trulb Bracelet -- "Sweet Sorrow (0): Discard one of your Trulbs from play. Draw a number of
// cards equal to the Trulb's printed starting energy, plus one." "Trulb" is a naming family
// (matched by substring, same as Chogus/Vemment/Xyx elsewhere) -- the draw amount is computed
// from the SACRIFICED card's own printed cost, not a fixed number.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById, printedStartingEnergy } from '../targeting.js';
import { discardFromPlay, drawCards } from '../effects.js';

registerCardEffect('Trulb Bracelet', {
  powerTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => cardDb.get(c.definitionKey)?.name.includes('Trulb')),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Sweet Sorrow') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!ctx.cardDb.get(target.definitionKey)?.name.includes('Trulb')) return;
    const drawAmount = printedStartingEnergy(ctx.cardDb, target.definitionKey) + 1;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId, undefined, undefined, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, drawAmount);
  },
});
