// Husp -- "Ensnare: Discard Husp from play. Search through any player's deck and select up to three
// different cards. That player may place one of the chosen cards back into the deck. The other chosen
// cards are discarded. Shuffle the deck afterward." (Awakening errata applied: two of the three
// chosen cards are discarded, not all three.) Built task #46, 2026-07-18, the Orothe region pass --
// Category C. Extends Warlum's opponent-deck-search shape (task #29-2d): `powerTargets` picks the
// player (Magi-proxy), `deckSearch { whoseDeck: 'target' }` lets the acting player pick the cards.
// "Up to three" is `count: 'any'` sliced to 3 (same as Keru's "up to three"), since a fixed numeric
// count would force EXACTLY that many and break when the deck has fewer. "That player may place one
// back" is the deck-owner's choice, auto-resolved to KEEP their highest-cost chosen card (a rational
// default -- salvage your best; there's no interactive "which one to keep" UI for the reacting owner,
// same auto-pick convention as Bronn's Battle Staff / Vogo). The other chosen cards are discarded.

import { registerCardEffect } from './registry.js';
import type { GameState } from '../types/state.js';
import type { CardInstance } from '../types/instance.js';
import { discardFromPlay, discardFromDeck } from '../effects.js';
import { shuffleDeck } from '../zones.js';

function allMagiInPlay(state: GameState): CardInstance[] {
  const result: CardInstance[] = [];
  for (const player of state.players.values()) {
    if (player.activeMagi) result.push(player.activeMagi);
  }
  return result;
}

registerCardEffect('Husp', {
  powerTargets: (state) => allMagiInPlay(state),
  deckSearch: { count: 'any', whoseDeck: 'target' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Ensnare') return;
    if (ctx.chosenTargetId === undefined) return;
    const targetMagi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!targetMagi) return;
    const owner = ctx.state.players.get(targetMagi.controllerId);
    if (!owner) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const chosenIds = (ctx.chosenDeckSearchIds ?? []).slice(0, 3);
    const chosenCards = chosenIds
      .map((id) => owner.deck.find((c) => c.instanceId === id))
      .filter((c): c is CardInstance => c !== undefined);
    if (chosenCards.length > 0) {
      // The deck owner keeps their highest-cost chosen card; the rest are discarded.
      const keep = chosenCards.reduce((best, c) => {
        const cCost = (ctx.cardDb.get(c.definitionKey)?.cost as number) ?? 0;
        const bestCost = (ctx.cardDb.get(best.definitionKey)?.cost as number) ?? 0;
        return cCost > bestCost ? c : best;
      });
      const toDiscard = chosenCards.filter((c) => c.instanceId !== keep.instanceId).map((c) => c.instanceId);
      discardFromDeck(ctx.state, owner, toDiscard);
    }
    shuffleDeck(owner, ctx.rng);
  },
});
