// Mobis -- printed text: "Legacy: If Mobis is defeated, add three energy to your next Magi when
// he or she is revealed." Uses the new registry.ts `onNextMagiRevealed` hook (2026-07-12) --
// fires automatically whenever Mobis is the controller's most recently defeated Magi, so no
// separate onOwnMagiDefeated registration is needed. Self-guards with a permanent tag so the bonus
// only ever applies once (to whoever comes next), not to every subsequent reveal after that.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag } from '../durationTags.js';

const MOBIS_LEGACY_CONSUMED = 'mobisLegacyConsumed';

registerCardEffect('Mobis', {
  onNextMagiRevealed: (state, cardDb, self, nextMagi) => {
    if (self.tags.has(MOBIS_LEGACY_CONSUMED)) return;
    addPermanentTag(state, cardDb, self, MOBIS_LEGACY_CONSUMED);
    addEnergy(state, cardDb, nextMagi, 3, 'effect');
  },
});
