// Craw -- "Sift (1): Discard Craw from play. Search your discard pile for a d'Resh Relic and add
// it to your hand." Same discardPileSearch shape as Bog Stone/Sperri/Delia, plus discarding
// itself as part of the same resolution -- Craw is already gone from play by the time the search
// resolves, same ordering as every other "discard self, then do X" Power in this codebase.

import { registerCardEffect } from './registry.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';
import { discardFromPlay, retrieveFromDiscardPile } from '../effects.js';
import { regionForTargetFilter } from '../targeting.js';

function isDReshRelic(state: GameState, cardDb: CardDatabase, definitionKey: number): boolean {
  const def = cardDb.get(definitionKey);
  return !!def && def.card_type === 'Relic' && def.regions.includes(regionForTargetFilter(state, "d'Resh"));
}

registerCardEffect('Craw', {
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => isDReshRelic(state, cardDb, card.definitionKey),
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Sift') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    if (!card || !isDReshRelic(ctx.state, ctx.cardDb, card.definitionKey)) return;
    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'hand');
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ["d'Resh"],
});
