// Ickle -- "Spike: Whenever an opponent plays a Relic, choose one of that player's Creatures.
// Discard two energy from the chosen Creature." Broadcast onPlay reactor.
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first eligible in array order"
// simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice).

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const SPIKE_PENDING_PREFIX = 'ickleSpikePending:';

function pendingSpikeOpponentId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(SPIKE_PENDING_PREFIX)) return tag.slice(SPIKE_PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Ickle', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;
    if (creaturesControlledBy(state, cardDb, played.controllerId).length === 0) return;
    addPermanentTag(state, cardDb, self, `${SPIKE_PENDING_PREFIX}${played.controllerId}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const opponentId = pendingSpikeOpponentId(self);
    if (opponentId === undefined) return undefined;
    const pool = creaturesControlledBy(state, cardDb, opponentId);
    if (pool.length === 0) return undefined;
    return { prompt: "Ickle's Spike: choose one of that player's Creatures to discard 2 energy from", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const opponentId = pendingSpikeOpponentId(self);
    if (opponentId === undefined) return;
    removePermanentTag(self, `${SPIKE_PENDING_PREFIX}${opponentId}`);
    if (!chosenInstanceId) return;
    const target = creaturesControlledBy(state, cardDb, opponentId).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 2, 'effect', self.controllerId, rng);
  },
});
