// Icefang Battlesled -- "Zoom (2): Choose one of your Creatures. Add two energy to the chosen
// Creature. That Creature can and must attack a Magi directly this turn. Use this power only
// before the Attack step." The "must" half is built now (task #44 Part B, 2026-07-18) --
// MUST_ATTACK_THIS_TURN (durationTags.ts), enforced by combat.ts's
// getUnresolvedMustAttackObligations at Play.tsx's "Next Phase" button.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { addDurationTag, CAN_ATTACK_MAGI_DIRECTLY, MUST_ATTACK_THIS_TURN } from '../durationTags.js';

registerCardEffect('Icefang Battlesled', {
  legalPhases: ['prs1'],
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Zoom') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;

    addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
    addDurationTag(ctx.state, ctx.cardDb, target, CAN_ATTACK_MAGI_DIRECTLY, ctx.state.turnNumber);
    addDurationTag(ctx.state, ctx.cardDb, target, MUST_ATTACK_THIS_TURN, ctx.state.turnNumber);
  },
});
