// Mirago -- both printed clauses:
//   "Extra focus: Whenever you play a Creature from your hand, you may discard a Bograth or
//   d'Resh card from your hand to add two additional energy to that Creature." onPlay, self-owned
//   trigger reacting to any own Creature entering play (including Mirago itself, if it happens to
//   be Bograth or d'Resh-eligible some other way -- no exclusion in the printed text).
//   "Shifty: Mirago loses no energy from opposing Effects." No card-side logic needed --
//   effects.ts's discardEnergy itself checks printsShifty on the target and zeroes out any
//   'effect'-caused loss when the target is opposing.
//
// The "may" choice is still auto-taken whenever legal (out of scope for Phase 4c -- same tradeoff
// as magamsRing.ts/skullek.ts/freep.ts). WHICH Bograth/d'Resh card to discard is now a real
// pending choice (Phase 4c, 2026-07-11, registry.ts's pendingTargetChoice/resolveTargetChoice)
// instead of the earlier "first eligible in hand-array order" simplification. The Creature to
// receive the energy is remembered via the pending tag, since it may no longer be "the last
// played Creature" by the time the choice resolves.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromHand } from '../effects.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';

const EXTRA_FOCUS_PENDING_PREFIX = 'miragoExtraFocusPending:';

function pendingRecipientId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(EXTRA_FOCUS_PENDING_PREFIX)) return tag.slice(EXTRA_FOCUS_PENDING_PREFIX.length);
  }
  return undefined;
}

function extraFocusPool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  const owner = state.players.get(self.controllerId);
  if (!owner) return [];
  return owner.hand.filter((c) => {
    const def = cardDb.get(c.definitionKey);
    return !!def && (def.regions.includes('Bograth') || def.regions.includes("d'Resh"));
  });
}

registerCardEffect('Mirago', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Extra focus (lowercase f matches JSON)
  // owns the onPlay reactor + its pending discard-picker. Shifty is JSON-data-driven, no hooks.
  effectHooks: {
    'Extra focus': ['onPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
    Shifty: [],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (extraFocusPool(state, cardDb, self).length === 0) return;
    addPermanentTag(state, cardDb, self, `${EXTRA_FOCUS_PENDING_PREFIX}${played.instanceId}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const recipientId = pendingRecipientId(self);
    if (recipientId === undefined) return undefined;
    const pool = extraFocusPool(state, cardDb, self);
    if (pool.length === 0) return undefined;
    return { prompt: "Mirago's Extra Focus: choose a Bograth or d'Resh card in your hand to discard for +2 energy on the played Creature", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    const recipientId = pendingRecipientId(self);
    if (recipientId === undefined) return;
    removePermanentTag(self, `${EXTRA_FOCUS_PENDING_PREFIX}${recipientId}`);
    if (!chosenInstanceId) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    if (!extraFocusPool(state, cardDb, self).some((c) => c.instanceId === chosenInstanceId)) return;
    const recipient = owner.inPlay.find((c) => c.instanceId === recipientId);
    if (!recipient) return;
    discardFromHand(state, cardDb, owner, [chosenInstanceId]);
    addEnergy(state, cardDb, recipient, 2, 'effect');
  },
});
