// Gyrg -- "Digging Mastery: Each of your Underneath Creatures in play loses no more than two
// energy each time it is attacked." A damage CAP on what's dealt to the defender -- a ctx.locked
// clamp, not a real energy mutation, so this lives in onAttack (locked-value adjustments), not
// onBeforeEnergyRemoved.

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Gyrg', {
  // Ordering declaration only -- see registry.ts. This card CAPS combat loss, so it resolves
  // after every flat reduction (owner ruling 2026-07-27).
  appliesCombatLossCap: true,
  onAttack: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Underneath')) return;
    if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.min(ctx.locked.attackerEnergy, 2);
  },
});
