// Twee -- "Regrow: If Twee is discarded from play, retrieve the first non-Twee Creature card
// under Twee from your discard pile and place it in your hand." "Under Twee" reads as pile-order:
// scanning backward from Twee's own position (the most recently discarded entries first) for the
// nearest non-Twee Creature -- the discard pile array is oldest-first/most-recent-last, matching
// every other push-based zone in this codebase.

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';

registerCardEffect('Twee', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;

    const owner = state.players.get(discardedOwnerId);
    if (!owner) return;
    const tweeIndex = owner.discardPile.findIndex((c) => c.instanceId === self.instanceId);
    if (tweeIndex === -1) return;

    for (let i = tweeIndex - 1; i >= 0; i--) {
      const card = owner.discardPile[i]!;
      const def = cardDb.get(card.definitionKey);
      if (def?.card_type === 'Creature' && def.name !== 'Twee') {
        retrieveFromDiscardPile(state, owner, card.instanceId, 'hand');
        return;
      }
    }
  },
});
