// Corrupt (Spell, Core, cost 4) -- "Choose any one Magi in play. Attack Corrupt to the chosen Magi.
// If the chosen Magi is discarded from play, discard Corrupt from play. When a Creature is played
// by any Magi, discard Corrupt from play. The Creature played becomes a Core Creature instead of
// its original region, and your Magi gains control of that Creature." Task #53-5, 2026-07-21, the
// Core Spell pass's A3 gain-control cluster.
//
// spellStaysInPlay (Crystal Vision's mechanism) -- Corrupt sits in its OWN controller's `inPlay`
// (not literally nested in the chosen Magi's own zone; nothing else in this card's text needs it to
// travel with a specific host), tracking the chosen Magi by instance id via a tag.
//
// Two independent watch conditions, either one discards Corrupt:
// - "If the chosen Magi is discarded from play" -- Magi don't move through discardFromPlay/
//   onCardDiscardedFromPlay at all (that's for inPlay Creatures/Relics); a Magi's defeat is a
//   completely separate zone move (energy.ts's defeatMagi). Corrupt doesn't control and isn't
//   controlled by the chosen Magi, so neither existing Magi-defeat hook reaches it
//   (onOwnMagiDefeated only broadcasts to the DEFEATED Magi's own controller's board;
//   onOpponentMagiDefeatedByActivePlayer is scoped to "my own Magi, opponent defeated on their
//   turn") -- needed the new registry.ts onAnyMagiDefeated broadcast (task #53-5), fired
//   unconditionally to every in-play card + Magi on both sides.
// - "When a Creature is played by any Magi" -- the generic onPlay broadcast (fires for every card
//   played, any player, any type -- same shape shadowEmpress.ts's Treacherous Bargain/harror.ts's
//   Spellfire use), filtered to `card_type === 'Creature'`, no controller-match check ("any Magi").
//
// The gain-control mechanism itself is the already-proven primitive (Yog's Turn): effects.ts's
// gainControl + CardInstance.effectiveRegionOverride, permanent (no expiresAfterTurnNumber).

import { registerCardEffect } from './registry.js';
import { gainControl, discardFromPlay } from '../effects.js';
import { allMagiInPlay } from '../targeting.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const TARGET_MAGI_PREFIX = 'corruptTargetMagi:';

function trackedMagiId(self: { tags: ReadonlySet<string> }): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(TARGET_MAGI_PREFIX));
  return tag ? tag.slice(TARGET_MAGI_PREFIX.length) : undefined;
}

registerCardEffect('Corrupt', {
  spellTargets: (state) => allMagiInPlay(state),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    const target = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!target) return;
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${TARGET_MAGI_PREFIX}${ctx.chosenTargetId}`);
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  onAnyMagiDefeated: (state, cardDb, self, defeatedMagi, defeatedPlayerId, rng) => {
    const targetId = trackedMagiId(self);
    if (!targetId || defeatedMagi.instanceId !== targetId) return;
    removePermanentTag(self, `${TARGET_MAGI_PREFIX}${targetId}`);
    const owner = state.players.get(self.controllerId);
    if (owner && owner.inPlay.some((c) => c.instanceId === self.instanceId)) {
      discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    }
  },
  onPlay: (state, cardDb, played, self, rng) => {
    if (played.instanceId === self.instanceId) return;
    const targetId = trackedMagiId(self);
    if (!targetId) return; // already discarded (e.g. same-resolution ordering)
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;

    removePermanentTag(self, `${TARGET_MAGI_PREFIX}${targetId}`);
    played.effectiveRegionOverride = { region: 'Core' };
    gainControl(state, cardDb, played, self.controllerId);

    const owner = state.players.get(self.controllerId);
    if (owner && owner.inPlay.some((c) => c.instanceId === self.instanceId)) {
      discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    }
  },
});
