// Bo'Ahsa (Weave Magi) -- "Weave Tactics: Once per turn, when one of your Weave Creatures is
// attacked, you may switch it with any one of your other Weave Creatures in play." Built in the
// Weave region pass #49, Category C.
//
// A defender SUBSTITUTION ("switch it with"), so it reuses the offersDefenderRedirect mechanism
// (Gum-Gum / Sarazen Guard / Baby Hyren) -- but Bo'Ahsa is a MAGI (combat.ts's redirect scan was
// widened to the Magi this pass) and is "once per turn," which the free+unlimited earlier users
// never needed. The once-per-turn limit is enforced via the new onDefenderRedirectAccepted callback
// (fired only on a real accept): the offer is withheld once the WEAVE_TACTICS_USED duration tag is
// set for the turn.

import { registerCardEffect } from './registry.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const WEAVE_TACTICS_USED = 'boAhsaWeaveTacticsUsedThisTurn';

function otherWeaveCreatures(state: GameState, cardDb: CardDatabase, controllerId: string, excludeId: string): CardInstance[] {
  return creaturesControlledBy(state, cardDb, controllerId).filter(
    (c) => c.instanceId !== excludeId && effectiveRegions(state, cardDb, c).includes('Weave')
  );
}

registerCardEffect("Bo'Ahsa", {
  offersDefenderRedirect: (state, cardDb, self, _attacker, declaredDefender) => {
    if (hasDurationTag(self, WEAVE_TACTICS_USED)) return undefined; // "once per turn"
    if (declaredDefender.controllerId !== self.controllerId) return undefined; // "one of YOUR Weave Creatures"
    if (!effectiveRegions(state, cardDb, declaredDefender).includes('Weave')) return undefined;
    const pool = otherWeaveCreatures(state, cardDb, self.controllerId, declaredDefender.instanceId);
    return pool.length > 0 ? pool : undefined;
  },
  onDefenderRedirectAccepted: (state, cardDb, self) => {
    addDurationTag(state, cardDb, self, WEAVE_TACTICS_USED, state.turnNumber);
  },
});
