// Aubra's Timepiece -- two printed clauses:
//   "Time Slip: All cards played during the second Powers/Spells/Relics step cost two extra
//   energy to play." No "your" qualifier -- applies to BOTH players, same shape as Aubra's
//   Hourglass (prs1 surcharge); this is prs2 instead.
//   Top-level text: "After you play Aubra's Timepiece, discard all copies of Aubra's Hourglass
//   from play. Cards cannot prevent Aubra's Hourglass from being discarded." Region-audit
//   follow-up, 2026-07-24 -- mirror-image of Aubra's Hourglass's own clause; see that file's own
//   comment for why "cannot prevent" is left as ordinary `discardFromPlay`.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect("Aubra's Timepiece", {
  costModifier: (state) => (state.phase === 'prs2' ? 2 : 0),
  onPlay: (state, cardDb, played, self, rng) => {
    if (played.instanceId !== self.instanceId) return;
    for (const player of state.players.values()) {
      const copies = player.inPlay.filter((c) => cardDb.get(c.definitionKey)?.name === "Aubra's Hourglass");
      for (const copy of copies) {
        discardFromPlay(state, cardDb, player, copy.instanceId, self.controllerId, undefined, rng);
      }
    }
  },
});
