// ---------------------------------------------------------------------------------------------
// The scripted 3-turn sequence itself (Alan/p1 Turn 1, Zoe/p2 Turn 1, Alan/p1 Turn 2), transcribed
// action-by-action from the rulebook. `actor: 'p2'` steps are always executed automatically by
// the driver below (Zoe never touches the real UI); `actor: 'p1'` steps are what Phase C's guided
// prompt narrows Alan's real, human-driven UI down to -- same step data, two different consumers.
// ---------------------------------------------------------------------------------------------

import type { GameState, PlayerId } from './types/state.js';
import { getPlayer } from './types/state.js';
import type { CardDatabase } from './types/card.js';
import type { CardInstance } from './types/instance.js';
import type { Rng } from './rng.js';
import { defaultRng } from './rng.js';
import { tutorStartingCards, drawOpeningHandIfEligible } from './setup.js';
import { advancePhase } from './turn.js';
import {
  attemptPlayCard,
  attemptUsePower,
  attemptDeclareAttack,
  declineStalePendingReactiveOffer,
} from './reactiveOffers.js';

export type TutorialActor = 'p1' | 'p2';

/** Names a specific card by NAME + zone, resolved to its actual (runtime-assigned) instance id
 *  at the moment a step executes -- instance ids can't be hardcoded since they're assigned
 *  sequentially by createCardInstance, and every card in this fully-deterministic script is
 *  uniquely identifiable by name+zone+owner at the point it's referenced. */
export interface TutorialCardRef {
  owner: TutorialActor;
  zone: 'hand' | 'inPlay' | 'activeMagi';
  name: string;
}

export type TutorialStep =
  | { actor: TutorialActor; kind: 'tutorStartingCards'; chosenNames: string[]; narration: string }
  | { actor: TutorialActor; kind: 'advancePhase'; narration?: string }
  | {
      actor: TutorialActor;
      kind: 'playCard';
      card: TutorialCardRef;
      target?: TutorialCardRef;
      secondTarget?: TutorialCardRef;
      amount?: number;
      narration: string;
    }
  | {
      actor: TutorialActor;
      kind: 'usePower';
      source: TutorialCardRef;
      powerName: string;
      target?: TutorialCardRef;
      /** Rigs the die roll for a Power that rolls one (only Grega's Thermal Blast in this script)
       *  by overriding the rng passed to THIS call only -- see rollDie's `1 + Math.floor(rng() *
       *  sides)` formula in effects.ts; 0.5 lands exactly on a 4-of-6 with zero luck modifiers in
       *  play (confirmed neither deck has one). */
      rngOverride?: number;
      narration: string;
    }
  | { actor: TutorialActor; kind: 'declareAttack'; attacker: TutorialCardRef; defender: TutorialCardRef; narration: string };

/** Exported for Play.tsx's Phase C guided-UI narrowing -- it needs the exact same name+zone+owner
 *  resolution to compute the one instanceId a scripted step allows, so its own legalMoves/target-pool
 *  filtering matches runTutorialStep's own lookups exactly rather than duplicating the logic. */
export function resolveCardRef(state: GameState, cardDb: CardDatabase, ref: TutorialCardRef): CardInstance {
  const player = getPlayer(state, ref.owner as PlayerId);
  if (ref.zone === 'activeMagi') {
    if (!player.activeMagi || cardDb.get(player.activeMagi.definitionKey)!.name !== ref.name) {
      throw new Error(`Tutorial script: ${ref.owner}'s active Magi is not "${ref.name}"`);
    }
    return player.activeMagi;
  }
  const pool = ref.zone === 'hand' ? player.hand : player.inPlay;
  const found = pool.find((c) => cardDb.get(c.definitionKey)!.name === ref.name);
  if (!found) {
    throw new Error(`Tutorial script: could not find "${ref.name}" in ${ref.owner}'s ${ref.zone}`);
  }
  return found;
}

/** Executes one scripted step against a live GameState, using the exact same engine entry points
 *  (attemptPlayCard/attemptUsePower/attemptDeclareAttack/advancePhase) the real UI and driver.ts's
 *  bot use -- nothing here is a special "tutorial-only" code path into the engine itself.
 *
 *  attemptPlayCard/attemptUsePower/attemptDeclareAttack are STAGED: any one of them can pause
 *  mid-resolution with a `state.pendingReactiveOffer` (e.g. "does the opponent want to negate
 *  this?") instead of completing synchronously -- normally left for a human/bot to answer on
 *  their own timing, and otherwise swept by the next advancePhase call
 *  (declineStalePendingReactiveOffer, turn.ts). Nobody in this script ever accepts one of these
 *  offers (Zoe never negates Alan's plays and vice versa), so every step here declines any offer
 *  its own action raised IMMEDIATELY, right after issuing it -- without this, e.g. Pruitt's
 *  Refresh would appear to silently no-op (energy never actually moves) rather than complete,
 *  since nothing would resume it until whatever LATER advancePhase call happened to sweep it,
 *  well after this step's own effects were supposed to already be visible. */
export function runTutorialStep(
  state: GameState,
  cardDb: CardDatabase,
  step: TutorialStep,
  rng: Rng = defaultRng
): void {
  switch (step.kind) {
    case 'tutorStartingCards': {
      const player = getPlayer(state, step.actor);
      tutorStartingCards(state, cardDb, step.actor, step.chosenNames, rng);
      drawOpeningHandIfEligible(state, player);
      return;
    }
    case 'advancePhase':
      advancePhase(state, cardDb, rng);
      return;
    case 'playCard': {
      const card = resolveCardRef(state, cardDb, step.card);
      const target = step.target ? resolveCardRef(state, cardDb, step.target) : undefined;
      const secondTarget = step.secondTarget ? resolveCardRef(state, cardDb, step.secondTarget) : undefined;
      attemptPlayCard(
        state,
        cardDb,
        step.actor,
        card.instanceId,
        {
          ...(target ? { chosenTargetId: target.instanceId } : {}),
          ...(secondTarget ? { chosenSecondTargetId: secondTarget.instanceId } : {}),
          ...(step.amount !== undefined ? { chosenAmounts: { move: step.amount } } : {}),
        },
        rng
      );
      declineStalePendingReactiveOffer(state, cardDb, rng);
      return;
    }
    case 'usePower': {
      const source = resolveCardRef(state, cardDb, step.source);
      const target = step.target ? resolveCardRef(state, cardDb, step.target) : undefined;
      const powerRng = step.rngOverride !== undefined ? () => step.rngOverride! : rng;
      attemptUsePower(
        state,
        cardDb,
        step.actor,
        source.instanceId,
        step.powerName,
        target ? { chosenTargetId: target.instanceId } : {},
        powerRng
      );
      declineStalePendingReactiveOffer(state, cardDb, powerRng);
      return;
    }
    case 'declareAttack': {
      const attacker = resolveCardRef(state, cardDb, step.attacker);
      const defender = resolveCardRef(state, cardDb, step.defender);
      attemptDeclareAttack(
        state,
        cardDb,
        step.actor,
        { attackerInstanceId: attacker.instanceId, defenderInstanceId: defender.instanceId },
        rng
      );
      declineStalePendingReactiveOffer(state, cardDb, rng);
      return;
    }
  }
}

const c = (owner: TutorialActor, zone: TutorialCardRef['zone'], name: string): TutorialCardRef => ({
  owner,
  zone,
  name,
});

