// Hogra Stones -- "Divination: Roll one die and discard the top card of your deck: 1-2: Add four
// energy to your Magi if the discarded card is a Creature. 3-4: Add two energy to your Magi if
// the discarded card is a Spell. 5-6: Discard three energy from your Magi if the discarded card
// is a Relic." First card using effects.ts's new discardTopOfDeck primitive.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724). Note: printed order is "roll
// AND discard" -- discard happens in the roll consumer (after Whimsy window closes), keeping the
// two effects atomic per resolution unit.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy, discardTopOfDeck, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { getPlayer } from '../types/state.js';

registerCardEffect('Hogra Stones', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Divination') return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'hograStones:divination',
      { controllingPlayerId: ctx.controllingPlayer.playerId },
      ctx.rng
    );
  },
});

registerRollConsumer('hograStones:divination', (state, cardDb, _source, payload, finalRoll, rng) => {
  const { controllingPlayerId } = payload as { controllingPlayerId: string };
  const controllingPlayer = getPlayer(state, controllingPlayerId);
  const discarded = discardTopOfDeck(state, controllingPlayer);
  if (!discarded || !controllingPlayer.activeMagi) return;
  const discardedType = cardDb.get(discarded.definitionKey)?.card_type;
  if (finalRoll <= 2) {
    if (discardedType === 'Creature') addEnergy(state, cardDb, controllingPlayer.activeMagi, 4, 'power');
  } else if (finalRoll <= 4) {
    if (discardedType === 'Spell') addEnergy(state, cardDb, controllingPlayer.activeMagi, 2, 'power');
  } else {
    if (discardedType === 'Relic') discardEnergy(state, cardDb, controllingPlayer.activeMagi, 3, undefined, undefined, rng);
  }
});
