// Flashfreeze (Spell) -- "Choose a Creature. Remove one energy from the Creature for each Frozen
// card you control." Nar Spell pass, Category A (2026-07-22). "Frozen card" (not "Frozen Creature")
// -- counts both Creatures AND Relics/Spells-in-play the caster controls that are isFrozen (e.g. a
// Djarmander-frozen Relic counts). Own inPlay list filtered directly, not allCreaturesInPlay.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Flashfreeze', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    const count = ctx.controllingPlayer.inPlay.filter((c) => isFrozen(ctx.state, ctx.cardDb, c)).length;
    if (count > 0) discardEnergy(ctx.state, ctx.cardDb, target, count, 'spell', undefined, ctx.rng);
  },
});
