// Sandstorm Orshaa -- "Stinging Sands (2): Choose a Spell in play. Discard the chosen Spell and
// three energy from that Spell's Magi." First card targeting a lingering Spell in play
// (targeting.ts's new allSpellsInPlay).
//
// "As you play Sandstorm Orshaa, reduce its cost by four. Sandstorm Orshaa is not considered to be
// in play when checking to see if your Magi is defeated, and it cannot attack Magi directly." --
// post-playtest correctness pass, P1 (2026-07-12), via the shared illusionCreature.ts helper.

import { registerCardEffect } from './registry.js';
import { allSpellsInPlay, findInPlayById } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';
import { applyIllusionEntry } from './illusionCreature.js';

registerCardEffect('Sandstorm Orshaa', {
  selfCostAdjustment: () => -4,
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) applyIllusionEntry(state, cardDb, self);
  },
  powerTargets: (state, cardDb) => allSpellsInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Stinging Sands') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Spell') return;
    const owner = ctx.state.players.get(target.controllerId);
    if (!owner) return;

    discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
    if (owner.activeMagi) discardEnergy(ctx.state, ctx.cardDb, owner.activeMagi, 3, undefined, undefined, ctx.rng);
  },
});
