// Crouching Xamf -- "Skulk (1): Choose an opposing Kybar's Teeth Creature. Remove one energy from
// it and add four energy to your largest Creature." Same Skulk family as renegadeEpik.ts; first
// card to use targeting.ts's largestCreatureControlledBy.

import { registerCardEffect } from './registry.js';
import { largestCreatureControlledBy, opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Crouching Xamf', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- opposingMagi, not
  // allMagiInPlay, so the acting player's own Magi is never offered (see creepingAinjer.ts).
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)).filter(
      (c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, "Kybar's Teeth"))
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Skulk') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, "Kybar's Teeth"))) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
    const largest = largestCreatureControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (largest) addEnergy(ctx.state, ctx.cardDb, largest, 4, 'power');
  },
  specifiedTargetRegions: () => ["Kybar's Teeth"],
});
