// Furlosk -- all three printed effects are built now:
//   "Swamp Lore: Once per turn, when you play another Bograth Creature, draw a card."
//   "Forest Power: Once per turn, when you play another Naroom Creature, add two energy to your
//   Magi."
// (Furlosk is itself Bograth/Naroom dual-region, hence "ANOTHER Bograth/Naroom Creature" --
// excludes Furlosk reacting to its own play.) Each has its own once-per-turn guard since they're
// independently triggered by different regions and could both fire off the same single play if a
// card were somehow both (none currently are).
//
// "Companionship [errata]: If you do not have another Bograth or Naroom Creature in play, discard
// Furlosk from play." -- post-playtest correctness pass, P4 (2026-07-12), via registry.ts's
// standingConditionMet hook (effects.ts's sweepStandingConditions).

import { registerCardEffect } from './registry.js';
import { drawCards, addEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';

const SWAMP_LORE_USED_THIS_TURN = 'furloskSwampLoreUsedThisTurn';
const FOREST_POWER_USED_THIS_TURN = 'furloskForestPowerUsedThisTurn';

registerCardEffect('Furlosk', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Swamp Lore and Forest Power SHARE the
  // same `onPlay` body (different region-branch checks inside), so a Taglat copy of either
  // Effect grants the whole onPlay -- both sub-clauses will run under the recipient's turn if
  // conditions match. That's an over-grant relative to printed text but far tighter than the
  // whole-card fallback (which would also grant Companionship's self-destruct standingConditionMet).
  effectHooks: {
    'Swamp Lore': ['onPlay'],
    'Forest Power': ['onPlay'],
    Companionship: ['standingConditionMet'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) return;
    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Creature') return;

    if (playedDef.regions.includes('Bograth') && !hasDurationTag(self, SWAMP_LORE_USED_THIS_TURN)) {
      const player = state.players.get(self.controllerId);
      if (player) {
        drawCards(state, cardDb, player, 1);
        addDurationTag(state, cardDb, self, SWAMP_LORE_USED_THIS_TURN, state.turnNumber);
      }
    }

    if (playedDef.regions.includes('Naroom') && !hasDurationTag(self, FOREST_POWER_USED_THIS_TURN)) {
      const magi = state.players.get(self.controllerId)?.activeMagi;
      if (magi) {
        addEnergy(state, cardDb, magi, 2, 'effect');
        addDurationTag(state, cardDb, self, FOREST_POWER_USED_THIS_TURN, state.turnNumber);
      }
    }
  },
  standingConditionMet: (state, cardDb, self) => {
    const otherBograthOrNaroom = creaturesControlledBy(state, cardDb, self.controllerId).filter(
      (c) => c.instanceId !== self.instanceId && (effectiveRegions(state, cardDb, c).includes('Bograth') || effectiveRegions(state, cardDb, c).includes('Naroom'))
    );
    return otherBograthOrNaroom.length === 0;
  },
});
