// Wasperine -- "Rush: If your Magi is a Naroom or Naroom Shadow Magi, you may play Wasperine at
// the beginning of your Attack Step, paying all costs." Built task #45, 2026-07-18, the Naroom
// region pass -- direct reuse of Mountain Trulb's proven `onOwnAttackStepStart` +
// `pendingYesNoChoice` + `playFromZonePayingCost` shape (task #42), minus the extra attack-grant
// clauses Wasperine Stalker's own version of this pattern has (CAN/MUST attack Magi directly,
// Woot! energy bonus) -- Wasperine's printed text is just the play-timing override, nothing else.
// "Naroom Shadow Magi may play Wasperine" needs no code -- already covered by the database's own
// `shadow_play: "Naroom"` field + regions.ts, same as Urhail's precedent.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { playFromZonePayingCost } from '../play.js';

const RUSH_PENDING = 'wasperineRushPending';

registerCardEffect('Wasperine', {
  onOwnAttackStepStart: (state, cardDb, self) => {
    removePermanentTag(self, RUSH_PENDING);
    const magi = state.players.get(self.controllerId)?.activeMagi;
    const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
    if (!magiDef || !magiDef.regions.includes('Naroom')) return;
    addPendingChoiceTag(self, RUSH_PENDING);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(RUSH_PENDING)) return undefined;
    return {
      prompt: 'Wasperine\'s Rush: play it now, paying all costs?',
      yesLabel: 'Play Wasperine',
      noLabel: 'Not now',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, RUSH_PENDING);
    if (!chosenBoolean) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    playFromZonePayingCost(state, cardDb, player, 'hand', self.instanceId, {}, rng);
  },
});
