// Salafy -- "Protege: Once per turn, when you play a Naroom Creature, you may search your discard
// pile for a copy of that Creature and place it in your hand." Built task #45, 2026-07-18, the
// Naroom region pass -- plain onPlay broadcast + pendingYesNoChoice + retrieveFromDiscardPile
// (Twee's precedent for the retrieval half), with a turn-reset tag for the "once per turn" gate.
// CardInstance.persistentCategoryChoice (Niffer/Sarazen Outcast's field) is reused here to hold
// the triggering Creature's NAME rather than a region/Creature-type -- nothing else on Salafy
// needs the field, and it already has exactly the "remember one string between trigger and
// resolve" shape this needs. The "once per turn" gate is only consumed when a matching copy is
// actually found in the discard pile -- playing a Naroom Creature with no copy sitting in the
// discard pile has nothing to search for and doesn't burn the turn's use.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { retrieveFromDiscardPile } from '../effects.js';

const USED_THIS_TURN = 'salafyUsedThisTurn';

registerCardEffect('Salafy', {
  onOwnTurnStart: (state, cardDb, self) => {
    removePermanentTag(self, USED_THIS_TURN);
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (self.tags.has(USED_THIS_TURN)) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Creature' || !def.regions.includes('Naroom')) return;

    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const hasCopy = owner.discardPile.some((c) => c.definitionKey === played.definitionKey);
    if (!hasCopy) return;

    addPermanentTag(state, cardDb, self, USED_THIS_TURN);
    self.persistentCategoryChoice = def.name;
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (self.persistentCategoryChoice === null) return undefined;
    return {
      prompt: `Salafy's Protege: search your discard pile for a copy of ${self.persistentCategoryChoice} and add it to hand?`,
      yesLabel: 'Search discard pile',
      noLabel: 'Not now',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean) => {
    const name = self.persistentCategoryChoice;
    self.persistentCategoryChoice = null;
    if (!chosenBoolean || name === null) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const match = owner.discardPile.find((c) => cardDb.get(c.definitionKey)?.name === name);
    if (!match) return;
    retrieveFromDiscardPile(state, owner, match.instanceId, 'hand');
  },
});
