// Volcano Hyren -- "Conflagration (2): The next Cald Spell you play this turn that removes energy
// from a single Creature removes an additional energy from that Creature and one energy from each
// of that player's other Creatures in play." Task #51, 2026-07-20, the Cald Spell-reference
// cluster.
//
// Same "arm on Power use, consume on the next matching event this turn" shape as Dakat's Deja Vu
// (dakat.ts), a real port now that the Spell-side broadcast exists (task #51's
// onOwnPowerDiscardedOpposingEnergyFromCreature widening) rather than new design -- gated to
// `sourceCard`'s own card_type === 'Spell' (Volcano Hyren's text is Spell-only, unlike Scroll of
// Fire/Amanax's "Spells or Powers") and region === 'Cald', plus Ithapher's own "a SINGLE Creature"
// gate (`distinctCreaturesAffected === 1`). The "one energy from each of that player's OTHER
// Creatures in play" clause reuses creaturesControlledBy (shockRing.ts's own precedent import),
// scoped to the hit Creature's controller, excluding the hit Creature itself.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag, removeDurationTag } from '../durationTags.js';
import { creaturesControlledBy } from '../targeting.js';

const CONFLAGRATION_ARMED = 'volcanoHyrenConflagrationArmed';

registerCardEffect('Volcano Hyren', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Conflagration') return;
    addDurationTag(ctx.state, ctx.cardDb, ctx.source, CONFLAGRATION_ARMED, ctx.state.turnNumber);
  },
  onOwnPowerDiscardedOpposingEnergyFromCreature: (state, cardDb, self, sourceCard, target, _amount, distinctCreaturesAffected) => {
    if (!hasDurationTag(self, CONFLAGRATION_ARMED)) return;
    if (cardDb.get(sourceCard.definitionKey)?.card_type !== 'Spell') return;
    if (!cardDb.get(sourceCard.definitionKey)?.regions.includes('Cald')) return;
    if (distinctCreaturesAffected !== 1) return;

    removeDurationTag(self, CONFLAGRATION_ARMED);
    discardEnergy(state, cardDb, target, 1, 'power');
    for (const other of creaturesControlledBy(state, cardDb, target.controllerId)) {
      if (other.instanceId === target.instanceId) continue;
      discardEnergy(state, cardDb, other, 1, 'power');
    }
  },
});
