// Orwin's Gaze (Spell, cost 3) -- "Take any one card from your discard pile and place it on the
// top of your deck." Naroom Spell pass, Category A (2026-07-23). Exact same shape as Book of
// Life's Relearn Power (bookOfLife.ts) -- spellDiscardPileSearch (the Spell-side counterpart of a
// Power's discardPileSearch, mudBubble.ts precedent) + retrieveFromDiscardPile(..., 'deckTop'), no
// card_type filter (any card, not just Spells).

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';

registerCardEffect("Orwin's Gaze", {
  spellDiscardPileSearch: { count: 1 },
  resolveSpell: (ctx) => {
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    if (!ctx.controllingPlayer.discardPile.some((c) => c.instanceId === id)) return;
    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'deckTop');
  },
});
