// J'lith -- both printed Effects.
//
//   "Collector: Whenever any player plays a Relic, once per turn, add two energy to J'lith."
//   Broadcast onPlay reactor, once-per-turn tag (same convention as Koza's Steal).
//
//   "Coveting: If you ever have no Relics in play, discard J'lith from play." BUILT 2026-07-28
//   (ability-count sweep) -- it had no code, so J'lith kept its upside with none of its drawback.
//
// "If you EVER" is a continuous condition, and this engine has no continuous-state-check pass, so
// it is polled at the three moments the condition can actually become true: both turn starts, and
// immediately after any card leaves play (the only way a Relic count can drop mid-turn). Deliberate
// consequence: a Relic that leaves and returns WITHIN a single resolution never trips it, which
// matches "if you ever have no Relics" read at observable checkpoints rather than between every
// individual mutation. Same polling tradeoff Vault of Knowledge Key's region lock already makes.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import type { Rng } from '../rng.js';

const COLLECTOR_USED_THIS_TURN = 'jLithCollectorUsedThisTurn';

function covetingCheck(state: GameState, cardDb: CardDatabase, self: CardInstance, rng?: Rng): void {
  const owner = state.players.get(self.controllerId);
  if (!owner) return;
  if (!owner.inPlay.some((c) => c.instanceId === self.instanceId)) return; // already gone
  const hasRelic = owner.inPlay.some((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic');
  if (hasRelic) return;
  discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
}

registerCardEffect("J'lith", {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Coveting is the "no Relics -> discard
  // self" continuous check, polled at three moments; Collector is the once-per-turn Relic-play
  // reactor. No shared hooks -- either Effect narrows cleanly.
  effectHooks: {
    Coveting: ['onOwnTurnStart', 'onOpponentTurnStart', 'onCardDiscardedFromPlay'],
    Collector: ['onPlay'],
  },
  onOwnTurnStart: covetingCheck,
  onOpponentTurnStart: covetingCheck,
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, _cause, _source, _causedByPlayerId, rng) => {
    if (discarded.instanceId === self.instanceId) return; // its own discard is not a re-trigger
    covetingCheck(state, cardDb, self, rng);
  },
  onPlay: (state, cardDb, played, self) => {
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;
    if (hasDurationTag(self, COLLECTOR_USED_THIS_TURN)) return;

    addEnergy(state, cardDb, self, 2, 'effect');
    addDurationTag(state, cardDb, self, COLLECTOR_USED_THIS_TURN, state.turnNumber);
  },
});
