// Obsis -- "Sandaclysm: Discard Obsis from play. Discard all Creatures from play. Cards do not
// prevent your Creatures from being discarded by Sandaclysm." The anti-prevention clause is a
// no-op by omission -- nothing in this engine implements "prevention" effects at all yet, so
// there's nothing for it to override. Obsis's own play-legality restriction ("can only be played
// if there are no opposing Creatures in play," in its `text` field) is built via registry.ts's new
// `preventsOwnPlay` hook (task #39-1, 2026-07-17) -- previously unenforced.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Obsis', {
  preventsOwnPlay: (state, cardDb, playerId) => {
    const hasOpposingCreature = allCreaturesInPlay(state, cardDb).some((c) => c.controllerId !== playerId);
    return hasOpposingCreature ? 'Obsis can only be played if there are no opposing Creatures in play' : false;
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Sandaclysm') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const creatures = allCreaturesInPlay(ctx.state, ctx.cardDb);
    for (const creature of creatures) {
      const owner = ctx.state.players.get(creature.controllerId);
      if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, creature.instanceId, undefined, undefined, ctx.rng);
    }
  },
});
