// Sperri -- two printed clauses:
//   "Preserve (2): Return any one Furok from your discard pile to your hand." First user of
//   registry.ts's discardPileSearch.
//   "Infuse: Whenever Sperri plays a Furok, add two additional energy to the Furok." Region-audit
//   follow-up, 2026-07-24 -- the old "needs an onPlayCreature hook that doesn't exist" deferral
//   reason was already stale (Hasseth's Master Illusionist, the sibling card that framing pointed
//   at, was actually built via the plain `onPlay` broadcast + name filter, same pattern Darkwood
//   Furok's Mantle of Kings, Chayla's Companionship, and Forest Wudge's Home Turf already use in
//   this same region). Word-boundary name check (not `creatureType()`, which breaks for compound
//   names like "Furok Protector"/"Furok Guardian" -- Darkwood Furok's own file has the full story).

import { registerCardEffect } from './registry.js';
import { creatureType } from '../targeting.js';
import { addEnergy, retrieveFromDiscardPile } from '../effects.js';

registerCardEffect('Sperri', {
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => creatureType(cardDb, card.definitionKey) === 'Furok',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Preserve') return;
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    if (!card || creatureType(ctx.cardDb, card.definitionKey) !== 'Furok') return;
    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'hand');
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (played.instanceId === self.instanceId) return; // Sperri playing itself doesn't count
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Creature') return;
    if (!/\bFuroks?\b/.test(playedDef.name)) return;
    addEnergy(state, cardDb, played, 2, 'effect');
  },
});
