// Agram's Plaything -- "Puppet Strings (0): Until the end of your turn, Agram's Plaything changes
// to a Creature. Add one energy to Agram's Plaything whenever it becomes a Creature. If your Magi
// is Agram, add two additional energy to it. Whenever Agram's Plaything becomes a Relic, discard
// all energy from it." Second user of the Creature<->Relic cardTypeOverride primitive (task #35,
// 2026-07-16, built alongside Jingjack) -- unlike Jingjack, which retains whatever energy it had
// across its own transitions, this card's own text ties BOTH transition directions to an explicit
// energy change, so it registers both onBecameCreature and onBecameRelic. The "becomes a Relic"
// clause fires on the automatic end-of-turn reversion too (effects.ts's
// sweepExpiredCardTypeOverrides routes through the same setCardTypeOverride broadcast as an
// explicit change), not just an explicit one -- there's no way to become a Relic any other way for
// this card, since its printed cost is 0 and it's never toggled anywhere else.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { setCardTypeOverride } from '../effects.js';

registerCardEffect("Agram's Plaything", {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Puppet Strings') return;
    setCardTypeOverride(ctx.state, ctx.cardDb, ctx.source, {
      asType: 'Creature',
      expiresAfterTurnNumber: ctx.state.turnNumber,
    });
  },
  onBecameCreature: (state, cardDb, self) => {
    addEnergy(state, cardDb, self, 1, 'power');
    const controller = state.players.get(self.controllerId);
    const controllingMagiName = controller?.activeMagi ? cardDb.get(controller.activeMagi.definitionKey)?.name : undefined;
    if (controllingMagiName === 'Agram') {
      addEnergy(state, cardDb, self, 2, 'power');
    }
  },
  onBecameRelic: (state, cardDb, self) => {
    if ((self.currentEnergy ?? 0) > 0) {
      discardEnergy(state, cardDb, self, self.currentEnergy ?? 0, 'effect');
    }
  },
});
