// Magam and Weebo -- both printed with the identical "Vitalize: Choose any one Creature in play
// with less than its starting energy. Restore the chosen Creature to its starting energy." Same
// shared-definition pattern as fossik.ts's Fossik, Ringsmith/Underkeeper.

import { registerCardEffect } from './registry.js';
import type { CardEffectDefinition } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveStartingEnergy } from '../targeting.js';
import { restoreEnergy } from '../effects.js';

const vitalize: CardEffectDefinition = {
  powerTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter((c) => (c.currentEnergy ?? 0) < effectiveStartingEnergy(state, cardDb, c)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Vitalize') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const starting = effectiveStartingEnergy(ctx.state, ctx.cardDb, target);
    if ((target.currentEnergy ?? 0) >= starting) return;

    restoreEnergy(ctx.state, ctx.cardDb, target, starting);
  },
};

registerCardEffect('Magam', vitalize);
registerCardEffect('Weebo', vitalize);
