// Bog Wellisk -- "Dream Draft: Whenever an opponent plays a Relic, if your Magi is Bograth or
// Orothe, you may immediately play Bog Wellisk from your hand, ignoring all costs. You may play
// one Bog Wellisk in this way per turn." registry.ts's reactsToPlayFromHand (new this pass) --
// unlike onPlay, this scans HANDS, since Bog Wellisk itself is sitting in hand when the trigger
// fires, never in play. "You may" applied unconditionally (free Creature, no real downside).
//
// The once-per-turn limit is a PLAYER-wide cap ("play ONE Bog Wellisk... per turn"), not a
// per-instance one -- multiple copies in hand should still only trigger once combined. Tracked via
// a duration tag on the controller's own Magi (a stable per-player anchor), not on Bog Wellisk
// itself, since a freshly-drawn second copy wouldn't carry a per-instance tag anyway.

import { registerCardEffect } from './registry.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import { effectiveRegions } from '../targeting.js';

const DREAM_DRAFT_USED = 'bogWellisksDreamDraftUsedThisTurn';

registerCardEffect('Bog Wellisk', {
  reactsToPlayFromHand: (state, cardDb, self, played, playerId) => {
    if (playerId === self.controllerId) return false; // "an opponent"
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return false;
    const player = state.players.get(self.controllerId);
    const magi = player?.activeMagi;
    if (!magi) return false;
    const magiRegions = effectiveRegions(state, cardDb, magi);
    if (!magiRegions.includes('Bograth') && !magiRegions.includes('Orothe')) return false;
    if (hasDurationTag(magi, DREAM_DRAFT_USED)) return false;

    addDurationTag(state, cardDb, magi, DREAM_DRAFT_USED, state.turnNumber);
    return true;
  },
});
