// Taglat -- "Dream Cross: Choose any one Power or Effect on an opposing card in play. Until the
// beginning of your next turn, the chosen Power or Effect is considered to be printed on Taglat.
// Taglat cannot copy a Power or Effect that it already has. All copied Powers that reference the
// card that they are printed on now reference Taglat." Effect half BUILT S8/C3 2026-08-12 -- rides
// grantedEffects.ts's per-Effect narrowing (Q2 ruling), storing `effectName` on the grant so only
// the specific chosen Effect's hooks (per the donor card's `effectHooks` metadata) fire on Taglat.
// A donor card without `effectHooks[chosenName]` falls back to whole-card grant (see
// GrantedEffect.effectName's own doc comment for why the fallback is safe).
// The "now reference Taglat" self-reference rule needs no special handling -- see copiedPowers.ts
// and grantedEffects.ts's header comments: hooks (Power OR Effect) always read whatever instance
// they are handed, never the card the text was printed on. Composite id encoding: Powers use the
// existing `${cardId}::${powerName}` shape (unchanged from the Power-only era); Effects use the
// new `${cardId}::@effect:${effectName}` shape (see registry.ts's `copyPowerChoice` doc).
//   "Dreamwarp: As you play Taglat, increase or decrease its starting energy by up to one, until
//   the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import type { CardInstance } from '../types/instance.js';
import type { Power } from '../types/card.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { allUsablePowers } from '../power.js';
import { addCopiedPower } from '../copiedPowers.js';
import { addGrantedEffect, activeGrantedEffects } from '../grantedEffects.js';
import { beginningOfNextOwnTurnNumber } from '../durationTags.js';

const EFFECT_PREFIX = '@effect:';

registerCardEffect('Taglat', {
  copyPowerChoice: {
    pool: (state, cardDb, playerId, sourceInstanceId) => {
      const opposing = [
        ...allCreaturesInPlay(state, cardDb).filter((c) => c.controllerId !== playerId),
        ...allMagiInPlay(state).filter((m) => m.controllerId !== playerId),
      ];
      const source = findCreatureOrMagiById(state, sourceInstanceId);
      const alreadyHavePowers = new Set((source ? allUsablePowers(state, cardDb, source) : []).map((p) => p.name));
      const alreadyHaveEffects = new Set(
        source
          ? activeGrantedEffects(state, source).flatMap((g) => (g.effectName !== undefined ? [g.effectName] : []))
          : []
      );
      const result: Array<
        | { card: CardInstance; power: Power; effectName?: undefined }
        | { card: CardInstance; effectName: string; power?: undefined }
      > = [];
      for (const card of opposing) {
        const def = cardDb.get(card.definitionKey);
        if (!def) continue;
        for (const power of def.powers ?? []) {
          if (!alreadyHavePowers.has(power.name)) result.push({ card, power });
        }
        // Effects: only NAMED Effect entries qualify -- the printed rules text ("Choose any one
        // Power or Effect") refers to a card's named printed Effects, not e.g. rule-keyword flags
        // like "Invulnerability" that have no chooser-meaningful individual identity. `def.effects`
        // is the array of printed Effect entries; filter to those with a `name` field set.
        for (const eff of def.effects ?? []) {
          if (!eff.name) continue;
          if (alreadyHaveEffects.has(eff.name)) continue;
          result.push({ card, effectName: eff.name });
        }
      }
      return result;
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Cross') return;
    if (!ctx.chosenTargetId) return;
    const separator = ctx.chosenTargetId.indexOf('::');
    if (separator === -1) return;
    const cardInstanceId = ctx.chosenTargetId.slice(0, separator);
    const rest = ctx.chosenTargetId.slice(separator + 2);
    if (!cardInstanceId || !rest) return;

    const target = [...allCreaturesInPlay(ctx.state, ctx.cardDb), ...allMagiInPlay(ctx.state)].find(
      (c) => c.instanceId === cardInstanceId
    );
    if (!target || target.controllerId === ctx.controllingPlayer.playerId) return;
    const def = ctx.cardDb.get(target.definitionKey);
    if (!def) return;

    const expiry = beginningOfNextOwnTurnNumber(ctx.state);

    if (rest.startsWith(EFFECT_PREFIX)) {
      const effectName = rest.slice(EFFECT_PREFIX.length);
      if (!effectName) return;
      // Only genuine printed named Effects qualify; re-validate against the def.
      if (!(def.effects ?? []).some((e) => e.name === effectName)) return;
      const alreadyHave = activeGrantedEffects(ctx.state, ctx.source).some(
        (g) => g.fromDefinitionKey === def.key && g.effectName === effectName
      );
      if (alreadyHave) return;
      addGrantedEffect(ctx.source, def.key, { afterTurnNumber: expiry, effectName });
      return;
    }

    const powerName = rest;
    const power = def.powers.find((p) => p.name === powerName);
    if (!power) return;
    const alreadyHave = allUsablePowers(ctx.state, ctx.cardDb, ctx.source).some((p) => p.name === power.name);
    if (alreadyHave) return;

    addCopiedPower(ctx.source, power, def.key, { afterTurnNumber: expiry });
  },
  dreamwarpRange: () => 1,
});
