// Pody -- "Backhand (1): Choose any one Creature in play that attacked on its controller's last
// turn. Discard three energy from the chosen Creature." First card using
// CardInstance.attackedLastOwnTurn (types/instance.ts) -- the retroactive-tracking piece. Also
// prints "Weave: Whenever Pody attacks or is attacked, before energy is removed, you may move one
// energy between it and one of your other Weave Creatures in play." (see weave.ts)

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { applyWeave } from './weave.js';

registerCardEffect('Pody', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn. Magi never attack in this
  // engine, so attackedLastOwnTurn is never true for one -- a Crown-granted Magi option would
  // always fail the check below, harmlessly (same "correct but never actually reachable" shape as
  // Kwup's STALKED tag).
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)).filter(
      (c) => c.attackedLastOwnTurn
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Backhand') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (!target.attackedLastOwnTurn) return;

    discardEnergy(ctx.state, ctx.cardDb, target, 3, undefined, undefined, ctx.rng);
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave']),
});
