// Traveling Healer -- both printed pieces:
//   "Grudge: When you reveal Traveling Healer, if an opposing Magi is Orothe or Weave, add five
//   energy to Traveling Healer." Self-reactive onMagiRevealed.
//   "Bolster: At the end of your turn, add one energy to each of your Creatures with less than its
//   starting energy."

import { registerCardEffect } from './registry.js';
import { opposingMagi, creaturesControlledBy, effectiveStartingEnergy } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Traveling Healer', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Grudge is the on-reveal +5 vs. Orothe/Weave;
  // Bolster is the end-of-turn +1 to below-starting-energy own Creatures.
  effectHooks: {
    Grudge: ['onMagiRevealed'],
    Bolster: ['onOwnTurnEnd'],
  },
  onMagiRevealed: (state, cardDb, revealedMagi, self) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    const qualifies = opposingMagi(state, cardDb, self.controllerId).some((m) => {
      const def = cardDb.get(m.definitionKey);
      return def?.regions.includes('Orothe') || def?.regions.includes('Weave');
    });
    if (qualifies) addEnergy(state, cardDb, self, 5, 'effect');
  },
  onOwnTurnEnd: (state, cardDb, self) => {
    for (const creature of creaturesControlledBy(state, cardDb, self.controllerId)) {
      if ((creature.currentEnergy ?? 0) < effectiveStartingEnergy(state, cardDb, creature)) {
        addEnergy(state, cardDb, creature, 1, 'effect');
      }
    }
  },
});
