// Charg -- "Scattershot: Whenever Charg attacks a Creature, before energy is removed, discard one
// energy from each of the defending Magi's Creatures. Discard an additional energy from each of
// the defending Magi's Orothe Creatures." A direct discardEnergy sweep, not a ctx.locked
// adjustment -- the text targets every one of the defender's Creatures, not just the declared
// defender itself.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';

registerCardEffect('Charg', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.defendingPlayer.playerId)) {
      const amount = effectiveRegions(ctx.state, ctx.cardDb, creature).includes('Orothe') ? 2 : 1;
      discardEnergy(ctx.state, ctx.cardDb, creature, amount, 'effect', undefined, ctx.rng);
    }
  },
});
