// Spark (Spell, cost 1) -- "Choose an opposing Creature and remove three energy from it. That
// Creature's controller may choose a Creature or Magi controlled by any player and remove one
// energy from it." Cald Spell pass, Category B (2026-07-20).
//
// First pick (an opposing Creature, -3 energy) is a plain spellTargets pool, applied synchronously
// in resolveSpell. The second pick is genuinely OPTIONAL ("may") and made by a DIFFERENT player
// (whoever controls the first-picked Creature -- always the caster's own opponent in this 2-player
// engine, izmer.ts/muckRain.ts's own "whose choice it really is stays documentation-only"
// convention) over a pool spanning BOTH sides' board. Considered (and rejected) using
// gorglesGift.ts/abwynsGift.ts's spellSecondTargets for this: Play.tsx's own hasSecondTarget gate
// treats a Spell's second target as MANDATORY whenever its pool is non-empty, which is correct for
// Gorgle's/Abwyn's Gift (neither second half is a "may") but wrong for Spark's genuinely optional
// second effect -- so this instead reuses the generic post-hoc pendingTargetChoice/
// resolveTargetChoice family (izmer.ts precedent, same idiom the Bograth pass used for Muck Rain/
// Trulbble!) as a post-resolveSpell follow-up, which natively supports a real decline.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, opposingCreatures } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const SPARK_SECOND_PICK_PENDING = 'sparkSecondPickPending';

function secondPickPool(state: GameState, cardDb: CardDatabase) {
  return [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)];
}

registerCardEffect('Spark', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return; // must be opposing

    discardEnergy(ctx.state, ctx.cardDb, target, 3, 'spell', undefined, ctx.rng);
    addPendingChoiceTag(ctx.source, SPARK_SECOND_PICK_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SPARK_SECOND_PICK_PENDING)) return undefined;
    const pool = secondPickPool(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Spark: the first target's controller may choose a Creature or Magi to remove one energy from", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, SPARK_SECOND_PICK_PENDING);
    if (!chosenInstanceId) return;
    const target = secondPickPool(state, cardDb).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 1, 'spell', undefined, rng);
  },
});
