// Trulb Horde (Spell) -- "If you have at least three Bograth Creatures in play, play any one
// Bograth Creature from your hand with one energy instead of its starting energy, ignoring all
// costs." Bograth Spell pass, Category B1 (2026-07-20). The new effectiveBograthCreatureCount count
// gate + phlouk.ts/trulb.ts's identical free-play pattern (spellHandPlayChoice + playFromZone,
// which already bypasses normal cost/region/phase legality -- matching "ignoring all costs").
// Unlike Crushing Stench/Phlouk, the printed text has no "cannot attack" clause, so none is applied.

import { registerCardEffect } from './registry.js';
import { effectiveBograthCreatureCount } from '../targeting.js';
import { playFromZone } from '../effects.js';

registerCardEffect('Trulb Horde', {
  spellHandPlayChoice: {
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes('Bograth');
    },
  },
  resolveSpell: (ctx) => {
    const count = effectiveBograthCreatureCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (count < 3) return;
    if (!ctx.chosenHandPlayId) return;
    const handCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    const def = handCard ? ctx.cardDb.get(handCard.definitionKey) : undefined;
    if (!def || def.card_type !== 'Creature' || !def.regions.includes('Bograth')) return;

    playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: ctx.chosenHandPlayId },
      ctx.controllingPlayer,
      1
    , ctx.rng);
  },
});
