// Froxfire (Spell, Paradwyn, cost 5) -- "Choose any one stalked Creature in play. Discard the
// chosen Creature from play." Target pool filters allCreaturesInPlay by the generic STALKED
// duration tag; resolution is a plain discardFromPlay.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { hasDurationTag, STALKED } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

function stalkedCreaturesInPlay(state: GameState, cardDb: CardDatabase) {
  return allCreaturesInPlay(state, cardDb).filter((c) => hasDurationTag(c, STALKED));
}

registerCardEffect('Froxfire', {
  // "Ummm...NO!" (task #565): this Spell reaches effects.ts#discardFromPlay on a single
  // chosenTargetId Creature, so it is answerable. See registry.ts for the flag contract.
  spellSpecificallyDiscardsCreature: true,
  spellTargets: (state, cardDb) => stalkedCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = stalkedCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, 'spell', ctx.rng);
  },
});
