// Kioko -- two independent once-per-turn "may" choices, both substituting a Creature's STARTING
// energy for its CURRENT energy when computing this attack's damage -- a ctx.locked substitution,
// not a real energy mutation, so both live in onAttack. Each has its own once-per-turn guard since
// they trigger off different roles (own Creature defending vs. the opposing attacker) and could
// both fire in the same attack.
//   "Motivate": your Creature deals its STARTING energy instead of current while defending.
//   "Demotivate": the attacking Creature deals its STARTING energy instead of current.
//
// Real choice (task #40-3, 2026-07-17, player-choice-default retrofit, Group 3): both "may"s are
// now real yes/nos via `pendingPreCombatTargetChoice`, returning an ARRAY of two independent
// single-candidate-pool choices (Motivate's pool is the defender, Demotivate's is the attacker) --
// the first real user of that plural return shape, since both clauses can be live on the same
// instance in the same attack. Each carries its own `clauseName` so `combat.ts`'s
// `preCombatChoiceKey` keeps their answers from colliding in `ctx.scratch.preCombatTargetChoices`.
// Still read inside `onAttack` (not `onBeforeEnergyRemoved`) since `ctx.scratch` is populated
// before EITHER hook phase runs -- no need to move this off its existing, correct-for-ctx.locked
// timing. No resolution supplied for a clause falls back to that clause's old
// "auto-take whenever it would help" default (matches the printed intent -- a Creature well below
// its starting energy benefits, one already at/above doesn't, so auto-taking was never a real
// downside to begin with).

import { registerCardEffect } from './registry.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';
import { preCombatChoiceKey, type PreCombatTargetResolution } from '../combat.js';

const MOTIVATE_USED_THIS_TURN = 'kiokoMotivateUsedThisTurn';
const DEMOTIVATE_USED_THIS_TURN = 'kiokoDemotivateUsedThisTurn';

registerCardEffect('Kioko', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Motivate and Demotivate SHARE the
  // same hook bodies (`pendingPreCombatTargetChoice` returns an array with one entry per
  // clause, `onAttack` internally dispatches on the answered clauseName). No refactor here:
  // both Effects list both hooks, so a narrowed grant of either name still exposes the shared
  // machinery; the internal per-clause `USED_THIS_TURN` gates keep the un-copied clause's
  // path dormant on the recipient (it never triggers unless its own gate is also live). This
  // is metadata-only fidelity work -- splitting the bodies into per-Effect hooks is out of
  // scope for the audit.
  effectHooks: {
    Motivate: ['pendingPreCombatTargetChoice', 'onAttack'],
    Demotivate: ['pendingPreCombatTargetChoice', 'onAttack'],
  },
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker, isDefender, attacker, defender) => {
    if (!defender || defender.controllerId !== self.controllerId) return undefined;
    const choices: { clauseName: string; prompt: string; pool: (typeof defender)[] }[] = [];
    if (!hasDurationTag(self, MOTIVATE_USED_THIS_TURN)) {
      choices.push({ clauseName: 'motivate', prompt: "Kioko's Motivate: deal the defending Creature's starting energy instead of current?", pool: [defender] });
    }
    if (!hasDurationTag(self, DEMOTIVATE_USED_THIS_TURN)) {
      choices.push({ clauseName: 'demotivate', prompt: "Kioko's Demotivate: deal the attacking Creature's starting energy instead of current?", pool: [attacker] });
    }
    return choices.length > 0 ? choices : undefined;
  },
  onAttack: (ctx, self) => {
    if (!ctx.defender) return;
    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;

    if (ctx.defender.controllerId === self.controllerId && !hasDurationTag(self, MOTIVATE_USED_THIS_TURN)) {
      const resolution = resolutions?.[preCombatChoiceKey(self.instanceId, 'motivate')];
      const startEnergy = effectiveStartingEnergy(ctx.state, ctx.cardDb, ctx.defender);
      const wouldHelp = startEnergy > ctx.locked.defenderEnergy;
      const takeIt = resolution !== undefined ? !('skip' in resolution) : wouldHelp; // unchanged auto-take-if-helpful default
      if (wouldHelp && takeIt) {
        ctx.locked.defenderEnergy = startEnergy;
        addDurationTag(ctx.state, ctx.cardDb, self, MOTIVATE_USED_THIS_TURN, ctx.state.turnNumber);
      }
    }
    if (ctx.defender.controllerId === self.controllerId && !hasDurationTag(self, DEMOTIVATE_USED_THIS_TURN)) {
      const resolution = resolutions?.[preCombatChoiceKey(self.instanceId, 'demotivate')];
      const startEnergy = effectiveStartingEnergy(ctx.state, ctx.cardDb, ctx.attacker);
      const wouldHelp = startEnergy > ctx.locked.attackerEnergy;
      const takeIt = resolution !== undefined ? !('skip' in resolution) : wouldHelp; // unchanged auto-take-if-helpful default
      if (wouldHelp && takeIt) {
        ctx.locked.attackerEnergy = startEnergy;
        addDurationTag(ctx.state, ctx.cardDb, self, DEMOTIVATE_USED_THIS_TURN, ctx.state.turnNumber);
      }
    }
  },
});
