// Submerge (Spell) -- "Choose any one Orothe Creature in play. Add three energy to the chosen
// Creature." Same resolveSpell/spellTargets shape as Shooting Star (registry.ts's Spell pipeline).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

function orotheCreaturesInPlay(state: GameState, cardDb: CardDatabase) {
  return allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Orothe')));
}

registerCardEffect('Submerge', {
  spellTargets: (state, cardDb) => orotheCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    const target = orotheCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    addEnergy(ctx.state, ctx.cardDb, target, 3, 'spell');
  },
  specifiedSpellTargetRegions: () => ['Orothe'],
});
