// Rock Yajo -- three printed effects:
//   "Invulnerability: Rock Yajo loses one less energy in attacks." (self-agnostic, same pattern
//   as Darge's Invulnerability half)
//   "Weave: Whenever Rock Yajo is attacked, before energy is removed, you may move up to one
//   energy between it and one of your other Kybar's Teeth or Weave Creatures in play." (defend-
//   only -- see weave.ts)
//   "Dream Cross (Power): Discard Rock Yajo from play. Choose one of your Kybar's Teeth
//   Creatures in play and one of your Weave Creatures in play. Until the end of your next turn,
//   each chosen Creature gains all Powers and Effects printed on the other chosen Creature." --
//   BUILT 2026-08-11 (post-audit deferred-gap closure pass, Category B). First real wiring of
//   grantedEffects.ts's whole-card grant (built 2026-07-28 with THIS card named as its intended
//   use case, but never actually hooked up to a live card until now) -- paired with
//   copiedPowers.ts for the Power half, since a grant only covers registry-hook Effects, not
//   individually-addressable Powers (see grantedEffects.ts's own header comment on the
//   distinction). `powerTargetSlots` offers the two independent picks (own Kybar's Teeth
//   Creature, own Weave Creature -- both filtered to exclude Rock Yajo itself, since it's
//   discarded as part of resolving its own Power and "gaining its own Effects back" would be
//   moot). Expiry uses `durationTags.ts`'s `nextOwnTurnNumber` (not `beginningOfNextOwnTurnNumber`,
//   Taglat's own "until the BEGINNING of your next turn" shape) -- Rock Yajo's own text is one
//   full turn longer ("until the END of your next turn"), so the grant must stay active through
//   the controller's entire next turn and only expire at the start of the turn after that.

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked, discardFromPlay } from '../effects.js';
import { applyWeave } from './weave.js';
import { creaturesControlledBy, effectiveRegions, findCreatureOrMagiById } from '../targeting.js';
import { addGrantedEffect } from '../grantedEffects.js';
import { addCopiedPower } from '../copiedPowers.js';
import { nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Rock Yajo', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Weave owns weaveConfig (Q4 data field)
  // + onBeforeEnergyRemoved (applyWeave runs before the damage snapshot); Invulnerability owns
  // onAttack. Dream Cross is a Power (powerTargetSlots + resolvePower), not an Effect -- Taglat
  // surfaces it separately via the Power branch of copyPowerChoice.
  effectHooks: {
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
    Invulnerability: ['onAttack'],
  },
  weaveConfig: { eligibleRegions: ["Kybar's Teeth", 'Weave'], mode: 'defendOnly' },
  // Weave moves real energy, so it must run before the damage snapshot (corrected 2026-07-11) --
  // split from Invulnerability below, which only adjusts the already-locked damage value.
  onBeforeEnergyRemoved: (ctx, self) => {
    applyWeave(ctx, self, ["Kybar's Teeth", 'Weave'], 'defendOnly');
  },
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId === self.instanceId) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = Math.max(0, ctx.locked.defenderEnergy - 1);
    } else if (ctx.defender?.instanceId === self.instanceId) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.max(0, ctx.locked.attackerEnergy - 1);
    }
  },
  powerTargetSlots: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    if (powerName !== 'Dream Cross') return [];
    return [
      {
        label: "Choose one of your Kybar's Teeth Creatures",
        pool: (s, db, pid) =>
          creaturesControlledBy(s, db, pid).filter(
            (c) => c.instanceId !== sourceInstanceId && effectiveRegions(s, db, c).includes("Kybar's Teeth")
          ),
        min: 1,
        max: 1,
      },
      {
        label: 'Choose one of your Weave Creatures',
        pool: (s, db, pid) =>
          creaturesControlledBy(s, db, pid).filter(
            (c) => c.instanceId !== sourceInstanceId && effectiveRegions(s, db, c).includes('Weave')
          ),
        min: 1,
        max: 1,
      },
    ];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Cross') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const aId = slots[0]?.[0];
    const bId = slots[1]?.[0];
    if (!aId || !bId || aId === bId) return;

    const a = findCreatureOrMagiById(ctx.state, aId);
    const b = findCreatureOrMagiById(ctx.state, bId);
    if (!a || !b) return;
    if (a.controllerId !== ctx.controllingPlayer.playerId || b.controllerId !== ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(a.definitionKey)?.card_type !== 'Creature' || ctx.cardDb.get(b.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, a).includes("Kybar's Teeth")) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, b).includes('Weave')) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const expiry = { afterTurnNumber: nextOwnTurnNumber(ctx.state) };
    addGrantedEffect(a, b.definitionKey, expiry);
    addGrantedEffect(b, a.definitionKey, expiry);
    const aDef = ctx.cardDb.get(a.definitionKey);
    const bDef = ctx.cardDb.get(b.definitionKey);
    for (const power of bDef?.powers ?? []) addCopiedPower(a, power, b.definitionKey, expiry);
    for (const power of aDef?.powers ?? []) addCopiedPower(b, power, a.definitionKey, expiry);
  },
});
