// Kybar's Gift (Spell) -- "If you have a Creature in play, choose an opposing Magi. Return one of
// your Creatures to your hand, discarding all of that Creature's energy. Reveal your hand to all
// players. Discard energy equal to the number of Kybar's Teeth Creatures in your hand from both
// the chosen Magi and one of that Magi's Creatures." Kybar's Teeth Spell pass, Category D
// (2026-07-22).
//
// Three independent target picks -- registry.ts's spellTargets/spellSecondTargets/spellThirdTargets
// (a Spell-side third-target slot added THIS session specifically for this card, no prior Spell
// needed more than two): (1) an opposing Magi, (2) one of the caster's own Creatures to return to
// hand, (3) one of the CHOSEN Magi's controller's Creatures (the pool depends on pick #1). "Reveal
// your hand to all players" now actually reaches a UI (PvP Step 3.5 item 3, 2026-08-02 --
// effects.ts's `revealHandToAll`, see its own doc comment); this file's own bare `logEvent` call
// for the same purpose was the "logged for audit-trail parity... but not otherwise modeled"
// placeholder that motivated building the real primitive. The energy amount is computed from the
// hand's Kybar's Teeth Creature count AFTER the return-to-hand (the returned Creature, if itself
// Kybar's Teeth, counts -- the printed order is return-then-reveal, so the count is taken at
// reveal time, which is after the return -- `revealHandToAll` is called at that same point).

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, creaturesControlledBy } from '../targeting.js';
import { returnToHand, discardEnergy, revealHandToAll } from '../effects.js';

registerCardEffect("Kybar's Gift", {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- mirrors resolveSpell's own
  // kybarsTeethInHand gate (computed AFTER the return, per that hook's own comment): a static
  // check of the CURRENT hand plus the specific Creature about to be returned to it, no
  // execution. Target 1 is always the opposing Magi by construction (spellTargets only offers
  // opposing Magi), so this only needs to confirm the energy amount will be nonzero.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options) => {
    const magiId = options.chosenTargetId as string | undefined;
    if (!magiId) return false;
    const magi = allMagiInPlay(state).find((m) => m.instanceId === magiId);
    if (!magi || magi.controllerId === actingPlayerId) return false;
    const player = state.players.get(actingPlayerId);
    if (!player) return false;
    if (player.hand.some((c) => cardDb.get(c.definitionKey)?.regions.includes("Kybar's Teeth"))) return true;
    const returnedId = options.chosenSecondTargetId as string | undefined;
    const returned = returnedId ? creaturesControlledBy(state, cardDb, actingPlayerId).find((c) => c.instanceId === returnedId) : undefined;
    return !!returned && !!cardDb.get(returned.definitionKey)?.regions.includes("Kybar's Teeth");
  },
  preventsOwnPlay: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player || player.inPlay.length === 0) return 'You must have a Creature in play to play Kybar\'s Gift';
    return false;
  },
  spellTargets: (state, cardDb, playerId) => allMagiInPlay(state).filter((m) => m.controllerId !== playerId),
  spellSecondTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  spellThirdTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) => {
    const magi = allMagiInPlay(state).find((m) => m.instanceId === firstChosenId);
    if (!magi) return undefined;
    return creaturesControlledBy(state, cardDb, magi.controllerId);
  },
  resolveSpell: (ctx) => {
    const magi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenTargetId);
    if (!magi) return;
    const ownCreature = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenSecondTargetId
    );
    if (ownCreature) {
      returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ownCreature.instanceId);
    }

    revealHandToAll(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, ctx.source.instanceId);

    const kybarsTeethInHand = ctx.controllingPlayer.hand.filter((c) =>
      ctx.cardDb.get(c.definitionKey)?.regions.includes("Kybar's Teeth")
    ).length;
    if (kybarsTeethInHand === 0) return;

    discardEnergy(ctx.state, ctx.cardDb, magi, kybarsTeethInHand, 'spell', undefined, ctx.rng);

    const opposingCreature = creaturesControlledBy(ctx.state, ctx.cardDb, magi.controllerId).find(
      (c) => c.instanceId === ctx.chosenThirdTargetId
    );
    if (opposingCreature) {
      discardEnergy(ctx.state, ctx.cardDb, opposingCreature, kybarsTeethInHand, 'spell', undefined, ctx.rng);
    }
  },
});
