/** Injectable random source so tests can be deterministic instead of depending on Math.random. */
export type Rng = () => number;

export const defaultRng: Rng = Math.random;

/** Fisher-Yates, in place. */
export function shuffle<T>(items: T[], rng: Rng = defaultRng): void {
  for (let i = items.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rng() * (i + 1));
    const tmp = items[i]!;
    items[i] = items[j]!;
    items[j] = tmp;
  }
}

/** Seeded PRNG (mulberry32) -- save/replay determinism groundwork. The same seed always produces
 *  the same output sequence, unlike `defaultRng` (Math.random). A saved game only needs to store
 *  its seed once; replaying it re-derives every random value the original playthrough saw by
 *  re-running the same seeded sequence from the start, rather than re-rolling with a fresh,
 *  unrepeatable source. 32-bit state is plenty here -- this is game-flavor randomness (shuffles,
 *  die rolls), not cryptography. */
export function createSeededRng(seed: number): Rng {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A fresh, unpredictable seed for a brand-new game. The SEED itself doesn't need to be
 *  reproducible (it's picked once, at game start, same as shuffling a physical deck) -- only the
 *  Rng DERIVED from it needs to replay deterministically once chosen, which createSeededRng
 *  guarantees. Bounded to a positive 32-bit int so it round-trips cleanly through JSON. */
export function randomGameSeed(): number {
  return Math.floor(Math.random() * 0xffffffff);
}
