// Cauldron of Ice -- "Dish Out (Power): Place any card under Cauldron of Ice into your hand.
// Discard a card from your hand." "Stir In (Effect): Immediately after you play a Nar Spell, you
// may discard one energy from your Magi to place the Spell under Cauldron of Ice."
//
// Stir In maps onto registry.ts's offersAttachRedirect the same as Gia's Tome/Nyrex -- a Spell
// auto-discards straight into its owner's discard pile inside play.ts's playCard, so by the time
// the UI checks for offers it's already sitting there exactly like a combat-defeated Creature
// would be, no separate onPlay hook needed. Its own resolveAttachRedirect pays the 1-energy Magi
// cost before moving the card, since the generic default (attachedCards.ts) doesn't know about
// that cost.
//
// No explicit "if Cauldron of Ice leaves play, discard cards under it" clause is printed (unlike
// Ababila/Gia's Tome/Hubdra's Cube) -- applied as a safety default anyway (documented in
// deferred-card-mechanics.md) so a Spell under it can never become permanently un-reachable in
// any zone if Cauldron of Ice is discarded some other way before Dish Out retrieves it.

import { registerCardEffect } from './registry.js';
import { detachCard, discardAllAttached, moveDiscardedIntoAttached } from '../attachedCards.js';
import { discardFromHand } from '../effects.js';

registerCardEffect('Cauldron of Ice', {
  // Cards stored under this one are OUT of play, not markers riding on it -- see
  // registry.ts's `holdsInertContents`. Without this, every board-wide broadcast that
  // flattens `attachedCards` (to reach the marker family) also fires the abilities of
  // whatever is sitting inertly in here.
  holdsInertContents: true,
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) => {
    if (powerName !== 'Dish Out') return undefined;
    const player = state.players.get(playerId);
    const self = player?.inPlay.find((c) => c.instanceId === sourceInstanceId);
    return self?.attachedCards ?? [];
  },
  handDiscardCost: { count: 1 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dish Out') return;
    if (!ctx.chosenTargetId) return;
    const card = detachCard(ctx.source, ctx.chosenTargetId);
    if (!card) return;
    ctx.controllingPlayer.hand.push(card);
    if (ctx.chosenHandCardIds?.[0]) {
      discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [ctx.chosenHandCardIds[0]], undefined, ctx.rng);
    }
  },
  offersAttachRedirect: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discardedOwnerId !== self.controllerId) return false;
    const def = cardDb.get(discarded.definitionKey);
    if (def?.card_type !== 'Spell' || !def.regions.includes('Nar')) return false;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    return (magi?.currentEnergy ?? 0) >= 1;
  },
  resolveAttachRedirect: (state, cardDb, discarded, self) => {
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (magi) magi.currentEnergy = Math.max(0, (magi.currentEnergy ?? 0) - 1);
    moveDiscardedIntoAttached(state, discarded, self);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;
    discardAllAttached(state, cardDb, self);
  },
});
