// Black Agovo -- "Disrupt (5): Choose any one player. Discard Black Agovo from play. The chosen
// player discards three cards from his or her hand." The TARGET's own choice of which cards, but
// a MANDATORY count -- unlike Giant Vulbor's "may discard up to two to mitigate," here the
// discard isn't optional. Reuses opponentHandDiscardChoice (whose maxCount the UI enforces as a
// cap on the checkboxes), with resolvePower additionally requiring the target's controller to
// have chosen exactly min(3, hand.length) cards rather than treating a partial pick as valid.
// Disrupt's cost (5) exactly matches Black Agovo's own starting energy, so paying the cost can
// already zero it out and trigger power.ts's automatic Creature-defeat check (step 3, BEFORE this
// resolvePower even runs) -- the explicit "discard Black Agovo from play" must tolerate that,
// not assume it's still there.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardFromHand, discardFromPlay } from '../effects.js';

registerCardEffect('Black Agovo', {
  powerTargets: (state) => allMagiInPlay(state),
  opponentHandDiscardChoice: { maxCount: 3 },
  causesOpponentHandDiscard: true, // task #718 (Riptide clause 2, 2026-08-11)

  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Disrupt') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const targetOwner = ctx.state.players.get(chosenMagi.controllerId);
    if (!targetOwner) return;

    const required = Math.min(3, targetOwner.hand.length);
    const offered = ctx.chosenOpponentHandCardIds ?? [];
    const validIds = offered.filter((id) => targetOwner.hand.some((c) => c.instanceId === id));
    if (validIds.length !== required) return;

    if (ctx.controllingPlayer.inPlay.some((c) => c.instanceId === ctx.source.instanceId)) {
      discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    }
    discardFromHand(ctx.state, ctx.cardDb, targetOwner, validIds, undefined, ctx.rng);
  },
});
