// Allio -- "Douse: Whenever Allio is attacked by a Cald Creature, add four energy to Allio before
// energy is removed."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Allio', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.attacker).includes('Cald')) return;
    addEnergy(ctx.state, ctx.cardDb, self, 4, 'effect');
  },
});
