// Great Throne Mushrooms -- "Enduring Renewal: Whenever one of your Creatures is discarded from
// play, you may discard one energy from your Magi to draw a card."
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice` -- no external reference
// needed (self's own controller's Magi is re-derivable fresh at resolve time).

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { checkMagiDefeats } from '../energy.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const AWAITING_CHOICE = 'greatThroneMushroomsAwaitingChoice';

registerCardEffect('Great Throne Mushrooms', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discardedOwnerId !== self.controllerId) return;
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Creature') return;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return;
    addPendingChoiceTag(self, AWAITING_CHOICE);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) < 1) return undefined;
    return {
      prompt: "Great Throne Mushrooms' Enduring Renewal: discard one energy from your Magi to draw a card?",
      yesLabel: 'Discard 1, draw a card',
      noLabel: 'Decline',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, AWAITING_CHOICE);
    if (!chosenBoolean) return;
    const owner = state.players.get(self.controllerId);
    const magi = owner?.activeMagi;
    if (!owner || !magi || (magi.currentEnergy ?? 0) < 1) return;
    magi.currentEnergy = Math.max(0, (magi.currentEnergy ?? 0) - 1);
    checkMagiDefeats(state, cardDb, rng);
    drawCards(state, cardDb, owner, 1);
  },
});
