// Fossik, Ringsmith and Fossik, Underkeeper -- both printed with the identical "Strengthen:
// Choose any one of your Creatures in play. Discard a card from your hand to add two energy to
// the chosen Creature." (two different Magi versions of the same character/power).

import { registerCardEffect } from './registry.js';
import type { CardEffectDefinition } from './registry.js';
import { creaturesControlledBy, findInPlayById } from '../targeting.js';
import { addEnergy, discardFromHand } from '../effects.js';

const strengthen: CardEffectDefinition = {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  handDiscardCost: { count: 1 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Strengthen') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
  },
};

registerCardEffect('Fossik, Ringsmith', strengthen);
registerCardEffect('Fossik, Underkeeper', strengthen);
