// Blight (Spell, Core, cost 7) -- "Discard two energy from each non-Core, non-Bograth Creature and
// Magi in play. Add one energy to each Core and Bograth Creature and Magi in play. Bograth Magi may
// play Blight." Task #53-4, 2026-07-21, the Core Spell pass's A1 quick wins.
//
// Confirmed precedent for the region-category-sweep shape: wildfire.ts (Cald)/golthub.ts (Mire) --
// REGIONS list + `effectiveRegions` filter + a broadcast loop over both sides' `inPlay`. Blight
// extends that shape two ways: TWO clauses (discard one group, add to the other) instead of one, and
// covers Magi as well as Creatures (both wildfire.ts/golthub.ts only touch inPlay). "Non-Core,
// non-Bograth" / "Core and Bograth" are checked directly against `effectiveRegions` rather than a
// REGIONS list + negation, since Universal cards (no regions at all) need to fall on the "non-Core,
// non-Bograth" side too and an explicit membership check handles that for free.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';
import { effectiveRegions, regionForTargetFilter } from '../targeting.js';
import type { CardInstance } from '../types/instance.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

function isCoreOrBograth(state: GameState, cardDb: CardDatabase, card: CardInstance): boolean {
  const regions = effectiveRegions(state, cardDb, card);
  return regions.includes(regionForTargetFilter(state, 'Core')) || regions.includes(regionForTargetFilter(state, 'Bograth'));
}

registerCardEffect('Blight', {
  resolveSpell: (ctx) => {
    for (const p of ctx.state.players.values()) {
      const targets: CardInstance[] = p.activeMagi ? [...p.inPlay, p.activeMagi] : [...p.inPlay];
      for (const card of targets) {
        if (isCoreOrBograth(ctx.state, ctx.cardDb, card)) {
          addEnergy(ctx.state, ctx.cardDb, card, 1, 'spell');
        } else {
          discardEnergy(ctx.state, ctx.cardDb, card, 2, 'spell', undefined, ctx.rng);
        }
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ['Core', 'Bograth'],
});
