// Xala -- "As you play Xala, reduce its cost by four. Xala is not considered to be in play when
// checking to see if your Magi is defeated, and it cannot attack Magi directly." --
// post-playtest correctness pass, P1 (2026-07-12), via the shared illusionCreature.ts helper.
//
// "Piercing Scream: As an opposing Creature uses a Power, you may discard three energy from Xala
// to negate the Power. All costs for the Power must still be paid." Built task #41, 2026-07-17,
// the "react-and-negate window" architecture project, Checkpoint A -- the first real user of
// registry.ts's offersPowerNegation/resolvePowerNegation. See
// docs/plans/react-and-negate-window-plan.md for the full design.

import { registerCardEffect } from './registry.js';
import { applyIllusionEntry } from './illusionCreature.js';
import { discardEnergy } from '../effects.js';
import { effectiveCardType } from '../targeting.js';

registerCardEffect('Xala', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Only Piercing Scream is mapped;
  // the second (unnamed) Illusion clause -- selfCostAdjustment + its onPlay applyIllusionEntry
  // -- has no name to key on and falls through to whole-card grant.
  effectHooks: {
    'Piercing Scream': ['offersPowerNegation', 'resolvePowerNegation'],
  },
  selfCostAdjustment: () => -4,
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) applyIllusionEntry(state, cardDb, self);
  },
  offersPowerNegation: (state, cardDb, self, user) => {
    if (user.controllerId === self.controllerId) return false; // "an OPPOSING Creature"
    if (effectiveCardType(cardDb, user) !== 'Creature') return false; // "opposing CREATURE"
    return (self.currentEnergy ?? 0) >= 3;
  },
  resolvePowerNegation: (state, cardDb, self, _negatedSource, _negatedPowerName, _currentTargetId, rng) => {
    discardEnergy(state, cardDb, self, 3, undefined, undefined, rng);
  },
});
