// Creeping Ainjer -- "Skulk (1): Choose an opposing Bograth Creature. Remove one energy from it
// and add three energy to your Magi." Same Skulk family as renegadeEpik.ts.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Creeping Ainjer', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- the alternate pool is
  // opposingMagi, NOT allMagiInPlay, so the picker never offers the acting player's OWN Magi
  // (which resolvePower's own "opposing" check below would reject anyway). The Bograth-region
  // filter still applies to whatever the widened pool includes, matching resolvePower's own
  // ordering (type-flexibility check first, then region check).
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)).filter(
      (c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Bograth'))
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Skulk') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Bograth'))) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 1, undefined, undefined, ctx.rng);
    if (ctx.controllingPlayer.activeMagi) {
      addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, 3, 'power');
    }
  },
  specifiedTargetRegions: () => ['Bograth'],
});
