// Elios -- printed text: "If Elios is defeated, discard all but five cards from your hand."
// Real choice (retrofitted 2026-07-20, playtest bug report: "still random discards cards from
// hand when defeated (not chosen)"): WHICH cards to discard is the controller's own pick, now a
// pendingMultiTargetChoice/resolveMultiTargetChoice (registry.ts's Group 6 multi-select post-hoc
// family, same shape Ballistic Baldar's Fly Like a Rock uses) with pool = the controller's own
// hand and minCount/maxCount both the live excess-over-5 count. No answer falls back to the old
// array-order auto-pick, same convention as every other retrofitted card.
//
// "Dream Hard" (task #29-3b, 2026-07-15; rebuilt as a real choice task #40-4, 2026-07-17): "At the
// beginning of your Energize Step, if Elios is able to energize, choose a number less than his
// energize rate. Reduce Elios' energy rate by the chosen number until the start of your next turn.
// During your Draw Step, draw cards equal to the chosen number instead of your normal two."
//
// Real choice: the number must be picked BEFORE this same turn's Energize actually reads Elios'
// rate, which rules out registry.ts's beforeOwnEnergize as the collection point -- it fires
// synchronously from inside applyEnergizeToInstance, already past the only real pause window this
// engine has (turn.ts's state.energizePending, set by runStartOfTurnHooks and resolved by
// advancePhase on the player's NEXT action -- the same pause Warrada's Ring's yes/no turn-start
// choice already uses). Built via the new pendingOwnTurnStartNumericChoice/
// resolveOwnTurnStartNumericChoice pair (registry.ts, Warrada's Ring's exact shape generalized to
// a numeric range): onOwnTurnStart marks a pending choice (gated on "able to energize," i.e. rate
// > 0) instead of auto-picking; resolveOwnTurnStartNumericChoice stores the answer on
// CardInstance.counters['dreamHardChoice'] (task #50f's generic per-instance numeric bag) and adds
// a ONE-SHOT energizeModifiers.ts entry immediately (consumed automatically the next time Elios
// actually energizes -- his own turn's Energize Step, which hasn't run yet since energizePending
// is still true) so it's already active by the time Energize finally reads the rate.
// drawCountModifier reads the same counter (the chosen number REPLACES the base 2-card draw, so
// the delta returned is chosenNumber - 2).

import { registerCardEffect } from './registry.js';
import { discardFromHand } from '../effects.js';
import { addEnergizeModifier } from '../energizeModifiers.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { effectiveEnergizeRate } from '../turn.js';

const AWAITING_DREAM_HARD_CHOICE = 'eliosAwaitingDreamHardChoice';
const AWAITING_MAGI_DEFEATED_DISCARD = 'eliosAwaitingMagiDefeatedDiscard';

registerCardEffect('Elios', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Only the NAMED Effect Dream Hard
  // is listed -- it owns the turn-start numeric-choice trio plus the drawCountModifier that
  // reads the stored counter. The other printed Effect has `name: null` in the DB (the
  // "if Elios is defeated, discard all but five" hand-cull), so per the audit convention
  // it isn't listed here -- a Taglat grant can only target named Effects.
  effectHooks: {
    'Dream Hard': [
      'onOwnTurnStart',
      'pendingOwnTurnStartNumericChoice',
      'resolveOwnTurnStartNumericChoice',
      'drawCountModifier',
    ],
  },
  onOwnMagiDefeated: (state, cardDb, self) => {
    const player = state.players.get(self.controllerId);
    if (!player) return;
    if (player.hand.length - 5 > 0) addPendingChoiceTag(self, AWAITING_MAGI_DEFEATED_DISCARD);
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_MAGI_DEFEATED_DISCARD)) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player) return undefined;
    const excess = player.hand.length - 5;
    if (excess <= 0) {
      removePermanentTag(self, AWAITING_MAGI_DEFEATED_DISCARD);
      return undefined;
    }
    return {
      prompt: `Elios' defeat: choose ${excess} card${excess === 1 ? '' : 's'} to discard from your hand (keep five)`,
      pool: player.hand.map((c) => c.instanceId),
      minCount: excess,
      maxCount: excess,
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds) => {
    if (!self.tags.has(AWAITING_MAGI_DEFEATED_DISCARD)) return;
    removePermanentTag(self, AWAITING_MAGI_DEFEATED_DISCARD);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const excess = player.hand.length - 5;
    if (excess <= 0) return;
    const handIds = new Set(player.hand.map((c) => c.instanceId));
    let targetIds: string[];
    if (chosenInstanceIds) {
      const valid = [...new Set(chosenInstanceIds)].filter((id) => handIds.has(id)).slice(0, excess);
      targetIds = valid.length === excess ? valid : player.hand.slice(0, excess).map((c) => c.instanceId);
    } else {
      targetIds = player.hand.slice(0, excess).map((c) => c.instanceId);
    }
    discardFromHand(state, cardDb, player, targetIds);
  },
  onOwnTurnStart: (state, cardDb, self) => {
    delete self.counters.dreamHardChoice;
    removePermanentTag(self, AWAITING_DREAM_HARD_CHOICE);
    const rate = effectiveEnergizeRate(state, cardDb, self);
    if (rate > 0) addPermanentTag(state, cardDb, self, AWAITING_DREAM_HARD_CHOICE);
  },
  pendingOwnTurnStartNumericChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_DREAM_HARD_CHOICE)) return undefined;
    const rate = effectiveEnergizeRate(state, cardDb, self);
    if (rate <= 0) return undefined;
    return {
      prompt: "Elios' Dream Hard: choose a number less than his energize rate to reduce it by (draw that many cards instead of two)",
      min: 0,
      max: rate - 1,
    };
  },
  resolveOwnTurnStartNumericChoice: (state, cardDb, self, chosen) => {
    removePermanentTag(self, AWAITING_DREAM_HARD_CHOICE);
    const rate = effectiveEnergizeRate(state, cardDb, self);
    const clamped = Math.max(0, Math.min(chosen, rate - 1));
    self.counters.dreamHardChoice = clamped;
    if (clamped > 0) addEnergizeModifier(self, -clamped, { oneShot: true });
  },
  drawCountModifier: (state, cardDb, self) => {
    const chosen = self.counters.dreamHardChoice;
    if (chosen === undefined) return 0;
    return chosen - 2; // replaces the base 2-card draw with the chosen number
  },
});
