// Shooting Star (Spell) -- "Choose any one Arderial Creature in play. Add two energy to the chosen
// Creature." The first spell built on the resolveSpell pipeline (registry.ts). Targeted: spellTargets
// offers every Arderial Creature in play (either side, per "any one"); resolveSpell adds 2 energy to
// the chosen one with cause 'spell', so the "opposing Powers and Spells" reducers apply if the target
// is an opponent's Creature.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

function arderialCreaturesInPlay(state: GameState, cardDb: CardDatabase) {
  return allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Arderial')));
}

registerCardEffect('Shooting Star', {
  spellTargets: (state, cardDb) => arderialCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    const target = arderialCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    addEnergy(ctx.state, ctx.cardDb, target, 2, 'spell');
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ['Arderial'],
});
