// Freep -- "Refresh: At the beginning of your turn, if your Magi is Underneath, you may discard
// Freep from play to add five energy to your Magi."
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): replaces the
// earlier auto-take with a real `pendingYesNoChoice`/`resolveYesNoChoice` -- no external reference
// needed (self + self's own controller's Magi, both re-derivable fresh at resolve time).

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromPlay } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const AWAITING_CHOICE = 'freepRefreshAwaitingChoice';

function eligible(state: Parameters<typeof addEnergy>[0], cardDb: Parameters<typeof addEnergy>[1], self: { controllerId: string }): boolean {
  const magi = state.players.get(self.controllerId)?.activeMagi;
  const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
  return !!magi && !!magiDef?.regions.includes('Underneath');
}

registerCardEffect('Freep', {
  onOwnTurnStart: (state, cardDb, self) => {
    removePermanentTag(self, AWAITING_CHOICE);
    if (eligible(state, cardDb, self)) addPendingChoiceTag(self, AWAITING_CHOICE);
  },
  pendingYesNoChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    if (!eligible(state, cardDb, self)) return undefined;
    return {
      prompt: "Freep's Refresh: discard Freep from play to add five energy to your Magi?",
      yesLabel: 'Discard Freep, +5 to Magi',
      noLabel: 'Keep Freep in play',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    removePermanentTag(self, AWAITING_CHOICE);
    if (!chosenBoolean) return;
    if (!eligible(state, cardDb, self)) return;
    const player = state.players.get(self.controllerId);
    const magi = player?.activeMagi;
    if (!player || !magi) return;
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
    addEnergy(state, cardDb, magi, 5, 'effect');
  },
});
