// Jory -- "Heatwave: Once per turn, after a Cald Spell discards an opposing Creature from play,
// remove two energy from that Creature's Magi." Task #51, 2026-07-20, the Cald Spell-reference
// cluster.
//
// Reuses the existing onCardDiscardedFromPlay broadcast (already Spell-aware since task #32,
// 2026-07-16 -- `source`/`causedByPlayerId` both thread 'spell' through discardFromPlay/
// checkCreatureDefeats correctly) -- no new broadcast needed at all, unlike Scroll of
// Fire/Ithapher/Giant Arboll's family (which needed the task #51 energy-DIFF snapshot; this hook
// fires off the discard itself, not an energy diff). Region ("Cald") is read off
// state.currentAction.sourceDefinitionKey -- the causing Spell's own definitionKey, still set at
// this point since this hook fires from deep inside that Spell's own resolveSpell call (via
// discardEnergy -> checkCreatureDefeats, or an explicit discardFromPlay) -- same idiom
// blocksPowerEffectBySourceRegion (task #35, 2026-07-16) already established for "what region was
// the acting card" checks.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const HEATWAVE_USED_THIS_TURN = 'joryHeatwaveUsedThisTurn';

registerCardEffect('Jory', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, _cause, source, causedByPlayerId) => {
    if (source !== 'spell') return;
    if (causedByPlayerId !== self.controllerId) return; // must be Jory's OWN controller's Spell
    if (discardedOwnerId === self.controllerId) return; // "opposing Creature"
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Creature') return;
    if (hasDurationTag(self, HEATWAVE_USED_THIS_TURN)) return;
    const spellDef = state.currentAction?.sourceDefinitionKey !== undefined ? cardDb.get(state.currentAction.sourceDefinitionKey) : undefined;
    if (!spellDef?.regions.includes('Cald')) return;

    const owner = state.players.get(discardedOwnerId);
    if (!owner?.activeMagi) return;

    addDurationTag(state, cardDb, self, HEATWAVE_USED_THIS_TURN, state.turnNumber);
    discardEnergy(state, cardDb, owner.activeMagi, 2, 'effect');
  },
});
