// Ember Vard -- "Scorch: When any player plays a Spell, you may discard Ember Vard from play. If
// you do, choose one of that player's Creatures. Discard five energy from the chosen Creature."
// Trigger detected via the existing onPlay broadcast (card_type === 'Spell') even though the
// Spell's own effect never executes in this engine -- same insight as Jasker's Mask's Spell-tax
// clause.
//
// Real choice (task #40-4, 2026-07-17, player-choice-default retrofit, Group 4): the "may" and the
// target pick are bundled into ONE decision ("if you do, choose...") rather than two separate
// questions, so this uses Group 1's `pendingTargetChoice`/`resolveTargetChoice` (habob.ts's
// template) instead of the new yes/no family -- declining is just `undefined`, no separate yes/no
// needed. Pool is widened to include the SPELL PLAYER's own case too (previously only offered when
// an opponent played the Spell, auto-declining the self-harm case entirely) -- a real choice means
// the player can decide for themselves whether discarding their own Creature is ever worth it
// (e.g. to trigger something else), not have that decision made for them.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, discardEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const PENDING_PREFIX = 'emberVardScorchPending:';

function pendingSpellPlayerId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) return tag.slice(PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Ember Vard', {
  onPlay: (state, cardDb, played, self) => {
    if (cardDb.get(played.definitionKey)?.card_type !== 'Spell') return;
    if (creaturesControlledBy(state, cardDb, played.controllerId).length === 0) return;
    addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${played.controllerId}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const spellPlayerId = pendingSpellPlayerId(self);
    if (spellPlayerId === undefined) return undefined;
    const pool = creaturesControlledBy(state, cardDb, spellPlayerId);
    if (pool.length === 0) return undefined;
    return { prompt: "Ember Vard's Scorch: discard Ember Vard to discard five energy from a chosen Creature of the Spell's player?", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const spellPlayerId = pendingSpellPlayerId(self);
    if (spellPlayerId !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${spellPlayerId}`);
    if (!chosenInstanceId || spellPlayerId === undefined) return;
    const target = creaturesControlledBy(state, cardDb, spellPlayerId).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    const owner = state.players.get(self.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    discardEnergy(state, cardDb, target, 5, 'effect', undefined, rng);
  },
});
