// Drahkar -- "Dominate": "When Drahkar is discarded from play, choose one opposing Creature with
// three energy or less. Discard the chosen Creature."
//
// "As you play Drahkar, reduce its cost by five. Drahkar is not considered to be in play when
// checking to see if your Magi is defeated, and it cannot attack Magi directly." -- post-playtest
// correctness pass, P1 (2026-07-12), via the shared illusionCreature.ts helper.
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first eligible in array order"
// simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice). Fires exactly when self is discarded, so self is already in the discard
// pile by the time the choice needs resolving -- findPendingTargetChoices scans both discard
// piles for exactly this kind of trigger.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { opposingCreatures } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { applyIllusionEntry } from './illusionCreature.js';

const DOMINATE_PENDING = 'drahkarDominatePending';

registerCardEffect('Drahkar', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Only Dominate is mapped; the
  // second (unnamed) Illusion clause -- selfCostAdjustment and its onPlay applyIllusionEntry
  // -- has no name to key on and falls through to whole-card grant.
  effectHooks: {
    Dominate: ['onCardDiscardedFromPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  selfCostAdjustment: () => -5,
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) applyIllusionEntry(state, cardDb, self);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;
    if (opposingCreatures(state, cardDb, self.controllerId).filter((c) => (c.currentEnergy ?? 0) <= 3).length === 0) return;
    addPendingChoiceTag(self, DOMINATE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(DOMINATE_PENDING)) return undefined;
    const pool = opposingCreatures(state, cardDb, self.controllerId).filter((c) => (c.currentEnergy ?? 0) <= 3);
    if (pool.length === 0) return undefined;
    return { prompt: "Drahkar's Dominate: choose an opposing Creature with 3 energy or less to discard from play", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, DOMINATE_PENDING);
    if (!chosenInstanceId) return;
    const target = opposingCreatures(state, cardDb, self.controllerId)
      .filter((c) => (c.currentEnergy ?? 0) <= 3)
      .find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    const owner = state.players.get(target.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, target.instanceId, undefined, undefined, rng);
  },
});
