// Drush -- "Vengeance: If Drush is attacked and defeated, choose any one of the attacking
// player's Creatures in play. Discard the chosen Creature from play."
//
// Real choice (Phase 4c, 2026-07-11): replaces the earlier "first eligible in array order"
// simplification with a real pending choice (registry.ts's pendingTargetChoice/
// resolveTargetChoice). Drush is defeated by the time this needs resolving, so self is already in
// the discard pile -- findPendingTargetChoices scans both discard piles for exactly this reason.

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';

const VENGEANCE_PENDING = 'drushVengeancePending';

registerCardEffect('Drush', {
  afterCombat: (ctx, outcome, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    if (outcome.defenderSurvived) return;
    if (creaturesControlledBy(ctx.state, ctx.cardDb, ctx.attackingPlayer.playerId).length === 0) return;
    addPendingChoiceTag(self, VENGEANCE_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(VENGEANCE_PENDING)) return undefined;
    const opponent = [...state.players.values()].find((p) => p.playerId !== self.controllerId);
    const pool = opponent ? creaturesControlledBy(state, cardDb, opponent.playerId) : [];
    if (pool.length === 0) return undefined;
    return { prompt: "Drush's Vengeance: choose one of the attacking player's Creatures to discard from play", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, VENGEANCE_PENDING);
    if (!chosenInstanceId) return;
    const opponent = [...state.players.values()].find((p) => p.playerId !== self.controllerId);
    const target = opponent && creaturesControlledBy(state, cardDb, opponent.playerId).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    const owner = state.players.get(target.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, target.instanceId, undefined, undefined, rng);
  },
});
