// Cyclone Vashp -- "Cyclone (1): Choose one of your Creatures and one of your opponent's
// Creatures in play. Discard as much energy from your opponent's Creature as is on your Creature.
// Discard your Creature from play." The amount is read from the own Creature's CURRENT energy
// BEFORE it's discarded, per the text's own order.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Cyclone Vashp', {
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: 'Choose one of your Creatures',
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid),
      min: 1,
      max: 1,
    },
    {
      // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- this slot feeds
      // discardEnergy, the OWN slot above doesn't (see resolvePower's own comment below).
      label: "Choose one of your opponent's Creatures",
      pool: (s, db, pid) => flexibleTargetPool(s, db, pid, opposingCreatures(s, db, pid), opposingMagi(s, db, pid)),
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Cyclone') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const ownId = slots[0]?.[0];
    const oppId = slots[1]?.[0];
    if (!ownId || !oppId) return;

    const ownTarget = findCreatureOrMagiById(ctx.state, ownId);
    if (!ownTarget || ctx.cardDb.get(ownTarget.definitionKey)?.card_type !== 'Creature') return;
    if (ownTarget.controllerId !== ctx.controllingPlayer.playerId) return;
    const oppTarget = findCreatureOrMagiById(ctx.state, oppId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow this (energy-discard) target to
    // be a Magi instead -- the OWN target above only feeds discardFromPlay, not discardEnergy, so
    // it's unaffected and stays Creature-only.
    if (!oppTarget || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, oppTarget, 'Creature')) return;
    if (oppTarget.controllerId === ctx.controllingPlayer.playerId) return;

    const amount = ownTarget.currentEnergy ?? 0;
    discardEnergy(ctx.state, ctx.cardDb, oppTarget, amount, undefined, undefined, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ownTarget.instanceId, undefined, undefined, ctx.rng);
  },
});
