// Crushing Winds (Spell) -- "Choose any one Creature in play. Discard four energy from the chosen
// Creature. If this discards the chosen Creature from play, draw two cards. Only Arderial Magi and
// Arderial Shadow Magi can play Crushing Winds." The last sentence needs no code -- already covered
// generically by the card's own `regions` field + normal region-legality checks (same "no code
// needed" precedent as Urhail's access text, see docs/deferred-card-mechanics.md).

import { registerCardEffect } from './registry.js';
import { discardEnergy, drawCards } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';

registerCardEffect('Crushing Winds', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    const targetId = target.instanceId;
    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);
    const stillThere = findInPlayById(ctx.state, targetId);
    if (!stillThere) drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 2);
  },
});
