// Kybar's Hammer -- "Whump: Discard a card from your hand. Roll one die. Choose any one Creature
// in play with less energy than the die roll. Discard the chosen Creature from play." Same "offer
// broad, resolve validates" pattern as Raega -- the pool can't be pre-filtered by a roll that
// hasn't happened yet at UI-offer time.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724). Note: printed order is
// "discard hand card, roll, choose Creature." Hand discard happens BEFORE the roll (so the cost
// is paid regardless of Whimsy). The Creature discard happens in the roll consumer.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromHand, discardFromPlay, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';

registerCardEffect("Kybar's Hammer", {
  handDiscardCost: { count: 1 },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Whump') return;
    const id = (ctx.chosenHandCardIds ?? [])[0];
    if (!id) return;
    if (ctx.chosenTargetId === undefined) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [id], undefined, ctx.rng);
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'kybarsHammer:whump',
      { chosenTargetId: ctx.chosenTargetId },
      ctx.rng
    );
  },
});

registerRollConsumer('kybarsHammer:whump', (state, cardDb, _source, payload, finalRoll, rng) => {
  const { chosenTargetId } = payload as { chosenTargetId: string };
  const target = findInPlayById(state, chosenTargetId);
  if (!target || cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
  if ((target.currentEnergy ?? 0) >= finalRoll) return;
  const owner = state.players.get(target.controllerId);
  if (owner) discardFromPlay(state, cardDb, owner, target.instanceId, undefined, undefined, rng);
});
