// Turn lifecycle: beginning a turn (including Magi reveal/succession), the six strictly-
// sequential phases, and ending a turn (rules-reference.md §5, §10).

import { PHASE_ORDER } from './types/state.js';
import type { GameState, PlayerState, PlayerId } from './types/state.js';
import { getActivePlayer, getPlayer, getOpponents } from './types/state.js';
import type { CardDatabase, CardDefinition } from './types/card.js';
import { drawCardsRaw, shuffleDiscardIntoDeck, removeFromZone, moveToDiscardPile } from './zones.js';
import { logEvent } from './log.js';
import { checkForDefeats, declineDefeatInterrupt, defeatMagi } from './energy.js';
import { closeSpiritSpellWindow } from './spiritSpells.js';
import { type Rng, defaultRng } from './rng.js';
import { sweepStalePendingChoiceTags, sweepStalePendingRevealChoiceTags, sweepExpiredDurationTags, sweepExpiredStartingEnergyOverrides, sweepExpiredEffectiveRegionOverrides, sweepExpiredTemporaryRegionGrants, sweepExpiredCostReductionGrants, sweepExpiredRegionPowerCostReductions, sweepExpiredMagiIdentityOverrides, sweepExpiredIdentityOverrides, DISCARD_AT_END_OF_TURN, RETURN_TO_HAND_AT_END_OF_TURN, RESTORE_MAGI_AT_END_OF_TURN, MUST_ATTACK_THIS_TURN_OR_DISCARD, addPermanentTagRaw, removePermanentTag, NO_STARTING_CARDS, ARTIMILLIES_REMEMBERANCE, LADY_OF_THE_SKY_ENERGIZE_BONUS, TOSS_AND_TURN, PERPETUAL_MOTION } from './durationTags.js';
import { activeEnergizeModifiers, consumeOneShotEnergizeModifiers } from './energizeModifiers.js';
import { getCardEffectByName, activeAttachedCards } from './cardEffects/registry.js';
import { isCardEffectLockedDown } from './lockdown.js';
import { effectsFor } from './grantedEffects.js';

import type { CardInstance } from './types/instance.js';
import { addEnergy, discardEnergy, restoreEnergy, returnToHand, sweepExpiredControlThefts, sweepExpiredCardTypeOverrides, drawCards, discardFromPlay, broadcastMagiEnergyGainOutsideEnergize, resetPerTurnStateOnEnterPlay } from './effects.js';
import { playedCardNameThisTurn, findCreatureOrMagiById, printedStartingEnergy } from './targeting.js';
import { releaseAttachedOnLeavePlay } from './attachedCards.js';
import { declineReactiveDreamwarp } from './pendingChoices.js';
import { finalizePendingDieRoll } from './play.js';
import { declineStalePendingReactiveOffer, declineStalePendingOpponentHandChoice, declineStalePendingOpponentSubChoice } from './reactiveOffers.js';
import { beginOrderedBroadcast, declineStalePendingSimultaneousOrderChoice } from './simultaneousOrder.js';

const DRAW_COUNT = 2;

/**
 * Starts a turn for state.activePlayerId: resets per-turn instance flags, reveals that
 * player's next Magi if they don't currently have one active (this single mechanism covers
 * both "a player's very first Magi reveal" and "succession after a mid-game defeat" --
 * rules-reference.md §10 says the replacement "stays face-down... until the start of that
 * player's next turn," which is exactly when this next runs for them), then runs the Energize
 * phase. Called by setupGame for turn 1 and by endTurn for every subsequent turn.
 */
export function beginTurn(state: GameState, cardDb: CardDatabase, rng: Rng = defaultRng): void {
  runStartOfTurnHooks(state, cardDb, rng);
  // Thin, fully-synchronous wrapper (P2, 2026-07-12) -- used only by setup.ts's turn-1 call, which
  // needs the old "one call fully starts the turn" contract (no `advancePhase` in the loop yet to
  // resolve a pause). `advancePhase`'s own turn-transition path calls `runStartOfTurnHooks`
  // directly and leaves `energizePending` set, giving the player a moment to see any pending
  // onOwnTurnStart choice before Energize runs.
  resolveEnergizePending(state, cardDb, rng);
}

/**
 * Turn-start half of beginTurn, split out for P2 (2026-07-12): resets per-turn instance flags,
 * reveals the active player's next Magi if needed, fires onOwnTurnStart/onOpponentTurnStart, then
 * sets `state.energizePending` instead of running Energize itself -- see GameState.energizePending's
 * doc comment for why.
 */
function runStartOfTurnHooks(state: GameState, cardDb: CardDatabase, rng: Rng = defaultRng): void {
  state.turnNumber += 1;
  const player = getActivePlayer(state);

  // Duration tags (e.g. "stalked") expire based on an absolute turn number set when they were
  // applied -- sweep BEFORE the per-turn flag reset below so a tag that just expired can't linger
  // into the new turn even by one action.
  sweepExpiredDurationTags(state);
  // CardInstance.startingEnergyOverride's own sweep (task #30, 2026-07-15: Slime Stone) --
  // same value/carrying counterpart to the plain string-tag sweep just above.
  sweepExpiredStartingEnergyOverrides(state);
  // CardInstance.effectiveRegionOverride's own sweep (task #31, 2026-07-16: Braggle's Morph) --
  // same shape, permanent (Yog/Ruid) entries are left untouched.
  sweepExpiredEffectiveRegionOverrides(state);
  // CardInstance.temporaryRegionGrant's own sweep (task #35, 2026-07-16: Jalex's Designer Intent)
  // -- same shape as sweepExpiredStartingEnergyOverrides, always-required expiry (never permanent).
  sweepExpiredTemporaryRegionGrants(state);
  // CardInstance.costReductionGrant's own sweep (task #39-3d, 2026-07-17: Nashiq's Salvage/Lens of
  // Truth's Future Sight) -- same shape as the grant sweep just above.
  sweepExpiredCostReductionGrants(state);
  // CardInstance.regionPowerCostReduction's own sweep (task #53-4, 2026-07-21: Shadow Ritual) --
  // same shape, held only on activeMagi.
  sweepExpiredRegionPowerCostReductions(state);
  // CardInstance.magiIdentityOverride's own sweep (task #53-6, 2026-07-21: Hrada's Tainted Touch)
  // -- same shape, held only on activeMagi, permanent grants untouched.
  sweepExpiredMagiIdentityOverrides(state);
  // CardInstance.identityOverride's own sweep (Swirling Orshaa's Morph, Spell-pass audit
  // follow-up, 2026-07-24) -- same shape, always-required expiry (never permanent).
  sweepExpiredIdentityOverrides(state);
  // CardInstance.temporaryControlTheft's own sweep (task #35, 2026-07-16: Morag's Theft) -- unlike
  // the field-only sweeps above, this one moves cards between zones, so it lives in effects.ts
  // alongside gainControl/returnToOwnersHand rather than durationTags.ts.
  sweepExpiredControlThefts(state, cardDb);
  // CardInstance.cardTypeOverride's own sweep (task #35, 2026-07-16: Agram's Plaything's Puppet
  // Strings) -- same "moves through effects.ts, not durationTags.ts" reasoning as the control-theft
  // sweep just above, since it needs to fire onBecameCreature/onBecameRelic via setCardTypeOverride.
  sweepExpiredCardTypeOverrides(state, cardDb);
  // Phrup's Time Lapse name-block (task #50c, 2026-07-12) -- "this turn" ends here.
  state.blockedCardNamesThisTurn.clear();
  // Spray Narth's Congregate once-per-turn gate (region-audit follow-up, 2026-07-24) -- same
  // per-turn-flag-reset shape as the name-block just above.
  state.congregateUsedThisTurn = false;
  // Aula, Mindseeker's Windsight draw-lockout (region-audit follow-up, 2026-07-24) -- "this turn"
  // ends here, for the player whose turn is starting.
  player.cannotDrawThisTurn = false;
  // Deadfall's "next two Creatures played" charges (Naroom Spell pass, 2026-07-23) -- play.ts's
  // own turnNumber<=expiresAfterTurnNumber check already makes a stale counter inert, but clear it
  // outright here too (same hygiene as blockedCardNamesThisTurn just above) rather than leaving a
  // dead object sitting in GameState indefinitely.
  if (state.deadfallPendingCharges && state.turnNumber > state.deadfallPendingCharges.expiresAfterTurnNumber) {
    state.deadfallPendingCharges = null;
  }
  // Flourish's own turnNumber<=expiresAfterTurnNumber check already makes a stale window inert,
  // same hygiene sweep as deadfallPendingCharges just above.
  if (state.flourishUntilTurn !== null && state.turnNumber > state.flourishUntilTurn) {
    state.flourishUntilTurn = null;
  }
  // Spirit of Cald's reactive watch (region-audit follow-up, 2026-07-24) -- play.ts's own
  // turnNumber<=expiresAfterTurnNumber check already makes a stale watch inert, same hygiene sweep
  // as Deadfall just above.
  if (state.spiritOfCaldPendingWatch && state.turnNumber > state.spiritOfCaldPendingWatch.expiresAfterTurnNumber) {
    state.spiritOfCaldPendingWatch = null;
  }
  // Eyes of Arderial's spell-naming lock (2026-07-24) -- play.ts's own turnNumber<=expiresAfterTurnNumber
  // check already makes a stale entry inert, same hygiene sweep as Deadfall just above.
  state.bannedSpellNames = state.bannedSpellNames.filter((b) => state.turnNumber <= b.expiresAfterTurnNumber);

  // registry.ts's ticksWhileAttached (task #30, 2026-07-15: Tar Hyren's Cling) -- fires at the
  // beginning of EVERY turn, either player's, for a card currently sitting in another card's
  // attachedCards -- distinct from onOwnTurnStart/onOpponentTurnStart, which only ever scan
  // `inPlay` + Magi and would never reach an attached card. Scans both sides unconditionally.
  for (const p of state.players.values()) {
    for (const holder of p.inPlay) {
      for (const attached of activeAttachedCards(cardDb, holder)) {
        for (const effect of effectsFor(state, cardDb, attached)) {
          effect.ticksWhileAttached?.(state, cardDb, attached, holder, rng);
        }
      }
    }
  }

  // PlayerState.attackedThisTurn (Showdown) -- the player-level twin of the per-Creature flag
  // below, cleared at the same boundary. See its own doc comment for why a card-level scan is not
  // a substitute.
  player.attackedThisTurn = false;
  // PlayerState.playedRelicThisTurn (Brothers of Vengeance's "And We're Not Happy") -- same
  // player-level "did the ACT happen" shape, cleared at the same boundary.
  player.playedRelicThisTurn = false;
  // PlayerState.cardsPlayedThisTurn (Korg's play-count limiter, Bucket D Batch B 2026-08-13) --
  // reset for EVERY player at every turn boundary, not just the active one (owner Q2 ruling:
  // "reset EACH turn"). Korg gets a fresh 2-play budget for reactive Spells during the
  // opponent's turn.
  for (const p of state.players.values()) {
    p.cardsPlayedThisTurn = 0;
  }

  for (const card of player.inPlay) {
    // attackedLastOwnTurn/usedPowerLastOwnTurn are NOT snapshotted here -- they're snapshotted at
    // the END of this player's own turn instead (runEndOfTurnHooks, below), fixed 2026-08-09. See
    // that snapshot's own doc comment for why start-of-turn was the wrong place.
    card.attackedThisTurn = false;
    card.attackedMagiDirectlyThisTurn = false;
    card.attacksThisTurn = 0;
    card.oneShotBonusAttacks = 0;
    card.attackEnergyBonus = 0;
    card.attackEnergyMultiplier = 1;
    // Dreamwarp deliberately does NOT claw energy back here (owner ruling 2026-07-27). It changes
    // STARTING energy -- the stat that sets play cost and that ~50 cards read (Weebo, Ookami's
    // Drums, Liriel's Cape) -- not the energy sitting on the Creature. You pay the adjusted cost
    // and it enters play with the adjusted amount; that energy is then just energy. The "until the
    // end of the turn" clause governs the STAT, and is carried by `startingEnergyOverride`, swept
    // by sweepExpiredStartingEnergyOverrides like every other turn-scoped override.
    //
    // The old code subtracted the delta back off currentEnergy, which meant Dreamwarping UP made
    // you pay +1 AND then confiscated 1 -- paying twice for nothing, strictly worse than not using
    // the ability. It also dropped Creatures to 0 without a defeat check (the N'kala playtest
    // report). Only the ledger is cleared now; `dreamwarpAdjustment` survives as a record of what
    // was chosen (registry.ts's onAnyDreamwarpUsed reads a nonzero delta), never as a rollback.
    card.dreamwarpAdjustment = 0;
    card.wasAttackedThisTurn = false;
    card.defeatedThisTurn = false;
    card.energyLostToOpponentThisTurn = 0;
    card.usedPowerNames.clear();
    card.usedPowerCounts.clear();
  }
  if (player.activeMagi) {
    player.activeMagi.usedPowerNames.clear();
    player.activeMagi.usedPowerCounts.clear();
    player.activeMagi.attacksThisTurn = 0;
    player.activeMagi.oneShotBonusAttacks = 0;
  }

  if (!player.activeMagi) {
    revealNextMagi(state, cardDb, player, undefined, rng);
  }

  // "At the start of your turn" automatic grants (e.g. Korremar, Avatar's Wisdom: "Illusions may
  // attack one extra time each turn") -- fires once for the active player's own Magi and every
  // in-play card, same "scan everyone, let each card's own hook decide if it cares" shape as
  // onAttack/afterCombat.
  //
  // Jagt's/Gargagnor's Perpetual Motion (task #42, 2026-07-17, Kybar's Teeth pass, durationTags.ts's
  // PERPETUAL_MOTION doc comment): a player carrying that tag has their OWN onOwnTurnStart-family
  // broadcast rerouted to fire on their OPPONENT's turn start instead of their own -- so the normal
  // loop below is skipped entirely for a redirecting player's turn, and a second pass right after it
  // fires that SAME broadcast for any OPPONENT who is themselves redirecting (2-player-only, so "the
  // opponent" is unambiguous -- no real per-player choice needed, matching Treepsh's own "any one
  // opponent" simplification).
  // Simultaneous-order Phase 1 (playtest audit, 2026-08-11): instead of always firing in `inPlay`
  // array order, this is the proving case for simultaneousOrder.ts's beginOrderedBroadcast --
  // chosen because it's the site most plausible to have real same-controller collisions TODAY (a
  // large number of registered onOwnTurnStart effects on ordinary Relics/Creatures with no
  // one-per-player restriction, e.g. Warrada's Ring + Three Leaf Clover both on one board), and
  // because this hook is already per-player-scoped in normal play, so Phase 1 proves the
  // single-owner primitive without needing the cross-player APNAP case at all. Filters down to only
  // cards whose effect actually registers onOwnTurnStart first, so a board with one real reactor
  // plus ten irrelevant cards doesn't spuriously prompt for an "order" of one.
  const emitOwnTurnStart = (owner: PlayerState): void => {
    const cards: CardInstance[] = owner.activeMagi ? [owner.activeMagi, ...owner.inPlay] : [...owner.inPlay];
    const reactors = cards.filter((card) => effectsFor(state, cardDb, card).some((e) => !!e.onOwnTurnStart));
    beginOrderedBroadcast(state, cardDb, owner.playerId, 'onOwnTurnStart', reactors, undefined, rng);
  };
  const hasPerpetualMotion = (owner: PlayerState): boolean =>
    (owner.activeMagi ? [owner.activeMagi, ...owner.inPlay] : [...owner.inPlay]).some((c) => c.tags.has(PERPETUAL_MOTION));

  if (!hasPerpetualMotion(player)) {
    emitOwnTurnStart(player);
  }
  for (const opponent of getOpponents(state, player.playerId)) {
    if (hasPerpetualMotion(opponent)) {
      emitOwnTurnStart(opponent);
    }
  }
  // CardInstance.hasOmborResilience (Spirit of Ombor, Underneath Spell pass, 2026-07-25):
  // "At the beginning of your turn, if you have fewer Creatures in play than any opponent, add two
  // energy to your Magi." Granted onto a future revealed Magi, so it has no registerCardEffect
  // entry of its own to dispatch through -- checked directly here, same as TOSS_AND_TURN just
  // below. "Fewer than ANY opponent" is a strict less-than against each opponent's own count
  // (2-player: just the one), so an equal count does NOT qualify.
  if (player.activeMagi?.hasOmborResilience) {
    const ownCreatures = player.inPlay.length;
    const fewerThanSomeOpponent = getOpponents(state, player.playerId).some((o) => ownCreatures < o.inPlay.length);
    if (fewerThanSomeOpponent) {
      addEnergy(state, cardDb, player.activeMagi, 2, 'effect');
    }
  }
  // durationTags.ts's TOSS_AND_TURN (task #35, 2026-07-16: Nightmare Hyren's Horrible Dreams) --
  // a generic tag check, not a per-card hook, since the tagged Creature is typically NOT
  // Nightmare Hyren itself. Fires once if ANY of the active player's own in-play Creatures
  // carries it (the printed text is a property of the CONTROLLING player's turn, not multiplied
  // per tagged Creature if more than one somehow ended up on the same side).
  //
  // Scoped to Creatures only (playtest audit fix, 2026-08-11) -- `player.inPlay` holds Relics
  // alongside Creatures, and this loop used to hit every entry unconditionally. `discardEnergy`
  // unconditionally sets `currentEnergy` on whatever it's given; a Relic's `currentEnergy` is
  // normally `undefined` (Play.tsx renders it as "-"), so an affected Relic started showing a real
  // numeric energy badge every turn thereafter -- visually indistinguishable from a Creature losing
  // energy, even though nothing in the printed text touches Relics at all.
  if (player.inPlay.some((c) => c.tags.has(TOSS_AND_TURN))) {
    if (player.activeMagi) discardEnergy(state, cardDb, player.activeMagi, 1, 'effect', undefined, rng);
    for (const creature of player.inPlay) {
      if (cardDb.get(creature.definitionKey)?.card_type !== 'Creature') continue;
      discardEnergy(state, cardDb, creature, 1, 'effect', undefined, rng);
    }
  }
  // registry.ts's reactsFromDiscardPileAtOwnTurnStart (task #30, 2026-07-15: Black Stuff's
  // Regenerate) -- distinct from the onOwnTurnStart broadcast just above, which only ever scans
  // `inPlay` + Magi: a card sitting in the DISCARD PILE (not in play) would never be reached by
  // that loop at all, so this is a separate small broadcast specifically for the discard pile.
  // Snapshot the pile before iterating -- a successful play removes the card from it.
  for (const card of [...player.discardPile]) {
    for (const effect of effectsFor(state, cardDb, card)) {
      if (!effect.reactsFromDiscardPileAtOwnTurnStart) continue;
      effect.reactsFromDiscardPileAtOwnTurnStart(state, cardDb, card, rng);
    }
  }
  // The onOpponentTurnStart half of the pair above (registry.ts, added 2026-07-12 for Agram's
  // Armor's "at the beginning of EACH player's turn") -- same broadcast, just scanning every
  // OTHER player's Magi + inPlay instead.
  for (const opponent of getOpponents(state, player.playerId)) {
    const opponentCards: CardInstance[] = opponent.activeMagi ? [opponent.activeMagi, ...opponent.inPlay] : [...opponent.inPlay];
    for (const card of opponentCards) {
      const def = cardDb.get(card.definitionKey);
      for (const effect of effectsFor(state, cardDb, card)) {
        if (!effect.onOpponentTurnStart) continue;
        effect.onOpponentTurnStart(state, cardDb, card, rng);
        logEvent(state, 'onOpponentTurnStartHookFired', { cardName: def!.name, instanceId: card.instanceId });
      }
    }
  }

  state.energizePending = true;
}

/** Resolves `state.energizePending` (P2, 2026-07-12): runs the active player's Energize phase and
 *  clears the flag. Called by `beginTurn`'s thin wrapper (immediately, no pause) and by
 *  `advancePhase` (whenever the player's next action comes in -- the actual pause point). */
function resolveEnergizePending(state: GameState, cardDb: CardDatabase, rng: Rng = defaultRng): void {
  state.energizePending = false;
  state.phase = 'energize';
  runEnergizePhase(state, cardDb, getActivePlayer(state), rng);
}

export function revealNextMagi(
  state: GameState,
  cardDb: CardDatabase,
  player: PlayerState,
  options?: { skipStartingCards?: boolean },
  rng: Rng = defaultRng
): void {
  const next = player.magiQueue.shift();
  if (!next) {
    throw new Error(`${player.playerId} has no Magi left to reveal (game should already be over)`);
  }
  const def = cardDb.get(next.definitionKey);
  if (!def) throw new Error(`Unknown card key ${next.definitionKey}`);

  // registry.ts's declinesOwnReveal (Shadow Empress: "the first time each turn you would reveal
  // [her]... reveal your next Magi instead") -- checked against the card about to become active,
  // BEFORE it does, since a declining Magi never truly becomes active this cycle. `next` goes
  // back to the bottom of the queue face down and undefeated (same zone move the voluntary-swap
  // cards below use), and this recurses to reveal whichever Magi is next in line.
  for (const effect of effectsFor(state, cardDb, next)) {
    if (!effect.declinesOwnReveal?.(state, cardDb, next)) continue;
    // Stamp the once-per-turn mark BEFORE recursing (Tripvine's own `<name>UsedTurn` precedent,
    // combat.ts) -- fixed 2026-08-01 after a fuzz-found stack overflow: without this, a deck with
    // two or more copies of a declinesOwnReveal Magi (only possible via the fuzz harness's own
    // deck generator, which doesn't dedupe Magi picks -- see fuzzDecks.ts's own fix, same day)
    // recursed without bound, since each copy kept declining forever as it cycled to the back of
    // the queue. Named per-card (`shadowEmpressDeclinedTurn`), not generic, same as
    // tripvineStumbleUsedTurn/parathinHideUsedTurn -- this hook is Shadow Empress-specific today,
    // and a future second declinesOwnReveal card would stamp its own key the same way.
    next.counters.shadowEmpressDeclinedTurn = state.turnNumber;
    player.magiQueue.push(next);
    revealNextMagi(state, cardDb, player, options, rng);
    // The declining card may grant the REPLACEMENT one or more bonus starting-card entries
    // (Shadow Empress: "If that Magi is Hrada or Agram, add ... to his starting cards") --
    // checked here, once the replacement is already active.
    //
    // Fuzz harness finding (2026-07-30, task #600 bucket E): `player.activeMagi` was asserted
    // non-null on the assumption the recursive revealNextMagi call just above always leaves it
    // set -- confirmed live it does NOT always hold (uncaught "Cannot read properties of null
    // (reading 'definitionKey')" in magiCountsAs, from this exact call site, seed 949). A guard
    // here is the same "verify before touching" convention as every other reveal-path check in
    // this function; a genuinely unset activeMagi just means no bonus to grant.
    if (player.activeMagi) {
      const bonus = effect.bonusStartingCardNames?.(state, cardDb, next, player.activeMagi);
      if (bonus) {
        player.activeMagi.bonusStartingCardNames.push(...bonus);
      }
    }
    return;
  }

  if (typeof def.cost !== 'number') {
    throw new Error(`Magi ${def.name} has non-numeric starting energy (${def.cost}) -- data problem`);
  }
  next.currentEnergy = def.cost;
  // Bug fix 2026-08-12 (owner follow-up on the Warrior's Boots / Tony, Returned pass): a Magi
  // that was previously active this turn AND used a Power, then got tucked back into the
  // magiQueue via Giant Parathin's Interchange / M'Rika's Interchange / Shadow Empress's
  // declinesOwnReveal cycling back to the same Magi, was returning as activeMagi with a stale
  // `usedPowerNames` map -- so Tony, Returned's Rediscover was blocked on the second reveal
  // even though the Magi is a fresh object per the leaves-play-and-returns convention. Same
  // helper the enter-play sites in play.ts/effects.ts use; keeps this reset in exactly one
  // place. Safe for a first-ever reveal too (usedPowerNames is empty for a Magi that was never
  // active before -- no-op).
  resetPerTurnStateOnEnterPlay(next);
  player.activeMagi = next;
  if (options?.skipStartingCards) {
    addPermanentTagRaw(next, NO_STARTING_CARDS);
  }
  logEvent(state, 'magiRevealed', { playerId: player.playerId, instanceId: next.instanceId, name: def.name });
  // Broadcast to the revealed Magi itself AND every other card in play -- see registry.ts's
  // onMagiRevealed doc comment for why this isn't scoped to just the revealed card.
  for (const card of [next, ...player.inPlay]) {
    const cardDef = cardDb.get(card.definitionKey);
    for (const cardEffect of effectsFor(state, cardDb, card)) {
      if (!cardEffect.onMagiRevealed) continue;
      cardEffect.onMagiRevealed(state, cardDb, next, card, rng);
      logEvent(state, 'onMagiRevealedHookFired', { cardName: cardDef!.name, instanceId: card.instanceId });
    }
  }

  // registry.ts's onMagiRevealedWhileInDiscardPile -- the DISCARD-PILE-scoped sibling, for the
  // Recurring cards, whose whole ability only ever matters from the bin (the reveal they key off is
  // succession after a defeat, which just wiped their controller's board). Kept a separate hook so
  // the 15 in-play onMagiRevealed readers above don't start firing off dead copies -- see the hook's
  // doc comment. Iterated over a COPY, because a reactor may move itself out of the discard pile.
  for (const card of [...player.discardPile]) {
    const cardDef = cardDb.get(card.definitionKey);
    for (const cardEffect of effectsFor(state, cardDb, card)) {
      if (!cardEffect.onMagiRevealedWhileInDiscardPile) continue;
      cardEffect.onMagiRevealedWhileInDiscardPile(state, cardDb, next, card, rng);
      logEvent(state, 'onMagiRevealedHookFired', { cardName: cardDef!.name, instanceId: card.instanceId });
    }
  }

  // registry.ts's onNextMagiRevealed (Mobis's "+3 energy to your next Magi," Erisa's Legacy's
  // Relic-wipe half) -- checked against the CONTROLLER's most recently defeated Magi, which is no
  // longer in `inPlay` so the broadcast loop above would never reach it.
  const lastDefeated = player.defeatedMagi[player.defeatedMagi.length - 1];
  if (lastDefeated) {
    const defeatedDef = cardDb.get(lastDefeated.definitionKey);
    for (const defeatedEffect of effectsFor(state, cardDb, lastDefeated)) {
      if (!defeatedEffect.onNextMagiRevealed) continue;
      defeatedEffect.onNextMagiRevealed(state, cardDb, lastDefeated, next, rng);
      logEvent(state, 'onNextMagiRevealedHookFired', { cardName: defeatedDef!.name, instanceId: lastDefeated.instanceId });
    }
  }

  // Lady of the Sky's Legacy ("permanently increase the Energize rate of all of your other
  // Arderial Magi by one for the rest of the game") and Artimillies' Rememberance ("add two energy
  // to each of your Magi after they are revealed, +1 more if a Keeper") are both PERMANENT,
  // apply-to-EVERY-future-reveal effects, unlike onNextMagiRevealed's one-shot shape -- modeled as
  // two specific, generically-checked tags (durationTags.ts) rather than a per-card hook, same
  // "checked directly by the engine, not dispatched per-card" pattern FROZEN/BURROWED already use.
  // Lady of the Sky's own onOwnMagiDefeated tags the whole remaining Magi queue at the moment of
  // her own defeat (see ladyOfTheSky.ts); this only needs to read the tag on `next`.
  if (next.tags.has(ARTIMILLIES_REMEMBERANCE)) {
    const bonus = def.subtype === 'Keeper' ? 3 : 2;
    addEnergy(state, cardDb, next, bonus, 'effect');
  }

  // PlayerState.pendingMagiRevealEnergyBonus (Spirit of Bograth, Bograth Spell pass, 2026-07-20):
  // "when you reveal your next Magi, add energy to it equal to one opposing Magi's Energize rate"
  // -- a one-shot bonus snapshotted at Spirit of Bograth's own resolution (long before this reveal
  // happens), consumed the very next time THIS player's own reveal fires, however many turns away.
  if (player.pendingMagiRevealEnergyBonus !== null) {
    addEnergy(state, cardDb, next, player.pendingMagiRevealEnergyBonus, 'effect');
    player.pendingMagiRevealEnergyBonus = null;
  }

  // PlayerState.pendingMagiRevealDamageReduction (Spirit of the Teeth, Kybar's Teeth Spell pass,
  // 2026-07-22): "when you reveal your next Magi, it gains 'Effect -- Tough Stuff: Whenever this
  // Magi loses energy from an opposing card, it loses two less energy.'" Same "consumed the very
  // next reveal, however many turns away" shape as pendingMagiRevealEnergyBonus just above, but
  // sets CardInstance.grantedEnergyLossReduction on `next` instead of adding energy immediately.
  if (player.pendingMagiRevealDamageReduction !== null) {
    next.grantedEnergyLossReduction = player.pendingMagiRevealDamageReduction;
    player.pendingMagiRevealDamageReduction = null;
  }

  // PlayerState.pendingMagiRevealEternalVigor (Spirit of Naroom, Naroom Spell pass, 2026-07-23):
  // "when you reveal your next Magi, it permanently gains 'Effect -- Eternal Vigor...'" Same
  // "consumed the very next reveal, however many turns away" shape as the two pending fields just
  // above, but sets CardInstance.hasEternalVigor on `next` instead of a numeric grant.
  if (player.pendingMagiRevealEternalVigor) {
    next.hasEternalVigor = true;
    player.pendingMagiRevealEternalVigor = false;
  }

  // PlayerState.pendingMagiRevealOmborResilience (Spirit of Ombor, Underneath Spell pass,
  // 2026-07-25): "when you reveal your next Magi, it gains 'Effect -- Resilience...'" -- identical
  // arm-now/consume-at-next-reveal shape to Eternal Vigor just above; the granted ability itself is
  // a beginning-of-your-turn trigger, checked in runStartOfTurnHooks.
  if (player.pendingMagiRevealOmborResilience) {
    next.hasOmborResilience = true;
    player.pendingMagiRevealOmborResilience = false;
  }

  // PlayerState.pendingMagiRevealStartingCardNames (Spirit of Orothe, Orothe Spell pass, Category
  // D, 2026-07-24): "when you reveal your next Magi, replace his or her starting cards line with
  // 'STARTING: Orothean Goggles, Hubdra's Cube, One Orothe Creature'" -- same "consumed at the
  // very next reveal, however many turns away" shape as the pending fields just above, granted via
  // `bonusStartingCardNames` (same field/mechanism Shadow Empress's succession clause already
  // uses) rather than a numeric/boolean field on `next`. See that PlayerState field's own doc
  // comment for the documented additive-not-replace simplification.
  if (player.pendingMagiRevealStartingCardNames) {
    next.bonusStartingCardNames.push(...player.pendingMagiRevealStartingCardNames);
    player.pendingMagiRevealStartingCardNames = null;
  }

  // Starting-card tutoring (§4.4/§10) and the opening-hand draw are NOT done here, deliberately.
  // Both are player choices / order-sensitive with each other (tutor first, then draw tops up to
  // 5 -- doing it here would draw before the caller has a chance to tutor). The caller (UI) is
  // responsible for calling tutorStartingCards and then drawOpeningHandIfEligible (both in
  // setup.ts) once it detects a freshly-revealed Magi.
}

/**
 * A card's total Energize-phase gain: printed def.energize (Magi always have one; a handful of
 * non-Magi Creatures like Rabbage/Green Stuff print their own), plus every currently-active
 * STORED modifier on the card itself (energizeModifiers.ts -- Tree Hinko's one-shot +2, Yayek's
 * "until end of turn" +N, Agram's permanent ratchet), plus every in-play card's (both players',
 * including both Magi) CONTINUOUS energizeRateModifier hook contribution (registry.ts -- Water of
 * Life's flat +1, Ice Hyren's conditional grant). Clamped to a minimum of 0 -- a negative
 * Energize rate would be a soft-lock, not a real rules outcome.
 */
export function effectiveEnergizeRate(state: GameState, cardDb: CardDatabase, instance: CardInstance): number {
  const def = cardDb.get(instance.definitionKey)!;
  let total = def.energize ?? 0;
  // Rules-correctness fix (2026-08-05, owner-supplied ruling): energize rates from separate GRANTS
  // ("gain(s)/have an Energize: N") don't stack with each other or with the card's own
  // printed/modified rate -- only the highest applies. Genuine additive deltas ("+N"/"increased by
  // N") keep summing into `total` exactly as before; grant amounts are collected separately and
  // folded in via Math.max at the very end instead. See EnergizeModifier.isGrant's own doc comment
  // for the concrete bug this fixes (Overgrowth stacking with a Creature's own printed rate).
  const grants: number[] = [];
  for (const mod of activeEnergizeModifiers(state, instance)) {
    if (mod.isGrant) grants.push(mod.amount);
    else total += mod.amount;
  }
  // Lady of the Sky's Legacy -- see durationTags.ts's LADY_OF_THE_SKY_ENERGIZE_BONUS doc comment.
  if (instance.tags.has(LADY_OF_THE_SKY_ENERGIZE_BONUS)) {
    total += 1;
  }
  // Wind Hyren's Invigorate cap (Bucket D Batch A closure, 2026-08-13). "A Magi can only be
  // affected by one Invigorate at a time" -- when any live Wind Hyren is in play, all
  // Invigorate-named `energizeRateModifier` contributions collapse to the highest instead of
  // summing. Owner ruling 2026-08-13: highest-wins, silence the rest. Bucketed contributions
  // are identified by `effect.effectHooks?.Invigorate?.includes('energizeRateModifier')`; every
  // continuous-Invigorate card (Wind Hyren, Thast, Water of Life, Rayje's Construct, Ruid)
  // declares this annotation. Tree Hinko's one-shot Invigorate Power uses
  // `applyEnergizeModifier` and doesn't reach this broadcast, correctly excluded from the cap.
  const invigorateContributions: number[] = [];
  const invigorateCapActive = (() => {
    for (const p of state.players.values()) {
      const board: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
      for (const card of board) {
        const def = cardDb.get(card.definitionKey);
        if (def?.name !== 'Wind Hyren') continue;
        // Rayje-lockdown of Invigorate silences the cap along with the +2 grant. effectsFor
        // strips locked hooks, so a Wind Hyren whose Invigorate is locked returns no
        // energizeRateModifier hook here and its cap-carrying rule is silenced with it.
        for (const eff of effectsFor(state, cardDb, card)) {
          if (eff.effectHooks?.Invigorate?.includes('energizeRateModifier') && eff.energizeRateModifier) {
            return true;
          }
        }
      }
    }
    return false;
  })();
  for (const p of state.players.values()) {
    const onBoard: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
    // ...plus each board card's own attachedCards. An attach-a-marker Spell (Dream Channel,
    // Nightmare Channel) lives in its HOST's `attachedCards`, never in anyone's `inPlay`, so a
    // board-only scan cannot see it and its energize clause would silently do nothing -- the same
    // blind spot `amplifiesOwnEnergyLoss` (Sunburn) and `grantedAttackLossReduction` already widen
    // for. Found by a Dream Channel test reading 5 where it should have read 7.
    const contributors: CardInstance[] = [...onBoard, ...onBoard.flatMap((c) => activeAttachedCards(cardDb, c))];
    for (const contributor of contributors) {
      for (const effect of effectsFor(state, cardDb, contributor)) {
        if (effect.energizeRateModifier) {
          const delta = effect.energizeRateModifier(state, cardDb, instance, contributor);
          const isInvigorate = effect.effectHooks?.Invigorate?.includes('energizeRateModifier') === true;
          if (isInvigorate) {
            if (delta > 0) invigorateContributions.push(delta);
            // Negative Invigorate deltas would be an unprinted shape; if any card ever prints
            // one, revisit the cap semantics. Zero deltas (region-gated no-ops like Wind Hyren
            // on a Bograth Magi) are naturally dropped by the > 0 filter.
          } else {
            total += delta;
          }
        }
        // energizeRateGrant (see registry.ts's own doc comment) -- Jile/Yerthe/Ice Hyren/Chayla/
        // Gragling's "gain(s) ENERGIZE: N" clauses, kept out of the additive `total` on purpose.
        if (effect.energizeRateGrant) {
          const grant = effect.energizeRateGrant(state, cardDb, instance, contributor);
          if (grant > 0) grants.push(grant);
        }
      }
    }
  }
  // Apply the Invigorate bucket: `Math.max` under the cap, sum otherwise.
  if (invigorateContributions.length > 0) {
    total += invigorateCapActive
      ? Math.max(...invigorateContributions)
      : invigorateContributions.reduce((a, b) => a + b, 0);
  }
  return Math.max(0, total, ...grants);
}

/** Applies one instance's own Energize gain (the shared body between the normal Energize-phase
 *  path and task #50g's deferred-to-Draw path below). Exported (Naroom Spell pass, 2026-07-23:
 *  Flood of Energy -- "Energize all cards with an energize rate") so an ad-hoc extra-energize
 *  effect can reuse the exact same per-card gain (afterMagiEnergized broadcast, one-shot modifier
 *  consumption, energized log event) instead of re-deriving a partial copy. */
export function applyEnergizeToInstance(state: GameState, cardDb: CardDatabase, player: PlayerState, instance: CardInstance, rng: Rng = defaultRng): void {
  // registry.ts's beforeOwnEnergize (Agram's Focus: "before Agram energizes... permanently add
  // one to his energize rate") -- fires BEFORE the rate is read below, so a ratchet applies to
  // THIS SAME energize event too, not just future ones.
  for (const ownEffect of effectsFor(state, cardDb, instance)) {
    ownEffect.beforeOwnEnergize?.(state, cardDb, instance);
  }
  const amount = effectiveEnergizeRate(state, cardDb, instance);
  if (amount === 0 && instance.energizeModifiers.length === 0) return;
  instance.currentEnergy = (instance.currentEnergy ?? 0) + amount;
  consumeOneShotEnergizeModifiers(instance);
  logEvent(state, 'energized', {
    playerId: player.playerId,
    instanceId: instance.instanceId,
    amount,
    newTotal: instance.currentEnergy,
  });
  // registry.ts's onMagiGainedEnergyOutsideOwnEnergizeStep (Wyle's Tap Strength, 2026-07-28) --
  // an ENERGIZE can itself land outside the Energize step: Flood of Energy calls this function
  // mid-turn from a Spell, and Zajan energizes during the Draw step via the deferral grant below.
  // Both bypass addEnergy entirely, which is exactly why the hook is phase-gated rather than
  // hung off the addEnergy path. The helper itself decides whether the phase qualifies.
  broadcastMagiEnergyGainOutsideEnergize(state, cardDb, instance, amount);
  // registry.ts's afterMagiEnergized (added 2026-07-12 for Nightmare Construct's Absorb) --
  // only Magi-energize events react-broadcast (a Magi's own text says "a Magi energizes," never
  // "a Creature energizes"), to every in-play card + Magi on BOTH sides, since Absorb-style text
  // has no "your"/"opposing" qualifier.
  if (instance === player.activeMagi) {
    for (const p of state.players.values()) {
      const reactors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
      for (const reactor of reactors) {
        for (const effect of effectsFor(state, cardDb, reactor)) {
          effect.afterMagiEnergized?.(state, cardDb, instance, reactor, amount, rng);
        }
      }
    }
  }
}

/** registry.ts's deferEnergizeToDraw (task #50g, 2026-07-12) -- broadcast to every in-play card
 *  + Magi on both sides, asking each "do you move `candidate`'s Energize gain to the Draw step." */
function hasEnergizeDeferralGrant(state: GameState, cardDb: CardDatabase, candidate: CardInstance): boolean {
  for (const p of state.players.values()) {
    const contributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
    for (const contributor of contributors) {
      for (const effect of effectsFor(state, cardDb, contributor)) {
        if (effect.deferEnergizeToDraw?.(state, cardDb, candidate, contributor)) return true;
      }
    }
  }
  return false;
}

function runEnergizePhase(state: GameState, cardDb: CardDatabase, player: PlayerState, rng: Rng = defaultRng): void {
  // registry.ts's onOwnEnergizeStepStart (task #43, 2026-07-18: Blizzard Core's Coriolis) --
  // fires before anything else in this function, even the first-turn skip check, since "the
  // beginning of your Energize step" happens regardless of whether Energize itself gets skipped.
  const stepStartCards: CardInstance[] = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
  for (const card of stepStartCards) {
    for (const effect of effectsFor(state, cardDb, card)) {
      effect.onOwnEnergizeStepStart?.(state, cardDb, card, rng);
    }
  }
  if (state.skipEnergizeForFirstTurn) {
    state.skipEnergizeForFirstTurn = false; // single-event, consumed now (rules-reference.md §4)
    // task #50g: this turn's Energize never ran at all, so runDrawPhase's own deferred-apply
    // loop (V'ryle/Zajan's deferEnergizeToDraw) must NOT grant a gain that was never actually
    // skipped-and-deferred -- without this, a deferred card would get a "free" bonus gain on the
    // one turn Energize is skipped entirely (rules-reference.md §4), which no other card gets.
    state.energizeSkippedThisTurn = true;
    logEvent(state, 'energizeSkipped', { playerId: player.playerId, reason: 'first turn of the game' });
    return;
  }
  // Crushing Fungus (Spell, Underneath Spell pass, Category B, 2026-07-25): "its Magi does not
  // energize on his or her next turn." One-shot -- cleared whether or not it actually bites, since
  // the penalty was aimed at ONE specific Magi and a replacement Magi is not the one that was
  // penalized. See types/state.ts's skipEnergizeForMagiInstanceId.
  if (player.skipEnergizeForMagiInstanceId !== null) {
    const penalizedMagiStillActive = player.activeMagi?.instanceId === player.skipEnergizeForMagiInstanceId;
    player.skipEnergizeForMagiInstanceId = null;
    if (penalizedMagiStillActive) {
      // Same reason the first-turn skip sets this: task #50g's deferEnergizeToDraw must not grant
      // a bonus for an Energize step that never actually ran.
      state.energizeSkippedThisTurn = true;
      logEvent(state, 'energizeSkipped', { playerId: player.playerId, reason: 'Crushing Fungus' });
      return;
    }
  }
  state.energizeSkippedThisTurn = false;
  if (player.activeMagi) {
    player.hasEnergizedOnce = true;
  }
  // Magi always energize (rules-reference.md §5.1); non-Magi in-play cards only do if they print
  // or have been granted a nonzero rate (e.g. Rabbage, Green Stuff) -- the overwhelming majority
  // of Creatures/Relics have no ENERGIZE rate at all and effectiveEnergizeRate correctly returns 0
  // for them.
  const candidates: CardInstance[] = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
  for (const instance of candidates) {
    // task #50g's deferEnergizeToDraw (V'ryle's Autumn Leaves, Zajan's Work All Night) -- skip
    // the normal gain entirely here; runDrawPhase applies it there instead.
    if (hasEnergizeDeferralGrant(state, cardDb, instance)) continue;
    applyEnergizeToInstance(state, cardDb, player, instance, rng);
  }
  // task #50g's drawsDuringEnergizeInstead (Zajan's Sleep All Day) -- self-only, drawing during
  // Energize instead of Draw; the same reshuffle-once-per-turn rule as runDrawPhase's own draw
  // applies (shared across both, since Zajan's own Draw-phase count is separately suppressed to
  // 0 by his drawCountModifier, so there's no risk of reshuffling twice in one turn).
  for (const instance of candidates) {
    // TODO(granted-effects composition): per-effect independent invocation here means multiple
    // grants of drawsDuringEnergizeInstead on one Creature each trigger their own draw+broadcast
    // (sum semantics via repeated firing). Only Zajan's Sleep All Day registers this today, so
    // the situation only arises under Rock Yajo grants — flagged for primary-session review.
    for (const effect of effectsFor(state, cardDb, instance)) {
      const count = effect.drawsDuringEnergizeInstead?.(state, cardDb, instance);
      if (!count || count <= 0) continue;
      let drawn = drawCardsRaw(player, count);
      if (drawn.length < count && player.discardPile.length > 0) {
        shuffleDiscardIntoDeck(player, rng);
        const remainder = drawCardsRaw(player, count - drawn.length);
        drawn = [...drawn, ...remainder];
      }
      logEvent(state, 'drewCards', { playerId: player.playerId, count: drawn.length });
      broadcastCardsDrawn(state, cardDb, player.playerId, drawn, rng);
    }
  }
  // Defensive -- not expected to fire from energize itself, but keeps the "check continuously"
  // rule honest if something upstream left a card sitting at 0.
  checkForDefeats(state, cardDb, undefined, rng);
}

/** registry.ts's onAnyCardDrawn (task #35, 2026-07-16: Darkbreed's Minion's Smolder) -- fired
 *  `count` times (once per card actually drawn), broadcast to every in-play card + Magi on both
 *  sides. Previously wired only into these two natural Draw Step call sites; widened (task #44,
 *  2026-07-18: outside-Draw-Step trigger sweep) to also fire from effects.ts's `drawCards`
 *  primitive, so a card reacting to an opponent's EFFECT-triggered draw (not just a natural Draw
 *  Step draw) sees it too -- `cardDb` was the actual blocker, not the call-site count (see
 *  `drawCards`'s own doc comment). Kept as a separate copy of the same broadcast logic rather than
 *  importing `drawCards` here, since `turn.ts` uses `drawCardsRaw` directly for its own
 *  reshuffle-aware Draw Step handling (rules-reference.md §5.6's Draw-Step-only reshuffle rule),
 *  not the wrapped `drawCards`.
 *
 *  Task #47, 2026-07-18 (bug fix): in-play reactors get `onAnyCardDrawn` over activeMagi + inPlay
 *  ONLY; HAND cards get the separate `onAnyCardDrawnWhileInHand` hook (Snow Barl Pup) -- kept apart
 *  so an in-play passive Effect (Darkbreed's Minion et al.) can never fire while sitting in hand.
 *
 *  Widened again (Cald Spell pass, 2026-07-20: Singed Pride -- "After that Magi's owner draws a
 *  card outside of his or her Draw step...") to ALSO scan each in-play contributor's own
 *  `attachedCards` -- a card attached to a Magi/Creature (via `attachedCards.ts`'s `attachCard`)
 *  sits in `holder.attachedCards`, not `p.inPlay`/`p.activeMagi` itself, so it was previously
 *  unreachable by this broadcast no matter what it registered (same "attached card invisible to a
 *  board-wide scan" gap the Flame Spurt build separately widened for `combat.ts`'s
 *  `allInPlayAndMagi`). Purely additive: no pre-existing `onAnyCardDrawn` registrant has ever sat
 *  in `attachedCards`, so this changes nothing for any card built before Singed Pride. */
function broadcastCardsDrawn(state: GameState, cardDb: CardDatabase, drawingPlayerId: PlayerState['playerId'], drawnCards: readonly CardInstance[], rng: Rng = defaultRng): void {
  for (const drawnCard of drawnCards) {
    for (const p of state.players.values()) {
      const inPlayContributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
      for (const contributor of inPlayContributors) {
        for (const effect of effectsFor(state, cardDb, contributor)) {
          effect.onAnyCardDrawn?.(state, cardDb, contributor, drawingPlayerId, drawnCard, rng);
        }
        for (const attached of activeAttachedCards(cardDb, contributor)) {
          for (const attachedEffect of effectsFor(state, cardDb, attached)) {
            attachedEffect.onAnyCardDrawn?.(state, cardDb, attached, drawingPlayerId, drawnCard, rng);
          }
        }
      }
      for (const handCard of p.hand) {
        for (const effect of effectsFor(state, cardDb, handCard)) {
          effect.onAnyCardDrawnWhileInHand?.(state, cardDb, handCard, drawingPlayerId, drawnCard);
        }
      }
    }
  }
}

function runDrawPhase(state: GameState, cardDb: CardDatabase, player: PlayerState, rng: Rng): void {
  if (state.skipDrawStepThisTurn) {
    state.skipDrawStepThisTurn = false; // single-event, consumed now
    logEvent(state, 'drawStepSkipped', { playerId: player.playerId });
    return;
  }
  // PlayerState.cannotDrawThisTurn (region-audit follow-up, 2026-07-24: Aula, Mindseeker's
  // Windsight) -- this natural Draw Step calls drawCardsRaw directly below, bypassing
  // effects.ts's own drawCards choke point, so it needs this separate early return.
  if (player.cannotDrawThisTurn) {
    logEvent(state, 'drawStepSkipped', { playerId: player.playerId });
    return;
  }
  // Mydra Swarm (Bograth Spell pass, 2026-07-20): "the chosen player cannot draw any cards on his
  // or her next turn" -- PlayerState.pendingDrawSkipOnTurnNumber's own doc comment explains why
  // this is a targeted, specific-future-turn field rather than skipDrawStepThisTurn's same-turn/
  // self-only shape. Consumed the moment it matches, same single-event convention as above.
  if (player.pendingDrawSkipOnTurnNumber !== null) {
    const shouldSkip = player.pendingDrawSkipOnTurnNumber === state.turnNumber;
    player.pendingDrawSkipOnTurnNumber = null;
    if (shouldSkip) {
      logEvent(state, 'drawStepSkipped', { playerId: player.playerId });
      return;
    }
  }
  // registry.ts's drawCountModifier (Scarletsong Banner's "draw an extra card during your Draw
  // step," Tropical Plith's conditional +1) -- scanned over the drawing player's own contributors
  // only, same shape as effectiveEnergizeRate but no opposing side ever grants this.
  let drawCount = DRAW_COUNT;
  const drawContributors: CardInstance[] = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
  for (const contributor of drawContributors) {
    for (const effect of effectsFor(state, cardDb, contributor)) {
      if (effect.drawCountModifier) {
        drawCount += effect.drawCountModifier(state, cardDb, contributor);
      }
    }
  }
  // PlayerState.aubrasWisdomExtraDrawUntilTurn (task #349, 2026-07-20) -- see that field's own doc
  // comment for why this is a player-level expiry rather than a registry.ts drawCountModifier.
  if (player.aubrasWisdomExtraDrawUntilTurn !== null && state.turnNumber <= player.aubrasWisdomExtraDrawUntilTurn) {
    drawCount += 3;
  }
  // PlayerState.tranquilityExtraDrawUntilTurn (Wave DD1 of the deferred coverage audit,
  // 2026-08-13) -- Tranquility's second clause "Draw one additional card during your Draw Step
  // this turn." Same shape as aubrasWisdomExtraDrawUntilTurn just above; see the field's own
  // doc comment for why this is a player-level expiry rather than a registry.ts drawCountModifier.
  if (player.tranquilityExtraDrawUntilTurn !== null && state.turnNumber <= player.tranquilityExtraDrawUntilTurn) {
    drawCount += 1;
  }
  drawCount = Math.max(0, drawCount);
  // registry.ts's anyDrawCountModifier (task #35, 2026-07-16: Ebony Mirror's conditional "-1") --
  // both sides can grant this (unlike drawCountModifier above), so scan every in-play card + Magi
  // across ALL players, same shape as capsDrawCountAt just below.
  let guaranteedMinimum: number | undefined;
  for (const p of state.players.values()) {
    const broadcastContributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
    for (const contributor of broadcastContributors) {
      for (const effect of effectsFor(state, cardDb, contributor)) {
        if (effect.anyDrawCountModifier) {
          drawCount += effect.anyDrawCountModifier(state, cardDb, contributor, player.playerId);
        }
        const minimum = effect.guaranteesMinimumDrawCountOf?.(state, cardDb, contributor);
        if (minimum !== undefined) guaranteedMinimum = guaranteedMinimum === undefined ? minimum : Math.max(guaranteedMinimum, minimum);
      }
    }
  }
  drawCount = Math.max(0, drawCount);
  // registry.ts's capsDrawCountAt (task #50k, 2026-07-12: Reality Anchor's "Players may not draw
  // more than four cards each turn") -- both sides can grant this, so scan every in-play card +
  // Magi across ALL players, not just the drawing one; the lowest cap wins.
  for (const p of state.players.values()) {
    const capContributors: CardInstance[] = p.activeMagi ? [p.activeMagi, ...p.inPlay] : [...p.inPlay];
    for (const contributor of capContributors) {
      for (const effect of effectsFor(state, cardDb, contributor)) {
        const cap = effect.capsDrawCountAt?.(state, cardDb, contributor);
        if (cap !== undefined) drawCount = Math.min(drawCount, cap);
      }
    }
  }
  // registry.ts's guaranteesMinimumDrawCountOf (task #35, 2026-07-16: Ebony Mirror's "all players
  // draw at least one card") -- applied LAST, after the cap above, so this floor can't be
  // undercut by a cap that's stricter than the guaranteed minimum (Ebony Mirror's own cap and
  // floor never conflict in practice -- the cap only ever fires at DRAW_COUNT-1 -- but a future
  // second card combining both independently should still resolve correctly).
  if (guaranteedMinimum !== undefined) drawCount = Math.max(drawCount, guaranteedMinimum);
  // PlayerState.pendingDrawCap (task #35, 2026-07-16: Korremar's Mind Shock) -- a one-shot hard
  // cap on THIS specific player's draw, applied LAST (after every other modifier/cap/floor above)
  // since it's a targeted "may only draw X" restriction, then consumed immediately.
  if (player.pendingDrawCap !== null) {
    drawCount = Math.min(drawCount, player.pendingDrawCap);
    player.pendingDrawCap = null;
  }

  let drawn = drawCardsRaw(player, drawCount);
  if (drawn.length < drawCount && player.discardPile.length > 0) {
    // The only point in the turn reshuffling like this is allowed, and only once per turn
    // (rules-reference.md §5.6).
    shuffleDiscardIntoDeck(player, rng);
    const remainder = drawCardsRaw(player, drawCount - drawn.length);
    drawn = [...drawn, ...remainder];
  }
  logEvent(state, 'drewCards', { playerId: player.playerId, count: drawn.length });
  broadcastCardsDrawn(state, cardDb, player.playerId, drawn, rng);
  // registry.ts's afterOwnDraw (task #37, 2026-07-17: Pok's Brilliantly Absent-Minded -- "draw two
  // additional cards, then discard a card at random from your hand") -- own contributors only,
  // fired once per Draw Step regardless of how many cards were actually drawn.
  for (const contributor of drawContributors) {
    for (const effect of effectsFor(state, cardDb, contributor)) {
      effect.afterOwnDraw?.(state, cardDb, contributor, rng, drawn);
    }
  }
  // registry.ts's onSelfDrawnDuringDrawStep (deferred-list re-audit Bucket C closure,
  // 2026-08-13: Tweave's Surprise -- "If you draw Tweave during your Draw Step, ..."). Fired
  // per just-drawn card, on the drawn card ITSELF (which is now in the drawing player's hand,
  // never in play at trigger time -- this is why `afterOwnDraw`'s in-play-contributors-only
  // scan can't cover it). Deliberately scanned over `drawn` rather than over any board slice.
  //
  // Draw-Step-scoping (Bucket C Q4, 2026-08-13): the Draw Step is a phase, so the phase gate
  // is that this call site is inside `runDrawPhase`. `effects.ts`'s `drawCards` mirrors this
  // fire behind a `state.phase === 'draw'` check, so a follow-up draw made from within the
  // Draw Step (a future Tomorrow's Jewel's Lore) still triggers, while a Spell/Power drawing
  // outside the Draw Step (Vortex of Knowledge, Secrets of the Book) does NOT.
  for (const drawnCard of drawn) {
    for (const effect of effectsFor(state, cardDb, drawnCard)) {
      effect.onSelfDrawnDuringDrawStep?.(state, cardDb, drawnCard, rng);
    }
  }
  // registry.ts's onOwnDrawStepComplete (Bucket D Batch B closure, 2026-08-13: Tomorrow's
  // Jewel's Lore -- "Once during your Draw step, after you draw, you may discard one card
  // from your hand. If you do, draw one card"). Fires ONCE per Draw phase, per own in-play
  // card that registers it (Magi + inPlay, mirroring afterOwnDraw's own scoping). Distinct
  // from `onSelfDrawnDuringDrawStep` (which fires per-drawn-card on the drawn card itself);
  // this fires on the OBSERVER (a card already in play) once, after all draws complete. The
  // hook body may set `state.drawPending = true` to force `advancePhase` to pause before
  // moving off the Draw phase (owner Q4 ruling 2026-08-13: pause pattern preferred over
  // arm-and-let-carry for higher fidelity to "during your Draw step").
  for (const contributor of drawContributors) {
    for (const effect of effectsFor(state, cardDb, contributor)) {
      effect.onOwnDrawStepComplete?.(state, cardDb, contributor, rng);
    }
  }

  // task #50g's deferEnergizeToDraw (V'ryle's Autumn Leaves, Zajan's Work All Night) -- apply the
  // Energize gain HERE for any candidate that had it deferred from the Energize phase above.
  // Skipped entirely if THIS turn's Energize phase never ran at all (energizeSkippedThisTurn) --
  // otherwise a deferred card would get a "free" gain on the one turn Energize is skipped
  // outright (rules-reference.md §4), which no other card gets.
  if (!state.energizeSkippedThisTurn) {
    const energizeCandidates: CardInstance[] = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
    for (const instance of energizeCandidates) {
      if (hasEnergizeDeferralGrant(state, cardDb, instance)) {
        applyEnergizeToInstance(state, cardDb, player, instance, rng);
      }
    }
  }
}

/**
 * Advances to the next phase in sequence, running that phase's automatic entry action if it has
 * one (Energize, Draw). PRS/Attack/Play-New-Creatures have no automatic action -- they're
 * windows for player-chosen actions (combat: task 13; playing cards and using Powers: task 14),
 * not implemented by this function. Advancing past the last phase (Draw) ends the turn instead.
 */
export function advancePhase(
  state: GameState,
  cardDb: CardDatabase,
  rng: Rng = defaultRng,
  // Internal-only: true when this call is the skip-bypass's own recursive continuation (see
  // below), so the "leaving attack" check doesn't fire for a phase that was entered and
  // immediately skipped THIS SAME synchronous call chain, never genuinely played.
  _skippingPhase = false
): void {
  if (state.winnerId || state.isDraw) {
    throw new Error('Game is already over');
  }
  // Defensive sweep (task #591 Phase 7, 2026-07-30) -- runs FIRST, ahead of every sweep below, since
  // declining it through to completion can itself set fresh one-advancePhase-lifetime state (e.g. a
  // Power/Spell/attack finally resolving here could open a reactiveWindow or post a Dreamwarp
  // choice) that the sweeps below need to also catch. See reactiveOffers.ts's own doc comment on
  // declineStalePendingReactiveOffer for why this can't just null the field like its siblings do.
  declineStalePendingReactiveOffer(state, cardDb, rng);
  // Same defense-in-depth as the sweep just above, for PvP Step 3.5 item 4's own pause field --
  // see declineStalePendingOpponentHandChoice's own doc comment (reactiveOffers.ts).
  declineStalePendingOpponentHandChoice(state, cardDb, rng);
  // Same defense-in-depth again, for the "Group B" fix's own pause field -- see
  // declineStalePendingOpponentSubChoice's own doc comment (reactiveOffers.ts).
  declineStalePendingOpponentSubChoice(state, cardDb, rng);
  // Same defense-in-depth again, for Category C's own pause field -- see
  // declineStalePendingSimultaneousOrderChoice's own doc comment (simultaneousOrder.ts).
  declineStalePendingSimultaneousOrderChoice(state, cardDb, rng);
  // A one-shot off-turn reactive-play opportunity (task #35, 2026-07-16) -- valid only until the
  // NEXT advancePhase call, unconditionally, so it can't outlive the attack phase (or turn) it was
  // created in. The only legal actions while it's live are "declare another attack" (already
  // self-clearing -- see combat.ts's declareAttack) or "advance phase" (cleared here). Mirrors the
  // blockedCardNamesThisTurn.clear() per-turn-flag-reset precedent above (runStartOfTurnHooks) but
  // fires on every advancePhase call, not just turn start, since the window must not survive past
  // the attack phase even within the same turn.
  state.reactiveWindow = null;
  // Post-hoc pending choices get the same one-advancePhase window, and for the same reason (task
  // #533, 2026-07-26). A pending choice belongs to the moment its trigger fired; if its reader
  // could not build a prompt then -- empty pool, or Rayje's Belt locking the effect down -- the
  // choice must FIZZLE, not sit on the card waiting for the blocker to lift and then ambush the
  // player mid-combat. Safe to do unconditionally here because the UI refuses to advance the
  // phase while a prompt is open, so anything still pending at a phase boundary was never
  // offered. See durationTags.ts's addPendingChoiceTag for the full write-up.
  sweepStalePendingChoiceTags(state);
  // Reveal-time pending choices (Kyg'n's energize target, Rayje/Wiep/Grahnna's Transform, Yog's
  // Turn, Niffer/Bria/League Elder's region pick) get a SEPARATE, owner-scoped sweep instead of the
  // one above. The one above assumes the choice's OWNER is the one whose advancePhase call is
  // clearing it (true for a human, whose one shared modal blocks every player's input) -- but a
  // reveal can happen on the OPPONENT's turn (Kyg'n succeeding a defeated Magi mid-combat), and nothing
  // stops the opponent's own routine advancePhase calls from sweeping a choice its bot never got a
  // chance to answer, well before the owner's own next turn. See durationTags.ts's
  // addPendingRevealChoiceTag for the full write-up (found live via Spectate mode, 2026-08-01).
  sweepStalePendingRevealChoiceTags(state);
  // Reactive Dreamwarp (Phase 0, 2026-07-30): same one-advancePhase lifetime as every other
  // post-hoc choice above -- fizzles rather than lingering to ambush a later playCard.
  declineReactiveDreamwarp(state);
  // Fate's Whimsy die-roll window (Category D SEVENTH item, 2026-08-12, task #724): same
  // defense-in-depth as every other pending choice above -- a UI that never answered the Whimsy
  // prompt (or a bot that didn't know to) must not leave the roll dangling forever. Finalize
  // with `currentValue` (which is `originalValue` if no Whimsy was ever played, or the last
  // player's picked value if the chain got partway through).
  if (state.pendingDieRoll) {
    finalizePendingDieRoll(state, cardDb, rng);
  }
  // Pausable-outer-resolution refactor (2026-08-14): the Yricho's Staff consumer chain above
  // clears `pendingDiscardFromPlay` on any of its exit paths (prevent, next-candidate,
  // resume). Only defense-in-depth clear the field if it's stuck WITHOUT a pending die roll --
  // that would mean the consumer left torn state (a bug in a card body that threw, a
  // hot-reload dropping a consumer registration). If the consumer re-armed pendingDieRoll for
  // the NEXT Yricho candidate in the chain, we must leave pendingDiscardFromPlay set so the
  // next finalize call can complete the chain properly.
  if (state.pendingDieRoll === null) {
    state.pendingDiscardFromPlay = null;
    // Multi-target discard queue safety-net (2026-08-15): same defense-in-depth as the field
    // above -- normally the yrichoStaff:safe consumer drains this queue on every exit path, so
    // by the time we get here it should already be empty. If a torn state left entries stuck,
    // clear them here rather than let them fire mid-next-turn.
    state.pendingDiscardFromPlayQueue = [];
  }
  // Spirit of Rayje's pre-defeat interrupt (task #535 Phase 2) gets the same unconditional
  // one-advancePhase lifetime, for a blunter reason than the others: while it is open, energy.ts's
  // checkMagiDefeats is DEFERRING a defeat. A UI that never answers would otherwise leave a Magi
  // alive at 0 energy forever. Declining resolves the deferred defeat properly rather than just
  // dropping the flag.
  for (const playerId of [...state.players.keys()]) {
    if (state.players.get(playerId)?.pendingDefeatInterrupt) {
      declineDefeatInterrupt(state, cardDb, playerId, rng);
    }
    // The regional Spirit Spell window gets the same one-advancePhase lifetime as every other
    // reaction window here (owner ruling, 2026-07-26). It previously had NO lifetime at all --
    // only a matching Spirit Spell being played ever cleared it -- so a player holding none
    // carried an open window for the rest of the game. The UI blocks Next Phase while a player
    // has a PLAYABLE Spirit Spell, so anything still open at this point was genuinely
    // unanswerable and is safe to close.
    closeSpiritSpellWindow(state, playerId);
  }
  // P2 (2026-07-12): resolve a pending turn-transition pause before anything else -- `state.phase`
  // is stale (whatever it was before the turn ended) while either flag is set, so none of the
  // normal phase-advance logic below should run yet. Each call here resolves exactly one pause;
  // the caller (UI) just keeps calling advancePhase the same way it always has.
  if (state.turnHandoffPending) {
    state.turnHandoffPending = false;
    completeTurnHandoff(state, cardDb, rng);
    return;
  }
  if (state.energizePending) {
    resolveEnergizePending(state, cardDb, rng);
    return;
  }
  if (state.phase === 'attack' && !_skippingPhase) {
    // "At the end of your Attack Step" text (e.g. Porphin's Bolster) -- fires here, right as we
    // leave a genuinely-played attack phase.
    const player = getActivePlayer(state);
    const attackStepEndCards: CardInstance[] = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
    for (const card of attackStepEndCards) {
      const def = cardDb.get(card.definitionKey);
      for (const effect of effectsFor(state, cardDb, card)) {
        if (!effect.onOwnAttackStepEnd) continue;
        effect.onOwnAttackStepEnd(state, cardDb, card, rng);
        logEvent(state, 'onOwnAttackStepEndHookFired', { cardName: def!.name, instanceId: card.instanceId });
      }
    }
    // registry.ts's onAnyAttackStepEnd (Showdown) -- "at the end of EACH player's Attack Step".
    // A separate pass over ALL players (plus attachedCards, which the loop above cannot see),
    // deliberately not a widening of onOwnAttackStepEnd; see that hook's own doc comment.
    // Snapshotted first: a hook body may discard its own card, and mutating a live board array
    // mid-iteration would skip entries.
    const everyCard: CardInstance[] = [];
    for (const p of state.players.values()) {
      for (const c of p.inPlay) everyCard.push(c, ...activeAttachedCards(cardDb, c));
      if (p.activeMagi) everyCard.push(p.activeMagi, ...activeAttachedCards(cardDb, p.activeMagi));
    }
    for (const card of everyCard) {
      const def = cardDb.get(card.definitionKey);
      for (const effect of effectsFor(state, cardDb, card)) {
        if (!effect.onAnyAttackStepEnd) continue;
        effect.onAnyAttackStepEnd(state, cardDb, card, player.playerId);
        logEvent(state, 'onAnyAttackStepEndHookFired', { cardName: def!.name, instanceId: card.instanceId });
      }
    }
  }
  // Shaper's Apprentice's Dream Twist (region-audit follow-up, 2026-07-24): scheduledEnergizeStepDiscards
  // -- "at the end of your next Energize Step," a genuinely future-turn-scheduled trigger (see that
  // field's own doc comment in types/state.ts). Same "fire right as we leave a genuinely-played
  // phase" placement as the Attack-Step-end block just above, just for 'energize' instead of
  // 'attack' -- Energize is never skipped, so no `_skippingPhase` guard is needed here.
  if (state.phase === 'energize' && state.scheduledEnergizeStepDiscards.length > 0) {
    const player = getActivePlayer(state);
    const due = state.scheduledEnergizeStepDiscards.filter((d) => d.playerId === player.playerId && d.dueTurnNumber === state.turnNumber);
    if (due.length > 0) {
      state.scheduledEnergizeStepDiscards = state.scheduledEnergizeStepDiscards.filter(
        (d) => !(d.playerId === player.playerId && d.dueTurnNumber === state.turnNumber)
      );
      for (const d of due) {
        if (player.inPlay.some((c) => c.instanceId === d.instanceId)) {
          discardFromPlay(state, cardDb, player, d.instanceId, player.playerId, 'effect', rng);
        }
      }
    }
  }
  const currentIndex = PHASE_ORDER.indexOf(state.phase);
  const isLastPhase = currentIndex === PHASE_ORDER.length - 1;
  if (isLastPhase) {
    // Draw-step pause (Bucket D Batch B closure 2026-08-13: Tomorrow's Jewel's Lore). If any
    // in-play card's `onOwnDrawStepComplete` hook set `state.drawPending = true` this Draw
    // phase, refuse to hand off the turn until the pending choice is resolved (or explicitly
    // declined by the resolver clearing the flag). Same "pause point" pattern as
    // `energizePending`/`turnHandoffPending`.
    if (state.drawPending) return;
    runEndOfTurnHooks(state, cardDb, rng);
    return;
  }
  state.phase = PHASE_ORDER[currentIndex + 1]!;
  if (state.phase === 'attack' && state.skipAttackPhaseThisTurn) {
    state.skipAttackPhaseThisTurn = false; // single-event, consumed now
    logEvent(state, 'attackPhaseSkipped', { playerId: state.activePlayerId });
    advancePhase(state, cardDb, rng, true); // straight through to the next phase, never genuinely entered
    return;
  }
  runPhaseEntryActions(state, cardDb, rng);
}

function runPhaseEntryActions(state: GameState, cardDb: CardDatabase, rng: Rng): void {
  const player = getActivePlayer(state);
  if (state.phase === 'energize') {
    runEnergizePhase(state, cardDb, player, rng);
  } else if (state.phase === 'draw') {
    runDrawPhase(state, cardDb, player, rng);
  } else if (state.phase === 'playNewCreatures') {
    runPlayCreaturesPhaseStart(state, cardDb, player);
  } else if (state.phase === 'attack') {
    runAttackStepStart(state, cardDb, player, rng);
  }
}

/** registry.ts's onOwnAttackStepStart (task #42, 2026-07-17: Mountain Trulb's Rolling Stone) --
 *  scans the active player's HAND, not inPlay/activeMagi like every other phase-start broadcast,
 *  since this hook exists specifically for a card offering itself an alternate play timing while
 *  still sitting in hand (see the hook's own doc comment in registry.ts). */
function runAttackStepStart(state: GameState, cardDb: CardDatabase, player: PlayerState, rng: Rng): void {
  for (const card of player.hand) {
    for (const effect of effectsFor(state, cardDb, card)) {
      effect.onOwnAttackStepStart?.(state, cardDb, card);
    }
  }
  // registry.ts's onOwnAttackStepBegin (task #714, 2026-08-11: Moga Fang Necklace's Roar) -- the
  // opposite-boundary sibling of onOwnAttackStepEnd (advancePhase, below), same "scan the active
  // player's own Magi + inPlay" shape.
  const attackStepBeginCards: CardInstance[] = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
  for (const card of attackStepBeginCards) {
    const def = cardDb.get(card.definitionKey);
    for (const effect of effectsFor(state, cardDb, card)) {
      if (!effect.onOwnAttackStepBegin) continue;
      effect.onOwnAttackStepBegin(state, cardDb, card, rng);
      logEvent(state, 'onOwnAttackStepBeginHookFired', { cardName: def!.name, instanceId: card.instanceId });
    }
  }
  // ReactiveWindow 'opponentAttackStepBegan' (Paradwyn Spell pass, 2026-07-25: Snare -- "Play Snare
  // at the beginning of an opponent's Attack step"). Opened unconditionally on entering the Attack
  // step, naming the NON-active player as the reactor -- same single-slot, self-overwriting
  // convention as the other two window kinds, and consumed through the same generic reactsToWindow
  // plumbing (no new UI needed). Single opponent, matching this codebase's 2-player-primary scope.
  const [opponent] = getOpponents(state, player.playerId);
  if (opponent) {
    state.reactiveWindow = {
      kind: 'opponentAttackStepBegan',
      reactingPlayerId: opponent.playerId,
      actingPlayerId: player.playerId,
    };
  }
}

/** registry.ts's onOwnPlayCreaturesStepStart (task #35, 2026-07-16: The Real Qwade's Leech) --
 *  same "scan the active player's own Magi + inPlay" shape as runStartOfTurnHooks' onOwnTurnStart
 *  broadcast, but fired at THIS phase's entry specifically rather than once at the top of the turn. */
function runPlayCreaturesPhaseStart(state: GameState, cardDb: CardDatabase, player: PlayerState): void {
  const candidates: CardInstance[] = player.activeMagi ? [player.activeMagi, ...player.inPlay] : [...player.inPlay];
  for (const card of candidates) {
    for (const effect of effectsFor(state, cardDb, card)) {
      effect.onOwnPlayCreaturesStepStart?.(state, cardDb, card);
    }
  }
}

/**
 * Turn-end half of the old monolithic endTurn, split out for P2 (2026-07-12): fires
 * onOwnTurnEnd/onOpponentTurnEnd, sweeps DISCARD_AT_END_OF_TURN, then sets
 * `state.turnHandoffPending` instead of immediately switching the active player and starting the
 * next turn -- see GameState.turnHandoffPending's doc comment for why.
 */
function runEndOfTurnHooks(state: GameState, cardDb: CardDatabase, rng: Rng): void {
  // "At the end of your turn" text (e.g. Tunneler's Boots' Strengthen, Strag's Ring's Purity,
  // d'Jarvish's Strengthen) -- fires before the DISCARD_AT_END_OF_TURN sweep and before the
  // active player switches, so "the end of the turn" is still THIS turn's end.
  const player = getActivePlayer(state);
  // CardInstance.attackedLastOwnTurn/usedPowerLastOwnTurn (Sawgrass/Pody/Mobis' Avenger/K'teeb
  // Thumper) -- snapshotted HERE, at the true end of this player's own turn, not at the start of
  // their NEXT own turn (bug fix 2026-08-09, live-playtest report). The old start-of-turn snapshot
  // (see the comment where attackedThisTurn resets below) left the flag stale for one full extra
  // opposing turn: a Creature that attacked in turn N kept reporting ITS turn-(N-2) status all the
  // way through the opponent's very next turn (N+1), since nothing refreshed it until this
  // player's own beginTurn ran again at N+2 -- exactly backwards from "attacked on its
  // controller's LAST turn." Snapshotting here instead means the flag is already correct the
  // instant the opponent's next turn begins. attackedThisTurn/usedPowerNames themselves are
  // untouched here -- they still reset at the START of this player's own next turn
  // (runStartOfTurnHooks), same as before; only the snapshot's timing moved.
  for (const card of player.inPlay) {
    card.attackedLastOwnTurn = card.attackedThisTurn;
    card.usedPowerLastOwnTurn = card.usedPowerNames.size > 0;
  }
  if (player.activeMagi) {
    player.activeMagi.usedPowerLastOwnTurn = player.activeMagi.usedPowerNames.size > 0;
  }
  // Mud Bubble (Bograth Spell pass, 2026-07-20): "if you play one or more copies of that Creature
  // this turn, draw a card at the end of your turn" -- PlayerState.pendingMudBubbleWatch's own doc
  // comment explains why this is a direct player-level check rather than a card-instance hook (Mud
  // Bubble itself is long since sitting in the discard pile by this point). Checked and cleared
  // here, before the per-card onOwnTurnEnd broadcast below, same "this turn only" single-event
  // convention as every other pending-marker field.
  if (player.pendingMudBubbleWatch && player.pendingMudBubbleWatch.turnNumber === state.turnNumber) {
    if (playedCardNameThisTurn(state, player.playerId, player.pendingMudBubbleWatch.cardName)) {
      drawCards(state, cardDb, player, 1);
    }
  }
  player.pendingMudBubbleWatch = null;
  // IN-PLAY SCOPE ONLY. `defeatedMagi` was folded in here on 2026-07-12 for Trygar's Avenger, on
  // the reasoning that it was "safe to scan unconditionally: only a card that explicitly registers
  // onOwnTurnEnd/onOpponentTurnEnd AND self-guards its own pending state does anything." That was
  // wrong, and a playtest report (2026-07-27) caught it: Voda's Deluge is an UNCONDITIONAL standing
  // passive ("at the end of your turn, add four energy to the Creature with the most energy"), so
  // it has no pending state to self-guard -- it just kept firing every turn forever after Voda was
  // defeated and replaced. 11 of the 12 Magi that register onOwnTurnEnd are standing passives of
  // that kind; only Trygar wants the post-defeat call.
  //
  // Fixed by splitting the hook by ZONE rather than asking every card to guard itself -- the same
  // remedy as onAnyCardDrawn/onAnyCardDrawnWhileInHand (task #47) and
  // onMagiRevealed/onMagiRevealedWhileInDiscardPile. A standing passive should stop when its card
  // leaves play, and that should be the DEFAULT, not something each card has to remember.
  const turnEndCards: CardInstance[] = [...(player.activeMagi ? [player.activeMagi] : []), ...player.inPlay];
  for (const card of turnEndCards) {
    const def = cardDb.get(card.definitionKey);
    for (const effect of effectsFor(state, cardDb, card)) {
      if (!effect.onOwnTurnEnd) continue;
      effect.onOwnTurnEnd(state, cardDb, card, rng);
      logEvent(state, 'onOwnTurnEndHookFired', { cardName: def!.name, instanceId: card.instanceId });
    }
  }
  // The DEFEATED-Magi counterpart, for a delayed consequence of one's own defeat that has to
  // resolve at a turn boundary (Trygar's Avenger, the sole consumer). Deliberately a separate hook
  // so registering an ordinary end-of-turn passive can never accidentally outlive its card.
  for (const card of player.defeatedMagi) {
    const def = cardDb.get(card.definitionKey);
    for (const effect of effectsFor(state, cardDb, card)) {
      if (!effect.onOwnTurnEndWhileDefeated) continue;
      effect.onOwnTurnEndWhileDefeated(state, cardDb, card, rng);
      logEvent(state, 'onOwnTurnEndHookFired', { cardName: def!.name, instanceId: card.instanceId });
    }
  }
  // "At the end of each OPPONENT's turn" text (e.g. Crystal Saris' Regenerate, Crystal Twinklet's
  // Dream Charge) -- same moment, scanning the OTHER side's Magi + inPlay, with the same
  // defeated-Magi split as above.
  for (const opponent of getOpponents(state, state.activePlayerId)) {
    const opponentTurnEndCards: CardInstance[] = [
      ...(opponent.activeMagi ? [opponent.activeMagi] : []),
      ...opponent.inPlay,
    ];
    for (const card of opponentTurnEndCards) {
      const def = cardDb.get(card.definitionKey);
      for (const effect of effectsFor(state, cardDb, card)) {
        if (!effect.onOpponentTurnEnd) continue;
        effect.onOpponentTurnEnd(state, cardDb, card, rng);
        logEvent(state, 'onOpponentTurnEndHookFired', { cardName: def!.name, instanceId: card.instanceId });
      }
    }
    for (const card of opponent.defeatedMagi) {
      const def = cardDb.get(card.definitionKey);
      for (const effect of effectsFor(state, cardDb, card)) {
        if (!effect.onOpponentTurnEndWhileDefeated) continue;
        effect.onOpponentTurnEndWhileDefeated(state, cardDb, card, rng);
        logEvent(state, 'onOpponentTurnEndHookFired', { cardName: def!.name, instanceId: card.instanceId });
      }
    }
  }
  sweepDiscardAtEndOfTurn(state, cardDb);
  sweepReturnToHandAtEndOfTurn(state, cardDb);
  sweepRestoreMagiAtEndOfTurn(state, cardDb);
  sweepMustAttackOrDiscard(state, cardDb);
  // Tony At A Con's Sleep Dep (Category D SIXTH item, 2026-08-12): "at the end of your turn, if
  // you just took two turns in a row, defeat your Magi. Sleep Dep cannot be prevented or
  // canceled." Checked here as a DIRECT engine call rather than a card-effect hook: `defeatMagi`
  // is called straight (not via checkMagiDefeats), so Spirit of Rayje's pre-defeat interrupt --
  // which only fires from checkMagiDefeats's zero-energy path -- never gets offered (owner Q5,
  // 2026-08-12). And this check does not go through `effectsFor`, so Rayje's Belt's Lockdown of
  // Sleep Dep by name (which nulls effectsFor's return for cards whose printed effect names are
  // locked) cannot suppress it either. `justTookAdditionalTurn` is cleared unconditionally right
  // after -- the flag only marks THIS specific turn, and a Sleep-Dep-caused defeat still consumes
  // the flag so a subsequent extra turn from a chained Caffeine! (owner Q4) trips its own Sleep
  // Dep on the freshly-revealed replacement Magi rather than a stale one.
  if (player.justTookAdditionalTurn && player.activeMagi?.hasSleepDep) {
    logEvent(state, 'sleepDepTriggered', {
      playerId: player.playerId,
      magiInstanceId: player.activeMagi.instanceId,
    });
    defeatMagi(state, cardDb, player, rng);
    checkForDefeats(state, cardDb, undefined, rng);
  }
  player.justTookAdditionalTurn = false;
  state.turnHandoffPending = true;
}

/** Resolves `state.turnHandoffPending` (P2, 2026-07-12): switches the active player and runs the
 *  new active player's start-of-turn hooks, leaving `state.energizePending` set for the NEXT
 *  advancePhase call to resolve. Called by `advancePhase` -- the actual pause point.
 *
 *  Tony At A Con's Caffeine! (Category D SIXTH item, 2026-08-12): if the just-ending player
 *  carries a positive `pendingExtraTurns` count, we DECREMENT it, set
 *  `justTookAdditionalTurn = true` for their upcoming extra turn (Sleep Dep's own trigger reads
 *  this in `runEndOfTurnHooks` below), and SKIP the active-player rotation -- the same player's
 *  `runStartOfTurnHooks` fires again. See `PlayerState.pendingExtraTurns`/
 *  `justTookAdditionalTurn` doc comments for the field-level contract, and `tonyAtACon.ts` for
 *  the printed-text-to-mechanics mapping. */
function completeTurnHandoff(state: GameState, cardDb: CardDatabase, rng: Rng): void {
  const endingPlayer = getActivePlayer(state);
  if (endingPlayer.pendingExtraTurns > 0) {
    endingPlayer.pendingExtraTurns -= 1;
    endingPlayer.justTookAdditionalTurn = true;
    logEvent(state, 'extraTurnGranted', { playerId: endingPlayer.playerId });
    runStartOfTurnHooks(state, cardDb, rng);
    return;
  }
  const currentIndex = state.turnOrder.indexOf(state.activePlayerId);
  const nextIndex = (currentIndex + 1) % state.turnOrder.length;
  state.activePlayerId = getPlayer(state, state.turnOrder[nextIndex]!).playerId;
  runStartOfTurnHooks(state, cardDb, rng);
}

/**
 * Swirling Orshaa's Morph, Effect-half turn-boundary bucket (2026-07-24) -- previews whether a
 * reactive Morph offer should appear before the NEXT `advancePhase` call runs a turn-boundary
 * sweep (Gorran/Orathan Amulet/Olum Mystic's `onOwnTurnEnd`/`onOpponentTurnEnd`, Ulk's
 * `onOwnTurnStart`). Mirrors `advancePhase`'s own priority order exactly (`turnHandoffPending`
 * checked first, then the "last phase" check) so this always agrees with which sweep the NEXT
 * call will actually run:
 *  - `state.turnHandoffPending` set -> the next call resolves `completeTurnHandoff`, which fires
 *    `onOwnTurnStart` for the player about to become active (Ulk's Strengthen).
 *  - otherwise, if the active player is on the last phase (`draw`) and not already paused on
 *    `energizePending` -> the next call runs `runEndOfTurnHooks`, firing `onOwnTurnEnd` for the
 *    active player and `onOpponentTurnEnd` for every opponent (Gorran/Orathan Amulet's own-turn
 *    sweep, Olum Mystic's immunity pool, checked from either side).
 * Any other phase/pause state returns `undefined` -- no turn-boundary sweep is imminent.
 * Deliberately scans only `inPlay`/`activeMagi` (not `defeatedMagi`, unlike the real sweeps' own
 * broader candidate list for Trygar's Avenger) -- none of the 4 registered
 * `turnBoundaryCreatureTypes` files apply to a defeated Magi. `actorPlayerId`/`sourceDef`/
 * `sourceInstanceId` passed to `offersIdentityOverrideBeforeChoices` are filled from the first
 * matching trigger card found, purely for signature symmetry with the Power/Spell call sites --
 * see that hook's own doc comment for why this is safe (Swirling Orshaa, the only registrant,
 * ignores all three for every `abilityKind`).
 */
export function previewIdentityOverrideOffersForTurnBoundary(
  state: GameState,
  cardDb: CardDatabase
):
  | { pool: CardInstance[]; specifiedRegions: string[]; specifiedCreatureTypes: string[]; triggerSourceInstanceId: string }
  | undefined {
  const specifiedRegions = new Set<string>();
  const specifiedCreatureTypes = new Set<string>();
  let triggerSourceInstanceId: string | undefined;
  let triggerDef: CardDefinition | undefined;

  function collect(candidates: CardInstance[], hookName: 'onOwnTurnEnd' | 'onOpponentTurnEnd' | 'onOwnTurnStart', playerId: PlayerId): void {
    for (const card of candidates) {
      const def = cardDb.get(card.definitionKey);
      for (const effect of effectsFor(state, cardDb, card)) {
        if (!effect[hookName]) continue;
        const types = effect.turnBoundaryCreatureTypes?.(state, cardDb, playerId, card.instanceId) ?? [];
        const regions = effect.turnBoundaryRegions?.(state, cardDb, playerId, card.instanceId) ?? [];
        if (types.length === 0 && regions.length === 0) continue;
        if (triggerSourceInstanceId === undefined) {
          triggerSourceInstanceId = card.instanceId;
          triggerDef = def;
        }
        types.forEach((t) => specifiedCreatureTypes.add(t));
        regions.forEach((r) => specifiedRegions.add(r));
      }
    }
  }

  if (state.turnHandoffPending) {
    const currentIndex = state.turnOrder.indexOf(state.activePlayerId);
    const nextIndex = (currentIndex + 1) % state.turnOrder.length;
    const nextPlayer = getPlayer(state, state.turnOrder[nextIndex]!);
    const candidates: CardInstance[] = nextPlayer.activeMagi ? [...nextPlayer.inPlay, nextPlayer.activeMagi] : [...nextPlayer.inPlay];
    collect(candidates, 'onOwnTurnStart', nextPlayer.playerId);
  } else if (!state.energizePending) {
    const currentIndex = PHASE_ORDER.indexOf(state.phase);
    if (currentIndex === PHASE_ORDER.length - 1) {
      const player = getActivePlayer(state);
      const ownCandidates: CardInstance[] = player.activeMagi ? [...player.inPlay, player.activeMagi] : [...player.inPlay];
      collect(ownCandidates, 'onOwnTurnEnd', player.playerId);
      for (const opponent of getOpponents(state, player.playerId)) {
        const opponentCandidates: CardInstance[] = opponent.activeMagi ? [...opponent.inPlay, opponent.activeMagi] : [...opponent.inPlay];
        collect(opponentCandidates, 'onOpponentTurnEnd', opponent.playerId);
      }
    }
  }

  if (triggerSourceInstanceId === undefined || !triggerDef) return undefined;

  const regionsArr = [...specifiedRegions];
  const typesArr = [...specifiedCreatureTypes];

  const pool: CardInstance[] = [];
  for (const p of state.players.values()) {
    const candidates: CardInstance[] = p.activeMagi ? [...p.inPlay, p.activeMagi] : [...p.inPlay];
    for (const candidate of candidates) {
      for (const effect of effectsFor(state, cardDb, candidate)) {
        if (
          effect.offersIdentityOverrideBeforeChoices?.(
            state,
            cardDb,
            candidate,
            state.activePlayerId,
            'turnBoundary',
            triggerDef,
            triggerSourceInstanceId,
            regionsArr,
            typesArr
          )
        ) {
          pool.push(candidate);
          break;
        }
      }
    }
  }
  if (pool.length === 0) return undefined;
  return { pool, specifiedRegions: regionsArr, specifiedCreatureTypes: typesArr, triggerSourceInstanceId };
}

/**
 * Applies a confirmed turn-boundary Morph offer -- same shape as power.ts's
 * `confirmIdentityOverrideForPower`, but computes `expiresAfterTurnNumber` itself instead of
 * always passing the current `state.turnNumber`: when `state.turnHandoffPending` is set,
 * confirmation is happening BEFORE `runStartOfTurnHooks` increments `state.turnNumber` for the
 * upcoming turn (see `resolveIdentityOverride`'s own doc comment in registry.ts for why passing
 * the current, pre-increment number would make the override expire before the very hook
 * (`onOwnTurnStart`) it was meant to enable ever runs).
 */
export function confirmIdentityOverrideForTurnBoundary(
  state: GameState,
  cardDb: CardDatabase,
  reactorInstanceId: string,
  kind: 'region' | 'creatureType',
  value: string
): void {
  const reactor = findCreatureOrMagiById(state, reactorInstanceId);
  if (!reactor) return;
  const reactorDef = cardDb.get(reactor.definitionKey);
  const reactorEffect = reactorDef && getCardEffectByName(reactorDef.name);
  const expiresAfterTurnNumber = state.turnHandoffPending ? state.turnNumber + 1 : state.turnNumber;
  logEvent(state, 'identityOverrideConfirmed', { reactorInstanceId, kind, value });
  reactorEffect?.resolveIdentityOverride?.(state, cardDb, reactor, kind, value, expiresAfterTurnNumber);
}

/** Discards every card tagged DISCARD_AT_END_OF_TURN (e.g. Bronn's Snowball, Poad Innkeeper's
 *  Party: "Discard the Creature at the end of the turn") -- checked generically, both players,
 *  same "tag applied by the card, consumed by generic engine code" pattern as STALKED/
 *  CANNOT_ATTACK. Runs before the active player switches, so "the end of the turn" is still THIS
 *  turn's end, not the next player's. */
function sweepDiscardAtEndOfTurn(state: GameState, cardDb: CardDatabase): void {
  for (const player of state.players.values()) {
    const toDiscard = player.inPlay.filter((c) => c.tags.has(DISCARD_AT_END_OF_TURN));
    for (const card of toDiscard) {
      const removed = removeFromZone(player, 'inPlay', card.instanceId);
      moveToDiscardPile(state, player, removed);
      releaseAttachedOnLeavePlay(state, cardDb, removed); // task #329
      logEvent(state, 'endOfTurnDiscard', { instanceId: card.instanceId, name: cardDb.get(card.definitionKey)?.name });
    }
  }
}

/** Resolves durationTags.ts's MUST_ATTACK_THIS_TURN_OR_DISCARD (Cry of Thunder, task #50,
 *  2026-07-19): discards every tagged Creature that never attacked this turn, and always clears the
 *  tag off survivors so it doesn't linger into a future turn -- same "generic sweep, tag applied by
 *  the card" shape as sweepDiscardAtEndOfTurn just above, except CONDITIONAL on attackedThisTurn. */
function sweepMustAttackOrDiscard(state: GameState, cardDb: CardDatabase): void {
  for (const player of state.players.values()) {
    const tagged = player.inPlay.filter((c) => c.tags.has(MUST_ATTACK_THIS_TURN_OR_DISCARD));
    for (const card of tagged) {
      removePermanentTag(card, MUST_ATTACK_THIS_TURN_OR_DISCARD);
      if (card.attackedThisTurn) continue;
      const removed = removeFromZone(player, 'inPlay', card.instanceId);
      moveToDiscardPile(state, player, removed);
      releaseAttachedOnLeavePlay(state, cardDb, removed); // task #329
      logEvent(state, 'endOfTurnDiscard', { instanceId: card.instanceId, name: cardDb.get(card.definitionKey)?.name });
    }
  }
}

/** Returns every card tagged RETURN_TO_HAND_AT_END_OF_TURN to its owner's hand, energy discarded
 *  (e.g. Alaban Kit's Undream) -- same generic sweep shape as sweepDiscardAtEndOfTurn, just to
 *  hand instead of the discard pile. `returnToHand` already nulls currentEnergy. Widened (task
 *  #41, 2026-07-17: Grakanden's Grounding / Anastasia's Scream) to also check each player's
 *  `discardPile`, not just `inPlay` -- a Spell tagged for delayed return already fully played out
 *  and landed in the discard pile (Spells have no in-play presence in this engine at all), so the
 *  original in-play-only scan would never find it. */
/** Restores every Magi tagged RESTORE_MAGI_AT_END_OF_TURN to its printed starting energy (Aritex's
 *  Heal, task #576) -- same generic "tag applied by a card, consumed by engine code at end of turn"
 *  shape as the two sweeps above. Reads `printedStartingEnergy`, not the effective one: a Magi's
 *  starting energy is its printed cost and no board-wide modifier targets Magi (task #568's split).
 *  The tag is removed whether or not the restore changes anything, so it can never carry into a
 *  later turn. */
function sweepRestoreMagiAtEndOfTurn(state: GameState, cardDb: CardDatabase): void {
  for (const player of state.players.values()) {
    const magi = player.activeMagi;
    if (!magi || !magi.tags.has(RESTORE_MAGI_AT_END_OF_TURN)) continue;
    removePermanentTag(magi, RESTORE_MAGI_AT_END_OF_TURN);
    restoreEnergy(state, cardDb, magi, printedStartingEnergy(cardDb, magi.definitionKey));
    logEvent(state, 'endOfTurnMagiRestored', { instanceId: magi.instanceId, name: cardDb.get(magi.definitionKey)?.name });
  }
}

function sweepReturnToHandAtEndOfTurn(state: GameState, cardDb: CardDatabase): void {
  for (const player of state.players.values()) {
    const toReturn = player.inPlay.filter((c) => c.tags.has(RETURN_TO_HAND_AT_END_OF_TURN));
    for (const card of toReturn) {
      returnToHand(state, cardDb, player, card.instanceId);
      logEvent(state, 'endOfTurnReturnToHand', { instanceId: card.instanceId, name: cardDb.get(card.definitionKey)?.name });
    }
    const toReturnFromDiscard = player.discardPile.filter((c) => c.tags.has(RETURN_TO_HAND_AT_END_OF_TURN));
    for (const card of toReturnFromDiscard) {
      returnToHand(state, cardDb, player, card.instanceId, 'discardPile');
      logEvent(state, 'endOfTurnReturnToHand', { instanceId: card.instanceId, name: cardDb.get(card.definitionKey)?.name });
    }
  }
}
