// Fog Hyren -- both printed clauses:
//   "Obscure Knowledge: Draw two cards, then discard a card if your Magi is not Bograth."
//   handDiscardCost's count:'any' offers the picker; resolvePower only actually discards if the
//   Bograth condition holds, ignoring any choice made if it doesn't.
//   "Dreamwarp: As you play Fog Hyren, increase or decrease its starting energy by up to two,
//   until the end of the turn." (registry.ts's dreamwarpRange.)

import { registerCardEffect } from './registry.js';
import { drawCards, discardFromHand } from '../effects.js';

registerCardEffect('Fog Hyren', {
  handDiscardCost: { count: 'any' },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Obscure Knowledge') return;
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 2);

    const magi = ctx.controllingPlayer.activeMagi;
    const magiDef = magi ? ctx.cardDb.get(magi.definitionKey) : undefined;
    const isBograth = magiDef?.regions.includes('Bograth') ?? false;
    if (isBograth) return;

    const id = (ctx.chosenHandCardIds ?? []).find((cid) => ctx.controllingPlayer.hand.some((c) => c.instanceId === cid));
    if (id) discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, [id], undefined, ctx.rng);
  },
  dreamwarpRange: () => 2,
});
