// Smoke Xyx -- "Suffocate (2): Choose any one Creature in play. Until the start of your next turn,
// the chosen Creature removes no energy from attacking Creatures while it is defending." A
// targeted, turn-scoped grant (same shape as Grej's Toughen) -- a new SUFFOCATED duration tag,
// consumed generically by Smoke Xyx's own onAttack hook (broadcast-checked, not scoped to Smoke
// Xyx being a combat participant).

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addDurationTag, hasDurationTag, beginningOfNextOwnTurnNumber } from '../durationTags.js';

const SUFFOCATED = 'smokeXyxSuffocated';

registerCardEffect('Smoke Xyx', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Suffocate') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    addDurationTag(ctx.state, ctx.cardDb, target, SUFFOCATED, beginningOfNextOwnTurnNumber(ctx.state));
  },
  onAttack: (ctx, self) => {
    if (ctx.defender && hasDurationTag(ctx.defender, SUFFOCATED)) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = 0;
    }
  },
});
