// Ring of Secrets -- "Tinker: Whenever you play a Relic, choose any one Creature in play. Add one
// energy to the chosen Creature. You cannot choose a Creature more than once per turn with Tinker."
// The Tinker mechanism (real pending choice + the shared once-per-turn-per-Creature dedup) lives in
// tinker.ts and is reused by Rayje's Construct; this file just wires it with its own pending tag.
//
// Real choice (task #40-1, 2026-07-17, player-choice-default retrofit): replaces the earlier
// "first eligible Creature (any player's) not yet tinkered with" auto-pick with a real pending
// choice (registry.ts's pendingTargetChoice/resolveTargetChoice).

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { applyTinker, tinkerPool } from './tinker.js';

const TINKER_PENDING = 'ringOfSecretsTinkerPending';

registerCardEffect('Ring of Secrets', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;
    if (tinkerPool(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, TINKER_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(TINKER_PENDING)) return undefined;
    const pool = tinkerPool(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Ring of Secrets' Tinker: choose a Creature to add 1 energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, TINKER_PENDING);
    applyTinker(state, cardDb, chosenInstanceId);
  },
});
