// Frost Hyren -- both printed clauses:
//   "Frostbite": "Whenever any player plays a Relic, discard one energy from each of that
//   player's Creatures." Broadcast onPlay reactor, fires regardless of which side played the
//   Relic.
//   Unnamed passive: "While Frost Hyren is in play, all Creatures in play are frozen; Powers on
//   frozen cards cost one additional energy to use." Built via task #26's `grantsFrozenTo`
//   broadcast (2026-07-14) -- the "Powers cost +1" half is already generic (power.ts's
//   isLegalPowerUse), so registering the grant alone is enough for both clauses.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { creaturesControlledBy, allCreaturesInPlay } from '../targeting.js';

registerCardEffect('Frost Hyren', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Only Frostbite is mapped; the
  // unnamed Creature-freeze passive (grantsFrozenTo) has no name to key on and falls through
  // to whole-card grant.
  effectHooks: {
    Frostbite: ['onPlay'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;

    for (const creature of creaturesControlledBy(state, cardDb, played.controllerId)) {
      discardEnergy(state, cardDb, creature, 1, 'effect', self.controllerId);
    }
  },
  grantsFrozenTo: (state, cardDb, self, target) =>
    allCreaturesInPlay(state, cardDb).some((c) => c.instanceId === target.instanceId),
});
