// Ullig -- "Fearless: When Ullig's last Creature is discarded from play by an opposing card, add
// four energy to Ullig." "By an opposing card" retrofitted (task #32, 2026-07-16) from the old
// `state.activePlayerId === self.controllerId` heuristic to the real `causedByPlayerId` param now
// available on `onCardDiscardedFromPlay`. "Last Creature" is checked AFTER the discard has already
// happened (onCardDiscardedFromPlay fires post-move), so an empty creaturesControlledBy pool at
// this point correctly means "that was the last one."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';

registerCardEffect('Ullig', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discardedOwnerId !== self.controllerId) return;
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Creature') return;
    if (causedByPlayerId === undefined || causedByPlayerId === self.controllerId) return;
    if (creaturesControlledBy(state, cardDb, self.controllerId).length > 0) return;

    addEnergy(state, cardDb, self, 4, 'effect');
  },
});
