// Flourish (Spell, Paradwyn, cost 3) -- "Until the end of your next turn, all Creatures with
// starting energy greater than two cost two less energy to play, to a minimum of two." No
// targeting -- sets GameState.flourishUntilTurn (own doc comment in types/state.ts), checked
// directly in play.ts's cost computation for either player's Creature plays.

import { registerCardEffect } from './registry.js';
import { nextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Flourish', {
  resolveSpell: (ctx) => {
    ctx.state.flourishUntilTurn = nextOwnTurnNumber(ctx.state);
  },
});
