// Arbolit -- "Healing Flame: Choose any one Creature in play. Discard Arbolit from play. Add two
// energy to the chosen Creature." Self-discard as part of using its own Power (the pattern the
// project owner flagged specifically) -- unlike Thunder Vashp, there's no ambiguity here about
// double-processing since the target isn't required to be Arbolit itself, but nothing prevents
// choosing Arbolit as its own target either; if so, the "add energy" just lands on a card that's
// already sitting in the discard pile -- harmless, not worth special-casing.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy, discardFromPlay } from '../effects.js';

registerCardEffect('Arbolit', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Healing Flame') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
  },
});
