// Gogor -- "Gravel Storm (4): Roll one die. Discard energy equal to the die roll from each
// Creature in play. Gravel Storm does not affect burrowed Creatures." No target. The burrowed
// exemption is now live (BURROWED shipped 2026-07-08, see durationTags.ts's isBurrowed) -- this
// comment previously said it was moot pending a card that grants burrowed, which was stale.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { isBurrowed } from '../durationTags.js';

registerCardEffect('Gogor', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Gravel Storm') return;
    requestDieRoll(ctx.state, ctx.cardDb, ctx.source, ctx.source.controllerId, 6, 'gogor:gravelStorm', {}, ctx.rng);
  },
});

registerRollConsumer('gogor:gravelStorm', (state, cardDb, _source, _payload, finalRoll, rng) => {
  for (const creature of allCreaturesInPlay(state, cardDb)) {
    if (isBurrowed(state, cardDb, creature)) continue;
    discardEnergy(state, cardDb, creature, finalRoll, undefined, undefined, rng);
  }
});
