// Bikneets -- "Shield (2): Choose any one Naroom Creature in play. Discard Bikneets from play. The
// chosen Creature loses no energy from opponents' attacks, Spells or Powers until the beginning of
// your next turn." Built task #45, 2026-07-18, the Naroom region pass. NOT full immunity forever --
// a bounded-duration TOTAL prevention from three specific sources, expiring via
// beginningOfNextOwnTurnNumber (Grej's Toughen precedent).
//
// The "attacks" half needs no new mechanism: durationTags.ts's NO_ENERGY_LOST_IN_ATTACKS (Vaal/
// Parmalag's Shield) turned out to ALREADY be a full block in combat.ts, not a bounded reduction --
// re-verified directly against combat.ts's attackerImmune/defenderImmune gating before building
// this, correcting an earlier scoping assumption. Only the "Powers" half needed a genuinely new
// tag (NO_ENERGY_LOST_FROM_OPPOSING_POWER, checked in effects.ts's discardEnergy) -- "Spells" is
// moot, Spells never execute in this engine.
//
// No controller restriction on the target pool ("Choose any one Naroom Creature in play," no
// "your" qualifier) -- same reading as Forest Hyren's Energy Transfer.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { addDurationTag, NO_ENERGY_LOST_IN_ATTACKS, NO_ENERGY_LOST_FROM_OPPOSING_POWER, beginningOfNextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Bikneets', {
  powerTargets: (state, cardDb) =>
    allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Naroom'))),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shield') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Naroom'))) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);
    const expiry = beginningOfNextOwnTurnNumber(ctx.state);
    addDurationTag(ctx.state, ctx.cardDb, target, NO_ENERGY_LOST_IN_ATTACKS, expiry, ctx.source.instanceId);
    addDurationTag(ctx.state, ctx.cardDb, target, NO_ENERGY_LOST_FROM_OPPOSING_POWER, expiry);
  },
  specifiedTargetRegions: () => ['Naroom'],
});
