// Ardonia -- "Relentless Hunt: At the end of each of your turns, all opposing stalked Creatures in
// play lose one energy."

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { opposingCreatures } from '../targeting.js';
import { hasDurationTag, STALKED } from '../durationTags.js';

registerCardEffect('Ardonia', {
  onOwnTurnEnd: (state, cardDb, self) => {
    for (const creature of opposingCreatures(state, cardDb, self.controllerId)) {
      if (hasDurationTag(creature, STALKED)) {
        discardEnergy(state, cardDb, creature, 1, 'effect');
      }
    }
  },
});
