// Bone Cragnoc -- "Frenzy" and "Invulnerability" are built here:
//   "At the beginning of your turn, if Bone Cragnoc is the largest Creature, add two energy to
//   it." Read as "largest in play, either side" (no "your"/"opposing" qualifier in the printed
//   text). Ties broken by array order, same as every other largest/smallest comparison in this
//   codebase.
//   "Invulnerability: This Creature loses one less energy in attacks." (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { applyInvulnerability } from './invulnerability.js';

registerCardEffect('Bone Cragnoc', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Frenzy owns onOwnTurnStart,
  // Invulnerability owns onAttack.
  effectHooks: {
    Frenzy: ['onOwnTurnStart'],
    Invulnerability: ['onAttack'],
  },
  onOwnTurnStart: (state, cardDb, self) => {
    const selfEnergy = self.currentEnergy ?? 0;
    const isLargest = allCreaturesInPlay(state, cardDb).every(
      (c) => c.instanceId === self.instanceId || (c.currentEnergy ?? 0) <= selfEnergy
    );
    if (!isLargest) return;
    addEnergy(state, cardDb, self, 2, 'effect');
  },
  onAttack: (ctx, self) => applyInvulnerability(ctx, self, 1),
});
