// V'ryle -- "Autumn Leaves: Your creatures energize on your draw step instead of your energize
// step." registry.ts's deferEnergizeToDraw, granted broadcast-style to every own Creature in
// play (including itself, since V'ryle is itself a Creature).

import { registerCardEffect } from './registry.js';

registerCardEffect("V'ryle", {
  deferEnergizeToDraw: (state, cardDb, candidate, self) => {
    if (candidate.controllerId !== self.controllerId) return false;
    return cardDb.get(candidate.definitionKey)?.card_type === 'Creature';
  },
});
