import type { CardInstance } from './types/instance.js';
import type { GameState, PlayerId, PlayerState } from './types/state.js';
import { getPlayer } from './types/state.js';
import { shuffle, type Rng } from './rng.js';

/** The zones that hold an ordered list of cards (activeMagi is a single-slot zone, handled separately). */
export type ListZone = 'deck' | 'magiQueue' | 'defeatedMagi' | 'hand' | 'discardPile' | 'inPlay';

export function removeFromZone(
  player: PlayerState,
  zone: ListZone,
  instanceId: string
): CardInstance {
  const list = player[zone];
  const index = list.findIndex((c) => c.instanceId === instanceId);
  if (index === -1) {
    throw new Error(`Card ${instanceId} not found in ${player.playerId}'s ${zone}`);
  }
  const [removed] = list.splice(index, 1);
  return removed!;
}

export function addToZone(
  player: PlayerState,
  zone: ListZone,
  instance: CardInstance,
  position: 'top' | 'bottom' = 'bottom'
): void {
  if (position === 'top') {
    player[zone].unshift(instance);
  } else {
    player[zone].push(instance);
  }
}

/**
 * Moves `card` into `player`'s discard pile, stamping CardInstance.discardedOnTurn with the
 * current turn number so "discarded THIS turn" card text (e.g. Chelon's Wash Ashore) can be
 * checked later -- the single choke point for every place a card enters a discard pile (explicit
 * discards via effects.ts, the automatic zero-energy defeat check in energy.ts, Spells
 * auto-discarding after use, and the handful of card-specific direct-push call sites this
 * replaced). Callers are still responsible for removing `card` from its PREVIOUS zone first (same
 * division of labor as addToZone) -- this only appends to discardPile and stamps the turn.
 */
export function moveToDiscardPile(
  state: GameState,
  player: PlayerState,
  card: CardInstance,
  cause?: 'zero-energy' | 'explicit',
  source?: 'combat' | 'power' | 'effect' | 'spell',
  causedByPlayerId?: PlayerId
): void {
  card.discardedOnTurn = state.turnNumber;
  card.discardedCause = cause;
  card.discardedSource = source;
  card.discardedByPlayerId = causedByPlayerId;
  // A card always goes to its OWNER's discard pile, never the current controller's. This only
  // differs for a control-stolen card (ownerId != the player whose zone it was in) -- the `player`
  // arg names the zone it was removed FROM, but the destination is always the owner. 2026-07-18 bug
  // audit: a controlled Creature discarded/defeated was landing in the thief's pile.
  const owner = state.players.get(card.ownerId) ?? player;
  // controllerId only has meaning while a card is in play (CardInstance's own doc comment: "differs
  // only while a control-changing effect is active"). Reset here, same as returnToOwnersHand and
  // shuffleFromPlayIntoOwnersDeck already do -- fuzz finding (2026-08-01): a Creature whose control
  // had been gained by an opponent, then discarded/defeated, landed in its owner's discard pile with
  // a STALE controllerId still pointing at the former controller. Retrieved back to hand later (any
  // discard-pile-to-hand effect) and replayed by its real owner, Rabid Wasperine's own onPlay then
  // used that stale controllerId as the attacking player for its reactive counterattack, which
  // looked for the attacker in the WRONG player's inPlay array and threw "Attacker is not in play."
  card.controllerId = card.ownerId;
  owner.discardPile.push(card);
}

export interface CardLocation {
  playerId: PlayerId;
  zone: ListZone | 'activeMagi';
  instance: CardInstance;
}

/** Searches every zone of every player, including the single-slot activeMagi zone. */
export function findCard(state: GameState, instanceId: string): CardLocation | null {
  for (const player of state.players.values()) {
    if (player.activeMagi?.instanceId === instanceId) {
      return { playerId: player.playerId, zone: 'activeMagi', instance: player.activeMagi };
    }
    const listZones: ListZone[] = [
      'deck',
      'magiQueue',
      'defeatedMagi',
      'hand',
      'discardPile',
      'inPlay',
    ];
    for (const zone of listZones) {
      const found = player[zone].find((c) => c.instanceId === instanceId);
      if (found) {
        return { playerId: player.playerId, zone, instance: found };
      }
    }
  }
  return null;
}

/**
 * Draws up to `count` cards from the top of the deck into hand. Does NOT reshuffle the discard
 * pile if the deck runs out -- that's only legal once per turn during the Draw phase specifically
 * (rules-reference.md §5.6), so it's handled by the Draw phase logic, not this generic helper.
 * Returns the cards actually drawn (may be fewer than `count` if the deck ran out).
 */
export function drawCardsRaw(player: PlayerState, count: number): CardInstance[] {
  const drawn: CardInstance[] = [];
  for (let i = 0; i < count; i += 1) {
    const card = player.deck.shift();
    if (!card) break;
    player.hand.push(card);
    drawn.push(card);
  }
  return drawn;
}

/** Shuffles a player's discard pile into a new deck, per the once-per-turn Draw phase rule. */
export function shuffleDiscardIntoDeck(player: PlayerState, rng: Rng): void {
  const reclaimed = player.discardPile.splice(0, player.discardPile.length);
  shuffle(reclaimed, rng);
  player.deck.push(...reclaimed);
}

export function shuffleDeck(player: PlayerState, rng: Rng): void {
  shuffle(player.deck, rng);
}

/**
 * Finds and removes cards matching `names` from a player's deck (used for tutoring a Magi's
 * starting cards), then reshuffles the deck -- "Searching the deck — always reshuffle afterward"
 * (rules-reference.md §12). Cards not found are silently skipped (caller should have already
 * validated legality via a card-name lookup before calling this).
 */
export function searchDeckForNames(
  state: GameState,
  playerId: PlayerId,
  names: readonly string[],
  cardNameOf: (instance: CardInstance) => string,
  rng: Rng
): CardInstance[] {
  const player = getPlayer(state, playerId);
  const found: CardInstance[] = [];
  for (const name of names) {
    const index = player.deck.findIndex((c) => cardNameOf(c) === name);
    if (index !== -1) {
      const [card] = player.deck.splice(index, 1);
      found.push(card!);
    }
  }
  // Tutorial Mode (2026-08-10): a Tutorial deck's authored order IS the exact draw order for the
  // whole game (see GameState.tutorialMode's doc comment) -- the reshuffle that would otherwise
  // follow every deck search (rules-reference.md §12) is skipped here so the post-search draws
  // still land exactly where the tutorial script expects them.
  if (!state.tutorialMode) shuffleDeck(player, rng);
  return found;
}
