// Saitorr -- "Snuggles: As the beginning of your turn, if your Magi is Nar, you may discard
// Saitorr from play. If you do, draw a card for each energy on your Magi above his or her
// starting energy, to a maximum of five." Auto-taken only when it would draw at least one card --
// unlike this codebase's usual "always auto-take a 'may'" convention, sacrificing a Creature for
// zero cards is never a rational choice, so this is the one case where "auto-take" means "auto-
// take when strictly beneficial," not unconditionally.

import { registerCardEffect } from './registry.js';
import { discardFromPlay, drawCards } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';

registerCardEffect('Saitorr', {
  onOwnTurnStart: (state, cardDb, self, rng) => {
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi) return;
    const magiDef = cardDb.get(magi.definitionKey);
    if (!magiDef?.regions.includes('Nar')) return;
    const startingEnergy = effectiveStartingEnergy(state, cardDb, magi);
    const excess = (magi.currentEnergy ?? 0) - startingEnergy;
    const toDraw = Math.min(5, excess);
    if (toDraw <= 0) return;
    const player = state.players.get(self.controllerId)!;
    discardFromPlay(state, cardDb, player, self.instanceId, undefined, undefined, rng);
    drawCards(state, cardDb, player, toDraw);
  },
});
