// Shell (Spell, Orothe, cost 2) -- two printed clauses:
//   1. "Until the end of your next turn, your Orothe Creatures in play are not affected by
//      opposing Spells and Powers." A snapshot at cast time (durationTags.ts's SHELL_PROTECTED,
//      applied directly to each currently-in-play Orothe Creature the caster controls) -- a
//      Creature played AFTER Shell resolves isn't retroactively covered, matching the printed
//      present tense "Creatures in play." Checked directly inside effects.ts's
//      addEnergy/discardEnergy for both cause==='spell' and cause==='power' (broader than any
//      existing region-scoped immunity), opposing-only.
//   2. "If an opponent's Power, Spell, or Effect discards one or more cards from your hand, you may
//      discard Shell from your hand instead. If you do, discard all of that opponent's Relics in
//      play. All ongoing Powers and Effects of those Relics are canceled." registry.ts's
//      substitutesForHostileHandDiscard (Bagala Fangs' precedent, auto-taken -- discarding a
//      already-spent Shell to also wipe the opponent's Relics is essentially always correct) +
//      the new onSubstitutedForHostileHandDiscard hook for the bundled consequence. The
//      cancellation clause needs no separate code -- discardFromPlay already stops a Relic's
//      Powers/Effects from applying the instant it leaves play.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { addDurationTag, nextOwnTurnNumber, SHELL_PROTECTED } from '../durationTags.js';

registerCardEffect('Shell', {
  resolveSpell: (ctx) => {
    const expiry = nextOwnTurnNumber(ctx.state);
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      const regions = ctx.cardDb.get(creature.definitionKey)?.regions ?? [];
      if (regions.includes(regionForTargetFilter(ctx.state, 'Orothe'))) {
        addDurationTag(ctx.state, ctx.cardDb, creature, SHELL_PROTECTED, expiry, ctx.source.instanceId);
      }
    }
  },
  substitutesForHostileHandDiscard: () => true,
  onSubstitutedForHostileHandDiscard: (state, cardDb, self, actorPlayerId, rng) => {
    const opponent = state.players.get(actorPlayerId);
    if (!opponent) return;
    const relics = opponent.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic');
    for (const relic of relics) {
      discardFromPlay(state, cardDb, opponent, relic.instanceId, undefined, 'spell', rng);
    }
  },
  specifiedSpellTargetRegions: () => ['Orothe'],
});
