// Erisa -- Effects:
//   Nomad: "Erisa's frozen Creatures do not count as being in play when checking to see if she is
//   defeated." Narrows the Magi-defeat check's Creature-count requirement rather than dropping it
//   entirely (contrast All-High King Korg's Super Brave, same `customDefeatCondition` hook,
//   different shape).
//   Legacy: "When Erisa is defeated, leave her frozen Creatures and frozen Relics in play. When
//   you reveal your next Magi, discard all of your Relics from play if that Magi is not Nar."
//   Two halves, two hooks (2026-07-12): `survivesOwnMagiDefeat` exempts her own frozen
//   Creatures/Relics from the normal "wipe all inPlay" step; `onNextMagiRevealed` (self-guarded
//   with a permanent tag, fires once) discards whatever Relics are in play -- in practice, only
//   ever the ones her own survivesOwnMagiDefeat just preserved, since play.ts requires an active
//   Magi to play anything, and there is none between her defeat and the next reveal -- if that
//   next Magi's own printed region doesn't include Nar.

import { registerCardEffect } from './registry.js';
import { isFrozen, addPermanentTag } from '../durationTags.js';
import { discardFromPlay } from '../effects.js';

const ERISA_LEGACY_CONSUMED = 'erisaLegacyConsumed';

registerCardEffect('Erisa', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Nomad narrows the defeat condition; Legacy owns
  // both the "leave frozen cards" survivor guard and the reveal-time Relic wipe.
  effectHooks: {
    Nomad: ['customDefeatCondition'],
    Legacy: ['survivesOwnMagiDefeat', 'onNextMagiRevealed'],
  },
  customDefeatCondition: (state, cardDb, magi, ownCreatures) =>
    (magi.currentEnergy ?? 0) <= 0 && ownCreatures.every((c) => isFrozen(state, cardDb, c)),
  survivesOwnMagiDefeat: (state, cardDb, magi, card) => {
    const def = cardDb.get(card.definitionKey);
    if (!def || (def.card_type !== 'Creature' && def.card_type !== 'Relic')) return false;
    return isFrozen(state, cardDb, card);
  },
  onNextMagiRevealed: (state, cardDb, self, nextMagi, rng) => {
    if (self.tags.has(ERISA_LEGACY_CONSUMED)) return;
    addPermanentTag(state, cardDb, self, ERISA_LEGACY_CONSUMED);
    const nextDef = cardDb.get(nextMagi.definitionKey);
    if (nextDef?.regions.includes('Nar')) return;
    const player = state.players.get(self.controllerId);
    if (!player) return;
    for (const card of [...player.inPlay]) {
      if (cardDb.get(card.definitionKey)?.card_type === 'Relic') {
        discardFromPlay(state, cardDb, player, card.instanceId, undefined, undefined, rng);
      }
    }
  },
});
