// Ascend (Spell) -- "Play Ascend only before your Attack Step. Your Kybar's Teeth Creatures cannot
// attack this turn. Until the beginning of your next turn, all of your Kybar's Teeth Creatures lose
// three less energy in attacks." Kybar's Teeth Spell pass, Category C (2026-07-22). No target --
// applies to every Kybar's Teeth Creature the caster controls that's already in play at resolution
// (a one-shot Spell has no ongoing broadcast hook to reach Creatures played later this same turn).
// "Only before your Attack Step" is a phase gate on the caster's OWN turn -- 'energize' or 'prs1'.

import { registerCardEffect } from './registry.js';
import { addDurationTag, CANNOT_ATTACK, ASCEND_REDUCED_ATTACK_LOSS } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { creaturesControlledBy, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { beginningOfNextOwnTurnNumber } from '../durationTags.js';

registerCardEffect('Ascend', {
  preventsOwnPlay: (state, cardDb, playerId) => {
    if (state.activePlayerId !== playerId || (state.phase !== 'energize' && state.phase !== 'prs1')) {
      return 'Ascend can only be played before your own Attack Step';
    }
    return false;
  },
  resolveSpell: (ctx) => {
    const yours = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).filter((c) =>
      effectiveRegions(ctx.state, ctx.cardDb, c).includes(regionForTargetFilter(ctx.state, "Kybar's Teeth"))
    );
    const expiry = beginningOfNextOwnTurnNumber(ctx.state);
    for (const c of yours) {
      addRestrictionTag(ctx.state, c, CANNOT_ATTACK, ctx.state.turnNumber);
      addDurationTag(ctx.state, ctx.cardDb, c, ASCEND_REDUCED_ATTACK_LOSS, expiry, ctx.source.instanceId);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ["Kybar's Teeth"],
});
