// Sarazen Keeper -- two Powers.
// "Forged Alliance: If you have a Hyren in play, add one energy to each of your Sarazen in play."
// Two name-family checks (Hyren for the condition, Sarazen for the sweep).
// "Strength: If you have at least two Sarazens in play, draw a card." Previously had no branch in
// resolvePower at all -- cost was paid but nothing happened, a silent fizzle caught auditing for
// the same bug class as Thunder Hyren's Replenish (PROGRESS_LOG.md, 2026-07-09).

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { addEnergy, drawCards } from '../effects.js';

registerCardEffect('Sarazen Keeper', {
  resolvePower: (ctx) => {
    const own = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (ctx.powerName === 'Forged Alliance') {
      const hasHyren = own.some((c) => ctx.cardDb.get(c.definitionKey)?.name.includes('Hyren'));
      if (!hasHyren) return;

      for (const creature of own) {
        if (ctx.cardDb.get(creature.definitionKey)?.name.includes('Sarazen')) {
          addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
        }
      }
    } else if (ctx.powerName === 'Strength') {
      const sarazenCount = own.filter((c) => ctx.cardDb.get(c.definitionKey)?.name.includes('Sarazen')).length;
      if (sarazenCount < 2) return;
      drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    }
  },
});
