// Starlight's Genesis (Spell) -- "Discard a card from your hand and draw a card. If you played a
// copy of Sunbeam's End this turn, you may remove three energy from your Magi to draw two extra
// cards." Combos with sunbeamsEnd.ts via targeting.ts's playedCardNameThisTurn (a log scan, not a
// dedicated tracked field -- see that helper's own doc comment). The bonus's own yes/no choice
// (spellBooleanChoice) is only offered when the combo condition already holds.

import { registerCardEffect } from './registry.js';
import { discardFromHand, drawCards, discardEnergy } from '../effects.js';
import { playedCardNameThisTurn } from '../targeting.js';

registerCardEffect("Starlight's Genesis", {
  spellHandDiscardCost: { count: 1 },
  spellBooleanChoice: (state, cardDb, playerId) =>
    playedCardNameThisTurn(state, playerId, "Sunbeam's End")
      ? { prompt: 'Remove three energy from your Magi to draw two extra cards?', yesLabel: 'Yes', noLabel: 'No' }
      : undefined,
  resolveSpell: (ctx) => {
    const ids = ctx.chosenHandCardIds ?? [];
    if (ids.length !== 1) return;
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids, undefined, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    if (ctx.chosenBoolean && playedCardNameThisTurn(ctx.state, ctx.controllingPlayer.playerId, "Sunbeam's End")) {
      const magi = ctx.controllingPlayer.activeMagi;
      if (magi) {
        discardEnergy(ctx.state, ctx.cardDb, magi, 3, 'spell', undefined, ctx.rng);
        drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 2);
      }
    }
  },
});
