// Severos -- "Mind Dredge (1): Choose a Creature in an opponent's discard pile. Play the chosen
// Creature, ignoring regional restrictions and penalties. Pay all costs from Severos instead of
// your Magi. Use this Power only after the Attack step." First user of effects.ts's playFromZone.
// "Use this Power only after the Attack step" maps to legalPhases: ['prs2'] (the only
// Powers-usable phase after Attack in the fixed phase order -- power.ts already restricts Powers
// to prs1/prs2 generally). "Pay all costs from Severos" means discarding the played Creature's own
// printed cost as ENERGY from Severos itself, not the normal Magi payment.
//
// "When that Creature leaves play, discard Severos from play" -- built inline this pass
// (deferred-list full re-audit, 2026-08-13). The old comment cited "a linked-instance watch that
// nothing else in the codebase has needed yet"; that was stale on both counts. The
// permanent-tag-with-embedded-instanceId pattern shipped several times since -- Phlouk's Ring
// Testing uses the exact same "remember the id my past resolve targeted, react in a later hook"
// primitive (`phloukRingTestingPlayed:<instanceId>` on Phlouk itself, checked in onOwnTurnEnd) --
// and Umbu, Gherish, and Muck Rain are three more variants of the same shape. Severos tags itself
// with `severosMindDredgePlayed:<instanceId>` at the moment the played Creature enters play, and
// its own `onCardDiscardedFromPlay` hook fires when any tagged instance leaves play, discarding
// Severos as a matching-cascade explicit discard. Multiple uses of Mind Dredge accumulate multiple
// tags -- any one of the tracked Creatures leaving play triggers the "discard Severos" clause,
// matching the printed "when that Creature leaves play" phrasing (each tracked instance is a
// distinct "that Creature" the clause was armed for). Severos's own discard is not re-entrantly
// self-triggering: the hook checks `discarded.instanceId` against Severos's tags, and Severos's
// own instanceId never lands in that tag set.

import { registerCardEffect } from './registry.js';
import { opposingMagi, findCreatureOrMagiById, effectiveStartingEnergy } from '../targeting.js';
import { discardEnergy, discardFromPlay, playFromZone } from '../effects.js';
import { addPermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';

const DREDGED_PREFIX = 'severosMindDredgePlayed:';

function isTrackedDredgedId(self: CardInstance, instanceId: string): boolean {
  for (const tag of self.tags) {
    if (tag.startsWith(DREDGED_PREFIX) && tag.slice(DREDGED_PREFIX.length) === instanceId) return true;
  }
  return false;
}

registerCardEffect('Severos', {
  legalPhases: ['prs2'],
  powerTargets: (state, cardDb, playerId) => opposingMagi(state, cardDb, playerId),
  discardPileSearch: {
    count: 1,
    whoseDiscardPile: 'target',
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mind Dredge') return;
    if (ctx.chosenTargetId === undefined) return;
    const chosenMagi = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!chosenMagi || ctx.cardDb.get(chosenMagi.definitionKey)?.card_type !== 'Magi') return;
    const owner = ctx.state.players.get(chosenMagi.controllerId);
    if (!owner) return;

    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = owner.discardPile.find((c) => c.instanceId === id);
    if (!card || ctx.cardDb.get(card.definitionKey)?.card_type !== 'Creature') return;

    const cost = effectiveStartingEnergy(ctx.state, ctx.cardDb, card);
    if ((ctx.source.currentEnergy ?? 0) < cost) return;
    discardEnergy(ctx.state, ctx.cardDb, ctx.source, cost, undefined, undefined, ctx.rng);
    const played = playFromZone(ctx.state, ctx.cardDb, { owner, zone: 'discardPile', instanceId: id! }, ctx.controllingPlayer, cost, ctx.rng);
    if (played) {
      // Tag Severos so a later `onCardDiscardedFromPlay` on this same instance fires the
      // "discard Severos from play" clause. Uses the played instance's id (unchanged by
      // playFromZone), same shape as Phlouk's phloukRingTestingPlayed.
      addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${DREDGED_PREFIX}${played.instanceId}`);
    }
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, _discardedOwnerId, self, _cause, _source, _causedByPlayerId, rng) => {
    if (discarded.instanceId === self.instanceId) return;
    if (!isTrackedDredgedId(self, discarded.instanceId)) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    if (!owner.inPlay.some((c) => c.instanceId === self.instanceId)) return;
    discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
  },
});
