// Twunk -- "Timber: Whenever one of your Naroom Creatures with less energy than Twunk is
// attacked, remove two energy from the attacking Creature before energy is removed." Real energy
// discard -> onBeforeEnergyRemoved.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Twunk', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Naroom')) return;
    if ((ctx.defender.currentEnergy ?? 0) >= (self.currentEnergy ?? 0)) return;
    // Caused by Twunk's OWN controller (the defending side), not the attacker -- explicit
    // causedByPlayerId so discardEnergy's opposing/burrow-cap check attributes this correctly
    // (the attacker is the active player during their own attack, so the default would otherwise
    // wrongly read this as self-caused).
    discardEnergy(ctx.state, ctx.cardDb, ctx.attacker, 2, 'effect', self.controllerId, ctx.rng);
  },
});
