// Bria, Relic Hunter -- three abilities, all built now:
//   "Loss": After a Relic you control is discarded from play, remove one energy from Bria.
//     Via registry.ts's onCardDiscardedFromPlay, same shape as Thresh's Rethresh.
//   "Desire": After an OPPONENT plays a Relic, add three energy to Bria. `onPlay`'s broadcast
//     already reacts to a DIFFERENT player's play (same shape as Forest Wudge's Strengthen).
//   Top-level text "Bria, Relic Hunter may play Core Relics" -- post-playtest correctness pass, P3
//     (2026-07-12), via registry.ts's regionOverride hook (grej.ts is the template), checked by
//     play.ts's isLegalToPlay against the active Magi's own registered effect.

import { registerCardEffect } from './registry.js';
import { discardEnergy, addEnergy } from '../effects.js';
import { magiCountsAs } from './magiIdentity.js';
import { ashioAdjustedRegion } from '../targeting.js';

registerCardEffect('Bria, Relic Hunter', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Loss = the own-Relic-discarded
  // self-damage on `onCardDiscardedFromPlay`; Desire = the opponent-plays-Relic energy gain
  // on `onPlay`. `regionOverride` is top-level card text ("Bria may play Core Relics"), not
  // one of the named printed Effects, so it stays with the whole card, not any narrowed grant.
  effectHooks: {
    Loss: ['onCardDiscardedFromPlay'],
    Desire: ['onPlay'],
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    void discardedOwnerId;
    if (discarded.controllerId !== self.controllerId) return;
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Relic') return;
    discardEnergy(state, cardDb, self, 1, 'effect');
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return; // Desire is opponent-only
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;
    addEnergy(state, cardDb, self, 3, 'effect');
  },
  // Ashio's Weave Twist (2026-07-24): "Core" above is Bria's OWN printed text, so under Ashio it
  // means her own region (Orothe) instead -- see targeting.ts's ashioAdjustedRegion doc comment.
  // (Redundant once substituted, since Orothe Magi already play Orothe Relics natively -- that's
  // the correct, if anticlimactic, result of the substitution rule.)
  regionOverride: (state, cardDb, playedDef, magi) =>
    magiCountsAs(cardDb, magi, 'Bria, Relic Hunter') &&
    playedDef.card_type === 'Relic' &&
    playedDef.regions.includes(ashioAdjustedRegion(state, cardDb, 'Core', ['Orothe'])),
});
