// Cald Shadow Geyser (Spell, Core, cost 5) -- "The energy cost for this Geyser is zero if played by
// an Cald Shadow Magi. To play this Geyser, discard energy from each of your Creatures in play
// equal to the cost of their most expensive Power. If you discarded at least five energy, place
// this Geyser on the table. All Powers on Cald cards in play cost two additional energy to use. All
// Powers on your Core cards cost one less energy to use, to a minimum of one. You may not play
// another Cald Shadow Geyser while this one is in play. If your Magi leaves play, you may keep all
// but one of your Shadow Geysers in play. Agram does not discard any Shadow Geysers from play when
// he leaves play." Task #53-9, 2026-07-21, the Core Spell pass's A2 checkpoint.
//
// Unlike the other 4 Geysers, this cost is genuinely CONDITIONAL -- the discard always happens (an
// unconditional "each of your Creatures"), but placing the Geyser on the table depends on the
// resulting total meeting a threshold. `spellStaysInPlay: true` only means "resolveSpell is fully
// responsible for placing the card somewhere" (Crystal Vision's own doc comment) -- when the
// threshold isn't met, resolveSpell places it in the discard pile itself instead (moveToDiscardPile,
// imported directly from zones.ts) rather than relying on play.ts's own auto-discard, which is
// unconditionally skipped once spellStaysInPlay is declared.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { moveToDiscardPile } from '../zones.js';
import { creaturesControlledBy } from '../targeting.js';
import {
  castByShadowMagiOf,
  geyserSurvivesOwnMagiDefeat,
  geyserOnOwnMagiDefeated,
  geyserPendingTargetChoice,
  geyserResolveTargetChoice,
} from './shadowGeysers.js';
import type { CardDatabase } from '../types/card.js';

const NAME = 'Cald Shadow Geyser';

function mostExpensivePowerCost(cardDb: CardDatabase, definitionKey: number): number {
  const def = cardDb.get(definitionKey);
  if (!def || def.powers.length === 0) return 0;
  return Math.max(0, ...def.powers.map((p) => (typeof p.cost === 'number' ? p.cost : 0)));
}

registerCardEffect(NAME, {
  selfCostOverride: (state, cardDb, playerId) => (castByShadowMagiOf(state, cardDb, playerId, 'Cald') ? 0 : undefined),
  preventsOwnPlay: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (player?.inPlay.some((c) => cardDb.get(c.definitionKey)?.name === NAME)) {
      return 'You may not play another Cald Shadow Geyser while this one is in play';
    }
    return false;
  },
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    let totalDiscarded = 0;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      const amount = mostExpensivePowerCost(ctx.cardDb, creature.definitionKey);
      if (amount <= 0) continue;
      const before = creature.currentEnergy ?? 0;
      discardEnergy(ctx.state, ctx.cardDb, creature, amount, 'spell', undefined, ctx.rng);
      totalDiscarded += before - (creature.currentEnergy ?? 0);
    }
    if (totalDiscarded >= 5) {
      ctx.controllingPlayer.inPlay.push(ctx.source);
    } else {
      moveToDiscardPile(ctx.state, ctx.controllingPlayer, ctx.source);
    }
  },
  powerCostModifier: (state, cardDb, powerUserId, sourceDef, self) => {
    let delta = 0;
    if (sourceDef.regions.includes('Cald')) delta += 2;
    if (self.controllerId === powerUserId && sourceDef.regions.includes('Core')) delta -= 1;
    return delta;
  },
  powerCostFloorsAtOne: (state, cardDb, powerUserId, sourceDef, self) => self.controllerId === powerUserId && sourceDef.regions.includes('Core'),
  survivesOwnMagiDefeat: geyserSurvivesOwnMagiDefeat,
  onOwnMagiDefeated: geyserOnOwnMagiDefeated,
  pendingTargetChoice: geyserPendingTargetChoice,
  resolveTargetChoice: geyserResolveTargetChoice,
});
