  currentAction: { actorPlayerId: PlayerId; source: 'combat' | 'power' | 'effect' | 'spell'; sourceDefinitionKey?: number; sourceInstanceId?: string; archiveRedirect?: { substituteInstanceId: string } | 'skip' } | null;
