  pendingDiscardFromPlay: {
    /** The player whose zone the card is being removed from (controller, not necessarily owner). */
    ownerId: PlayerId;
    /** The Creature that would be discarded. Still in play while this field is set. */
    targetInstanceId: string;
    /** The player who caused the discard (opposing to owner, since Yricho only triggers there). */
    causedByPlayerId: PlayerId;
    /** Resolved discard source ('power' | 'spell' | 'effect' | 'combat'). */
    source: 'power' | 'spell' | 'effect' | 'combat';
    /** Yricho candidates still to attempt (first one is the current in-flight roll). */
    remainingYrichoCandidateInstanceIds: string[];
  } | null;
