// Gorgle's Ring -- "Wild Fire: Roll one die. 1, 2 or 3 = Discard one energy from each of your
// Creatures in play. 4 or 5 = Choose any one Creature in play. Discard two energy from the chosen
// Creature. 6 = Choose any one Magi in play. Discard four energy from the chosen Magi."
//
// The die roll (inside resolvePower) decides whether a target is even needed, but the UI must
// collect a target BEFORE the roll happens. Documented simplification: the picker offers every
// Creature AND every Magi in play (the union of what rolls 4-6 could need), even though a 1-3
// roll won't use it at all.
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import {
  allCreaturesInPlay,
  allMagiInPlay,
  creaturesControlledBy,
  findCreatureOrMagiById,
  isValidTargetGivenFlexibility,
} from '../targeting.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';

registerCardEffect("Gorgle's Ring", {
  powerTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Wild Fire') return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'gorglesRing:wildFire',
      { controllingPlayerId: ctx.controllingPlayer.playerId, chosenTargetId: ctx.chosenTargetId },
      ctx.rng
    );
  },
});

registerRollConsumer('gorglesRing:wildFire', (state, cardDb, _source, payload, finalRoll, rng) => {
  const { controllingPlayerId, chosenTargetId } = payload as { controllingPlayerId: string; chosenTargetId?: string };
  if (finalRoll <= 3) {
    for (const creature of creaturesControlledBy(state, cardDb, controllingPlayerId)) {
      discardEnergy(state, cardDb, creature, 1, undefined, undefined, rng);
    }
    return;
  }
  if (chosenTargetId === undefined) return;
  const target = findCreatureOrMagiById(state, chosenTargetId);
  if (!target) return;
  if (finalRoll <= 5) {
    if (!isValidTargetGivenFlexibility(state, cardDb, controllingPlayerId, target, 'Creature')) return;
    discardEnergy(state, cardDb, target, 2, undefined, undefined, rng);
  } else {
    if (!isValidTargetGivenFlexibility(state, cardDb, controllingPlayerId, target, 'Magi')) return;
    discardEnergy(state, cardDb, target, 4, undefined, undefined, rng);
  }
});
