// Kier -- two Effects:
//   "Burrow: As long as you have another Kybar's Teeth and another Underneath Creature in play,
//   Kier is burrowed; it cannot attack and loses no more than two energy per turn from attacks
//   and opposing Spells and Powers." (isConditionallyBurrowed -- the two region requirements can
//   be satisfied by one other Creature with both regions, or two different Creatures.)
//   "Crush: Whenever Kier attacks a Creature, Kier removes an additional energy from the
//   defending Creature."

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';

registerCardEffect('Kier', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Burrow owns isConditionallyBurrowed;
  // Crush owns onBeforeEnergyRemoved.
  effectHooks: {
    Burrow: ['isConditionallyBurrowed'],
    Crush: ['onBeforeEnergyRemoved'],
  },
  isConditionallyBurrowed: (state, cardDb, instance) => {
    const others = creaturesControlledBy(state, cardDb, instance.controllerId).filter(
      (c) => c.instanceId !== instance.instanceId
    );
    const hasOtherKybarsTeeth = others.some((c) => effectiveRegions(state, cardDb, c).includes("Kybar's Teeth"));
    const hasOtherUnderneath = others.some((c) => effectiveRegions(state, cardDb, c).includes('Underneath'));
    return hasOtherKybarsTeeth && hasOtherUnderneath;
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId || !ctx.defender) return;
    discardEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect', undefined, ctx.rng);
  },
});
