// Platheus -- "Soporific: Choose any one Creature in play. The chosen Creature cannot attack
// until after your next turn." Existing CANNOT_ATTACK tag (proven on 4 other cards), applied to
// an arbitrary chosen target with nextOwnTurnNumber's "until after YOUR next turn" duration --
// distinct from Firefly Amulet's nextTurnNumberFor(target's own controller).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addDurationTag, CANNOT_ATTACK, nextOwnTurnNumber } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Platheus', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Soporific') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, nextOwnTurnNumber(ctx.state));
  },
});
