// Great Pool of Wisdom -- "Stagnant Energy: Roll a die. If the number you roll is less than the
// number of your Bograth Creatures in play, draw a card." No target -- a roll-vs-count
// comparison gating a draw.
//
// Bograth-count-helper sweep (Bograth-cluster follow-up, 2026-07-21): reads targeting.ts's
// effectiveBograthCreatureCount (folds in Emlob's bonus, Bog Stench's virtual +2 for free).
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { effectiveBograthCreatureCount } from '../targeting.js';
import { drawCards, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { getPlayer } from '../types/state.js';

registerCardEffect('Great Pool of Wisdom', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Stagnant Energy') return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'greatPoolOfWisdom:stagnantEnergy',
      { controllingPlayerId: ctx.controllingPlayer.playerId },
      ctx.rng
    );
  },
});

registerRollConsumer('greatPoolOfWisdom:stagnantEnergy', (state, cardDb, _source, payload, finalRoll) => {
  const { controllingPlayerId } = payload as { controllingPlayerId: string };
  const controllingPlayer = getPlayer(state, controllingPlayerId);
  const bograthCount = effectiveBograthCreatureCount(state, cardDb, controllingPlayerId);
  if (finalRoll < bograthCount) {
    drawCards(state, cardDb, controllingPlayer, 1);
  }
});
