// Szhar -- "Legacy: When Szhar is discarded from play, draw two cards." Self-reactive
// onCardDiscardedFromPlay, doesn't care which cause (combat or explicit). Also carries the
// Recurring-subtype reveal clause shared with Habob/Uban/Venger (recurringReveal.ts, task #39-1).

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { recurringRevealHooks } from './recurringReveal.js';

registerCardEffect('Szhar', {
  ...recurringRevealHooks,
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;
    const player = state.players.get(discardedOwnerId);
    if (!player) return;
    drawCards(state, cardDb, player, 2);
  },
});
