// Icepack (Spell) -- "Choose a Creature and attach Icepack to it. If the Creature is Frozen, its
// Powers cost two less energy, to a minimum of one." Nar Spell pass, Category A (2026-07-22).
// spellStaysInPlay (Volt Shield's own precedent) since it attaches instead of discarding. The
// actual discount is checked directly in power.ts's cost computation (see that file's own
// Icepack comment) -- attachedCards aren't reached by the powerCostModifier broadcast loop, so
// this needs no registerCardEffect hooks of its own beyond the target pool and the attach itself.

import { registerCardEffect } from './registry.js';
import { attachCard } from '../attachedCards.js';
import { allCreaturesInPlay } from '../targeting.js';

registerCardEffect('Icepack', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    attachCard(target, ctx.source);
  },
});
