// Shrink (Spell) -- "Choose a Creature. Discard half of the chosen Creature's energy, rounded down."
// Targeted at ANY Creature (either side); resolveSpell discards floor(energy/2) with cause 'spell', so
// against an opponent's Creature it goes through the "opposing Powers and Spells" energy-loss reducers
// (Rayje, Legend's Intimidation, Garan, etc.) exactly like an opposing Power would. discardEnergy runs
// its own creature-defeat check, so reducing a Creature to 0 defeats it.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';

registerCardEffect('Shrink', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolveSpell: (ctx) => {
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target) return;
    const amount = Math.floor((target.currentEnergy ?? 0) / 2);
    if (amount > 0) discardEnergy(ctx.state, ctx.cardDb, target, amount, 'spell', undefined, ctx.rng);
  },
});
