// Aula -- "Windsight: Discard your hand. Draw five cards. You may not use Windsight with less
// than two cards in your hand." The "less than two cards" precondition is an unenforced legality
// gap (same documented-simplification tradeoff as other minor self-restriction clauses elsewhere
// in this codebase, e.g. Ancient's Puzzlebox's "cannot play another copy this turn").

import { registerCardEffect } from './registry.js';
import { drawCards, discardFromHand } from '../effects.js';

registerCardEffect('Aula', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Windsight') return;
    const handIds = ctx.controllingPlayer.hand.map((c) => c.instanceId);
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, handIds, undefined, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 5);
  },
});
