// Channeler's Gloves -- "Channeling: Discard two cards from your hand. Add two energy to your
// Magi." Not actually remove-energy (a survey false positive, same shape as Trulb Bracelet) --
// implemented anyway since it's a plain, already-speced-out use of the new hand-discard-cost
// framework. No target, no filter -- any two hand cards.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromHand } from '../effects.js';

registerCardEffect("Channeler's Gloves", {
  handDiscardCost: { count: 2 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Channeling') return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 2) return;
    if (!ctx.controllingPlayer.activeMagi) return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 2), undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, ctx.controllingPlayer.activeMagi, 2, 'power');
  },
});
