// Parathin -- "Dream Twist (3): Choose any one of your Creatures in play. Discard the chosen
// Creature from play. Reveal and discard cards from the top of your deck one at a time, until you
// reveal a Creature. Play that Creature with half of its starting energy (rounded up) without
// paying any costs." The mill-until-a-Creature loop is fully automatic -- the only player choice
// is which own Creature to discard first.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay, discardTopOfDeck, playFromZone } from '../effects.js';

registerCardEffect('Parathin', {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Twist') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = ctx.controllingPlayer.inPlay.find(
      (c) => c.instanceId === ctx.chosenTargetId && ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature'
    );
    if (!target) return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId, undefined, undefined, ctx.rng);

    const player = ctx.controllingPlayer;
    while (player.deck.length > 0) {
      const top = player.deck[0]!;
      if (ctx.cardDb.get(top.definitionKey)?.card_type === 'Creature') {
        const half = Math.ceil(effectiveStartingEnergy(ctx.state, ctx.cardDb, top) / 2);
        playFromZone(ctx.state, ctx.cardDb, { owner: player, zone: 'deck', instanceId: top.instanceId }, player, half, ctx.rng);
        break;
      }
      discardTopOfDeck(ctx.state, player);
    }
  },
});
