// Dreamdrain Charm -- two printed clauses:
//   "Dreamdrain: Reduce each Magi's Energize by the number of that Magi's Spells and Relics in
//   play." -- energizeRateModifier, unqualified ("each Magi," no "your"/"opposing"), reacting to
//   whichever Magi is about to energize regardless of side, counting THAT Magi's own controller's
//   Spells + Relics in play (Spells only sit in play very briefly via any "stays in play" text --
//   counted the same as Relics either way, matching the printed wording literally).
//   "At the beginning of their turn, any player may discard all of their Relics and Spells from
//   play to discard Dreamdrain Charm from play." Built task #43, 2026-07-18, the Nar region pass.
//   "Their turn" means whoever's turn is starting gets the option -- not both players
//   simultaneously, and not one player reacting to the other's turn. Just onOwnTurnStart +
//   onOpponentTurnStart (both already-existing broadcasts), each independently offering the SAME
//   pendingYesNoChoice to whichever player's turn just began, gated on that player actually having
//   Relics/Spells in play to discard. No new mechanism needed.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { discardFromPlay } from '../effects.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const DESTROY_PENDING = 'dreamdrainCharmDestroyPending';

function armIfEligible(state: GameState, cardDb: CardDatabase, turnPlayerId: string, self: CardInstance): void {
  const player = state.players.get(turnPlayerId);
  if (!player) return;
  const hasRelicOrSpell = player.inPlay.some((c) => {
    const def = cardDb.get(c.definitionKey);
    return def?.card_type === 'Spell' || def?.card_type === 'Relic';
  });
  if (!hasRelicOrSpell) return;
  addPermanentTag(state, cardDb, self, `${DESTROY_PENDING}:${turnPlayerId}`);
}

registerCardEffect('Dreamdrain Charm', {
  // Bucket D Batch C part 2 closure 2026-08-14: this Relic's body self-discards this card
  // from play, so Vault of Knowledge Key's Archive may offer a redirect. See registry.ts's
  // `causesOwnRelicSelfDiscard` doc comment.
  causesOwnRelicSelfDiscard: true,
  energizeRateModifier: (state, cardDb, energizing) => {
    if (cardDb.get(energizing.definitionKey)?.card_type !== 'Magi') return 0;
    const owner = state.players.get(energizing.controllerId);
    if (!owner) return 0;
    const count = owner.inPlay.filter((c) => {
      const def = cardDb.get(c.definitionKey);
      return def?.card_type === 'Spell' || def?.card_type === 'Relic';
    }).length;
    return -count;
  },
  onOwnTurnStart: (state, cardDb, self) => armIfEligible(state, cardDb, self.controllerId, self),
  onOpponentTurnStart: (state, cardDb, self) => armIfEligible(state, cardDb, state.activePlayerId, self),
  pendingYesNoChoice: (state, cardDb, self) => {
    const pendingFor = [...self.tags].find((t) => t.startsWith(`${DESTROY_PENDING}:`));
    if (!pendingFor) return undefined;
    const turnPlayerId = pendingFor.slice(`${DESTROY_PENDING}:`.length);
    if (turnPlayerId !== state.activePlayerId) return undefined; // stale -- that player's turn already passed
    return {
      prompt: 'Dreamdrain Charm: discard all of your Relics and Spells from play to discard Dreamdrain Charm from play?',
      yesLabel: 'Discard them all',
      noLabel: 'Leave Dreamdrain Charm alone',
    };
  },
  resolveYesNoChoice: (state, cardDb, self, chosenBoolean, rng) => {
    const pendingFor = [...self.tags].find((t) => t.startsWith(`${DESTROY_PENDING}:`));
    if (pendingFor) removePermanentTag(self, pendingFor);
    if (!chosenBoolean || !pendingFor) return;
    const turnPlayerId = pendingFor.slice(`${DESTROY_PENDING}:`.length);
    const player = state.players.get(turnPlayerId);
    if (!player) return;
    const targets = player.inPlay.filter((c) => {
      const def = cardDb.get(c.definitionKey);
      return def?.card_type === 'Spell' || def?.card_type === 'Relic';
    });
    for (const target of targets) {
      discardFromPlay(state, cardDb, player, target.instanceId, undefined, undefined, rng);
    }
    const charmOwner = state.players.get(self.controllerId);
    if (charmOwner) discardFromPlay(state, cardDb, charmOwner, self.instanceId, undefined, undefined, rng);
  },
});
