// Crystal Saris -- "Regenerate: At the end of each opponent's turn, if Crystal Saris was not
// attacked, add two energy to it." First real user of registry.ts's new onOpponentTurnEnd hook.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Crystal Saris', {
  onOpponentTurnEnd: (state, cardDb, self) => {
    if (self.wasAttackedThisTurn) return;
    addEnergy(state, cardDb, self, 2, 'effect');
  },
});
