// Quor Pup -- "Charge: When Quor Pup attacks, move up to two energy to it from your Magi."
// Unconditional self-attacker trigger, any attack type.
//
// Real choice (task #40-3, 2026-07-17, player-choice-default retrofit, Group 3): "up to two"
// replaced with a real `pendingPreCombatTargetChoice`/`amount` choice (Ugger's Borrow's exact
// template, `PreCombatTargetResolution.amount`) instead of auto-maxing -- the pool is always just
// the controller's own Magi (a fixed single-candidate target), so the real choice here is the
// AMOUNT, 0-2. No resolution supplied (bots, or any caller written before this existed) falls
// back to the old auto-max-2 default, same as Scout Bungaloo's own fallback.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import type { PreCombatTargetResolution } from '../combat.js';

registerCardEffect('Quor Pup', {
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker) => {
    if (!isAttacker) return undefined;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi || (magi.currentEnergy ?? 0) <= 0) return undefined;
    return { prompt: "Quor Pup's Charge: choose how much energy (up to two) to move from your Magi", pool: [magi] };
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    const magi = ctx.attackingPlayer.activeMagi;
    if (!magi) return;

    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
    const resolution = resolutions?.[self.instanceId];
    let amount: number;
    if (resolution !== undefined) {
      amount = 'skip' in resolution ? 0 : Math.max(0, Math.min(resolution.amount ?? 0, magi.currentEnergy ?? 0, 2));
    } else {
      amount = Math.min(2, magi.currentEnergy ?? 0); // unchanged auto-max default when no resolution was supplied
    }
    if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, magi, self, amount, ctx.rng);
  },
});
