// Lava Balamant -- "If Lava Balamant attacks, add one energy before energy is removed."
// Unconditional self-attacker trigger, any attack type (Creature or direct Magi).

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Lava Balamant', {
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    addEnergy(ctx.state, ctx.cardDb, self, 1, 'effect');
  },
});
