// Sarazen Outcast -- both printed clauses:
//   "Favored Enemy: When you play Sarazen Outcast, choose any one Creature type." Stored on
//   CardInstance.persistentCategoryChoice (task #30, 2026-07-15 -- same field Niffer's Allies
//   uses, genericized this pass to also cover a Creature TYPE, not just a region).
//   "Bane: Whenever Sarazen Outcast attacks or is attacked by a Creature of the chosen type, add
//   four energy to Sarazen Outcast before energy is removed." onBeforeEnergyRemoved, checking
//   BOTH the attacker and defender (whichever one ISN'T Sarazen Outcast) against the stored type.
//
// Real choice (task #40-5, 2026-07-17, player-choice-default retrofit, Group 5): "choose any one
// Creature type" is a MANDATORY pick (no "may"), so this is now a real `pendingCategoryChoice`/
// `resolveCategoryChoice` (registry.ts's post-hoc category family, shared with Niffer's Allies) --
// options are every distinct Creature type currently in play on EITHER side (the same "types that
// could actually matter for Bane" scope the old auto-pick's own candidate pool used, before
// collapsing it to a single most-common pick), falling back to `['Hyren']` (the single most common
// family in the real card pool) if the board is empty so a choice is still always offered. No
// resolution (or an out-of-options answer) falls back to the old "most common opposing, else most
// common overall, else Hyren" default.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creatureType, effectiveCreatureType } from '../targeting.js';
import { getOpponents } from '../types/state.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING_CHOICE = 'sarazenOutcastAwaitingChoice';

function typeCounts(cardDb: CardDatabase, creatures: { definitionKey: number }[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const c of creatures) {
    const type = creatureType(cardDb, c.definitionKey);
    counts.set(type, (counts.get(type) ?? 0) + 1);
  }
  return counts;
}

function mostCommonType(counts: Map<string, number>): string | undefined {
  let best: string | undefined;
  let bestCount = 0;
  for (const [type, count] of counts) {
    if (count > bestCount) {
      best = type;
      bestCount = count;
    }
  }
  return best;
}

function oppCreatures(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  return getOpponents(state, self.controllerId)
    .flatMap((p) => p.inPlay)
    .filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature');
}

function allCreatures(state: GameState, cardDb: CardDatabase): CardInstance[] {
  return [...state.players.values()].flatMap((p) => p.inPlay).filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Creature');
}

registerCardEffect('Sarazen Outcast', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Favored Enemy owns the onPlay pending
  // trigger plus its resolve pair. Bane owns the onBeforeEnergyRemoved reactor that reads the
  // stored persistentCategoryChoice.
  effectHooks: {
    'Favored Enemy': ['onPlay', 'pendingCategoryChoice', 'resolveCategoryChoice'],
    Bane: ['onBeforeEnergyRemoved', 'combatCreatureTypes'],
  },
  // Swirling Orshaa's Morph Effect-half (Bucket D Batch E2 closure, 2026-08-14). Sarazen
  // Outcast's Bane is a continuous per-attack Creature-type check ("chosen type"); Orshaa's
  // controller may want a Morph opt-in to make Orshaa the chosen type (usually the informed
  // choice is to DECLINE -- opting in makes Bane fire against Orshaa; declining lets Orshaa
  // stay printed d'Resh and avoid Bane's +4). Registering `combatCreatureTypes` is what makes
  // the offer FIRE (player-agency-preserving), not the assumption that opt-in is beneficial.
  // No chosen type yet (Favored Enemy hasn't resolved) -> empty pool -> no offer.
  combatCreatureTypes: (state, cardDb, _playerId, sourceInstanceId) => {
    const p = state.players.get(_playerId);
    const self = p?.inPlay.find((c) => c.instanceId === sourceInstanceId);
    if (!self || self.persistentCategoryChoice === null) return [];
    return [self.persistentCategoryChoice];
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    if (self.persistentCategoryChoice !== null) return;
    addPendingChoiceTag(self, AWAITING_CHOICE);
  },
  pendingCategoryChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const options = [...typeCounts(cardDb, allCreatures(state, cardDb)).keys()];
    if (options.length === 0) options.push('Hyren');
    return { prompt: 'Sarazen Outcast\'s Favored Enemy: choose any one Creature type', options };
  },
  resolveCategoryChoice: (state, cardDb, self, chosen) => {
    removePermanentTag(self, AWAITING_CHOICE);
    const allCounts = typeCounts(cardDb, allCreatures(state, cardDb));
    if (chosen && (allCounts.has(chosen) || chosen === 'Hyren')) {
      self.persistentCategoryChoice = chosen;
      return;
    }
    const oppCounts = typeCounts(cardDb, oppCreatures(state, cardDb, self));
    self.persistentCategoryChoice = mostCommonType(oppCounts) ?? mostCommonType(allCounts) ?? 'Hyren';
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (self.persistentCategoryChoice === null) return;
    const isAttacker = ctx.attacker.instanceId === self.instanceId;
    const isDefender = ctx.defender?.instanceId === self.instanceId;
    if (!isAttacker && !isDefender) return;

    const other = isAttacker ? ctx.defender : ctx.attacker;
    if (!other) return;
    if (ctx.cardDb.get(other.definitionKey)?.card_type !== 'Creature') return;
    // Bucket D Batch E2 closure (2026-08-14): honors Swirling Orshaa's Morph Effect-half via
    // effectiveCreatureType (was raw creatureType, which ignored Orshaa's identityOverride
    // -- a silent gap for Bane that even a fired opt-in wouldn't have fixed until this line
    // changed too). Same pattern as Shadow Hyren's Taste and every other post-2026-07-24
    // Morph-respecting reader.
    if (effectiveCreatureType(ctx.cardDb, other) !== self.persistentCategoryChoice) return;

    addEnergy(ctx.state, ctx.cardDb, self, 4, 'effect');
  },
});
