// Ohk -- "Mind's Gift: Discard any one Creature card from your hand. Choose any one Creature in
// play. Add three energy to the chosen Creature."

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy, discardFromHand } from '../effects.js';

registerCardEffect('Ohk', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.card_type === 'Creature',
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Mind's Gift") return;
    if (ctx.chosenTargetId === undefined) return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandCardIds![0]);
    if (!discardedCard || ctx.cardDb.get(discardedCard.definitionKey)?.card_type !== 'Creature') return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    addEnergy(ctx.state, ctx.cardDb, target, 3, 'power');
  },
});
