// Trulb -- "Dream Hatch: Discard Trulb from play. Look at a number of cards from the top of your
// deck equal to the number of your Bograth Creatures in play. Choose any one Bograth Creature from
// those cards and play it with one energy, ignoring all costs. Shuffle the remaining cards into
// your deck." First user of deckTopReveal's dynamic (state-dependent) count. The unchosen revealed
// cards are never explicitly moved -- they're still sitting in the deck below where the chosen
// card was (only the chosen one gets removed), so a plain shuffleDeck afterward IS "shuffle the
// remaining cards into your deck": there's nothing left to move, just to randomize.
//
// Emlob retrofit (task #30, 2026-07-15): counts "your Bograth Creatures in play," exactly Emlob's
// Imaginary Friends inflates by three -- applied to BOTH the UI-facing deckTopReveal.count and
// resolvePower's own re-derivation of the same number, so they stay consistent.
//
// Bograth-count-helper sweep (Bograth-cluster follow-up, 2026-07-21): both call sites now read
// targeting.ts's effectiveBograthCreatureCount (which already folds in Emlob's bonus) instead of a
// separate manual emlobBonus() call, keeping the same "stay consistent with each other" property,
// and picking up Bog Stench's virtual +2 for free.

import { registerCardEffect } from './registry.js';
import { effectiveBograthCreatureCount } from '../targeting.js';
import { discardFromPlay, playFromZone } from '../effects.js';
import { shuffleDeck } from '../zones.js';
import type { CardDatabase } from '../types/card.js';

function isBograthCreature(cardDb: CardDatabase, definitionKey: number): boolean {
  const def = cardDb.get(definitionKey);
  return !!def && def.card_type === 'Creature' && def.regions.includes('Bograth');
}

registerCardEffect('Trulb', {
  deckTopReveal: {
    count: (state, cardDb, playerId) => effectiveBograthCreatureCount(state, cardDb, playerId),
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dream Hatch') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const n = effectiveBograthCreatureCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    const ids = ctx.chosenDeckTopIds ?? [];
    if (ids.length === 0) {
      shuffleDeck(ctx.controllingPlayer, ctx.rng); // nothing chosen -- deck stays as-is, but shuffle is unconditional per the text
      return;
    }
    if (ids.length > 1) return;
    const top = ctx.controllingPlayer.deck.slice(0, n).map((c) => c.instanceId);
    const [id] = ids;
    if (!top.includes(id!)) return;
    const card = ctx.controllingPlayer.deck.find((c) => c.instanceId === id);
    if (!card || !isBograthCreature(ctx.cardDb, card.definitionKey)) return;

    playFromZone(ctx.state, ctx.cardDb, { owner: ctx.controllingPlayer, zone: 'deck', instanceId: id! }, ctx.controllingPlayer, 1, ctx.rng);
    shuffleDeck(ctx.controllingPlayer, ctx.rng);
  },
});
