// Yajo -- "Vitalize (1): Choose any one Creature in play that attacked this turn. Add three
// energy to the chosen Creature." Also prints "Timid: Yajo cannot attack." (permanent tag on
// entry) and "Weave: Whenever Yajo is attacked, before energy is removed, you may move one
// energy between it and one of your other Weave Creatures in play." (defend-only, matching
// Timid -- see weave.ts)

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { addPermanentTag, CANNOT_ATTACK } from '../durationTags.js';
import { applyWeave } from './weave.js';

registerCardEffect('Yajo', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Timid self-tags CANNOT_ATTACK on entry
  // via `onPlay`; Weave is the defend-only move hook + `weaveConfig`. Vitalize is a POWER, not a
  // printed Effect -- `powerTargets`/`resolvePower` are intentionally omitted (Powers travel via
  // the syntheticPowers/findPower widening path, not `effectHooks`).
  effectHooks: {
    Timid: ['onPlay'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => c.attackedThisTurn),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Vitalize') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!target.attackedThisTurn) return;

    addEnergy(ctx.state, ctx.cardDb, target, 3, 'power');
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    addPermanentTag(state, cardDb, self, CANNOT_ATTACK);
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'defendOnly' },
  onBeforeEnergyRemoved: (ctx, self) => applyWeave(ctx, self, ['Weave'], 'defendOnly'),
});
