// Eryss -- "Discordia: Once per turn, when an opposing Magi plays a non-Universal Creature not of
// their Magi's region, you may choose and discard one of that Magi's Creatures from play."
// onPlay broadcast (opposing player's Creature play, off-region relative to THEIR OWN active
// Magi, not Eryss's) + once-per-turn duration tag on Eryss herself + auto-picked discard target
// (highest current energy among that Magi's controller's own Creatures -- a hostile effect,
// "prefer the best target for an unprompted pick" convention used elsewhere, e.g. Worgle/Garlak).

import { registerCardEffect } from './registry.js';
import { discardFromPlay } from '../effects.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';
import { isUniversal } from '../regions.js';
import { addDurationTag, hasDurationTag } from '../durationTags.js';

const DISCORDIA_USED = 'eryssDiscordiaUsedThisTurn';

registerCardEffect('Eryss', {
  onPlay: (state, cardDb, played, self, rng) => {
    if (played.controllerId === self.controllerId) return; // "an opposing Magi"
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    const playedRegions = effectiveRegions(state, cardDb, played);
    if (isUniversal(playedRegions)) return;
    if (hasDurationTag(self, DISCORDIA_USED)) return;

    const playingPlayer = state.players.get(played.controllerId);
    const magi = playingPlayer?.activeMagi;
    if (!magi) return;
    const magiRegions = effectiveRegions(state, cardDb, magi);
    if (playedRegions.some((r) => magiRegions.includes(r))) return; // shares a region -- not off-region

    const targets = creaturesControlledBy(state, cardDb, played.controllerId);
    if (targets.length === 0) return;
    const target = targets.reduce((best, c) => ((c.currentEnergy ?? 0) > (best.currentEnergy ?? 0) ? c : best));

    addDurationTag(state, cardDb, self, DISCORDIA_USED, state.turnNumber);
    const owner = state.players.get(target.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, target.instanceId, undefined, undefined, rng);
  },
});
