// Borse -- "Tinker: Choose any one of your Relics in play. Discard the chosen Relic from play.
// Reveal the top five cards of your deck to all players. Play one of the revealed Relics,
// regardless of Region. Place all other revealed cards into your discard pile." Errata (2i Design,
// data-pipeline/output/rulings.json, applied 2026-07-09) changed this from "put one of EACH
// distinct-named Relic revealed into play" (fully automatic, no choice) to "play ONE of the
// revealed Relics" (the controller picks at most one) -- a real behavior change, not just
// wording, so this now uses deckTopReveal for the choice instead of being fully automatic.

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { removeFromZone, addToZone, moveToDiscardPile } from '../zones.js';

registerCardEffect('Borse', {
  powerTargets: (state, cardDb, playerId) => allRelicsInPlay(state, cardDb).filter((c) => c.controllerId === playerId),
  deckTopReveal: { count: 5 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Tinker') return;
    if (ctx.chosenTargetId === undefined) return;
    const relic = ctx.controllingPlayer.inPlay.find(
      (c) => c.instanceId === ctx.chosenTargetId && ctx.cardDb.get(c.definitionKey)?.card_type === 'Relic'
    );
    if (!relic) return;

    const player = ctx.controllingPlayer;
    const top = player.deck.slice(0, 5);
    const topIds = top.map((c) => c.instanceId);
    const chosenIds = (ctx.chosenDeckTopIds ?? []).filter((id) => topIds.includes(id));
    if (chosenIds.length > 1) return;
    const playedId = chosenIds[0];
    if (playedId) {
      const chosen = top.find((c) => c.instanceId === playedId);
      if (!chosen || ctx.cardDb.get(chosen.definitionKey)?.card_type !== 'Relic') return;
    }

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, relic.instanceId, undefined, undefined, ctx.rng);
    for (const id of topIds) {
      const card = removeFromZone(player, 'deck', id);
      if (id === playedId) {
        card.currentEnergy = null;
        addToZone(player, 'inPlay', card);
      } else {
        moveToDiscardPile(ctx.state, player, card);
      }
    }
  },
});
