// Kolte -- two effects:
//   "Parting Shot: Each time one of your Creatures is defeated in an attack, discard two energy
//   from the Creature that defeated it." (afterCombat)
//   "Fight Back: Whenever Kolte is attacked, discard two energy from the attacking Creature before
//   energy is removed." (onBeforeEnergyRemoved, self=defender) -- a direct discardEnergy on the
//   attacker's own pool. Corrected 2026-07-11: this used to run in onAttack (after the damage
//   snapshot), with a comment claiming it deliberately did NOT reduce the damage locked in for
//   THIS attack -- but the card's own printed "before energy is removed" text says otherwise. Now
//   it runs before the snapshot, so the reduction correctly counts toward this attack's own
//   damage output too, same fix as Bleph/cycloneXyx.ts's Backlash if that ever prints similar text.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Kolte', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Fight Back = the pre-damage
  // attacker discount when Kolte is direct-attacked (`onBeforeEnergyRemoved`); Parting Shot =
  // the "own Creature defeated in combat -> discard 2 from the killer" reactor (`afterCombat`).
  effectHooks: {
    'Fight Back': ['onBeforeEnergyRemoved'],
    'Parting Shot': ['afterCombat'],
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    // ctx.defender is only set for a Creature defender -- Kolte is a Magi, so "whenever Kolte is
    // attacked" needs the direct-Magi-attack check instead (ctx.defender === null).
    if (ctx.defender !== null) return;
    if (ctx.defendingPlayer.activeMagi?.instanceId !== self.instanceId) return;
    discardEnergy(ctx.state, ctx.cardDb, ctx.attacker, 2, 'effect', undefined, ctx.rng);
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.defender === null || ctx.defender.controllerId !== self.controllerId) return;
    if (outcome.defenderSurvived) return;
    discardEnergy(ctx.state, ctx.cardDb, ctx.attacker, 2, 'effect', undefined, ctx.rng);
  },
});
