// Vopok -- two printed clauses:
//   "Great Wall: When you play Vopok, if your Magi is Kybar's Teeth, add six energy to Vopok."
//   Unnamed: "Vopok cannot attack. During your Energize Step, you may discard a card from your
//   hand. If you do, Vopok can attack this turn." Region-audit follow-up, 2026-07-24 -- the old
//   "whatever bucket handles Energize-Step player choices" deferral is stale: `onOwnEnergizeStepStart`
//   now exists (Blizzard Core), and the "may discard a hand card to unlock X" shape is proven by
//   Mountain Trulb's Rolling Stone (same `pendingYesNoChoice`/pendingTargetChoice-with-Skip family;
//   here it's `pendingTargetChoice` over the hand pool specifically, since WHICH card gets
//   discarded matters, unlike Rolling Stone's plain yes/no). "Cannot attack" is the standard
//   permanent CANNOT_ATTACK tag applied on entry (Mosp's own precedent); the unlock is a
//   same-turn-only exception via `grantsCanAttackDespiteCannotAttackTo` (Empress Gia's own
//   mechanism), gated on a duration tag that expires at the end of the current turn.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardFromHand } from '../effects.js';
import { addDurationTag, addPermanentTag, addPendingChoiceTag, removePermanentTag, hasDurationTag, CANNOT_ATTACK } from '../durationTags.js';

const VOPOK_UNLOCK_PENDING = 'vopokUnlockPending';
const VOPOK_CAN_ATTACK_THIS_TURN = 'vopokCanAttackThisTurn';

registerCardEffect('Vopok', {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    addPermanentTag(state, cardDb, self, CANNOT_ATTACK);
    const magi = state.players.get(self.controllerId)?.activeMagi;
    const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
    if (!magiDef?.regions.includes("Kybar's Teeth")) return;
    addEnergy(state, cardDb, self, 6, 'effect');
  },
  onOwnEnergizeStepStart: (state, cardDb, self) => {
    const owner = state.players.get(self.controllerId);
    if (!owner || owner.hand.length === 0) return;
    addPendingChoiceTag(self, VOPOK_UNLOCK_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(VOPOK_UNLOCK_PENDING)) return undefined;
    const owner = state.players.get(self.controllerId);
    if (!owner || owner.hand.length === 0) return undefined;
    return { prompt: "Vopok: discard a card from your hand so Vopok can attack this turn?", pool: owner.hand };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, VOPOK_UNLOCK_PENDING);
    if (!chosenInstanceId) return;
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    discardFromHand(state, cardDb, owner, [chosenInstanceId], self.controllerId);
    addDurationTag(state, cardDb, self, VOPOK_CAN_ATTACK_THIS_TURN, state.turnNumber);
  },
  grantsCanAttackDespiteCannotAttackTo: (state, cardDb, self, attacker) => {
    if (attacker.instanceId !== self.instanceId) return false;
    return hasDurationTag(self, VOPOK_CAN_ATTACK_THIS_TURN);
  },
});
