// Koza -- "Steal": "Once per turn, when you play a Relic from your hand, choose a Magi. Discard
// two energy from the chosen Magi." Real choice (Phase 4c, 2026-07-11): replaces the earlier
// "first eligible in allMagiInPlay's array order" simplification with a real pending choice
// (registry.ts's pendingTargetChoice/resolveTargetChoice).
// "Borrow: Koza can use Powers on opposing Relics." Built task #43, 2026-07-18, the Nar region
// pass -- Category C. Read as "Koza can ACTIVATE an opposing Relic's own printed Power as if it
// were Koza's own" (borrowing), not a targeting-restriction bypass -- maps onto the existing
// copiedPowers.ts#addCopiedPower primitive (proven by Nahara/Taglat/K'teeb/Gremm's
// Helmet/Ergar's Ignite/Mohani's Imbue Spell). Dispatch already resolves a copied Power against
// `ctx.source` (Koza), so "all copied Powers... reference the copier" falls out for free, same as
// every existing user; `def` (Koza's own identity, a Magi) stays the paidBy source per
// power.ts's own contract, so a borrowed Relic Power still correctly pays from Koza's own energy.
// Live-synced on onOwnTurnStart: for each opposing Relic currently in play that Koza hasn't
// already copied, add copies of all its printed Powers, each expiring when THAT SPECIFIC Relic
// leaves play (expiresWhenInstanceLeavesPlay, K'teeb's own precedent) -- naturally handles Relics
// entering/leaving over the course of the game without needing an explicit removal step.

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { allMagiInPlay } from '../targeting.js';
import { addDurationTag, addPermanentTag, addPendingChoiceTag, hasDurationTag, removePermanentTag } from '../durationTags.js';
import { addCopiedPower } from '../copiedPowers.js';
import { getOpponents } from '../types/state.js';

const STEAL_USED_THIS_TURN = 'kozaStealUsedThisTurn';
const STEAL_PENDING = 'kozaStealPending';

registerCardEffect('Koza', {
  // Per-Effect hook narrowing (E1, 2026-08-12). Steal owns the on-Relic-play pending-choice
  // chain; Borrow owns the turn-start sweep that live-copies opposing Relics' Powers onto Koza.
  effectHooks: {
    Steal: ['onPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
    Borrow: ['onOwnTurnStart'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;
    if (hasDurationTag(self, STEAL_USED_THIS_TURN)) return;
    if (allMagiInPlay(state).length === 0) return;

    addPendingChoiceTag(self, STEAL_PENDING);
    addDurationTag(state, cardDb, self, STEAL_USED_THIS_TURN, state.turnNumber);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(STEAL_PENDING)) return undefined;
    const pool = allMagiInPlay(state);
    if (pool.length === 0) return undefined;
    return { prompt: "Koza's Steal: choose a Magi to discard 2 energy from", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, STEAL_PENDING);
    if (!chosenInstanceId) return;
    const target = allMagiInPlay(state).find((c) => c.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 2, 'effect', undefined, rng);
  },
  onOwnTurnStart: (state, cardDb, self) => {
    const opposingRelics = getOpponents(state, self.controllerId).flatMap((p) =>
      p.inPlay.filter((c) => cardDb.get(c.definitionKey)?.card_type === 'Relic')
    );
    const alreadyCopiedInstanceIds = new Set(self.copiedPowers.map((cp) => cp.expiresWhenInstanceLeavesPlay).filter((id): id is string => id !== undefined));
    for (const relic of opposingRelics) {
      if (alreadyCopiedInstanceIds.has(relic.instanceId)) continue;
      const relicDef = cardDb.get(relic.definitionKey);
      if (!relicDef) continue;
      for (const power of relicDef.powers ?? []) {
        addCopiedPower(self, power, relic.definitionKey, { whenInstanceLeavesPlay: relic.instanceId });
      }
    }
  },
});
