// Dakat -- "Deja Vu (2): Discard a card from your hand. The next time this turn one of your
// Spells or Powers removes energy from an opposing Creature, choose another Creature in play.
// Remove an equal amount of energy from the chosen Creature."
//
// Task #39-3g, 2026-07-17, d'Resh Category C: the "watch for the next Power-caused energy removal
// from an opposing Creature this turn, then prompt a follow-up target choice" mechanism the
// original scoping plan flagged as needing something new -- turned out to already exist:
// registry.ts's `onOwnPowerDiscardedOpposingEnergyFromCreature` (task #31, The Last Words/Scroll
// of Fire/Ithapher's precedent) already fires exactly once per opposing Creature actually hit by
// one of Dakat's controller's own Powers, with that Creature's own exact loss amount -- precisely
// "the next time... one of your Powers removes energy from an opposing Creature." (Task #51,
// 2026-07-20: the underlying hook now ALSO fires from Spell resolution, so the "Spells" half of
// Dakat's own printed text is live too, for free, with no changes needed here.) A permanent tag
// marks the one-shot watch; the hook consumes it on the FIRST qualifying hit this turn (even mid-resolution,
// if a single Power hits multiple opposing Creatures in one go, only the first one in iteration
// order triggers Deja Vu, matching "the next time," singular). The follow-up "choose another
// Creature in play" is a real mandatory `pendingTargetChoice`/`resolveTargetChoice` -- pool is
// every Creature in play EXCEPT the one that was just hit ("another"), no side restriction (could
// be your own or the opponent's).

import { registerCardEffect } from './registry.js';
import { discardEnergy, discardFromHand } from '../effects.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';

const WATCHING = 'dakatDejaVuWatching';
const PENDING_PREFIX = 'dakatDejaVuPending:'; // `${amount}:${excludedInstanceId}`

function parsePending(self: { tags: ReadonlySet<string> }): { amount: number; excludedInstanceId: string } | undefined {
  for (const tag of self.tags) {
    if (!tag.startsWith(PENDING_PREFIX)) continue;
    const rest = tag.slice(PENDING_PREFIX.length);
    const separatorIndex = rest.indexOf(':');
    if (separatorIndex === -1) continue;
    const amount = Number(rest.slice(0, separatorIndex));
    const excludedInstanceId = rest.slice(separatorIndex + 1);
    if (!Number.isFinite(amount)) continue;
    return { amount, excludedInstanceId };
  }
  return undefined;
}

registerCardEffect('Dakat', {
  handDiscardCost: { count: 1 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Deja Vu') return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, WATCHING);
  },
  // "The next time THIS TURN" -- an unused watch doesn't carry over into a future turn.
  onOwnTurnEnd: (state, cardDb, self) => removePermanentTag(self, WATCHING),
  onOwnPowerDiscardedOpposingEnergyFromCreature: (state, cardDb, self, sourceCard, target, amount) => {
    if (!self.tags.has(WATCHING)) return;
    removePermanentTag(self, WATCHING);
    if (allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== target.instanceId).length === 0) return;
    addPermanentTag(state, cardDb, self, `${PENDING_PREFIX}${amount}:${target.instanceId}`);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const pending = parsePending(self);
    if (!pending) return undefined;
    const pool = allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== pending.excludedInstanceId);
    if (pool.length === 0) return undefined;
    return { prompt: `Dakat's Deja Vu: choose another Creature in play to remove ${pending.amount} energy from`, pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const pending = parsePending(self);
    if (!pending) return;
    removePermanentTag(self, `${PENDING_PREFIX}${pending.amount}:${pending.excludedInstanceId}`);
    if (!chosenInstanceId) return;
    const target = findInPlayById(state, chosenInstanceId);
    if (!target || target.instanceId === pending.excludedInstanceId) return;
    discardEnergy(state, cardDb, target, pending.amount, 'power', undefined, rng);
  },
});
