// Bog Stone -- "Rummage (2): Place any one Bograth Creature from your discard pile into your
// hand." Same discardPileSearch shape as Sperri/Delia, filtered by region + card_type instead of
// creatureType (there's no single shared "family" name across Bograth Creatures the way Furok/
// Vellup are one family each).

import { registerCardEffect } from './registry.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';
import { retrieveFromDiscardPile } from '../effects.js';
import { regionForTargetFilter } from '../targeting.js';

function isBograthCreature(state: GameState, cardDb: CardDatabase, definitionKey: number): boolean {
  const def = cardDb.get(definitionKey);
  return !!def && def.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, 'Bograth'));
}

registerCardEffect('Bog Stone', {
  discardPileSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => isBograthCreature(state, cardDb, card.definitionKey),
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Rummage') return;
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    if (!card || !isBograthCreature(ctx.state, ctx.cardDb, card.definitionKey)) return;
    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'hand');
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Bograth'],
});
