// Xyx Elder -- "Shockstorm (6): Roll one die. Discard that much energy from each non-Xyx Creature
// in play." No target picker -- applies automatically to every Creature whose name doesn't
// contain "Xyx" (same name-substring-family approach as chogulith.ts's Chogus check).
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay } from '../targeting.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';

registerCardEffect('Xyx Elder', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shockstorm') return;
    requestDieRoll(ctx.state, ctx.cardDb, ctx.source, ctx.source.controllerId, 6, 'xyxElder:shockstorm', {}, ctx.rng);
  },
});

registerRollConsumer('xyxElder:shockstorm', (state, cardDb, _source, _payload, finalRoll, rng) => {
  for (const creature of allCreaturesInPlay(state, cardDb)) {
    const name = cardDb.get(creature.definitionKey)?.name ?? '';
    if (!name.includes('Xyx')) {
      discardEnergy(state, cardDb, creature, finalRoll, undefined, undefined, rng);
    }
  }
});
