// Heat of Day (Spell) -- "Choose a number of Creatures up to the number of cards in your hand.
// Discard one energy from each chosen Creature." A variable-count multi-select from your own
// Creatures, count only bounded (not fixed) by hand size -- reuses registry.ts's
// pendingMultiTargetChoice/resolveMultiTargetChoice post-hoc multi-select family (Weave Mat's own
// precedent) rather than a new up-front mechanism: resolveSpell just arms a pending-choice tag (the
// Spell itself discards normally right after, and the pending-choice scan still finds it sitting in
// the discard pile -- same "still-findable after resolving" shape Redream's own two-step discard
// prompt relies on).

import { registerCardEffect } from './registry.js';
import { discardEnergy } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { creaturesControlledBy } from '../targeting.js';

const AWAITING_CHOICE = 'heatOfDayAwaitingChoice';

registerCardEffect('Heat of Day', {
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    if (player.hand.length === 0) return;
    if (creaturesControlledBy(ctx.state, ctx.cardDb, player.playerId).length === 0) return;
    addPendingChoiceTag(ctx.source, AWAITING_CHOICE);
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const player = state.players.get(self.controllerId);
    if (!player) return undefined;
    const pool = creaturesControlledBy(state, cardDb, self.controllerId);
    const maxCount = Math.min(pool.length, player.hand.length);
    if (pool.length === 0 || maxCount === 0) return undefined;
    return {
      prompt: 'Heat of Day: choose up to your hand size in Creatures to discard one energy from each',
      pool: pool.map((c) => c.instanceId),
      minCount: 0,
      maxCount,
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds, rng) => {
    removePermanentTag(self, AWAITING_CHOICE);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const pool = creaturesControlledBy(state, cardDb, self.controllerId);
    const poolIds = new Set(pool.map((c) => c.instanceId));
    const maxCount = Math.min(pool.length, player.hand.length);
    const chosen = [...new Set(chosenInstanceIds ?? [])].filter((id) => poolIds.has(id)).slice(0, maxCount);
    for (const id of chosen) {
      const target = pool.find((c) => c.instanceId === id);
      if (target) discardEnergy(state, cardDb, target, 1, 'spell', undefined, rng);
    }
  },
});
