// Granite Parmalag -- both printed pieces:
//   "Rock Solid: All of your Parmalags in play lose one less energy in attacks." A third-party
//   grant to every "Parmalag"-type Creature (targeting.ts's creatureType) involved in THIS
//   combat, including Granite Parmalag itself -- which stacks with its own separate
//   Invulnerability below, for -2 total on itself specifically.
//   "Invulnerability: Granite Parmalag loses one less energy in attacks." (invulnerability.ts)

import { registerCardEffect } from './registry.js';
import { creatureType } from '../targeting.js';
import { applyInvulnerability } from './invulnerability.js';
import type { CardInstance } from '../types/instance.js';

registerCardEffect('Granite Parmalag', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Rock Solid and Invulnerability both
  // live in the single onAttack body (Rock Solid broadcasts +1 protection to Parmalag-type
  // Creatures, Invulnerability reduces self's own loss); field-level narrowing can't split them.
  // A Taglat copy of either exposes onAttack.
  effectHooks: {
    'Rock Solid': ['onAttack'],
    Invulnerability: ['onAttack'],
  },
  onAttack: (ctx, self) => {
    applyInvulnerability(ctx, self, 1);
    for (const combatant of [ctx.attacker, ctx.defender]) {
      if (!combatant) continue;
      const c = combatant as CardInstance;
      if (c.controllerId === self.controllerId && creatureType(ctx.cardDb, c.definitionKey) === 'Parmalag') {
        // 4th arg: this grant comes from Granite Parmalag, not from `c` itself, so a Creature
        // whose own text refuses outside protection (Tunnel Parmalag) correctly declines it.
        applyInvulnerability(ctx, c, 1, self);
      }
    }
  },
});
