// Wence's Travelog -- "Wence Was Here: During your Energize step, if you have a Naroom Creature
// and a different Weave Creature in play, add two energy to your Magi." onOwnTurnStart fires
// immediately before the Energize step begins (turn.ts's beginTurn), so this is a same-turn
// approximation of "during your Energize step" -- documented simplification, same class as
// Shryque/Gar's Draw-step approximations below.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { creaturesControlledBy, effectiveRegions } from '../targeting.js';

registerCardEffect("Wence's Travelog", {
  onOwnTurnStart: (state, cardDb, self) => {
    const owned = creaturesControlledBy(state, cardDb, self.controllerId);
    const naroomCreature = owned.find((c) => effectiveRegions(state, cardDb, c).includes('Naroom'));
    const weaveCreature = owned.find(
      (c) => effectiveRegions(state, cardDb, c).includes('Weave') && c.instanceId !== naroomCreature?.instanceId
    );
    if (!naroomCreature || !weaveCreature) return;
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (magi) addEnergy(state, cardDb, magi, 2, 'effect');
  },
});
