// Crushing Ice (Spell) -- "Choose an opposing Creature. Discard four energy from the chosen
// Creature. If this discards that Creature from play, discard three energy from the chosen
// Creature's Magi. Only Nar and Nar Shadow Magi can play Crushing Ice." Nar Spell pass, Category A
// (2026-07-22). The region restriction is fully data-driven (region_restrictive + shadow_play:
// "Nar" on the card's own definition, enforced generically by regions.ts) -- zero code needed.
// The "discard 4; if it dies, hit its Magi" half is crushingStench.ts's/crushingSands.ts's own
// exact discardEnergy -> checkCreatureDefeats -> re-check-findInPlayById structure.

import { registerCardEffect } from './registry.js';
import { opposingCreatures, findInPlayById } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import { checkCreatureDefeats } from '../energy.js';

registerCardEffect('Crushing Ice', {
  spellTargets: (state, cardDb, playerId) => opposingCreatures(state, cardDb, playerId),
  resolveSpell: (ctx) => {
    const target = opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c) => c.instanceId === ctx.chosenTargetId
    );
    if (!target) return;
    const magiId = target.controllerId;

    discardEnergy(ctx.state, ctx.cardDb, target, 4, 'spell', undefined, ctx.rng);
    checkCreatureDefeats(ctx.state, ctx.cardDb, 'spell', undefined, ctx.rng);
    if (findInPlayById(ctx.state, target.instanceId)) return; // wasn't discarded -- no follow-up

    const magi = ctx.state.players.get(magiId)?.activeMagi;
    if (magi) discardEnergy(ctx.state, ctx.cardDb, magi, 3, 'spell', undefined, ctx.rng);
  },
});
