// Greater Vaal -- "Immolate (5): Roll two dice. Choose any one Creature or Magi in play. Discard
// energy equal to the dice total from the chosen Creature or Magi." Same "Creature or Magi"
// target shape as Grega/Grega's Ring, but the first card to roll TWO dice and sum them rather
// than one -- not to be confused with the unrelated card just named "Vaal" (its "Shield" Power is
// a persistent status effect, a different, still-deferred category; see task #26).
//
// Whimsy refactor (Category D SEVENTH item, 2026-08-12, task #724): same two-die chain pattern
// as cragnoc.ts -- two sequential requestDieRoll calls, sum applied by die 2's consumer.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';

registerCardEffect('Greater Vaal', {
  powerTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Immolate') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target) return;
    requestDieRoll(
      ctx.state,
      ctx.cardDb,
      ctx.source,
      ctx.source.controllerId,
      6,
      'greaterVaal:immolate:die1',
      { targetId: target.instanceId },
      ctx.rng
    );
  },
});

registerRollConsumer('greaterVaal:immolate:die1', (state, cardDb, source, payload, finalRoll, rng) => {
  if (!source) return;
  const { targetId } = payload as { targetId: string };
  requestDieRoll(
    state,
    cardDb,
    source,
    source.controllerId,
    6,
    'greaterVaal:immolate:die2',
    { targetId, die1: finalRoll },
    rng
  );
});

registerRollConsumer('greaterVaal:immolate:die2', (state, cardDb, _source, payload, finalRoll, rng) => {
  const { targetId, die1 } = payload as { targetId: string; die1: number };
  const target = findCreatureOrMagiById(state, targetId);
  if (!target) return;
  discardEnergy(state, cardDb, target, die1 + finalRoll, undefined, undefined, rng);
});
