// Enrich (Spell, Underneath, cost 1) -- "Choose any one burrowed Creature in play. Add three
// energy to the chosen Creature." Pure reuse of the generic BURROWED reader (durationTags.ts's
// isBurrowed, which already accounts for both the duration tag AND broadcast grants like Tunnel
// Hyren's / Granas' / Urigant's conditional burrowing) -- deliberately NOT a raw
// hasDurationTag(BURROWED) check, which would miss every granted-burrow case.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';
import { isBurrowed } from '../durationTags.js';

registerCardEffect('Enrich', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => isBurrowed(state, cardDb, c)),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const target = allCreaturesInPlay(ctx.state, ctx.cardDb).find((c) => c.instanceId === ctx.chosenTargetId);
    if (!target || !isBurrowed(ctx.state, ctx.cardDb, target)) return; // re-validate at resolution
    addEnergy(ctx.state, ctx.cardDb, target, 3, 'spell');
  },
});
