// Barak's Ring -- "Purity: At the end of your turn, if all Spells in your discard pile are Cald,
// discard all of your non-Cald cards from play and discard one energy from each opposing Creature
// in play."

import { registerCardEffect } from './registry.js';
import { applyPurity } from './purityRing.js';
import { discardEnergy } from '../effects.js';
import { opposingCreatures } from '../targeting.js';

registerCardEffect("Barak's Ring", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, 'Cald', rng)) return;
    for (const creature of opposingCreatures(state, cardDb, self.controllerId)) {
      discardEnergy(state, cardDb, creature, 1, 'effect');
    }
  },
});
