// Inyx -- both printed clauses:
//   "Vitalize (1): If there is at least one opposing Creature in play, add one energy to each
//   Creature in play."
//   "Dreamwarp: As you play Inyx, increase or decrease its starting energy by up to the number of
//   other Paradwyn Creatures that you have in play, until the end of the turn." (registry.ts's
//   dreamwarpRange -- the one Dreamwarp card whose range is board-state-dependent rather than a
//   flat constant.) play.ts's playCard adds a Creature to `inPlay` BEFORE calling this hook, so
//   Inyx itself is already present in `creaturesControlledBy` at this point -- explicitly excluded
//   by instanceId to get "OTHER Paradwyn Creatures" right (confirmed by a real test failure).

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creaturesControlledBy, effectiveRegions, opposingCreatures } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Inyx', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Vitalize') return;
    if (opposingCreatures(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).length === 0) return;

    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      addEnergy(ctx.state, ctx.cardDb, creature, 1, 'power');
    }
  },
  dreamwarpRange: (state, cardDb, playerId, self) =>
    creaturesControlledBy(state, cardDb, playerId).filter(
      (c) => c.instanceId !== self.instanceId && effectiveRegions(state, cardDb, c).includes('Paradwyn')
    ).length,
});
