// Dreamcatcher -- "Absorb: Once per turn, after an opponent plays a Creature, you may move up to
// two energy from that Creature to a Creature you control." Broadcast onPlay reactor, once-per-
// turn tag (same convention as J'lith's Collector/Koza's Steal).
//
// The "may" choice is still auto-taken whenever legal (out of scope for Phase 4c). "A Creature you
// control" is now a real pending choice (Phase 4c, 2026-07-11, registry.ts's pendingTargetChoice/
// resolveTargetChoice) over every own Creature, instead of the earlier "controller's own largest
// Creature" simplification. The recipient tag remembers which opposing Creature to drain from,
// since the pending choice may not be resolved until after other actions happen in between.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { addDurationTag, addPermanentTag, hasDurationTag, removePermanentTag } from '../durationTags.js';

const ABSORB_USED_THIS_TURN = 'dreamcatcherAbsorbUsedThisTurn';
const ABSORB_PENDING_PREFIX = 'dreamcatcherAbsorbPending:';

function pendingAbsorbSourceId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(ABSORB_PENDING_PREFIX)) return tag.slice(ABSORB_PENDING_PREFIX.length);
  }
  return undefined;
}

registerCardEffect('Dreamcatcher', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId === self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Creature') return;
    if (hasDurationTag(self, ABSORB_USED_THIS_TURN)) return;
    if (creaturesControlledBy(state, cardDb, self.controllerId).length === 0) return;
    if ((played.currentEnergy ?? 0) <= 0) return;

    addPermanentTag(state, cardDb, self, `${ABSORB_PENDING_PREFIX}${played.instanceId}`);
    addDurationTag(state, cardDb, self, ABSORB_USED_THIS_TURN, state.turnNumber);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    const sourceId = pendingAbsorbSourceId(self);
    if (sourceId === undefined) return undefined;
    const pool = creaturesControlledBy(state, cardDb, self.controllerId);
    if (pool.length === 0) return undefined;
    return { prompt: "Dreamcatcher's Absorb: choose a Creature you control to move up to 2 energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    const sourceId = pendingAbsorbSourceId(self);
    if (sourceId === undefined) return;
    removePermanentTag(self, `${ABSORB_PENDING_PREFIX}${sourceId}`);
    if (!chosenInstanceId) return;
    const target = creaturesControlledBy(state, cardDb, self.controllerId).find((c) => c.instanceId === chosenInstanceId);
    if (!target) return;
    // The opposing source Creature may have left play since the trigger fired -- search both
    // players' inPlay (its controller may have changed too, e.g. via a gainControl effect).
    let source;
    for (const player of state.players.values()) {
      source = player.inPlay.find((c) => c.instanceId === sourceId);
      if (source) break;
    }
    if (!source) return;
    const amount = Math.min(2, source.currentEnergy ?? 0);
    if (amount > 0) rearrangeEnergy(state, cardDb, source, target, amount, rng);
  },
});
