// Poad, Innkeeper -- "Party (1): Choose one of your Creatures. Add energy to the chosen Creature
// equal to the number of Creatures you have in play. The chosen Creature cannot use Powers this
// turn. Discard the Creature at the end of the turn." First card using durationTags.ts's
// CANNOT_USE_POWER tag, alongside Bronn's DISCARD_AT_END_OF_TURN.
//
// "Hearty: Once per turn, when one of your Creatures is attacked, you may move any amount of
// energy from Poad to that Creature. Add an additional energy to the Creature if it is Nar or
// Naroom." Added task #45, 2026-07-18, the Naroom region pass -- the file previously only
// implemented Party. Same pendingPreCombatTargetChoice/onBeforeEnergyRemoved third-party-reactor
// shape as Silth Giant's Swallow Whole ("one of your Creatures" -- Poad needn't be a combatant
// itself), combined with Ugger's Borrow "amount" choice (PreCombatTargetResolution.amount) since
// this is "any amount," not a fixed value. No safe auto-pick default for an arbitrary amount (same
// reasoning as Ugger), so an unresolved choice is a no-op skip.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, findInPlayById, effectiveRegions } from '../targeting.js';
import { addEnergy, rearrangeEnergy } from '../effects.js';
import { addDurationTag, addPermanentTag, hasDurationTag, CANNOT_USE_POWER, DISCARD_AT_END_OF_TURN } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import type { PreCombatTargetResolution } from '../combat.js';

const HEARTY_USED_THIS_TURN = 'poadInnkeeperHeartyUsedThisTurn';

registerCardEffect('Poad, Innkeeper', {
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Party') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;

    const count = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).length;
    if (count > 0) addEnergy(ctx.state, ctx.cardDb, target, count, 'power');
    addRestrictionTag(ctx.state, target, CANNOT_USE_POWER, ctx.state.turnNumber);
    addPermanentTag(ctx.state, ctx.cardDb, target, DISCARD_AT_END_OF_TURN);
  },
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker, isDefender, attacker, defender) => {
    if (!defender) return undefined;
    if (defender.instanceId === self.instanceId) return undefined; // moving energy from Poad to itself is a no-op
    if (defender.controllerId !== self.controllerId) return undefined;
    if (hasDurationTag(self, HEARTY_USED_THIS_TURN)) return undefined;
    if ((self.currentEnergy ?? 0) <= 0) return undefined;
    return { prompt: "Poad, Innkeeper's Hearty: move energy from Poad to the attacked Creature (and how much)?", pool: [defender] };
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (!ctx.defender) return;
    if (ctx.defender.instanceId === self.instanceId) return;
    if (ctx.defender.controllerId !== self.controllerId) return;
    if (hasDurationTag(self, HEARTY_USED_THIS_TURN)) return;

    const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
    const resolution = resolutions?.[self.instanceId];
    if (!resolution || 'skip' in resolution) return;
    if (resolution.chosenInstanceId !== ctx.defender.instanceId) return;
    if (!resolution.amount || resolution.amount <= 0) return;

    addDurationTag(ctx.state, ctx.cardDb, self, HEARTY_USED_THIS_TURN, ctx.state.turnNumber);
    rearrangeEnergy(ctx.state, ctx.cardDb, self, ctx.defender, Math.min(resolution.amount, self.currentEnergy ?? 0), ctx.rng);

    const defenderRegions = effectiveRegions(ctx.state, ctx.cardDb, ctx.defender);
    if (defenderRegions.includes('Nar') || defenderRegions.includes('Naroom')) {
      addEnergy(ctx.state, ctx.cardDb, ctx.defender, 1, 'effect');
    }
  },
});
