// Paranoia (Spell, Core, cost 2) -- "Choose any one Creature in play. The chosen Creature can only
// attack if opposing Magi control no Creatures with six or more energy. Attach Paranoia to the
// chosen Creature. Discard Paranoia if the chosen Creature is discarded from play." Task #53-4,
// 2026-07-21, the Core Spell pass's A1 quick wins.
//
// "Attach... to the chosen Creature" here means Paranoia stays in play as its OWN instance
// (`spellStaysInPlay`, crystalVision.ts/voltShield.ts/sunburn.ts precedent) tracking the target by
// instance id, rather than physically nesting inside the target's own `attachedCards` zone
// (attachedCards.ts) -- that zone is for cards a specific HOLDER's own file knows to clean up on its
// own discard (Gia's Tome/Cauldron of Ice/etc., each self-registered), which doesn't fit here since
// the target could be ANY Creature in the game, none of which know Paranoia exists. Watching for the
// target's OWN discard via the standard onCardDiscardedFromPlay broadcast (same "any in-play card
// reacts to seeing another card leave play" shape as Twee's Regrow) sidesteps the still-open
// "attached cards don't decouple when an arbitrary holder leaves play" gap entirely.
//
// The conditional attack restriction itself needed a genuinely new hook -- registry.ts's
// `preventsAttackOf` (new this pass), a per-attacker broadcast re-checked live at every attack
// declaration, since the condition can change turn to turn and isn't a static CANNOT_ATTACK grant.
// "Opposing Magi" is relative to the CHOSEN Creature's own controller (whoever it would actually be
// attacking), not Paranoia's controller -- the two are usually the same in 1v1 but the printed text
// scopes it to the target's side.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, creaturesControlledBy } from '../targeting.js';
import { getOpponents } from '../types/state.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import { discardFromPlay } from '../effects.js';

const TARGET_PREFIX = 'paranoiaTarget:';

function trackedTargetId(self: { tags: ReadonlySet<string> }): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(TARGET_PREFIX));
  return tag ? tag.slice(TARGET_PREFIX.length) : undefined;
}

registerCardEffect('Paranoia', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    if (!ctx.chosenTargetId) return;
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${TARGET_PREFIX}${ctx.chosenTargetId}`);
    // spellStaysInPlay (Crystal Vision's mechanism, "resolveSpell is fully responsible for placing
    // the card somewhere") -- placed directly into player.inPlay rather than via attachedCards.ts's
    // attachCard, same reasoning as Crystal Vision: the new preventsAttackOf/onCardDiscardedFromPlay
    // broadcasts both scan activeMagi + inPlay only, never attachedCards.
    ctx.controllingPlayer.inPlay.push(ctx.source);
  },
  preventsAttackOf: (state, cardDb, self, attacker) => {
    const targetId = trackedTargetId(self);
    if (!targetId || attacker.instanceId !== targetId) return false;
    const opponents = getOpponents(state, attacker.controllerId);
    return opponents.some((p) => creaturesControlledBy(state, cardDb, p.playerId).some((c) => (c.currentEnergy ?? 0) >= 6));
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, _cause, _source, _causedByPlayerId, rng) => {
    const targetId = trackedTargetId(self);
    if (!targetId || discarded.instanceId !== targetId) return;
    removePermanentTag(self, `${TARGET_PREFIX}${targetId}`);
    const owner = state.players.get(self.controllerId);
    if (owner && owner.inPlay.some((c) => c.instanceId === self.instanceId)) {
      discardFromPlay(state, cardDb, owner, self.instanceId, undefined, undefined, rng);
    }
  },
});
