// Phlouk -- "Ring Testing: Play a Bograth Creature from your hand, ignoring all costs. That
// Creature cannot attack this turn. At the end of your turn, discard energy from Phlouk equal to
// the Creature's starting energy. If you don't have enough energy on Phlouk, discard the Creature
// from play."
//
// End-of-turn cleanup clause -- built inline this pass (deferred-list re-audit, 2026-08-13). The
// file's old comment cited "the same linked-instance tracking gap as Severos/Tidal Karak," which
// was stale: the permanent-tag pattern shipped several times since (Muck Rain's
// `muckRainPendingFor:<playerId>` tag surviving the Spell's zone move into the discard pile,
// Umbu's `umbuLockTarget:<instanceId>` naming the Relic Umbu is riding, Gherish's `driftSource:`)
// is exactly the "remember one instance id my past resolution targeted" primitive Severos et al.
// need. Ring Testing tags itself with `phloukRingTestingPlayed:<instanceId>` at the moment of
// play, and the onOwnTurnEnd hook (turn.ts's per-card sweep, includes the active Magi) reads it
// back and either discards the cost from Phlouk OR discards the played Creature from play if
// Phlouk can't cover it. The tag is cleared after the end-of-turn resolve regardless of outcome,
// so Ring Testing's end-of-turn clause fires ONCE (at the end of the play turn), not each
// subsequent turn -- the natural reading of the "That Creature cannot attack THIS turn. At the
// end of YOUR turn..." same-sentence "this turn" scoping (a lasting per-turn drain would print
// "at the end of each of your turns" instead, per every other continuous-tick card in the
// codebase). If the played Creature has already left play by end-of-turn (e.g. killed in combat),
// both branches are moot -- the discard-energy still fires because the printed cost is still
// owed, but the "discard the Creature" fallback is a no-op.

import { registerCardEffect } from './registry.js';
import { effectiveStartingEnergy } from '../targeting.js';
import { discardEnergy, discardFromPlay, playFromZone } from '../effects.js';
import { addPermanentTag, removePermanentTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import type { CardInstance } from '../types/instance.js';

const PLAYED_PREFIX = 'phloukRingTestingPlayed:';

function playedInstanceId(self: CardInstance): string | undefined {
  for (const tag of self.tags) if (tag.startsWith(PLAYED_PREFIX)) return tag.slice(PLAYED_PREFIX.length);
  return undefined;
}

registerCardEffect('Phlouk', {
  handPlayChoice: {
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes('Bograth');
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Ring Testing') return;
    if (!ctx.chosenHandPlayId) return;
    const handCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandPlayId);
    const def = handCard ? ctx.cardDb.get(handCard.definitionKey) : undefined;
    if (!def || def.card_type !== 'Creature' || !def.regions.includes('Bograth')) return;

    const played = playFromZone(
      ctx.state,
      ctx.cardDb,
      { owner: ctx.controllingPlayer, zone: 'hand', instanceId: ctx.chosenHandPlayId },
      ctx.controllingPlayer,
      effectiveStartingEnergy(ctx.state, ctx.cardDb, handCard!)
    , ctx.rng);
    if (played) {
      addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
      addPermanentTag(ctx.state, ctx.cardDb, ctx.source, `${PLAYED_PREFIX}${played.instanceId}`);
    }
  },
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    const playedId = playedInstanceId(self);
    if (!playedId) return;
    removePermanentTag(self, `${PLAYED_PREFIX}${playedId}`);
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const played = owner.inPlay.find((c) => c.instanceId === playedId);
    if (!played) return; // Creature already left play (combat, etc.); both branches are moot.
    const cost = effectiveStartingEnergy(state, cardDb, played);
    if ((self.currentEnergy ?? 0) >= cost) {
      discardEnergy(state, cardDb, self, cost, 'effect', self.controllerId);
    } else {
      discardFromPlay(state, cardDb, owner, played.instanceId, undefined, undefined, rng);
    }
  },
});
