// Brog -- "Fertilize: Whenever a Creature is discarded from play in an attack, add one energy to
// Brog." Uses energy.ts's new `source` distinction (2026-07-11) to require a combat-caused
// zero-energy defeat specifically -- fires for EITHER side's Creature.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Brog', {
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source) => {
    if (cause !== 'zero-energy' || source !== 'combat') return;
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Creature') return;

    addEnergy(state, cardDb, self, 1, 'effect');
  },
});
