// Blygt -- "Waking Dreams (3): Choose up to three different Bograth Creatures in your discard
// pile. An opposing player of your choice chooses one of the three Creatures. Shuffle the chosen
// Creature into your deck. Play each of the other two Creatures with one energy instead of their
// normal starting energy. Those Creatures cannot attack this turn."
//
// Real choice (task #40-2, 2026-07-17, player-choice-default retrofit, Group 2): two dependent
// `powerTargetSlots` -- slot 0 is the controller's "up to three" pick from the discard pile
// (`min: 0`); slot 1 is the OPPONENT's pick of exactly one of slot 0's chosen Creatures to shuffle
// away, using `priorChoices` to scope its pool to just what was actually chosen (same dependent-
// pool shape raskDeserter.ts's own doc comment names as the precedent), marked
// `respondingPlayer: 'opponent'` (documentation-only in this 2-player, single-screen engine, same
// as every other opponent-decision slot). 2-player only, so "an opposing player of your choice"
// collapses to "the opponent" -- no real choice there.

import { registerCardEffect } from './registry.js';
import { playFromZone } from '../effects.js';
import { addDurationTag, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';
import { regionForTargetFilter } from '../targeting.js';

function bograthInDiscard(state: Parameters<typeof playFromZone>[0], cardDb: Parameters<typeof playFromZone>[1], playerId: string) {
  const player = state.players.get(playerId)!;
  const region = regionForTargetFilter(state, 'Bograth');
  return player.discardPile.filter(
    (c) => cardDb.get(c.definitionKey)?.card_type === 'Creature' && cardDb.get(c.definitionKey)?.regions.includes(region)
  );
}

registerCardEffect('Blygt', {
  powerTargetSlots: (state, cardDb, playerId) => {
    const pool = bograthInDiscard(state, cardDb, playerId);
    return [
      {
        label: 'Choose up to three different Bograth Creatures in your discard pile',
        pool: (s, db, pid) => bograthInDiscard(s, db, pid),
        min: 0,
        max: Math.min(3, pool.length),
      },
      {
        label: "The opponent chooses one of the three Creatures to shuffle into your deck",
        pool: (s, db, pid, priorChoices) => {
          const chosenIds = priorChoices[0] ?? [];
          return bograthInDiscard(s, db, pid).filter((c) => chosenIds.includes(c.instanceId));
        },
        min: (priorChoices) => (priorChoices[0]?.length ? 1 : 0),
        max: (priorChoices) => (priorChoices[0]?.length ? 1 : 0),
        respondingPlayer: 'opponent',
      },
    ];
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Waking Dreams') return;
    const player = ctx.controllingPlayer;
    const chosenIds = ctx.chosenSlotIds?.[0] ?? [];
    if (chosenIds.length === 0) return;
    const shuffledAwayId = ctx.chosenSlotIds?.[1]?.[0];

    if (shuffledAwayId) {
      const index = player.discardPile.findIndex((c) => c.instanceId === shuffledAwayId);
      if (index !== -1) {
        const [card] = player.discardPile.splice(index, 1);
        player.deck.push(card!);
        // Fisher-Yates, matching setupGame's own shuffle convention.
        for (let i = player.deck.length - 1; i > 0; i--) {
          const j = Math.floor(ctx.rng() * (i + 1));
          [player.deck[i], player.deck[j]] = [player.deck[j]!, player.deck[i]!];
        }
      }
    }

    for (const id of chosenIds) {
      if (id === shuffledAwayId) continue;
      const played = playFromZone(ctx.state, ctx.cardDb, { owner: player, zone: 'discardPile', instanceId: id }, player, 1, ctx.rng);
      if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Bograth'],
});
