// Junjertrug -- "Rage: Whenever Junjertrug attacks, add two energy to it before energy is
// removed." "Hunger: Junjertrug must attack each turn if able." -- built now too (task #44 Part
// B, 2026-07-18, must-attack enforcement architecture), same standing-obligation shape as Garan's
// Rake: self-only, re-applied every turn via `onOwnTurnStart`.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { addDurationTag, MUST_ATTACK_THIS_TURN } from '../durationTags.js';

registerCardEffect('Junjertrug', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Rage is the pre-damage self-buff on
  // attack; Hunger is the per-turn must-attack retag.
  effectHooks: {
    Rage: ['onBeforeEnergyRemoved'],
    Hunger: ['onOwnTurnStart'],
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    addEnergy(ctx.state, ctx.cardDb, self, 2, 'effect');
  },
  onOwnTurnStart: (state, cardDb, self) => {
    addDurationTag(state, cardDb, self, MUST_ATTACK_THIS_TURN, state.turnNumber);
  },
});
