// Chaos Jile -- "Weakness: If Chaos Jile is attacked, discard three energy from it after energy
// is removed." / "Rebound: If Chaos Jile attacks a Creature, add four energy to it after energy
// is removed." Both afterCombat, both unconditional on outcome (fires whether or not either side
// survives), both direct self-energy changes.

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Chaos Jile', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Weakness (defender -> discard 3) and
  // Rebound (attacker vs Creature -> +4) both fold into a single `afterCombat` body that branches
  // on which side of the attack Chaos Jile is on. Structurally inseparable, so a Taglat narrow-copy
  // of either surfaces the same shared hook, matching whole-card grant. Annotated for metadata
  // explicitness.
  effectHooks: {
    Weakness: ['afterCombat'],
    Rebound: ['afterCombat'],
  },
  afterCombat: (ctx, outcome, self) => {
    if (ctx.defender?.instanceId === self.instanceId) {
      discardEnergy(ctx.state, ctx.cardDb, self, 3, 'effect', undefined, ctx.rng);
    } else if (ctx.attacker.instanceId === self.instanceId && ctx.defender !== null) {
      addEnergy(ctx.state, ctx.cardDb, self, 4, 'effect');
    }
  },
});
