// Shock Vashp -- "Shock: Choose any one Creature in play. Discard an Arderial Creature from your
// hand to discard two energy from the chosen Creature. If you discard a Vashp, discard an
// additional energy from the chosen Creature. Opposing cards do not affect Shock when it is used
// and may not alter the amount of energy discarded by Shock." (The last sentence is a static
// "can't be countered" clause -- nothing in this engine currently implements counter-effects to
// begin with, so it's a no-op by omission, not a gap.)

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById, regionForTargetFilter } from '../targeting.js';
import { discardEnergy, discardFromHand } from '../effects.js';

registerCardEffect('Shock Vashp', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  handDiscardCost: {
    count: 1,
    filter: (state, cardDb, playerId, card) => {
      const def = cardDb.get(card.definitionKey);
      return def?.card_type === 'Creature' && def.regions.includes(regionForTargetFilter(state, 'Arderial'));
    },
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Shock') return;
    if (ctx.chosenTargetId === undefined) return;
    if (!ctx.chosenHandCardIds || ctx.chosenHandCardIds.length < 1) return;
    const discardedCard = ctx.controllingPlayer.hand.find((c) => c.instanceId === ctx.chosenHandCardIds![0]);
    const discardedDef = discardedCard ? ctx.cardDb.get(discardedCard.definitionKey) : undefined;
    if (!discardedDef || discardedDef.card_type !== 'Creature' || !discardedDef.regions.includes(regionForTargetFilter(ctx.state, 'Arderial'))) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;

    const bonus = discardedDef.name.includes('Vashp') ? 1 : 0;
    discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.chosenHandCardIds.slice(0, 1), undefined, ctx.rng);
    discardEnergy(ctx.state, ctx.cardDb, target, 2 + bonus, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Arderial'],
});
