// Surf Diel -- "Reckon: Discard Surf Diel from play. Choose a Cald Creature in play. Discard the
// chosen Creature. Use this Power only before the Attack Step."
//
// "Comb the Beach: Whenever one of your Relics is discarded from play by an opposing card, add two
// energy to Surf Diel." (#536 C6d, 2026-07-27 -- the card-pool reconciliation found this Effect had
// no hook at all, so it never fired.)
//
// BROAD: "discarded from play" is unqualified, so no `cause` filter. Relics have no energy and so
// can never be DEFEATED, which makes the broad/narrow distinction moot in practice here -- but the
// filter is written by what the text requires, not by what is currently reachable, per #536.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, effectiveRegions, regionForTargetFilter } from '../targeting.js';
import { discardFromPlay, addEnergy } from '../effects.js';

registerCardEffect('Surf Diel', {
  legalPhases: ['prs1'],
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discardedOwnerId !== self.controllerId) return; // "one of YOUR Relics"
    if (causedByPlayerId === undefined || causedByPlayerId === self.controllerId) return; // "by an OPPOSING card"
    if (cardDb.get(discarded.definitionKey)?.card_type !== 'Relic') return;
    // Reckon discards Surf Diel itself, and a Relic of yours could leave play in the same
    // resolution -- only collect while Surf Diel is actually still in play.
    const owner = state.players.get(self.controllerId);
    if (!owner?.inPlay.some((c) => c.instanceId === self.instanceId)) return;

    addEnergy(state, cardDb, self, 2, 'effect');
  },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Cald'))),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Reckon') return;
    if (ctx.chosenTargetId === undefined) return;

    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, 'Cald'))) return;
    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ['Cald'],
});
