// Rayje's Boots -- "Non-Universal Magi may not play non-Universal Creatures that are not of their
// region." Identical shape to Rayje's Band (registry.ts's preventsPlayOf), for Creatures instead of
// Spells: a passive lockdown broadcast over both players' boards, restricting every non-Universal
// Magi (including this Relic's own controller). Universal Magi / Universal Creatures / a Creature of
// the acting Magi's own region are all unaffected.

import { registerCardEffect } from './registry.js';
import { isUniversal } from '../regions.js';

registerCardEffect("Rayje's Boots", {
  preventsPlayOf: (state, cardDb, playedDef, playerId) => {
    if (playedDef.card_type !== 'Creature' || isUniversal(playedDef.regions)) return false;
    const magi = state.players.get(playerId)?.activeMagi;
    const magiDef = magi ? cardDb.get(magi.definitionKey) : undefined;
    if (!magiDef || isUniversal(magiDef.regions)) return false; // only NON-Universal Magi are restricted
    return !magiDef.regions.some((r) => playedDef.regions.includes(r)); // "not of their region"
  },
});
