// Secrets of the Book -- "Secrets: Choose any one opposing player. The chosen player reveals his
// or her hand to all players. Draw one card for each Creature revealed, and one card for each
// non-Creature Naroom card revealed, to a maximum of four." The "to a maximum of four" cap is an
// official errata (2i Design ruling: "A maximum limit of four cards can be drawn through
// Secrets") -- it's in data-pipeline/output/rulings.json but NOT in the base scraped card text
// (cards_final.json), which is why the cap was missing entirely here; caught in playtesting
// (PROGRESS_LOG.md, 2026-07-09). "Reveal to all players" is a UI/knowledge concern, not a
// state-transition one -- the engine already has full access to the opponent's hand (only the UI
// hides it, per task #23), so this reads it directly rather than needing a new reveal mechanism.
// 2-player only, so "choose an opposing player" has exactly one legal choice -- no target needed.
// registry.ts's blocksHandReveal (task #29-3c, 2026-07-15: Storm Shield/Eyes of Arderial) --
// checked against the TARGET player's own board before reading their hand at all.

import { registerCardEffect } from './registry.js';
import { drawCards, revealHandToAll } from '../effects.js';
import { getOpponents } from '../types/state.js';
import { effectsFor } from '../grantedEffects.js';
import type { CardInstance } from '../types/instance.js';

registerCardEffect('Secrets of the Book', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Secrets') return;
    const opponent = getOpponents(ctx.state, ctx.controllingPlayer.playerId)[0];
    if (!opponent) return;
    const blockers: CardInstance[] = opponent.activeMagi ? [opponent.activeMagi, ...opponent.inPlay] : [...opponent.inPlay];
    for (const blocker of blockers) {
      for (const blockerEffect of effectsFor(ctx.state, ctx.cardDb, blocker)) {
        if (blockerEffect.blocksHandReveal?.(ctx.state, ctx.cardDb, blocker)) return;
      }
    }

    // PvP Step 3.5 item 3 (2026-08-02) -- "reveals his or her hand to all players" now actually
    // reaches a UI, not just the internal draw-count math below. See effects.ts's own doc comment.
    revealHandToAll(ctx.state, ctx.cardDb, opponent.playerId, ctx.source.instanceId);

    let count = 0;
    for (const card of opponent.hand) {
      const def = ctx.cardDb.get(card.definitionKey);
      if (!def) continue;
      if (def.card_type === 'Creature') count += 1;
      else if (def.regions.includes('Naroom')) count += 1;
    }
    count = Math.min(count, 4);
    if (count > 0) drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, count);
  },
});
