// Shadow Fird -- "Feed: After a Furok is discarded from play, you may play one copy of Shadow
// Fird from your discard pile, ignoring all costs."
//
// Built task #35, 2026-07-16 -- "Furok" is a creature TYPE (the last word of a card's own printed
// name, same convention targeting.ts's creatureType helper uses for Sarazen Outcast's Bane, etc.),
// not a database field. This is a genuinely new trigger shape: Shadow Fird reacts while sitting IN
// its controller's OWN discard pile, not while in play -- registry.ts's new
// `reactsFromDiscardPileToDiscard` hook (broadcast to every card in either player's discard pile,
// fired alongside the existing `onCardDiscardedFromPlay` broadcast from both places that already
// fire it) marks a pending choice, exposed via the existing `pendingTargetChoice`/
// `resolveTargetChoice` machinery (whose aggregator already scans discard piles) as a
// single-element pool -- there's nothing to pick, just confirm or decline. The play itself reuses
// `effects.ts`'s existing `playFromZone` primitive (built for Trulb's Dream Hatch/Warlum), which
// already supports pulling from `'discardPile'` with a set starting energy, ignoring cost entirely.
// No "your" qualifier on "a Furok is discarded" -- either side's Furok can trigger this.

import { registerCardEffect } from './registry.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { playFromZone } from '../effects.js';
import { effectiveStartingEnergy } from '../targeting.js';

const FEED_PENDING = 'shadowFirdFeedPending';

function isFurok(name: string): boolean {
  return name.trim().split(/\s+/).pop() === 'Furok';
}

registerCardEffect('Shadow Fird', {
  reactsFromDiscardPileToDiscard: (state, cardDb, self, discardedDef) => {
    if (!isFurok(discardedDef.name)) return;
    addPendingChoiceTag(self, FEED_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(FEED_PENDING)) return undefined;
    return { prompt: 'Feed: play Shadow Fird from your discard pile, ignoring all costs?', pool: [self] };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    if (!self.tags.has(FEED_PENDING)) return;
    removePermanentTag(self, FEED_PENDING);
    if (chosenInstanceId !== self.instanceId) return; // declined
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const startingEnergy = effectiveStartingEnergy(state, cardDb, self);
    playFromZone(state, cardDb, { owner, zone: 'discardPile', instanceId: self.instanceId }, owner, startingEnergy, rng);
  },
});
