// Icy Prison -- both printed clauses:
//   "Cold Comfort": "Reduce each Magi's Energize by the number of frozen Creatures that Magi has
//   in play." A global effect -- applies to BOTH players' Magi regardless of who controls Icy
//   Prison itself.
//   "If any player has no Creatures in play, discard Icy Prison from play." -- post-playtest
//   correctness pass follow-up (2026-07-12), via registry.ts's standingConditionMet hook
//   (effects.ts's sweepStandingConditions), the same mechanism built for Rous/Vrak/Furlosk. A
//   genuinely different shape from those three: checks EVERY player's board, not just Icy
//   Prison's own controller's -- the reason it wasn't folded into that batch.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy } from '../targeting.js';
import { isFrozen } from '../durationTags.js';

registerCardEffect('Icy Prison', {
  energizeRateModifier: (state, cardDb, energizing) => {
    if (cardDb.get(energizing.definitionKey)?.card_type !== 'Magi') return 0;
    const frozenCount = creaturesControlledBy(state, cardDb, energizing.controllerId).filter((c) => isFrozen(state, cardDb, c)).length;
    return -frozenCount;
  },
  standingConditionMet: (state, cardDb) =>
    [...state.players.keys()].some((playerId) => creaturesControlledBy(state, cardDb, playerId).length === 0),
});
