// Drum Solo (Spell, Paradwyn, cost 4) -- "Choose two Paradwyn Creatures. Restore each Creature to
// its printed starting energy." Two independent picks via spellTargets + spellSecondTargets
// (Abwyn's Gift precedent) -- the second pool just excludes whichever Creature was picked first,
// no other dependency on the first pick's outcome (unlike Crushing Surf/Tidal Wave's conditional
// pools).

import { registerCardEffect } from './registry.js';
import { restoreEnergy } from '../effects.js';
import { allCreaturesInPlay, effectiveRegions, printedStartingEnergy, regionForTargetFilter } from '../targeting.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState } from '../types/state.js';

function paradwynCreaturesInPlay(state: GameState, cardDb: CardDatabase) {
  return allCreaturesInPlay(state, cardDb).filter((c) => effectiveRegions(state, cardDb, c).includes(regionForTargetFilter(state, 'Paradwyn')));
}

registerCardEffect('Drum Solo', {
  spellTargets: (state, cardDb) => paradwynCreaturesInPlay(state, cardDb),
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) =>
    paradwynCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== firstChosenId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined) return;
    const pool = paradwynCreaturesInPlay(ctx.state, ctx.cardDb);
    const first = pool.find((c) => c.instanceId === ctx.chosenTargetId);
    if (first) restoreEnergy(ctx.state, ctx.cardDb, first, printedStartingEnergy(ctx.cardDb, first.definitionKey));

    if (ctx.chosenSecondTargetId === undefined || ctx.chosenSecondTargetId === ctx.chosenTargetId) return;
    const second = pool.find((c) => c.instanceId === ctx.chosenSecondTargetId);
    if (second) restoreEnergy(ctx.state, ctx.cardDb, second, printedStartingEnergy(ctx.cardDb, second.definitionKey));
  },
  specifiedSpellTargetRegions: () => ['Paradwyn'],
});
