// Ballistic Baldar -- "Fly Like a Rock: At the end of your turn, discard five energy from
// Ballistic Baldar. If Ballistic Baldar is still in play, roll a die. Choose a number of
// Creatures in play equal to the die roll. You cannot choose a Creature more than once. Discard
// three energy from each of the chosen Creatures." First onOwnTurnEnd user of the hook's own
// `rng` parameter (registry.ts, added for this card).
//
// Real choice (task #40-6, 2026-07-17, player-choice-default retrofit, Group 6): "choose a
// number of Creatures" doesn't say whose, but it IS a real player choice, not an auto-pick -- now
// a `pendingMultiTargetChoice`/`resolveMultiTargetChoice` (registry.ts's new multi-select
// post-hoc family). The die roll itself still happens synchronously in `onOwnTurnEnd` (it needs
// `rng`, only available at trigger time) and is remembered via an embedded-value permanent tag
// (`PENDING_PREFIX` + the rolled number) so repeated UI polls before the player answers keep
// seeing the same required count. No resolution (or an invalid/incomplete answer) falls back to
// the old array-order auto-pick (own side first, then opponent's), same convention as every other
// retrofitted card in this pass.

import { registerCardEffect } from './registry.js';
import { discardEnergy, requestDieRoll } from '../effects.js';
import { registerRollConsumer } from '../rollConsumers.js';
import { creaturesControlledBy, opposingCreatures, findInPlayById } from '../targeting.js';
import { addPermanentTag, removePermanentTag } from '../durationTags.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';
import type { CardInstance } from '../types/instance.js';

const PENDING_PREFIX = 'ballisticBaldarPendingRoll:';

function pendingRoll(self: { tags: ReadonlySet<string> }): number | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(PENDING_PREFIX)) {
      const n = Number(tag.slice(PENDING_PREFIX.length));
      return Number.isFinite(n) ? n : undefined;
    }
  }
  return undefined;
}

function pool(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  return [
    ...creaturesControlledBy(state, cardDb, self.controllerId),
    ...opposingCreatures(state, cardDb, self.controllerId),
  ];
}

registerCardEffect('Ballistic Baldar', {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    discardEnergy(state, cardDb, self, 5, 'effect');
    const player = state.players.get(self.controllerId);
    if (!player?.inPlay.some((c) => c.instanceId === self.instanceId)) return;
    requestDieRoll(state, cardDb, self, self.controllerId, 6, 'ballisticBaldar:flyLikeARock', {}, rng);
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    const roll = pendingRoll(self);
    if (roll === undefined) return undefined;
    const candidates = pool(state, cardDb, self);
    if (candidates.length === 0) return undefined;
    const count = Math.min(roll, candidates.length);
    return {
      prompt: `Ballistic Baldar's Fly Like a Rock: choose ${count} Creature${count === 1 ? '' : 's'} in play to discard three energy from each`,
      pool: candidates.map((c) => c.instanceId),
      minCount: count,
      maxCount: count,
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds, rng) => {
    const roll = pendingRoll(self);
    if (roll !== undefined) removePermanentTag(self, `${PENDING_PREFIX}${roll}`);
    if (roll === undefined) return;

    const candidates = pool(state, cardDb, self);
    const candidateIds = new Set(candidates.map((c) => c.instanceId));
    const count = Math.min(roll, candidates.length);

    let targetIds: string[];
    if (chosenInstanceIds) {
      const valid = [...new Set(chosenInstanceIds)].filter((id) => candidateIds.has(id)).slice(0, count);
      targetIds = valid.length === count ? valid : candidates.slice(0, count).map((c) => c.instanceId);
    } else {
      targetIds = candidates.slice(0, count).map((c) => c.instanceId);
    }

    for (const id of targetIds) {
      const target = findInPlayById(state, id);
      if (target) discardEnergy(state, cardDb, target, 3, 'effect', undefined, rng);
    }
  },
});

registerRollConsumer('ballisticBaldar:flyLikeARock', (state, cardDb, source, _payload, finalRoll) => {
  if (!source) return;
  // Only tag if source is still in play (Whimsy window could theoretically have discarded it via
  // some indirect route; the onOwnTurnEnd path above already checks this pre-roll, but re-check
  // defensively).
  const player = state.players.get(source.controllerId);
  if (!player?.inPlay.some((c) => c.instanceId === source.instanceId)) return;
  addPermanentTag(state, cardDb, source, `${PENDING_PREFIX}${finalRoll}`);
});
