// Energy Band -- "Charge (1): Use this Power only before your Attack Step. Choose any one
// Creature in play. Add two energy to the chosen Creature. That Creature must attack this turn,
// if able." The "must" half is built now too (task #44 Part B, 2026-07-18) --
// MUST_ATTACK_THIS_TURN (durationTags.ts). "Any one Creature in play" -- no ownership qualifier,
// so the target pool is `allCreaturesInPlay` (both sides); obligating an OPPONENT'S Creature to
// attack is a real, intentional use of this card (forcing a bad trade), not an oversight.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';
import { addDurationTag, MUST_ATTACK_THIS_TURN } from '../durationTags.js';

registerCardEffect('Energy Band', {
  legalPhases: ['prs1'],
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Charge') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    addEnergy(ctx.state, ctx.cardDb, target, 2, 'power');
    addDurationTag(ctx.state, ctx.cardDb, target, MUST_ATTACK_THIS_TURN, ctx.state.turnNumber);
  },
});
