// T'lok -- "Big Ol' Rock (3): Choose any one Magi with no Creatures in play. Discard ten energy
// from the chosen Magi." Magi-only target, filtered by that Magi's controller having zero
// Creatures currently in play.

import { registerCardEffect } from './registry.js';
import { allMagiInPlay, allCreaturesInPlay, findCreatureOrMagiById, isValidTargetGivenFlexibility, flexibleTargetPool } from '../targeting.js';
import { discardEnergy } from '../effects.js';
import type { CardDatabase } from '../types/card.js';
import type { GameState, PlayerId } from '../types/state.js';

function hasNoCreatures(state: GameState, cardDb: CardDatabase, controllerId: PlayerId): boolean {
  const player = state.players.get(controllerId);
  return !player || player.inPlay.every((c) => cardDb.get(c.definitionKey)?.card_type !== 'Creature');
}

registerCardEffect("T'lok", {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn (naturalType 'Magi', alternate
  // Creature). Note a Crown-granted Creature target would always fail hasNoCreatures below (the
  // target itself is one of its controller's in-play Creatures), so this is correct but never
  // actually reachable -- same "harmless" shape as Kwup's STALKED tag.
  powerTargets: (state, cardDb, playerId) =>
    flexibleTargetPool(state, cardDb, playerId, allMagiInPlay(state), allCreaturesInPlay(state, cardDb)).filter((m) =>
      hasNoCreatures(state, cardDb, m.controllerId)
    ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Big Ol' Rock") return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Magi')) return;
    if (!hasNoCreatures(ctx.state, ctx.cardDb, target.controllerId)) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 10, undefined, undefined, ctx.rng);
  },
});
