// Volt Shield (2-cost Spell) -- "Choose a Creature in play and attach Volt Shield to it. If that
// Creature would be affected by an opposing non-Arderial Spell, you may discard Volt Shield from
// play. If you do, the Creature is unaffected by that Spell." Task #50, 2026-07-20, Arderial
// Category D -- the first (and so far only) Spell that stays in play instead of the normal
// "resolves once, straight to the discard pile" default (registry.ts's `spellStaysInPlay`).
//
// SIMPLIFICATION, documented rather than silently dropped: only covers single-target opposing
// Spells (`offersAttachedSpellNegation`'s own doc comment). A board-wide effect (Cataclysm-style)
// is out of scope -- "protect one Creature from an effect that also hits everyone else" would need
// per-target opt-out threaded through every resolveSpell body, not just a pre-resolution check.

import { registerCardEffect } from './registry.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import { allCreaturesInPlay, findCreatureOrMagiById } from '../targeting.js';
import { attachCard, detachCard } from '../attachedCards.js';
import { moveToDiscardPile } from '../zones.js';

/** Finds whichever in-play card/Magi (either side) currently holds `self` in its attachedCards --
 *  CardInstance has no back-reference to its holder, so this is a small forward scan. */
function findHolderOf(state: GameState, self: CardInstance): CardInstance | undefined {
  for (const player of state.players.values()) {
    const candidates: CardInstance[] = player.activeMagi ? [...player.inPlay, player.activeMagi] : [...player.inPlay];
    for (const holder of candidates) {
      if (holder.attachedCards.some((c) => c.instanceId === self.instanceId)) return holder;
    }
  }
  return undefined;
}

registerCardEffect('Volt Shield', {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId ?? '');
    if (!target) return;
    attachCard(target, ctx.source);
  },
  offersAttachedSpellNegation: (state, cardDb, self, targetedInstanceId, spellDef) => {
    if (spellDef.regions.includes('Arderial')) return false; // "non-Arderial Spell" only
    const holder = findHolderOf(state, self);
    if (!holder || holder.instanceId !== targetedInstanceId) return false;
    return true;
  },
  resolveAttachedSpellNegation: (state, cardDb, self) => {
    const holder = findHolderOf(state, self);
    if (!holder) return;
    const detached = detachCard(holder, self.instanceId);
    if (!detached) return;
    const owner = state.players.get(detached.ownerId);
    if (owner) moveToDiscardPile(state, owner, detached);
  },
});
