// Flame Control (Spell, Cald, cost 1) -- "Rearrange the energy on your Creatures as you wish."
// Cald Spell pass, Category C (2026-07-20).
//
// A true many-to-many free reallocation across an arbitrary number of the caster's own Creatures
// has no existing one-shot primitive (effects.ts's rearrangeEnergy only moves a fixed amount
// between ONE source and ONE target per call). Built the same way as Bombard's split (this same
// pass): a small local state machine on the Spell's own (already discarded) instance, repeating a
// source-pick / destination-pick / amount-pick cycle via the existing pendingTargetChoice
// (reused for BOTH the source and destination picks, distinguished by which phase tag is active)
// and pendingNumericChoice post-hoc families, looping back to another source pick after each
// completed move until the player declines the source pick (their way of saying "done
// rearranging") -- unlike Bombard there's no fixed pool being divided and no round cap, matching
// "as you wish" being genuinely unbounded. Each amount is re-validated live against the chosen
// source's CURRENT energy at resolution time (rearrangeEnergy's own clamp), not a snapshot from
// when the round started, since an earlier round in the same resolution can change it.

import { registerCardEffect } from './registry.js';
import { rearrangeEnergy } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import type { CardInstance } from '../types/instance.js';
import type { GameState } from '../types/state.js';
import type { CardDatabase } from '../types/card.js';

const AWAITING_SOURCE = 'flameControlAwaitingSource';
const AWAITING_DESTINATION = 'flameControlAwaitingDestination';
const AWAITING_AMOUNT = 'flameControlAwaitingAmount';
const SOURCE_PREFIX = 'flameControlSource:';
const DESTINATION_PREFIX = 'flameControlDestination:';

function taggedId(self: CardInstance, prefix: string): string | undefined {
  const tag = [...self.tags].find((t) => t.startsWith(prefix));
  return tag ? tag.slice(prefix.length) : undefined;
}

function ownCreatures(state: GameState, cardDb: CardDatabase, self: CardInstance): CardInstance[] {
  return creaturesControlledBy(state, cardDb, self.controllerId);
}

registerCardEffect('Flame Control', {
  resolveSpell: (ctx) => {
    // Need at least 2 own Creatures -- a lone Creature could be picked as a source but would then
    // have no valid destination, leaving the card stuck mid-sequence with no way to decline.
    if (ownCreatures(ctx.state, ctx.cardDb, ctx.source).length >= 2) {
      addPendingChoiceTag(ctx.source, AWAITING_SOURCE);
    }
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (self.tags.has(AWAITING_SOURCE)) {
      const pool = ownCreatures(state, cardDb, self).filter((c) => (c.currentEnergy ?? 0) > 0);
      if (pool.length === 0) return undefined;
      return { prompt: 'Flame Control: choose a Creature to move energy FROM (or decline to finish)', pool };
    }
    if (self.tags.has(AWAITING_DESTINATION)) {
      const sourceId = taggedId(self, SOURCE_PREFIX);
      const pool = ownCreatures(state, cardDb, self).filter((c) => c.instanceId !== sourceId);
      if (pool.length === 0) return undefined;
      return { prompt: 'Flame Control: choose a Creature to move that energy TO', pool };
    }
    return undefined;
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    if (self.tags.has(AWAITING_SOURCE)) {
      removePermanentTag(self, AWAITING_SOURCE);
      if (!chosenInstanceId) return; // decline -- done rearranging
      const source = ownCreatures(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
      if (!source || (source.currentEnergy ?? 0) <= 0) return;
      addPermanentTag(state, cardDb, self, `${SOURCE_PREFIX}${chosenInstanceId}`);
      addPendingChoiceTag(self, AWAITING_DESTINATION);
      return;
    }
    if (self.tags.has(AWAITING_DESTINATION)) {
      removePermanentTag(self, AWAITING_DESTINATION);
      const sourceId = taggedId(self, SOURCE_PREFIX);
      if (!chosenInstanceId || !sourceId) {
        // Declined the destination pick -- abandon this pair, offer another source pick.
        if (sourceId) removePermanentTag(self, `${SOURCE_PREFIX}${sourceId}`);
        if (ownCreatures(state, cardDb, self).length >= 2) addPendingChoiceTag(self, AWAITING_SOURCE);
        return;
      }
      const dest = ownCreatures(state, cardDb, self).find((c) => c.instanceId === chosenInstanceId);
      if (!dest || chosenInstanceId === sourceId) {
        removePermanentTag(self, `${SOURCE_PREFIX}${sourceId}`);
        if (ownCreatures(state, cardDb, self).length >= 2) addPendingChoiceTag(self, AWAITING_SOURCE);
        return;
      }
      addPermanentTag(state, cardDb, self, `${DESTINATION_PREFIX}${chosenInstanceId}`);
      addPendingChoiceTag(self, AWAITING_AMOUNT);
    }
  },
  pendingNumericChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_AMOUNT)) return undefined;
    const sourceId = taggedId(self, SOURCE_PREFIX);
    const source = sourceId ? ownCreatures(state, cardDb, self).find((c) => c.instanceId === sourceId) : undefined;
    const max = source?.currentEnergy ?? 0;
    if (max <= 0) return undefined;
    return { prompt: 'Flame Control: how much energy to move?', min: 0, max };
  },
  resolveNumericChoice: (state, cardDb, self, chosen, rng) => {
    removePermanentTag(self, AWAITING_AMOUNT);
    const sourceId = taggedId(self, SOURCE_PREFIX);
    if (sourceId) removePermanentTag(self, `${SOURCE_PREFIX}${sourceId}`);

    const destId = taggedId(self, DESTINATION_PREFIX);
    if (destId) removePermanentTag(self, `${DESTINATION_PREFIX}${destId}`);

    if (sourceId && destId && chosen > 0) {
      const source = ownCreatures(state, cardDb, self).find((c) => c.instanceId === sourceId);
      const dest = ownCreatures(state, cardDb, self).find((c) => c.instanceId === destId);
      if (source && dest) rearrangeEnergy(state, cardDb, source, dest, chosen, rng);
    }

    if (ownCreatures(state, cardDb, self).length > 0) addPendingChoiceTag(self, AWAITING_SOURCE);
  },
});
