// Gorgle's Gift (Spell) -- "If you have a Creature in play, choose any one Creature in play.
// Discard seven energy from the chosen Creature. Return any one of your Creatures in play to your
// hand, discarding all of that Creature's energy." Cald Spell pass, Category A (2026-07-20).
// Near-1:1 structural match with abwynsGift.ts: same castability gate (spellTargets returns []
// with no Creature in play), same spellSecondTargets two-independent-picks shape,
// discardEnergy(7)/returnToHand swapped in for Abwyn's Gift's discardFromPlay/returnToHand.
// returnToHand already zeroes the returned card's energy (effects.ts), so "discarding all of that
// Creature's energy" needs no extra code.

import { registerCardEffect } from './registry.js';
import { discardEnergy, returnToHand } from '../effects.js';
import { allCreaturesInPlay, creaturesControlledBy, findInPlayById } from '../targeting.js';

registerCardEffect("Gorgle's Gift", {
  spellTargets: (state, cardDb, playerId) =>
    creaturesControlledBy(state, cardDb, playerId).length > 0 ? allCreaturesInPlay(state, cardDb) : [],
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) =>
    creaturesControlledBy(state, cardDb, playerId).filter((c) => c.instanceId !== firstChosenId),
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === undefined || ctx.chosenSecondTargetId === undefined) return;
    if (ctx.chosenTargetId === ctx.chosenSecondTargetId) return;
    const discardTarget = findInPlayById(ctx.state, ctx.chosenTargetId);
    const returnTarget = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (!discardTarget || ctx.cardDb.get(discardTarget.definitionKey)?.card_type !== 'Creature') return;
    if (!returnTarget || returnTarget.controllerId !== ctx.controllingPlayer.playerId) return;
    if (ctx.cardDb.get(returnTarget.definitionKey)?.card_type !== 'Creature') return;

    discardEnergy(ctx.state, ctx.cardDb, discardTarget, 7, 'spell', undefined, ctx.rng);

    // Discarding energy from the first target can't discard IT from play (Gorgle's Gift has no
    // "if this defeats it" clause the way Crushing Stench does), but re-check the second target is
    // still there before returning it anyway, matching abwynsGift.ts's own defensive re-check.
    const stillThere = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (stillThere) returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, stillThere.instanceId);
  },
});
