// Harresh -- "Time Shuffle: Draw two cards. Place one card from your hand at the bottom of your
// deck." Uses handDiscardCost purely as a "let the player choose one hand card" UI offering --
// resolvePower moves it to the deck instead of discarding it, the same "the field just offers a
// hand pool, resolvePower decides what happens to the chosen ids" latitude Xandia/Emaya rely on.

import { registerCardEffect } from './registry.js';
import { drawCards, moveHandCardToDeck } from '../effects.js';

registerCardEffect('Harresh', {
  handDiscardCost: { count: 1 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Time Shuffle') return;
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 2);
    const id = (ctx.chosenHandCardIds ?? [])[0];
    if (!id || !ctx.controllingPlayer.hand.some((c) => c.instanceId === id)) return;
    moveHandCardToDeck(ctx.state, ctx.cardDb, ctx.controllingPlayer, id, 'bottom', ctx.rng);
  },
});
