// Tragan -- both printed effects:
//   "Weakness: If Tragan is attacked, discard two energy from Tragan before energy is removed."
//   (onBeforeEnergyRemoved, self=defender -- a direct discardEnergy on itself, correctly counting
//   toward the damage Tragan deals back this attack per its own "before energy is removed" text)
//   "Boost: When Tragan is played, add three energy to it." (onPlay, self-trigger)

import { registerCardEffect } from './registry.js';
import { addEnergy, discardEnergy } from '../effects.js';

registerCardEffect('Tragan', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Boost is the on-play +3; Weakness is
  // the "if attacked, discard 2 before energy is removed" self-discard. No shared hooks --
  // either Effect narrows cleanly.
  effectHooks: {
    Boost: ['onPlay'],
    Weakness: ['onBeforeEnergyRemoved'],
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    addEnergy(state, cardDb, self, 3, 'effect');
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.defender?.instanceId !== self.instanceId) return;
    discardEnergy(ctx.state, ctx.cardDb, self, 2, 'effect', undefined, ctx.rng);
  },
});
