// Urigant -- three Effects:
//   "Burrow: As long as you have a burrowed Creature in play, Urigant is burrowed; it cannot
//   attack and loses no more than two energy per turn from attacks and opposing Spells and
//   Powers." (isConditionallyBurrowed.)
//   "Dig Up: All other burrowed Creatures in play lose energy as normal in attacks." (the
//   suppression itself lives in durationTags.ts's burrowCappedLoss -- a single hardcoded check,
//   same shape as weave.ts's Ushi check -- since it needs to intercept the ONE shared primitive
//   both combat and opposing Spells/Powers already funnel through.)
//   "Invulnerability: Urigant loses two less energy in attacks." (reduces Urigant's own combat
//   loss on either side, same shape as Odavast's Ice Wall.)

import { registerCardEffect } from './registry.js';
import { cardLocalCombatReductionBlocked } from '../effects.js';
import { creaturesControlledBy } from '../targeting.js';
import { isBurrowed } from '../durationTags.js';

registerCardEffect('Urigant', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Burrow owns isConditionallyBurrowed;
  // Invulnerability owns onAttack. Dig Up lives in durationTags.ts's burrowCappedLoss (a shared
  // primitive that suppresses the cap for other burrowed Creatures whenever an Urigant is in
  // play) -- no hook on this registration, so it's listed with an empty array. A Taglat copy of
  // Dig Up therefore runs nothing on Taglat itself; the "if an Urigant is in play" broadcast
  // wouldn't extend to Taglat via a grant regardless.
  effectHooks: {
    Burrow: ['isConditionallyBurrowed'],
    'Dig Up': [],
    Invulnerability: ['onAttack'],
  },
  isConditionallyBurrowed: (state, cardDb, instance) =>
    creaturesControlledBy(state, cardDb, instance.controllerId).some(
      (c) => c.instanceId !== instance.instanceId && isBurrowed(state, cardDb, c)
    ),
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId === self.instanceId) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'defenderOutput', self)) ctx.locked.defenderEnergy = Math.max(0, ctx.locked.defenderEnergy - 2);
    }
    if (ctx.defender !== null && ctx.defender.instanceId === self.instanceId) {
      if (!cardLocalCombatReductionBlocked(ctx.state, ctx.cardDb, ctx.attacker, ctx.defender, 'attackerOutput', self)) ctx.locked.attackerEnergy = Math.max(0, ctx.locked.attackerEnergy - 2);
    }
  },
});
