// Darbok -- "Divebomb (1): Choose one of your other Creatures and an opposing Creature. Return
// your chosen Creature to your hand, discarding its energy. Discard four energy from the
// opposing chosen Creature." First card using registry.ts's powerTargetSlots -- two independent
// single picks (own Creature, then opposing Creature), rather than the simpler single-target
// powerTargets.

import { registerCardEffect } from './registry.js';
import { creaturesControlledBy, opposingCreatures, opposingMagi, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, returnToHand } from '../effects.js';

registerCardEffect('Darbok', {
  // Slot 1's pool now excludes Darbok itself precisely, even with up to 3 copies legally in play
  // (2026-07-08 fix -- see registry.ts's powerTargets doc comment). resolvePower still rejects a
  // self-pick too, same "the resolve function re-validates" pattern every other card relies on.
  powerTargetSlots: (state, cardDb, playerId, _powerName, sourceInstanceId) => [
    {
      label: 'Choose one of your other Creatures',
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid).filter((c) => c.instanceId !== sourceInstanceId),
      min: 1,
      max: 1,
    },
    {
      // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- this slot feeds
      // discardEnergy, the OWN slot above doesn't (see resolvePower's own comment below).
      label: 'Choose an opposing Creature',
      pool: (s, db, pid) => flexibleTargetPool(s, db, pid, opposingCreatures(s, db, pid), opposingMagi(s, db, pid)),
      min: 1,
      max: 1,
    },
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Divebomb') return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const ownTargetId = slots[0]?.[0];
    const oppTargetId = slots[1]?.[0];
    if (!ownTargetId || !oppTargetId) return;
    if (ownTargetId === ctx.source.instanceId) return; // must be an OTHER Creature

    const ownTarget = findCreatureOrMagiById(ctx.state, ownTargetId);
    if (!ownTarget || ctx.cardDb.get(ownTarget.definitionKey)?.card_type !== 'Creature') return;
    if (ownTarget.controllerId !== ctx.controllingPlayer.playerId) return;
    const oppTarget = findCreatureOrMagiById(ctx.state, oppTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow this (energy-discard) target to
    // be a Magi instead -- the OWN target above only feeds returnToHand, not discardEnergy, so
    // it's unaffected and stays Creature-only.
    if (!oppTarget || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, oppTarget, 'Creature')) return;
    if (oppTarget.controllerId === ctx.controllingPlayer.playerId) return;

    returnToHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ownTarget.instanceId);
    discardEnergy(ctx.state, ctx.cardDb, oppTarget, 4, undefined, undefined, ctx.rng);
  },
});
