// Brannix -- "Charge: Whenever Brannix attacks a non-Arderial Creature, add one energy to Brannix
// before energy is removed." / "Absorption: Whenever Brannix attacks an Arderial Creature, add
// three energy to Brannix before energy is removed." Direct self-energy gain (not a damage
// boost), added before lock-in so the extra energy is still on Brannix when it takes its own
// counter-damage this same attack.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { effectiveRegions } from '../targeting.js';

registerCardEffect('Brannix', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Charge (non-Arderial +1) and Absorption
  // (Arderial +3) are both fused into a single `onBeforeEnergyRemoved` body that branches on the
  // defender's region. Structurally inseparable, so a Taglat narrow-copy of either Effect surfaces
  // the same hook and behaviorally matches fallback (whole-card grant). Annotated anyway for
  // metadata explicitness.
  effectHooks: {
    Charge: ['onBeforeEnergyRemoved'],
    Absorption: ['onBeforeEnergyRemoved'],
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender === null) return;
    const isArderial = effectiveRegions(ctx.state, ctx.cardDb, ctx.defender).includes('Arderial');
    addEnergy(ctx.state, ctx.cardDb, self, isArderial ? 3 : 1, 'effect');
  },
});
