// Snag Arboll -- "Trip (2): Choose an opponent. Remove one energy from that opponent's Magi for
// each Creature he or she controls." The "choice" is a PLAYER, not a card -- in this 2-player
// engine there's only ever one legal opponent, so no target picker is needed at all; resolvePower
// just resolves against the (only) opponent directly.

import { registerCardEffect } from './registry.js';
import { getOpponents } from '../types/state.js';
import { discardEnergy } from '../effects.js';

registerCardEffect('Snag Arboll', {
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Trip') return;
    const opponent = getOpponents(ctx.state, ctx.controllingPlayer.playerId)[0];
    if (!opponent?.activeMagi) return;
    const creatureCount = opponent.inPlay.filter((c) => ctx.cardDb.get(c.definitionKey)?.card_type === 'Creature').length;
    discardEnergy(ctx.state, ctx.cardDb, opponent.activeMagi, creatureCount, undefined, undefined, ctx.rng);
  },
});
