// Eidon -- "Familiarity: Whenever Eidon plays a Creature, add two energy to Eidon if another
// Creature with the same name is already in play."

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';
import { allCreaturesInPlay } from '../targeting.js';

registerCardEffect('Eidon', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== 'Creature') return;

    const alreadyInPlay = allCreaturesInPlay(state, cardDb).some(
      (c) => c.instanceId !== played.instanceId && cardDb.get(c.definitionKey)?.name === playedDef.name
    );
    if (!alreadyInPlay) return;
    addEnergy(state, cardDb, self, 2, 'effect');
  },
});
