// Nashiq -- "Salvage: Choose a card in your discard pile. Shuffle the chosen card into your deck.
// Until the end of the turn, the cost to play cards of the same name is reduced by three, to a
// minimum of one." The retrieval half reuses discardPileSearch/retrieveFromDiscardPile (deckTop ->
// deckShuffled destination, unfiltered), already built.
//
// Cost-reduction half NOW BUILT (task #39-3d, 2026-07-17, d'Resh Category C) -- corrects the
// earlier deferral note above this comment's own history: no state-level "reduced this turn" table
// is actually needed. `CardInstance.costReductionGrant` (a new per-instance field, read by this
// same card's own `costModifier`, the same broadcast every other cost-reducing contributor already
// goes through) covers it -- Nashiq just remembers its own grant on itself. "Until the end of the
// turn" -- `expiresAfterTurnNumber: state.turnNumber` (the CURRENT turn), swept by
// `sweepExpiredCostReductionGrants` the moment `turn.ts#runStartOfTurnHooks` advances past it.

import { registerCardEffect } from './registry.js';
import { retrieveFromDiscardPile } from '../effects.js';

registerCardEffect('Nashiq', {
  discardPileSearch: { count: 1 },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Salvage') return;
    const ids = ctx.chosenDiscardPileIds ?? [];
    if (ids.length !== 1) return;
    const [id] = ids;
    const card = ctx.controllingPlayer.discardPile.find((c) => c.instanceId === id);
    if (!card) return;
    const def = ctx.cardDb.get(card.definitionKey);
    if (!def) return;

    retrieveFromDiscardPile(ctx.state, ctx.controllingPlayer, id!, 'deckShuffled', ctx.rng);
    ctx.source.costReductionGrant = { filter: { name: def.name }, amount: 3, expiresAfterTurnNumber: ctx.state.turnNumber };
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    const grant = self.costReductionGrant;
    if (!grant || !('name' in grant.filter)) return 0;
    if (state.turnNumber > grant.expiresAfterTurnNumber) return 0;
    return playedDef.name === grant.filter.name ? -grant.amount : 0;
  },
});
