// Balamant Pup -- "Support (2): Choose any one other Creature in play. Add two energy to the
// chosen Creature. Add one additional energy if the chosen Creature is a Balamant." Excludes
// itself at the POOL level (via sourceInstanceId, same fix as Flame Rudwot's Healing Flame -- see
// registry.ts's powerTargets doc comment), not just in resolvePower's post-hoc check -- otherwise
// the UI still OFFERS itself as a target, and picking it pays the Power's cost for zero effect
// with no clear feedback why. A real bug caught in playtesting (PROGRESS_LOG.md, 2026-07-09).
//
// Swirling Orshaa's Morph (Spell-pass audit follow-up, 2026-07-24) -- same bonus-condition
// treatment as Radget's Parmalag check, routed through matchesCreatureFamily().

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById, matchesCreatureFamily } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Balamant Pup', {
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) =>
    allCreaturesInPlay(state, cardDb).filter((c) => c.instanceId !== sourceInstanceId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Support') return;
    if (ctx.chosenTargetId === undefined || ctx.chosenTargetId === ctx.source.instanceId) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    const bonus = matchesCreatureFamily(ctx.cardDb, target, 'Balamant') ? 1 : 0;
    addEnergy(ctx.state, ctx.cardDb, target, 2 + bonus, 'power');
  },
  specifiedCreatureTypes: () => ['Balamant'],
});
