// K'teeb Thumper -- both printed clauses:
//   "Dreamthump: Choose any one Creature or Magi in play that used a Power on its player's last
//   turn. Discard three energy from the chosen Creature or Magi." Uses
//   CardInstance.usedPowerLastOwnTurn, the Power-use counterpart to Pody's attackedLastOwnTurn.
//   "Dreamwarp: As you play K'teeb Thumper, increase or decrease its starting energy by up to
//   one, until the end of the turn." (registry.ts's dreamwarpRange -- an unrelated NAME collision
//   with Dreamthump, not the same mechanic.)

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy } from '../effects.js';

registerCardEffect("K'teeb Thumper", {
  powerTargets: (state, cardDb) =>
    [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)].filter((c) => c.usedPowerLastOwnTurn),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Dreamthump') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !target.usedPowerLastOwnTurn) return;

    discardEnergy(ctx.state, ctx.cardDb, target, 3, undefined, undefined, ctx.rng);
  },
  dreamwarpRange: () => 1,
});
