// Coral Hyren -- "Spelltap: Whenever you play an Orothe Spell, add one energy to Coral Hyren."
// Broadcast onPlay reactor, self gains energy -- no Spell effect-execution needed, this only
// reacts to the ACT of playing an Orothe Spell.

import { registerCardEffect } from './registry.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Coral Hyren', {
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const def = cardDb.get(played.definitionKey);
    if (def?.card_type !== 'Spell') return;
    if (!def.regions.includes('Orothe')) return;
    addEnergy(state, cardDb, self, 1, 'effect');
  },
});
