// Toasted Yajo -- both printed effects:
//   "Brittle: As Toasted Yajo is attacked, you may shuffle it into its owner's deck and draw a
//   card." Removes itself from `inPlay` mid-onAttack, same established-safe "early self-removal
//   during onAttack" pattern Leaf Chogo/Wellisk Pup already use -- combat.ts's subsequent
//   damage-application step still runs against the now-orphaned `ctx.defender` object harmlessly
//   (it's just no longer in any zone).
//   "Weave: Whenever Toasted Yajo attacks or is attacked, before energy is removed, you may move
//   one energy between it and one of your other Weave Creatures in play." (see weave.ts -- mostly
//   moot while defending, since Brittle already removes it from play right after, but still
//   meaningful while it's the ATTACKER, which Brittle doesn't cover)
//
// Real choice (task #40-3, 2026-07-17, player-choice-default retrofit, Group 3): "may" is now a
// real yes/no via `pendingPreCombatTargetChoice`, single-candidate pool (self -- the only possible
// target, since this is "shuffle ITSELF into its owner's deck"). No resolution supplied falls back
// to the old always-take default, same escape-valve tradeoff as freep.ts's self-sacrifice/
// scoutBungaloo.ts's Flee.

import { registerCardEffect } from './registry.js';
import { drawCards } from '../effects.js';
import { addToZone, removeFromZone, shuffleDeck } from '../zones.js';
import { releaseAttachedOnLeavePlay } from '../attachedCards.js';
import { applyWeave } from './weave.js';
import type { PreCombatTargetResolution } from '../combat.js';

registerCardEffect('Toasted Yajo', {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Brittle owns the pre-combat yes/no plus
  // the shuffle-back branch of `onBeforeEnergyRemoved`; Weave owns the move branch of the same
  // fused hook plus `weaveConfig`. Field-level narrowing can't split the fused body, so listing
  // `onBeforeEnergyRemoved` under both is honest.
  effectHooks: {
    Brittle: ['pendingPreCombatTargetChoice', 'onBeforeEnergyRemoved'],
    Weave: ['weaveConfig', 'onBeforeEnergyRemoved'],
  },
  weaveConfig: { eligibleRegions: ['Weave'], mode: 'both' },
  pendingPreCombatTargetChoice: (state, cardDb, self, isAttacker, isDefender) => {
    if (!isDefender) return undefined;
    return { prompt: "Toasted Yajo's Brittle: shuffle itself into its owner's deck and draw a card?", pool: [self] };
  },
  onBeforeEnergyRemoved: (ctx, self) => {
    if (ctx.defender?.instanceId === self.instanceId) {
      const resolutions = ctx.scratch.preCombatTargetChoices as Record<string, PreCombatTargetResolution> | undefined;
      const resolution = resolutions?.[self.instanceId];
      const takeIt = resolution !== undefined ? !('skip' in resolution) : true; // unchanged auto-take default
      if (takeIt) {
        const owner = ctx.state.players.get(self.ownerId);
        // Fuzz finding (2026-08-01): same "verify presence, no-op if already gone" convention task
        // #600 bucket A established -- self can already be out of `inPlay` by the time this fires
        // (e.g. a co-defender/redirect chain that resolved the attack against a different card
        // first), and this file's own header comment already documents Brittle firing mid-onAttack
        // as an expected early-self-removal race; it just wasn't guarded at this specific call site.
        if (owner?.inPlay.some((c) => c.instanceId === self.instanceId)) {
          const card = removeFromZone(owner, 'inPlay', self.instanceId);
          releaseAttachedOnLeavePlay(ctx.state, ctx.cardDb, card); // task #329 -- before it enters the deck
          addToZone(owner, 'deck', card);
          shuffleDeck(owner, ctx.rng);
          drawCards(ctx.state, ctx.cardDb, owner, 1);
        }
      }
    }
    applyWeave(ctx, self, ['Weave']);
  },
});
