// Mobis, Avenger -- "Vengeance (4): Choose a Creature that attacked last turn. Discard that
// Creature." Target pool filtered by CardInstance.attackedLastOwnTurn, the same retroactive-
// tracking field Pody's target pool already relies on.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { discardFromPlay } from '../effects.js';

registerCardEffect('Mobis, Avenger', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter((c) => c.attackedLastOwnTurn),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Vengeance') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;
    if (!target.attackedLastOwnTurn) return;

    const owner = ctx.state.players.get(target.controllerId);
    if (owner) discardFromPlay(ctx.state, ctx.cardDb, owner, target.instanceId, undefined, undefined, ctx.rng);
  },
});
