// Kyg'n -- Effects:
//   True Gift: "Kyg'n is not defeated, even if he has no energy or Creatures in play, until he is
//   directly attacked." Built here -- suppresses the normal Magi-defeat check entirely until a
//   stored condition (durationTags.ts's EVER_ATTACKED_MAGI_DIRECTLY, set unconditionally by
//   combat.ts whenever ANY direct-Magi attack resolves) becomes true, then the normal condition
//   applies from then on. Same new `customDefeatCondition` hook as Korg/Erisa, a third distinct
//   shape (full immunity with a one-time unlock, rather than dropping/narrowing the check).
//   Unnamed: "Increase Kyg'n energize rate by the number of Creatures an opposing Magi of your
//   choice has in play." Built task #42, 2026-07-17, the Kybar's Teeth region pass -- a mandatory
//   ("of your choice", no "may") one-time pick at reveal, via `pendingTargetChoice`/
//   `resolveTargetChoice` (Venger/Oranragan's embedded-id-permanent-tag technique to remember the
//   chosen Magi's instance id persistently, since this isn't a per-use choice). `energizeRateModifier`
//   then reads the stored id via `findCreatureOrMagiById`, which only searches inPlay + activeMagi
//   -- if the chosen Magi is later defeated and succeeded, the lookup naturally fails and the bonus
//   silently drops to 0, which is the only sensible reading of a printed text that names a single
//   Magi with no fallback clause for what happens if that Magi later leaves play.

import { registerCardEffect } from './registry.js';
import { EVER_ATTACKED_MAGI_DIRECTLY, addPermanentTag, addPendingRevealChoiceTag, removePermanentTag } from '../durationTags.js';
import { getOpponents } from '../types/state.js';
import { findCreatureOrMagiById, creaturesControlledBy } from '../targeting.js';
import type { CardInstance } from '../types/instance.js';

const AWAITING_CHOICE = 'kygnEnergizeAwaitingChoice';
const TARGET_MAGI_PREFIX = 'kygnEnergizeTargetMagi:';

function storedTargetMagiId(self: { tags: ReadonlySet<string> }): string | undefined {
  for (const tag of self.tags) {
    if (tag.startsWith(TARGET_MAGI_PREFIX)) return tag.slice(TARGET_MAGI_PREFIX.length);
  }
  return undefined;
}

registerCardEffect("Kyg'n", {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Kyg'n's only NAMED Effect is
  // True Gift (the immunity-until-directly-attacked defeat gate on `customDefeatCondition`).
  // The second printed Effect has `name: null` in the DB (energize-rate boost by opposing
  // Magi's Creatures), so per the audit convention it isn't listed here -- a Taglat grant
  // can only target named Effects, and no map entry means the unnamed hooks stay dormant on
  // a narrowed grant (which is the correct printed-text reading).
  effectHooks: {
    'True Gift': ['customDefeatCondition'],
  },
  customDefeatCondition: (state, cardDb, magi, ownCreatures) => {
    if (!magi.tags.has(EVER_ATTACKED_MAGI_DIRECTLY)) return false; // immune until directly attacked
    return (magi.currentEnergy ?? 0) <= 0 && ownCreatures.length === 0;
  },
  onMagiRevealed: (state, cardDb, revealedMagi, self) => {
    if (revealedMagi.instanceId !== self.instanceId) return;
    if (storedTargetMagiId(self) !== undefined) return; // already chosen (e.g. a later re-reveal)
    addPendingRevealChoiceTag(self, AWAITING_CHOICE);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE)) return undefined;
    const pool = getOpponents(state, self.controllerId)
      .map((p) => p.activeMagi)
      .filter((m): m is CardInstance => m !== null);
    if (pool.length === 0) return undefined;
    return { prompt: "Kyg'n's energize rate: choose an opposing Magi", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, AWAITING_CHOICE);
    if (!chosenInstanceId) return;
    addPermanentTag(state, cardDb, self, `${TARGET_MAGI_PREFIX}${chosenInstanceId}`);
  },
  energizeRateModifier: (state, cardDb, energizing, self) => {
    const owner = state.players.get(self.controllerId);
    if (owner?.activeMagi?.instanceId !== energizing.instanceId) return 0;
    const targetId = storedTargetMagiId(self);
    if (targetId === undefined) return 0;
    const targetMagi = findCreatureOrMagiById(state, targetId);
    if (!targetMagi) return 0;
    return creaturesControlledBy(state, cardDb, targetMagi.controllerId).length;
  },
});
