// Rayje's Construct -- three Effects + four Powers.
// Effects (added 2026-07-19 after a playtest found "Invigorate" doing nothing -- the file had only
// ever implemented the Powers, a partial-file gap):
//   "Ancestral Favor: All your Spells cost one less Energy to play, to a minimum of one." ->
//     costModifier -1 on the controller's Spells; play.ts already floors a negative costModifier to
//     Math.max(1, ...), so "minimum of one" needs no per-card clamp.
//   "Invigorate: Increase your Magi's energize rate by one." -> energizeRateModifier +1 when the
//     energizing card is the controller's own active Magi (akkar.ts / aurorea.ts pattern).
//   "Tinker: Whenever you play a Relic, choose any one Creature in play. Add one energy to it. You
//     cannot choose a Creature more than once per turn with Tinker." -> the SHARED Tinker mechanism
//     in tinker.ts (Ring of Secrets prints the identical ability). onPlay arms a per-source pending
//     tag; the pending-choice + once-per-turn-per-Creature dedup are the shared helper's. The dedup
//     is shared across all Tinker sources (errata: "Each Creature can only be affected by Tinker once
//     a turn"), so a Creature Tinkered by Ring of Secrets this turn is also off-limits to this one.
// Four Powers:
// "Lore (2): Draw one card." A fixed-cost Power with no target.
// "Channeling: Discard two cards from your hand to add two energy to your Magi." No printed
// energy cost (free) -- the hand discard IS the cost, via handDiscardCost.
// "Pound Pound Pound (2): Discard any one Relic from play." Unrestricted -- "any one Relic," not
// "any one OF YOUR OPPONENT'S," so the pool spans both players' Relics.
// "Auraflection (2): Copy any one Power on your Magi, paying all costs." Built task #49 (Universal
// pass) via the shared invokeCopiedMagiPower helper (auraflection.ts): the (2) activation cost is
// the DB Power cost paid by usePower; "paying all costs" is the copied Power's own cost, paid out of
// the Magi, then the Magi's own resolvePower is re-executed. Distinct from copiedPowers.ts (a
// REUSABLE copy) -- this is a one-shot borrow. The player picks the Power via chosenPowerName; a
// copied Power needing a target relies on the UI collecting chosenTargetId alongside it. The other
// three Powers were found completely missing
// (silent fizzle, cost paid for nothing) auditing for the same bug class as Thunder Hyren's
// Replenish (PROGRESS_LOG.md, 2026-07-09) and are now implemented for real.

import { registerCardEffect } from './registry.js';
import { allRelicsInPlay, findInPlayById } from '../targeting.js';
import { addEnergy, discardFromHand, discardFromPlay, drawCards } from '../effects.js';
import { addPermanentTag, addPendingChoiceTag, removePermanentTag } from '../durationTags.js';
import { getPlayer } from '../types/state.js';
import { invokeCopiedMagiPower, magiPowerCopyPool } from './auraflection.js';
import { applyTinker, tinkerPool } from './tinker.js';

const TINKER_PENDING = 'rayjesConstructTinkerPending';

registerCardEffect("Rayje's Construct", {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Three named printed Effects, each with
  // disjoint hooks: Ancestral Favor (own-Spell cost -1), Invigorate (own-Magi energize +1),
  // Tinker (on-Relic-play pending Creature pick, shared with Ring of Secrets via tinker.ts). The
  // four Powers (Lore/Channeling/Pound Pound Pound/Auraflection) are NOT Effects -- they live on
  // `powerTargets`/`copyPowerChoice`/`handDiscardCost`/`resolvePower` and are Taglat-copied via
  // the Power branch, not the Effect branch. Any of the three Effects narrows cleanly.
  effectHooks: {
    'Ancestral Favor': ['costModifier'],
    Invigorate: ['energizeRateModifier'],
    Tinker: ['onPlay', 'pendingTargetChoice', 'resolveTargetChoice'],
  },
  // "Ancestral Favor" -- your Spells cost 1 less, minimum 1 (play.ts floors the negative sum).
  costModifier: (state, cardDb, playedDef, playerId, self) =>
    playerId === self.controllerId && playedDef.card_type === 'Spell' ? -1 : 0,
  // "Invigorate" -- +1 to your Magi's energize rate.
  energizeRateModifier: (state, cardDb, energizing, self) => {
    const owner = state.players.get(self.controllerId);
    return owner?.activeMagi?.instanceId === energizing.instanceId ? 1 : 0;
  },
  // "Tinker" -- on your Relic play, choose a Creature to add 1 energy (shared mechanism, tinker.ts).
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    if (cardDb.get(played.definitionKey)?.card_type !== 'Relic') return;
    if (tinkerPool(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, TINKER_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(TINKER_PENDING)) return undefined;
    const pool = tinkerPool(state, cardDb);
    if (pool.length === 0) return undefined;
    return { prompt: "Rayje's Construct's Tinker: choose a Creature to add 1 energy to", pool };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId) => {
    removePermanentTag(self, TINKER_PENDING);
    applyTinker(state, cardDb, chosenInstanceId);
  },
  powerTargets: (state, cardDb, playerId, powerName) =>
    powerName === 'Pound Pound Pound' ? allRelicsInPlay(state, cardDb) : undefined,
  copyPowerChoice: {
    // Only Auraflection copies a Power; the other 3 Powers return an empty pool (no picker).
    pool: (state, cardDb, playerId, _sourceId, powerName) => (powerName === 'Auraflection' ? magiPowerCopyPool(state, cardDb, playerId) : []),
  },
  handDiscardCost: (powerName) => (powerName === 'Channeling' ? { count: 2 } : undefined),
  resolvePower: (ctx) => {
    if (ctx.powerName === 'Lore') {
      drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
    } else if (ctx.powerName === 'Channeling') {
      const ids = ctx.chosenHandCardIds ?? [];
      if (ids.length !== 2) return;
      discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids, undefined, ctx.rng);
      const magi = ctx.controllingPlayer.activeMagi;
      if (magi) addEnergy(ctx.state, ctx.cardDb, magi, 2, 'power');
    } else if (ctx.powerName === 'Pound Pound Pound') {
      if (ctx.chosenTargetId === undefined) return;
      const target = findInPlayById(ctx.state, ctx.chosenTargetId);
      if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Relic') return;
      discardFromPlay(ctx.state, ctx.cardDb, getPlayer(ctx.state, target.controllerId), target.instanceId, undefined, undefined, ctx.rng);
    } else if (ctx.powerName === 'Auraflection') {
      // "Copy any one Power on your Magi, paying all costs." The (2) activation cost is the DB Power
      // cost paid by usePower; "paying all costs" is the copied Power's own cost (no extra surcharge).
      invokeCopiedMagiPower(ctx, 0);
    }
  },
});
