// Rask -- two printed clauses:
//   "Chill: When Rask attacks, it removes two additional energy." Region-audit follow-up,
//   2026-07-24 -- unconditional +2 to the locked attacker energy, identical shape to Hunter
//   Furok/Gransaber's own "Chill" text.
//   "Satiate: Discard Rask from play. If your Magi is Nar, Creature with more than their starting
//   energy cannot attack until the beginning of your next turn." No "opposing" qualifier in the
//   source text -- read literally as a sweep across every Creature in play matching the filter,
//   either side. Mass application of the existing CANNOT_ATTACK tag, same helper
//   (beginningOfNextOwnTurnNumber) Lurking Minani/Jungle Jile/Snag Hyren already use for this exact
//   duration wording.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, effectiveStartingEnergy } from '../targeting.js';
import { discardFromPlay } from '../effects.js';
import { addDurationTag, beginningOfNextOwnTurnNumber, CANNOT_ATTACK } from '../durationTags.js';
import { addRestrictionTag } from '../restrictions.js';

registerCardEffect('Rask', {
  onAttack: (ctx, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    ctx.locked.attackerEnergy += 2;
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Satiate') return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, undefined, undefined, ctx.rng);

    const magi = ctx.controllingPlayer.activeMagi;
    const magiDef = magi ? ctx.cardDb.get(magi.definitionKey) : undefined;
    if (!magiDef?.regions.includes('Nar')) return;

    const expiry = beginningOfNextOwnTurnNumber(ctx.state);
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if ((creature.currentEnergy ?? 0) > effectiveStartingEnergy(ctx.state, ctx.cardDb, creature)) {
        addRestrictionTag(ctx.state, creature, CANNOT_ATTACK, expiry);
      }
    }
  },
});
