// Cave Hyren -- "Energy Transfer (X): Choose any one Creature in play. Add X energy to the chosen
// Creature." Same shape as Snow Hyren/Leaf Hyren/Wyle.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, findInPlayById } from '../targeting.js';
import { addEnergy } from '../effects.js';

registerCardEffect('Cave Hyren', {
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Energy Transfer') return;
    if (ctx.chosenTargetId === undefined || ctx.chosenXValue === undefined) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== 'Creature') return;

    addEnergy(ctx.state, ctx.cardDb, target, ctx.chosenXValue, 'power');
  },
});
