// Giant Vulbor -- "Mind Shock (2): Remove four energy from any one Creature. That Creature's
// Magi may discard up to two cards. For each card discarded, remove two less energy." First card
// using registry.ts's opponentHandDiscardChoice -- the mitigation choice is the TARGET's
// controller's, discarding from THEIR hand, not Giant Vulbor's controller's.

import { registerCardEffect } from './registry.js';
import { allCreaturesInPlay, allMagiInPlay, findInPlayById, isValidTargetGivenFlexibility, flexibleTargetPool, findCreatureOrMagiById } from '../targeting.js';
import { discardEnergy, discardFromHand } from '../effects.js';

registerCardEffect('Giant Vulbor', {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  opponentHandDiscardChoice: { maxCount: 2 },
  causesOpponentHandDiscard: true, // task #718 (Riptide clause 2, 2026-08-11)

  resolvePower: (ctx) => {
    if (ctx.powerName !== 'Mind Shock') return;
    if (ctx.chosenTargetId === undefined) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    // task #34, 2026-07-16: Abraxin's Crown's Dreamburn may allow a Magi target here instead.
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, 'Creature')) return;
    const targetOwner = ctx.state.players.get(target.controllerId);
    if (!targetOwner) return;

    const offered = ctx.chosenOpponentHandCardIds ?? [];
    const validIds = offered.filter((id) => targetOwner.hand.some((c) => c.instanceId === id));
    const count = Math.min(2, validIds.length);
    if (count > 0) discardFromHand(ctx.state, ctx.cardDb, targetOwner, validIds.slice(0, count), undefined, ctx.rng);

    discardEnergy(ctx.state, ctx.cardDb, target, Math.max(0, 4 - 2 * count), undefined, undefined, ctx.rng);
  },
});
